        }
        static string[,] BuildPalette(){
            int[,] anchors={{28,19,13},{65,37,23},{110,60,32},{145,81,38},{161,124,65},{179,164,138}};
            // One immutable row/shade table shared by every effect. Row indices
            // are viewport-relative. Both drawable edges fade toward black; UI is masked.
            string[,] p=new string[TopFadeRows+1,48];
            for(int row=0;row<=TopFadeRows;row++){
                double t=row/(double)TopFadeRows,fade=t*t*(3-2*t);
                for(int i=0;i<48;i++){double q=i*5.0/47;int a=Math.Min(4,(int)q);double f=q-a;
                    int r=(int)(anchors[a,0]*(1-f)+anchors[a+1,0]*f),g=(int)(anchors[a,1]*(1-f)+anchors[a+1,1]*f),b=(int)(anchors[a,2]*(1-f)+anchors[a+1,2]*f);
