        }
        static string[,] BuildFlamePalette(){
            int[,] colors={{36,0,0},{92,6,0},{130,13,0},{191,43,0},{222,69,0},{248,124,0},{255,157,23},{255,206,82},{255,224,131},{255,247,209}};string[,] p=new string[TopFadeRows+1,48];
            for(int row=0;row<=TopFadeRows;row++){
