                for(int shade=0;shade<48;shade++){int i=Math.Min(colors.GetLength(0)-1,shade);
                    p[row,shade]="\x1b[38;2;"+(int)(colors[i,0]*fade)+";"+(int)(colors[i,1]*fade)+";"+(int)(colors[i,2]*fade)+"m";
