        }
        static int W(Info i){return i.Window.Right-i.Window.Left+1;}
        static int H(Info i){return i.Window.Bottom-i.Window.Top+1;}
        void Capture(Info info){
            geometry=info;width=W(info);height=H(info);
            originX=info.Cursor.X-info.Window.Left;originY=info.Cursor.Y-info.Window.Top;
            if(width<40||height<10||(long)width*height>2000000||info.Window.Left!=0){animation=false;return;}
            snapshot=new Cell[width*height];Rect rect=info.Window;
            if(!ReadConsoleOutputW(output,snapshot,new Coord(width,height),new Coord(0,0),ref rect))throw new InvalidOperationException("Could not capture console UI.");
            if(originY<0||originY>=height){animation=false;return;}
