            if(Effects.IsLocalized(effect))generator.ConfigurePlacement(protectedCells,effect);
        }
        void BuildMask(){
            protectedCells=new bool[width*height];
            for(int y=0;y<height;y++){
                int x=0;
                while(x<width){
                    while(x<width&&Blank(snapshot[y*width+x].Character))x++;
                    if(x==width)break;
                    int start=x,last=x;x++;
                    while(x<width){if(!Blank(snapshot[y*width+x].Character)){last=x;}else if(x-last>2)break;x++;}
                    // Enclosed UI boxes protect their interior, including empty rows.
                    char first=snapshot[y*width+start].Character;
                    if(first=='│'||first=='║'){
                        for(int end=width-1;end>last;end--)if(snapshot[y*width+end].Character==first){last=end;x=end+1;break;}
                    }
                    Protect(y,start-1,last+1);
                }
                protectedCells[y*width+width-1]=true;
            }
