        }
        static bool Blank(char c){return c=='\0'||char.IsWhiteSpace(c);}
        void Protect(int y,int start,int end){for(int x=Math.Max(0,start);x<=Math.Min(width-1,end);x++)protectedCells[y*width+x]=true;}
        void NativeWrite(string value){
            int size=Encoding.UTF8.GetMaxByteCount(value.Length);if(encoded.Length<size)encoded=new byte[size];
            int length=Encoding.UTF8.GetBytes(value,0,value.Length,encoded,0),written;
            if(!WriteFile(output,encoded,length,out written,IntPtr.Zero)||written!=length)throw new InvalidOperationException("Console presentation write failed.");
        }
        public void RenderFrame(double seconds){
            if(!Animating||snapshot==null)return;
            generator.Generate(effect,seconds);frame.Length=0;frame.Append("\x1b"+"7");
            for(int y=0;y<height-1;y++){
                int x=0;while(x<width-1){while(x<width-1&&protectedCells[y*width+x])x++;if(x>=width-1)break;
                    frame.Append("\x1b[").Append(y+1).Append(';').Append(x+1).Append('H');int last=-1;
                    while(x<width-1&&!protectedCells[y*width+x]){
                        int i=y*width+x;char c=generator.Glyph[i];int shade=generator.Shade[i];
                        if(c!=' '&&shade!=last){frame.Append((effect=="Flame Fire"?FlamePalette:Palette)[Math.Min(TopFadeRows,Math.Min(y,height-2-y)),shade]);last=shade;}frame.Append(c);x++;
                    }
                }
            }
