        }
        void RestoreDecoration(){
            if(!painted||snapshot==null)return;
            Info current;if(!GetConsoleScreenBufferInfo(output,out current))return;
            if(W(current)!=width||H(current)!=height||current.Window.Top!=geometry.Window.Top){painted=false;return;}
            for(int y=0;y<height-1;y++){
                int x=0;while(x<width-1){while(x<width-1&&protectedCells[y*width+x])x++;int start=x;
                    while(x<width-1&&!protectedCells[y*width+x])x++;
                    if(x>start){Rect r=new Rect{Left=(short)start,Right=(short)(x-1),Top=(short)(geometry.Window.Top+y),Bottom=(short)(geometry.Window.Top+y)};
                        WriteConsoleOutputW(output,snapshot,new Coord(width,height),new Coord(start,y),ref r);}
                }
            }
