        }
        void DrawInput(StringBuilder text,int caret){
            Info info;if(!GetConsoleScreenBufferInfo(output,out info))return;
            int available=Math.Max(1,W(info)-originX-1),start=Math.Max(0,caret-available+1);
            string all=text.ToString();int count=Math.Min(available,all.Length-start);
            NativeWrite("\x1b["+(originY+1)+";"+(originX+1)+"H"+all.Substring(start,Math.Max(0,count))+new string(' ',available-Math.Max(0,count)));
