                    // ConPTY/Windows Terminal history is owned by the frontend and is
                    // deliberately NOT inferred from its compatibility srWindow.
                    scrollFrozen=classicScroll&&((W(current)==width&&H(current)==height&&(current.Window.Top!=geometry.Window.Top||current.Window.Left!=geometry.Window.Left))||current.Cursor.Y<current.Window.Top||current.Cursor.Y>current.Window.Bottom);
                    try{if(!scrollFrozen&&LastError==null&&Resize(current)){
