                        if(key.Key==ConsoleKey.LeftArrow){caret=Math.Max(0,caret-1);}
                        else if(key.Key==ConsoleKey.RightArrow){caret=Math.Min(text.Length,caret+1);}
                        else if(key.Key==ConsoleKey.Home){caret=0;}
                        else if(key.Key==ConsoleKey.End){caret=text.Length;}
                        else if(key.Key==ConsoleKey.Backspace&&caret>0){text.Remove(--caret,1);}
                        else if(key.Key==ConsoleKey.Delete&&caret<text.Length){text.Remove(caret,1);}
                        else if(key.Key==ConsoleKey.U&&(key.Modifiers&ConsoleModifiers.Control)!=0){text.Length=0;caret=0;}
                        else if(!char.IsControl(key.KeyChar)){text.Insert(caret++,key.KeyChar);}
                        if(!scrollFrozen)DrawInput(text,caret);
                    }
                    double now=clock.Elapsed.TotalSeconds;
                    if(Animating&&now>=next){
                        double before=now;
                        try{RenderFrame(now);}catch(Exception ex){LastError=ex.Message;RestoreDecoration();animation=false;}
                        double cost=clock.Elapsed.TotalSeconds-before;next=before+Math.Max(.033,cost*6);
                    }
                    Thread.Sleep(5);
                }
            }finally{Console.TreatControlCAsInput=originalCtrl;RestoreDecoration();SetConsoleTextAttribute(output,originalAttributes);}
        }
        public void Dispose(){
            if(disposed)return;
            try{RestoreDecoration();}finally{if(valid){SetConsoleTextAttribute(output,originalAttributes);SetConsoleMode(output,originalMode);}disposed=true;valid=false;}
        }
    }
}
'@
    Add-Type -TypeDefinition $source -Language CSharp -ErrorAction Stop|Out-Null
}

function Read-VSO7AnimatedMenuInputVSO {
    param([AllowNull()][string]$Prompt,[switch]$AnimatedMenu)
    Complete-VSO7ConsoleSceneVSO
    # Explicit audited selectors opt in independently of translated prompt text.
    # Other readers keep the original classifier and blocking fallback.
    $isChoice=[bool]$AnimatedMenu
    if(-not$AnimatedMenu){
        $isChoice=([string]$Prompt-match'(?i)^(elige una opcion|choose an option|choose|choice|action|accion|opcion|option|selection|seleccion|objective|objetivo|menu|menú)(\b|\s|/)')
        if([string]$Prompt-match'(?i)(search|buscar|find|nombre|name|ruta|path|exact|password|contraseña|FeatureIds|AppIds|PID|\.exe|command|comando)'){$isChoice=$false}
    }
    if(-not$isChoice-or-not(Test-VSO7ConsolePresentationAvailableVSO)-or$null-eq$script:ConsoleDrawRecords){return [pscustomobject]@{Used=$false;Text=$null}}
    $session=$null;$answer=$null;$used=$false;$failureMessage=$null
    try{
        Update-VSO7ConsoleResponsiveSceneVSO
        Initialize-VSO7ConsoleAnimationTypeVSO
        $repaint=[Action]{Invoke-VSO7ConsolePresentationReplayVSO}
        $session=New-Object VSO.ConsoleAnimation.TerminalSession -ArgumentList @([string]$script:ConsoleAnimationCurrentEffect,[int]$script:ConsoleAnimationSeed,$repaint)
        if($session.Animating){
            $answer=$session.ReadMenuLine();$used=$true
        }else{$script:ConsoleAnimationRuntimeDisabled=$true}
        if($session.LastError){
            $script:ConsoleAnimationRuntimeDisabled=$true
            if(-not$script:ConsoleAnimationFailureShown){
                $script:ConsoleAnimationFailureShown=$true
                $safeError=([string]$session.LastError)-replace'[\x00-\x1f]',' '
                $failureMessage='Console background disabled for this session: '+$safeError
            }
        }
    }catch{
        if($_.Exception.GetBaseException()-is[OperationCanceledException]){throw (New-Object System.Management.Automation.PipelineStoppedException)}
        $script:ConsoleAnimationRuntimeDisabled=$true
        if(-not$script:ConsoleAnimationFailureShown){
            $script:ConsoleAnimationFailureShown=$true
            $failureMessage='Console background unavailable for this session; using the normal console.'
        }
    }finally{if($null-ne$session){$session.Dispose()}}
    if($used){
        # Re-emit plain input at its original cursor position through PSHost.
        # This preserves the visible newline and captures input in the transcript,
        # while native animation bytes never pass through the host/logging streams.
        Write-VSOHost $answer
    }
    if($failureMessage){try{Write-VSO7Log $failureMessage 'WARN'}catch{}}
    return [pscustomobject]@{Used=$used;Text=$answer}
}


function Show-VSO7ConsoleBackgroundSettingsVSO {
    while($true){
        Write-Title
        Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'FONDO ANIMADO' 'ANIMATED BACKGROUND') -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text ((Get-VSO7ConsoleTextVSO 'Actual: ' 'Current: ')+(Get-VSO7ConsoleBackgroundLabelVSO $script:ConsoleBackgroundEffect)) -Color $script:ThemeText
        $names=@(Get-VSO7ConsoleBackgroundNamesVSO);$rows=@()
        for($i=0;$i-lt$names.Count;$i++){
            $name=$names[$i];$description=Get-VSO7ConsoleTextVSO 'Fondo decorativo propio de VSO. No modifica Windows.' 'VSO decorative background. Does not modify Windows.'
            if($name-eq'Disabled'){$description=Get-VSO7ConsoleTextVSO 'Consola normal con fondo negro, sin renderer.' 'Normal black console with no renderer.'}
            if($name-eq'Random'){$description=Get-VSO7ConsoleTextVSO 'Elige un efecto al azar al iniciar y al cambiar de pantalla.' 'Chooses a random effect at startup and on screen changes.'}
            $rows+=[pscustomobject]@{Text=('[{0}] {1}{2}'-f($i+1),(Get-VSO7ConsoleBackgroundLabelVSO $name),$(if($script:ConsoleBackgroundEffect-eq$name){' *'}else{''}));Color=$(if($script:ConsoleBackgroundEffect-eq$name){'Green'}else{'Gray'});Description=$description}
        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        Write-CenteredMenuVSO -Items @([pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[0] Volver' '[0] Back');Color='Gray'})
        $choice=Read-CenteredPromptVSO -Text (Get-VSO7ConsoleTextVSO 'Seleccion' 'Selection')
        if($choice-eq'0'){return}
        $number=0
        if([int]::TryParse($choice,[ref]$number)-and$number-ge1-and$number-le$names.Count){
            $previous=$script:ConsoleBackgroundEffect;$script:ConsoleBackgroundEffect=$names[$number-1]
            Save-VSOLanguagePreference
            try{
                $saved=Get-Content -LiteralPath $script:LanguageFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
                if([string]$saved.AnimatedBackground-cne$script:ConsoleBackgroundEffect){throw 'Appearance preference was not saved.'}
            }catch{
                $script:ConsoleBackgroundEffect=$previous
                Write-VSOHost (Get-VSO7ConsoleTextVSO 'No se pudo guardar la preferencia de fondo. Se conserva la anterior.' 'Could not save the background preference. The previous selection is retained.') -ForegroundColor Yellow
                Pause-Vico
            }
        }
    }
}


function Get-VSO7ConsoleGridPlanVSO {
    param([array]$Items)
    $width=Get-VSOConsoleWidth;$gap=4;$columns=1
    $body=@($Items|Where-Object{$null-ne$_-and-not($_.PSObject.Properties.Name-contains'SeparatorBefore'-and[bool]$_.SeparatorBefore)})
    if($width-ge112-and$body.Count-ge6){$columns=2}
    if($width-ge196-and$body.Count-ge15){$columns=3}
    $cell=[int][Math]::Min(76,[Math]::Floor(($width-4-$gap*($columns-1))/$columns))
    $cell=[Math]::Max(12,$cell)
    $gridWidth=$cell*$columns+$gap*($columns-1)
    $gridX=[int][Math]::Max(0,[Math]::Floor(($width-$gridWidth)/2))
    $rows=New-Object 'Collections.Generic.List[object]'
    foreach($item in $body){
        $title=[string](Convert-VSOText -Value ([string]$item.Text));$description='';$color=$script:ThemeText
        if($item.PSObject.Properties.Name-contains'Description'){$description=[string](Convert-VSOText -Value ([string]$item.Description))}
        if($item.PSObject.Properties.Name-contains'Color'-and$item.Color){$color=[string]$item.Color}
        $lines=New-Object 'Collections.Generic.List[string]'
        foreach($line in @(Split-VSO7TextLinesVSO -Text $title -Width ($cell-2))){[void]$lines.Add([string]$line)}
        $titleCount=$lines.Count
        if($description){foreach($line in @(Split-VSO7TextLinesVSO -Text $description -Width ($cell-4))){[void]$lines.Add('  '+$line)}}
        [void]$lines.Add('')
        [void]$rows.Add([pscustomobject]@{Lines=$lines.ToArray();TitleCount=$titleCount;Color=$color})
    }
    $height=0
    for($i=0;$i-lt$rows.Count;$i+=$columns){$h=0;for($c=0;$c-lt$columns-and($i+$c)-lt$rows.Count;$c++){$h=[Math]::Max($h,$rows[$i+$c].Lines.Count)};$height+=$h}
    return [pscustomobject]@{Columns=$columns;Cell=$cell;Gap=$gap;Width=$gridWidth;X=$gridX;Rows=$rows.ToArray();Height=$height}
}

function Get-VSO7ConsoleSceneHeightVSO {
    $height=0
    foreach($record in $script:ConsoleDrawRecords){
        switch($record.Name){
            'Write-Title'{if($script:ConsoleCompactHeader){$height+=4}else{$height+=10}}
            'Write-CenteredLineVSO'{$height++}
            'Write-VSO7ConsolePromptVSO'{$height++}
            'Write-VSOHost'{if(-not$record.Parameters.NoNewline){$height+=1+([regex]::Matches([string]$record.Parameters.Object,"`n")).Count}}
            {$_-in@('Write-CenteredMenuVSO','Write-VSO7TwoColumnOptionsVSO')}{
                $items=@($record.Parameters.Items);$plan=Get-VSO7ConsoleGridPlanVSO -Items $items
                if($plan.Columns-gt1){$height+=$plan.Height;if($record.Name-eq'Write-CenteredMenuVSO'-or$record.Parameters.Boxed){$height+=2}}else{
                    $height+=2
                    foreach($item in $items){$height++;if($item.Description){$height+=2}elseif($item.SeparatorBefore){$height++}}
                }
                $back=@($items|Where-Object{$_.SeparatorBefore})
                if($plan.Columns-gt1-and$back.Count){
                    $height+=2
                    foreach($item in $back){$height++;if($item.Description){$height+=2}else{$height++}}
                }
            }
        }
    }
    return $height
}

function Update-VSO7ConsoleResponsiveSceneVSO {
    param([switch]$PlanOnly)
    if($null-eq$script:ConsoleDrawRecords-or$script:ConsoleDrawReplaying){return}
    $height=Get-VSO7ConsoleSceneHeightVSO
    $viewportHeight=0;try{$viewportHeight=[int]$Host.UI.RawUI.WindowSize.Height}catch{return}
    $isMain=@($script:ConsoleDrawRecords|Where-Object{$_.Name-eq'Write-CenteredLineVSO'-and[string]$_.Parameters.Text-match'^(MENU PRINCIPAL|MAIN MENU)$'}).Count-gt0
    $previous=[bool]$script:ConsoleCompactHeader
    $fullHeight=$height;if($previous){$fullHeight+=6}
    $compactForWidth=((Get-VSOConsoleWidth)-lt60)
    $script:ConsoleCompactHeader=($compactForWidth-or(-not$isMain-and$fullHeight-gt$viewportHeight-and($fullHeight-6)-le$viewportHeight))
    $script:ConsoleSceneIsLong=($fullHeight-$(if($script:ConsoleCompactHeader){6}else{0}))-gt$viewportHeight
    if(-not$PlanOnly-and$previous-ne[bool]$script:ConsoleCompactHeader){Invoke-VSO7ConsolePresentationReplayVSO}
}

function Initialize-VSOConsoleTheme {

    try {

        Set-VSO7TerminalDefaultBlackVSO
        $raw = $Host.UI.RawUI
        $script:OriginalConsoleBackground = $raw.BackgroundColor
        $script:OriginalConsoleForeground = $raw.ForegroundColor
        $raw.BackgroundColor = [System.ConsoleColor]::Black
        if ($raw.ForegroundColor -eq [System.ConsoleColor]::Black) {

            $raw.ForegroundColor = [System.ConsoleColor]::Gray

        }
        $script:ConsoleThemeInitialized = $true
        try{
            [Console]::Clear()
        }catch{}
        return

    } catch {}

    try {

        $script:OriginalConsoleBackground = [Console]::BackgroundColor
        $script:OriginalConsoleForeground = [Console]::ForegroundColor
        [Console]::BackgroundColor = [ConsoleColor]::Black
        if ([Console]::ForegroundColor -eq [ConsoleColor]::Black) {

            [Console]::ForegroundColor = [ConsoleColor]::Gray

        }
        [Console]::Clear()
        $script:ConsoleThemeInitialized = $true

    } catch {}

}

function Restore-VSOConsoleTheme {
    Restore-VSO7TerminalDefaultVSO

    if (-not $script:ConsoleThemeInitialized) {
        return
    }
    try {

        if ($null -ne $script:OriginalConsoleBackground) {
            $Host.UI.RawUI.BackgroundColor = $script:OriginalConsoleBackground
        }
        if ($null -ne $script:OriginalConsoleForeground) {
            $Host.UI.RawUI.ForegroundColor = $script:OriginalConsoleForeground
        }

    } catch {
        try{
            if($null-ne$script:OriginalConsoleBackground){[Console]::BackgroundColor=$script:OriginalConsoleBackground}
            if($null-ne$script:OriginalConsoleForeground){[Console]::ForegroundColor=$script:OriginalConsoleForeground}
        }catch{}
    }

}

function Get-VSOConsoleWidth {
    # Layout always uses the visible viewport, never the buffer or renderer size.
    try{
        $width=[int]$Host.UI.RawUI.WindowSize.Width
        if($script:GuiMode-or$script:GuiRequested){return [Math]::Max(72,[Math]::Min(180,$width))}
        return [Math]::Max(1,$width)
    }catch{}
    try{return [Math]::Max(1,[int][Console]::WindowWidth)}catch{return 100}
}


function Write-CenteredLineVSO {

    param(
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Text,
        [string]$Color = 'Gray'
    )
    $vsoDrawEntered=Start-VSO7ConsoleDrawRecordVSO -Name 'Write-CenteredLineVSO' -Parameters $PSBoundParameters
    try {
        if($script:ConsoleDrawPending-and-not$script:ConsoleDrawReplaying){return}
    $shown = [string](Convert-VSOText -Value $Text)
    $width = Get-VSOConsoleWidth
    $padding = [math]::Max(0,[math]::Floor(($width - $shown.Length) / 2))
    Write-VSOHost (((' ' * $padding) + $shown)) -ForegroundColor $Color


    }finally{Stop-VSO7ConsoleDrawRecordVSO -Entered $vsoDrawEntered}
}

function Write-CenteredMenuVSO {

    param([Parameter(Mandatory=$true)][AllowNull()][AllowEmptyCollection()][array]$Items)
    $vsoDrawEntered=Start-VSO7ConsoleDrawRecordVSO -Name 'Write-CenteredMenuVSO' -Parameters $PSBoundParameters
    try {
        if($script:ConsoleDrawPending-and-not$script:ConsoleDrawReplaying){return}

    $Items=@($Items|Where-Object{
        $null-ne$_
    })
    if ($Items.Count -eq 0) {
        return
    }
    $display = @()
    $maxLength = 0
    foreach ($item in $Items) {

        $line = [string](Convert-VSOText -Value ([string]$item.Text))
        $description = ''
        if ($item.PSObject.Properties.Name -contains 'Description' -and -not [string]::IsNullOrWhiteSpace([string]$item.Description)) {

            $description = [string](Convert-VSOText -Value ([string]$item.Description))

        }
        if ($line.Length -gt $maxLength) {
            $maxLength = $line.Length
        }
        if (-not [string]::IsNullOrWhiteSpace($description) -and ($description.Length + 4) -gt $maxLength) {
            $maxLength = $description.Length + 4
        }
        $color = if ($item.PSObject.Properties.Name -contains 'Color' -and -not [string]::IsNullOrWhiteSpace([string]$item.Color)) {
            [string]$item.Color
        } else {
            $script:ThemeText
        }
        $separatorBefore = ($item.PSObject.Properties.Name -contains 'SeparatorBefore' -and [bool]$item.SeparatorBefore)
        $display += [pscustomobject]@{
            Text=$line;
            Description=$description;
            Color=$color;
            SeparatorBefore=$separatorBefore
        }

    }

    $consoleWidth = Get-VSOConsoleWidth
    if(-not$script:GuiMode-and-not$script:GuiRequested-and( Get-VSO7ConsoleGridPlanVSO -Items $Items ).Columns-gt1){
        Write-VSO7TwoColumnOptionsVSO -Items $Items -Boxed
        return
    }

    # Long diagnostic rows (paths, commands, startup locations) stay unboxed so
    # VSO7 never truncates useful information just to make the UI prettier.
    if (($maxLength + 6) -gt $consoleWidth) {

        $padding = [math]::Max(0,[math]::Floor(($consoleWidth - $maxLength) / 2))
        $prefix = ' ' * $padding
        foreach ($row in $display) {

            if ($row.SeparatorBefore) {
                Write-VSOHost ''
            }
            Write-VSOHost ($prefix + [string]$row.Text) -ForegroundColor $row.Color
            if (-not [string]::IsNullOrWhiteSpace([string]$row.Description)) {

                Write-VSOHost ($prefix + '    ' + [string]$row.Description) -ForegroundColor $script:ThemeMuted

            }

        }
        return

    }

    $inner = [math]::Max($maxLength + 4,34)
    $outer = $inner + 2
    $leftPad = [math]::Max(0,[math]::Floor(($consoleWidth - $outer) / 2))
    $prefix = ' ' * $leftPad

    function Write-VSO7MenuBoxRow {

        param([string]$Value,[string]$Color)
        $text = [string]$Value
        $right = [math]::Max(0,$inner - 2 - $text.Length)
        Write-VSOHost ($prefix + '│ ') -NoNewline -ForegroundColor $script:ThemeBorder
        Write-VSOHost ($text + (' ' * $right)) -NoNewline -ForegroundColor $Color
        Write-VSOHost ' │' -ForegroundColor $script:ThemeBorder

    }

    Write-VSOHost ($prefix + '┌' + ('─' * $inner) + '┐') -ForegroundColor $script:ThemeBorder
    foreach ($row in $display) {

        if ($row.SeparatorBefore) {
            Write-VSO7MenuBoxRow -Value '' -Color $script:ThemeMuted
        }
        Write-VSO7MenuBoxRow -Value ([string]$row.Text) -Color ([string]$row.Color)
        if (-not [string]::IsNullOrWhiteSpace([string]$row.Description)) {

            Write-VSO7MenuBoxRow -Value ('    ' + [string]$row.Description) -Color $script:ThemeMuted
            if(-not$row.SeparatorBefore){
                Write-VSO7MenuBoxRow -Value '' -Color $script:ThemeMuted
            }

        }

    }
    Write-VSOHost ($prefix + '└' + ('─' * $inner) + '┘') -ForegroundColor $script:ThemeBorder


    }finally{Stop-VSO7ConsoleDrawRecordVSO -Entered $vsoDrawEntered}
}

function Read-CenteredPromptVSO {

    param([Parameter(Mandatory=$true)][string]$Text,[switch]$AnimatedMenu)
    $prompt = [string](Convert-VSOText -Value $Text)
    if($script:GuiMode -or $script:GuiRequested){
        return (Read-VSOHost $prompt)
    }
    Write-VSO7ConsolePromptVSO -Text $Text
    Complete-VSO7ConsoleSceneVSO
    $read=Read-VSO7AnimatedMenuInputVSO -Prompt $prompt -AnimatedMenu:$AnimatedMenu
    if($read.Used){return [string]$read.Text}
    return (Microsoft.PowerShell.Utility\Read-Host)

}

function Split-VSO7TextLinesVSO {

    param([Parameter(Mandatory=$true)][string]$Text,[int]$Width=46)
    if($Width-lt12){
        $Width=12
    }
    $words=@([regex]::Split(([string]$Text).Trim(),'\s+')|Where-Object{
        $_ -ne ''
    })
    $lines=New-Object Collections.Generic.List[string];
    $current=''
    foreach($word in $words){

        # Preserve every character of long app IDs/paths while keeping boxed
        # columns inside the viewport. This changes display wrapping only.
        if($word.Length-gt$Width){
            if(-not[string]::IsNullOrWhiteSpace($current)){[void]$lines.Add($current);$current=''}
            while($word.Length-gt$Width){[void]$lines.Add($word.Substring(0,$Width));$word=$word.Substring($Width)}
        }
        if([string]::IsNullOrWhiteSpace($current)){
            $current=$word;
            continue
        }
        if(($current.Length+1+$word.Length)-le$Width){
            $current+=' '+$word
        }else{
            [void]$lines.Add($current);
            $current=$word
        }

    }
    if(-not[string]::IsNullOrWhiteSpace($current)){
        [void]$lines.Add($current)
    }
    if($lines.Count-eq0){
        [void]$lines.Add('')
    }
    return $lines.ToArray()

}

function Write-VSO7TwoColumnOptionsVSO {
    param([Parameter(Mandatory=$true)][AllowNull()][AllowEmptyCollection()][array]$Items,[switch]$Boxed)
    $entered=Start-VSO7ConsoleDrawRecordVSO -Name 'Write-VSO7TwoColumnOptionsVSO' -Parameters $PSBoundParameters
    try{
        if($script:ConsoleDrawPending-and-not$script:ConsoleDrawReplaying){return}
        $Items=@($Items|Where-Object{$null-ne$_});$plan=Get-VSO7ConsoleGridPlanVSO -Items $Items
        if($plan.Columns-eq1){Write-CenteredMenuVSO -Items $Items;return}
        $prefix=' '*[Math]::Max(0,($plan.X-2))
        if($Boxed){Write-VSOHost ($prefix+'┌'+('─'*($plan.Width+2))+'┐') -ForegroundColor $script:ThemeBorder}
        for($i=0;$i-lt$plan.Rows.Count;$i+=$plan.Columns){
            $height=0;for($c=0;$c-lt$plan.Columns-and($i+$c)-lt$plan.Rows.Count;$c++){$height=[Math]::Max($height,$plan.Rows[$i+$c].Lines.Count)}
            for($y=0;$y-lt$height;$y++){
                if($Boxed){Write-VSOHost ($prefix+'│ ') -NoNewline -ForegroundColor $script:ThemeBorder}else{Write-VSOHost (' '*$plan.X) -NoNewline}
                for($c=0;$c-lt$plan.Columns;$c++){
                    $text='';$color=$script:ThemeMuted
                    if(($i+$c)-lt$plan.Rows.Count){$row=$plan.Rows[$i+$c];if($y-lt$row.Lines.Count){$text=[string]$row.Lines[$y]};if($y-lt$row.TitleCount){$color=$row.Color}}
                    Write-VSOHost ($text.PadRight($plan.Cell)) -NoNewline -ForegroundColor $color
                    if($c-lt$plan.Columns-1){Write-VSOHost (' '*$plan.Gap) -NoNewline}
                }
                if($Boxed){Write-VSOHost ' │' -ForegroundColor $script:ThemeBorder}else{Write-VSOHost ''}
            }
        }
        if($Boxed){Write-VSOHost ($prefix+'└'+('─'*($plan.Width+2))+'┘') -ForegroundColor $script:ThemeBorder}
        $back=@($Items|Where-Object{$_.PSObject.Properties.Name-contains'SeparatorBefore'-and[bool]$_.SeparatorBefore})
        if($back.Count){Write-CenteredMenuVSO -Items $back}
    }finally{Stop-VSO7ConsoleDrawRecordVSO -Entered $entered}
}


function Write-VSOTitleFrameLine {

    param(
        [ValidateSet('Top','Divider','Bottom')][string]$Kind
    )
    $innerWidth = [Math]::Max(1,[Math]::Min(70,(Get-VSOConsoleWidth)-4))
    $consoleWidth = Get-VSOConsoleWidth
    $leftPad = [math]::Max(0,[math]::Floor(($consoleWidth - ($innerWidth + 2)) / 2))
    $prefix = ' ' * $leftPad
    switch ($Kind) {

        'Top'     {
            $line = '╔' + ('═' * $innerWidth) + '╗'
        }
        'Divider' {
            $line = '╠' + ('═' * $innerWidth) + '╣'
        }
        'Bottom'  {
            $line = '╚' + ('═' * $innerWidth) + '╝'
        }

    }
    Microsoft.PowerShell.Utility\Write-Host ($prefix + $line) -ForegroundColor $script:ThemeBorder

}

function Write-VSOTitleBoxLine {

    param(
        [AllowEmptyString()][string]$Text = '',
        [string]$Color = 'Gray'
    )
    $innerWidth = [Math]::Max(1,[Math]::Min(70,(Get-VSOConsoleWidth)-4))
    $shown = [string]$Text
    if ($shown.Length -gt $innerWidth) {
        $shown = $shown.Substring(0,$innerWidth)
    }
    $boxX=[int][Math]::Max(0,[Math]::Floor(((Get-VSOConsoleWidth)-$innerWidth-2)/2))
    $left = [int][Math]::Max(0,[Math]::Floor(((Get-VSOConsoleWidth)-$shown.Length)/2)-$boxX-1)
    $right = [Math]::Max(0,$innerWidth - $shown.Length - $left)
    $consoleWidth = Get-VSOConsoleWidth
    $leftPad = [math]::Max(0,[math]::Floor(($consoleWidth - ($innerWidth + 2)) / 2))
    $prefix = ' ' * $leftPad

    Microsoft.PowerShell.Utility\Write-Host ($prefix + '║') -NoNewline -ForegroundColor $script:ThemeBorder
    Microsoft.PowerShell.Utility\Write-Host ((' ' * $left) + $shown + (' ' * $right)) -NoNewline -ForegroundColor $Color
    Microsoft.PowerShell.Utility\Write-Host '║' -ForegroundColor $script:ThemeBorder

}

function Get-VSOLogoRows {

    # Each glyph has a fixed bounding box and every glyph is separated by exactly
    # two columns. This keeps V-S, S-O and O-7 spacing identical as a layout rule.
    $v = @(
        '██╗   ██╗',
        '██║   ██║',
        '██║   ██║',
        '╚██╗ ██╔╝',
        ' ╚████╔╝ ',
        '  ╚═══╝  '
    )
    $s = @(
        ' ███████╗',
        '██╔═════╝',
        '╚██████╗ ',
        ' ╚════██╗',
        '███████╔╝',
        '╚══════╝ '
    )
    $o = @(
        ' ██████╗ ',
        '██╔═══██╗',
        '██║   ██║',
        '██║   ██║',
        '╚██████╔╝',
        ' ╚═════╝ '
    )
    $seven = @(
        '████████╗',
        '╚════██╔╝',
        '    ██╔╝ ',
        '   ██╔╝  ',
        '  ██╔╝   ',
        '  ╚═╝    '
    )

    $rows = @()
    for ($i = 0; $i -lt 6; $i++) {

        # El precheck de release exige 42 columnas exactas. En runtime, sin embargo,
        # un defecto puramente visual nunca debe derribar VSO7: el renderer acepta
        # el ancho real de la fila y la centra de forma segura.
        $rows += ($v[$i] + '  ' + $s[$i] + '  ' + $o[$i] + '  ' + $seven[$i])

    }
    return $rows

}

function Write-VSOLogoLine {

    param(
        [Parameter(Mandatory=$true)][string]$Text,
        [string]$Color = 'Gray',
        [AllowEmptyString()][string]$CornerText = ''
    )
    $innerWidth = [Math]::Max(1,[Math]::Min(70,(Get-VSOConsoleWidth)-4))
    if ($Text.Length -gt $innerWidth) {
        $Text = $Text.Substring(0,$innerWidth)
    }
    $logoWidth = $Text.Length

    $boxX=[int][Math]::Max(0,[Math]::Floor(((Get-VSOConsoleWidth)-$innerWidth-2)/2))
    $left = [int][Math]::Max(0,[Math]::Floor(((Get-VSOConsoleWidth)-$logoWidth)/2)-$boxX-1)
    $right = [Math]::Max(0,$innerWidth - $logoWidth - $left)
    $consoleWidth = Get-VSOConsoleWidth
    $leftPad = [math]::Max(0,[math]::Floor(($consoleWidth - ($innerWidth + 2)) / 2))
    $prefix = ' ' * $leftPad

    Microsoft.PowerShell.Utility\Write-Host ($prefix + '║') -NoNewline -ForegroundColor $script:ThemeBorder
    Microsoft.PowerShell.Utility\Write-Host ((' ' * $left) + $Text) -NoNewline -ForegroundColor $Color
    if($CornerText-and$right-ge($CornerText.Length+1)){
        Microsoft.PowerShell.Utility\Write-Host ((' '*($right-$CornerText.Length-1))+$CornerText+' ') -NoNewline -ForegroundColor $script:ThemeMuted
    }else{
        Microsoft.PowerShell.Utility\Write-Host (' '*$right) -NoNewline -ForegroundColor $Color
    }
    Microsoft.PowerShell.Utility\Write-Host '║' -ForegroundColor $script:ThemeBorder

}

function Write-Title {
    $vsoDrawEntered=Start-VSO7ConsoleDrawRecordVSO -Name 'Write-Title' -Parameters $PSBoundParameters
    try {
        if($script:ConsoleDrawPending-and-not$script:ConsoleDrawReplaying){return}

    if($script:GuiMode){

        Clear-VSO7GuiOutputVSO
        Write-VSOHost ("VSO7 · {0}" -f $script:DisplayVersion) -ForegroundColor Yellow
        Write-VSOHost ''
        return

    }
    try{
        [Console]::Clear()
    }catch{}
    Microsoft.PowerShell.Utility\Write-Host ''

    if($script:ConsoleCompactHeader){
        Write-CenteredLineVSO -Text 'VSO7 — Vico Safe Optimizer' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text ('Version '+$script:DisplayVersion) -Color $script:ThemeCream
        Write-CenteredLineVSO -Text ('─'*[Math]::Min(48,(Get-VSOConsoleWidth)-2)) -Color $script:ThemeBorder
        return
    }
    $logoRows = Get-VSOLogoRows
    Write-VSOTitleFrameLine -Kind Top
    Write-VSOLogoLine -Text $logoRows[0] -Color $script:ThemeBrown -CornerText ('v'+$script:DisplayVersion)
    Write-VSOLogoLine -Text $logoRows[1] -Color $script:ThemeBrown
    Write-VSOLogoLine -Text $logoRows[2] -Color $script:ThemeCopper
    Write-VSOLogoLine -Text $logoRows[3] -Color $script:ThemeCopper
    Write-VSOLogoLine -Text $logoRows[4] -Color $script:ThemeCream
    Write-VSOLogoLine -Text $logoRows[5] -Color $script:ThemeCream
    Write-VSOTitleFrameLine -Kind Bottom
    Microsoft.PowerShell.Utility\Write-Host ''


    }finally{Stop-VSO7ConsoleDrawRecordVSO -Entered $vsoDrawEntered}
}

function Write-Section {

    param([string]$Text)
    Write-VSOHost ''
    $title = [string](Convert-VSOText -Value $Text)
    $width = [math]::Min(68,[math]::Max(28,$title.Length + 10))
    $side = [math]::Max(2,[math]::Floor(($width - $title.Length - 2)/2))
    $line = (('─' * $side) + ' ' + $title + ' ' + ('─' * $side))
    Write-CenteredLineVSO -Text $line -Color $script:ThemeCopper

}

function Write-VSO7Log {

    param(
        [Parameter(Mandatory=$true)][string]$Message,
        [ValidateSet('INFO','WARN','ERROR','CHANGE')][string]$Level = 'INFO'
    )

    $line = "[{0}] [{1}] {2}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$Level,$Message
    try {
        Add-Content -LiteralPath $script:LogFile -Value $line -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch {}

    $shown = [string](Convert-VSOText -Value $Message)
    switch ($Level) {

        'WARN'   {
            Write-VSOHost '[!] ' -NoNewline -ForegroundColor $script:ThemeWarning;
            Write-VSOHost $shown -ForegroundColor $script:ThemeText
        }
        'ERROR'  {
            Write-VSOHost '[X] ' -NoNewline -ForegroundColor $script:ThemeDanger;
            Write-VSOHost $shown -ForegroundColor $script:ThemeText
        }
        'CHANGE' {
            Write-VSOHost '[+] ' -NoNewline -ForegroundColor $script:ThemeSuccess;
            Write-VSOHost $shown -ForegroundColor $script:ThemeText
        }
        default  {
            Write-VSOHost '[i] ' -NoNewline -ForegroundColor $script:ThemeCopper;
            Write-VSOHost $shown -ForegroundColor $script:ThemeText
        }

    }

}

function Pause-Vico {

    Write-VSOHost ''
    if($script:GuiMode-or$script:GuiRequested){
        # GUI navigation owns continuation. Never use a modal "OK to continue" surrogate.
        return
    }
    [void](Read-VSOHost 'Pulsa ENTER para continuar')
}

function Confirm-Word {

    param(
        [Parameter(Mandatory=$true)][string]$Word,
        [Parameter(Mandatory=$true)][string]$Message
    )
    # Native GUI pages can perform an equivalent explicit dangerous-action confirmation and
    # authorize exactly one legacy typed token. This prevents text-entry confirmations from
    # leaking into mouse-driven flows while preserving the same underlying operation path.
    if($script:GuiMode-and$null-ne$script:GuiApprovedConfirmations-and$script:GuiApprovedConfirmations.ContainsKey($Word)){
        $approved=[bool]$script:GuiApprovedConfirmations[$Word]
        [void]$script:GuiApprovedConfirmations.Remove($Word)
        return $approved
    }

    $expected=$Word
    $prompt=$Message
    if($script:Language-eq'en'){
        $map=@{
            'ACEPTO BUILD NO VALIDADA'='I ACCEPT UNVALIDATED BUILD';'REVERTIR'='REVERT';
            'QUIERO ARRIESGAR WINDOWS'='I WANT TO RISK WINDOWS';'ALTO'='HIGH';'AGRESIVO'='AGGRESSIVE';
            'EQUILIBRADO'='BALANCED';'ELIMINAR APPS'='REMOVE APPS';'REVERTIR TODO'='REVERT ALL';
            'RIESGO 4'='RISK 4';'RESTAURAR NATIVO'='RESTORE NATIVE';'RESTAURAR RECOMENDADA'='RESTORE RECOMMENDED';'LEGACY'='LEGACY'
        }
        if($map.ContainsKey($Word)){$expected=[string]$map[$Word]}
        $prompt=('Type exactly: {0}'-f$expected)
    }
    $answer=Read-VSOHost $prompt
    return ($answer-ceq$expected)
}

function Initialize-VSOTrustedSystemPaths {

    try {

        $systemDirectory=[Environment]::SystemDirectory
        if([string]::IsNullOrWhiteSpace($systemDirectory)-or-not[IO.Path]::IsPathRooted($systemDirectory)){
            throw 'Environment.SystemDirectory no devolvio una ruta absoluta.'
        }
        $systemDirectory=[IO.Path]::GetFullPath($systemDirectory).TrimEnd('\')
        if(-not(Test-Path -LiteralPath $systemDirectory -PathType Container)){
            throw 'El directorio de sistema de Windows no existe.'
        }
        $windowsRoot=[IO.Path]::GetFullPath((Split-Path -Parent $systemDirectory)).TrimEnd('\')
        $systemDrive=[IO.Path]::GetPathRoot($windowsRoot).TrimEnd('\')
        if([string]::IsNullOrWhiteSpace($systemDrive)){
            throw 'No se pudo determinar la unidad de Windows.'
        }

        # Las rutas de usuario usadas como frontera de seguridad NO se toman de
        # Known Folders configurables por HKCU. Se derivan del ProfileImagePath
        # registrado bajo HKLM para el SID actual y se rechazan redirecciones/reparse.
        $sid=(Get-VSO7CurrentUserSidVSO).Value
        $profileKey=$null
        try{

            $profileKey=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey(('SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\{0}'-f$sid),$false)
            if($null-eq$profileKey){
                throw 'No existe ProfileList para el SID actual.'
            }
            $profileRaw=[string]$profileKey.GetValue('ProfileImagePath',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)

        }finally{
            if($null-ne$profileKey){
                try{
                    $profileKey.Close()
                }catch{}
            }
        }
        if([string]::IsNullOrWhiteSpace($profileRaw)){
            throw 'ProfileImagePath del usuario esta vacio.'
        }
        $profileExpanded=$profileRaw -replace '(?i)%SystemDrive%',[string]$systemDrive
        $profileExpanded=$profileExpanded -replace '(?i)%SystemRoot%',[string]$windowsRoot
        $profileExpanded=$profileExpanded -replace '(?i)%windir%',[string]$windowsRoot
        if($profileExpanded-match'%[^%]+%'){
            throw 'ProfileImagePath contiene variables no permitidas.'
        }
        $profileRoot=[IO.Path]::GetFullPath($profileExpanded).TrimEnd('\')
        if($profileRoot-notmatch'^[A-Za-z]:\\'){
            throw 'ProfileImagePath no es una ruta local de unidad.'
        }
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $profileRoot)
        $local=[IO.Path]::GetFullPath((Join-Path $profileRoot 'AppData\Local')).TrimEnd('\')
        $roaming=[IO.Path]::GetFullPath((Join-Path $profileRoot 'AppData\Roaming')).TrimEnd('\')

        $common=[Environment]::GetFolderPath([Environment+SpecialFolder]::CommonApplicationData)
        $programFiles=[Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFiles)
        $programFilesX86=[Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFilesX86)
        foreach($required in @($common,$programFiles)){

            if([string]::IsNullOrWhiteSpace([string]$required)-or-not[IO.Path]::IsPathRooted([string]$required)){
                throw 'Windows no devolvio una carpeta de sistema conocida valida.'
            }

        }

        $script:SystemDirectory=$systemDirectory
        $script:WindowsRoot=$windowsRoot
        $script:SystemDrive=$systemDrive
        $script:UserProfileRoot=$profileRoot
        $script:LocalAppData=$local
        $script:AppData=$roaming
        $script:ProgramData=[IO.Path]::GetFullPath($common).TrimEnd('\')
        $script:ProgramFiles=[IO.Path]::GetFullPath($programFiles).TrimEnd('\')
        $script:ProgramFilesX86=$(if([string]::IsNullOrWhiteSpace([string]$programFilesX86)){
            $null
        }else{
            [IO.Path]::GetFullPath($programFilesX86).TrimEnd('\')
        })

    } catch {

        throw ("VSO7 no pudo obtener rutas confiables de Windows mediante .NET: {0}" -f $_.Exception.Message)

    }

}

function Get-VSO7CurrentUserSidVSO {

    $identity=$null
    try{

        $identity=[Security.Principal.WindowsIdentity]::GetCurrent()
        if($null-eq$identity.User){
            throw 'WindowsIdentity no contiene SID de usuario.'
        }
        return (New-Object Security.Principal.SecurityIdentifier($identity.User.Value))

    }finally{
        if($null-ne$identity){
            try{
                $identity.Dispose()
            }catch{}
        }
    }

}

function Test-VSO7AclRightsCanModifyVSO {

    param([Parameter(Mandatory=$true)][Security.AccessControl.FileSystemRights]$Rights)
    $dangerous=[Security.AccessControl.FileSystemRights]::Write -bor
        [Security.AccessControl.FileSystemRights]::Delete -bor
        [Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles -bor
        [Security.AccessControl.FileSystemRights]::ChangePermissions -bor
        [Security.AccessControl.FileSystemRights]::TakeOwnership
    return (($Rights-band$dangerous)-ne0)

}

function New-VSO7LockedDirectoryAcl {

    $admins=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18')
    $currentUser=Get-VSO7CurrentUserSidVSO
    $acl=New-Object Security.AccessControl.DirectorySecurity
    $acl.SetAccessRuleProtection($true,$false)
    $acl.SetOwner($admins)
    $inherit=[Security.AccessControl.InheritanceFlags]::ContainerInherit-bor[Security.AccessControl.InheritanceFlags]::ObjectInherit
    $prop=[Security.AccessControl.PropagationFlags]::None
    $allow=[Security.AccessControl.AccessControlType]::Allow
    $rights=[Security.AccessControl.FileSystemRights]::FullControl
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($system,$rights,$inherit,$prop,$allow)))
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($admins,$rights,$inherit,$prop,$allow)))
    if(@($system.Value,$admins.Value)-notcontains$currentUser.Value){

        $read=[Security.AccessControl.FileSystemRights]::ReadAndExecute
        $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($currentUser,$read,$inherit,$prop,$allow)))

    }
    return $acl

}

function New-VSO7LockedFileAcl {

    $admins=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18')
    $currentUser=Get-VSO7CurrentUserSidVSO
    $acl=New-Object Security.AccessControl.FileSecurity
    $acl.SetAccessRuleProtection($true,$false)
    $acl.SetOwner($admins)
    $allow=[Security.AccessControl.AccessControlType]::Allow
    $rights=[Security.AccessControl.FileSystemRights]::FullControl
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($system,$rights,$allow)))
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($admins,$rights,$allow)))
    if(@($system.Value,$admins.Value)-notcontains$currentUser.Value){

        $read=[Security.AccessControl.FileSystemRights]::Read
        $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($currentUser,$read,$allow)))

    }
    return $acl

}

function Assert-VSO7ExistingSecureDirectoryProvenance {

    param([Parameter(Mandatory=$true)][string]$Path)
    $di=New-Object IO.DirectoryInfo($Path)
    $sections=[Security.AccessControl.AccessControlSections]::Access -bor [Security.AccessControl.AccessControlSections]::Owner
    $acl=$di.GetAccessControl($sections)
    $owner=$acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
    if(@('S-1-5-32-544','S-1-5-18') -notcontains $owner){
        throw ("Directorio de seguridad preexistente con owner no confiable: {0}" -f $Path)
    }
    foreach($rule in $acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])){

        if($rule.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow){
            continue
        }
        if(@('S-1-5-32-544','S-1-5-18') -contains $rule.IdentityReference.Value){
            continue
        }
        if(Test-VSO7AclRightsCanModifyVSO -Rights $rule.FileSystemRights){

            throw ("Directorio de seguridad preexistente permite escritura a {0}: {1}" -f $rule.IdentityReference.Value,$Path)

        }

    }

}

function Protect-VSO7SecureDirectory {

    param([Parameter(Mandatory=$true)][string]$Path)
    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        throw 'Ruta segura invalida.'
    }
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if(Test-Path -LiteralPath $full){

        $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
        if(-not$item.PSIsContainer){
            throw 'La ruta de estado seguro existe pero no es un directorio.'
        }
        if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'La ruta de estado seguro es un reparse point.'
        }
        Assert-VSO7ExistingSecureDirectoryProvenance -Path $full

    }else{

        # En Windows PowerShell 5.1 (.NET Framework), este overload aplica la
        # DirectorySecurity durante la creacion. Aun asi, si otra entidad gana
        # exactamente la carrera de creacion, CreateDirectory puede devolver una
        # ruta preexistente: validamos procedencia ANTES de reescribir su ACL.
        [IO.Directory]::CreateDirectory($full,(New-VSO7LockedDirectoryAcl))|Out-Null
        $createdItem=Get-Item -LiteralPath $full -Force -ErrorAction Stop
        if(-not$createdItem.PSIsContainer-or($createdItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'La ruta de estado seguro creada es invalida/reparse point.'
        }
        Assert-VSO7ExistingSecureDirectoryProvenance -Path $full

    }
    $di=New-Object IO.DirectoryInfo($full)
    $di.SetAccessControl((New-VSO7LockedDirectoryAcl))
    $sections=[Security.AccessControl.AccessControlSections]::Access -bor [Security.AccessControl.AccessControlSections]::Owner
    $check=$di.GetAccessControl($sections)
    $owner=$check.GetOwner([Security.Principal.SecurityIdentifier]).Value
    if(@('S-1-5-32-544','S-1-5-18')-notcontains$owner){
        throw 'Owner inesperado en el estado seguro.'
    }
    foreach($rule in $check.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])){

        if($rule.AccessControlType-ne[Security.AccessControl.AccessControlType]::Allow){
            continue
        }
        if(@('S-1-5-32-544','S-1-5-18')-contains$rule.IdentityReference.Value){
            continue
        }
        if(Test-VSO7AclRightsCanModifyVSO -Rights $rule.FileSystemRights){
            throw ("ACL de estado seguro concede escritura inesperada a: {0}"-f$rule.IdentityReference.Value)
        }

    }
    return $full

}

function Assert-VSO7ProtectedDirectChildFileVSO {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$AllowedParent,
        [switch]$AllowMissing
    )
    if([string]::IsNullOrWhiteSpace($Path)-or[string]::IsNullOrWhiteSpace($AllowedParent)){
        throw 'Ruta protegida vacia.'
    }
    $parent=[IO.Path]::GetFullPath($AllowedParent).TrimEnd('\')
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if([IO.Path]::GetDirectoryName($full)-ine$parent){
        throw 'Archivo fuera del directorio protegido esperado.'
    }
    $parentItem=Get-Item -LiteralPath $parent -Force -ErrorAction Stop
    if(-not$parentItem.PSIsContainer-or($parentItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Directorio protegido invalido/reparse point.'
    }
    Assert-VSO7ExistingSecureDirectoryProvenance -Path $parent
    if(-not(Test-Path -LiteralPath $full)){

        if($AllowMissing){
            return $full
        }
        throw 'Falta archivo protegido esperado.'

    }
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Archivo protegido invalido/reparse point.'
    }
    return $full

}

function Protect-VSO7ProtectedFileVSO {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$AllowedParent,
        [switch]$AllowMissing
    )
    $full=Assert-VSO7ProtectedDirectChildFileVSO -Path $Path -AllowedParent $AllowedParent -AllowMissing:$AllowMissing
    if(-not(Test-Path -LiteralPath $full)){
        return $full
    }
    $fi=New-Object IO.FileInfo($full)
    $fi.SetAccessControl((New-VSO7LockedFileAcl))
    [void](Assert-VSO7ProtectedDirectChildFileVSO -Path $full -AllowedParent $AllowedParent)
    return $full

}

function Commit-VSO7AtomicFileVSO {

    param(
        [Parameter(Mandatory=$true)][string]$SourcePath,
        [Parameter(Mandatory=$true)][string]$DestinationPath
    )
    if([string]::IsNullOrWhiteSpace($SourcePath)-or[string]::IsNullOrWhiteSpace($DestinationPath)){
        throw 'Commit atomico recibio una ruta vacia.'
    }
    $src=[IO.Path]::GetFullPath($SourcePath)
    $dst=[IO.Path]::GetFullPath($DestinationPath)
    $parent=[IO.Path]::GetDirectoryName($dst).TrimEnd('\')
    if([IO.Path]::GetDirectoryName($src).TrimEnd('\')-ine$parent){
        throw 'El temporal y el destino del commit atomico deben compartir directorio.'
    }
    $parentItem=Get-Item -LiteralPath $parent -Force -ErrorAction Stop
    if(-not$parentItem.PSIsContainer-or($parentItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Directorio del commit atomico invalido/reparse point.'
    }
    Assert-VSO7ExistingSecureDirectoryProvenance -Path $parent
    $srcItem=Get-Item -LiteralPath $src -Force -ErrorAction Stop
    if($srcItem.PSIsContainer-or($srcItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Temporal del commit atomico invalido/reparse point.'
    }
    if(Test-Path -LiteralPath $dst){

        $dstItem=Get-Item -LiteralPath $dst -Force -ErrorAction Stop
        if($dstItem.PSIsContainer-or($dstItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'Destino del commit atomico invalido/reparse point.'
        }
        [IO.File]::Replace($src,$dst,[System.Management.Automation.Language.NullString]::Value)

    }else{

        [IO.File]::Move($src,$dst)

    }
    $final=Get-Item -LiteralPath $dst -Force -ErrorAction Stop
    if($final.PSIsContainer-or($final.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'El archivo resultante del commit atomico es invalido/reparse point.'
    }
    [void](Protect-VSO7ProtectedFileVSO -Path $dst -AllowedParent $parent)
    return $dst

}

function Copy-VSO7FileAtomicallyVSO {

    param(
        [Parameter(Mandatory=$true)][string]$SourcePath,
        [Parameter(Mandatory=$true)][string]$DestinationPath
    )
    $src=[IO.Path]::GetFullPath($SourcePath)
    $dst=[IO.Path]::GetFullPath($DestinationPath)
    if(-not(Test-Path -LiteralPath $src -PathType Leaf)){
        throw 'Origen ausente para copia atomica.'
    }
    $srcItem=Get-Item -LiteralPath $src -Force -ErrorAction Stop
    if($srcItem.PSIsContainer-or($srcItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Origen invalido/reparse point para copia atomica.'
    }
    $parent=[IO.Path]::GetDirectoryName($dst).TrimEnd('\')
    if([string]::IsNullOrWhiteSpace($parent)-or-not(Test-Path -LiteralPath $parent -PathType Container)){
        throw 'Directorio destino ausente para copia atomica.'
    }
    [void](Assert-VSO7ExistingSecureDirectoryProvenance -Path $parent)
    $temp=Join-Path $parent ('.vso-copy-'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{

        Copy-Item -LiteralPath $src -Destination $temp -ErrorAction Stop
        [void](Commit-VSO7AtomicFileVSO -SourcePath $temp -DestinationPath $dst)

    }finally{

        if(Test-Path -LiteralPath $temp -PathType Leaf){

            try{

                $item=Get-Item -LiteralPath $temp -Force -ErrorAction Stop
                if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-eq0){
                    Remove-Item -LiteralPath $temp -Force -ErrorAction Stop
                }

            }catch{}

        }

    }
    return $dst

}

function Get-VSO7LoadedRecoveryRunnerHashVSO {

    if([string]::IsNullOrWhiteSpace([string]$script:BootstrapLoadedScriptContents)){
        throw 'No existe ScriptContents cargado para identificar Recovery Runner.'
    }
    # Recovery Runner se guarda como UTF-8 CON BOM por compatibilidad con Windows PowerShell 5.1.
    # El nombre del runner usa el hash de esos bytes exactos, no del archivo de origen mutable.
    $enc=New-Object Text.UTF8Encoding($true)
    $preamble=$enc.GetPreamble()
    $body=$enc.GetBytes([string]$script:BootstrapLoadedScriptContents)
    $bytes=New-Object byte[] ($preamble.Length+$body.Length)
    if($preamble.Length-gt0){
        [Array]::Copy($preamble,0,$bytes,0,$preamble.Length)
    }
    if($body.Length-gt0){
        [Array]::Copy($body,0,$bytes,$preamble.Length,$body.Length)
    }
    $sha=[Security.Cryptography.SHA256]::Create()
    try{
        return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToUpperInvariant()
    }
    finally{

        $sha.Dispose()
        if($null-ne$body){
            [Array]::Clear($body,0,$body.Length)
        }
        if($null-ne$bytes){
            [Array]::Clear($bytes,0,$bytes.Length)
        }

    }

}

function Initialize-VSO7RecoveryRunnerIdentityVSO {

    if([string]::IsNullOrWhiteSpace([string]$script:SecureStateRoot)){
        throw 'SecureStateRoot no inicializado para Recovery Runner.'
    }
    if(([string]$script:Version)-notmatch'^[0-9]+(?:\.[0-9]+){1,3}$'){
        throw 'Version VSO7 no valida para identificar Recovery Runner.'
    }
    $hash=Get-VSO7LoadedRecoveryRunnerHashVSO
    if($hash-notmatch'^[A-F0-9]{64}$'){
        throw 'Hash invalido del Recovery Runner.'
    }
    $root=Protect-VSO7SecureDirectory -Path (Join-Path $script:SecureStateRoot 'RecoveryRunners')
    $leaf=('VSO7-RecoveryRunner-{0}-{1}.ps1'-f[string]$script:Version,$hash)
    $script:RecoveryRunnerRoot=$root
    $script:RecoveryRunnerHash=$hash
    $script:RecoveryRunnerScript=Join-Path $root $leaf
    [void](Protect-VSO7ProtectedFileVSO -Path $script:RecoveryRunnerScript -AllowedParent $root -AllowMissing)
    return $script:RecoveryRunnerScript

}

function Install-VSO7ProtectedRecoveryRunnerVSO {

    if([string]::IsNullOrWhiteSpace([string]$script:RecoveryRunnerScript)){
        throw 'Ruta del Recovery Runner protegido no inicializada.'
    }
    if([string]::IsNullOrWhiteSpace([string]$script:RecoveryRunnerHash)){
        throw 'Hash del Recovery Runner protegido no inicializado.'
    }
    if([string]::IsNullOrWhiteSpace([string]$script:BootstrapLoadedScriptContents)){
        throw 'No existe ScriptContents cargado para instalar Recovery Runner sin releer disco.'
    }
    $dest=[IO.Path]::GetFullPath([string]$script:RecoveryRunnerScript)
    $parent=[IO.Path]::GetDirectoryName($dest).TrimEnd('\')
    if($parent-ine[IO.Path]::GetFullPath([string]$script:RecoveryRunnerRoot).TrimEnd('\')){
        throw 'Recovery Runner fuera de RecoveryRunnerRoot.'
    }
    [void](Protect-VSO7SecureDirectory -Path $parent)

    # Content-addressed e inmutable: una version/hash ya instalada se reutiliza; si el
    # archivo con ese nombre no tiene ese hash, se falla cerrado en vez de sobrescribirlo.
    if(Test-Path -LiteralPath $dest -PathType Leaf){

        [void](Protect-VSO7ProtectedFileVSO -Path $dest -AllowedParent $parent)
        $existingHash=(Get-FileHash -LiteralPath $dest -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($existingHash-ine[string]$script:RecoveryRunnerHash){
            throw 'Recovery Runner versionado existente no coincide con su hash; VSO7 no lo sobrescribira.'
        }
        return $dest

    }

    $tmp=Join-Path $parent ('.recovery-runner-'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{

        # Se serializa exactamente el texto ya cargado por el host confiable. El BOM se
        # fija aqui para que Windows PowerShell 5.1 interprete Unicode/acentos de forma estable.
        [IO.File]::WriteAllText($tmp,[string]$script:BootstrapLoadedScriptContents,(New-Object Text.UTF8Encoding($true)))
        $tmpItem=Get-Item -LiteralPath $tmp -Force -ErrorAction Stop
        if($tmpItem.PSIsContainer-or($tmpItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'Temporal del Recovery Runner invalido/reparse point.'
        }
        $expectedHash=(Get-FileHash -LiteralPath $tmp -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($expectedHash-ine[string]$script:RecoveryRunnerHash){
            throw 'Los bytes del Recovery Runner no coinciden con la identidad calculada.'
        }
        if(Test-Path -LiteralPath $dest){
            throw 'Recovery Runner aparecio durante la instalacion; VSO7 se niega a sobrescribirlo.'
        }
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $dest)
        $finalHash=(Get-FileHash -LiteralPath $dest -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($finalHash-ine$expectedHash){
            throw 'Recovery Runner protegido no coincide con el contenido ya cargado por VSO7.'
        }

    }finally{

        if(Test-Path -LiteralPath $tmp -PathType Leaf){
            try{
                $ti=Get-Item -LiteralPath $tmp -Force -ErrorAction Stop;
                if(($ti.Attributes-band[IO.FileAttributes]::ReparsePoint)-eq0){
                    Remove-Item -LiteralPath $tmp -Force -ErrorAction Stop
                }
            }catch{}
        }

    }
    return $dest

}
function Assert-VSO7RecoveryExecutionTrustVSO {

    if([string]::IsNullOrWhiteSpace($RestoreFromBundle)){
        return
    }
    if([string]::IsNullOrWhiteSpace([string]$script:RecoveryRunnerScript)){
        throw 'Recovery Runner protegido no esta inicializado.'
    }
    $expected=[IO.Path]::GetFullPath([string]$script:RecoveryRunnerScript)
    $actual=if([string]::IsNullOrWhiteSpace([string]$script:BootstrapOriginalSourcePath)){
        $null
    }else{
        [IO.Path]::GetFullPath([string]$script:BootstrapOriginalSourcePath)
    }
    if($null-eq$actual-or$actual-ine$expected){
        throw 'Recovery elevado solo puede proceder del Recovery Runner protegido de ProgramData. Usa ROLLBACK.cmd generado por VSO7 o el menu Recovery.'
    }
    [void](Protect-VSO7ProtectedFileVSO -Path $expected -AllowedParent ([IO.Path]::GetDirectoryName($expected)))

}

function Protect-VSO7SecureStateLeaf {

    param([Parameter(Mandatory=$true)][string]$Path,[switch]$AllowMissing)
    $root=[IO.Path]::GetFullPath([string]$script:SecureStateRoot).TrimEnd('\')
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if([IO.Path]::GetDirectoryName($full)-ine$root){
        throw 'Archivo de estado fuera del SecureStateRoot.'
    }
    if(-not(Test-Path -LiteralPath $full)){

        if($AllowMissing){
            return $full
        }
        throw 'Falta archivo de estado seguro esperado.'

    }
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Archivo de estado seguro invalido/reparse point.'
    }
    $fi=New-Object IO.FileInfo($full)
    $fi.SetAccessControl((New-VSO7LockedFileAcl))
    return $full

}

function Assert-VSO7LegacyFixedStateSafeToIgnoreVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('Normal','Extreme')][string]$Kind,[Parameter(Mandatory=$true)][string]$LegacyPath,[Parameter(Mandatory=$true)][string]$SecurePath)
    if(-not(Test-Path -LiteralPath $LegacyPath -PathType Leaf)-or(Test-Path -LiteralPath $SecurePath)){
        return
    }
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $LegacyPath)
    $legacyItem=Get-Item -LiteralPath $LegacyPath -Force -ErrorAction Stop
    if($legacyItem.PSIsContainer-or($legacyItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw ("Estado legado {0} es invalido/reparse point; VSO7 no continuara."-f$Kind)
    }
    $limit=if($Kind-eq'Normal'){
        16777216
    }else{
        33554432
    }
    if([int64]$legacyItem.Length-le0-or[int64]$legacyItem.Length-gt$limit){
        throw ("Estado legado {0} excede el tamano permitido para validacion segura."-f$Kind)
    }
    $obj=Get-Content -LiteralPath $LegacyPath -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    if($Kind-eq'Normal'){

        $validated=ConvertTo-VSO7ValidatedNormalState -Object $obj
        $hasRollback=(@($validated.Registry).Count-gt0 -or -not[string]::IsNullOrWhiteSpace([string]$validated.OriginalPowerScheme) -or -not[string]::IsNullOrWhiteSpace([string]$validated.AppliedPowerScheme) -or -not[string]::IsNullOrWhiteSpace([string]$validated.PendingPowerScheme))
        if($hasRollback){
            throw 'Existe state.json legado no protegido con rollback. Aunque su esquema sea valido, 7.0.0 no puede autenticar su procedencia y se niega a importarlo/ejecutarlo automaticamente.'
        }

    }else{

        $validated=ConvertTo-VSO7ValidatedExtremeState -Object $obj
        $hasRollback=(@($validated.Registry).Count-gt0-or@($validated.Services).Count-gt0-or@($validated.Features).Count-gt0-or@($validated.PowerSettings).Count-gt0-or$null-ne$validated.Hibernation-or@($validated.Bcd).Count-gt0-or@($validated.PendingTweaks).Count-gt0-or@($validated.AppliedTweaks).Count-gt0)
        if($hasRollback){
            throw 'Existe extreme-state.json legado no protegido con rollback. Aunque su esquema sea valido, 7.0.0 no puede autenticar su procedencia y se niega a importarlo/ejecutarlo automaticamente.'
        }

    }
    Write-VSO7Log ("Estado legado {0} vacio/sin rollback detectado; se ignora y no se importa a almacenamiento protegido."-f$Kind) 'WARN'

}

function New-VSO7SecretDirectoryAclVSO {

    $admins=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18')
    $acl=New-Object Security.AccessControl.DirectorySecurity
    $acl.SetAccessRuleProtection($true,$false);
    $acl.SetOwner($admins)
    $inherit=[Security.AccessControl.InheritanceFlags]::ContainerInherit-bor[Security.AccessControl.InheritanceFlags]::ObjectInherit
    $none=[Security.AccessControl.PropagationFlags]::None;
    $allow=[Security.AccessControl.AccessControlType]::Allow
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($system,[Security.AccessControl.FileSystemRights]::FullControl,$inherit,$none,$allow)))
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($admins,[Security.AccessControl.FileSystemRights]::FullControl,$inherit,$none,$allow)))
    return $acl

}

function New-VSO7SecretFileAclVSO {

    $admins=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18')
    $acl=New-Object Security.AccessControl.FileSecurity
    $acl.SetAccessRuleProtection($true,$false);
    $acl.SetOwner($admins);
    $allow=[Security.AccessControl.AccessControlType]::Allow
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($system,[Security.AccessControl.FileSystemRights]::FullControl,$allow)))
    $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($admins,[Security.AccessControl.FileSystemRights]::FullControl,$allow)))
    return $acl

}

function Get-VSO7SecretAclAssessmentVSO {

    param([Parameter(Mandatory=$true)]$Info)
    if(($Info.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        return [pscustomobject]@{SafeToNormalize=$false;OwnerTrusted=$false;IsReparse=$true;ExternalRead=$false;ExternalModify=$false;ExternalRules=@();Reason='reparse-point'}
    }
    $sections=[Security.AccessControl.AccessControlSections]::Access-bor[Security.AccessControl.AccessControlSections]::Owner
    $acl=$Info.GetAccessControl($sections)
    $owner=$acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
    $ownerTrusted=(@('S-1-5-32-544','S-1-5-18')-contains$owner)
    $trusted=@('S-1-5-32-544','S-1-5-18')
    $mutating=[Security.AccessControl.FileSystemRights]::WriteData-bor
        [Security.AccessControl.FileSystemRights]::AppendData-bor
        [Security.AccessControl.FileSystemRights]::WriteExtendedAttributes-bor
        [Security.AccessControl.FileSystemRights]::WriteAttributes-bor
        [Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles-bor
        [Security.AccessControl.FileSystemRights]::Delete-bor
        [Security.AccessControl.FileSystemRights]::ChangePermissions-bor
        [Security.AccessControl.FileSystemRights]::TakeOwnership
    $external=New-Object 'Collections.Generic.List[object]'
    $externalRead=$false
    $externalModify=$false
    foreach($rule in $acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])){
        if($rule.AccessControlType-ne[Security.AccessControl.AccessControlType]::Allow){continue}
        $sid=[string]$rule.IdentityReference.Value
        if($trusted-contains$sid){continue}
        $rights=[Security.AccessControl.FileSystemRights]$rule.FileSystemRights
        $isModify=(($rights-band$mutating)-ne0)
        if($isModify){$externalModify=$true}else{$externalRead=$true}
        [void]$external.Add([pscustomobject]@{Sid=$sid;Rights=[string]$rights;Inherited=[bool]$rule.IsInherited;ModifyCapable=[bool]$isModify})
    }
    $reason=if(-not$ownerTrusted){'untrusted-owner'}elseif($externalModify){'external-modify'}elseif($externalRead){'external-read-only'}else{'strict-or-admin-only'}
    return [pscustomobject]@{
        SafeToNormalize=[bool]($ownerTrusted-and-not$externalModify)
        OwnerTrusted=[bool]$ownerTrusted
        IsReparse=$false
        ExternalRead=[bool]$externalRead
        ExternalModify=[bool]$externalModify
        ExternalRules=$external.ToArray()
        Reason=$reason
        AccessRulesProtected=[bool]$acl.AreAccessRulesProtected
    }

}

function Assert-VSO7SecretAclVSO {

    param([Parameter(Mandatory=$true)]$Info)
    $assessment=Get-VSO7SecretAclAssessmentVSO -Info $Info
    if($assessment.IsReparse){throw 'The VSO7 secret is a reparse point.'}
    if(-not$assessment.OwnerTrusted){throw 'The VSO7 secret has an untrusted owner.'}
    if($assessment.ExternalModify){throw 'The VSO7 secret grants modification rights to a non-administrative identity.'}
    if($assessment.ExternalRead){throw 'The VSO7 secret grants access to a non-administrative identity.'}
    if(-not$assessment.AccessRulesProtected){throw 'The VSO7 secret still has ACL inheritance enabled.'}

}

function Assert-VSO7SecretAclSafeToNormalizeVSO {

    param([Parameter(Mandatory=$true)]$Info,[Parameter(Mandatory=$true)][string]$Kind)
    $assessment=Get-VSO7SecretAclAssessmentVSO -Info $Info
    if($assessment.IsReparse){throw ("VSO7 secret {0} is a reparse point; its ACL will not be changed."-f$Kind)}
    if(-not$assessment.OwnerTrusted){throw ("VSO7 secret {0} has an untrusted owner; its ACL will not be changed."-f$Kind)}
    if($assessment.ExternalModify){
        $rules=@($assessment.ExternalRules|Where-Object{$_.ModifyCapable}|ForEach-Object{
            '{0}: {1} (Inherited={2})'-f$_.Sid,$_.Rights,$_.Inherited
        })-join'; '
        throw ("VSO7 secret {0} grants external write access. Path: {1}. ACL: {2}. The existing state was preserved without changes. Do not delete Secrets or recovery-auth.key; first review the ACLs and any Recovery backups that depend on this key."-f$Kind,[string]$Info.FullName,$rules)
    }
    return $assessment

}

function Protect-VSO7SecretDirectoryVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if(Test-Path -LiteralPath $full){

        $di=New-Object IO.DirectoryInfo($full)
        $assessment=Assert-VSO7SecretAclSafeToNormalizeVSO -Info $di -Kind 'directory'
        if($assessment.ExternalRead){
            Write-VSO7Log 'Secrets granted external read-only access; its ACL is being restricted to SYSTEM and Administrators before secret material is used.' 'WARN'
        }

    }else{

        [IO.Directory]::CreateDirectory($full,(New-VSO7SecretDirectoryAclVSO))|Out-Null
        $di=New-Object IO.DirectoryInfo($full)
        # Igual que en el arbol de estado: no corregimos una ruta aparecida por carrera
        # hasta demostrar owner confiable, ausencia de reparse y ausencia de escritura externa.
        [void](Assert-VSO7SecretAclSafeToNormalizeVSO -Info $di -Kind 'directory')

    }
    $di.SetAccessControl((New-VSO7SecretDirectoryAclVSO))
    Assert-VSO7SecretAclVSO -Info $di
    return $full

}

function Test-VSO7RecoveryAuthDependentMaterialVSO {

    if(-not[string]::IsNullOrWhiteSpace([string]$script:RecoveryRoot)-and(Test-Path -LiteralPath $script:RecoveryRoot -PathType Container)){
        [void](Assert-VSO7ExistingSecureDirectoryProvenance -Path $script:RecoveryRoot)
        # Only modern Recovery generations containing origin.json depend on the
        # HMAC identity. Legacy Startup snapshots such as seleccion-antes.json
        # are useful rollback data, but rotating this key does not invalidate
        # them. Treating every child as key-dependent permanently blocked a
        # safe migration from older Secrets ACLs.
        $pending=New-Object 'Collections.Generic.Queue[IO.DirectoryInfo]'
        $pending.Enqueue((New-Object IO.DirectoryInfo([string]$script:RecoveryRoot)))
        while($pending.Count-gt0){
            $directory=$pending.Dequeue()
            foreach($file in @($directory.GetFiles())){
                if(($file.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){return $true}
                if([string]$file.Name-ieq'origin.json'){return $true}
            }
            foreach($child in @($directory.GetDirectories())){
                if(($child.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){return $true}
                $pending.Enqueue($child)
            }
        }
    }
    if(-not[string]::IsNullOrWhiteSpace([string]$script:SecureStateRoot)){
        foreach($name in @('recovery-publish-pending.json','recovery-reconcile-pending.json')){
            $pending=Join-Path ([string]$script:SecureStateRoot) $name
            if(Test-Path -LiteralPath $pending -PathType Leaf){return $true}
        }
    }
    return $false

}

function Move-VSO7UntrustedSecretDirectoryAsideVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)]$Assessment)
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    $secure=[IO.Path]::GetFullPath([string]$script:SecureStateRoot).TrimEnd('\')
    if([string]::IsNullOrWhiteSpace($secure)-or[IO.Path]::GetDirectoryName($full)-ine$secure-or[IO.Path]::GetFileName($full)-ine'Secrets'){
        throw 'Secrets migration received a path outside protected storage.'
    }
    if(-not[bool]$Assessment.OwnerTrusted-or[bool]$Assessment.IsReparse-or-not[bool]$Assessment.ExternalModify){
        throw 'Secrets migration received an inconsistent ACL assessment.'
    }
    [void](Assert-VSO7ExistingSecureDirectoryProvenance -Path $secure)
    $destination=Join-Path $secure ('Secrets-Untrusted-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N'))
    if(Test-Path -LiteralPath $destination){throw 'The Secrets quarantine destination already exists.'}
    [IO.Directory]::Move($full,$destination)
    if((Test-Path -LiteralPath $full)-or-not(Test-Path -LiteralPath $destination -PathType Container)){
        throw 'The untrusted Secrets directory could not be quarantined atomically.'
    }
    Write-VSO7Log ('Secrets with external write access was preserved as untrusted evidence at: '+$destination) 'WARN'
    Write-VSOHost ('[WARNING] An old untrusted Secrets directory was quarantined at: '+$destination) -ForegroundColor Yellow
    return $destination

}

function New-VSO7RecoveryAuthKeyFileVSO {

    param([Parameter(Mandatory=$true)][string]$SecretRoot,[Parameter(Mandatory=$true)][string]$KeyPath,[switch]$ReplaceExisting)
    $rng=[Security.Cryptography.RandomNumberGenerator]::Create()
    $bytes=New-Object byte[] 32
    $keyTemp=Join-Path $SecretRoot ('.recovery-auth-'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{

        $rng.GetBytes($bytes)
        [IO.File]::WriteAllBytes($keyTemp,$bytes)
        $tempInfo=New-Object IO.FileInfo($keyTemp)
        if(($tempInfo.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or[int64]$tempInfo.Length-ne32){throw 'The temporary recovery-auth.key file is invalid.'}
        $tempInfo.SetAccessControl((New-VSO7SecretFileAclVSO))
        Assert-VSO7SecretAclVSO -Info $tempInfo
        if($ReplaceExisting){
            if(-not(Test-Path -LiteralPath $KeyPath -PathType Leaf)){throw 'recovery-auth.key disappeared before it could be rotated safely.'}
            [IO.File]::Replace($keyTemp,$KeyPath,$null)
        }else{
            if(Test-Path -LiteralPath $KeyPath){throw 'recovery-auth.key appeared while it was being created; VSO7 will not overwrite it.'}
            [IO.File]::Move($keyTemp,$KeyPath)
        }
        $published=New-Object IO.FileInfo($KeyPath)
        $published.SetAccessControl((New-VSO7SecretFileAclVSO))
        Assert-VSO7SecretAclVSO -Info $published
        if([int64]$published.Length-ne32){throw 'recovery-auth.key has an invalid size after publication.'}

    }finally{

        $rng.Dispose()
        if($null-ne$bytes){[Array]::Clear($bytes,0,$bytes.Length)}
        if(Test-Path -LiteralPath $keyTemp -PathType Leaf){
            try{
                $ti=New-Object IO.FileInfo($keyTemp)
                if(($ti.Attributes-band[IO.FileAttributes]::ReparsePoint)-eq0){[IO.File]::Delete($keyTemp)}
            }catch{}
        }

    }

}

function Get-VSO7RecoveryAuthKeyVSO {

    param([switch]$RequireExisting)
    if([string]::IsNullOrWhiteSpace([string]$script:SecureStateRoot)){throw 'SecureStateRoot is not initialized for Recovery authentication.'}

    $secretRootPath=[IO.Path]::GetFullPath((Join-Path $script:SecureStateRoot 'Secrets')).TrimEnd('\')
    $keyPath=Join-Path $secretRootPath 'recovery-auth.key'
    $preKeyAssessment=$null

    # IMPORTANTE: capturar la ACL de una clave ya existente ANTES de normalizar Secrets.
    # Si la clave heredaba una ACE externa de solo lectura, endurecer primero el padre podria
    # borrar esa evidencia y hacer que una clave potencialmente expuesta pareciera siempre segura.
    if(Test-Path -LiteralPath $secretRootPath){
        $secretInfo=New-Object IO.DirectoryInfo($secretRootPath)
        $secretAssessment=Get-VSO7SecretAclAssessmentVSO -Info $secretInfo
        if($secretAssessment.IsReparse){throw 'The VSO7 secret directory is a reparse point and will not be modified.'}
        if(-not$secretAssessment.OwnerTrusted){throw 'The VSO7 secret directory has an untrusted owner and will not be modified.'}
        if($secretAssessment.ExternalModify){
            if($RequireExisting-or(Test-VSO7RecoveryAuthDependentMaterialVSO)){
                $rules=@($secretAssessment.ExternalRules|Where-Object{$_.ModifyCapable}|ForEach-Object{
                    '{0}: {1} (Inherited={2})'-f$_.Sid,$_.Rights,$_.Inherited
                })-join'; '
                throw ('Secrets grants external write access, and authenticated Recovery material or a pending operation requires the current key. Path: '+$secretRootPath+'. ACL: '+$rules+'. The existing state was preserved without changes.')
            }
            [void](Move-VSO7UntrustedSecretDirectoryAsideVSO -Path $secretRootPath -Assessment $secretAssessment)
            # The old key is never read or reused. Protect-VSO7SecretDirectoryVSO
            # below creates a fresh strict directory and a new HMAC identity.
        }else{
            [void](Assert-VSO7SecretAclSafeToNormalizeVSO -Info $secretInfo -Kind 'directory')
        }
        if((Test-Path -LiteralPath $secretRootPath)-and(Test-Path -LiteralPath $keyPath -PathType Leaf)){
            $preKeyInfo=New-Object IO.FileInfo($keyPath)
            $preKeyAssessment=Assert-VSO7SecretAclSafeToNormalizeVSO -Info $preKeyInfo -Kind 'recovery-auth.key'
        }elseif((Test-Path -LiteralPath $secretRootPath)-and(Test-Path -LiteralPath $keyPath)){
            throw 'The existing recovery-auth.key is not a regular file.'
        }
    }

    $secretRoot=Protect-VSO7SecretDirectoryVSO -Path $secretRootPath
    $script:RecoveryAuthKeyFile=$keyPath

    if(-not(Test-Path -LiteralPath $keyPath -PathType Leaf)){
        if($RequireExisting){throw 'The protected key that authenticates this computer''s Recovery bundles is missing.'}
        if(Test-VSO7RecoveryAuthDependentMaterialVSO){
            throw 'recovery-auth.key is missing, but Recovery data exists. VSO7 will not generate a new key; recover the original key or review the bundles manually.'
        }
        New-VSO7RecoveryAuthKeyFileVSO -SecretRoot $secretRoot -KeyPath $keyPath
    }else{
        $item=New-Object IO.FileInfo($keyPath)
        $currentAssessment=Assert-VSO7SecretAclSafeToNormalizeVSO -Info $item -Kind 'recovery-auth.key'
        $readExposure=[bool]($currentAssessment.ExternalRead-or($null-ne$preKeyAssessment-and$preKeyAssessment.ExternalRead))
        if($readExposure){
            if($RequireExisting-or(Test-VSO7RecoveryAuthDependentMaterialVSO)){
                throw 'A non-administrative identity could read recovery-auth.key, and dependent Recovery data exists or may exist. VSO7 will not rotate or use the key automatically.'
            }
            # La ACL del directorio ya esta endurecida; ahora rotamos la identidad HMAC mediante
            # reemplazo atomico en el mismo directorio, sin utilizar la clave potencialmente expuesta.
            New-VSO7RecoveryAuthKeyFileVSO -SecretRoot $secretRoot -KeyPath $keyPath -ReplaceExisting
            Write-VSO7Log 'recovery-auth.key had external read-only exposure with no dependent Recovery data; its ACL was restricted and the key was rotated.' 'WARN'
        }else{
            # Incluso sin exposicion externa, eliminar herencia residual y dejar la ACL final canonica.
            $item.SetAccessControl((New-VSO7SecretFileAclVSO))
            Assert-VSO7SecretAclVSO -Info $item
        }
    }

    $item=New-Object IO.FileInfo($keyPath)
    Assert-VSO7SecretAclVSO -Info $item
    if([int64]$item.Length-ne32){throw 'recovery-auth.key has an invalid size.'}
    $result=[IO.File]::ReadAllBytes($keyPath)
    if($result.Length-ne32){throw 'A valid Recovery authentication key could not be read.'}
    return $result

}

function Get-VSO7RecoveryOriginCanonicalVSO {

    param([Parameter(Mandatory=$true)]$Origin)
    $fields=@(
        [string]$Origin.Schema,[string]$Origin.Product,[string]$Origin.Version,[string]$Origin.RunnerSha256,
        ([string][bool]$Origin.StateExpectedExists),[string]$Origin.StateExpectedSha256,[string]$Origin.StateBundleSha256,
        ([string][bool]$Origin.ExtremeExpectedExists),[string]$Origin.ExtremeExpectedSha256,[string]$Origin.ExtremeBundleSha256,
        ([string][bool]$Origin.StartupExpectedExists),[string]$Origin.StartupExpectedSha256,[string]$Origin.StartupBundleSha256,
        [string]$Origin.UpdatedAt
    )
    return [string]::Join("`n",$fields)

}

function Get-VSO7RecoveryOriginHmacVSO {

    param([Parameter(Mandatory=$true)]$Origin)
    $key=Get-VSO7RecoveryAuthKeyVSO -RequireExisting
    $h=New-Object Security.Cryptography.HMACSHA256
    try{

        $h.Key=$key
        $bytes=(New-Object Text.UTF8Encoding($false)).GetBytes((Get-VSO7RecoveryOriginCanonicalVSO -Origin $Origin))
        return ([BitConverter]::ToString($h.ComputeHash($bytes))).Replace('-','').ToUpperInvariant()

    }finally{

        $h.Dispose()
        if($null-ne$key){
            [Array]::Clear($key,0,$key.Length)
        }

    }

}

function Test-VSO7FixedTimeHexEqualVSO {

    param([Parameter(Mandatory=$true)][string]$Left,[Parameter(Mandatory=$true)][string]$Right)
    if($Left.Length-ne$Right.Length){
        return $false
    }
    [int]$diff=0
    for($i=0;$i-lt$Left.Length;$i++){

        $diff=$diff-bor(([int][char]$Left[$i])-bxor([int][char]$Right[$i]))

    }
    return ($diff-eq0)

}

function Assert-VSO7RecoveryOriginAuthenticationVSO {

    param([Parameter(Mandatory=$true)]$Origin)
    $expected=Get-VSO7RecoveryOriginHmacVSO -Origin $Origin
    if(-not(Test-VSO7FixedTimeHexEqualVSO -Left $expected -Right ([string]$Origin.AuthHmacSha256))){
        throw 'origin.json no supera autenticacion HMAC de esta instalacion VSO7.'
    }
    return $true

}

function Test-VSO7RecoveryStagingHasRollbackEvidenceVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    try{

        $full=Assert-VSO7ManagedRecoveryBundleVSO -Path $Path
        if([IO.Path]::GetFileName($full)-notmatch'^RestoreStaging_[0-9a-fA-F]{32}$'){
            return $true
        }

        $normal=Join-Path $full 'state.json'
        if(Test-Path -LiteralPath $normal -PathType Leaf){

            $state=ConvertTo-VSO7ValidatedNormalState -Object (Get-Content -LiteralPath $normal -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
            if(@($state.Registry).Count-gt0-or-not[string]::IsNullOrWhiteSpace([string]$state.OriginalPowerScheme)-or-not[string]::IsNullOrWhiteSpace([string]$state.AppliedPowerScheme)-or-not[string]::IsNullOrWhiteSpace([string]$state.PendingPowerScheme)){
                return $true
            }

        }

        $extreme=Join-Path $full 'extreme-state.json'
        if(Test-Path -LiteralPath $extreme -PathType Leaf){

            $state=ConvertTo-VSO7ValidatedExtremeState -Object (Get-Content -LiteralPath $extreme -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
            if(@($state.Registry).Count-gt0-or@($state.Services).Count-gt0-or@($state.Features).Count-gt0-or@($state.PowerSettings).Count-gt0-or@($state.Bcd).Count-gt0-or$null-ne$state.Hibernation-or@($state.PendingTweaks).Count-gt0-or@($state.AppliedTweaks).Count-gt0){
                return $true
            }

        }

        $startup=Join-Path $full 'startup-state.json'
        if(Test-Path -LiteralPath $startup -PathType Leaf){

            $oldStartupFile=$script:StartupStateFile
            try{

                $script:StartupStateFile=$startup
                $state=ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $startup -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
                if(@($state.Disabled).Count-gt0){
                    return $true
                }

            }finally{
                $script:StartupStateFile=$oldStartupFile
            }

        }
        return $false

    }catch{

        Write-VSO7Log ("No se pudo demostrar que un RestoreStaging este vacio de rollback; se conserva: {0}"-f$_.Exception.Message) 'WARN'
        return $true

    }

}

function Invoke-VSO7ConservativeOrphanGarbageCollectionVSO {

    # Solo se invoca con el mutex global adquirido y despues de completar/rechazar
    # journals Recovery pendientes. Ante cualquier duda, conserva el artefacto.
    [int]$removed=0

    # Temporales de creacion de la clave HMAC. El directorio Secrets ya esta
    # protegido; con una sola instancia activa, cualquier nombre exacto restante
    # de una ejecucion anterior es huerfano.
    try{

        $secretRoot=Join-Path ([string]$script:SecureStateRoot) 'Secrets'
        if(Test-Path -LiteralPath $secretRoot -PathType Container){

            $secretRoot=Protect-VSO7SecretDirectoryVSO -Path $secretRoot
            foreach($file in @(Get-ChildItem -LiteralPath $secretRoot -File -Force -ErrorAction Stop|Where-Object{
                [string]$_.Name-match'^\.recovery-auth-[0-9a-fA-F]{32}\.tmp$'
            })){

                try{

                    $full=[IO.Path]::GetFullPath($file.FullName)
                    if([IO.Path]::GetDirectoryName($full)-ine[IO.Path]::GetFullPath($secretRoot).TrimEnd('\')){
                        throw 'Temporal secreto fuera de Secrets.'
                    }
                    if(($file.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                        throw 'Temporal secreto es reparse point.'
                    }
                    Remove-Item -LiteralPath $full -Force -ErrorAction Stop
                    $removed++

                }catch{
                    Write-VSO7Log ("No se pudo limpiar temporal HMAC huerfano; se conserva: {0}"-f$_.Exception.Message) 'WARN'
                }

            }

        }

    }catch{
        Write-VSO7Log ("GC de temporales HMAC omitido por seguridad: {0}"-f$_.Exception.Message) 'WARN'
    }

    # Backups Startup: solo se eliminan hijos directos con el patron aleatorio
    # generado por VSO7 y que NO aparecen en el startup-state.json protegido actual.
    try{

        $stash=Join-Path ([string]$script:SecureStateRoot) 'StartupDisabled'
        if(Test-Path -LiteralPath $stash -PathType Container){

            $stash=Protect-VSO7SecureDirectory -Path $stash
            $keep=@{}
            if(Test-Path -LiteralPath $script:StartupStateFile -PathType Leaf){

                $state=ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $script:StartupStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
                foreach($entry in @($state.Disabled|Where-Object{
                    [string]$_.Type-ieq'File'
                })){
                    $keep[([string]$entry.BackupName).ToLowerInvariant()]=$true
                }

            }
            foreach($file in @(Get-ChildItem -LiteralPath $stash -File -Force -ErrorAction Stop|Where-Object{
                [string]$_.Name-match'^[0-9a-fA-F]{32}_.+'
            })){

                if($keep.ContainsKey(([string]$file.Name).ToLowerInvariant())){
                    continue
                }
                try{

                    $safe=Assert-VSO7StartupPathRuntimeSafe -Path $file.FullName -AllowedParents @($stash)
                    $item=Get-Item -LiteralPath $safe -Force -ErrorAction Stop
                    if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                        throw 'Backup Startup huerfano invalido/reparse point.'
                    }
                    Remove-Item -LiteralPath $safe -Force -ErrorAction Stop
                    $removed++

                }catch{
                    Write-VSO7Log ("No se pudo limpiar backup Startup huerfano; se conserva: {0}"-f$_.Exception.Message) 'WARN'
                }

            }

        }

    }catch{
        Write-VSO7Log ("GC de StartupDisabled omitido por seguridad: {0}"-f$_.Exception.Message) 'WARN'
    }

    # RestoreStaging: no basta el nombre. Solo se borra si es hijo directo protegido,
    # no esta referenciado por un journal activo y sus estados validan SIN evidencia
    # residual de rollback. Los stagings parciales/ambiguos quedan intactos.
    try{

        $activeStage=$null
        $journal=Get-VSO7RecoveryReconcileJournalVSO
        if($null-ne$journal){
            $activeStage=[IO.Path]::GetFullPath([string]$journal.StagePath).TrimEnd('\')
        }
        foreach($dir in @(Get-ChildItem -LiteralPath $script:RecoveryRoot -Directory -Force -ErrorAction Stop|Where-Object{
            [string]$_.Name-match'^RestoreStaging_[0-9a-fA-F]{32}$'
        })){

            $full=[IO.Path]::GetFullPath($dir.FullName).TrimEnd('\')
            if(-not[string]::IsNullOrWhiteSpace($activeStage)-and$full-ieq$activeStage){
                continue
            }
            if(Test-VSO7RecoveryStagingHasRollbackEvidenceVSO -Path $full){
                continue
            }
            try{

                if(($dir.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                    throw 'RestoreStaging huerfano es reparse point.'
                }
                if([IO.Path]::GetDirectoryName($full)-ine[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')){
                    throw 'RestoreStaging huerfano fuera de RecoveryRoot.'
                }
                Assert-VSO7ExistingSecureDirectoryProvenance -Path $full
                Remove-Item -LiteralPath $full -Recurse -Force -ErrorAction Stop
                $removed++

            }catch{
                Write-VSO7Log ("No se pudo limpiar RestoreStaging huerfano; se conserva: {0}"-f$_.Exception.Message) 'WARN'
            }

        }

    }catch{
        Write-VSO7Log ("GC de RestoreStaging omitido por seguridad: {0}"-f$_.Exception.Message) 'WARN'
    }

    if($removed-gt0){
        Write-VSO7Log ("GC conservador VSO7 retiro {0} artefacto(s) huerfano(s) protegido(s)."-f$removed) 'CHANGE'
    }
    return $removed

}

function Resolve-VSO7VisibleOutputDirectoryVSO {

    param(
        [Parameter(Mandatory=$true)][string]$PrimaryPath,
        [Parameter(Mandatory=$true)][string]$FallbackPath,
        [Parameter(Mandatory=$true)][ValidateSet('Logs','Informes')][string]$Kind
    )
    $reason=$null
    try{

        $primary=[IO.Path]::GetFullPath($PrimaryPath).TrimEnd('\')
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $primary)
        $item=Get-Item -LiteralPath $primary -Force -ErrorAction Stop
        if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'la carpeta local no es un directorio normal.'
        }
        # CreateNew proves that the selected local output directory is writable. The probe is
        # random, non-executable and deleted immediately; it never changes Windows configuration.
        $probe=Join-Path $primary ('.vso7-write-probe-'+[guid]::NewGuid().ToString('N')+'.tmp')
        $stream=$null
        try{

            $stream=[IO.File]::Open($probe,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)

        }finally{
            if($null-ne$stream){$stream.Dispose()}
            if(Test-Path -LiteralPath $probe -PathType Leaf){
                Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue
            }
        }
        return [pscustomobject]@{Path=$primary;Fallback=$false;Reason=$null}

    }catch{
        $reason=[string]$_.Exception.Message
    }
    $fallback=Protect-VSO7SecureDirectory -Path $FallbackPath
    return [pscustomobject]@{Path=$fallback;Fallback=$true;Reason=$reason}

}

function Initialize-VSO7SecureStateStorage {

    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SECURE_PROGRAMDATA_VALIDATE'
    if([string]::IsNullOrWhiteSpace([string]$script:ProgramData)-or-not[IO.Path]::IsPathRooted([string]$script:ProgramData)){
        throw 'ProgramData confiable no esta inicializado.'
    }
    $programDataItem=Get-Item -LiteralPath $script:ProgramData -Force -ErrorAction Stop
    if(($programDataItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'ProgramData es un reparse point; VSO7 no persistira estado elevado.'
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SECURE_PROGRAMDATA_VALIDATE' -StartedMs $secureStage
    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SECURE_ROOT_DIRECTORY'
    $vendor=Protect-VSO7SecureDirectory -Path (Join-Path $script:ProgramData 'VicoreDevelopment')
    $secure=Protect-VSO7SecureDirectory -Path (Join-Path $vendor 'VSO7')
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SECURE_ROOT_DIRECTORY' -StartedMs $secureStage
    $script:SecureStateRoot=$secure

    # Config/Recovery y otros journals con ownership permanecen en ProgramData protegido.
    # Logs e Informes son artefactos visibles/portables: se guardan junto a VSO7 por defecto y
    # solo usan ProgramData como fallback cuando la carpeta local no puede demostrarse escribible.
    $legacyConfigRoot=[IO.Path]::GetFullPath([string]$script:ConfigRoot)
    $localLogRoot=[IO.Path]::GetFullPath([string]$script:LogRoot)
    $localReportRoot=[IO.Path]::GetFullPath([string]$script:ReportRoot)
    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SECURE_OUTPUT_RESOLVE'
    $script:ConfigRoot=Protect-VSO7SecureDirectory -Path (Join-Path $secure 'Config')
    $logChoice=Resolve-VSO7VisibleOutputDirectoryVSO -PrimaryPath $localLogRoot -FallbackPath (Join-Path $secure 'Logs') -Kind Logs
    $reportChoice=Resolve-VSO7VisibleOutputDirectoryVSO -PrimaryPath $localReportRoot -FallbackPath (Join-Path $secure 'Informes') -Kind Informes
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SECURE_OUTPUT_RESOLVE' -StartedMs $secureStage
    $script:LogRoot=[string]$logChoice.Path
    $script:ReportRoot=[string]$reportChoice.Path
    $script:LogStorageFallbackUsed=[bool]$logChoice.Fallback
    $script:ReportStorageFallbackUsed=[bool]$reportChoice.Fallback
    $script:LogStorageFallbackReason=[string]$logChoice.Reason
    $script:ReportStorageFallbackReason=[string]$reportChoice.Reason
    $script:GamingProfileRoot=Protect-VSO7SecureDirectory -Path (Join-Path $script:ConfigRoot 'GamingProfiles')
    $script:ToolsRoot=$secure
    $script:LanguageFile=Join-Path $script:ConfigRoot 'language.json'
    $script:CleanupHistoryFile=Join-Path $script:ConfigRoot 'cleanup-history.json'
    $script:ScoreHistoryFile=Join-Path $script:ConfigRoot 'score-history.json'
    $script:ProtectedProcessesFile=Join-Path $script:ConfigRoot 'protected-processes.json'
    $script:LastAppliedSelectionFile=Join-Path $script:ConfigRoot 'last-applied-selection.json'
    $stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
    $script:LogFile=Join-Path $script:LogRoot ("VSO7_{0}.log" -f $stamp)
    $script:TranscriptFile=Join-Path $script:LogRoot ("VSO7_TRANSCRIPT_{0}.log" -f $stamp)
    foreach($runtimeLeaf in @($script:LanguageFile,$script:CleanupHistoryFile,$script:ScoreHistoryFile,$script:ProtectedProcessesFile,$script:LastAppliedSelectionFile)){

        [void](Protect-VSO7ProtectedFileVSO -Path $runtimeLeaf -AllowedParent $script:ConfigRoot -AllowMissing)

    }

    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_RECOVERY_IDENTITY_AUTH_INIT'
    $script:RecoveryRoot=Protect-VSO7SecureDirectory -Path (Join-Path $secure 'Recovery')
    [void](Initialize-VSO7RecoveryRunnerIdentityVSO)
    if([string]::IsNullOrWhiteSpace($RestoreFromBundle)){
        [void](Get-VSO7RecoveryAuthKeyVSO)
    }else{
        [void](Get-VSO7RecoveryAuthKeyVSO -RequireExisting)
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_RECOVERY_IDENTITY_AUTH_INIT' -StartedMs $secureStage
    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PRESENTMON_STORAGE_INIT'
    $script:PresentMonRoot=Protect-VSO7SecureDirectory -Path (Join-Path $secure 'PresentMon')
    $script:PresentMonExe=Join-Path $script:PresentMonRoot 'PresentMon.exe'
    $script:PresentMonMetaFile=Join-Path $script:PresentMonRoot 'presentmon-meta.json'
    $script:BenchmarkRoot=Join-Path $script:ReportRoot 'Benchmarks'
    if(-not(Test-Path -LiteralPath $script:BenchmarkRoot)){[void](New-Item -ItemType Directory -Path $script:BenchmarkRoot -Force -ErrorAction Stop)}
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $script:BenchmarkRoot)
    [void](Protect-VSO7ProtectedFileVSO -Path $script:PresentMonExe -AllowedParent $script:PresentMonRoot -AllowMissing)
    [void](Protect-VSO7ProtectedFileVSO -Path $script:PresentMonMetaFile -AllowedParent $script:PresentMonRoot -AllowMissing)
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PRESENTMON_STORAGE_INIT' -StartedMs $secureStage

    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SECURE_STATE_MIGRATION_CHECKS'
    $legacyState=Join-Path $legacyConfigRoot 'state.json'
    $legacyExtreme=Join-Path $legacyConfigRoot 'extreme-state.json'
    $legacyStartup=Join-Path $legacyConfigRoot 'startup-state.json'
    $legacyGaming=Join-Path $legacyConfigRoot 'gaming-session-active.json'
    $secureState=Join-Path $secure 'state.json'
    $secureExtreme=Join-Path $secure 'extreme-state.json'
    $secureStartup=Join-Path $secure 'startup-state.json'
    $secureGaming=Join-Path $secure 'gaming-session-active.json'

    Assert-VSO7LegacyFixedStateSafeToIgnoreVSO -Kind Normal -LegacyPath $legacyState -SecurePath $secureState
    Assert-VSO7LegacyFixedStateSafeToIgnoreVSO -Kind Extreme -LegacyPath $legacyExtreme -SecurePath $secureExtreme

    if(-not(Test-Path -LiteralPath $secureStartup)-and(Test-Path -LiteralPath $legacyStartup -PathType Leaf)){

        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $legacyStartup)
        $legacyItem=Get-Item -LiteralPath $legacyStartup -Force -ErrorAction Stop
        if($legacyItem.PSIsContainer-or($legacyItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'startup-state.json legado es invalido/reparse point.'
        }
        if([int64]$legacyItem.Length-le0-or[int64]$legacyItem.Length-gt8388608){
            throw 'startup-state.json legado excede el tamano permitido para validacion segura.'
        }
        $oldStartupFile=$script:StartupStateFile
        try{

            $script:StartupStateFile=$legacyStartup
            $obj=Get-Content -LiteralPath $legacyStartup -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
            $validated=ConvertTo-VSO7ValidatedStartupState -Object $obj
            if(@($validated.Disabled).Count-gt0){
                throw 'Existe rollback Startup legado en almacenamiento no protegido. VSO7 7.0.0 lo conserva pero se niega a importarlo/ejecutarlo automaticamente; restaura primero con una copia confiable de 5.0.12 o revisalo manualmente.'
            }

        }finally{
            $script:StartupStateFile=$oldStartupFile
        }

    }
    if(-not(Test-Path -LiteralPath $secureGaming)-and(Test-Path -LiteralPath $legacyGaming -PathType Leaf)){

        throw 'Existe una sesion Gaming legada en almacenamiento no protegido. VSO7 7.0.0 se detiene sin ejecutarla para no confiar en estado dinamico no autenticado.'

    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SECURE_STATE_MIGRATION_CHECKS' -StartedMs $secureStage

    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SECURE_STATE_LEAF_PROTECT'
    $script:StateFile=$secureState
    $script:ExtremeStateFile=$secureExtreme
    $script:StartupStateFile=$secureStartup
    $script:GamingSessionStateFile=$secureGaming
    foreach($leaf in @($secureState,$secureExtreme,$secureStartup,$secureGaming)){
        [void](Protect-VSO7SecureStateLeaf -Path $leaf -AllowMissing)
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SECURE_STATE_LEAF_PROTECT' -StartedMs $secureStage
    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_RECOVERY_JOURNAL_RECONCILE'
    $reconcilePending=Test-Path -LiteralPath (Get-VSO7RecoveryReconcileJournalPathVSO) -PathType Leaf
    $publishPending=Test-Path -LiteralPath (Get-VSO7RecoveryPublishJournalPathVSO) -PathType Leaf
    if($reconcilePending-and$publishPending){
        throw 'Existen simultaneamente journals Recovery de reconciliacion y publicacion; VSO7 falla cerrado para no adivinar el orden de dos transacciones interrumpidas.'
    }
    if($reconcilePending){

        if(-not(Complete-VSO7PendingRecoveryReconcileVSO)){
            throw 'Existe una reconciliacion Recovery interrumpida que no pudo completarse de forma segura. VSO7 se bloquea para no operar sobre estados parcialmente sincronizados.'
        }

    }
    if($publishPending){

        if(-not(Complete-VSO7PendingRecoveryPublishVSO)){
            throw 'Existe una publicacion Recovery interrumpida que no pudo completarse de forma segura. VSO7 se bloquea hasta reconciliar el bundle con el estado protegido.'
        }

    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_RECOVERY_JOURNAL_RECONCILE' -StartedMs $secureStage
    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ORPHAN_GC'
    $stash=Join-Path $secure 'StartupDisabled'
    if(Test-Path -LiteralPath $stash){
        [void](Protect-VSO7SecureDirectory -Path $stash)
    }
    [void](Invoke-VSO7ConservativeOrphanGarbageCollectionVSO)
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ORPHAN_GC' -StartedMs $secureStage

    $secureStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_RECOVERY_RUNNER_SETUP'
    if([string]::IsNullOrWhiteSpace($RestoreFromBundle)){

        [void](Install-VSO7ProtectedRecoveryRunnerVSO)

    }else{

        Assert-VSO7RecoveryExecutionTrustVSO

    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_RECOVERY_RUNNER_SETUP' -StartedMs $secureStage

}

function Test-IsWindows {

    return ($env:OS -eq 'Windows_NT')

}

function Test-IsAdministrator {

    $identity=$null
    try {

        $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
        $principal = New-Object Security.Principal.WindowsPrincipal($identity)
        return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

    } catch {

        return $false

    } finally {

        if($null-ne$identity){
            try{
                $identity.Dispose()
            }catch{}
        }

    }

}

function Test-IsWindowsPowerShell51 {

    try {

        return ($PSVersionTable.PSEdition -eq 'Desktop' -and ([version]$PSVersionTable.PSVersion) -ge ([version]'5.1'))

    } catch {
        return $false
    }

}

function Quote-VSOArg {

    param([string]$Value)
    return (ConvertTo-VSOCommandLineArgBootstrap -Value $Value)

}

function Remove-OrganizationSourceIfSafe {

    if ([string]::IsNullOrWhiteSpace([string]$CleanupSource)) {
        return
    }
    if ([string]::IsNullOrWhiteSpace([string]$script:ScriptPath)) {
        return
    }
    try {

        $src=[IO.Path]::GetFullPath([string]$CleanupSource)
        $dst=[IO.Path]::GetFullPath([string]$script:ScriptPath)
        if ($src -ieq $dst -or -not(Test-Path -LiteralPath $src -PathType Leaf)) {
            return
        }
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $src)
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $dst)
        $same=((Get-FileHash -LiteralPath $src -Algorithm SHA256 -ErrorAction Stop).Hash -ceq (Get-FileHash -LiteralPath $dst -Algorithm SHA256 -ErrorAction Stop).Hash)
        if (-not $same) {

            Write-VSOHost 'No se borro el archivo original porque no coincide con la copia organizada.' -ForegroundColor Yellow
            return

        }
        for($i=0;$i-lt20;$i++){

            try{
                Remove-Item -LiteralPath $src -Force -ErrorAction Stop;
                return
            }catch{
                Start-Sleep -Milliseconds 250
            }

        }
        Write-VSO7Log ("No se pudo retirar el VSO7.ps1 original tras organizarlo: {0}" -f $src) 'WARN'

    } catch {

        Write-VSO7Log ("No se pudo limpiar el VSO7.ps1 original tras organizarlo: {0}" -f $_.Exception.Message) 'WARN'

    }

}

function Initialize-VSO7LocalFolders {

    $root=[IO.Path]::GetFullPath([string]$script:Root)
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $root)
    foreach($name in @('Config','Logs','Informes','Recuperacion')){

        $path=Join-Path $root $name
        if(Test-Path -LiteralPath $path){

            $item=Get-Item -LiteralPath $path -Force -ErrorAction Stop
            if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ("{0} no es una carpeta local normal."-f$path)
            }

        }else{
            New-Item -ItemType Directory -Path $path -ErrorAction Stop|Out-Null
        }

    }
    $script:RecoveryRoot=Join-Path $root 'Recuperacion';
    $script:LogRoot=Join-Path $root 'Logs';
    $script:ReportRoot=Join-Path $root 'Informes';
    $script:ConfigRoot=Join-Path $root 'Config';
    $script:DataRoot=$script:ConfigRoot
    $script:LanguageFile=Join-Path $script:ConfigRoot 'language.json'

}

function Test-VSO7TreeHasReparsePointVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    if(-not(Test-Path -LiteralPath $Path)){
        return $false
    }
    $root=Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if(($root.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        return $true
    }
    if(-not$root.PSIsContainer){
        return $false
    }
    foreach($item in @(Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction Stop)){

        if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            return $true
        }

    }
    return $false

}

function Copy-VSO7PackageDirectoryVSO {

    param([Parameter(Mandatory=$true)][string]$Source,[Parameter(Mandatory=$true)][string]$Destination)
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $Source)
    if(Test-VSO7TreeHasReparsePointVSO -Path $Source){
        throw ("El directorio de paquete contiene reparse points: {0}"-f$Source)
    }
    $parent=Split-Path -Parent $Destination
    $leaf=Split-Path -Leaf $Destination
    $temp=Join-Path $parent ('.VSO7.package.'+$leaf+'.'+[guid]::NewGuid().ToString('N'))
    $backup=$null
    try{

        Copy-Item -LiteralPath $Source -Destination $temp -Recurse -Force -ErrorAction Stop
        if(Test-VSO7TreeHasReparsePointVSO -Path $temp){
            throw ("La copia temporal del paquete contiene reparse points: {0}"-f$temp)
        }
        if(Test-Path -LiteralPath $Destination){

            $destItem=Get-Item -LiteralPath $Destination -Force -ErrorAction Stop
            if(-not$destItem.PSIsContainer-or($destItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ("Destino de paquete invalido: {0}"-f$Destination)
            }
            $backup=Join-Path $parent ('.VSO7.previous.'+$leaf+'.'+[guid]::NewGuid().ToString('N'))
            Move-Item -LiteralPath $Destination -Destination $backup -ErrorAction Stop

        }
        Move-Item -LiteralPath $temp -Destination $Destination -ErrorAction Stop
        $temp=$null
        if(-not[string]::IsNullOrWhiteSpace([string]$backup)-and(Test-Path -LiteralPath $backup)){

            if(Test-VSO7TreeHasReparsePointVSO -Path $backup){

                Write-VSO7Log ("No se elimina el directorio de paquete anterior porque contiene un reparse point: {0}"-f$backup) 'WARN'

            }else{
                Remove-Item -LiteralPath $backup -Recurse -Force -ErrorAction Stop;
                $backup=$null
            }

        }

    }catch{

        if(-not[string]::IsNullOrWhiteSpace([string]$temp)-and(Test-Path -LiteralPath $temp)){
            try{
                if(-not(Test-VSO7TreeHasReparsePointVSO -Path $temp)){
                    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction Stop
                }
            }catch{}
        }
        if(-not[string]::IsNullOrWhiteSpace([string]$backup)-and(Test-Path -LiteralPath $backup)-and-not(Test-Path -LiteralPath $Destination)){

            try{
                Move-Item -LiteralPath $backup -Destination $Destination -ErrorAction Stop;
                $backup=$null
            }catch{}

        }
        throw

    }

}

function Copy-VSO7PackageResourcesVSO {

    param([Parameter(Mandatory=$true)][string]$SourceRoot,[Parameter(Mandatory=$true)][string]$TargetRoot)
    $allow=@('Resources','Tools','VSO7_7.0.0_RC_R80.ps1','START VSO7.bat','UNBLOCK VSO7.bat','INICIAR VSO7.vbs','INICIAR VSO7 CONSOLA.cmd','COMPROBAR VSO7.cmd','DESBLOQUEAR VSO7.bat','README.md','CHANGELOG.md','RC_STATUS.txt','LICENSE.txt','LICENSE.Win11Debloat.txt','THIRD_PARTY_NOTICES.md','SHA256SUMS.txt','SHA256.txt','RELEASE_SHA256_MANIFEST.txt','VSO7_AUDIT_7.0.0_RC_R80.json')
    foreach($name in $allow){

        $src=Join-Path $SourceRoot $name
        if(-not(Test-Path -LiteralPath $src)){
            continue
        }
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $src)
        $dst=Join-Path $TargetRoot $name
        $srcItem=Get-Item -LiteralPath $src -Force -ErrorAction Stop
        if($srcItem.PSIsContainer){
            Copy-VSO7PackageDirectoryVSO -Source $src -Destination $dst
        }
        else{

            if(Test-Path -LiteralPath $dst){
                $dstItem=Get-Item -LiteralPath $dst -Force -ErrorAction Stop;
                if($dstItem.PSIsContainer-or($dstItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                    throw ("Destino de archivo de paquete invalido: {0}"-f$dst)
                }
            }
            Copy-Item -LiteralPath $src -Destination $dst -Force -ErrorAction Stop

        }

    }

}

function Invoke-FirstRunOrganization {

    if ($SkipOrganize -or -not [string]::IsNullOrWhiteSpace([string]$RestoreFromBundle)) {
        return $false
    }
    if ([string]::IsNullOrWhiteSpace([string]$script:ScriptPath)) {
        return $false
    }

    $source=[IO.Path]::GetFullPath([string]$script:ScriptPath)
    $here=[IO.Path]::GetDirectoryName($source)
    if ([string]::IsNullOrWhiteSpace($here)) {
        return $false
    }
    if ((Split-Path -Leaf $here) -ieq 'VSO7') {
        return $false
    }

    $preferenceFile=Join-Path (Join-Path $here 'Config') 'organization.json'
    try {

        if (Test-Path -LiteralPath $preferenceFile -PathType Leaf) {

            $saved=Get-Content -LiteralPath $preferenceFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
            if (-not[string]::IsNullOrWhiteSpace([string]$saved.SkippedPath)) {

                $savedPath=[IO.Path]::GetFullPath([string]$saved.SkippedPath).TrimEnd('\')
                if ($savedPath -ieq [IO.Path]::GetFullPath($here).TrimEnd('\')) {
                    return $false
                }

            }

        }

    } catch {}

    if($script:GuiRequested){
        # R52 GUI first-run uses a dedicated responsive WPF choice dialog. It does
        # not route through Read-Host/Show-VSO7GuiPromptVSO and never exposes CLI
        # tokens such as [S/N]. The decision semantics remain unchanged.
        while($true){
            $guiOrganizationChoice=Show-VSO7FirstRunOrganizationDialogVSO -CurrentRoot $here
            if($guiOrganizationChoice-eq'Organize'){
                break
            }
            if($guiOrganizationChoice-eq'KeepHere'){
                $guiKeepChoice=Show-VSO7FirstRunKeepConfirmationVSO -CurrentRoot $here
                if($guiKeepChoice-eq'Back'){
                    continue
                }
                if($guiKeepChoice-eq'KeepHere'){
                    $script:Root=$here
                    Initialize-VSO7LocalFolders
                    Save-VSOLanguagePreference
                    try{
                        $preferenceFile=Join-Path $script:ConfigRoot 'organization.json'
                        $tmp=$preferenceFile+'.tmp.'+[guid]::NewGuid().ToString('N')
                        [pscustomobject]@{
                            SkippedPath=[IO.Path]::GetFullPath($here)
                            UpdatedAt=(Get-Date).ToString('o')
                        }|ConvertTo-Json|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
                        Move-Item -LiteralPath $tmp -Destination $preferenceFile -Force -ErrorAction Stop
                    }catch{}
                    return $false
                }
            }
        }
    }else{
        Clear-Host
        Write-VSOHost ''
        Write-CenteredLineVSO -Text ('╔' + ('═' * 70) + '╗') -Color $script:ThemeBorder
        Write-CenteredLineVSO -Text 'PRIMER INICIO DE VSO7' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text ('╚' + ('═' * 70) + '╝') -Color $script:ThemeBorder
        Write-VSOHost ''
        Write-CenteredLineVSO -Text 'VSO7 necesita una ubicacion estable para sus recursos, informes y recuperacion.' -Color $script:ThemeText
        Write-CenteredLineVSO -Text 'La opcion recomendada crea una carpeta VSO7 y coloca dentro el script y sus recursos.' -Color $script:ThemeText
        Write-VSOHost ''
        Write-CenteredLineVSO -Text 'Si eliges NO, VSO7 permanecera aqui y creara igualmente:' -Color $script:ThemeWarning
        Write-CenteredLineVSO -Text 'Config  |  Logs  |  Informes  |  Recuperacion' -Color $script:ThemeCream
        Write-CenteredLineVSO -Text 'No se desactiva ninguna funcion por rechazar el traslado.' -Color $script:ThemeText
        Write-VSOHost ''
        Write-CenteredLineVSO -Text 'Ubicacion recomendada:' -Color $script:ThemeSuccess
        Write-CenteredLineVSO -Text (("{0}\VSO7\VSO7.ps1" -f $here)) -Color $script:ThemeCream
        Write-VSOHost ''

        while($true){
            $answer=Read-CenteredPromptVSO -Text '¿Crear la carpeta VSO7, copiar el paquete dentro y relanzarlo? [S/N]'
            if($answer-match'^[sSyY]$'){
                break
            }
            if($answer-notmatch'^[nN]$'){
                Write-CenteredLineVSO -Text 'Opcion no valida.' -Color $script:ThemeDanger
                continue
            }
            Write-VSOHost ''
            Write-CenteredLineVSO -Text 'VSO7 permanecera en la ubicacion actual y creara aqui sus carpetas base.' -Color $script:ThemeWarning
            Write-CenteredLineVSO -Text ([IO.Path]::GetFullPath($here)) -Color $script:ThemeCream
            Write-CenteredLineVSO -Text 'Esto puede mezclar los archivos de VSO7 con otros archivos de esa carpeta.' -Color $script:ThemeText
            Write-VSOHost ''
            while($true){
                $confirm=Read-CenteredPromptVSO -Text '¿Estas seguro de que quieres continuar sin mover VSO7? [S/N]'
                if($confirm-match'^[sSyY]$'){
                    $script:Root=$here
                    Initialize-VSO7LocalFolders
                    Save-VSOLanguagePreference
                    try{
                        $preferenceFile=Join-Path $script:ConfigRoot 'organization.json'
                        $tmp=$preferenceFile+'.tmp.'+[guid]::NewGuid().ToString('N')
                        [pscustomobject]@{
                            SkippedPath=[IO.Path]::GetFullPath($here)
                            UpdatedAt=(Get-Date).ToString('o')
                        }|ConvertTo-Json|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
                        Move-Item -LiteralPath $tmp -Destination $preferenceFile -Force -ErrorAction Stop
                    }catch{}
                    return $false
                }
                if($confirm-match'^[nN]$'){
                    Write-VSOHost ''
                    break
                }
                Write-CenteredLineVSO -Text 'Opcion no valida.' -Color $script:ThemeDanger
            }
        }
    }

    $mutexReleased=$false
    try{

        $targetDir=Join-Path $here 'VSO7'
        if(Test-Path -LiteralPath $targetDir){
            $targetItem=Get-Item -LiteralPath $targetDir -Force -ErrorAction Stop;
            if(-not$targetItem.PSIsContainer-or($targetItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw 'La ruta VSO7 existente no es un directorio normal.'
            }
        }else{
            New-Item -ItemType Directory -Path $targetDir -ErrorAction Stop|Out-Null
        }
        $targetDir=[IO.Path]::GetFullPath($targetDir);
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $targetDir)
        $targetScript=Join-Path $targetDir 'VSO7.ps1'
        if(Test-Path -LiteralPath $targetScript -PathType Leaf){

            $same=((Get-FileHash -LiteralPath $targetScript -Algorithm SHA256 -ErrorAction Stop).Hash-ceq(Get-FileHash -LiteralPath $source -Algorithm SHA256 -ErrorAction Stop).Hash)
            if(-not$same){
                if($script:GuiRequested){
                    $replaceChoice=Show-VSO7FirstRunReplaceConfirmationVSO -TargetPath $targetScript
                    if($replaceChoice-ne'Replace'){ return $false }
                }else{
                    Write-CenteredLineVSO -Text 'Ya existe VSO7\VSO7.ps1 y es diferente.' -Color $script:ThemeWarning
                    $replace=Read-CenteredPromptVSO -Text '¿Reemplazar el VSO7 existente? [S/N]'
                    if($replace-notmatch'^[sSyY]$'){ return $false }
                }
            }

        }
        # No copiamos/re-ejecutamos silenciosamente un VSO7.ps1 que haya cambiado en disco
        # desde que PowerShell cargo esta sesion. El contenido en memoria es nuestra referencia.
        $sourceText=[IO.File]::ReadAllText($source)
        if($sourceText-cne[string]$script:BootstrapLoadedScriptContents){
            throw 'VSO7.ps1 cambio en disco durante la sesion; no se organizara ni se ejecutara esa copia.'
        }
        $temp=Join-Path $targetDir ('.VSO7.organize.'+[guid]::NewGuid().ToString('N')+'.tmp')
        try{
            Copy-Item -LiteralPath $source -Destination $temp -Force -ErrorAction Stop;
            if((Get-FileHash $temp -Algorithm SHA256).Hash-cne(Get-FileHash $source -Algorithm SHA256).Hash){
                throw 'La copia de VSO7.ps1 no coincide con el origen.'
            };
            Move-Item -LiteralPath $temp -Destination $targetScript -Force -ErrorAction Stop
        }finally{
            if(Test-Path $temp){
                Remove-Item $temp -Force -ErrorAction SilentlyContinue
            }
        }
        Copy-VSO7PackageResourcesVSO -SourceRoot $here -TargetRoot $targetDir
        try{
            Unblock-File -LiteralPath $targetScript -ErrorAction SilentlyContinue
        }catch{}

        $exe=Join-Path $script:SystemDirectory 'WindowsPowerShell\v1.0\powershell.exe'
        $sid=[string](Get-VSO7CurrentUserSidVSO).Value
        # El hijo se inicia mientras este proceso conserva el mutex. Como relevo interno, espera
        # en Enter-VSO7SingleInstance; el bloqueo solo se libera cuando el nuevo host ya arrancó.
        $childStarted=Start-VSOTrustedMemoryHostBootstrap -PowerShellExe $exe -LoadedScriptText ([string]$script:BootstrapLoadedScriptContents) -OriginalSourcePath $targetScript -ExpectedUserSid $sid -SkipOrganize -CleanupSource $source -Language ([string]$script:Language) -DirectAction ([string]$DirectAction) -StartupProbe ([string]$StartupProbe) -ProbeArtifactRoot ([string]$VSOProbeArtifactRoot) -ProbeOwnerToken ([string]$VSOProbeOwnerToken) -ProbeMutexName ([string]$VSOProbeMutexName) -InternalHandoff
        if(-not[bool]$childStarted){
            throw 'Windows no confirmó el relanzamiento de VSO7 desde su carpeta organizada.'
        }
        Exit-VSO7SingleInstance;
        $mutexReleased=$true
        return $true

    }catch{

        if($mutexReleased-and$null-eq$script:InstanceMutex){
            [void](Enter-VSO7SingleInstance)
        }
        Write-CenteredLineVSO -Text ((Convert-VSOText -Value $(Get-VSO7ConsoleTextVSO -Es 'No se pudo organizar automaticamente:' -En 'Could not organize VSO7 automatically:'))+' '+[string]$_.Exception.Message) -Color $script:ThemeDanger
        Write-CenteredLineVSO -Text 'VSO7 continuara desde la ubicacion actual.' -Color $script:ThemeWarning
        $script:Root=$here;
        Initialize-VSO7LocalFolders;
        Pause-Vico

    }
    return $false

}

function Ensure-CompatibleShellAndAdministrator {

    $isAdmin = Test-IsAdministrator
    $is51 = Test-IsWindowsPowerShell51
    $hasNoProfile = $false
    foreach ($argument in [Environment]::GetCommandLineArgs()) {

        if ([string]$argument -ieq '-NoProfile') {
            $hasNoProfile = $true;
            break
        }

    }
    $activeModulePath = [Environment]::GetEnvironmentVariable('PSModulePath','Process')
    $nativeBitness=(-not[Environment]::Is64BitOperatingSystem-or[Environment]::Is64BitProcess)
    if (-not $VSOTrustedHost -or -not $isAdmin -or -not $is51 -or -not $hasNoProfile -or -not$nativeBitness) {

        throw 'El bootstrap protegido no pudo confirmar Windows PowerShell 5.1 elevado, sin perfiles y con arquitectura nativa.'

    }
    if ([string]::IsNullOrWhiteSpace($script:TrustedSystemModulesRoot) -or $activeModulePath -ine $script:TrustedSystemModulesRoot) {

        throw 'PSModulePath dejo de coincidir con la unica raiz de modulos integrada permitida.'

    }

}

function Initialize-VSO7LifecycleDiagnosticsVSO {

    if(-not($script:GuiRequested -or [string]$StartupProbe -like 'GUI*')){
        return
    }
    $script:LifecycleStopwatch=[Diagnostics.Stopwatch]::StartNew()

    # Probe ownership is explicit-only. The same validated root/token/mutex tuple is carried
    # through every trusted-memory handoff; lifecycle diagnostics never recover ownership
    # from ambient environment variables.
    $probeRootCandidate=[string]$VSOProbeArtifactRoot
    $probeTokenCandidate=[string]$VSOProbeOwnerToken
    if([string]$StartupProbe -like 'GUI*'){
        if([string]::IsNullOrWhiteSpace($probeRootCandidate)){throw 'GUI startup probe lost VSOProbeArtifactRoot before lifecycle initialization.'}
        if([string]::IsNullOrWhiteSpace($probeTokenCandidate)-or$probeTokenCandidate-notmatch'^[A-Fa-f0-9]{32}$'){throw 'GUI startup probe lost or corrupted VSOProbeOwnerToken before lifecycle initialization.'}
    }
    $token=if(-not[string]::IsNullOrWhiteSpace($probeTokenCandidate)-and$probeTokenCandidate-match'^[A-Fa-f0-9]{32}$'){
        $probeTokenCandidate
    }else{
        [guid]::NewGuid().ToString('N')
    }
    $root=$null
    if(-not[string]::IsNullOrWhiteSpace($probeRootCandidate)){
        $root=[IO.Path]::GetFullPath($probeRootCandidate)
        $temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')+'\'
        if(-not($root.TrimEnd('\')+'\').StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)){
            throw 'Lifecycle probe solo puede escribir checkpoints dentro de TEMP.'
        }
        if(-not[IO.Directory]::Exists($root)){
            throw 'No existe la carpeta temporal del lifecycle probe.'
        }
        $rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop
        if(-not$rootItem.PSIsContainer-or($rootItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'La carpeta de lifecycle probe es invalida o reparse point.'
        }
    }else{
        $root=[IO.Path]::GetFullPath([IO.Path]::GetTempPath())
    }
    $script:LifecycleCheckpointOwner=$token
    $script:LifecycleCheckpointFile=Join-Path $root ('VSO7_R80_LIFECYCLE_{0}_PID{1}.log'-f$token,$PID)
    if($null-eq$script:ProcessParentPid){$script:ProcessParentPid=-1;try{$ci=CimCmdlets\Get-CimInstance Win32_Process -Filter ("ProcessId={0}"-f$PID) -ErrorAction Stop;$script:ProcessParentPid=[int]$ci.ParentProcessId}catch{}}
    $header='[{0}] PID={1} PPID={2} TID={3} MonoMs={4} Apartment={5} Action={6} Probe={7} CHECKPOINT_FILE_READY'-f(
        (Get-Date).ToString('o'),$PID,$script:ProcessParentPid,[Threading.Thread]::CurrentThread.ManagedThreadId,
        [int64]$script:LifecycleStopwatch.ElapsedMilliseconds,[Threading.Thread]::CurrentThread.ApartmentState,[string]$DirectAction,[string]$StartupProbe
    )
    try{
        [IO.File]::WriteAllText([string]$script:LifecycleCheckpointFile,$header+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))
    }catch{
        if([string]$StartupProbe -like 'GUI*'){
            throw ('No se pudo crear el archivo independiente de checkpoints lifecycle: {0}'-f$_.Exception.Message)
        }
        $script:LifecycleCheckpointFile=$null
    }

}

function Write-VSO7LifecycleCheckpointVSO {
    param(
        [Parameter(Mandatory=$true)][ValidatePattern('^[A-Z0-9_]+$')][string]$Name,
        [AllowNull()][string]$Detail
    )
    $path=[string]$script:LifecycleCheckpointFile
    if([string]::IsNullOrWhiteSpace($path)){return}
    if($null-eq$script:ProcessParentPid){
        $script:ProcessParentPid=-1
        try{$ci=CimCmdlets\Get-CimInstance Win32_Process -Filter ("ProcessId={0}"-f$PID) -ErrorAction Stop;$script:ProcessParentPid=[int]$ci.ParentProcessId}catch{}
    }
    $mutexHeld=($null-ne$script:InstanceMutex)
    $transcript=[bool]$script:TranscriptActive
    $suffix=if([string]::IsNullOrWhiteSpace([string]$Detail)){''}else{' Detail='+([string]$Detail -replace '[\r\n]+',' ')}
    $monoMs=if($null-ne$script:LifecycleStopwatch){[int64]$script:LifecycleStopwatch.ElapsedMilliseconds}else{-1}
    $line='[{0}] PID={1} PPID={2} TID={3} MonoMs={4} Mutex={5} Transcript={6} {7}{8}'-f((Get-Date).ToString('o'),$PID,$script:ProcessParentPid,[Threading.Thread]::CurrentThread.ManagedThreadId,$monoMs,$mutexHeld,$transcript,$Name,$suffix)
    try{[IO.File]::AppendAllText($path,$line+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}catch{
        $script:LifecycleCheckpointWriteError=[string]$_.Exception.Message
        try{[Console]::Error.WriteLine(('VSO7 lifecycle checkpoint failure ({0}): {1}'-f$Name,$_.Exception.Message))}catch{}
    }
}

function Start-VSO7LifecycleStageVSO {

    param(
        [Parameter(Mandatory=$true)][ValidatePattern('^BEFORE_[A-Z0-9_]+$')][string]$BeforeName,
        [AllowNull()][string]$Detail
    )
    Write-VSO7LifecycleCheckpointVSO -Name $BeforeName -Detail $Detail
    if($null-ne$script:LifecycleStopwatch){ return [int64]$script:LifecycleStopwatch.ElapsedMilliseconds }
    return [int64]-1

}

function Complete-VSO7LifecycleStageVSO {

    param(
        [Parameter(Mandatory=$true)][ValidatePattern('^AFTER_[A-Z0-9_]+$')][string]$AfterName,
        [Parameter(Mandatory=$true)][int64]$StartedMs,
        [AllowNull()][string]$Detail
    )
    $duration=-1
    if($StartedMs-ge0-and$null-ne$script:LifecycleStopwatch){
        $duration=[math]::Max([int64]0,([int64]$script:LifecycleStopwatch.ElapsedMilliseconds-$StartedMs))
    }
    $durationDetail='DurationMs='+[string]$duration
    if(-not[string]::IsNullOrWhiteSpace([string]$Detail)){ $durationDetail+=';'+[string]$Detail }
    Write-VSO7LifecycleCheckpointVSO -Name $AfterName -Detail $durationDetail
    if($script:GuiRequested-or[string]$StartupProbe-like'GUI*'){
        try{Write-VSO7GuiPerformanceEventVSO -Name ('STARTUP_'+$AfterName.Substring(6)) -NavigationTarget '' -Detail ('DurationMs='+[string]$duration)}catch{}
    }

}

function New-VSO7LifecycleCallbackWriterVSO {
    $writer=[Action[string,string]]{
        param([string]$Name,[string]$Detail)
        try{Write-VSO7LifecycleCheckpointVSO -Name $Name -Detail $Detail}catch{try{[Console]::Error.WriteLine(('VSO7 lifecycle callback checkpoint failed ({0}): {1}'-f$Name,$_.Exception.Message))}catch{}}
    }
    return $writer
}

function Invoke-VSO7FinalGuiResourceCleanupVSO {

    # Show-VSO7Gui desregistra sus handlers locales en su propio finally. Este cleanup global
    # solo rompe referencias de script; no vuelve a entrar en ShowDialog ni espera al Dispatcher.
    $script:GuiMode=$false
    $script:GuiWindow=$null
    $script:GuiOutput=$null
    $script:GuiOutputParagraph=$null
    $script:GuiHomeView=$null
    $script:GuiActionView=$null
    $script:GuiActionTitle=$null
    $script:GuiLifecycleHandlers=$null
    $script:GuiLifecycleDispatcher=$null
    $script:GuiPageCache=@{};$script:GuiPageContexts=@{};$script:GuiFeaturePageContexts=@{};$script:GuiApplicationsPageContext=$null;$script:GuiRecoveryPageContext=$null;$script:GuiLastBuiltPage=$null;$script:GuiHomeBuilt=$false

}

function Start-VSO7TranscriptVSO {

    if([bool]$script:ProbeSuppressTranscript){
        $script:TranscriptActive=$false
        Write-VSO7LifecycleCheckpointVSO -Name 'TRANSCRIPT_SUPPRESSED_FOR_AB_PROBE'
        return
    }
    if([bool]$script:TranscriptActive){
        return
    }
    if([string]::IsNullOrWhiteSpace([string]$script:TranscriptFile)){
        return
    }
    try{
        Start-Transcript -Path $script:TranscriptFile -Append -ErrorAction Stop | Out-Null
        $script:TranscriptActive=$true
    }catch{
        $script:TranscriptActive=$false
        try{
            Write-VSO7Log ("No se pudo iniciar transcript: {0}"-f$_.Exception.Message) 'WARN'
        }catch{
            [Console]::Error.WriteLine(('VSO7 no pudo iniciar transcript: {0}'-f$_.Exception.Message))
        }
    }

}

function Stop-VSO7TranscriptVSO {

    Write-VSO7LifecycleCheckpointVSO -Name 'BEFORE_STOP_TRANSCRIPT' -Detail $(if([bool]$script:TranscriptActive){'active'}else{'inactive'})
    if(-not[bool]$script:TranscriptActive){
        Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_STOP_TRANSCRIPT' -Detail 'inactive-noop'
        return
    }
    $stopError=$null
    try{
        if([bool]$script:ProbeForceStopTranscriptFailure){
            throw 'R44 synthetic Stop-Transcript failure requested by lifecycle probe.'
        }
        Stop-Transcript -ErrorAction Stop | Out-Null
    }catch{
        $stopError=$_
    }finally{
        $script:TranscriptActive=$false
    }
    if($null-ne$stopError){
        try{
            [Console]::Error.WriteLine(('VSO7 no pudo cerrar limpiamente el transcript: {0}'-f$stopError.Exception.Message))
        }catch{
            # No se relanza: el mutex ya debe haberse liberado antes de esta fase.
        }
        Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_STOP_TRANSCRIPT' -Detail ('error='+$stopError.Exception.Message)
        return
    }
    Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_STOP_TRANSCRIPT' -Detail 'ok'

}

function Initialize-VSO7FullStartupProbeArtifactsVSO {

    if(-not[bool]$script:FullGuiStartupProbe){ return $null }
    if([string]::IsNullOrWhiteSpace([string]$VSOProbeArtifactRoot)){ throw 'FULL STARTUP PROBE requiere VSOProbeArtifactRoot.' }
    if([string]::IsNullOrWhiteSpace([string]$VSOProbeOwnerToken)-or[string]$VSOProbeOwnerToken-notmatch'^[A-Fa-f0-9]{32}$'){
        throw 'FULL STARTUP PROBE recibio un owner token invalido.'
    }
    $root=[IO.Path]::GetFullPath([string]$VSOProbeArtifactRoot)
    $tempRoot=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')+'\'
    if(-not($root.TrimEnd('\')+'\').StartsWith($tempRoot,[StringComparison]::OrdinalIgnoreCase)){
        throw 'FULL STARTUP PROBE solo puede escribir artefactos dentro de TEMP.'
    }
    if(-not[IO.Directory]::Exists($root)){ throw 'No existe la carpeta temporal del FULL STARTUP PROBE.' }
    $item=Get-Item -LiteralPath $root -Force -ErrorAction Stop
    if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){ throw 'La carpeta del FULL STARTUP PROBE es invalida/reparse point.' }
    $token=[string]$VSOProbeOwnerToken
    $script:LogFile=Join-Path $root ('VSO7_R80_FULL_STARTUP_'+$token+'.log')
    $script:TranscriptFile=Join-Path $root ('VSO7_R80_FULL_STARTUP_TRANSCRIPT_'+$token+'.log')
    [IO.File]::WriteAllText($script:LogFile,('[{0}] [INFO] R52 full startup probe owner={1}; pid={2}; transcriptSuppressed={3}'-f(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$token,$PID,[bool]$script:ProbeSuppressTranscript)+[Environment]::NewLine,[Text.Encoding]::UTF8)
    Write-VSO7LifecycleCheckpointVSO -Name 'FULL_STARTUP_PROBE_ARTIFACTS_READY' -Detail ('LogFile='+$script:LogFile+';TranscriptFile='+$script:TranscriptFile)
    return [pscustomobject]@{OwnerToken=$token;Pid=[int]$PID;LogFile=[string]$script:LogFile;TranscriptFile=[string]$script:TranscriptFile}

}

function Initialize-VSO7StartupProbeArtifactsVSO {

    if([string]$StartupProbe-ieq'None'){
        return $null
    }
    if([string]::IsNullOrWhiteSpace([string]$VSOProbeArtifactRoot)){
        return $null
    }
    if([string]::IsNullOrWhiteSpace([string]$VSOProbeOwnerToken)-or[string]$VSOProbeOwnerToken-notmatch'^[A-Fa-f0-9]{32}$'){
        throw 'STARTUP PROBE recibio un owner token invalido.'
    }
    $root=[IO.Path]::GetFullPath([string]$VSOProbeArtifactRoot)
    $tempRoot=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\')+'\'
    if(-not($root.TrimEnd('\')+'\').StartsWith($tempRoot,[StringComparison]::OrdinalIgnoreCase)){
        throw 'STARTUP PROBE solo puede escribir artefactos dentro de TEMP.'
    }
    if(-not[IO.Directory]::Exists($root)){
        throw 'No existe la carpeta temporal de artefactos del STARTUP PROBE.'
    }
    $item=Get-Item -LiteralPath $root -Force -ErrorAction Stop
    if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'La carpeta de artefactos del STARTUP PROBE es invalida o reparse point.'
    }
    $token=[string]$VSOProbeOwnerToken
    $script:LogFile=Join-Path $root ('VSO7_R80_PROBE_'+$token+'.log')
    $script:TranscriptFile=Join-Path $root ('VSO7_R80_PROBE_TRANSCRIPT_'+$token+'.log')
    [IO.File]::WriteAllText($script:LogFile,('[{0}] [INFO] R52 startup probe owner={1}; pid={2}'-f(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$token,$PID)+[Environment]::NewLine,[Text.Encoding]::UTF8)
    Start-VSO7TranscriptVSO
    return [pscustomobject]@{
        OwnerToken=$token
        Pid=[int]$PID
        LogFile=[string]$script:LogFile
        TranscriptFile=[string]$script:TranscriptFile
    }

}

function Invoke-VSO7OwnedLifecycleCleanupVSO {

    if([bool]$script:LifecycleCleanupStarted){
        return
    }
    $script:LifecycleCleanupStarted=$true
    $script:LifecycleShuttingDown=$true
    Write-VSO7LifecycleCheckpointVSO -Name 'LIFECYCLE_FINALLY_ENTER'

    # GUI cleanup is deliberately bounded/non-waiting. Even if it throws, the mutex release
    # lives in an independent finally and therefore cannot be skipped by logging/transcript.
    try{
        Write-VSO7LifecycleCheckpointVSO -Name 'BEFORE_GUI_RESOURCE_CLEANUP'
        try{
            Invoke-VSO7FinalGuiResourceCleanupVSO
        }catch{
            try{[Console]::Error.WriteLine(('VSO7 GUI cleanup fallo: {0}'-f$_.Exception.Message))}catch{}
        }
        Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_GUI_RESOURCE_CLEANUP'
    }finally{
        # Single-instance ownership is the first externally visible resource released.
        # It must not depend on Stop-Transcript, logging or console-theme cleanup.
        try{
            Exit-VSO7SingleInstance
        }finally{
            if($null-ne$script:InstanceMutex){
                try{[Console]::Error.WriteLine('VSO7 lifecycle: el mutex sigue referenciado despues de Exit-VSO7SingleInstance.')}catch{}
            }
        }
    }

    # From here on, failures must never re-acquire or retain the single-instance mutex.
    if([bool]$script:ProbeForceLoggingCleanupFailure){
        try{
            throw 'R44 synthetic logging-cleanup failure requested by lifecycle probe.'
        }catch{
            Write-VSO7LifecycleCheckpointVSO -Name 'LOGGING_CLEANUP_SYNTHETIC_FAILURE' -Detail $_.Exception.Message
        }
    }
    Stop-VSO7TranscriptVSO

    if([bool]$script:ConsoleThemeInitialized){
        try{
            Restore-VSOConsoleTheme
        }catch{
            try{[Console]::Error.WriteLine(('VSO7 no pudo restaurar completamente el tema de consola: {0}'-f$_.Exception.Message))}catch{}
        }finally{
            $script:ConsoleThemeInitialized=$false
        }
    }
    Write-VSO7LifecycleCheckpointVSO -Name 'LIFECYCLE_DONE'

}

function Initialize-Environment {

    $stage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ENV_DIRECTORY_INIT'
    foreach ($dir in @($script:RecoveryRoot,$script:LogRoot,$script:ReportRoot,$script:ConfigRoot,$script:BenchmarkRoot,$script:GamingProfileRoot,$script:ToolsRoot)) {
        New-Item -ItemType Directory -Path $dir -Force -ErrorAction Stop | Out-Null
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ENV_DIRECTORY_INIT' -StartedMs $stage

    $stage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ENV_LEGACY_STATE_PROBE'
    # No se importa automaticamente el estado de generaciones antiguas desde
    # %ProgramData%\VicoSafeOptimizer. Ese formato no contiene evidencia de
    # ownership suficiente para un rollback elevado seguro. Se conserva intacto.
    $legacy = Join-Path $script:ProgramData 'VicoSafeOptimizer\state.json'
    if (-not (Test-Path -LiteralPath $script:StateFile) -and (Test-Path -LiteralPath $legacy -PathType Leaf)) {
        Write-VSO7Log 'Se detecto estado legado en VicoSafeOptimizer; 7.0.0 no lo importa automaticamente por seguridad.' 'WARN'
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ENV_LEGACY_STATE_PROBE' -StartedMs $stage

    $stage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ENV_PROTECTED_PROCESS_INIT'
    if (-not (Test-Path -LiteralPath $script:ProtectedProcessesFile)) {
        try {
            $defaults = @(Get-VSO7MandatoryProtectedProcesses)
            $tmpProtected = $script:ProtectedProcessesFile + '.tmp'
            $defaults | ConvertTo-Json | Set-Content -LiteralPath $tmpProtected -Encoding UTF8 -Force -ErrorAction Stop
            [void](Get-Content -LiteralPath $tmpProtected -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop)
            [void](Commit-VSO7AtomicFileVSO -SourcePath $tmpProtected -DestinationPath $script:ProtectedProcessesFile)
        } catch {
            Write-VSO7Log ("No se pudo inicializar la lista de procesos protegidos: {0}" -f $_.Exception.Message) 'WARN'
        }
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ENV_PROTECTED_PROCESS_INIT' -StartedMs $stage

    $stage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_START_TRANSCRIPT' -Detail ('Suppressed='+[string][bool]$script:ProbeSuppressTranscript)
    Start-VSO7TranscriptVSO
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_START_TRANSCRIPT' -StartedMs $stage -Detail ('Active='+[string][bool]$script:TranscriptActive+';Suppressed='+[string][bool]$script:ProbeSuppressTranscript)

    $stage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ENV_INITIAL_LOG_WRITE'
    Write-VSO7Log ("Inicio VSO7 v{0}. Raiz: {1}" -f $script:Version,$script:Root)
    if([bool]$script:LogStorageFallbackUsed){
        Write-VSO7Log ("Logs: se usa fallback protegido en ProgramData porque la carpeta local no estaba disponible: {0}"-f$script:LogStorageFallbackReason) 'WARN'
    }else{
        Write-VSO7Log ("Logs locales: {0}"-f$script:LogRoot) 'INFO'
    }
    if([bool]$script:ReportStorageFallbackUsed){
        Write-VSO7Log ("Informes: se usa fallback protegido en ProgramData porque la carpeta local no estaba disponible: {0}"-f$script:ReportStorageFallbackReason) 'WARN'
    }else{
        Write-VSO7Log ("Informes locales: {0}"-f$script:ReportRoot) 'INFO'
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ENV_INITIAL_LOG_WRITE' -StartedMs $stage

    # 7.0.0 no escribe/reescribe launchers junto al script durante una sesion elevada.
    # El launcher de release se distribuye como archivo estatico del paquete.

}

function Resolve-VSOSystemExecutable {

    param([Parameter(Mandatory=$true)][string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) {
        throw 'Nombre de ejecutable del sistema vacio.'
    }
    $leaf=[IO.Path]::GetFileName($Name).ToLowerInvariant()
    $allowed=@('powercfg.exe','bcdedit.exe','dism.exe','manage-bde.exe','reg.exe','sfc.exe','systeminfo.exe','fsutil.exe','rstrui.exe','wsl.exe','dxdiag.exe')
    if ($allowed -notcontains $leaf) {
        throw ("Ejecutable no autorizado por el resolver System32: {0}" -f $Name)
    }

    $expected=[IO.Path]::GetFullPath((Join-Path $script:SystemDirectory $leaf))
    if ([IO.Path]::IsPathRooted($Name)) {

        $candidate=[IO.Path]::GetFullPath($Name)
        if ($candidate -ine $expected) {
            throw ("Ejecutable de sistema fuera de System32 rechazado: {0}" -f $candidate)
        }

    } elseif ($Name -match '[\\/]') {

        throw ("Ruta relativa de ejecutable rechazada: {0}" -f $Name)

    }

    if (-not (Test-Path -LiteralPath $expected -PathType Leaf)) {
        throw ("No se encontro {0} en System32." -f $leaf)
    }
    $exeItem=Get-Item -LiteralPath $expected -Force -ErrorAction Stop
    if($exeItem.PSIsContainer-or($exeItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw ("Ejecutable System32 invalido/reparse point: {0}"-f$expected)
    }
    return $expected

}

function Enter-VSO7SingleInstance {

    if ($null -ne $script:InstanceMutex) {
        return $true
    }
    try {

        $created=$false
        $mutex=[System.Threading.Mutex]::new($false,[string]$script:InstanceMutexName,[ref]$created)
        $acquired=$false
        $waitMilliseconds=if($VSOInternalHandoff){
            8000
        }else{
            0
        }
        try {
            $acquired=$mutex.WaitOne($waitMilliseconds,$false)
        }
        catch [System.Threading.AbandonedMutexException] {
            $acquired=$true
        }
        if (-not $acquired) {

            try {
                $mutex.Dispose()
            } catch {}
            Write-VSOHost 'VSO7 ya esta abierto en otra instancia. Cierra la otra ventana antes de continuar.' -ForegroundColor Yellow
            return $false

        }
        $script:InstanceMutex=$mutex
        return $true

    } catch {

        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'No se pudo crear el bloqueo de instancia unica: {0}' -En 'The single-instance lock could not be created: {0}') -f $_.Exception.Message) -ForegroundColor Red
        return $false

    }

}

function Exit-VSO7SingleInstance {

    Write-VSO7LifecycleCheckpointVSO -Name 'BEFORE_RELEASE_MUTEX' -Detail $(if($null-eq$script:InstanceMutex){'already-null'}else{'owned'})
    if ($null -eq $script:InstanceMutex) {
        Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_RELEASE_MUTEX' -Detail 'already-null'
        return
    }
    $mutex=$script:InstanceMutex
    $script:InstanceMutex=$null
    $releaseError=$null
    try {
        $mutex.ReleaseMutex()
    } catch {
        $releaseError=$_
    } finally {
        try {
            $mutex.Dispose()
        } catch {
            if($null-eq$releaseError){$releaseError=$_}
        }
    }
    if($null-ne$releaseError){
        try{
            [Console]::Error.WriteLine(('VSO7 no pudo liberar limpiamente el mutex de instancia unica: {0}'-f$releaseError.Exception.Message))
        }catch{
            # El handle ya se ha intentado Dispose; no se lanza desde cleanup para no ocultar el error original.
        }
        Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_RELEASE_MUTEX' -Detail ('error='+$releaseError.Exception.Message)
        return
    }
    Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_RELEASE_MUTEX' -Detail 'released-disposed'

}

function Invoke-NativeCommandVSO {

    param(
        [Parameter(Mandatory=$true)][string]$FilePath,
        [string[]]$Arguments = @(),
        [switch]$CaptureOutput,
        [switch]$AllowNonZeroExit
    )

    $resolved=Resolve-VSOSystemExecutable -Name $FilePath
    $output=@()
    $exitCode=$null
    Push-Location -LiteralPath $script:SystemDirectory
    try{

        # Ejecuta binarios del sistema con CWD=System32 para no introducir el directorio
        # del script (potencialmente escribible) en búsquedas de dependencias basadas en CWD.
        $output = @(& $resolved @Arguments 2>&1)
        $exitCode = $LASTEXITCODE

    }finally{

        Pop-Location

    }

    if (-not $AllowNonZeroExit -and $exitCode -ne 0) {

        $tail = ($output | Select-Object -Last 8 | Out-String).Trim()
        if ([string]::IsNullOrWhiteSpace($tail)) {

            throw ("{0} devolvio codigo {1}." -f $resolved, $exitCode)

        }
        throw ("{0} devolvio codigo {1}: {2}" -f $resolved, $exitCode, $tail)

    }

    if ($CaptureOutput) {
        return @($output)
    }

}

function Get-VSO7NormalRegistryDefinitions {

    return @(
        [pscustomobject]@{
        Path='HKCU:\Software\Microsoft\GameBar';Name='AutoGameModeEnabled';Kind='DWord';Value=1
    },
        [pscustomobject]@{
        Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR';Name='AppCaptureEnabled';Kind='DWord';Value=0
    },
        [pscustomobject]@{
        Path='HKCU:\System\GameConfigStore';Name='GameDVR_Enabled';Kind='DWord';Value=0
    },
        [pscustomobject]@{
        Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize';Name='EnableTransparency';Kind='DWord';Value=0
    },
        [pscustomobject]@{
        Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects';Name='VisualFXSetting';Kind='DWord';Value=2
    },
        [pscustomobject]@{
        Path='HKCU:\Control Panel\Desktop\WindowMetrics';Name='MinAnimate';Kind='String';Value='0'
    },
        # Transaccion interna y temporal usada al solicitar un punto NUEVO para EXTREMO.
        # Se journaliza igual que cualquier otro cambio Registry para sobrevivir a crash.
        [pscustomobject]@{
        Path='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore';Name='SystemRestorePointCreationFrequency';Kind='DWord';Value=0
    }
    )

}

function Get-VSO7NormalRegistryDefinition {

    param([string]$Path,[string]$Name)
    return @(Get-VSO7NormalRegistryDefinitions|Where-Object{
        [string]$_.Path-ieq$Path-and[string]$_.Name-ieq$Name
    }|Select-Object -First 1)

}

function Test-VSO7RegistryKindName {

    param([string]$Kind)
    return @('String','ExpandString','Binary','DWord','MultiString','QWord') -contains $Kind

}

function Test-VSO7RegistryJsonValueShape {

    param($Value,[string]$Kind)
    if(-not(Test-VSO7RegistryKindName $Kind)){
        return $false
    }
    switch($Kind){

        'DWord' {
            return (Test-VSO7JsonInteger -Value $Value -Min -2147483648 -Max 4294967295)
        }
        'QWord' {
            return (Test-VSO7JsonInteger -Value $Value -Min 0 -Max ([int64]::MaxValue))
        }
        'String' {
            return ($Value -is [string] -and ([string]$Value).Length-le1048576)
        }
        'ExpandString' {
            return ($Value -is [string] -and ([string]$Value).Length-le1048576)
        }
        'MultiString' {

            if($null-eq$Value-or$Value-is[string]){
                return $false
            }
            $items=@($Value);
            if($items.Count-gt4096){
                return $false
            }
            foreach($item in $items){
                if(-not($item-is[string])-or([string]$item).Length-gt1048576){
                    return $false
                }
            }
            return $true

        }
        'Binary' {

            if($null-eq$Value-or$Value-is[string]){
                return $false
            }
            $items=@($Value);
            if($items.Count-gt16777216){
                return $false
            }
            foreach($item in $items){
                if(-not(Test-VSO7JsonInteger -Value $item -Min 0 -Max 255)){
                    return $false
                }
            }
            return $true

        }

    }
    return $false

}

function ConvertTo-VSO7ValidatedNormalState {

    param($Object)
    if($null-eq$Object){
        throw 'state.json esta vacio.'
    }
    $props=@($Object.PSObject.Properties|ForEach-Object{
        [string]$_.Name
    })
    $isV2=($props-contains'SchemaVersion')
    $required=if($isV2){
        @('SchemaVersion','Version','CreatedAt','Registry','OriginalPowerScheme','AppliedPowerScheme','PendingPowerScheme','Notes')
    }else{
        @('Version','CreatedAt','Registry','OriginalPowerScheme','Notes')
    }
    if(-not(Test-VSO7ExactJsonProperties -Object $Object -Required $required)){
        throw 'state.json no coincide con un esquema reconocido.'
    }
    if($isV2-and -not(Test-VSO7JsonInteger -Value $Object.SchemaVersion -Min 2 -Max 2)){
        throw 'SchemaVersion de state.json no es compatible.'
    }
    if(-not($Object.Version-is[string])-or[string]::IsNullOrWhiteSpace([string]$Object.Version)-or([string]$Object.Version).Length-gt32){
        throw 'Version invalida en state.json.'
    }
    if($isV2-and[string]$Object.Version-cne[string]$script:Version){
        throw ('state.json pertenece a VSO7 {0}; esta build exige estado schema v2 de VSO7 {1}.'-f[string]$Object.Version,[string]$script:Version)
    }
    if(-not($Object.CreatedAt-is[string])-or-not(Test-VSO7IsoUtcTimestamp ([string]$Object.CreatedAt))){
        throw 'CreatedAt invalido en state.json.'
    }
    if($null-eq$Object.Registry-or$Object.Registry-is[string]){
        throw 'Registry invalido en state.json.'
    }
    $registry=@($Object.Registry);
    if($registry.Count-gt64){
        throw 'Demasiadas entradas Registry en state.json.'
    }
    if(-not$isV2-and$registry.Count-gt0){
        throw 'state.json legado contiene rollback Registry sin evidencia fuerte de ownership; 7.0.0 lo conserva pero no lo ejecuta automaticamente.'
    }
    $normalized=@();
    $seen=@{}
    foreach($entry in $registry){

        $entryV2=(@($entry.PSObject.Properties.Name)-contains'Status')
        $entryRequired=if($entryV2){
            @('Path','Name','Exists','Kind','Value','AppliedExists','AppliedKind','AppliedValue','Status')
        }else{
            @('Path','Name','Exists','Kind','Value')
        }
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $entryRequired)){
            throw 'Entrada Registry con esquema no permitido en state.json.'
        }
        if(-not($entry.Path-is[string])-or-not($entry.Name-is[string])){
            throw 'Path/Name no son texto en state.json.'
        }
        $def=@(Get-VSO7NormalRegistryDefinition -Path ([string]$entry.Path) -Name ([string]$entry.Name))
        if($def.Count-ne1){
            throw ("Registro fuera de allowlist normal: {0}\{1}"-f$entry.Path,$entry.Name)
        }
        $key=([string]$def[0].Path).ToLowerInvariant()+'|'+([string]$def[0].Name).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'Registro duplicado en state.json.'
        };
        $seen[$key]=$true
        if(-not($entry.Exists-is[bool])){
            throw 'Exists no es booleano en state.json.'
        }
        $originalKind=$null;
        $originalValue=$null
        if([bool]$entry.Exists){

            if(-not($entry.Kind-is[string])-or-not(Test-VSO7RegistryJsonValueShape -Value $entry.Value -Kind ([string]$entry.Kind))){
                throw 'Valor original de Registro invalido en state.json.'
            }
            $originalKind=[string]$entry.Kind;
            $originalValue=$entry.Value

        }else{

            if($null-ne$entry.Kind-and-not[string]::IsNullOrWhiteSpace([string]$entry.Kind)){
                throw 'Kind debe estar vacio cuando Exists=false.'
            }
            if($null-ne$entry.Value){
                throw 'Value debe ser null cuando Exists=false.'
            }

        }
        $status='Applied'
        if($entryV2){

            if(-not($entry.AppliedExists-is[bool])-or-not[bool]$entry.AppliedExists){
                throw 'AppliedExists invalido en state.json.'
            }
            if(-not($entry.AppliedKind-is[string])-or[string]$entry.AppliedKind-ine[string]$def[0].Kind){
                throw 'AppliedKind no coincide con la allowlist.'
            }
            if(-not(Test-RegistryValueEqualVSO -Actual $entry.AppliedValue -Expected $def[0].Value -Kind ([string]$def[0].Kind))){
                throw 'AppliedValue no coincide con la allowlist.'
            }
            if(-not($entry.Status-is[string])-or@('Pending','Applied')-notcontains[string]$entry.Status){
                throw 'Status invalido en state.json.'
            }
            $status=[string]$entry.Status

        }
        $normalized += [pscustomobject]@{
            Path=[string]$def[0].Path;
            Name=[string]$def[0].Name;
            Exists=[bool]$entry.Exists;
            Kind=$originalKind;
            Value=$originalValue;
            AppliedExists=$true;
            AppliedKind=[string]$def[0].Kind;
            AppliedValue=$def[0].Value;
            Status=$status
        }

    }
    $originalPower=$Object.OriginalPowerScheme;
    $appliedPower=$null;
    $pendingPower=$null
    if($null -ne $originalPower -and -not($originalPower -is [string])){
        throw 'OriginalPowerScheme invalido.'
    }
    if(-not[string]::IsNullOrWhiteSpace([string]$originalPower) -and -not(Test-VSO7PowerSchemeGuid ([string]$originalPower))){
        throw 'OriginalPowerScheme no es GUID.'
    }
    if($isV2){

        $appliedPower=$Object.AppliedPowerScheme;
        $pendingPower=$Object.PendingPowerScheme
        foreach($g in @($appliedPower,$pendingPower)){
            if($null -ne $g -and -not($g -is [string])){
                throw 'Estado de energia invalido.'
            };
            if(-not[string]::IsNullOrWhiteSpace([string]$g) -and -not(Test-VSO7PowerSchemeGuid ([string]$g))){
                throw 'GUID de energia invalido.'
            }
        }
        if([string]::IsNullOrWhiteSpace([string]$originalPower) -and (-not[string]::IsNullOrWhiteSpace([string]$appliedPower) -or -not[string]::IsNullOrWhiteSpace([string]$pendingPower))){
            throw 'Energia aplicada/pending sin baseline original.'
        }

    }elseif(-not[string]::IsNullOrWhiteSpace([string]$originalPower)){

        throw 'state.json legado contiene rollback de energia sin evidencia del valor aplicado; se rechaza de forma segura.'

    }
    if($null -eq $Object.Notes -or $Object.Notes -is [string]){
        throw 'Notes invalido en state.json.'
    }
    $notes=@($Object.Notes);
    if($notes.Count-gt256){
        throw 'Demasiadas Notes en state.json.'
    };
    foreach($note in $notes){
        if(-not($note -is [string]) -or ([string]$note).Length -gt 4096){
            throw 'Note invalida en state.json.'
        }
    }
    $normalizedOriginalPower=if([string]::IsNullOrWhiteSpace([string]$originalPower)){
        $null
    }else{
        [string]$originalPower
    }
    $normalizedAppliedPower=if([string]::IsNullOrWhiteSpace([string]$appliedPower)){
        $null
    }else{
        [string]$appliedPower
    }
    $normalizedPendingPower=if([string]::IsNullOrWhiteSpace([string]$pendingPower)){
        $null
    }else{
        [string]$pendingPower
    }
    return @{
        SchemaVersion=2;
        Version=[string]$Object.Version;
        CreatedAt=[string]$Object.CreatedAt;
        Registry=$normalized;
        OriginalPowerScheme=$normalizedOriginalPower;
        AppliedPowerScheme=$normalizedAppliedPower;
        PendingPowerScheme=$normalizedPendingPower;
        Notes=@($notes)
    }

}

function New-EmptyState {

    return @{

        SchemaVersion = 2
        Version = $script:Version
        CreatedAt = (Get-Date).ToString('o')
        Registry = @()
        OriginalPowerScheme = $null
        AppliedPowerScheme = $null
        PendingPowerScheme = $null
        Notes = @()

    }

}

function Load-State {

    if (-not (Test-Path -LiteralPath $script:StateFile)) {

        $script:State = New-EmptyState
        return

    }
    try {

        $raw = Get-Content -LiteralPath $script:StateFile -Raw -ErrorAction Stop
        $obj = $raw | ConvertFrom-Json -ErrorAction Stop
        $script:State = ConvertTo-VSO7ValidatedNormalState -Object $obj

    } catch {

        Write-VSO7Log ("No se pudo validar state.json: {0}" -f $_.Exception.Message) 'ERROR'
        throw 'VSO7 no continuara con cambios mientras state.json no supere validacion semantica estricta. Conserva el archivo para recuperacion/manual.'

    }

}

function Save-State {

    $recoveryPublishBundle=$null
    try {

        $validated=ConvertTo-VSO7ValidatedNormalState -Object ([pscustomobject]$script:State)
        $script:State=$validated
        $json = $validated | ConvertTo-Json -Depth 10
        $temp = "$($script:StateFile).tmp"
        Set-Content -LiteralPath $temp -Value $json -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $temp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedNormalState -Object $check)
        if (-not [string]::IsNullOrWhiteSpace($script:LastRecoveryBundle) -and (Test-Path -LiteralPath $script:LastRecoveryBundle)) {

            $recoveryPublishBundle=Start-VSO7RecoveryPublishTransactionVSO -Bundle $script:LastRecoveryBundle

        }
        [void](Commit-VSO7AtomicFileVSO -SourcePath $temp -DestinationPath $script:StateFile)
        if (-not (Test-Path -LiteralPath $script:StateFile -PathType Leaf)) {
            throw 'state.json no existe tras guardarlo.'
        }
        $check=Get-Content -LiteralPath $script:StateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedNormalState -Object $check)
        if (-not [string]::IsNullOrWhiteSpace([string]$recoveryPublishBundle)) {

            [void](Publish-VSO7RecoveryGenerationVSO -Bundle $recoveryPublishBundle)
            Clear-VSO7RecoveryPublishJournalVSO

        }

    } catch {

        try{
            if(Test-Path -LiteralPath "$($script:StateFile).tmp" -PathType Leaf){
                Remove-Item -LiteralPath "$($script:StateFile).tmp" -Force -ErrorAction SilentlyContinue
            }
        }catch{}
        Write-VSO7Log ("No se pudo guardar/verificar state.json: {0}" -f $_.Exception.Message) 'ERROR'
        throw

    }

}

function Get-RegistrySnapshot {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Name
    )

    $exists = $false
    $kind = $null
    $value = $null
    $key=$null
    try {

        $pathExists = Test-Path -LiteralPath $Path -ErrorAction Stop
        if ($pathExists) {

            $key = Get-Item -LiteralPath $Path -ErrorAction Stop
            if ($key.GetValueNames() -contains $Name) {

                $exists = $true
                $kind = [string]$key.GetValueKind($Name)
                $value = $key.GetValue($Name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)

            }

        }

    } catch {

        Write-VSO7Log ("No se pudo respaldar {0}\{1}: {2}" -f $Path,$Name,$_.Exception.Message) 'ERROR'
        throw

    } finally {

        if($null-ne$key){
            try{
                $key.Close()
            }catch{}
        }

    }
    return [pscustomobject]@{
        Path=$Path;
        Name=$Name;
        Exists=$exists;
        Kind=$kind;
        Value=$value
    }

}

function Get-VSO7RegistryValuesSnapshotVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $result=@();
    $key=$null
    try{

        if(-not(Test-Path -LiteralPath $Path)){
            return @()
        }
        $key=Get-Item -LiteralPath $Path -ErrorAction Stop
        foreach($name in @($key.GetValueNames())){

            if([string]::IsNullOrWhiteSpace([string]$name)){
                continue
            }
            $result += [pscustomobject]@{

                Name=[string]$name
                Kind=[string]$key.GetValueKind([string]$name)
                Value=$key.GetValue([string]$name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)

            }

        }
        return @($result)

    }finally{
        if($null-ne$key){
            try{
                $key.Close()
            }catch{}
        }
    }

}

function Test-VSO7RegistrySnapshotEqualVSO {

    param(
        [Parameter(Mandatory=$true)]$Left,
        [Parameter(Mandatory=$true)]$Right
    )
    if([bool]$Left.Exists-ne[bool]$Right.Exists){
        return $false
    }
    if(-not[bool]$Left.Exists){
        return $true
    }
    if([string]$Left.Kind-ine[string]$Right.Kind){
        return $false
    }
    return (Test-RegistryValueEqualVSO -Actual $Left.Value -Expected $Right.Value -Kind ([string]$Left.Kind))

}

function Get-ExistingRegistryBaselineVSO {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Name
    )

    if ($null -ne $script:State -and $null -ne $script:State.Registry) {

        $normal=@($script:State.Registry | Where-Object {
            $_.Path -eq $Path -and $_.Name -eq $Name
        } | Select-Object -First 1)
        if ($normal.Count -gt 0) {

            return [pscustomobject]@{
                Path=$Path;
                Name=$Name;
                Exists=[bool]$normal[0].Exists;
                Kind=$normal[0].Kind;
                Value=$normal[0].Value
            }

        }

    }
    if ($null -ne $script:ExtremeState -and $null -ne $script:ExtremeState.Registry) {

        $ext=@($script:ExtremeState.Registry | Where-Object {
            $_.Path -eq $Path -and $_.Name -eq $Name
        } | Select-Object -First 1)
        if ($ext.Count -gt 0) {

            return [pscustomobject]@{
                Path=$Path;
                Name=$Name;
                Exists=[bool]$ext[0].Exists;
                Kind=$ext[0].Kind;
                Value=$ext[0].Value
            }

        }

    }
    return $null

}

function Backup-RegistryValue {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)]$AppliedValue,
        [Parameter(Mandatory=$true)][string]$AppliedKind,
        [Parameter(Mandatory=$true)]$ObservedSnapshot
    )
    $def=@(Get-VSO7NormalRegistryDefinition -Path $Path -Name $Name)
    if($def.Count-ne1-or[string]$def[0].Kind-ine$AppliedKind-or-not(Test-RegistryValueEqualVSO -Actual $AppliedValue -Expected $def[0].Value -Kind $AppliedKind)){
        throw 'Set-TrackedRegistryValue intento usar un destino/valor fuera de allowlist.'
    }
    $already = @($script:State.Registry | Where-Object {
        $_.Path -ieq $Path -and $_.Name -ieq $Name
    })
    if ($already.Count -gt 0) {

        $already[0].Status='Pending';
        $already[0].AppliedExists=$true;
        $already[0].AppliedKind=$AppliedKind;
        $already[0].AppliedValue=$AppliedValue;
        Save-State;
        return

    }
    $snapshot = Get-ExistingRegistryBaselineVSO -Path $Path -Name $Name
    if ($null -eq $snapshot) {

        if($null-eq$ObservedSnapshot-or[string]$ObservedSnapshot.Path-ine$Path-or[string]$ObservedSnapshot.Name-ine$Name){
            throw 'Snapshot observado invalido al crear rollback Registry normal.'
        }
        $snapshot=$ObservedSnapshot

    }
    $script:State.Registry += [pscustomobject]@{
        Path=$snapshot.Path;
        Name=$snapshot.Name;
        Exists=[bool]$snapshot.Exists;
        Kind=$snapshot.Kind;
        Value=$snapshot.Value;
        AppliedExists=$true;
        AppliedKind=$AppliedKind;
        AppliedValue=$AppliedValue;
        Status='Pending'
    }
    Save-State

}

function Set-TrackedRegistryValue {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)]$Value,
        [ValidateSet('DWord','QWord','String','ExpandString','MultiString','Binary')][string]$Type = 'DWord'
    )

    [void](Assert-VSO7NoNativeRegistryOwnershipVSO -Path $Path -Name $Name)
    $beforePending=Get-RegistrySnapshot -Path $Path -Name $Name
    $existingBefore=@($script:State.Registry|Where-Object{
        $_.Path-ieq$Path-and$_.Name-ieq$Name
    })
    if($existingBefore.Count-gt1){
        throw 'Estado Registry normal duplicado antes de iniciar la transaccion.'
    }
    $hadExisting=($existingBefore.Count-eq1)
    $previousStatus=if($hadExisting){
        [string]$existingBefore[0].Status
    }else{
        $null
    }
    $previousAppliedExists=if($hadExisting){
        [bool]$existingBefore[0].AppliedExists
    }else{
        $false
    }
    $previousAppliedKind=if($hadExisting){
        $existingBefore[0].AppliedKind
    }else{
        $null
    }
    $previousAppliedValue=if($hadExisting){
        $existingBefore[0].AppliedValue
    }else{
        $null
    }

    if($hadExisting){

        $old=$existingBefore[0]
        $matchesOldBaseline=([bool]$beforePending.Exists-eq[bool]$old.Exists)
        if($matchesOldBaseline-and[bool]$beforePending.Exists){
            $matchesOldBaseline=([string]$beforePending.Kind-ieq[string]$old.Kind)-and(Test-RegistryValueEqualVSO -Actual $beforePending.Value -Expected $old.Value -Kind ([string]$old.Kind))
        }
        $matchesOldApplied=([bool]$beforePending.Exists-eq[bool]$old.AppliedExists)
        if($matchesOldApplied-and[bool]$beforePending.Exists){
            $matchesOldApplied=([string]$beforePending.Kind-ieq[string]$old.AppliedKind)-and(Test-RegistryValueEqualVSO -Actual $beforePending.Value -Expected $old.AppliedValue -Kind ([string]$old.AppliedKind))
        }
        if([string]$previousStatus-ieq'Pending'-and-not($matchesOldBaseline-or$matchesOldApplied)){
            throw 'Existe Registry normal Pending ambiguo; VSO7 no lo sobrescribe con una nueva mutacion.'
        }
        if([string]$previousStatus-ieq'Applied'-and-not($matchesOldBaseline-or$matchesOldApplied)){

            # El ownership confirmado anterior ya fue desplazado externamente. Al iniciar el usuario
            # una NUEVA mutacion, ese estado externo pasa a ser el nuevo baseline del rollback.
            $old.Exists=[bool]$beforePending.Exists;
            $old.Kind=$beforePending.Kind;
            $old.Value=$beforePending.Value

        }

    }
    Backup-RegistryValue -Path $Path -Name $Name -AppliedValue $Value -AppliedKind $Type -ObservedSnapshot $beforePending

    try{

        if(Test-RegistryValueOwnedByExtremeVSO -Path $Path -Name $Name){
            [void](Assert-VSO7SharedRegistryOwnershipCompatibleVSO -Path $Path -Name $Name)
        }
        $afterPending=Get-RegistrySnapshot -Path $Path -Name $Name

    }
    catch{

        if($hadExisting){
            $owned=@($script:State.Registry|Where-Object{
                $_.Path-ieq$Path-and$_.Name-ieq$Name
            }|Select-Object -First 1);
            if($owned.Count-eq1){

            # Si cambiamos el baseline por drift externo antes de Backup, conservarlo: es la realidad
            # observada antes de la nueva operacion. La nueva mutacion NO ocurrio: restauramos
            # tanto el Status como la metadata Applied anterior.
            $owned[0].Status=$previousStatus
            $owned[0].AppliedExists=$previousAppliedExists;
                $owned[0].AppliedKind=$previousAppliedKind;
                $owned[0].AppliedValue=$previousAppliedValue

            }
        }
        else{
            $script:State.Registry=@($script:State.Registry|Where-Object{
                -not($_.Path-ieq$Path-and$_.Name-ieq$Name)
            })
        }
        Save-State
        throw ("No se pudo revalidar ownership/Registry antes de mutar; VSO7 retiro su Pending: {0}"-f$_.Exception.Message)

    }
    if(-not(Test-VSO7RegistrySnapshotEqualVSO -Left $beforePending -Right $afterPending)){

        if($hadExisting){
            $owned=@($script:State.Registry|Where-Object{
                $_.Path-ieq$Path-and$_.Name-ieq$Name
            }|Select-Object -First 1);
            if($owned.Count-eq1){
                $owned[0].Status=$previousStatus;
                $owned[0].AppliedExists=$previousAppliedExists;
                $owned[0].AppliedKind=$previousAppliedKind;
                $owned[0].AppliedValue=$previousAppliedValue
            }
        }
        else{
            $script:State.Registry=@($script:State.Registry|Where-Object{
                -not($_.Path-ieq$Path-and$_.Name-ieq$Name)
            })
        }
        Save-State
        throw 'El valor Registry cambio entre snapshot y mutacion; VSO7 retiro su Pending sin tocar Windows.'

    }

    try {

        if (-not (Test-Path -LiteralPath $Path)) {
            New-Item -Path $Path -Force -ErrorAction Stop | Out-Null
        }
        New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType $Type -Force -ErrorAction Stop | Out-Null
        $verify=Get-RegistrySnapshot -Path $Path -Name $Name
        if(-not[bool]$verify.Exists){
            throw 'El valor no existe despues de escribirlo.'
        }
        if (-not (Test-RegistryValueEqualVSO -Actual $verify.Value -Expected $Value -Kind $Type)) {
            throw 'El valor leido despues de escribir no coincide.'
        }
        $owned=@($script:State.Registry|Where-Object{
            $_.Path-ieq$Path-and$_.Name-ieq$Name
        }|Select-Object -First 1);
        if($owned.Count-ne1){
            throw 'Se perdio el estado de rollback tras escribir Registro.'
        };
        $owned[0].Status='Applied';
        Save-State
        Write-VSO7Log ("Registro verificado: {0}\{1} = {2}" -f $Path,$Name,$Value) 'CHANGE'

    } catch {

        Write-VSO7Log ("No se pudo modificar/verificar {0}\{1}: {2}" -f $Path,$Name,$_.Exception.Message) 'ERROR'
        throw

    }

}

function Test-RegistryValueOwnedByNormalVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Name)
    return ($null -ne $script:State -and $null -ne $script:State.Registry -and @($script:State.Registry | Where-Object {
        $_.Path -eq $Path -and $_.Name -eq $Name
    }).Count -gt 0)

}

function Test-RegistryValueOwnedByExtremeVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Name)
    if($null -eq $script:ExtremeState -or $null -eq $script:ExtremeState.Registry){
        return $false
    }
    $activeIds=@()
    if($null-ne$script:ExtremeState.AppliedTweaks){
        $activeIds += @($script:ExtremeState.AppliedTweaks|ForEach-Object{
            [string]$_.Id
        })
    }
    if($null-ne$script:ExtremeState.PendingTweaks){
        $activeIds += @($script:ExtremeState.PendingTweaks|ForEach-Object{
            [string]$_.Id
        })
    }
    if($activeIds.Count-eq0){
        return $false
    }
    return @($script:ExtremeState.Registry | Where-Object {
        $_.Path -eq $Path -and $_.Name -eq $Name -and $activeIds -contains [string]$_.TweakId
    }).Count -gt 0

}

function Assert-VSO7SharedRegistryOwnershipCompatibleVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Name)
    $owners=@()
    if($null-ne$script:State-and$null-ne$script:State.Registry){

        $owners+=@($script:State.Registry|Where-Object{
            $_.Path-ieq$Path-and$_.Name-ieq$Name
        })

    }
    if($null-ne$script:ExtremeState-and$null-ne$script:ExtremeState.Registry){

        $activeIds=@()
        if($null-ne$script:ExtremeState.AppliedTweaks){
            $activeIds+=@($script:ExtremeState.AppliedTweaks|ForEach-Object{
                [string]$_.Id
            })
        }
        if($null-ne$script:ExtremeState.PendingTweaks){
            $activeIds+=@($script:ExtremeState.PendingTweaks|ForEach-Object{
                [string]$_.Id
            })
        }
        $owners+=@($script:ExtremeState.Registry|Where-Object{
            $_.Path-ieq$Path-and$_.Name-ieq$Name-and$activeIds-contains[string]$_.TweakId
        })

    }
    if($owners.Count-lt2){
        return $true
    }
    $first=$owners[0]
    foreach($owner in @($owners|Select-Object -Skip 1)){

        if([bool]$owner.AppliedExists-ne[bool]$first.AppliedExists){
            throw 'Owners Registry superpuestos esperan distinta existencia aplicada.'
        }
        if([bool]$first.AppliedExists){

            if([string]$owner.AppliedKind-ine[string]$first.AppliedKind){
                throw 'Owners Registry superpuestos esperan distinto tipo aplicado.'
            }
            if(-not(Test-RegistryValueEqualVSO -Actual $owner.AppliedValue -Expected $first.AppliedValue -Kind ([string]$first.AppliedKind))){
                throw 'Owners Registry superpuestos esperan valores aplicados distintos.'
            }

        }

    }
    $current=Get-RegistrySnapshot -Path $Path -Name $Name
    if([bool]$current.Exists-ne[bool]$first.AppliedExists){
        throw 'El valor Registry compartido ya no coincide con el estado aplicado de sus owners.'
    }
    if([bool]$current.Exists-and(([string]$current.Kind-ine[string]$first.AppliedKind)-or-not(Test-RegistryValueEqualVSO -Actual $current.Value -Expected $first.AppliedValue -Kind ([string]$first.AppliedKind)))){
        throw 'El valor Registry compartido cambio externamente o divergio entre owners.'
    }
    return $true

}

function Repair-VSO7RestorePointFrequencyTransactionVSO {

    $path='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'
    $name='SystemRestorePointCreationFrequency'
    if($null-eq$script:State-or$null-eq$script:State.Registry){
        return $true
    }
    $entries=@($script:State.Registry|Where-Object{
        $_.Path-ieq$path-and$_.Name-ieq$name
    })
    if($entries.Count-eq0){
        return $true
    }
    if($entries.Count-ne1){
        Write-VSO7Log 'Estado interno de frecuencia de Restore Point duplicado; se conserva para revision.' 'ERROR';
        return $false
    }
    $entry=$entries[0]
    try{

        $current=Get-RegistrySnapshot -Path $path -Name $name
        $matchesApplied=([bool]$current.Exists-eq[bool]$entry.AppliedExists)
        if($matchesApplied-and[bool]$current.Exists){
            $matchesApplied=([string]$current.Kind-ieq[string]$entry.AppliedKind)-and(Test-RegistryValueEqualVSO -Actual $current.Value -Expected $entry.AppliedValue -Kind ([string]$entry.AppliedKind))
        }
        $matchesOriginal=([bool]$current.Exists-eq[bool]$entry.Exists)
        if($matchesOriginal-and[bool]$current.Exists){
            $matchesOriginal=([string]$current.Kind-ieq[string]$entry.Kind)-and(Test-RegistryValueEqualVSO -Actual $current.Value -Expected $entry.Value -Kind ([string]$entry.Kind))
        }

        if($matchesOriginal){

            Write-VSO7Log 'La frecuencia temporal de Restore Point ya coincide con su baseline; se libera ownership.' 'INFO'

        }elseif(-not$matchesApplied){

            if([string]$entry.Status-ieq'Pending'){

                Write-VSO7Log 'SystemRestorePointCreationFrequency esta Pending y no coincide ni con baseline ni con valor aplicado; se conserva evidencia ambigua.' 'ERROR'
                return $false

            }
            Write-VSO7Log 'La frecuencia de Restore Point cambio externamente tras estado Applied; VSO7 no la sobrescribe y libera ownership.' 'WARN'

        }else{

            if([bool]$entry.Exists){

                if(-not(Test-Path -LiteralPath $path)){
                    New-Item -Path $path -Force -ErrorAction Stop|Out-Null
                }
                New-ItemProperty -LiteralPath $path -Name $name -Value $entry.Value -PropertyType ([string]$entry.Kind) -Force -ErrorAction Stop|Out-Null

            }else{

                if(Test-Path -LiteralPath $path){
                    Remove-ItemProperty -LiteralPath $path -Name $name -ErrorAction Stop
                }

            }
            $after=Get-RegistrySnapshot -Path $path -Name $name
            if([bool]$after.Exists-ne[bool]$entry.Exists){
                throw 'La existencia final de SystemRestorePointCreationFrequency no coincide con el baseline.'
            }
            if([bool]$after.Exists-and(([string]$after.Kind-ine[string]$entry.Kind)-or-not(Test-RegistryValueEqualVSO -Actual $after.Value -Expected $entry.Value -Kind ([string]$entry.Kind)))){
                throw 'SystemRestorePointCreationFrequency no coincide con el baseline tras restaurar.'
            }
            Write-VSO7Log 'SystemRestorePointCreationFrequency restaurado y verificado.' 'CHANGE'

        }
        $script:State.Registry=@($script:State.Registry|Where-Object{
            -not($_.Path-ieq$path-and$_.Name-ieq$name)
        })
        Save-State
        return $true

    }catch{

        Write-VSO7Log ("No se pudo reconciliar SystemRestorePointCreationFrequency; el estado queda pendiente: {0}"-f$_.Exception.Message) 'ERROR'
        return $false

    }

}

function Restore-TrackedRegistry {

    if ($null -eq $script:State.Registry -or @($script:State.Registry).Count -eq 0) {
        Write-VSO7Log 'No hay valores de registro guardados para restaurar.';
        return $true
    }
    $failed=@();
    $remaining=@()
    foreach($entry in @($script:State.Registry)){

        try{

            if(Test-RegistryValueOwnedByExtremeVSO -Path ([string]$entry.Path) -Name ([string]$entry.Name)){
                [void](Assert-VSO7SharedRegistryOwnershipCompatibleVSO -Path ([string]$entry.Path) -Name ([string]$entry.Name));
                Write-VSO7Log ("Rollback normal libera {0}\{1}, pero no toca el valor porque un tweak EXTREMO compatible sigue siendo propietario."-f$entry.Path,$entry.Name) 'CHANGE';
                continue
            }
            $currentSnapshot=Get-RegistrySnapshot -Path ([string]$entry.Path) -Name ([string]$entry.Name)
            $currentExists=[bool]$currentSnapshot.Exists;
            $currentKind=$currentSnapshot.Kind;
            $currentValue=$currentSnapshot.Value
            $matchesApplied=($currentExists-eq[bool]$entry.AppliedExists)
            if($matchesApplied-and$currentExists){
                $matchesApplied=($currentKind-ieq[string]$entry.AppliedKind)-and(Test-RegistryValueEqualVSO -Actual $currentValue -Expected $entry.AppliedValue -Kind ([string]$entry.AppliedKind))
            }
            $matchesOriginal=($currentExists-eq[bool]$entry.Exists)
            if($matchesOriginal-and$currentExists){
                $matchesOriginal=($currentKind-ieq[string]$entry.Kind)-and(Test-RegistryValueEqualVSO -Actual $currentValue -Expected $entry.Value -Kind ([string]$entry.Kind))
            }
            if($matchesOriginal){
                Write-VSO7Log ("Rollback normal: {0}\{1} ya coincide con el valor original; se libera ownership."-f$entry.Path,$entry.Name) 'INFO';
                continue
            }
            if(-not$matchesApplied){

                if([string]$entry.Status-ieq'Pending'){
                    throw 'Registry normal Pending ambiguo: no coincide ni con baseline ni con el valor aplicado esperado; se conserva evidencia.'
                }
                Write-VSO7Log ("Rollback normal NO toca {0}\{1}: cambio externo detectado tras estado Applied; se libera ownership sin sobrescribir."-f$entry.Path,$entry.Name) 'WARN';
                continue

            }
            if([bool]$entry.Exists){

                if(-not(Test-Path -LiteralPath $entry.Path)){
                    New-Item -Path $entry.Path -Force -ErrorAction Stop|Out-Null
                }
                New-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -Value $entry.Value -PropertyType ([string]$entry.Kind) -Force -ErrorAction Stop|Out-Null

            }else{

                if(Test-Path -LiteralPath $entry.Path){
                    Remove-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -ErrorAction Stop
                }

            }
            $afterSnapshot=Get-RegistrySnapshot -Path ([string]$entry.Path) -Name ([string]$entry.Name)
            $afterExists=[bool]$afterSnapshot.Exists;
            $afterKind=$afterSnapshot.Kind;
            $afterValue=$afterSnapshot.Value
            if($afterExists-ne[bool]$entry.Exists){
                throw 'La existencia final no coincide con el baseline.'
            }
            if($afterExists-and(($afterKind-ine[string]$entry.Kind)-or-not(Test-RegistryValueEqualVSO -Actual $afterValue -Expected $entry.Value -Kind ([string]$entry.Kind)))){
                throw 'El valor final no coincide con el baseline.'
            }
            Write-VSO7Log ("Restaurado/verificado con ownership: {0}\{1}"-f$entry.Path,$entry.Name) 'CHANGE'

        }catch{
            $failed+=$entry;
            $remaining+=$entry;
            Write-VSO7Log ("No se pudo restaurar {0}\{1}: {2}"-f$entry.Path,$entry.Name,$_.Exception.Message) 'ERROR'
        }

    }
    $script:State.Registry=@($remaining);
    Save-State;
    return($failed.Count-eq0)

}

function Get-ActivePowerSchemeGuid {

    try {

        $lines = Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/getactivescheme') -CaptureOutput
        $text = ($lines | Out-String)
        $m = [regex]::Match($text, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
        if ($m.Success) {
            return $m.Value.ToLowerInvariant()
        }

    } catch {}
    return $null

}

function Get-PowerSchemeNameFromText {

    param([string]$Text)

    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $null
    }

    # powercfg coloca el nombre visible entre los parentesis EXTERIORES al final de la
    # linea. No usamos [^()]* porque un nombre personalizado puede contener parentesis.
    # Primero quitamos exclusivamente el asterisco de plan activo que queda FUERA del nombre.
    $tail=[string]$Text
    $guidMatch=[regex]::Match($tail,'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
    if($guidMatch.Success){
        $tail=$tail.Substring($guidMatch.Index+$guidMatch.Length)
    }
    if($tail -match '\*\s*$'){
        $tail=$tail.Substring(0,$tail.LastIndexOf('*')).TrimEnd()
    }
    $open=$tail.IndexOf('(')
    $close=$tail.LastIndexOf(')')
    if($open-ge0-and$close-gt$open-and[string]::IsNullOrWhiteSpace($tail.Substring($close+1))){

        return $tail.Substring($open+1,$close-$open-1).Trim()

    }
    return $null

}

function Get-ActivePowerSchemeInfo {

    $text=$null;
    $guid=$null;
    $queryError=$null
    try{
        $text=((Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/getactivescheme') -CaptureOutput)|Out-String).Trim();
        $guid=Get-ActivePowerSchemeGuid;
        if([string]::IsNullOrWhiteSpace([string]$guid)){
            throw 'powercfg no devolvio GUID activo.'
        }
    }catch{
        $queryError=$_.Exception.Message
    }
    $name=if($null-ne$text){
        Get-PowerSchemeNameFromText -Text $text
    }else{
        $null
    };
    $builtinName=$null
    if(-not[string]::IsNullOrWhiteSpace([string]$guid)){
        foreach($key in $script:BuiltInPowerSchemes.Keys){
            if($script:BuiltInPowerSchemes[$key]-eq$guid){
                $builtinName=$key;
                break
            }
        }
    }
    return [pscustomobject]@{
        Available=[string]::IsNullOrWhiteSpace([string]$queryError);
        Error=$queryError;
        Guid=$guid;
        Name=$name;
        Raw=$text;
        IsBuiltIn=($null-ne$builtinName);
        BuiltInName=$builtinName;
        IsCustom=(-not[string]::IsNullOrWhiteSpace([string]$guid)-and$null-eq$builtinName)
    }

}

function Get-AllPowerSchemes {

    $result = @()
    try {

        $lines = @(Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/list') -CaptureOutput)
        foreach ($line in $lines) {

            $lineText=[string]$line
            $m = [regex]::Match($lineText,'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
            if (-not $m.Success) {
                continue
            }
            $guid = $m.Value.ToLowerInvariant()
            $name = Get-PowerSchemeNameFromText -Text $lineText
            $active = ($lineText -match '\*\s*$')
            $builtinName = $null
            foreach ($key in $script:BuiltInPowerSchemes.Keys) {

                if ($script:BuiltInPowerSchemes[$key] -eq $guid) {
                    $builtinName = $key;
                    break
                }

            }
            $result += [pscustomobject]@{
                Guid=$guid;
                Name=$name;
                Active=$active;
                IsBuiltIn=($null -ne $builtinName);
                BuiltInName=$builtinName
            }

        }

    } catch {}
    return @($result)

}

function Backup-PowerScheme {

    param([Parameter(Mandatory=$true)][string]$PendingGuid)
    if(-not(Test-VSO7PowerSchemeGuid $PendingGuid)){
        throw 'GUID de energia objetivo invalido.'
    }
    if(@(Get-AllPowerSchemes|Where-Object{
        $_.Guid-ieq$PendingGuid
    }).Count-eq0){
        throw 'El plan objetivo no existe en powercfg /list.'
    }
    if([string]::IsNullOrWhiteSpace([string]$script:State.OriginalPowerScheme)){

        $guid=Get-ActivePowerSchemeGuid
        if([string]::IsNullOrWhiteSpace($guid)-or@(Get-AllPowerSchemes|Where-Object{
            $_.Guid-ieq$guid
        }).Count-eq0){
            throw 'No se pudo guardar/verificar el plan original.'
        }
        $script:State.OriginalPowerScheme=$guid
        $script:State.AppliedPowerScheme=$null

    }
    $script:State.PendingPowerScheme=$PendingGuid
    Save-State
    Write-VSO7Log ("Transaccion de energia preparada: original={0}, pendiente={1}"-f$script:State.OriginalPowerScheme,$PendingGuid)
    return $true

}

function Start-VSO7PowerSchemeMutationVSO {

    param([Parameter(Mandatory=$true)][string]$PendingGuid)
    $baseline=[string](Get-ActivePowerSchemeGuid)
    if([string]::IsNullOrWhiteSpace($baseline)){
        throw 'No se pudo capturar el plan activo inmediatamente antes de la transaccion.'
    }
    $previousOriginal=[string]$script:State.OriginalPowerScheme
    $previousApplied=[string]$script:State.AppliedPowerScheme
    $previousPending=[string]$script:State.PendingPowerScheme

    if(-not[string]::IsNullOrWhiteSpace($previousPending)){

        # Un Pending de energia puede representar un crash antes o despues de setactive. No se
        # inicia otra transaccion encima: primero debe reconciliarse el estado existente.
        throw ("Existe una transaccion de energia Pending ({0}); revierte/reconcilia antes de iniciar otra."-f$previousPending)

    }
    if(-not[string]::IsNullOrWhiteSpace($previousOriginal)){

        $matchesOriginal=($baseline-ieq$previousOriginal)
        $matchesApplied=(-not[string]::IsNullOrWhiteSpace($previousApplied)-and$baseline-ieq$previousApplied)
        if(-not($matchesOriginal-or$matchesApplied)){

            # El plan que VSO7 poseia fue sustituido externamente. El usuario esta iniciando una
            # nueva mutacion explicita: se libera el ownership viejo sin restaurarlo y se adopta
            # el plan externo actual como nuevo baseline.
            $script:State.OriginalPowerScheme=$baseline
            $script:State.AppliedPowerScheme=$null
            $script:State.PendingPowerScheme=$null
            Save-State
            $previousOriginal=$baseline;
            $previousApplied=$null;
            $previousPending=$null
            Write-VSO7Log ("El plan de energia cambio externamente; se adopta el plan actual {0} como nuevo baseline antes de la nueva mutacion."-f$baseline) 'WARN'

        }

    }

    $rollbackOriginal=$script:State.OriginalPowerScheme
    $rollbackApplied=$script:State.AppliedPowerScheme
    $rollbackPending=$script:State.PendingPowerScheme
    Backup-PowerScheme -PendingGuid $PendingGuid | Out-Null
    $recheck=[string](Get-ActivePowerSchemeGuid)
    if([string]::IsNullOrWhiteSpace($recheck)-or$recheck-ine$baseline){

        $script:State.OriginalPowerScheme=$rollbackOriginal
        $script:State.AppliedPowerScheme=$rollbackApplied
        $script:State.PendingPowerScheme=$rollbackPending
        Save-State
        throw 'El plan activo cambio entre snapshot y mutacion; VSO7 retiro su Pending sin cambiar energia.'

    }
    return [pscustomobject]@{

        Baseline=$baseline
        RollbackOriginal=$rollbackOriginal
        RollbackApplied=$rollbackApplied
        RollbackPending=$rollbackPending

    }

}

function Assert-VSO7PowerSchemeMutationStillSafeVSO {

    param([Parameter(Mandatory=$true)]$Transaction)
    $baseline=[string]$Transaction.Baseline
    if([string]::IsNullOrWhiteSpace($baseline)-or-not(Test-VSO7PowerSchemeGuid $baseline)){
        throw 'Transaccion de energia sin baseline valido.'
    }
    $current=[string](Get-ActivePowerSchemeGuid)
    if([string]::IsNullOrWhiteSpace($current)){

        # No se ha tocado Windows todavía: recuperamos exactamente el estado de ownership
        # anterior a preparar este Pending y abortamos.
        $script:State.OriginalPowerScheme=$Transaction.RollbackOriginal
        $script:State.AppliedPowerScheme=$Transaction.RollbackApplied
        $script:State.PendingPowerScheme=$Transaction.RollbackPending
        Save-State
        throw 'No se pudo revalidar el plan activo inmediatamente antes de setactive; VSO7 retiro su nuevo Pending sin tocar energia.'

    }
    if($current-ine$baseline){

        # Otro actor cambio el plan despues de la primera revalidacion y antes de nuestro
        # write. Como VSO7 aun NO llamo a setactive, no existe mutacion nuestra que revertir:
        # liberamos ownership de energia para no pisar el nuevo plan externo.
        $script:State.OriginalPowerScheme=$null
        $script:State.AppliedPowerScheme=$null
        $script:State.PendingPowerScheme=$null
        Save-State
        throw ("El plan activo cambio externamente a {0} justo antes de setactive; VSO7 libera ownership y no lo sobrescribe."-f$current)

    }
    return $true

}

function Test-HasBattery {

    try {

        $battery = @(CimCmdlets\Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop)
        return ($battery.Count -gt 0)

    } catch {

        Write-VSO7Log ("No se pudo determinar de forma fiable si el equipo tiene bateria: {0}"-f$_.Exception.Message) 'WARN'
        return $null

    }

}

function Set-HighPerformanceIfSafe {

    $batteryState=Test-HasBattery
    if ($true -eq $batteryState) {

        Write-VSO7Log 'Se detecto bateria/portatil: el preset no cambiara automaticamente el plan de energia.' 'WARN'
        return $true

    }
    if($null-eq$batteryState){

        Write-VSO7Log 'Estado de bateria desconocido: VSO7 conserva el plan de energia actual por seguridad.' 'WARN'
        return $true

    }

    $active = Get-ActivePowerSchemeInfo
    if ($active.IsCustom) {

        $displayName = if ($active.Name) {
            $active.Name
        } else {
            $active.Guid
        }
        Write-VSO7Log ("Plan personalizado detectado: '{0}'. Se conserva sin cambios." -f $displayName) 'WARN'
        return $true

    }
    if ($active.BuiltInName -eq 'HighPerformance' -or $active.BuiltInName -eq 'Ultimate') {

        Write-VSO7Log 'El plan actual ya es de alto rendimiento. No se cambia.'
        return $true

    }

    $highPerfGuid = $script:BuiltInPowerSchemes.HighPerformance
    $schemes = Get-AllPowerSchemes
    if (@($schemes | Where-Object {
        $_.Guid -eq $highPerfGuid
    }).Count -eq 0) {

        Write-VSO7Log 'El plan Alto rendimiento no existe actualmente; se conserva el plan actual.' 'WARN'
        return $true

    }

    $powerTransaction=Start-VSO7PowerSchemeMutationVSO -PendingGuid $highPerfGuid
    [void](Assert-VSO7PowerSchemeMutationStillSafeVSO -Transaction $powerTransaction)
    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive',$highPerfGuid)
    $after = Get-ActivePowerSchemeGuid
    if ([string]$after -ine [string]$highPerfGuid) {
        throw 'Windows no dejo activo el plan Alto rendimiento solicitado.'
    }
    $script:State.AppliedPowerScheme=$highPerfGuid;
    $script:State.PendingPowerScheme=$null;
    Save-State
    Write-VSO7Log 'Plan de energia cambiado y verificado: Alto rendimiento.' 'CHANGE'
    return $true

}

function Set-PowerSchemeExplicit {

    param([Parameter(Mandatory=$true)][string]$Guid,[string]$Name)
    if ([string]::IsNullOrWhiteSpace($Guid)) {
        throw 'GUID de plan vacio.'
    }
    $known = @(Get-AllPowerSchemes | Where-Object {
        $_.Guid -ieq $Guid
    })
    if ($known.Count -eq 0) {
        throw 'El plan seleccionado ya no aparece en powercfg /list.'
    }
    $powerTransaction=Start-VSO7PowerSchemeMutationVSO -PendingGuid $Guid
    [void](Assert-VSO7PowerSchemeMutationStillSafeVSO -Transaction $powerTransaction)
    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive',$Guid)
    if ([string](Get-ActivePowerSchemeGuid) -ine [string]$Guid) {
        throw 'No se pudo verificar el plan de energia seleccionado.'
    }
    $script:State.AppliedPowerScheme=$Guid;
    $script:State.PendingPowerScheme=$null;
    Save-State
    Write-VSO7Log ("Plan de energia activado/verificado: {0} ({1})" -f $Name,$Guid) 'CHANGE'

}

function Restore-PowerScheme {

    $original=[string]$script:State.OriginalPowerScheme
    if([string]::IsNullOrWhiteSpace($original)){
        Write-VSO7Log 'No hay plan de energia original guardado.';
        return $true
    }
    try{

        if(@(Get-AllPowerSchemes|Where-Object{
            $_.Guid-ieq$original
        }).Count-eq0){
            throw 'El plan original ya no existe.'
        }
        $current=[string](Get-ActivePowerSchemeGuid);
        if([string]::IsNullOrWhiteSpace($current)){
            throw 'No se pudo determinar el plan activo.'
        }
        $applied=[string]$script:State.AppliedPowerScheme;
        $pending=[string]$script:State.PendingPowerScheme
        if($current-ieq$original){
            Write-VSO7Log 'El plan original ya esta activo; se libera ownership.' 'INFO'
        }
        elseif(((-not[string]::IsNullOrWhiteSpace($applied))-and$current-ieq$applied)-or((-not[string]::IsNullOrWhiteSpace($pending))-and$current-ieq$pending)){

            Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive',$original)|Out-Null
            if([string](Get-ActivePowerSchemeGuid)-ine$original){
                throw 'El plan activo no coincide con el baseline.'
            }
            Write-VSO7Log ("Plan de energia restaurado/verificado: {0}"-f$original) 'CHANGE'

        }else{

            if(-not[string]::IsNullOrWhiteSpace($pending)){
                throw ("Energia normal Pending ambigua: plan actual {0} no coincide con baseline/aplicado/pendiente; se conserva evidencia."-f$current)
            }
            Write-VSO7Log ("No se restaura energia normal: cambio externo detectado ({0}) tras estado confirmado; se libera ownership sin sobrescribir."-f$current) 'WARN'

        }
        $script:State.OriginalPowerScheme=$null;
        $script:State.AppliedPowerScheme=$null;
        $script:State.PendingPowerScheme=$null;
        Save-State;
        return $true

    }catch{
        Write-VSO7Log ("Error restaurando el plan de energia: {0}"-f$_.Exception.Message) 'ERROR';
        return $false
    }

}

function Show-PowerPlanManager {

    while ($true) {

        Write-Title
        Write-CenteredLineVSO -Text 'PLANES DE ENERGIA' -Color $script:ThemeCopper
        Write-VSOHost ''
        Write-CenteredLineVSO -Text 'VSO7 no modifica el contenido de tus planes: aqui solo eliges cual queda activo.' -Color 'Green'
        Write-CenteredLineVSO -Text 'Los planes personalizados u OEM se respetan y se identifican claramente.' -Color $script:ThemeText
        Write-VSOHost ''

        $schemes = @(Get-AllPowerSchemes)
        if ($schemes.Count -eq 0) {

            Write-CenteredLineVSO -Text 'No se pudieron enumerar los planes de energia.' -Color $script:ThemeDanger
            Pause-Vico
            return

        }

        $powerRows = @()
        for ($i = 0; $i -lt $schemes.Count; $i++) {

            $plan=$schemes[$i]
            $marker=if($plan.Active){
                $(Get-VSO7ConsoleTextVSO -Es ' [ACTIVO]' -En ' [ACTIVE]')
            }else{
                ''
            }
            $type=if($plan.IsBuiltIn){
                'Windows'
            }else{
                $(Get-VSO7ConsoleTextVSO -Es 'Personalizado/OEM' -En 'Custom/OEM')
            }
            $desc=($(Get-VSO7ConsoleTextVSO -Es "Tipo: {0}. Seleccionarlo solo cambia el plan activo; VSO7 no edita sus valores." -En "Type: {0}. Selecting it only changes the active plan; VSO7 does not edit its settings.") -f $type)
            $powerRows += [pscustomobject]@{
                Text=("[{0}] {1}{2}" -f ($i+1),$plan.Name,$marker);
                Color=$(if($plan.Active){
                    'Green'
                }else{
                    'Gray'
                });
                Description=$desc
            }

        }
        Write-VSO7TwoColumnOptionsVSO -Items $powerRows

        $restoreNumber=$schemes.Count+1
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Restaurar el plan original' -En '[{0}] Restore the original power plan') -f $restoreNumber);Color='Yellow';Description='Vuelve al plan que estaba activo antes del primer cambio realizado por VSO7.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa al menu anterior sin cambiar el plan.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Elige una opcion'
        if($choice-eq'0'){
            return
        }
        $number=0
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }

        if($number-eq$restoreNumber){

            Load-State
            $restorePowerOk=[bool](Restore-PowerScheme)
            if($restorePowerOk){
                Write-CenteredLineVSO -Text 'Plan de energia original restaurado, verificado o ya reconciliado.' -Color $script:ThemeSuccess
            }
            else{
                Write-CenteredLineVSO -Text 'No se pudo completar la restauracion; VSO7 conserva el estado pendiente para no perder recuperacion.' -Color $script:ThemeDanger
            }
            Pause-Vico;
            continue

        }

        if($number-ge1-and$number-le$schemes.Count){

            $selected=$schemes[$number-1]
            if($selected.Active){
                Write-CenteredLineVSO -Text 'Ese plan ya esta activo.' -Color $script:ThemeMuted;
                Pause-Vico;
                continue
            }
            Write-VSOHost ''
            Write-CenteredLineVSO -Text ((Convert-VSOText -Value $(Get-VSO7ConsoleTextVSO -Es 'Vas a activar:' -En 'You are about to activate:'))+' '+[string]$selected.Name) -Color $script:ThemeWarning
            if(-not$selected.IsBuiltIn){
                Write-CenteredLineVSO -Text 'Es un plan personalizado/OEM. VSO7 no modifica su contenido; solo lo selecciona.' -Color 'Cyan'
            }
            $answer=Read-CenteredPromptVSO -Text '¿Activar este plan? [S/N]'
            if($answer-match'^[sSyY]$'){
                Load-State;
                Set-PowerSchemeExplicit -Guid $selected.Guid -Name $selected.Name
            }
            Pause-Vico

        }

    }

}

function Get-LatestRestorePointStrictVSO {

    $points = @(Microsoft.PowerShell.Management\Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber -Descending)
    if ($points.Count -gt 0) {
        return $points[0]
    }
    return $null

}

function Get-LatestRestorePoint {

    try {
        return (Get-LatestRestorePointStrictVSO)
    } catch {
        return $null
    }

}

function Convert-RestorePointDate {

    param($RestorePoint)

    if ($null -eq $RestorePoint) {
        return $null
    }

    try {

        return [Management.ManagementDateTimeConverter]::ToDateTime([string]$RestorePoint.CreationTime)

    } catch {

        try {
            return [datetime]$RestorePoint.CreationTime
        } catch {
            return $null
        }

    }

}

function Test-RecentRestorePoint {

    param([int]$Hours = 24)

    $latest = Get-LatestRestorePoint
    if ($null -eq $latest) {
        return $false
    }

    $date = Convert-RestorePointDate -RestorePoint $latest
    if ($null -eq $date) {
        return $false
    }

    return ($date -ge (Get-Date).AddHours(-$Hours))

}

function New-SafeRestorePoint {

    param([switch]$ForceAttempt)

    Write-VSOHost ''
    Write-VSOHost 'Comprobando Restauracion del sistema...' -ForegroundColor Cyan

    if (-not $ForceAttempt -and (Test-RecentRestorePoint -Hours 24)) {

        $latest = Get-LatestRestorePoint
        $date = Convert-RestorePointDate -RestorePoint $latest
        Write-VSO7Log ("Ya existe un punto de restauracion reciente ({0})." -f $date)
        return $true

    }

    # 7.0.0 no habilita automaticamente Proteccion del sistema: hacerlo seria
    # una mutacion persistente cuya restauracion segura no es trivial (deshabilitarla
    # despues puede eliminar puntos). Si Windows la tiene deshabilitada,
    # Checkpoint-Computer fallara y VSO7 cancelara sin cambiar esa configuracion.

    # Para EXTREMO la foto previa debe ser fiable: sin ella no podemos demostrar
    # que el punto observado despues sea realmente nuevo.
    $before=$null
    if($ForceAttempt){

        try{
            $before=Get-LatestRestorePointStrictVSO
        }catch{
            Write-VSO7Log ("No se pudo enumerar de forma fiable el Restore Point previo: {0}"-f$_.Exception.Message) 'ERROR';
            return $false
        }

    }else{

        $before=Get-LatestRestorePoint

    }
    $beforeSequence = if ($null -ne $before) {
        [int64]$before.SequenceNumber
    } else {
        -1
    }

    # En modo extremo exigimos un punto NUEVO. El override temporal se registra
    # ANTES de escribirlo en state.json protegido, para que un crash deje evidencia
    # suficiente y la siguiente ejecucion/Recovery pueda reconciliarlo.
    if ($ForceAttempt) {

        try {

            $frequencyPath='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'
            if(-not(Test-Path -LiteralPath $frequencyPath)){
                throw 'La configuracion de Restauracion del sistema no existe; habilita Proteccion del sistema manualmente y vuelve a intentarlo.'
            }
            Set-TrackedRegistryValue -Path $frequencyPath -Name 'SystemRestorePointCreationFrequency' -Value 0 -Type DWord

        } catch {

            Write-VSO7Log ("No se pudo preparar de forma transaccional la creacion obligatoria del punto de restauracion: {0}" -f $_.Exception.Message) 'ERROR'
            [void](Repair-VSO7RestorePointFrequencyTransactionVSO)
            return $false

        }

    }
    $created = $false

    try {

        $description = "VSO7 - {0}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
        Microsoft.PowerShell.Management\Checkpoint-Computer -Description $description -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
        Start-Sleep -Seconds 1

        $after = if($ForceAttempt){
            Get-LatestRestorePointStrictVSO
        }else{
            Get-LatestRestorePoint
        }
        if ($null -ne $after) {

            $afterSequence = [int64]$after.SequenceNumber
            $afterDate = Convert-RestorePointDate -RestorePoint $after
            if ($ForceAttempt) {

                $created = ($afterSequence -ne $beforeSequence -and $afterDate -ge (Get-Date).AddMinutes(-5))

            } else {

                $created = ($afterDate -ge (Get-Date).AddHours(-24))

            }

        }

    } catch {

        Write-VSO7Log ("Checkpoint-Computer fallo: {0}" -f $_.Exception.Message) 'ERROR'

    } finally {

        if ($ForceAttempt) {

            if(-not[bool](Repair-VSO7RestorePointFrequencyTransactionVSO)){

                Write-VSO7Log 'ATENCION: no se pudo cerrar la transaccion temporal de SystemRestorePointCreationFrequency.' 'ERROR'
                $created = $false

            }

        }

    }

    if ($created) {

        Write-VSO7Log 'Punto de restauracion creado y verificado.' 'CHANGE'
        return $true

    }

    if ($ForceAttempt) {

        Write-VSO7Log 'Modo extremo cancelado: no se pudo verificar la creacion de un punto NUEVO.' 'ERROR'

    } else {

        Write-VSO7Log 'No se pudo verificar un punto de restauracion reciente.' 'ERROR'

    }
    return $false

}

function Require-RestorePoint {

    param([switch]$Aggressive)

    $ok = if ($Aggressive) {
        New-SafeRestorePoint -ForceAttempt
    } else {
        New-SafeRestorePoint
    }
    if ($ok) {
        return $true
    }

    Write-VSOHost ''
    if ($Aggressive) {

        Write-VSOHost 'MODO AGRESIVO/EXTREMO CANCELADO.' -ForegroundColor Red

    } else {

        Write-VSOHost 'OPTIMIZACIÓN CANCELADA.' -ForegroundColor Red

    }

    Write-VSOHost 'No se aplicarán cambios sin un punto de restauración reciente.' -ForegroundColor Yellow
    Write-VSOHost 'Abre "Crear un punto de restauración", habilita Protección del sistema y vuelve a intentarlo.'
    return $false

}

function Remove-OldTempFiles {

    param([int]$OlderThanDays = 7)

    $cutoff = (Get-Date).AddDays(-$OlderThanDays)
    $paths=@()
    try{
        if($script:LocalAppData){
            $paths += Join-ValidatedDescendantPathVSO -Base ([string]$script:LocalAppData) -Relative 'Temp'
        }
    }catch{}
    try{
        if($script:WindowsRoot){
            $paths += Join-ValidatedDescendantPathVSO -Base ([string]$script:WindowsRoot) -Relative 'Temp'
        }
    }catch{}
    $paths=@($paths|Select-Object -Unique)
    $deletedCount = 0
    [int64]$deletedBytes = 0

    foreach ($path in $paths) {

        try{
            $safeRoot=Assert-CleanupPathAllowedVSO -Path $path
        }catch{
            Write-VSO7Log ("Se omite temporal fuera de allowlist: {0}"-f$path) 'WARN';
            continue
        }
        if (-not (Test-Path -LiteralPath $safeRoot -PathType Container)) {
            continue
        }
        $root = Get-Item -LiteralPath $safeRoot -Force -ErrorAction SilentlyContinue
        if ($null -eq $root -or (($root.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {

            Write-VSO7Log ("Se omite temporal inseguro/reparse point: {0}" -f $safeRoot) 'WARN'
            continue

        }
        Write-VSO7Log ("Limpiando temporales de mas de {0} dias en {1}" -f $OlderThanDays,$safeRoot)
        foreach ($file in @(Get-FilesNoReparseVSO -Root $safeRoot)) {

            if ($file.LastWriteTime -ge $cutoff) {
                continue
            }
            try {

                $size = [int64]$file.Length
                Remove-VSO7CleanupFileSafeVSO -Path $file.FullName -AllowedRoot $safeRoot
                $deletedCount++
                $deletedBytes += $size

            } catch {
                Write-VSO7Log ("No se pudo borrar temporal de forma segura: {0} ({1})"-f$file.FullName,$_.Exception.Message) 'WARN'
            }

        }

    }
    Write-VSO7Log ("Temporales eliminados: {0} archivos, aprox. {1} MB." -f $deletedCount,[math]::Round($deletedBytes/1MB,1)) 'CHANGE'

}

function Enable-GameMode {

    $nativeState=Get-VSO7ExtremeNativeOwnershipStateVSO -TweakId 'gaming.gamemode'
    if($nativeState-eq'AlreadyApplied'){
        Write-VSO7Log 'Game Mode ya estaba aplicado y protegido por Recovery nativo; se conserva su rollback original.' 'INFO'
        return 'AlreadyApplied'
    }
    if($nativeState-eq'Conflict'){
        throw 'Una sesion Recovery nativa posee Game Mode con un estado diferente o ambiguo; restaura o revisa esa sesion antes de modificarlo.'
    }
    Set-TrackedRegistryValue `
        -Path 'HKCU:\Software\Microsoft\GameBar' `
        -Name 'AutoGameModeEnabled' `
        -Value 1 `
        -Type DWord
    return 'Applied'

}

function Disable-BackgroundGameCapture {

    Set-TrackedRegistryValue `
        -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' `
        -Name 'AppCaptureEnabled' `
        -Value 0 `
        -Type DWord

    Set-TrackedRegistryValue `
        -Path 'HKCU:\System\GameConfigStore' `
        -Name 'GameDVR_Enabled' `
        -Value 0 `
        -Type DWord

}

function Disable-Transparency {

    Set-TrackedRegistryValue `
        -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' `
        -Name 'EnableTransparency' `
        -Value 0 `
        -Type DWord

}

function Disable-WindowAnimations {

    Set-TrackedRegistryValue `
        -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' `
        -Name 'VisualFXSetting' `
        -Value 2 `
        -Type DWord

    Set-TrackedRegistryValue `
        -Path 'HKCU:\Control Panel\Desktop\WindowMetrics' `
        -Name 'MinAnimate' `
        -Value '0' `
        -Type String

    Write-VSO7Log 'Los cambios de animaciones pueden requerir cerrar sesión o reiniciar para aplicarse completamente.' 'WARN'

}

function Apply-AggressiveVisualSettings {

    Disable-Transparency
    Disable-WindowAnimations

}

function Get-RegValueFriendly {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Name)
    try{

        $snapshot=Get-RegistrySnapshot -Path $Path -Name $Name
        if(-not[bool]$snapshot.Exists){
            return '<no configurado>'
        }
        return $snapshot.Value

    }catch{
        return '<no disponible>'
    }

}

function Get-StartupEntries {

    try {

        return @(CimCmdlets\Get-CimInstance Win32_StartupCommand -ErrorAction SilentlyContinue |
            Sort-Object Name |
            Select-Object Name, Command, Location, User)

    } catch {

        return @()

    }

}

function Get-VSO7StartupRegistryPaths {

    return @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
    )

}

function Get-VSO7StartupFolderRoots {

    $roots=@()
    foreach($candidate in @(
        $(if([string]::IsNullOrWhiteSpace([string]$script:AppData)){
        $null
    }else{
        Join-Path $script:AppData 'Microsoft\Windows\Start Menu\Programs\Startup'
    }),
        $(if([string]::IsNullOrWhiteSpace([string]$script:ProgramData)){
        $null
    }else{
        Join-Path $script:ProgramData 'Microsoft\Windows\Start Menu\Programs\Startup'
    })
    )){

        if([string]::IsNullOrWhiteSpace([string]$candidate)){
            continue
        }
        $full=[IO.Path]::GetFullPath([string]$candidate).TrimEnd('\')
        if($full-notmatch'^[A-Za-z]:\\'){
            continue
        }
        $roots += $full

    }
    return @($roots|Select-Object -Unique)

}

function Get-VSO7StartupStashRoot {

    if([string]::IsNullOrWhiteSpace([string]$script:StartupStateFile)){
        throw 'StartupStateFile no esta inicializado.'
    }
    $stateParent=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$script:StartupStateFile))
    if([string]::IsNullOrWhiteSpace($stateParent)){
        throw 'No se pudo determinar el directorio de startup-state.json.'
    }
    return [IO.Path]::GetFullPath((Join-Path $stateParent 'StartupDisabled')).TrimEnd('\')

}

function Assert-VSO7LocalPathChainNoReparseVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        throw 'Ruta local invalida/no absoluta.'
    }
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if($full-notmatch'^[A-Za-z]:\\'){
        throw ("VSO7 rechaza rutas UNC/redirigidas para esta operacion elevada: {0}"-f$full)
    }
    $root=[IO.Path]::GetPathRoot($full)
    if([string]::IsNullOrWhiteSpace($root)){
        throw 'No se pudo determinar la raiz local.'
    }
    $root=$root.TrimEnd('\')+'\'
    $rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop
    if(($rootItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw ("La raiz local es reparse point: {0}"-f$root)
    }
    $relative=$full.Substring($root.Length).Trim('\')
    $cursor=$root.TrimEnd('\')
    if(-not[string]::IsNullOrWhiteSpace($relative)){

        foreach($part in @($relative.Split('\'))){

            if([string]::IsNullOrWhiteSpace([string]$part)-or[string]$part-eq'.'-or[string]$part-eq'..'){
                throw 'Componente de ruta local invalido.'
            }
            $cursor=Join-Path $cursor ([string]$part)
            $item=Get-Item -LiteralPath $cursor -Force -ErrorAction Stop
            if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ("Reparse point detectado en la cadena de ruta: {0}"-f$cursor)
            }

        }

    }
    return $full

}

function Test-VSO7StartupDirectChildPath {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string[]]$AllowedParents)
    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        return $false
    }
    try{

        $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
        $parent=[IO.Path]::GetDirectoryName($full)
        if([string]::IsNullOrWhiteSpace($parent)){
            return $false
        }
        foreach($allowed in @($AllowedParents)){

            if([string]::IsNullOrWhiteSpace($allowed)){
                continue
            }
            if([IO.Path]::GetFullPath($allowed).TrimEnd('\') -ieq [IO.Path]::GetFullPath($parent).TrimEnd('\')){
                return $true
            }

        }

    }catch{
        return $false
    }
    return $false

}

function Assert-VSO7StartupPathRuntimeSafe {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string[]]$AllowedParents,
        [switch]$AllowMissingLeaf
    )
    if(-not(Test-VSO7StartupDirectChildPath -Path $Path -AllowedParents $AllowedParents)){
        throw ("Ruta de Inicio fuera de la allowlist: {0}"-f$Path)
    }
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    $parent=[IO.Path]::GetDirectoryName($full)
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $parent)
    $parentItem=Get-Item -LiteralPath $parent -Force -ErrorAction Stop
    if(($parentItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw ("Directorio de Inicio/stash es reparse point: {0}"-f$parent)
    }
    if(Test-Path -LiteralPath $full){

        $leaf=Get-Item -LiteralPath $full -Force -ErrorAction Stop
        if(($leaf.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw ("Entrada de Inicio es reparse point: {0}"-f$full)
        }
        if($leaf.PSIsContainer){
            throw 'La entrada de Inicio no es un archivo.'
        }

    }elseif(-not$AllowMissingLeaf){
        throw ("No existe la entrada de Inicio: {0}"-f$full)
    }
    return $full

}

function ConvertTo-VSO7ValidatedStartupState {

    param($Object)
    if($null-eq$Object){
        throw 'startup-state.json esta vacio.'
    }
    $props=@($Object.PSObject.Properties|ForEach-Object{
        [string]$_.Name
    })
    $isV2=($props-contains'SchemaVersion')
    $required=if($isV2){
        @('SchemaVersion','Version','CreatedAt','Disabled')
    }else{
        @('Version','CreatedAt','Disabled')
    }
    if(-not(Test-VSO7ExactJsonProperties -Object $Object -Required $required)){
        throw 'startup-state.json no coincide con un esquema reconocido.'
    }
    if($isV2-and-not(Test-VSO7JsonInteger -Value $Object.SchemaVersion -Min 2 -Max 2)){
        throw 'SchemaVersion de Startup incompatible.'
    }
    if(-not($Object.Version-is[string])-or[string]::IsNullOrWhiteSpace([string]$Object.Version)-or([string]$Object.Version).Length-gt32){
        throw 'Version de Startup invalida.'
    }
    if($isV2-and[string]$Object.Version-cne[string]$script:Version){
        throw ('startup-state.json pertenece a VSO7 {0}; esta build exige estado schema v2 de VSO7 {1}.'-f[string]$Object.Version,[string]$script:Version)
    }
    if(-not($Object.CreatedAt-is[string])-or-not(Test-VSO7IsoUtcTimestamp ([string]$Object.CreatedAt))){
        throw 'CreatedAt de Startup invalido.'
    }
    if($null-eq$Object.Disabled-or$Object.Disabled-is[string]){
        throw 'Disabled de Startup invalido.'
    }
    $items=@($Object.Disabled);
    if($items.Count-gt512){
        throw 'Demasiadas entradas en startup-state.json.'
    }
    if(-not$isV2-and$items.Count-gt0){
        throw 'startup-state.json legado contiene rollback sin evidencia fuerte de ownership; 7.0.0 no lo ejecuta automaticamente.'
    }
    $normalized=@();
    $seen=@{}
    $registryPaths=@(Get-VSO7StartupRegistryPaths)
    $startupRoots=@(Get-VSO7StartupFolderRoots)
    $stashRoot=Get-VSO7StartupStashRoot
    foreach($entry in $items){

        $names=@($entry.PSObject.Properties|ForEach-Object{
            [string]$_.Name
        })
        $hasStatus=($names-contains'Status');
        $hasBackupName=($names-contains'BackupName')
        $base=@('Id','Type','Name','RegistryPath','Value','Kind','OriginalPath','BackupPath','Sha256','DisabledAt')
        $req=@($base);
        if($hasStatus){
            $req+='Status'
        };
        if($hasBackupName){
            $req+='BackupName'
        }
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'Entrada de Startup con esquema invalido.'
        }
        if(-not($entry.Id-is[string])-or-not($entry.Type-is[string])-or-not($entry.Name-is[string])){
            throw 'Id/Type/Name de Startup invalidos.'
        }
        $name=[string]$entry.Name;
        if([string]::IsNullOrWhiteSpace($name)-or$name.Length-gt512-or$name.IndexOf([char]0)-ge0-or$name.Contains("`r")-or$name.Contains("`n")){
            throw 'Nombre de Startup invalido.'
        }
        $status=if($hasStatus){
            [string]$entry.Status
        }else{
            'Disabled'
        };
        if(@('Pending','Disabled','RestorePending')-notcontains$status){
            throw 'Status de Startup invalido.'
        }
        if(-not($entry.DisabledAt-is[string])-or-not(Test-VSO7IsoUtcTimestamp ([string]$entry.DisabledAt))){
            throw 'DisabledAt de Startup invalido.'
        }
        if([string]$entry.Type-ieq'Registry'){

            if(-not($entry.RegistryPath-is[string])-or$registryPaths-notcontains[string]$entry.RegistryPath){
                throw 'RegistryPath de Startup fuera de allowlist.'
            }
            if(-not($entry.Kind-is[string])-or@('String','ExpandString')-notcontains[string]$entry.Kind){
                throw 'Solo String/ExpandString son validos en claves Run.'
            }
            if(-not($entry.Value-is[string])-or([string]$entry.Value).Length-gt32767){
                throw 'Valor de Startup Registry invalido.'
            }
            $expectedId='REG|'+[string]$entry.RegistryPath+'|'+$name;
            if([string]$entry.Id-ine$expectedId){
                throw 'Id de Startup Registry no coincide con su destino.'
            }
            if($null-ne$entry.OriginalPath-or$null-ne$entry.BackupPath-or$null-ne$entry.Sha256){
                throw 'Startup Registry contiene campos de archivo.'
            }
            if($hasBackupName-and$null-ne$entry.BackupName){
                throw 'BackupName debe ser null para Startup Registry.'
            }
            $norm=[pscustomobject]@{
                Id=$expectedId;
                Type='Registry';
                Name=$name;
                RegistryPath=[string]$entry.RegistryPath;
                Value=[string]$entry.Value;
                Kind=[string]$entry.Kind;
                OriginalPath=$null;
                BackupPath=$null;
                BackupName=$null;
                Sha256=$null;
                Status=$status;
                DisabledAt=[string]$entry.DisabledAt
            }

        }elseif([string]$entry.Type-ieq'File'){

            if($null-ne$entry.RegistryPath-or$null-ne$entry.Value-or$null-ne$entry.Kind){
                throw 'Startup File contiene campos Registry.'
            }
            if(-not($entry.OriginalPath-is[string])-or-not($entry.Sha256-is[string])){
                throw 'Rutas/hash de Startup File invalidos.'
            }
            $original=[IO.Path]::GetFullPath([string]$entry.OriginalPath).TrimEnd('\')
            if(-not(Test-VSO7StartupDirectChildPath -Path $original -AllowedParents $startupRoots)){
                throw 'OriginalPath de Startup fuera de carpetas Startup.'
            }
            if($hasBackupName){

                if(-not($entry.BackupName-is[string])){
                    throw 'BackupName de Startup invalido.'
                }
                $backupName=[string]$entry.BackupName
                if([string]::IsNullOrWhiteSpace($backupName)-or$backupName.Length-gt512-or[IO.Path]::GetFileName($backupName)-ine$backupName){
                    throw 'BackupName de Startup invalido.'
                }
                if($null-ne$entry.BackupPath){

                    if(-not($entry.BackupPath-is[string])-or([string]$entry.BackupPath).Length-gt32767-or[string]::IsNullOrWhiteSpace([string]$entry.BackupPath)){
                        throw 'BackupPath legacy de Startup invalido.'
                    }
                    if([IO.Path]::GetFileName([string]$entry.BackupPath)-ine$backupName){
                        throw 'BackupPath legacy no coincide con BackupName.'
                    }

                }

            }else{

                if(-not($entry.BackupPath-is[string])-or[string]::IsNullOrWhiteSpace([string]$entry.BackupPath)){
                    throw 'Falta BackupName/BackupPath de Startup File.'
                }
                $legacyBackup=[IO.Path]::GetFullPath([string]$entry.BackupPath).TrimEnd('\')
                if(-not(Test-VSO7StartupDirectChildPath -Path $legacyBackup -AllowedParents @($stashRoot))){
                    throw 'BackupPath legacy de Startup fuera del stash gestionado.'
                }
                $backupName=[IO.Path]::GetFileName($legacyBackup)

            }
            $backup=[IO.Path]::GetFullPath((Join-Path $stashRoot $backupName)).TrimEnd('\')
            if(-not(Test-VSO7StartupDirectChildPath -Path $backup -AllowedParents @($stashRoot))){
                throw 'Backup Startup reconstruido fuera del stash gestionado.'
            }
            if([IO.Path]::GetFileNameWithoutExtension($original)-ine$name){
                throw 'Name de Startup File no coincide con OriginalPath.'
            }
            $expectedId='FILE|'+$original;
            if([string]$entry.Id-ine$expectedId){
                throw 'Id de Startup File no coincide con OriginalPath.'
            }
            $sha=([string]$entry.Sha256).ToUpperInvariant();
            if($sha-notmatch'^[0-9A-F]{64}$'){
                throw 'SHA-256 de Startup File invalido.'
            }
            $norm=[pscustomobject]@{
                Id=$expectedId;
                Type='File';
                Name=$name;
                RegistryPath=$null;
                Value=$null;
                Kind=$null;
                OriginalPath=$original;
                BackupPath=$backup;
                BackupName=$backupName;
                Sha256=$sha;
                Status=$status;
                DisabledAt=[string]$entry.DisabledAt
            }

        }else{
            throw 'Type de Startup no soportado.'
        }
        $key=([string]$norm.Id).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'Entrada Startup duplicada.'
        };
        $seen[$key]=$true;
        $normalized+=$norm

    }
    return @{
        SchemaVersion=2;
        Version=[string]$Object.Version;
        CreatedAt=[string]$Object.CreatedAt;
        Disabled=$normalized
    }

}

function New-EmptyStartupState {

    return @{
        SchemaVersion=2;
        Version=$script:Version;
        CreatedAt=(Get-Date).ToString('o');
        Disabled=@()
    }

}

function Load-StartupState {

    if(-not(Test-Path -LiteralPath $script:StartupStateFile -PathType Leaf)){
        $script:StartupState=New-EmptyStartupState;
        return
    }
    try{

        $o=Get-Content -LiteralPath $script:StartupStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        $script:StartupState=ConvertTo-VSO7ValidatedStartupState -Object $o
        Resolve-PendingStartupStateVSO

    }catch{

        Write-VSO7Log ("No se pudo validar startup-state.json: {0}"-f$_.Exception.Message) 'ERROR'
        throw 'VSO7 no continuara con el gestor de Inicio sin poder validar semanticamente su rollback anterior.'

    }

}

function Export-StartupStateToBundleVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle)
    $bundleFull=Assert-VSO7ManagedRecoveryBundleVSO -Path $Bundle
    $bundleItem=Get-Item -LiteralPath $bundleFull -Force -ErrorAction Stop
    if(($bundleItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'El bundle de Recovery es un reparse point.'
    }
    $destState=Join-Path $bundleFull 'startup-state.json'
    $bundleStash=Join-Path $bundleFull 'StartupDisabled'
    $exported=@()
    foreach($entry in @($script:StartupState.Disabled)){

        if([string]$entry.Type-ieq'Registry'){

            $exported += [pscustomobject]@{
                Id=[string]$entry.Id;
                Type='Registry';
                Name=[string]$entry.Name;
                RegistryPath=[string]$entry.RegistryPath;
                Value=[string]$entry.Value;
                Kind=[string]$entry.Kind;
                OriginalPath=$null;
                BackupPath=$null;
                BackupName=$null;
                Sha256=$null;
                Status=[string]$entry.Status;
                DisabledAt=[string]$entry.DisabledAt
            }
            continue

        }
        if([string]$entry.Type-ine'File'){
            throw 'Tipo Startup inesperado exportando Recovery.'
        }
        New-Item -ItemType Directory -Path $bundleStash -Force -ErrorAction Stop|Out-Null
        $stashItem=Get-Item -LiteralPath $bundleStash -Force -ErrorAction Stop
        if(($stashItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'StartupDisabled del bundle es reparse point.'
        }
        $backupName=[string]$entry.BackupName
        if([string]::IsNullOrWhiteSpace($backupName)-or[IO.Path]::GetFileName($backupName)-ne$backupName){
            throw 'BackupName Startup invalido exportando bundle.'
        }
        $destBackup=[IO.Path]::GetFullPath((Join-Path $bundleStash $backupName))
        if(-not(Test-VSO7StartupDirectChildPath -Path $destBackup -AllowedParents @($bundleStash))){
            throw 'Destino StartupDisabled fuera del bundle.'
        }
        $source=[string]$entry.BackupPath
        if(Test-Path -LiteralPath $source -PathType Leaf){

            [void](Assert-VSO7StartupPathRuntimeSafe -Path $source -AllowedParents @((Get-VSO7StartupStashRoot)))
            $sourceHash=(Get-FileHash -LiteralPath $source -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($sourceHash-ine[string]$entry.Sha256){
                throw ("Backup Startup alterado antes de exportar: {0}"-f$entry.Name)
            }
            if(Test-Path -LiteralPath $destBackup){

                $destItem=Get-Item -LiteralPath $destBackup -Force -ErrorAction Stop
                if(($destItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                    throw 'Backup Startup del bundle es reparse point.'
                }
                $destHash=(Get-FileHash -LiteralPath $destBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                if($destHash-ine$sourceHash){
                    throw 'Ya existe un backup Startup distinto en Recovery.'
                }

            }else{

                Copy-Item -LiteralPath $source -Destination $destBackup -ErrorAction Stop
                $destHash=(Get-FileHash -LiteralPath $destBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                if($destHash-ine$sourceHash){
                    throw 'Copia Startup del bundle no coincide por SHA-256.'
                }

            }

        }elseif([string]$entry.Status-ieq'Disabled'){

            throw ("Falta backup Startup requerido para Recovery: {0}"-f$entry.Name)

        }
        $exported += [pscustomobject]@{
            Id=[string]$entry.Id;
            Type='File';
            Name=[string]$entry.Name;
            RegistryPath=$null;
            Value=$null;
            Kind=$null;
            OriginalPath=[string]$entry.OriginalPath;
            BackupPath=$destBackup;
            BackupName=$backupName;
            Sha256=[string]$entry.Sha256;
            Status=[string]$entry.Status;
            DisabledAt=[string]$entry.DisabledAt
        }

    }
    $exportState=@{
        SchemaVersion=2;
        Version=[string]$script:StartupState.Version;
        CreatedAt=[string]$script:StartupState.CreatedAt;
        Disabled=$exported
    }
    $oldFile=$script:StartupStateFile
    try{

        $script:StartupStateFile=$destState
        $validated=ConvertTo-VSO7ValidatedStartupState -Object ([pscustomobject]$exportState)
        $tmp=$destState+'.tmp'
        ($validated|ConvertTo-Json -Depth 10)|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedStartupState -Object $check)
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $destState)

    }finally{
        $script:StartupStateFile=$oldFile
    }

}

function Save-StartupState {

    $recoveryPublishBundle=$null
    try{

        $validated=ConvertTo-VSO7ValidatedStartupState -Object ([pscustomobject]$script:StartupState)
        $script:StartupState=$validated
        $tmp="$($script:StartupStateFile).tmp"
        ($validated|ConvertTo-Json -Depth 10)|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedStartupState -Object $check)
        if(-not[string]::IsNullOrWhiteSpace($script:LastRecoveryBundle)-and(Test-Path -LiteralPath $script:LastRecoveryBundle)){

            $recoveryPublishBundle=Start-VSO7RecoveryPublishTransactionVSO -Bundle $script:LastRecoveryBundle

        }
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $script:StartupStateFile)
        $check=Get-Content -LiteralPath $script:StartupStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedStartupState -Object $check)
        if(-not[string]::IsNullOrWhiteSpace([string]$recoveryPublishBundle)){

            [void](Publish-VSO7RecoveryGenerationVSO -Bundle $recoveryPublishBundle)
            Clear-VSO7RecoveryPublishJournalVSO

        }

    }catch{

        try{
            if(Test-Path -LiteralPath "$($script:StartupStateFile).tmp" -PathType Leaf){
                Remove-Item -LiteralPath "$($script:StartupStateFile).tmp" -Force -ErrorAction SilentlyContinue
            }
        }catch{}
        Write-VSO7Log ("No se pudo guardar/verificar startup-state.json: {0}"-f$_.Exception.Message) 'ERROR'
        throw

    }

}

function Restore-VSO7StartupFileFromBackupVSO {

    param(
        [Parameter(Mandatory=$true)][string]$BackupPath,
        [Parameter(Mandatory=$true)][string]$OriginalPath,
        [Parameter(Mandatory=$true)][string]$ExpectedSha256,
        [switch]$KeepBackup
    )
    $expected=([string]$ExpectedSha256).ToUpperInvariant()
    if($expected-notmatch'^[0-9A-F]{64}$'){
        throw 'SHA-256 Startup esperado invalido.'
    }
    $backup=Assert-VSO7StartupPathRuntimeSafe -Path $BackupPath -AllowedParents @((Get-VSO7StartupStashRoot))
    $original=Assert-VSO7StartupPathRuntimeSafe -Path $OriginalPath -AllowedParents @(Get-VSO7StartupFolderRoots) -AllowMissingLeaf
    $backupHash=(Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
    if($backupHash-ine$expected){
        throw 'El backup Startup protegido no coincide por SHA-256.'
    }
    if(Test-Path -LiteralPath $original -PathType Leaf){

        [void](Assert-VSO7StartupPathRuntimeSafe -Path $original -AllowedParents @(Get-VSO7StartupFolderRoots))
        $existingHash=(Get-FileHash -LiteralPath $original -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($existingHash-ine$expected){
            throw 'Ya existe un archivo Startup distinto; VSO7 no lo sobrescribe.'
        }
        if(-not$KeepBackup){

            [void](Assert-VSO7StartupPathRuntimeSafe -Path $backup -AllowedParents @((Get-VSO7StartupStashRoot)))
            Remove-Item -LiteralPath $backup -Force -ErrorAction Stop

        }
        return $original

    }

    $parent=[IO.Path]::GetDirectoryName($original)
    $temp=[IO.Path]::GetFullPath((Join-Path $parent ('.vso-restore-'+[guid]::NewGuid().ToString('N')+'.tmp')))
    try{

        [void](Assert-VSO7StartupPathRuntimeSafe -Path $temp -AllowedParents @(Get-VSO7StartupFolderRoots) -AllowMissingLeaf)
        if(Test-Path -LiteralPath $temp){
            throw 'El temporal Startup aleatorio ya existe.'
        }
        Copy-Item -LiteralPath $backup -Destination $temp -ErrorAction Stop
        [void](Assert-VSO7StartupPathRuntimeSafe -Path $temp -AllowedParents @(Get-VSO7StartupFolderRoots))
        $tempHash=(Get-FileHash -LiteralPath $temp -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($tempHash-ine$expected){
            throw 'La copia temporal Startup no coincide por SHA-256.'
        }
        # Revalidar origen y destino inmediatamente antes del rename final.
        [void](Assert-VSO7StartupPathRuntimeSafe -Path $backup -AllowedParents @((Get-VSO7StartupStashRoot)))
        $backupHash2=(Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($backupHash2-ine$expected){
            throw 'El backup Startup cambio durante la restauracion.'
        }
        [void](Assert-VSO7StartupPathRuntimeSafe -Path $original -AllowedParents @(Get-VSO7StartupFolderRoots) -AllowMissingLeaf)
        if(Test-Path -LiteralPath $original){
            throw 'La ruta Startup original fue recreada durante la restauracion.'
        }
        [IO.File]::Move($temp,$original)
        [void](Assert-VSO7StartupPathRuntimeSafe -Path $original -AllowedParents @(Get-VSO7StartupFolderRoots))
        $finalHash=(Get-FileHash -LiteralPath $original -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($finalHash-ine$expected){
            throw 'El archivo Startup restaurado no coincide con el backup.'
        }
        if(-not$KeepBackup){

            [void](Assert-VSO7StartupPathRuntimeSafe -Path $backup -AllowedParents @((Get-VSO7StartupStashRoot)))
            $backupHash3=(Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($backupHash3-ine$expected){
                throw 'El backup Startup cambio antes de retirarlo.'
            }
            Remove-Item -LiteralPath $backup -Force -ErrorAction Stop

        }
        return $original

    }finally{

        if(Test-Path -LiteralPath $temp -PathType Leaf){

            try{

                [void](Assert-VSO7StartupPathRuntimeSafe -Path $temp -AllowedParents @(Get-VSO7StartupFolderRoots))
                Remove-Item -LiteralPath $temp -Force -ErrorAction Stop

            }catch{}

        }

    }

}

function Resolve-PendingStartupStateVSO {

    if ($null -eq $script:StartupState -or $null -eq $script:StartupState.Disabled) {
        return
    }

    $changed = $false
    $resolved = @()
    foreach ($entry in @($script:StartupState.Disabled)) {

        $status = if ($entry.PSObject.Properties.Name -contains 'Status') {
            [string]$entry.Status
        } else {
            'Disabled'
        }
        if (@('Pending','RestorePending') -notcontains $status) {

            $resolved += $entry
            continue

        }

        try {

            if ($entry.Type -eq 'Registry') {

                $snapshot=Get-RegistrySnapshot -Path ([string]$entry.RegistryPath) -Name ([string]$entry.Name)
                $exists=[bool]$snapshot.Exists
                $matchesOriginal=$false
                if($exists){
                    $matchesOriginal=([string]$snapshot.Kind -ieq [string]$entry.Kind) -and (Test-RegistryValueEqualVSO -Actual $snapshot.Value -Expected $entry.Value -Kind ([string]$entry.Kind))
                }

                if($status-ieq'Pending'){

                    if(-not$exists){

                        $entry.Status='Disabled';
                        $resolved+=$entry;
                        $changed=$true
                        Write-VSO7Log ("Operacion de Inicio pendiente reconciliada como Disabled: {0}"-f$entry.Name) 'WARN'
                        continue

                    }
                    if($matchesOriginal){

                        $changed=$true
                        Write-VSO7Log ("Operacion de Inicio pendiente descartada: la entrada original sigue intacta ({0})."-f$entry.Name) 'WARN'
                        continue

                    }

                }else{

                    if($matchesOriginal){

                        $changed=$true
                        Write-VSO7Log ("Restore de Inicio pendiente reconciliado como completado: {0}"-f$entry.Name) 'WARN'
                        continue

                    }
                    if(-not$exists){

                        $entry.Status='Disabled';
                        $resolved+=$entry;
                        $changed=$true
                        Write-VSO7Log ("Restore de Inicio pendiente no habia modificado Registry; vuelve a Disabled: {0}"-f$entry.Name) 'WARN'
                        continue

                    }

                }
                Write-VSO7Log ("Operacion de Inicio pendiente/ambigua conservada sin tocar: {0}"-f$entry.Name) 'ERROR'
                $resolved+=$entry
                continue

            }

            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots) -AllowMissingLeaf)
            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)) -AllowMissingLeaf)
            $originalExists=Test-Path -LiteralPath $entry.OriginalPath -PathType Leaf
            $backupExists=Test-Path -LiteralPath $entry.BackupPath -PathType Leaf
            $expected=([string]$entry.Sha256).ToUpperInvariant()
            $originalMatches=$false;
            $backupMatches=$false
            if($originalExists){

                [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots))
                $originalMatches=((Get-FileHash -LiteralPath $entry.OriginalPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()-ieq$expected)

            }
            if($backupExists){

                [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)))
                $backupMatches=((Get-FileHash -LiteralPath $entry.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()-ieq$expected)

            }

            if($status-ieq'Pending'){

                if($originalExists-and$originalMatches-and-not$backupExists){

                    $changed=$true
                    Write-VSO7Log ("Operacion de Inicio pendiente descartada: archivo original intacto ({0})."-f$entry.Name) 'WARN'
                    continue

                }
                if($originalExists-and$originalMatches-and$backupExists-and$backupMatches){

                    # La copia de seguridad llego a completarse, pero no se retiro el original.
                    # Volvemos de forma segura al baseline eliminando solo nuestra copia protegida.
                    Remove-Item -LiteralPath $entry.BackupPath -Force -ErrorAction Stop
                    $changed=$true
                    Write-VSO7Log ("Operacion de Inicio pendiente revertida al baseline: original y backup eran identicos ({0})."-f$entry.Name) 'WARN'
                    continue

                }
                if(-not$originalExists-and$backupExists-and$backupMatches){

                    $entry.Status='Disabled';
                    $resolved+=$entry;
                    $changed=$true
                    Write-VSO7Log ("Operacion de Inicio pendiente reconciliada como Disabled: {0}"-f$entry.Name) 'WARN'
                    continue

                }

            }else{

                if($originalExists-and$originalMatches){

                    if($backupExists){

                        if(-not$backupMatches){
                            throw 'Backup Startup no coincide durante reconciliacion RestorePending.'
                        }
                        Remove-Item -LiteralPath $entry.BackupPath -Force -ErrorAction Stop

                    }
                    $changed=$true
                    Write-VSO7Log ("Restore de Inicio pendiente reconciliado como completado: {0}"-f$entry.Name) 'WARN'
                    continue

                }
                if(-not$originalExists-and$backupExists-and$backupMatches){

                    $entry.Status='Disabled';
                    $resolved+=$entry;
                    $changed=$true
                    Write-VSO7Log ("Restore de Inicio pendiente no habia completado el archivo; vuelve a Disabled: {0}"-f$entry.Name) 'WARN'
                    continue

                }

            }

            Write-VSO7Log ("Operacion de Inicio pendiente/ambigua conservada sin tocar: {0}"-f$entry.Name) 'ERROR'
            $resolved+=$entry

        }catch{

            Write-VSO7Log ("No se pudo reconciliar operacion de Inicio pendiente {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
            $resolved+=$entry

        }

    }

    if($changed){

        $script:StartupState.Disabled=@($resolved)
        Save-StartupState

    }

}

function Get-StartupEntriesDetailed {

    param([switch]$Strict)
    $result=@();
    $regLocations=@(
        @{
        Path='HKCU:\Software\Microsoft\Windows\CurrentVersion\Run';Label='HKCU Run'
    },
        @{
        Path='HKLM:\Software\Microsoft\Windows\CurrentVersion\Run';Label='HKLM Run'
    },
        @{
        Path='HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run';Label='HKLM Run32'
    }
    )
    foreach($loc in $regLocations){

        try{

            if(-not(Test-Path -LiteralPath $loc.Path -ErrorAction Stop)){
                continue
            }
            foreach($snapshot in @(Get-VSO7RegistryValuesSnapshotVSO -Path ([string]$loc.Path))){
                $result += [pscustomobject]@{
                    Id=('REG|'+$loc.Path+'|'+[string]$snapshot.Name);
                    Type='Registry';
                    Name=[string]$snapshot.Name;
                    Command=[string]$snapshot.Value;
                    Location=$loc.Label;
                    RegistryPath=$loc.Path;
                    Kind=[string]$snapshot.Kind;
                    FilePath=$null
                }
            }

        }catch{
            if($Strict){
                throw
            }
        }

    }
    $startupRoots=@(Get-VSO7StartupFolderRoots);
    $folders=@();
    if($startupRoots.Count-ge1){
        $folders += @{
            Path=[string]$startupRoots[0];
            Label='Inicio usuario'
        }
    };
    if($startupRoots.Count-ge2){
        $folders += @{
            Path=[string]$startupRoots[1];
            Label='Inicio comun'
        }
    }
    foreach($f in $folders){

        if([string]::IsNullOrWhiteSpace($f.Path)){
            continue
        }
        try{
            if(-not(Test-Path -LiteralPath $f.Path -ErrorAction Stop)){
                continue
            };
            foreach($item in @(Get-ChildItem -LiteralPath $f.Path -File -Force -ErrorAction Stop)){
                $result += [pscustomobject]@{
                    Id=('FILE|'+$item.FullName);
                    Type='File';
                    Name=$item.BaseName;
                    Command=$item.FullName;
                    Location=$f.Label;
                    RegistryPath=$null;
                    Kind=$null;
                    FilePath=$item.FullName
                }
            }
        }catch{
            if($Strict){
                throw
            }
        }

    }
    return @($result|Sort-Object Name,Location)

}

function Get-VSO7StartupTechnicalClassVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $name=[string]$Entry.Name;
    $cmd=[string]$Entry.Command;
    $text=($name+' '+$cmd).ToLowerInvariant()
    if($text-match'windows defender|securityhealth|security health|antivirus|antimalware|firewall|vanguard|vgtray'){
        return 'Security'
    }
    if($text-match'\\windows\\|\\system32\\|microsoft\\windows|windows security|ctfmon\.exe|sihost\.exe'){
        return 'Windows'
    }
    if($text-match'realtek|audio driver|graphics driver|display driver|intel.*driver|amd.*driver|nvidia.*driver|synaptics|elan|touchpad|bluetooth.*driver'){
        return 'Driver'
    }
    if($text-match'update|updater|update assistant|autoupdate|auto-update|maintenance service'){
        return 'Updater'
    }
    if($text-match'launcher|spotify|steam|discord|epic|opera|chrome|edge|medal|overwolf|curseforge|capcut|roblox|onedrive|teams|slack'){
        return 'OptionalUserApp'
    }
    return 'Unknown'

}

function Get-StartupClassificationVSO {

    param([Parameter(Mandatory=$true)]$Entry)

    $text = (([string]$Entry.Name) + ' ' + ([string]$Entry.Command)).ToLowerInvariant()
    if ($text -match 'securityhealth|windowsdefender|rtkaud|rtkauduservice|steelseries|sonar|tailscale|vanguard|vgtray') {

        return 'MANTENER'

    }
    if ($text -match 'epicgameslauncher|medal|microsoftedgeautolaunch|curseforge|jetbrains toolbox|overwolf|riotclient|opera|steam|spotify|capcut|noping|roblox') {

        return 'CANDIDATO'

    }
    if ($text -match 'lghub|logitech|glorious|synapse|razer|onedrive|nordvpn|vpn') {

        return 'REVISAR'

    }
    return 'REVISAR'

}

function Disable-StartupEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)

    Load-StartupState
    $state = $null
    $modified = $false
    try {

        if([string]$Entry.Type-ieq'Registry'){

            $allowedRegistry=@(Get-VSO7StartupRegistryPaths)
            if($allowedRegistry-notcontains[string]$Entry.RegistryPath){
                throw 'La entrada Registry de Inicio esta fuera de la allowlist.'
            }
            if([string]::IsNullOrWhiteSpace([string]$Entry.Name)-or([string]$Entry.Name).Length-gt512){
                throw 'Nombre Registry de Inicio invalido.'
            }
            $expectedId='REG|'+[string]$Entry.RegistryPath+'|'+[string]$Entry.Name
            $existing=@($script:StartupState.Disabled|Where-Object{
                $_.Id-ieq$expectedId
            })
            if($existing.Count-gt0){
                throw ("Ya existe un backup pendiente para esta entrada ({0}). Restauralo antes de volver a modificarla."-f$Entry.Name)
            }
            $entrySnapshot=Get-RegistrySnapshot -Path ([string]$Entry.RegistryPath) -Name ([string]$Entry.Name)
            if(-not[bool]$entrySnapshot.Exists){
                throw 'La entrada de Inicio ya no existe.'
            }
            $raw=$entrySnapshot.Value
            $kind=[string]$entrySnapshot.Kind
            if(@('String','ExpandString')-notcontains$kind-or-not($raw-is[string]) -or ([string]$raw).Length-gt32767){
                throw 'La entrada Run no usa String/ExpandString seguro; VSO7 no la modificara.'
            }
            $state=[pscustomobject]@{
                Id=$expectedId;
                Type='Registry';
                Name=[string]$Entry.Name;
                RegistryPath=[string]$Entry.RegistryPath;
                Value=[string]$raw;
                Kind=$kind;
                OriginalPath=$null;
                BackupPath=$null;
                BackupName=$null;
                Sha256=$null;
                Status='Pending';
                DisabledAt=(Get-Date).ToString('o')
            }

        }elseif([string]$Entry.Type-ieq'File'){

            $startupRoots=@(Get-VSO7StartupFolderRoots)
            $originalSafe=Assert-VSO7StartupPathRuntimeSafe -Path ([string]$Entry.FilePath) -AllowedParents $startupRoots
            $expectedId='FILE|'+$originalSafe
            $existing=@($script:StartupState.Disabled|Where-Object{
                $_.Id-ieq$expectedId
            })
            if($existing.Count-gt0){
                throw ("Ya existe un backup pendiente para esta entrada ({0}). Restauralo antes de volver a modificarla."-f$Entry.Name)
            }
            $stash=Get-VSO7StartupStashRoot
            if(Test-Path -LiteralPath $stash){

                [void](Protect-VSO7SecureDirectory -Path $stash)

            }else{

                [IO.Directory]::CreateDirectory($stash)|Out-Null
                $stashDi=New-Object IO.DirectoryInfo($stash)
                $stashDi.SetAccessControl((New-VSO7LockedDirectoryAcl))
                [void](Protect-VSO7SecureDirectory -Path $stash)

            }
            $stashItem=Get-Item -LiteralPath $stash -Force -ErrorAction Stop
            if(($stashItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw 'El stash StartupDisabled es un reparse point.'
            }
            $safeName=('{0}_{1}{2}'-f([guid]::NewGuid().ToString('N')),[IO.Path]::GetFileNameWithoutExtension($originalSafe),[IO.Path]::GetExtension($originalSafe))
            $backupPath=Assert-VSO7StartupPathRuntimeSafe -Path (Join-Path $stash $safeName) -AllowedParents @($stash) -AllowMissingLeaf
            if(Test-Path -LiteralPath $backupPath){
                throw 'La ruta aleatoria de backup ya existe inesperadamente.'
            }
            $hash=(Get-FileHash -LiteralPath $originalSafe -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            $state=[pscustomobject]@{
                Id=$expectedId;
                Type='File';
                Name=[IO.Path]::GetFileNameWithoutExtension($originalSafe);
                RegistryPath=$null;
                Value=$null;
                Kind=$null;
                OriginalPath=$originalSafe;
                BackupPath=$backupPath;
                BackupName=[IO.Path]::GetFileName($backupPath);
                Sha256=$hash;
                Status='Pending';
                DisabledAt=(Get-Date).ToString('o')
            }

        }else{
            throw 'Tipo de entrada Startup no soportado.'
        }

        # Persistir el rollback ANTES de tocar Windows evita perder la restauracion si el proceso se interrumpe bruscamente.
        $script:StartupState.Disabled += $state
        Save-StartupState

        # El estado puede cambiar mientras escribimos Pending. Si no podemos demostrar que
        # sigue exactamente igual, VSO7 todavia no ha ejercido ownership: retira este Pending.
        try{

            if ($state.Type -eq 'Registry') {

                $startupNow=Get-RegistrySnapshot -Path ([string]$state.RegistryPath) -Name ([string]$state.Name)
                $expectedStartup=[pscustomobject]@{
                    Exists=$true;
                    Kind=[string]$state.Kind;
                    Value=$state.Value
                }
                if(-not(Test-VSO7RegistrySnapshotEqualVSO -Left $expectedStartup -Right $startupNow)){
                    throw 'La entrada Registry de Inicio cambio entre snapshot y borrado.'
                }

            } else {

                [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots))
                if(-not(Test-Path -LiteralPath $state.OriginalPath -PathType Leaf)){
                    throw 'El archivo Startup desaparecio entre snapshot y copia.'
                }
                $startupHashNow=(Get-FileHash -LiteralPath $state.OriginalPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                if($startupHashNow-ine[string]$state.Sha256){
                    throw 'El archivo Startup cambio entre snapshot y copia.'
                }

            }

        }catch{

            $reason=$_.Exception.Message
            $script:StartupState.Disabled=@($script:StartupState.Disabled|Where-Object{
                $_.Id-ine$state.Id
            })
            Save-StartupState
            $state=$null
            throw ("{0} VSO7 retiro su Pending sin modificar Windows."-f$reason)

        }

        if ($state.Type -eq 'Registry') {

            Remove-ItemProperty -LiteralPath $state.RegistryPath -Name $state.Name -ErrorAction Stop
            $modified = $true
            $check=Get-RegistrySnapshot -Path ([string]$state.RegistryPath) -Name ([string]$state.Name)
            if([bool]$check.Exists){
                throw 'Windows sigue mostrando la entrada despues de eliminarla.'
            }

        } else {

            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots))
            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)) -AllowMissingLeaf)
            [void](Copy-VSO7FileAtomicallyVSO -SourcePath ([string]$state.OriginalPath) -DestinationPath ([string]$state.BackupPath))
            $backupHash=(Get-FileHash -LiteralPath $state.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($backupHash-ine[string]$state.Sha256){
                throw 'La copia Startup protegida no coincide por SHA-256.'
            }
            # El original puede estar en otro volumen. Copiar+verificar antes de borrar mantiene
            # siempre una copia recuperable incluso si Move-Item no pudiera ser atomico cross-volume.
            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots))
            $originalHash=(Get-FileHash -LiteralPath $state.OriginalPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($originalHash-ine[string]$state.Sha256){
                throw 'El archivo Startup cambio durante la copia; no se elimina.'
            }
            Remove-Item -LiteralPath $state.OriginalPath -Force -ErrorAction Stop
            $modified=$true
            if(Test-Path -LiteralPath $state.OriginalPath){
                throw 'El archivo sigue en la carpeta Inicio.'
            }
            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)))
            $afterHash=(Get-FileHash -LiteralPath $state.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($afterHash-ine[string]$state.Sha256){
                throw 'El backup Startup cambio tras retirar el original.'
            }

        }

        $state.Status = 'Disabled'
        Save-StartupState
        Write-VSO7Log ("Autoarranque deshabilitado y respaldado: {0}" -f $Entry.Name) 'CHANGE'

    } catch {

        $original = $_.Exception.Message
        # Si aun no se modifico el destino real, no existe nada que restaurar. Retiramos
        # nuestro Pending y cualquier backup protegido que hayamos creado nosotros.
        if($null-ne$state-and-not$modified){

            try{

                if([string]$state.Type-ieq'File'-and(Test-Path -LiteralPath $state.BackupPath -PathType Leaf)){

                    [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)))
                    $pendingBackupHash=(Get-FileHash -LiteralPath $state.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                    if($pendingBackupHash-ine[string]$state.Sha256){
                        throw 'El backup Startup creado durante el intento no coincide; se conserva Pending para revision.'
                    }
                    Remove-Item -LiteralPath $state.BackupPath -Force -ErrorAction Stop

                }
                $script:StartupState.Disabled=@($script:StartupState.Disabled|Where-Object{
                    $_.Id-ine$state.Id
                })
                Save-StartupState
                Write-VSO7Log ("Operacion Startup abortada antes de mutar; Pending retirado: {0}"-f$state.Name) 'WARN'
                $state=$null

            }catch{
                Write-VSO7Log ("No se pudo limpiar con seguridad un Pending Startup que aun no habia mutado el destino: {0}"-f$_.Exception.Message) 'ERROR'
            }

        }
        if ($null -ne $state) {

            try {

                if ($state.Type -eq 'Registry') {

                    if (-not (Test-Path -LiteralPath $state.RegistryPath)) {
                        New-Item -Path $state.RegistryPath -Force -ErrorAction Stop | Out-Null
                    }
                    $kind = [string]$state.Kind
                    if ([string]::IsNullOrWhiteSpace($kind)) {
                        $kind = 'String'
                    }
                    $rollbackSnapshot=Get-RegistrySnapshot -Path ([string]$state.RegistryPath) -Name ([string]$state.Name)
                    if([bool]$rollbackSnapshot.Exists){

                        if([string]$rollbackSnapshot.Kind -ine $kind -or -not(Test-RegistryValueEqualVSO -Actual $rollbackSnapshot.Value -Expected $state.Value -Kind $kind)){
                            throw 'Conflicto: otra aplicacion recreo la entrada de Inicio; no se sobrescribe durante rollback.'
                        }

                    }else{

                        New-ItemProperty -LiteralPath $state.RegistryPath -Name $state.Name -Value $state.Value -PropertyType $kind -ErrorAction Stop | Out-Null

                    }

                } elseif ($state.Type -eq 'File') {

                    $originalExists=Test-Path -LiteralPath $state.OriginalPath -PathType Leaf
                    $backupExists=Test-Path -LiteralPath $state.BackupPath -PathType Leaf
                    if($originalExists){

                        [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots))
                        $currentOriginalHash=(Get-FileHash -LiteralPath $state.OriginalPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                        if($currentOriginalHash-ine[string]$state.Sha256){
                            throw 'Conflicto: el archivo Startup original cambio; no se sobrescribe durante rollback.'
                        }
                        if($backupExists){

                            [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$state.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)))
                            $currentBackupHash=(Get-FileHash -LiteralPath $state.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                            if($currentBackupHash-ine[string]$state.Sha256){
                                throw 'El backup Startup temporal no coincide; se conserva el estado Pending.'
                            }
                            Remove-Item -LiteralPath $state.BackupPath -Force -ErrorAction Stop

                        }

                    }elseif($backupExists){

                        [void](Restore-VSO7StartupFileFromBackupVSO -BackupPath ([string]$state.BackupPath) -OriginalPath ([string]$state.OriginalPath) -ExpectedSha256 ([string]$state.Sha256))

                    }else{

                        throw 'No existe ni original ni backup Startup; se conserva el estado Pending.'

                    }

                }
                $script:StartupState.Disabled = @($script:StartupState.Disabled | Where-Object {
                    $_.Id -ne $state.Id
                })
                Save-StartupState
                Write-VSO7Log ("Rollback transaccional de Inicio completado: {0}" -f $Entry.Name) 'WARN'

            } catch {

                Write-VSO7Log ("FALLO CRITICO restaurando la operacion de Inicio {0}: {1}" -f $Entry.Name,$_.Exception.Message) 'ERROR'

            }

        }
        throw $original

    }

}

function Restore-StartupEntryVSO {

    param([Parameter(Mandatory=$true)]$StateEntry)

    if (($StateEntry.PSObject.Properties.Name -contains 'Status') -and @('Pending','RestorePending') -contains [string]$StateEntry.Status) {

        throw 'Operacion de Inicio pendiente/ambigua: VSO7 se niega a sobrescribir nada automaticamente.'

    }

    Load-StartupState
    $tracked=@($script:StartupState.Disabled|Where-Object{
        $_.Id-ieq[string]$StateEntry.Id
    })
    if($tracked.Count-ne1){
        throw 'La entrada Startup a restaurar no coincide de forma unica con el estado protegido actual.'
    }
    $entry=$tracked[0]
    if([string]$entry.Status-ine'Disabled'){
        throw 'La entrada Startup no esta en estado Disabled restaurable.'
    }

    # Antes de persistir RestorePending comprobamos el estado deshabilitado. Si el destino
    # ya fue recreado externamente con el mismo contenido, VSO7 no lo sobrescribe: solo
    # libera su estado/backup. Si es distinto, falla cerrado.
    if([string]$entry.Type-ieq'Registry'){

        if(@(Get-VSO7StartupRegistryPaths)-notcontains[string]$entry.RegistryPath){
            throw 'RegistryPath de Startup fuera de allowlist durante restore.'
        }
        $pre=Get-RegistrySnapshot -Path ([string]$entry.RegistryPath) -Name ([string]$entry.Name)
        if([bool]$pre.Exists){

            $kind=[string]$entry.Kind;
            if([string]::IsNullOrWhiteSpace($kind)){
                $kind='String'
            }
            if([string]$pre.Kind-ine$kind-or-not(Test-RegistryValueEqualVSO -Actual $pre.Value -Expected $entry.Value -Kind $kind)){
                throw 'La entrada Startup fue recreada externamente con contenido distinto; VSO7 no la sobrescribe.'
            }
            $script:StartupState.Disabled=@($script:StartupState.Disabled|Where-Object{
                $_.Id-ine[string]$entry.Id
            });
            Save-StartupState
            Write-VSO7Log ("Startup Registry ya fue recreado externamente con el baseline; VSO7 libera ownership sin escribir: {0}"-f$entry.Name) 'WARN'
            return

        }

    }else{

        $backup=Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot))
        $backupHash=(Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($backupHash-ine[string]$entry.Sha256){
            throw 'El backup Startup protegido no coincide antes de iniciar restore.'
        }
        $original=Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots) -AllowMissingLeaf
        if(Test-Path -LiteralPath $original -PathType Leaf){

            [void](Assert-VSO7StartupPathRuntimeSafe -Path $original -AllowedParents @(Get-VSO7StartupFolderRoots))
            $originalHash=(Get-FileHash -LiteralPath $original -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($originalHash-ine[string]$entry.Sha256){
                throw 'El archivo Startup fue recreado externamente con contenido distinto; VSO7 no lo sobrescribe.'
            }
            $script:StartupState.Disabled=@($script:StartupState.Disabled|Where-Object{
                $_.Id-ine[string]$entry.Id
            });
            Save-StartupState
            try{
                Remove-Item -LiteralPath $backup -Force -ErrorAction Stop
            }catch{
                Write-VSO7Log ("El estado Startup ya se libero, pero quedo un backup huerfano que no se pudo retirar: {0}"-f$_.Exception.Message) 'WARN'
            }
            Write-VSO7Log ("Archivo Startup ya fue recreado externamente con el baseline; VSO7 libera ownership sin escribir: {0}"-f$entry.Name) 'WARN'
            return

        }

    }

    $entry.Status='RestorePending'
    Save-StartupState

    # Revalidacion posterior a Pending: el destino debe seguir ausente y el backup (si
    # existe) debe seguir siendo exactamente el autenticado antes de ejercer ownership.
    try{

        if([string]$entry.Type-ieq'Registry'){

            $afterPending=Get-RegistrySnapshot -Path ([string]$entry.RegistryPath) -Name ([string]$entry.Name)
            if([bool]$afterPending.Exists){
                throw 'La entrada Registry Startup reaparecio entre Pending y restore.'
            }

        }else{

            $backup=Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot))
            $backupHash=(Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($backupHash-ine[string]$entry.Sha256){
                throw 'El backup Startup cambio entre Pending y restore.'
            }
            $original=Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.OriginalPath) -AllowedParents @(Get-VSO7StartupFolderRoots) -AllowMissingLeaf
            if(Test-Path -LiteralPath $original){
                throw 'La ruta Startup original fue recreada entre Pending y restore.'
            }

        }

    }catch{

        $reason=$_.Exception.Message
        Load-StartupState
        $current=@($script:StartupState.Disabled|Where-Object{
            $_.Id-ieq[string]$entry.Id
        })
        if($current.Count-eq1-and[string]$current[0].Status-ieq'RestorePending'){
            $current[0].Status='Disabled';
            $script:StartupState.Disabled=@($script:StartupState.Disabled);
            Save-StartupState
        }
        throw ("{0} VSO7 no ejercio ownership y devolvio el estado a Disabled."-f$reason)

    }

    try{

        if($entry.Type-eq'Registry'){

            if(-not(Test-Path -LiteralPath $entry.RegistryPath)){
                New-Item -Path $entry.RegistryPath -Force -ErrorAction Stop|Out-Null
            }
            $kind=[string]$entry.Kind;
            if([string]::IsNullOrWhiteSpace($kind)){
                $kind='String'
            }
            New-ItemProperty -LiteralPath $entry.RegistryPath -Name $entry.Name -Value $entry.Value -PropertyType $kind -ErrorAction Stop|Out-Null
            $verifySnapshot=Get-RegistrySnapshot -Path ([string]$entry.RegistryPath) -Name ([string]$entry.Name)
            if(-not[bool]$verifySnapshot.Exists-or-not(Test-RegistryValueEqualVSO -Actual $verifySnapshot.Value -Expected $entry.Value -Kind $kind)){
                throw 'La entrada Registry restaurada no coincide con su backup.'
            }

        }else{

            [void](Restore-VSO7StartupFileFromBackupVSO -BackupPath ([string]$entry.BackupPath) -OriginalPath ([string]$entry.OriginalPath) -ExpectedSha256 ([string]$entry.Sha256) -KeepBackup)

        }

        Load-StartupState
        $script:StartupState.Disabled=@($script:StartupState.Disabled|Where-Object{
            $_.Id-ine[string]$entry.Id
        })
        Save-StartupState
        if([string]$entry.Type-ieq'File'-and(Test-Path -LiteralPath $entry.BackupPath -PathType Leaf)){

            try{

                [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)))
                $postCommitBackupHash=(Get-FileHash -LiteralPath $entry.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                if($postCommitBackupHash-ine[string]$entry.Sha256){
                    throw 'Backup Startup cambio despues de commit de estado; se conserva como huerfano para revision.'
                }
                Remove-Item -LiteralPath $entry.BackupPath -Force -ErrorAction Stop

            }catch{
                Write-VSO7Log ("Restore Startup finalizo, pero no se pudo retirar su backup huerfano: {0}"-f$_.Exception.Message) 'WARN'
            }

        }
        Write-VSO7Log ("Autoarranque restaurado/verificado: {0}"-f$entry.Name) 'CHANGE'

    }catch{

        $message=$_.Exception.Message
        try{

            Load-StartupState
            $current=@($script:StartupState.Disabled|Where-Object{
                $_.Id-ieq[string]$entry.Id
            })
            if($current.Count-eq1-and[string]$current[0].Status-ieq'RestorePending'){

                $safeToRevert=$false
                if([string]$entry.Type-ieq'Registry'){

                    $snap=Get-RegistrySnapshot -Path ([string]$entry.RegistryPath) -Name ([string]$entry.Name)
                    $safeToRevert=(-not[bool]$snap.Exists)

                }else{

                    $safeToRevert=(-not(Test-Path -LiteralPath $entry.OriginalPath -PathType Leaf)) -and (Test-Path -LiteralPath $entry.BackupPath -PathType Leaf)
                    if($safeToRevert){
                        [void](Assert-VSO7StartupPathRuntimeSafe -Path ([string]$entry.BackupPath) -AllowedParents @((Get-VSO7StartupStashRoot)));
                        $safeToRevert=((Get-FileHash -LiteralPath $entry.BackupPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()-ieq([string]$entry.Sha256).ToUpperInvariant())
                    }

                }
                if($safeToRevert){
                    $current[0].Status='Disabled';
                    $script:StartupState.Disabled=@($script:StartupState.Disabled);
                    Save-StartupState
                }

            }

        }catch{
            Write-VSO7Log ("No se pudo reconciliar inmediatamente RestorePending de Inicio {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
        }
        throw $message

    }

}

function Restore-AllStartupChangesVSO {

    Load-StartupState
    $ok=$true
    $pending=@($script:StartupState.Disabled|Where-Object{
        ($_.PSObject.Properties.Name-contains'Status') -and @('Pending','RestorePending') -contains [string]$_.Status
    })
    if($pending.Count-gt0){
        Write-VSO7Log ("Hay {0} operacion(es) de Inicio Pending/ambiguas; no se sobrescribiran automaticamente."-f$pending.Count) 'ERROR';
        $ok=$false
    }
    $items=@($script:StartupState.Disabled|Where-Object{
        ($_.PSObject.Properties.Name-notcontains'Status') -or @('Pending','RestorePending') -notcontains [string]$_.Status
    })
    foreach($entry in $items){
        try{
            Restore-StartupEntryVSO -StateEntry $entry
        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar Inicio {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
        }
    }
    return $ok

}

function Show-StartupRestoreMenuVSO {

    while($true){

        Write-Title;
        Load-StartupState
        $pending=@($script:StartupState.Disabled|Where-Object{
            ($_.PSObject.Properties.Name-contains'Status')-and@('Pending','RestorePending')-contains[string]$_.Status
        })
        $items=@($script:StartupState.Disabled|Where-Object{
            ($_.PSObject.Properties.Name-notcontains'Status')-or@('Pending','RestorePending')-notcontains[string]$_.Status
        })
        Write-CenteredLineVSO -Text 'RESTAURAR APLICACIONES DE INICIO' -Color 'Yellow'
        Write-CenteredLineVSO -Text 'Aqui solo se muestran entradas que VSO7 deshabilito anteriormente y sabe como restaurar.' -Color $script:ThemeText
        if($pending.Count-gt0){
            Write-CenteredLineVSO -Text $(Get-VSO7ConsoleTextVSO -Es 'Hay operaciones de inicio pendientes o ambiguas. VSO7 no las restaurara automaticamente.' -En 'Some startup operations are pending or ambiguous. VSO7 will not restore them automatically.') -Color $script:ThemeDanger;
            Write-CenteredLineVSO -Text 'Revisa startup-state.json y los logs antes de intervenir manualmente.' -Color $script:ThemeWarning;
            Write-VSOHost ''
        }
        if($items.Count-eq0){
            Write-CenteredLineVSO -Text 'No hay entradas deshabilitadas por VSO7.' -Color $script:ThemeMuted;
            Pause-Vico;
            return
        }
        $rows=@();
        for($i=0;$i-lt$items.Count;$i++){
            $rows += [pscustomobject]@{
                Text=("[{0}] {1}"-f($i+1),$items[$i].Name);
                Color='Gray';
                Description=($(Get-VSO7ConsoleTextVSO -Es 'Tipo: {0}. Restaura esta entrada a su ubicacion de inicio original guardada por VSO7.' -En 'Type: {0}. Restores this entry to its original startup location saved by VSO7.')-f$items[$i].Type)
            }
        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        $allNumber=$items.Count+1
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Restaurar todas las entradas' -En '[{0}] Restore all entries')-f$allNumber);Color='Green';Description='Intenta restaurar de una vez todas las entradas de inicio que VSO7 tiene registradas como deshabilitadas.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa sin restaurar ninguna entrada adicional.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Opcion';
        if($choice-eq'0'){
            return
        };
        $number=0;
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }
        if($number-eq$allNumber){
            if((Read-CenteredPromptVSO -Text '¿Restaurar TODAS? [S/N]')-match'^[sSyY]$'){
                foreach($entry in @($items)){
                    try{
                        Restore-StartupEntryVSO -StateEntry $entry
                    }catch{
                        Write-VSO7Log ("No se pudo restaurar {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
                    }
                }
            };
            continue
        }
        if($number-ge1-and$number-le$items.Count){
            try{
                Restore-StartupEntryVSO -StateEntry $items[$number-1]
            }catch{
                Write-VSO7Log $_.Exception.Message 'ERROR'
            };
            Pause-Vico
        }

    }

}

function New-StartupRecoverySnapshotVSO {

    param([Parameter(Mandatory=$true)][array]$Entries)

    $recoveryRoot=[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')
    $recoveryItem=Get-Item -LiteralPath $recoveryRoot -Force -ErrorAction Stop
    if(-not$recoveryItem.PSIsContainer-or($recoveryItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'RecoveryRoot invalido/reparse point.'
    }
    $dir = Join-Path $recoveryRoot ("Startup_{0}_{1}" -f (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'),([guid]::NewGuid().ToString('N')))
    if(Test-Path -LiteralPath $dir){
        throw 'Colision inesperada creando snapshot Startup.'
    }
    $dir=Protect-VSO7SecureDirectory -Path $dir

    $Entries |
        Select-Object Id,Type,Name,Command,Location,RegistryPath,Kind,FilePath |
        ConvertTo-Json -Depth 6 |
        Set-Content -LiteralPath (Join-Path $dir 'seleccion-antes.json') -Encoding UTF8 -Force -ErrorAction Stop

    if (Test-Path -LiteralPath $script:StartupStateFile) {

        Copy-Item -LiteralPath $script:StartupStateFile -Destination (Join-Path $dir 'startup-state-antes.json') -Force -ErrorAction Stop

    }

    Write-VSO7Log ("Snapshot de inicio creado: {0}" -f $dir) 'CHANGE'
    return $dir

}

function Show-StartupAnalysis {

    $selected=@{}
    while($true){

        Write-Title
        Write-CenteredLineVSO -Text 'GESTOR AUTOMATICO DE INICIO' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Elige exactamente que programas dejan de arrancar con Windows. No se desinstala nada.' -Color 'Green'
        Write-CenteredLineVSO -Text 'MANTENER = normalmente conviene dejarlo | REVISAR = depende de tu uso | CANDIDATO = suele ser prescindible al arrancar' -Color $script:ThemeText
        Write-VSOHost ''

        $entries=@(Get-StartupEntriesDetailed)
        if($entries.Count-eq0){
            Write-CenteredLineVSO -Text 'No se detectaron entradas de inicio compatibles.' -Color $script:ThemeMuted;
            Pause-Vico;
            return
        }

        $startupRows=@()
        for($i=0;$i-lt$entries.Count;$i++){

            $entry=$entries[$i];
            $mark=if($selected.ContainsKey($entry.Id)){
                'X'
            }else{
                ' '
            };
            $class=Get-StartupClassificationVSO -Entry $entry;
            $tech=Get-VSO7StartupTechnicalClassVSO -Entry $entry
            $color=switch($class){
                'MANTENER'{
                    'Green'
                }'CANDIDATO'{
                    'Yellow'
                }default{
                    'Gray'
                }
            }
            $isEn=($script:Language-eq'en');
            $meaning=switch($class){
                'MANTENER'{
                    if($isEn){
                        'VSO7 recommends keeping this entry unless you know you do not need it.'
                    }else{
                        'VSO7 recomienda conservar esta entrada salvo que sepas que no la necesitas.'
                    }
                }'CANDIDATO'{
                    if($isEn){
                        'Usually safe to remove from startup without uninstalling the application.'
                    }else{
                        'Suele poder quitarse del arranque sin desinstalar la aplicacion.'
                    }
                }default{
                    if($isEn){
                        'Review whether you need this program to start automatically.'
                    }else{
                        'Revisa si necesitas que este programa arranque automaticamente.'
                    }
                }
            }
            $sourceLabel=if($isEn){
                'Source'
            }else{
                'Origen'
            }
            $startupRows += [pscustomobject]@{
                Text=("[{0}] [{1}] {2} - {3}"-f($i+1),$mark,$(if($isEn){switch($class){'MANTENER'{'KEEP'}'CANDIDATO'{'CANDIDATE'}default{'REVIEW'}}}else{$class}),$entry.Name);
                Color=$color;
                Description=(($(Get-VSO7ConsoleTextVSO -Es "{0} {1}: {2} · Clase: {3}" -En "{0} {1}: {2} · Class: {3}")-f$meaning,$sourceLabel,$entry.Location,$tech))
            }

        }
        Write-VSO7TwoColumnOptionsVSO -Items $startupRows

        $selectCandidates=$entries.Count+1;
        $clearSelection=$entries.Count+2;
        $showCommand=$entries.Count+3;
        $disableSelected=$entries.Count+4;
        $restoreDisabled=$entries.Count+5
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar todos los CANDIDATOS' -En '[{0}] Select all CANDIDATES')-f$selectCandidates);Color='Yellow';Description='Marca automaticamente solo las entradas que VSO7 considera normalmente prescindibles al iniciar Windows.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Quitar toda la seleccion' -En '[{0}] Clear the selection')-f$clearSelection);Color='Gray';Description='Desmarca todo. No cambia Windows.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Ver detalles y comando de una entrada' -En '[{0}] View entry details and command')-f$showCommand);Color='Gray';Description='Muestra de donde sale una entrada y el comando que ejecuta, sin modificarla.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Deshabilitar las entradas seleccionadas' -En '[{0}] Disable selected startup entries')-f$disableSelected);Color='Yellow';Description='Crea recuperacion y evita que las seleccionadas arranquen automaticamente; no desinstala los programas.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Restaurar entradas deshabilitadas por VSO7' -En '[{0}] Restore startup entries disabled by VSO7')-f$restoreDisabled);Color='Green';Description='Abre el historial de entradas que VSO7 deshabilito para poder restaurarlas.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa al menu anterior sin aplicar cambios pendientes.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Opcion / numero para marcar o desmarcar'
        if($choice-eq'0'){
            return
        }
        $number=0;
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }

        if($number-ge1-and$number-le$entries.Count){
            $entry=$entries[$number-1];
            if($selected.ContainsKey($entry.Id)){
                $selected.Remove($entry.Id)
            }else{
                $selected[$entry.Id]=$true
            };
            continue
        }
        if($number-eq$selectCandidates){
            $selected=@{};
            foreach($entry in $entries){
                if((Get-StartupClassificationVSO -Entry $entry)-eq'CANDIDATO'){
                    $selected[$entry.Id]=$true
                }
            };
            continue
        }
        if($number-eq$clearSelection){
            $selected=@{};
            continue
        }
        if($number-eq$restoreDisabled){
            Show-StartupRestoreMenuVSO;
            continue
        }
        if($number-eq$showCommand){

            $raw=Read-CenteredPromptVSO -AnimatedMenu -Text 'Numero de la entrada que quieres inspeccionar';
            $detailNumber=0
            if([int]::TryParse($raw,[ref]$detailNumber)-and$detailNumber-ge1-and$detailNumber-le$entries.Count){
                $entry=$entries[$detailNumber-1];
                Write-VSOHost '';
                Write-VSOHost ((Convert-VSOText -Value $(Get-VSO7ConsoleTextVSO -Es 'Nombre :' -En 'Name   :'))+' '+$entry.Name);
                Write-VSOHost ((Convert-VSOText -Value $(Get-VSO7ConsoleTextVSO -Es 'Origen :' -En 'Source :'))+' '+$entry.Location);
                Write-VSOHost ((Convert-VSOText -Value $(Get-VSO7ConsoleTextVSO -Es 'Comando:' -En 'Command:'))+' '+$entry.Command);
                Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Clase  : ' -En 'Class  : ')+(Get-VSO7StartupTechnicalClassVSO -Entry $entry));
                Pause-Vico
            }
            continue

        }
        if($number-eq$disableSelected){

            $selection=@($entries|Where-Object{
                $selected.ContainsKey($_.Id)
            })
            if($selection.Count-eq0){
                Write-CenteredLineVSO -Text 'No hay ninguna entrada seleccionada.' -Color $script:ThemeMuted;
                Pause-Vico;
                continue
            }
            Write-VSOHost '';
            Write-CenteredLineVSO -Text 'Se quitara del arranque automatico:' -Color $script:ThemeWarning
            foreach($entry in $selection){
                Write-VSOHost (" - {0}"-f$entry.Name)
            }
            Write-CenteredLineVSO -Text 'Los programas seguiran instalados y podras abrirlos manualmente.' -Color $script:ThemeText
            if((Read-CenteredPromptVSO -Text '¿Continuar? [S/N]')-notmatch'^[sSyY]$'){
                continue
            }
            try{
                [void](New-StartupRecoverySnapshotVSO -Entries $selection)
            }catch{
                Write-VSO7Log ("Cancelado: no se pudo crear snapshot de inicio: {0}"-f$_.Exception.Message) 'ERROR';
                Pause-Vico;
                continue
            }
            foreach($entry in $selection){
                try{
                    Disable-StartupEntryVSO -Entry $entry
                }catch{
                    Write-VSO7Log ("Se detiene el lote en {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR';
                    break
                }
            }
            $selected=@{};
            Pause-Vico;
            continue

        }

    }

}

function Show-OverlayProcessManagerVSO {

    $selected=@{}
    while($true){

        Write-Title;
        Write-CenteredLineVSO -Text 'OVERLAYS / PROCESOS DE JUEGO' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Selecciona procesos para cerrarlos ahora. Esto NO cambia su autoarranque ni desinstala nada.' -Color 'Green';
        Write-VSOHost ''
        $items=@(Get-RunningOverlayCandidates)
        if($items.Count-eq0){
            Write-CenteredLineVSO -Text 'No se detectaron overlays o launchers conocidos ejecutandose.' -Color $script:ThemeMuted;
            Pause-Vico;
            return
        }
        $rows=@();
        for($i=0;$i-lt$items.Count;$i++){
            $entry=$items[$i];
            $key=[string]$entry.Id;
            $mark=if($selected.ContainsKey($key)){
                'X'
            }else{
                ' '
            };
            $rows += [pscustomobject]@{
                Text=("[{0}] [{1}] {2}"-f($i+1),$mark,$entry.Process);
                Color='Gray';
                Description=($(Get-VSO7ConsoleTextVSO -Es 'PID {0} | RAM aproximada: {1} MB. Marcarlo solo lo prepara para el cierre; todavia no se cierra.' -En 'PID {0} | Approximate RAM: {1} MB. Selecting it prepares it for closure; it is not closed yet.')-f$entry.Id,$entry.RAM_MB)
            }
        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        $allNumber=$items.Count+1;
        $clearNumber=$items.Count+2;
        $closeNumber=$items.Count+3
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar todos' -En '[{0}] Select all')-f$allNumber);Color='Gray';Description='Marca todos los procesos mostrados. No los cierra todavia.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Quitar toda la seleccion' -En '[{0}] Clear the selection')-f$clearNumber);Color='Gray';Description='Desmarca todos los procesos sin hacer cambios.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Cerrar los procesos seleccionados' -En '[{0}] Close selected processes')-f$closeNumber);Color='Yellow';Description='Pide confirmacion y cierra solo los procesos que hayas marcado y cuya identidad siga coincidiendo.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa sin cerrar procesos pendientes.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Opcion / numero';
        if($choice-eq'0'){
            return
        };
        $number=0;
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }
        if($number-ge1-and$number-le$items.Count){
            $key=[string]$items[$number-1].Id;
            if($selected.ContainsKey($key)){
                $selected.Remove($key)
            }else{
                $selected[$key]=$true
            };
            continue
        }
        if($number-eq$allNumber){
            $selected=@{};
            foreach($entry in $items){
                $selected[[string]$entry.Id]=$true
            };
            continue
        }
        if($number-eq$clearNumber){
            $selected=@{};
            continue
        }
        if($number-eq$closeNumber){

            $selection=@($items|Where-Object{
                $selected.ContainsKey([string]$_.Id)
            });
            if($selection.Count-eq0){
                Write-CenteredLineVSO -Text 'No hay procesos seleccionados.' -Color $script:ThemeMuted;
                Pause-Vico;
                continue
            }
            Write-VSOHost '';
            foreach($entry in $selection){
                Write-VSOHost (" - {0} (PID {1})"-f$entry.Process,$entry.Id)
            }
            if((Read-CenteredPromptVSO -Text '¿Cerrar ahora? [S/N]')-match'^[sSyY]$'){

                foreach($entry in $selection){
                    $current=$null;
                    try{
                        $current=Get-Process -Id $entry.Id -ErrorAction SilentlyContinue;
                        if($null-eq$current){
                            Write-VSO7Log ("No se cierra {0}: el proceso ya termino."-f$entry.Process) 'WARN';
                            continue
                        };
                        if([string]::IsNullOrWhiteSpace([string]$entry.StartTimeUtc)){
                            Write-VSO7Log ("No se cierra {0} (PID {1}): no se pudo guardar una identidad suficientemente fuerte."-f$entry.Process,$entry.Id) 'WARN';
                            continue
                        };
                        if(-not(Test-VSO7ProcessIdentityMatch -Expected $entry -Process $current)){
                            Write-VSO7Log ("No se cierra {0} (PID {1}): el PID fue reutilizado o cambio la identidad del proceso."-f$entry.Process,$entry.Id) 'WARN';
                            continue
                        };
                        Stop-Process -Id $entry.Id -Force -ErrorAction Stop;
                        Write-VSO7Log ("Proceso cerrado: {0} ({1})"-f$entry.Process,$entry.Id) 'CHANGE'
                    }catch{
                        Write-VSO7Log ("No se pudo cerrar {0}: {1}"-f$entry.Process,$_.Exception.Message) 'WARN'
                    }finally{
                        Close-VSO7ProcessObjectVSO -Process $current
                    }
                }

            }
            $selected=@{};
            continue

        }

    }

}

