}

function Get-RamDiagnostics {

    $modules = @()

    try {

        $modules = @(CimCmdlets\Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop | ForEach-Object {

            $configured = 0
            try {
                $configured = [int]$_.ConfiguredClockSpeed
            } catch {}
            if ($configured -le 0) {

                try {
                    $configured = [int]$_.Speed
                } catch {}

            }

            [pscustomobject]@{

                DeviceLocator = [string]$_.DeviceLocator
                BankLabel = [string]$_.BankLabel
                CapacityGB = [math]::Round([double]$_.Capacity / 1GB, 1)
                ConfiguredMTs = $configured
                RatedMTs = $(try {
                    [int]$_.Speed
                } catch {
                    0
                })
                Manufacturer = ([string]$_.Manufacturer).Trim()
                PartNumber = ([string]$_.PartNumber).Trim()

            }

        })

    } catch {}

    $totalGB = 0
    $configuredSpeeds = @()

    foreach ($m in $modules) {

        $totalGB += [double]$m.CapacityGB
        if ([int]$m.ConfiguredMTs -gt 0) {

            $configuredSpeeds += [int]$m.ConfiguredMTs

        }

    }

    $lowestConfigured = $null
    if ($configuredSpeeds.Count -gt 0) {

        $lowestConfigured = ($configuredSpeeds | Measure-Object -Minimum).Minimum

    }

    return [pscustomobject]@{

        Modules = $modules
        ModuleCount = $modules.Count
        TotalGB = [math]::Round($totalGB, 1)
        LowestConfiguredMTs = $lowestConfigured

    }

}

function Show-RamDetails {

    Write-Title
    Write-VSOHost 'MEMORIA RAM' -ForegroundColor Cyan
    Write-VSOHost '-----------'
    Write-VSOHost ''

    $ram = Get-RamDiagnostics

    if ($ram.ModuleCount -eq 0) {

        Write-VSOHost 'Windows no ha podido enumerar los módulos de RAM.' -ForegroundColor Yellow
        Pause-Vico
        return

    }

    Write-CenteredTableVSO -Rows @($ram.Modules) -Properties @('DeviceLocator','BankLabel','CapacityGB','ConfiguredMTs','RatedMTs','Manufacturer','PartNumber')

    Write-VSOHost ''
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Módulos detectados : {0}' -En 'Detected modules : {0}') -f $ram.ModuleCount)
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Capacidad detectada: {0} GB' -En 'Detected capacity: {0} GB') -f $ram.TotalGB)

    if ($null -ne $ram.LowestConfiguredMTs) {

        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Velocidad configurada mínima: {0} MT/s' -En 'Minimum configured speed: {0} MT/s') -f $ram.LowestConfiguredMTs)

    }

    Write-VSOHost ''
    if ($ram.ModuleCount -eq 1) {

        Write-VSOHost 'REVISAR: solo hay un módulo físico detectado.' -ForegroundColor Yellow
        Write-VSOHost 'Con una iGPU, un único módulo suele limitar el ancho de banda de memoria.' -ForegroundColor Yellow

    } else {

        Write-VSOHost 'Hay al menos dos módulos físicos instalados.' -ForegroundColor Green
        Write-VSOHost 'Windows/WMI no permite confirmar de forma fiable el modo dual-channel; confírmalo con CPU-Z/HWiNFO si quieres certeza.' -ForegroundColor DarkGray

    }

    Pause-Vico

}

function Get-GpuDiagnostics {

    try {

