                    $driverDate = [datetime]$_.DriverDate
                } catch {}

            }

            [pscustomobject]@{

                Name = [string]$_.Name
                DriverVersion = [string]$_.DriverVersion
                DriverDate = $driverDate
                AdapterRAMGB = $(if ([double]$_.AdapterRAM -gt 0) {
                    [math]::Round([double]$_.AdapterRAM / 1GB, 1)
                } else {
