}

function Get-LiveCpuUsage {

    param(
        [int]$Samples = 3,
        [int]$DelaySeconds = 1
    )

    $logical = [Environment]::ProcessorCount
    if ($logical -lt 1) {
        $logical = 1
    }

    $bucket = @{}

    for ($sample = 0; $sample -lt $Samples; $sample++) {

        try {

            $rows = @(CimCmdlets\Get-CimInstance Win32_PerfFormattedData_PerfProc_Process -ErrorAction Stop |
                Where-Object {

                    [int]$_.IDProcess -gt 0 -and
                    $_.Name -notin @('_Total','Idle')

            })

            foreach ($row in $rows) {

                $id = [int]$row.IDProcess
                $key = [string]$id

                if (-not $bucket.ContainsKey($key)) {

                    $bucket[$key] = [pscustomobject]@{

                        Id = $id
                        Name = [string]$row.Name
                        Sum = 0.0
                        Count = 0

                    }

                }

                $normalized = [double]$row.PercentProcessorTime / [double]$logical
                $bucket[$key].Sum += $normalized
                $bucket[$key].Count++

            }

        } catch {}

        if ($sample -lt ($Samples - 1)) {

            Start-Sleep -Seconds $DelaySeconds

        }

    }

    $result = @()

    foreach ($item in $bucket.Values) {

        if ($item.Count -le 0) {
            continue
        }

        $avg = [math]::Round($item.Sum / $item.Count, 1)
        $ramMB = $null

        $p=$null
        try {

            $p = Get-Process -Id $item.Id -ErrorAction Stop
            $ramMB = [math]::Round([double]$p.WorkingSet64 / 1MB, 1)

        } catch {} finally {
            Close-VSO7ProcessObjectVSO -Process $p
        }

        $result += [pscustomobject]@{

            Process = $item.Name
            Id = $item.Id
            CPU_Pct = $avg
            RAM_MB = $ramMB

        }

    }

    return @($result | Sort-Object CPU_Pct -Descending)

}

function Show-LiveProcesses {

    Write-Title
    Write-VSOHost 'CPU ACTUAL + RAM' -ForegroundColor Cyan
    Write-VSOHost '----------------'
    Write-VSOHost ''
    Write-VSOHost 'Midiendo durante unos segundos...' -ForegroundColor Gray
    Write-VSOHost ''

    $live = Get-LiveCpuUsage -Samples 3 -DelaySeconds 1

    if ($live.Count -eq 0) {

        Write-VSOHost 'No se pudo obtener una muestra de CPU actual.' -ForegroundColor Yellow
        Pause-Vico
        return

    }

    Write-CenteredTableVSO -Rows @($live|Select-Object -First 20 Process,Id,CPU_Pct,RAM_MB) -Properties @('Process','Id','CPU_Pct','RAM_MB')
    Write-VSOHost ''
    Write-VSOHost 'CPU_Pct es una media aproximada del porcentaje total de CPU del sistema, no CPU acumulada.' -ForegroundColor DarkGray

    Pause-Vico

}

function Get-DiskDiagnostics {

    $physical = @()
    try {

        $physical = @(Storage\Get-PhysicalDisk -ErrorAction Stop | ForEach-Object {

            [pscustomobject]@{

                FriendlyName = [string]$_.FriendlyName
                MediaType = [string]$_.MediaType
                BusType = [string]$_.BusType
                HealthStatus = [string]$_.HealthStatus
                OperationalStatus = ([string[]]$_.OperationalStatus -join ', ')
                SizeGB = [math]::Round([double]$_.Size / 1GB, 1)

            }

        })

    } catch {}

    $systemDrive = $null
    try {

        $driveId = $script:SystemDrive
        $d = CimCmdlets\Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $driveId) -ErrorAction Stop
        $freePct = 0
        if ([double]$d.Size -gt 0) {

            $freePct = [math]::Round(([double]$d.FreeSpace / [double]$d.Size) * 100, 1)

        }

        $systemDrive = [pscustomobject]@{

            Drive = $driveId
            FreeGB = [math]::Round([double]$d.FreeSpace / 1GB, 1)
            SizeGB = [math]::Round([double]$d.Size / 1GB, 1)
            FreePct = $freePct

        }

    } catch {}

    return [pscustomobject]@{

        Physical = $physical
        SystemDrive = $systemDrive

    }

}

function Get-RunningOverlayCandidates {

    param([switch]$Strict)
    $patterns=@('Discord','Medal','EpicGamesLauncher','EOSOverlayRenderer','GameBar','NVIDIA Overlay','RadeonSoftware')
    try{
        $processes=@(Get-Process -ErrorAction $(if($Strict){
            'Stop'
        }else{
            'SilentlyContinue'
        }))
    }catch{
        if($Strict){
            throw
        };
        $processes=@()
    }
    $result=@()
    try{
        foreach($p in $processes){
            foreach($pattern in $patterns){
                if($p.ProcessName-like"*$pattern*"-or$p.ProcessName-eq$pattern){
                    $identity=Get-VSO7ProcessIdentity -Process $p;
                    $result += [pscustomobject]@{
                        Process=[string]$p.ProcessName;
                        Name=[string]$identity.Name;
                        Id=[int]$identity.Id;
                        Path=[string]$identity.Path;
                        StartTimeUtc=[string]$identity.StartTimeUtc;
                        RAM_MB=[math]::Round([double]$p.WorkingSet64/1MB,1)
                    };
                    break
                }
            }
        }
    }finally{
        Close-VSO7ProcessCollectionVSO -Processes $processes
    }
    return @($result|Sort-Object Process,Id -Unique)

}

function Test-VSO7RecommendationSecurityGuardVSO {

    param([Parameter(Mandatory=$true)]$Feature)
    if($Feature.PSObject.Properties.Name-contains'SecurityReducing' -and [bool]$Feature.SecurityReducing){
        return $false
    }
    $text=(([string]$Feature.FeatureId)+' '+([string]$Feature.NameEn)+' '+([string]$Feature.DescriptionEn)).ToLowerInvariant()
    $protected=@('defender','firewall','smartscreen','tamper protection','credential guard','spectre','meltdown','hvci','vbs','virtualization based security','dep ',' cfg ')
    foreach($p in $protected){
        if($text.Contains($p)-and($text-match'(?i)disable|turn off|weaken|bypass')){
            return $false
        }
    }
    return $true

}

function Get-VSO7RecommendationPriorityVSO {

    param([Parameter(Mandatory=$true)]$Feature)
    $rec=switch([string]$Feature.Recommendation){
        'Recommended'{
            0
        }'Optional'{
            10
        }'Advanced'{
            20
        }default{
            50
        }
    }
    $maturity=switch([string]$Feature.Maturity){
        'Stable'{
            0
        }'Conditional'{
            2
        }default{
            10
        }
    }
    $evidence=switch([string]$Feature.Evidence){
        'E1'{
            0
        }'E2'{
            2
        }'E3'{
            5
        }default{
            10
        }
    }
    return ([int]$rec+[int]$maturity+[int]$evidence+([int]$Feature.Risk*2))

}

function Get-VSO7RecommendationDomainMatchVSO {

    param([Parameter(Mandatory=$true)]$Feature,[Parameter(Mandatory=$true)][ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Objective)
    # ObjectiveDomains is explicit policy. No objective inherits another one and
    # Balanced is never a universal fallback. This keeps the six rule sets
    # deterministic and makes catalog calibration visible/auditable.
    $domains=@($Feature.ObjectiveDomains|ForEach-Object{
        [string]$_
    })
    return ($domains-contains$Objective)

}

function Test-VSO7RecommendationAutoCandidateVSO {

    param([Parameter(Mandatory=$true)]$Feature,[switch]$IncludeOptional)

    # AutoSelection is executable policy, not descriptive metadata. Unknown or
    # missing values fail closed so a catalog mistake can never expand the
    # automatic mutation set.
    if($Feature.PSObject.Properties.Name-notcontains'AutoSelection'){

        return [pscustomobject]@{
            Eligible=$false;
            Reason='AutoSelectionMetadataMissing'
        }

    }
    $auto=[string]$Feature.AutoSelection
    if($auto-notin@('Eligible','Manual','Never')){

        return [pscustomobject]@{
            Eligible=$false;
            Reason=('AutoSelectionInvalid='+$auto)
        }

    }
    if($auto-eq'Manual'){

        return [pscustomobject]@{
            Eligible=$false;
            Reason='ManualSelectionRequired'
        }

    }
    if($auto-eq'Never'){

        return [pscustomobject]@{
            Eligible=$false;
            Reason='AutomaticSelectionProhibited'
        }

    }

    if(-not[bool]$Feature.Selectable){
        return [pscustomobject]@{
            Eligible=$false;
            Reason='NotSelectable'
        }
    }
    if([string]$Feature.FeatureType-ine'Mutation'){
        return [pscustomobject]@{
            Eligible=$false;
            Reason=('FeatureType='+[string]$Feature.FeatureType)
        }
    }
    if([string]$Feature.PreferenceVsOptimization-ieq'Preference'){
        return [pscustomobject]@{
            Eligible=$false;
            Reason='PreferenceOnly'
        }
    }
    if(-not(Test-VSO7RecommendationSecurityGuardVSO -Feature $Feature)){
        return [pscustomobject]@{
            Eligible=$false;
            Reason='SecurityGuard'
        }
    }

    $rec=[string]$Feature.Recommendation
    if($rec-in@('Experimental','Diagnostic','NotRecommended')){
        return [pscustomobject]@{
            Eligible=$false;
            Reason=('Recommendation='+$rec)
        }
    }
    if($rec-eq'Advanced'){
        return [pscustomobject]@{
            Eligible=$false;
            Reason='AdvancedRequiresExplicitSelection'
        }
    }
    if($rec-eq'Optional'-and-not$IncludeOptional){
        return [pscustomobject]@{
            Eligible=$false;
            Reason='OptionalNotRequested'
        }
    }
    if($rec-notin@('Recommended','Optional')){
        return [pscustomobject]@{
            Eligible=$false;
            Reason=('Recommendation='+$rec)
        }
    }
    if([string]$Feature.Maturity-notin@('Stable','Conditional')){
        return [pscustomobject]@{
            Eligible=$false;
            Reason=('Maturity='+[string]$Feature.Maturity)
        }
    }
    if([string]$Feature.Evidence-notin@('E1','E2')){
        return [pscustomobject]@{
            Eligible=$false;
            Reason=('Evidence='+[string]$Feature.Evidence)
        }
    }
    if([int]$Feature.Risk-gt2){
        return [pscustomobject]@{
            Eligible=$false;
            Reason=('Risk='+[string]$Feature.Risk)
        }
    }

    $why=if($rec-eq'Recommended'){
        'AutoSelectionEligible;CatalogRecommended'
    }else{
        'AutoSelectionEligible;OptionalExplicitlyIncluded'
    }
    return [pscustomobject]@{
        Eligible=$true;
        Reason=$why
    }

}

function Get-VSO7RecommendationAutoSelectionValidationVSO {

    param([AllowNull()][array]$Catalog)
    if($null-eq$Catalog){
        $Catalog=@(Get-VSO7FeatureCatalogVSO)
    }
    $valid=@('Eligible','Manual','Never')
    $invalid=New-Object System.Collections.Generic.List[object]
    $inconsistent=New-Object System.Collections.Generic.List[object]

    foreach($f in @($Catalog|Sort-Object FeatureId)){

        $id=[string]$f.FeatureId
        if($f.PSObject.Properties.Name-notcontains'AutoSelection'){

            [void]$invalid.Add([pscustomobject]@{
                FeatureId=$id;Value=$null;Reason='Missing'
            })
            continue

        }
        $auto=[string]$f.AutoSelection
        if($auto-notin$valid){

            [void]$invalid.Add([pscustomobject]@{
                FeatureId=$id;Value=$auto;Reason='UnknownValue'
            })
            continue

        }
        if($auto-ne'Eligible'){
            continue
        }

        $reasons=New-Object System.Collections.Generic.List[string]
        if([string]$f.FeatureType-ine'Mutation'){
            [void]$reasons.Add('EligibleRequiresMutation')
        }
        if([string]$f.PreferenceVsOptimization-ieq'Preference'){
            [void]$reasons.Add('EligibleCannotBePreference')
        }
        if([string]$f.Recommendation-in@('Experimental','Diagnostic','NotRecommended','Advanced')){
            [void]$reasons.Add('EligibleRecommendationIncompatible')
        }
        if([string]$f.Maturity-notin@('Stable','Conditional')){
            [void]$reasons.Add('EligibleMaturityIncompatible')
        }
        if([string]$f.Evidence-notin@('E1','E2')){
            [void]$reasons.Add('EligibleEvidenceInsufficient')
        }
        if([int]$f.Risk-gt2){
            [void]$reasons.Add('EligibleRiskTooHigh')
        }
        if(-not(Test-VSO7RecommendationSecurityGuardVSO -Feature $f)){
            [void]$reasons.Add('EligibleSecurityGuardConflict')
        }
        if($reasons.Count-gt0){

            [void]$inconsistent.Add([pscustomobject]@{
                FeatureId=$id;Value=$auto;Reasons=$reasons.ToArray()
            })

        }

    }

    return [pscustomobject]@{

        Total=@($Catalog).Count
        Eligible=@($Catalog|Where-Object{
            ($_.PSObject.Properties.Name-contains'AutoSelection')-and[string]$_.AutoSelection-eq'Eligible'
        }).Count
        Manual=@($Catalog|Where-Object{
            ($_.PSObject.Properties.Name-contains'AutoSelection')-and[string]$_.AutoSelection-eq'Manual'
        }).Count
        Never=@($Catalog|Where-Object{
            ($_.PSObject.Properties.Name-contains'AutoSelection')-and[string]$_.AutoSelection-eq'Never'
        }).Count
        Invalid=$invalid.Count
        Inconsistent=$inconsistent.Count
        InvalidItems=$invalid.ToArray()
        InconsistentItems=$inconsistent.ToArray()
        Pass=($invalid.Count-eq0-and$inconsistent.Count-eq0)

    }

}

function Resolve-VSO7RecommendationDependenciesVSO {

    param(
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][array]$Selected,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][array]$AlreadyOptimal,
        [Parameter(Mandatory=$true)][array]$Catalog,
        [switch]$IncludeOptional
    )

    # Requires se satisface si la FeatureId requerida permanece en el lote o su
    # Applicability demuestra AlreadySatisfied.
    # It does not yet encode arbitrary desired-state expressions.
    $work=New-Object System.Collections.Generic.List[object]
    foreach($c in @($Selected|Sort-Object {
        $_.Feature.FeatureId
    })){
        [void]$work.Add($c)
    }
    $already=New-Object System.Collections.Generic.List[object]
    foreach($a in @($AlreadyOptimal|Sort-Object {
        $_.Feature.FeatureId
    })){
        [void]$already.Add($a)
    }
    $skipped=New-Object System.Collections.Generic.List[object]

    $catalogById=@{}
    foreach($f in @($Catalog)){
        $catalogById[[string]$f.FeatureId]=$f
    }
    $satisfied=@{}
    foreach($a in $already.ToArray()){
        $satisfied[[string]$a.Feature.FeatureId]=$true
    }
    $dependencyProbe=@{}

    $changed=$true
    while($changed){

        $changed=$false
        $selectedIds=@{}
        foreach($c in $work.ToArray()){
            $selectedIds[[string]$c.Feature.FeatureId]=$true
        }

        foreach($c in @($work.ToArray()|Sort-Object {
            $_.Feature.FeatureId
        })){

            $unsatisfied=New-Object System.Collections.Generic.List[string]
            foreach($rawReq in @($c.Feature.Requires)){

                $req=[string]$rawReq
                if([string]::IsNullOrWhiteSpace($req)){
                    continue
                }
                if($selectedIds.ContainsKey($req)-or$satisfied.ContainsKey($req)){
                    continue
                }

                if(-not$catalogById.ContainsKey($req)){

                    [void]$unsatisfied.Add(($req+':MissingFeature'))
                    continue

                }

                if(-not$dependencyProbe.ContainsKey($req)){

                    $depFeature=$catalogById[$req]
                    try{

                        $depApp=Get-VSO7FeatureApplicabilityVSO -Feature $depFeature
                        if([bool]$depApp.AlreadySatisfied){

                            $reason=if($script:Language-eq'en'){
                                [string]$depApp.ReasonEn
                            }else{
                                [string]$depApp.ReasonEs
                            }
                            if([string]::IsNullOrWhiteSpace($reason)){
                                $reason='Dependency already satisfies its desired state.'
                            }
                            $dependencyProbe[$req]=[pscustomobject]@{
                                Satisfied=$true;
                                Reason='AlreadyOptimal';
                                Applicability=$depApp
                            }
                            $satisfied[$req]=$true
                            if(@($already|Where-Object{
                                [string]$_.Feature.FeatureId-ceq$req
                            }).Count-eq0){

                                [void]$already.Add([pscustomobject]@{
                                    Feature=$depFeature;Applicability=$depApp;Status='AlreadyOptimal';Reason=$reason;DependencyOnly=$true
                                })

                            }

                        }else{

                            $policy=Test-VSO7RecommendationAutoCandidateVSO -Feature $depFeature -IncludeOptional:$IncludeOptional
                            $state=if(-not[bool]$depApp.Applicable){
                                'NotApplicable'
                            }elseif(-not[bool]$policy.Eligible){
                                [string]$policy.Reason
                            }else{
                                'NotSelected'
                            }
                            $dependencyProbe[$req]=[pscustomobject]@{
                                Satisfied=$false;
                                Reason=$state;
                                Applicability=$depApp
                            }

                        }

                    }catch{

                        $dependencyProbe[$req]=[pscustomobject]@{
                            Satisfied=$false;
                            Reason='ApplicabilityError';
                            Applicability=$null
                        }

                    }

                }

                if([bool]$dependencyProbe[$req].Satisfied){

                    $satisfied[$req]=$true
                    continue

                }
                [void]$unsatisfied.Add(($req+':'+[string]$dependencyProbe[$req].Reason))

            }

            if($unsatisfied.Count-gt0){

                [void]$skipped.Add([pscustomobject]@{
                    Feature=$c.Feature;Status='DependencySkipped';Reason=('Unsatisfied required feature(s): '+($unsatisfied-join', '))
                })
                [void]$work.Remove($c)
                $changed=$true

            }

        }

    }

    # Detect dependency cycles among the surviving selected nodes. Kahn-style
    # reduction is deterministic; anything left is a cycle or blocked by one
    # and therefore fails closed.
    $node=@{}
    foreach($c in $work.ToArray()){
        $node[[string]$c.Feature.FeatureId]=$c
    }
    $remaining=@{}
    foreach($id in @($node.Keys)){
        $remaining[$id]=$true
    }
    $processed=@{}
    $progress=$true
    while($progress){

        $progress=$false
        foreach($id in @($remaining.Keys|Sort-Object)){

            $c=$node[$id]
            $blocking=@($c.Feature.Requires|Where-Object{

                $r=[string]$_
                -not[string]::IsNullOrWhiteSpace($r)-and$remaining.ContainsKey($r)-and-not$processed.ContainsKey($r)

            })
            if($blocking.Count-eq0){

                $processed[$id]=$true
                [void]$remaining.Remove($id)
                $progress=$true

            }

        }

    }
    if($remaining.Count-gt0){

        foreach($id in @($remaining.Keys|Sort-Object)){

            $c=$node[$id]
            [void]$skipped.Add([pscustomobject]@{
                Feature=$c.Feature;Status='DependencyCycle';Reason='Dependency cycle or dependency chain blocked by a cycle.'
            })
            [void]$work.Remove($c)

        }

    }

    return [pscustomobject]@{

        Selected=@($work|Sort-Object {
            $_.Feature.FeatureId
        })
        AlreadyOptimal=@($already|Sort-Object {
            $_.Feature.FeatureId
        })
        Skipped=@($skipped|Sort-Object {
            $_.Feature.FeatureId
        })

    }

}

function Test-VSO7RecommendedBatchModeVSO {

    param([Parameter(Mandatory=$true)][string]$FeatureId)
    $def=@(Get-VSO7NativeDataVSO).Features|Where-Object{
        [string]$_.FeatureId-ceq$FeatureId
    }|Select-Object -First 1
    if($null-eq$def){
        return [pscustomobject]@{
            Allowed=$false;
            Reason='NativeDefinitionMissing';
            Mode=$null
        }
    }
    $mode=[string]$def.Mode
    $allowed=@('Registry','PowerSetting','NetAdapterRss','NetAdapterAdvanced','NetOffloadGlobal','NetTcpSetting','NetTcpCimSetting','FsutilTrim','ScheduledTaskState','NetAdapterPower')
    return [pscustomobject]@{
        Allowed=($allowed-contains$mode);
        Reason=$(if($allowed-contains$mode){
            'BatchPreflightSupported'
        }else{
            'PrimitiveRequiresExplicitFlow'
        });
        Mode=$mode
    }

}

function Resolve-VSO7RecommendationConflictsVSO {

    param([Parameter(Mandatory=$true)][AllowEmptyCollection()][array]$Candidates)
    $ordered=@($Candidates|Sort-Object @{
        Expression={
            Get-VSO7RecommendationPriorityVSO -Feature $_.Feature
        }
    },@{
        Expression={
            [string]$_.Feature.FeatureId
        }
    })
    $selected=New-Object System.Collections.Generic.List[object]
    $skipped=New-Object System.Collections.Generic.List[object]
    foreach($candidate in $ordered){

        $f=$candidate.Feature;
        $conflict=$null
        foreach($existing in $selected.ToArray()){

            $ef=$existing.Feature
            if((-not[string]::IsNullOrWhiteSpace([string]$f.MutuallyExclusiveGroup))-and[string]$f.MutuallyExclusiveGroup-ceq[string]$ef.MutuallyExclusiveGroup){
                $conflict=$ef;
                break
            }
            if(@($f.ConflictsWith)-contains[string]$ef.FeatureId-or@($ef.ConflictsWith)-contains[string]$f.FeatureId){
                $conflict=$ef;
                break
            }

        }
        if($null-ne$conflict){

            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='ConflictSkipped';Reason=('Conflicts with selected '+[string]$conflict.FeatureId)
            })

        }else{
            [void]$selected.Add($candidate)
        }

    }
    return [pscustomobject]@{
        Selected=$selected.ToArray();
        Skipped=$skipped.ToArray()
    }

}

function Get-VSO7RecommendedOptimizationPlanVSO {

    param(
        [ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Objective='Balanced',
        [switch]$IncludeOptional,
        [AllowNull()][AllowEmptyCollection()][string[]]$ExplicitFeatureIds
    )
    $catalog=@(Get-VSO7FeatureCatalogVSO|Sort-Object FeatureId)
    $planMode=if($IncludeOptional){
        'RecommendedPlusOptional'
    }else{
        'Recommended'
    }
    $objectiveMode=if($Objective-eq'Privacy'){
        'ManualOnly'
    }else{
        'Automatic'
    }
    $autoValidation=Get-VSO7RecommendationAutoSelectionValidationVSO -Catalog $catalog
    if(-not[bool]$autoValidation.Pass){

        throw ('Recommendation catalog AutoSelection validation failed closed. Invalid='+[string]$autoValidation.Invalid+'; Inconsistent='+[string]$autoValidation.Inconsistent)

    }
    # Omitted scope keeps the historical global behavior; explicit null/empty is empty.
    $allCatalog=$catalog
    if($PSBoundParameters.ContainsKey('ExplicitFeatureIds')){
        $allowed=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach($id in @($ExplicitFeatureIds)){
            if(-not[string]::IsNullOrWhiteSpace([string]$id)){[void]$allowed.Add([string]$id)}
        }
        $catalog=@($catalog|Where-Object{$allowed.Contains([string]$_.FeatureId)})
    }
    $selectedCandidates=New-Object System.Collections.Generic.List[object]
    $already=New-Object System.Collections.Generic.List[object]
    $optional=New-Object System.Collections.Generic.List[object]
    $skipped=New-Object System.Collections.Generic.List[object]
    $diagnostic=0;
    $experimental=0;
    $advanced=0;
    $preferences=0;
    $unsupported=0;
    $ambiguous=0
    foreach($f in $catalog){

        $id=[string]$f.FeatureId
        $rec=[string]$f.Recommendation
        if($rec-eq'Diagnostic'-or[string]$f.FeatureType-eq'Diagnostic'){
            $diagnostic++;
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='Diagnostic';Reason='Diagnostic capability; never added to mutation batch.'
            });
            continue
        }
        if($rec-eq'Experimental'){
            $experimental++;
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='Experimental';Reason='Experimental requires explicit expert selection.'
            });
            continue
        }
        if($rec-eq'Advanced'){
            $advanced++
        }
        if([string]$f.PreferenceVsOptimization-eq'Preference'){
            $preferences++;
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='Preference';Reason='Subjective preference; not an objective auto-optimization.'
            });
            continue
        }
        if($Objective-eq'Privacy'-and(@($f.ObjectiveDomains)-contains'Privacy')){
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='ManualSelectionRequired';Reason='PrivacyObjectiveManualOnly: current Privacy mutations do not meet automatic E1/E2 + applicability policy.'
            });
            continue
        }
        if(-not(Get-VSO7RecommendationDomainMatchVSO -Feature $f -Objective $Objective)){
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='ObjectiveMismatch';Reason=('ObjectiveMismatch: '+$Objective)
            });
            continue
        }
        $candidate=Test-VSO7RecommendationAutoCandidateVSO -Feature $f -IncludeOptional:$IncludeOptional
        if(-not[bool]$candidate.Eligible){

            if($rec-eq'Optional'){
                [void]$optional.Add([pscustomobject]@{
                    Feature=$f;Status='Optional';Reason=[string]$candidate.Reason
                })
            }
            $skipStatus=switch -Regex ([string]$candidate.Reason){

                '^ManualSelectionRequired$' {
                    'ManualSelectionRequired';
                    break
                }
                '^AutomaticSelectionProhibited$' {
                    'AutomaticSelectionProhibited';
                    break
                }
                '^AutoSelection(Metadata|Invalid)' {
                    'MetadataInvalid';
                    break
                }
                '^OptionalNotRequested$' {
                    'OptionalNotRequested';
                    break
                }
                default {
                    'Manual';
                    break
                }

            }
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status=$skipStatus;Reason=[string]$candidate.Reason
            });
            continue

        }
        $batch=Test-VSO7RecommendedBatchModeVSO -FeatureId $id
        if(-not[bool]$batch.Allowed){
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status='Manual';Reason=[string]$batch.Reason
            });
            continue
        }
        $app=Get-VSO7FeatureApplicabilityVSO -Feature $f
        if([bool]$app.AlreadySatisfied){

            [void]$already.Add([pscustomobject]@{
                Feature=$f;Applicability=$app;Status='AlreadyOptimal';Reason=if($script:Language-eq'en'){
                    [string]$app.ReasonEn
                }else{
                    [string]$app.ReasonEs
                }
            });
            continue

        }
        if(-not[bool]$app.Applicable){

            $reason=if($script:Language-eq'en'){
                [string]$app.ReasonEn
            }else{
                [string]$app.ReasonEs
            }
            if($reason-match'(?i)ambig|unknown|no se pudo verificar|could not verify'){
                $ambiguous++
            }else{
                $unsupported++
            }
            [void]$skipped.Add([pscustomobject]@{
                Feature=$f;Status=$(if($reason-match'(?i)ambig|unknown'){
                    'Ambiguous'
                }else{
                    'NotApplicable'
                });Reason=$reason
            });
            continue

        }
        $reason=if($script:Language-eq'en'){
            [string]$app.ReasonEn
        }else{
            [string]$app.ReasonEs
        }
        if([string]::IsNullOrWhiteSpace($reason)){
            $reason=('Applicable; '+[string]$f.Recommendation+', '+[string]$f.Evidence+', risk '+[string]$f.Risk)
        }
        $selectedWhy=($Objective+'; '+$planMode+'; '+[string]$f.Recommendation+'; '+[string]$f.AutoSelection+'; '+[string]$f.Evidence+'; '+[string]$f.Maturity+'; '+[string]$candidate.Reason+'; '+$reason)
        [void]$selectedCandidates.Add([pscustomobject]@{
            Feature=$f;Applicability=$app;Status='Selected';Reason=$selectedWhy;PolicyReason=[string]$candidate.Reason;BatchMode=[string]$batch.Mode
        })

    }
    $resolved=Resolve-VSO7RecommendationConflictsVSO -Candidates $selectedCandidates.ToArray()
    foreach($s in @($resolved.Skipped)){
        [void]$skipped.Add($s)
    }
    # Resolve Requires with AlreadyOptimal-aware semantics, then fail closed
    # on cycles. Dependency-only AlreadyOptimal items are surfaced in preview.
    $depResolved=Resolve-VSO7RecommendationDependenciesVSO -Selected @($resolved.Selected) -AlreadyOptimal $already.ToArray() -Catalog $allCatalog -IncludeOptional:$IncludeOptional
    foreach($s in @($depResolved.Skipped)){
        [void]$skipped.Add($s)
    }
    $alreadyFinal=@($depResolved.AlreadyOptimal)
    $selection=@($depResolved.Selected|Sort-Object @{
        Expression={
            [string]$_.Feature.CategoryEn
        }
    },@{
        Expression={
            [string]$_.Feature.FeatureId
        }
    })
    $counts=[ordered]@{

        TotalFeatures=$catalog.Count;
        Selected=$selection.Count;
        AlreadyOptimal=$alreadyFinal.Count
        SelectedRecommended=@($selection|Where-Object{
            [string]$_.Feature.Recommendation-eq'Recommended'
        }).Count
        SelectedOptional=@($selection|Where-Object{
            [string]$_.Feature.Recommendation-eq'Optional'
        }).Count
        OptionalNotSelected=$optional.Count
        ManualAvailable=@($skipped|Where-Object{
            [string]$_.Status-eq'ManualSelectionRequired'
        }).Count
        AutomaticNever=@($skipped|Where-Object{
            [string]$_.Status-eq'AutomaticSelectionProhibited'
        }).Count
        AdvancedNotSelected=$advanced;
        ExperimentalNotSelected=$experimental;
        PreferencesNotSelected=$preferences
        Diagnostics=$diagnostic;
        NotApplicable=$unsupported;
        Ambiguous=$ambiguous;
        Skipped=$skipped.Count

    }
    return [pscustomobject]@{

        Product='VSO7';
        Version=$script:Version;
        Engine='R44 Rule-Based Recommendation';
        Objective=$Objective;
        ObjectiveMode=$objectiveMode;
        PlanMode=$planMode;
        IncludeOptional=[bool]$IncludeOptional
        AutoSelectionValidation=$autoValidation
        GeneratedAt=(Get-Date).ToString('o');
        Selected=$selection;
        AlreadyOptimal=@($alreadyFinal|Sort-Object {
            $_.Feature.FeatureId
        })
        Optional=@($optional|Sort-Object {
            $_.Feature.FeatureId
        });
        Skipped=@($skipped|Sort-Object {
            $_.Feature.FeatureId
        });
        Counts=[pscustomobject]$counts
        Determinism='Catalog sorted by FeatureId; conflicts resolved by Recommendation/Maturity/Evidence/Risk then FeatureId.'

    }

}

function Get-VSO7RecommendationCatalogCoverageVSO {

    $catalog=@(Get-VSO7FeatureCatalogVSO)
    $mutable=@($catalog|Where-Object{
        [string]$_.FeatureType-eq'Mutation'
    })
    return [pscustomobject]@{

        Total=$catalog.Count;
        Mutable=$mutable.Count;
        Diagnostic=@($catalog|Where-Object{
            [string]$_.FeatureType-eq'Diagnostic'
        }).Count
        Preference=@($catalog|Where-Object{
            [string]$_.FeatureType-eq'Preference'
        }).Count
        Recommended=@($catalog|Where-Object{
            [string]$_.Recommendation-eq'Recommended'
        }).Count
        Optional=@($catalog|Where-Object{
            [string]$_.Recommendation-eq'Optional'
        }).Count
        Advanced=@($catalog|Where-Object{
            [string]$_.Recommendation-eq'Advanced'
        }).Count
        Experimental=@($catalog|Where-Object{
            [string]$_.Recommendation-eq'Experimental'
        }).Count
        NotRecommended=@($catalog|Where-Object{
            [string]$_.Recommendation-eq'NotRecommended'
        }).Count
        AutoSelectionEligible=@($catalog|Where-Object{
            [string]$_.AutoSelection-eq'Eligible'
        }).Count
        AutoSelectionManual=@($catalog|Where-Object{
            [string]$_.AutoSelection-eq'Manual'
        }).Count
        AutoSelectionNever=@($catalog|Where-Object{
            [string]$_.AutoSelection-eq'Never'
        }).Count
        AutoSelectionValidation=(Get-VSO7RecommendationAutoSelectionValidationVSO -Catalog $catalog)
        MetadataComplete=@($catalog|Where-Object{

            $_.PSObject.Properties.Name-contains'Evidence'-and$_.PSObject.Properties.Name-contains'Maturity'-and$_.PSObject.Properties.Name-contains'Recommendation'-and
            $_.PSObject.Properties.Name-contains'Applicability'-and$_.PSObject.Properties.Name-contains'RestartSemantics'-and
            $_.PSObject.Properties.Name-contains'FeatureType'-and$_.PSObject.Properties.Name-contains'ObjectiveDomains'-and$_.PSObject.Properties.Name-contains'AutoSelection'

        }).Count

    }

}

function Get-VSO7NativeFeaturePreflightSnapshotVSO {

    param([Parameter(Mandatory=$true)][string]$FeatureId)
    $def=@((Get-VSO7NativeDataVSO).Features|Where-Object{
        [string]$_.FeatureId-ceq$FeatureId
    }|Select-Object -First 1)
    if($def.Count-ne1){
        throw ('No existe NativeDefinition para preflight: '+$FeatureId)
    }
    $mode=[string]$def[0].Mode;
    $items=New-Object System.Collections.Generic.List[object]
    foreach($op in @($def[0].Apply)){

        switch($mode){

            'Registry' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Path=[string]$op.Path;Name=[string]$op.Name;State=(Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$op.Path) -Name ([string]$op.Name))
                })
            }
            'PowerSetting' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;SubGroup=[string]$op.SubGroupAlias;Setting=[string]$op.SettingAlias;State=(Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias ([string]$op.SubGroupAlias) -SettingAlias ([string]$op.SettingAlias))
                })
            }
            'NetAdapterRss' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Targets=@(Get-VSO7PhysicalRssTargetsVSO|Sort-Object InterfaceGuid)
                })
            }
            'NetAdapterAdvanced' {

                $rows=@()
                foreach($identity in @(Get-VSO7PhysicalAdapterTargetsVSO -OnlyUp|Sort-Object InterfaceGuid)){

                    foreach($spec in @($op.Properties)){

                        $snap=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $identity -RegistryKeyword ([string]$spec.RegistryKeyword)
                        if($null-ne$snap){
                            $rows+=,$snap
                        }

                    }

                }
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Targets=@($rows|Sort-Object InterfaceGuid,RegistryKeyword)
                })

            }
            'NetOffloadGlobal' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Property=[string]$op.Property;State=(Get-VSO7GlobalOffloadStateVSO -Property ([string]$op.Property))
                })
            }
            'NetTcpSetting' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Property=[string]$op.Property;Targets=@(Get-VSO7TcpSettingTargetsVSO -Property ([string]$op.Property)|Sort-Object SettingName)
                })
            }
            'NetTcpCimSetting' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Targets=@(Get-VSO7TcpTimestampCimInstancesVSO|Select-Object SettingName,Property,Value,RawValue|Sort-Object SettingName)
                })
            }
            'FsutilTrim' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;State=(Get-VSO7FsutilTrimStateVSO)
                })
            }
            'ScheduledTaskState' {
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;State=(Get-VSO7ScheduledTaskSnapshotVSO -TaskPath ([string]$op.TaskPath) -TaskName ([string]$op.TaskName))
                })
            }
            'NetAdapterPower' {

                $onlyUp=$false;
                if($op.PSObject.Properties.Name-contains'OnlyUp'){
                    $onlyUp=[bool]$op.OnlyUp
                }
                [void]$items.Add([pscustomobject]@{
                    Action=[string]$op.Action;Property=[string]$op.Property;Targets=@(Get-VSO7NetAdapterPowerTargetsVSO -Property ([string]$op.Property) -OnlyUp:$onlyUp|Sort-Object InterfaceGuid)
                })

            }
            default {
                throw ('Primitive no soportada por el preflight global R44: '+$mode)
            }

        }

    }
    $snapshot=[pscustomobject]@{
        FeatureId=$FeatureId;
        Mode=$mode;
        Items=$items.ToArray()
    }
    $json=$snapshot|ConvertTo-Json -Depth 12 -Compress
    $sha=[Security.Cryptography.SHA256]::Create()
    try{
        $bytes=[Text.Encoding]::UTF8.GetBytes($json);
        $hash=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','')
    }finally{
        $sha.Dispose()
    }
    return [pscustomobject]@{
        FeatureId=$FeatureId;
        Mode=$mode;
        Hash=$hash;
        Snapshot=$snapshot
    }

}

function Get-VSO7KnownInternalNativeOwnershipIdsVSO {

    # Ownership IDs created by VSO7 subsystems that are intentionally not public catalog features.
    return @('V7GP-PERAPP')

}

function ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $value=([string]$Path).Trim().Replace('/','\')
    if([string]::IsNullOrWhiteSpace($value)){
        throw 'Path Registry vacio al canonicalizar ownership.'
    }
    $value=[regex]::Replace($value,'\\+','\')
    $maps=@(
        [pscustomobject]@{
        Pattern='^(?i)(?:HKLM|HKEY_LOCAL_MACHINE):?\\?(.*)$';Hive='HKEY_LOCAL_MACHINE'
    },
        [pscustomobject]@{
        Pattern='^(?i)(?:HKCU|HKEY_CURRENT_USER):?\\?(.*)$';Hive='HKEY_CURRENT_USER'
    },
        [pscustomobject]@{
        Pattern='^(?i)(?:HKCR|HKEY_CLASSES_ROOT):?\\?(.*)$';Hive='HKEY_CLASSES_ROOT'
    },
        [pscustomobject]@{
        Pattern='^(?i)(?:HKU|HKEY_USERS):?\\?(.*)$';Hive='HKEY_USERS'
    },
        [pscustomobject]@{
        Pattern='^(?i)(?:HKCC|HKEY_CURRENT_CONFIG):?\\?(.*)$';Hive='HKEY_CURRENT_CONFIG'
    }
    )
    foreach($map in $maps){

        if($value-match[string]$map.Pattern){

            $sub=([string]$matches[1]).Trim('\')
            if([string]::IsNullOrWhiteSpace($sub)){
                return [string]$map.Hive
            }
            return ('{0}\{1}'-f[string]$map.Hive,$sub)

        }

    }
    throw ('Path Registry fuera de los hives soportados para ownership: {0}'-f$Path)

}

function Assert-VSO7NoNativeRegistryOwnershipVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Name)
    $canonical=ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path $Path
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        [string]$_.Status-cne'Restored'
    })){

        foreach($entry in @($session.Entries)){

            if([string]$entry.Type-ieq'RegistryValue' -and (ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$entry.Path))-ieq$canonical -and [string]$entry.Name-ieq$Name){

                throw ('Recovery nativo activo ya posee Registry {0}\\{1}; restaura/revisa esa sesion antes de usar otro motor VSO.'-f$canonical,$Name)

            }

        }

    }
    return $true

}

function Assert-VSO7NoNativePowerOwnershipVSO {

    param([Parameter(Mandatory=$true)][string]$SchemeGuid,[Parameter(Mandatory=$true)][string]$SubGroupAlias,[Parameter(Mandatory=$true)][string]$SettingAlias)
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        [string]$_.Status-cne'Restored'
    })){

        foreach($entry in @($session.Entries)){

            if([string]$entry.Type-ieq'PowerSetting' -and [string]$entry.SchemeGuid-ieq$SchemeGuid -and [string]$entry.SubGroupAlias-ieq$SubGroupAlias -and [string]$entry.SettingAlias-ieq$SettingAlias){

                throw ('Recovery nativo activo ya posee PowerSetting {0}/{1} en el plan {2}; restaura/revisa esa sesion antes de usar EXTREMO.'-f$SubGroupAlias,$SettingAlias,$SchemeGuid)

            }

        }

    }
    return $true

}

function Assert-VSO7NoNativeOptionalFeatureOwnershipVSO {

    param([Parameter(Mandatory=$true)][string]$Name)
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        [string]$_.Status-cne'Restored'
    })){

        foreach($entry in @($session.Entries)){

            if([string]$entry.Type-ieq'OptionalFeature' -and [string]$entry.Name-ieq$Name){

                throw ('Recovery nativo activo ya posee OptionalFeature {0}; restaura/revisa esa sesion antes de usar EXTREMO.'-f$Name)

            }

        }

    }
    return $true

}

function Test-VSO7NativeFeatureOwnsActiveTargetVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$FeatureId)
    # These Specials either record historical NonReversible debt or perform no persistent
    # VSO-owned mutation. Their history must not become perpetual ownership.
    if($FeatureId-in@('V7SP003','V7SP004','V7TB007','V7SP008','V7SP005','V7SP001','V7SP002')){
        return $false
    }
    # A failed partial session with no journal entries has no target or baseline to own.
    if([string]$Session.Status-ceq'Partial'-and@($Session.Entries).Count-eq0){
        return $false
    }
    return $true

}

function Get-VSO7NativeEntryTargetClaimsVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    switch([string]$Entry.Type){

        'RegistryValue' {
            return @(('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$Entry.Path)),([string]$Entry.Name).ToLowerInvariant()))
        }
        'RegistryKey' {
            return @(('REGKEY|{0}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$Entry.Path))))
        }
        'PowerSetting' {

            $base=('POWER|{0}|{1}'-f([string]$Entry.SubGroupAlias).ToLowerInvariant(),([string]$Entry.SettingAlias).ToLowerInvariant())
            $claims=@();
            if([bool]$Entry.OwnsAC){
                $claims+=($base+'|AC')
            };
            if([bool]$Entry.OwnsDC){
                $claims+=($base+'|DC')
            };
            return @($claims)

        }
        'OptionalFeature' {
            return @(('OPTIONAL|'+([string]$Entry.Name).ToLowerInvariant()))
        }
        'ScheduledTaskState' {
            return @(('TASK|'+([string]$Entry.TaskPath).ToLowerInvariant()+'|'+([string]$Entry.TaskName).ToLowerInvariant()))
        }
        'NetOffloadGlobal' {
            return @(('NETGLOBAL|'+([string]$Entry.Property).ToLowerInvariant()))
        }
        'NetTcpSetting' {
            return @(('TCP|'+([string]$Entry.Property).ToLowerInvariant()+'|*'))
        }
        'NetTcpCimSetting' {
            return @('TCPCIM|timestamps|*')
        }
        'FsutilNtfsTrim' {
            return @('FSUTIL|ntfs|disabledeletenotify')
        }
        'NetAdapterRss' {
            return @(('RSS|'+([string]$Entry.InterfaceGuid).ToLowerInvariant()))
        }
        'NetAdapterAdvancedProperty' {
            return @(('NETADV|'+([string]$Entry.RegistryKeyword).ToLowerInvariant()+'|'+([string]$Entry.InterfaceGuid).ToLowerInvariant()))
        }
        'NetAdapterPower' {
            return @(('NICPOWER|'+([string]$Entry.Property).ToLowerInvariant()+'|'+([string]$Entry.InterfaceGuid).ToLowerInvariant()))
        }
        'NonReversible' {
            return @()
        }
        default {
            return @()
        }

    }

}

function Get-VSO7NativeFeatureStaticTargetClaimsVSO {

    param([Parameter(Mandatory=$true)][string]$FeatureId,[Parameter(Mandatory=$true)][array]$Definitions)
    $def=@($Definitions|Where-Object{
        [string]$_.FeatureId-ceq$FeatureId
    }|Select-Object -First 1)
    if($def.Count-ne1){
        throw ('No existe definicion nativa para claims de ownership: {0}.'-f$FeatureId)
    }
    $claims=@()
    switch([string]$def[0].Mode){

        'Registry' {

            foreach($op in @($def[0].Apply)){

                if([string]$op.Action-in@('SetValue','DeleteValue')){
                    $claims+=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$op.Path)),([string]$op.Name).ToLowerInvariant())
                }
                elseif([string]$op.Action-ieq'DeleteKey'){
                    $claims+=('REGKEY|{0}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$op.Path)))
                }

            }

        }
        'PowerSetting' {

            foreach($op in @($def[0].Apply)){

                if([string]$op.Action-ine'SetPowerSetting'){
                    continue
                };
                $base=('POWER|{0}|{1}'-f([string]$op.SubGroupAlias).ToLowerInvariant(),([string]$op.SettingAlias).ToLowerInvariant())
                if(($op.PSObject.Properties.Name-contains'AC')-and[string]$op.AC-ine'Preserve'){
                    $claims+=($base+'|AC')
                }
                if(($op.PSObject.Properties.Name-contains'DC')-and[string]$op.DC-ine'Preserve'){
                    $claims+=($base+'|DC')
                }

            }

        }
        'ScheduledTaskState' {
            foreach($op in @($def[0].Apply)){
                $claims+=('TASK|'+([string]$op.TaskPath).ToLowerInvariant()+'|'+([string]$op.TaskName).ToLowerInvariant())
            }
        }
        'NetOffloadGlobal' {
            foreach($op in @($def[0].Apply)){
                $claims+=('NETGLOBAL|'+([string]$op.Property).ToLowerInvariant())
            }
        }
        'NetTcpSetting' {
            foreach($op in @($def[0].Apply)){
                $claims+=('TCP|'+([string]$op.Property).ToLowerInvariant()+'|*')
            }
        }
        'NetTcpCimSetting' {
            $claims+='TCPCIM|timestamps|*'
        }
        'FsutilTrim' {
            $claims+='FSUTIL|ntfs|disabledeletenotify'
        }
        'NetAdapterRss' {
            $claims+='RSS|*'
        }
        'NetAdapterAdvanced' {

            foreach($op in @($def[0].Apply)){

                foreach($property in @($op.Properties)){

                    $keyword=[string]$property.RegistryKeyword
                    if([string]::IsNullOrWhiteSpace($keyword)){
                        throw ('NetAdapterAdvanced {0} contiene una propiedad sin RegistryKeyword.'-f$FeatureId)
                    }
                    $claims+=('NETADV|'+$keyword.ToLowerInvariant()+'|*')

                }

            }

        }
        'NetAdapterPower' {
            foreach($op in @($def[0].Apply)){
                $claims+=('NICPOWER|'+([string]$op.Property).ToLowerInvariant()+'|*')
            }
        }
        'Special' {

            switch($FeatureId){

                'V7GP001' {
                    $claims+=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$script:VSO7GraphicsUserPreferencePath)),'directxuserglobalsettings')
                }
                'V7GP002' {
                    $claims+=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$script:VSO7GraphicsUserPreferencePath)),'directxuserglobalsettings')
                }
                'V7GP003' {
                    $claims+='REG|HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\GraphicsDrivers|hwschmode'
                }
                'V7GP004' {
                    $claims+='REG|HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\GraphicsDrivers|hwschmode'
                }
                'V7OF001' {
                    $claims+='OPTIONAL|containers-disposableclientvm'
                }
                'V7OF002' {
                    $claims+=@('OPTIONAL|virtualmachineplatform','OPTIONAL|microsoft-windows-subsystem-linux')
                }

            }

        }

    }
    return @($claims|Where-Object{
        -not[string]::IsNullOrWhiteSpace([string]$_)
    }|Select-Object -Unique)

}

function Test-VSO7NativeTargetClaimOverlapVSO {

    param([Parameter(Mandatory=$true)][string]$A,[Parameter(Mandatory=$true)][string]$B)
    if($A-ieq$B){
        return $true
    }
    if($A.EndsWith('|*')-and$B.StartsWith($A.Substring(0,$A.Length-1),[StringComparison]::OrdinalIgnoreCase)){
        return $true
    }
    if($B.EndsWith('|*')-and$A.StartsWith($B.Substring(0,$B.Length-1),[StringComparison]::OrdinalIgnoreCase)){
        return $true
    }
    # Eliminar una RegistryKey posee toda la subrama. Por ello solapa tanto con
    # otra REGKEY descendiente/ascendiente como con cualquier REG value de esa clave
    # o de una subclave. No dependemos de FeatureId/metadata para esta relación.
    if($A.StartsWith('REGKEY|',[StringComparison]::OrdinalIgnoreCase)){

        $keyA=$A.Substring(7).TrimEnd('\')
        if($B.StartsWith('REGKEY|',[StringComparison]::OrdinalIgnoreCase)){

            $keyB=$B.Substring(7).TrimEnd('\')
            if($keyA-ieq$keyB-or$keyA.StartsWith(($keyB+'\'),[StringComparison]::OrdinalIgnoreCase)-or$keyB.StartsWith(($keyA+'\'),[StringComparison]::OrdinalIgnoreCase)){
                return $true
            }

        }elseif($B.StartsWith('REG|',[StringComparison]::OrdinalIgnoreCase)){

            $prefix='REG|'+$keyA
            if($B.StartsWith(($prefix+'|'),[StringComparison]::OrdinalIgnoreCase)-or$B.StartsWith(($prefix+'\'),[StringComparison]::OrdinalIgnoreCase)){
                return $true
            }

        }

    }
    if($B.StartsWith('REGKEY|',[StringComparison]::OrdinalIgnoreCase)-and$A.StartsWith('REG|',[StringComparison]::OrdinalIgnoreCase)){

        $keyB=$B.Substring(7).TrimEnd('\');
        $prefix='REG|'+$keyB
        if($A.StartsWith(($prefix+'|'),[StringComparison]::OrdinalIgnoreCase)-or$A.StartsWith(($prefix+'\'),[StringComparison]::OrdinalIgnoreCase)){
            return $true
        }

    }
    return $false

}

function Assert-VSO7NativeOwnershipAvailableVSO {

    param([Parameter(Mandatory=$true)][array]$Requested,[Parameter(Mandatory=$true)][array]$Catalog,[AllowNull()][array]$Definitions=$null)
    $requestedIds=@($Requested|ForEach-Object{
        [string]$_
    }|Where-Object{
        -not[string]::IsNullOrWhiteSpace($_)
    }|Select-Object -Unique)
    if($requestedIds.Count-eq0){
        return $true
    }
    if($null-eq$Definitions){
        $Definitions=@((Get-VSO7NativeDataVSO).Features)
    }
    $requestedClaims=@();
    foreach($requestedId in $requestedIds){
        if($requestedId-ieq'V7GP-PERAPP'){
            continue
        };
        if(@($Definitions|Where-Object{
            [string]$_.FeatureId-ceq[string]$requestedId
        }).Count-eq1){
            $requestedClaims+=@(Get-VSO7NativeFeatureStaticTargetClaimsVSO -FeatureId $requestedId -Definitions $Definitions)
        }
    }
    $knownPublic=@($Catalog|ForEach-Object{
        [string]$_.FeatureId
    })
    $knownAll=@($knownPublic)+@(Get-VSO7KnownInternalNativeOwnershipIdsVSO)
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        [string]$_.Status-cne'Restored'
    })){

        $activeClaims=@();
        foreach($entry in @($session.Entries)){
            $activeClaims+=@(Get-VSO7NativeEntryTargetClaimsVSO -Entry $entry)
        }
        foreach($requestedClaim in @($requestedClaims)){

            foreach($activeClaim in @($activeClaims)){
                if(Test-VSO7NativeTargetClaimOverlapVSO -A ([string]$requestedClaim) -B ([string]$activeClaim)){
                    throw ('Recovery nativo activo ya posee el target {0}; no se crea una segunda capa nativa sobre el mismo target.'-f$activeClaim)
                }
            }

        }
        foreach($ownedId in @($session.Features|ForEach-Object{
            [string]$_
        })){

            if(-not(Test-VSO7NativeFeatureOwnsActiveTargetVSO -Session $session -FeatureId $ownedId)){
                continue
            }
            if($knownAll-cnotcontains$ownedId){
                throw ('Recovery nativo activo contiene ownership desconocido para esta build: {0}.'-f$ownedId)
            }
            if($ownedId-ieq'V7GP-PERAPP'){
                continue
            }
            $owned=@($Catalog|Where-Object{
                [string]$_.FeatureId-ceq$ownedId
            }|Select-Object -First 1)
            if($owned.Count-ne1){
                throw ('No se puede resolver metadata del owner nativo activo: {0}.'-f$ownedId)
            }
            foreach($requestedId in $requestedIds){

                if($requestedId-ieq'V7GP-PERAPP'){
                    continue
                }
                $candidate=@($Catalog|Where-Object{
                    [string]$_.FeatureId-ceq$requestedId
                }|Select-Object -First 1)
                if($candidate.Count-ne1){
                    throw ('No se puede resolver metadata de la feature solicitada: {0}.'-f$requestedId)
                }
                if($requestedId-ieq$ownedId){
                    throw ('La feature {0} ya tiene ownership nativo activo en otra sesion.'-f$requestedId)
                }
                if(@($candidate[0].ConflictsWith|ForEach-Object{
                    [string]$_
                })-icontains$ownedId-or@($owned[0].ConflictsWith|ForEach-Object{
                    [string]$_
                })-icontains$requestedId){
                    throw ('La feature {0} entra en conflicto con ownership nativo activo de {1}.'-f$requestedId,$ownedId)
                }
                $requestedGroup=[string]$candidate[0].MutuallyExclusiveGroup;
                $ownedGroup=[string]$owned[0].MutuallyExclusiveGroup
                if(-not[string]::IsNullOrWhiteSpace($requestedGroup)-and$requestedGroup-ieq$ownedGroup){
                    throw ('La feature {0} comparte MutuallyExclusiveGroup {1} con ownership nativo activo de {2}.'-f$requestedId,$requestedGroup,$ownedId)
                }

            }

        }

    }
    return $true

}

function Assert-VSO7PerAppGraphicsOwnershipAvailableVSO {

    param([Parameter(Mandatory=$true)][string]$Executable)
    $target=[IO.Path]::GetFullPath($Executable)
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        [string]$_.Status-cne'Restored'-and(@($_.Features|ForEach-Object{
            [string]$_
        })-icontains'V7GP-PERAPP')
    })){

        $same=@($session.Entries|Where-Object{
            [string]$_.Type-ieq'RegistryValue'-and[string]$_.Primitive-ieq'GraphicsCompositeToken'-and[string]$_.Path-ieq[string]$script:VSO7GraphicsUserPreferencePath-and-not[string]::IsNullOrWhiteSpace([string]$_.Name)-and[IO.Path]::GetFullPath([string]$_.Name)-ieq$target
        })
        if($same.Count-gt0){
            throw ('Ya existe ownership Graphics per-app activo para este ejecutable: {0}.'-f$target)
        }

    }
    return $true

}

function Invoke-VSO7RecommendedPreflightVSO {

    param([Parameter(Mandatory=$true)][string[]]$FeatureIds)
    $catalog=@(Get-VSO7FeatureCatalogVSO)
    [void](Assert-VSO7NativeFeatureSelectionVSO -Requested $FeatureIds -Catalog $catalog)
    # A recommended run does not layer ownership over an unresolved/active native run
    # touching the same FeatureId. Restore/review that run first so rollback remains obvious.
    $overlap=@()
    $knownFeatureIds=@($catalog|ForEach-Object{
        [string]$_.FeatureId
    })
    $knownOwnershipIds=@($knownFeatureIds)+@(Get-VSO7KnownInternalNativeOwnershipIdsVSO)
    foreach($existing in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        [string]$_.Status-notin@('Restored')
    })){

        $ownedFeatureIds=@($existing.Features|ForEach-Object{
            [string]$_
        }|Where-Object{
            Test-VSO7NativeFeatureOwnsActiveTargetVSO -Session $existing -FeatureId ([string]$_)
        })
        $unknownOwnership=@($ownedFeatureIds|Where-Object{
            $knownOwnershipIds-cnotcontains[string]$_
        })
        if($unknownOwnership.Count-gt0){
            throw ('Recovery nativo activo contiene ownership que esta R44 no puede mapear de forma fiable: '+($unknownOwnership-join', ')+'. Restaura o revisa esa sesion antes de una nueva optimizacion recomendada.')
        }
        $shared=@($FeatureIds|Where-Object{
            $ownedFeatureIds-contains[string]$_
        })
        if($shared.Count-gt0){
            $overlap+=[pscustomobject]@{
                CreatedAt=[string]$existing.CreatedAt;
                Status=[string]$existing.Status;
                Features=$shared
            }
        }

    }
    if($overlap.Count-gt0){
        throw ('Existe Recovery nativo activo sobre feature(s) seleccionadas: '+(@($overlap|ForEach-Object{
            @($_.Features)
        })-join', ')+'. Restaura o revisa ese ownership antes de una nueva optimizacion recomendada.')
    }
    $baselines=New-Object System.Collections.Generic.List[object]
    foreach($id in @($FeatureIds|Sort-Object)){

        $batch=Test-VSO7RecommendedBatchModeVSO -FeatureId $id
        if(-not[bool]$batch.Allowed){
            throw ('Preflight global bloquea '+$id+': '+[string]$batch.Reason)
        }
        [void]$baselines.Add((Get-VSO7NativeFeaturePreflightSnapshotVSO -FeatureId $id))

    }
    return [pscustomobject]@{
        Pass=$true;
        CapturedAt=(Get-Date).ToString('o');
        FeatureIds=@($FeatureIds|Sort-Object);
        Baselines=$baselines.ToArray();
        FailurePolicy='StopOnFirstFailure; already-applied owned changes remain in the same recoverable batch.'
    }

}

function Show-VSO7RecommendedPlanVSO {

    param([Parameter(Mandatory=$true)]$Plan)
    $isEn=($script:Language-eq'en')
    $c=$Plan.Counts
    Write-CenteredLineVSO -Text $(if($isEn){
        'RECOMMENDED OPTIMIZATION FOR THIS PC'
    }else{
        'OPTIMIZACION RECOMENDADA PARA ESTE EQUIPO'
    }) -Color $script:ThemeCopper
    Write-CenteredLineVSO -Text (($(Get-VSO7ConsoleTextVSO -Es '{0} seleccionados ({1} recomendados + {2} opcionales) · {3} ya optimos · {4} manuales · {5} avanzados · {6} experimentales · {7} diagnosticos' -En '{0} selected ({1} Recommended + {2} Optional) · {3} already optimal · {4} manual · {5} advanced · {6} experimental · {7} diagnostics')-f$c.Selected,$c.SelectedRecommended,$c.SelectedOptional,$c.AlreadyOptimal,$c.ManualAvailable,$c.AdvancedNotSelected,$c.ExperimentalNotSelected,$c.Diagnostics)) -Color $script:ThemeText
    if([string]$Plan.PlanMode-eq'RecommendedPlusOptional'-and[int]$c.SelectedOptional-eq0){

        Write-CenteredLineVSO -Text $(if($isEn){
            'No additional Optional + Eligible settings are applicable for this PC/objective.'
        }else{
            'No hay ajustes Optional + Eligible adicionales aplicables para este equipo/objetivo.'
        }) -Color DarkGray

    }
    if([string]$Plan.ObjectiveMode-eq'ManualOnly'){

        Write-CenteredLineVSO -Text $(if($isEn){
            'This objective is manual-only in R44 because no current Privacy mutation meets automatic E1/E2 + applicability policy.'
        }else{
            'Este objetivo es solo manual en R44: ninguna mutacion Privacy actual cumple la policy automatica E1/E2 + Applicability.'
        }) -Color Yellow

    }
    $groups=@($Plan.Selected|Group-Object {
        $_.Feature.CategoryEn
    }|Sort-Object Name)
    foreach($g in $groups){

        Write-VSOHost '';
        Write-VSOHost ('['+$(if($isEn){[string]$g.Name}else{[string]$g.Group[0].Feature.CategoryEs})+']') -ForegroundColor Cyan
        foreach($x in @($g.Group)){

            $f=$x.Feature;
            $name=if($isEn){
                [string]$f.NameEn
            }else{
                [string]$f.NameEs
            }
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es '  + {0}  {1}  [Riesgo {2} / {3} / {4}]' -En '  + {0}  {1}  [Risk {2} / {3} / {4}]')-f$f.FeatureId,$name,$f.Risk,$f.Evidence,$f.Maturity) -ForegroundColor Green
            Write-VSOHost ("      "+[string]$x.Reason) -ForegroundColor DarkGray

        }

    }
    if(@($Plan.AlreadyOptimal).Count-gt0){

        Write-VSOHost '';
        Write-VSOHost ($(if($isEn){
            'Already optimal:'
        }else{
            'Ya optimas:'
        })) -ForegroundColor Green
        foreach($x in @($Plan.AlreadyOptimal)){
            $f=$x.Feature;
            $name=if($isEn){
                [string]$f.NameEn
            }else{
                [string]$f.NameEs
            };
            Write-VSOHost ('  = '+$f.FeatureId+'  '+$name) -ForegroundColor DarkGreen
        }

    }

}

function Restore-VSO7LatestRecommendedOptimizationVSO {

    $sessions=@(Get-VSO7NativeBackupSessionsVSO -SkipInvalid|Where-Object{
        ($_.PSObject.Properties.Name-contains'BatchKind')-and[string]$_.BatchKind-eq'RecommendedOptimization'-and[string]$_.Status-ne'Restored'
    })
    if($sessions.Count-eq0){
        Write-VSOHost 'No hay una ejecucion Recommended Optimization pendiente de restaurar.' -ForegroundColor Yellow;
        return $false
    }
    $selected=Select-VSO7NativeBackupSessionVSO -Sessions $sessions -TitleEs 'EJECUCIONES RECOMENDADAS RECUPERABLES' -TitleEn 'RECOVERABLE RECOMMENDED RUNS'
    if($null-eq$selected){
        return $false
    }
    if(-not(Confirm-Word -Word 'RESTAURAR RECOMENDADA' -Message ('Escribe exactamente RESTAURAR RECOMENDADA para restaurar la sesion '+[string]$selected.CreatedAt))){
        return $false
    }
    return [bool](Restore-VSO7NativeBackupSessionVSO -Session $selected)

}

function Get-VSO7RecommendedRunSummaryVSO {

    param([Parameter(Mandatory=$true)][string]$BatchId,[Parameter(Mandatory=$true)]$Plan)
    $session=@(Get-VSO7NativeBackupSessionsVSO|Where-Object{
        ($_.PSObject.Properties.Name-contains'BatchId')-and[string]$_.BatchId-ceq$BatchId
    }|Select-Object -First 1)
    $results=if($session.Count-eq1-and$session[0].PSObject.Properties.Name-contains'FeatureResults'){
        @($session[0].FeatureResults)
    }else{
        @()
    }
    $applied=@($results|Where-Object{
        [string]$_.Status-eq'Applied'
    }).Count
    $failed=@($results|Where-Object{
        [string]$_.Status-eq'Failed'
    }).Count
    $partial=@($results|Where-Object{
        [string]$_.Status-eq'Partial'
    }).Count
    $pending=@($results|Where-Object{
        [string]$_.Status-eq'Pending'
    }).Count
    $restart=@($Plan.Selected|ForEach-Object{
        [string]$_.Feature.RestartSemantics
    }|Where-Object{
        -not[string]::IsNullOrWhiteSpace($_)-and$_-ine'None'
    }|Sort-Object -Unique)
    return [pscustomobject]@{
        Selected=@($Plan.Selected).Count;
        Applied=$applied;
        AlreadyOptimal=@($Plan.AlreadyOptimal).Count;
        Partial=$partial;
        Pending=$pending;
        Failed=$failed;
        BatchStatus=if($session.Count-eq1){
            [string]$session[0].Status
        }else{
            'Unknown'
        };
        RestartRequirements=$restart
    }

}

function Show-VSO7RecommendedRunSummaryVSO {

    param([Parameter(Mandatory=$true)]$Summary)
    Write-VSOHost '';
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Seleccionados {0} | Aplicados {1} | Ya optimos {2} | Parciales {3} | Pendientes {4} | Fallidos {5}' -En 'Selected {0} | Applied {1} | AlreadyOptimal {2} | Partial {3} | Pending {4} | Failed {5}')-f$Summary.Selected,$Summary.Applied,$Summary.AlreadyOptimal,$Summary.Partial,$Summary.Pending,$Summary.Failed) -ForegroundColor Cyan
    if(@($Summary.RestartRequirements).Count-gt0){
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Reinicios necesarios: ' -En 'Restart requirements: ')+(@($Summary.RestartRequirements)-join', ')) -ForegroundColor Yellow
    }
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Estado del lote: ' -En 'Batch status: ')+[string]$Summary.BatchStatus) -ForegroundColor DarkGray

}

function Invoke-VSO7RecommendedOptimizationVSO {

    param(
        [ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Objective='Balanced',
        [switch]$IncludeOptional,
        [switch]$DryRun,
        [switch]$SkipConfirmation,
        [switch]$SuppressPresentation
    )
    $plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective $Objective -IncludeOptional:$IncludeOptional
    if(-not$SuppressPresentation){Show-VSO7RecommendedPlanVSO -Plan $plan}
    $ids=@($plan.Selected|ForEach-Object{
        [string]$_.Feature.FeatureId
    })
    if($DryRun){
        return $plan
    }
    if($ids.Count-eq0){
        Write-VSOHost 'No hay mutaciones recomendadas pendientes para esta politica.' -ForegroundColor Green;
        return $plan
    }
    if(-not$SkipConfirmation){

        $answer=Read-CenteredPromptVSO -Text '¿Aplicar exactamente esta seleccion? [S/N]'
        if($answer-notmatch'^[sSyY]$'){
            Write-VSOHost 'Cancelado.' -ForegroundColor Gray;
            return $plan
        }

    }
    $canonical=Get-VSO7FeatureSelectionPlanR75VSO -Operation Recommended -FeatureIds $ids -Objective $Objective
    $execution=Invoke-VSO7FeaturePlanExecutionR75VSO -Plan $canonical -Mode Apply -ExecutionKind Recommended
    if([string]$execution.Status-ceq'Cancelled'){
        throw 'No se pudo verificar/crear el punto de restauracion requerido.'
    }
    if([string]$execution.Status-ceq'Failed'-and[string]::IsNullOrWhiteSpace([string]$execution.BatchId)){
        throw $(if([string]::IsNullOrWhiteSpace([string]$execution.Error)){'El preflight global no paso.'}else{[string]$execution.Error})
    }
    $runId=[string]$execution.BatchId
    $plan|Add-Member -NotePropertyName RunId -NotePropertyValue $runId -Force
    $plan|Add-Member -NotePropertyName ApplyStatus -NotePropertyValue $(if([string]$execution.Status-ceq'Succeeded'){
        'Applied'
    }else{
        'PartialOrFailed'
    }) -Force
    $plan|Add-Member -NotePropertyName FailurePolicy -NotePropertyValue $(if($null-ne$execution.Preflight){[string]$execution.Preflight.FailurePolicy}else{''}) -Force
    if(-not[string]::IsNullOrWhiteSpace($runId)){
        $summary=Get-VSO7RecommendedRunSummaryVSO -BatchId $runId -Plan $plan
        $plan|Add-Member -NotePropertyName RunSummary -NotePropertyValue $summary -Force
        if(-not$SuppressPresentation){Show-VSO7RecommendedRunSummaryVSO -Summary $summary}
    }
    return $plan

}

function Select-VSO7RecommendedObjectiveVSO {

    param([ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Current='Balanced',[switch]$NoPrivacyReview)
    while($true){

        Write-Title
        Write-CenteredLineVSO -Text 'OBJETIVO · OPTIMIZACION RECOMENDADA' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Actual: ' -En 'Current: ')+$Current) -Color $script:ThemeText
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text='[1] Equilibrada';Color='Green';Description='Solo normalizaciones generales, seguras y poco controvertidas marcadas explicitamente Balanced.'
        },
            [pscustomobject]@{
            Text='[2] Rendimiento';Color='Cyan';Description='Solo features catalogadas explicitamente Performance; no hereda Responsiveness ni Gaming.'
        },
            [pscustomobject]@{
            Text='[3] Gaming';Color='Cyan';Description='Solo features catalogadas explicitamente Gaming; no aplica automaticamente todo Performance.'
        },
            [pscustomobject]@{
            Text='[4] Responsiveness';Color='Cyan';Description='Solo normalizaciones explicitamente Responsiveness; sin preferencias visuales ni timer folklore.'
        },
            [pscustomobject]@{
            Text='[5] Eficiencia energetica';Color='Cyan';Description='Politicas explicitamente PowerEfficiency y hardware-aware, con AC/DC preservado cuando aplica.'
        },
            [pscustomobject]@{
            Text='[6] Privacidad (revision manual)';Color='Gray';Description=$(if($NoPrivacyReview){Get-VSO7ConsoleTextVSO 'Privacidad sigue siendo manual. Mantiene el objetivo actual y la seleccion; no abre otro selector.' 'Privacy remains manual. Keeps the current objective and selection; does not open another selector.'}else{'No tiene AutoSelection automatico en R44: abre una revision manual basada exclusivamente en metadata Privacy del catalogo.'})
        },
            [pscustomobject]@{
            Text='[0] Mantener / volver';Color='Gray';SeparatorBefore=$true
        }
        )
        switch(Read-CenteredPromptVSO -Text $(Get-VSO7ConsoleTextVSO -Es 'Objetivo' -En 'Objective')){

            '1'{
                return 'Balanced'
            }
            '2'{
                return 'Performance'
            }
            '3'{
                return 'Gaming'
            }
            '4'{
                return 'Responsiveness'
            }
            '5'{
                return 'PowerEfficiency'
            }
            '6'{
                Write-VSOHost 'Privacy permanece manual-only: revisa conscientemente las features Privacy declaradas por el catalogo.' -ForegroundColor Yellow;
                Pause-Vico;
                if(-not$NoPrivacyReview){Show-VSO7PrivacyReviewVSO}
                return $Current
            }
            '0'{
                return $Current
            }

        }

    }

}

function Show-VSO7RecommendedReviewVSO {

    param(
        [ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Objective='Balanced',
        [switch]$IncludeOptional
    )
    $plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective $Objective -IncludeOptional:$IncludeOptional
    Show-VSO7RecommendedPlanVSO -Plan $plan
    Write-VSOHost ''
    Write-VSOHost 'Revision de exclusiones / motivos:' -ForegroundColor Yellow
    foreach($g in @($plan.Skipped|Group-Object Status|Sort-Object Name)){

        Write-VSOHost ('['+[string]$g.Name+']') -ForegroundColor DarkYellow
        foreach($x in @($g.Group|Sort-Object {
            $_.Feature.FeatureId
        })){

            Write-VSOHost ('  - '+[string]$x.Feature.FeatureId+' :: '+[string]$x.Reason) -ForegroundColor DarkGray

        }

    }
    return $plan

}

function Show-VSO7RecommendedOptimizationVSO {

    $objective='Balanced'
    while($true){

        Write-Title
        Write-CenteredLineVSO -Text 'OPTIMIZACION RECOMENDADA · ANALYZE → RECOMMEND → PREVIEW → APPLY → RESTORE' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Objetivo actual: ' -En 'Current objective: ')+$objective) -Color $script:ThemeText
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text='[1] Elegir objetivo';Color='Cyan';Description='Equilibrada, Rendimiento, Gaming, Responsiveness o Eficiencia; Privacidad se revisa manualmente.'
        },
            [pscustomobject]@{
            Text='[2] Preview / Dry Run';Color='Cyan';Description='Calcula la seleccion del objetivo actual sin modificar Windows.'
        },
            [pscustomobject]@{
            Text='[3] Aplicar recomendadas';Color='Green';Description='Recalcula y muestra el plan inmediatamente antes del preflight y la mutacion.'
        },
            [pscustomobject]@{
            Text='[4] Preview + Optional Eligible';Color='Cyan';Description='Solo Optional con AutoSelection=Eligible y el resto de policy en PASS.'
        },
            [pscustomobject]@{
            Text='[5] Aplicar + Optional Eligible';Color='Yellow';Description='Manual/Never siguen excluidas aunque IncludeOptional este activo.'
        },
            [pscustomobject]@{
            Text='[6] Revisar plan base';Color='Gray';Description='Revisa exactamente Recommended para el objetivo actual.'
        },
            [pscustomobject]@{
            Text='[9] Revisar plan + Optional Eligible';Color='Gray';Description='Revisa exactamente RecommendedPlusOptional para el objetivo actual.'
        },
            [pscustomobject]@{
            Text='[7] Restaurar ultima optimizacion recomendada';Color='Green';Description='Recovery normal, ownership/drift-aware.'
        },
            [pscustomobject]@{
            Text='[8] Modo experto / selector manual';Color='Gray';Description='Control individual usando el mismo motor de features.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion'
        switch($c){

            '1'{
                $objective=Select-VSO7RecommendedObjectiveVSO -Current $objective
            }
            '2'{
                [void](Invoke-VSO7RecommendedOptimizationVSO -Objective $objective -DryRun);
                Pause-Vico
            }
            '3'{
                [void](Invoke-VSO7RecommendedOptimizationVSO -Objective $objective);
                Pause-Vico
            }
            '4'{
                [void](Invoke-VSO7RecommendedOptimizationVSO -Objective $objective -IncludeOptional -DryRun);
                Pause-Vico
            }
            '5'{
                [void](Invoke-VSO7RecommendedOptimizationVSO -Objective $objective -IncludeOptional);
                Pause-Vico
            }
            '6'{
                [void](Show-VSO7RecommendedReviewVSO -Objective $objective);
                Pause-Vico
            }
            '9'{
                [void](Show-VSO7RecommendedReviewVSO -Objective $objective -IncludeOptional);
                Pause-Vico
            }
            '7'{
                [void](Restore-VSO7LatestRecommendedOptimizationVSO);
                Pause-Vico
            }
            '8'{
                Show-VSO7SafeSelector
            }
            '0'{
                return
            }

        }

    }

}

function Get-SmartRecommendations {

    $plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective Balanced
    $result=@()
    foreach($x in @($plan.Selected)){
        $f=$x.Feature;
        $result+=[pscustomobject]@{
            Level='RECOMENDADO';
            Area=[string]$f.CategoryEs;
            Message=$(if($script:Language-eq'en'){
                [string]$f.NameEn
            }else{
                [string]$f.NameEs
            })+' — '+[string]$x.Reason;
            AutoFix=$true;
            FeatureId=[string]$f.FeatureId
        }
    }
    foreach($x in @($plan.AlreadyOptimal)){
        $f=$x.Feature;
        $result+=[pscustomobject]@{
            Level='OK';
            Area=[string]$f.CategoryEs;
            Message=$(if($script:Language-eq'en'){
                [string]$f.NameEn
            }else{
                [string]$f.NameEs
            })+' — AlreadyOptimal';
            AutoFix=$false;
            FeatureId=[string]$f.FeatureId
        }
    }
    if($result.Count-eq0){
        $result+=[pscustomobject]@{
            Level='OK';
            Area='VSO7';
            Message='No hay cambios Recommended pendientes para la politica equilibrada.';
            AutoFix=$false;
            FeatureId=$null
        }
    }
    return @($result)

}

function Show-RecommendationTable {

    param([Parameter(Mandatory=$true)]$Recommendations)

    foreach ($r in $Recommendations) {

        $prefix = switch ($r.Level) {

            'OK'          {
                '[OK]'
            }
            'RECOMENDADO' {
                '[RECOMENDADO]'
            }
            'REVISAR'     {
                '[REVISAR]'
            }
            'IMPORTANTE'  {
                '[IMPORTANTE]'
            }
            default       {
                '[INFO]'
            }

        }

        $color = switch ($r.Level) {

            'OK'          {
                'Green'
            }
            'RECOMENDADO' {
                'Cyan'
            }
            'REVISAR'     {
                'Yellow'
            }
            'IMPORTANTE'  {
                'Red'
            }
            default       {
                'Gray'
            }

        }

        Write-VSOHost ("{0} {1}: {2}" -f $prefix, $r.Area, $r.Message) -ForegroundColor $color

    }

}

function Invoke-SmartDiagnostics {

    Write-Title
    Write-VSOHost 'DIAGNÓSTICO DE RENDIMIENTO' -ForegroundColor Cyan
    Write-VSOHost '--------------------------'
    Write-VSOHost ''
    Write-VSOHost 'No modifica nada. Analiza hardware, ajustes y procesos actuales.' -ForegroundColor Green

    Write-Section 'RAM'
    $ram = Get-RamDiagnostics
    if ($ram.ModuleCount -gt 0) {

        Write-CenteredTableVSO -Rows @($ram.Modules) -Properties @('DeviceLocator','CapacityGB','ConfiguredMTs','Manufacturer','PartNumber')

    } else {

        Write-VSOHost 'No disponible.' -ForegroundColor Yellow

    }

    Write-Section 'GPU'
    $gpus = Get-GpuDiagnostics
    if ($gpus.Count -gt 0) {

        Write-CenteredTableVSO -Rows @($gpus) -Properties @('Name','DriverVersion','DriverDate')

    } else {

        Write-VSOHost 'No disponible.' -ForegroundColor Yellow

    }

    Write-Section $(Get-VSO7ConsoleTextVSO -Es 'Discos' -En 'Drives')
    $disk = Get-DiskDiagnostics
    if ($disk.Physical.Count -gt 0) {

        Write-CenteredTableVSO -Rows @($disk.Physical) -Properties @('FriendlyName','MediaType','BusType','HealthStatus','SizeGB')

    }
    if ($null -ne $disk.SystemDrive) {

        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Sistema: {0} GB libres de {1} GB ({2}% libre)' -En 'System drive: {0} GB free of {1} GB ({2}% free)') -f $disk.SystemDrive.FreeGB, $disk.SystemDrive.SizeGB, $disk.SystemDrive.FreePct)

    }

    Write-Section 'CPU actual'
    Write-VSOHost 'Midiendo durante unos segundos...' -ForegroundColor Gray
    $live = Get-LiveCpuUsage -Samples 3 -DelaySeconds 1
    if ($live.Count -gt 0) {

        Write-CenteredTableVSO -Rows @($live|Select-Object -First 12 Process,Id,CPU_Pct,RAM_MB) -Properties @('Process','Id','CPU_Pct','RAM_MB')

    }

    Write-Section 'Recomendaciones'
    $recommendations = Get-SmartRecommendations
    Show-RecommendationTable -Recommendations $recommendations

    Write-VSOHost ''
    Write-VSOHost 'Nada de lo anterior ha modificado Windows.' -ForegroundColor Green
    Pause-Vico

}

function Invoke-ApplySmartRecommendations {

    # Wrapper de compatibilidad para referencias antiguas de menú/perfil.
    # Delega en el motor actual basado en catálogo y aplicabilidad.
    [void](Show-VSO7RecommendedOptimizationVSO)

}

function Open-DefaultGraphicsSettings {

    Write-VSOHost 'Por seguridad VSO7 no invoca ms-settings: desde el proceso elevado.' -ForegroundColor Yellow
    Write-VSOHost 'Abre manualmente: Configuracion > Sistema > Pantalla > Graficos.' -ForegroundColor Cyan

}

