                        }
                    }
                }catch{
                    Write-VSO7Log ('No se pudo procesar Game Mode desde Herramientas: '+[string]$_.Exception.Message) 'ERROR'
                    Write-CenteredLineVSO -Text ([string]$_.Exception.Message) -Color $script:ThemeDanger
                }
                Pause-Vico
            }
            '2'{
                Write-VSOHost '';
                Write-VSOHost 'Desactiva la grabacion/captura de juegos que Windows mantiene en segundo plano.' -ForegroundColor Yellow;
                $a=Read-VSOHost '¿Continuar? [S/N]';
                if($a-match'^[sSyY]$'){
                    if(Require-RestorePoint){
                        Load-State;
                        Disable-BackgroundGameCapture
                    }
                };
                Pause-Vico
            }
            '3'{
                if(Require-RestorePoint){
                    Load-State;
                    Disable-Transparency
                };
                Pause-Vico
            }
            '4'{
                Write-VSOHost '';
                Write-VSOHost 'Reduce animaciones visuales de Windows; no cambia rendimiento del hardware.' -ForegroundColor Yellow;
                $a=Read-VSOHost '¿Continuar? [S/N]';
                if($a-match'^[sSyY]$'){
                    if(Require-RestorePoint){
                        Load-State;
                        Disable-WindowAnimations
                    }
                };
                Pause-Vico
            }
            '5'{
                Write-VSOHost '';
                if((Read-VSOHost '¿Limpiar ahora los temporales de mas de 7 dias? [S/N]')-match'^[sSyY]$'){
                    Remove-OldTempFiles -OlderThanDays 7
                };
                Pause-Vico
            }
            '6'{
                Show-PowerPlanManager
            }'7'{
                Show-StartupAnalysis
            }'8'{
                Show-LiveProcesses
            }'9'{
                Show-QuickHealthChecks
            }'10'{
                Show-RamDetails
            }'11'{
                Show-GpuDetails
            }'12'{
                Open-DefaultGraphicsSettings;
                Pause-Vico
            }'13'{
                Show-StorageDeepAnalysis
            }'14'{
                Show-ExtremeOptimizer
            }'15'{
                Show-OverlayProcessManagerVSO
            }'16'{
                Show-CleanupManagerVSO
            }'0'{
                return
            }

        }

    }

}

function Get-PathSizeBytes {

    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path -PathType Container)) {
        return [int64]0
    }
    try {

        [int64]$sum = 0
        foreach ($file in @(Get-FilesNoReparseVSO -Root $Path)) {
            $sum += [int64]$file.Length
        }
        return $sum

    } catch {
        return [int64]0
    }

}

function Format-BytesVSO {

    param([int64]$Bytes)
    if ($Bytes -ge 1GB) {
        return ('{0:N2} GB' -f ($Bytes/1GB))
    }
    if ($Bytes -ge 1MB) {
        return ('{0:N1} MB' -f ($Bytes/1MB))
    }
    return ('{0:N0} KB' -f ($Bytes/1KB))

}

function Get-CleanupTweaksVSO {

    return @(Get-VSOExtremeTweaks | Where-Object {
        $_.Id -like 'cleanup.*'
    })

}

function Get-CleanupSizeEstimateVSO {

    param([Parameter(Mandatory=$true)][string]$Id)

    switch ($Id) {

        'cleanup.shaders' {

            [int64]$bytes = 0
            foreach ($path in @("$script:LocalAppData\NVIDIA\DXCache","$script:LocalAppData\NVIDIA\GLCache","$script:LocalAppData\D3DSCache")) {

                $bytes += Get-PathSizeBytes -Path $path

            }
            return $bytes

        }
        'cleanup.vscode' {

            [int64]$bytes = 0
            foreach ($root in @("$script:AppData\Code","$script:AppData\Code - Insiders")) {

                foreach ($name in @('CachedExtensionVSIXs','CachedData','Cache','GPUCache','Crashpad','Code Cache','DawnWebGPUCache')) {

                    $bytes += Get-PathSizeBytes -Path (Join-Path $root $name)

                }

            }
            return $bytes

        }
        'cleanup.spotify' {
            return (Get-PathSizeBytes -Path "$script:LocalAppData\Packages\SpotifyAB.SpotifyMusic_zpdnekdrzrea0\LocalCache")
        }
        'cleanup.lghub' {
            return (Get-PathSizeBytes -Path (Join-Path $script:ProgramData 'LGHUB\cache'))
        }
        'cleanup.fortnite' {
            return (Get-PathSizeBytes -Path "$script:LocalAppData\FortniteGame\Saved\PersistentDownloadDir")
        }
        'cleanup.bobby' {
            return (Get-PathSizeBytes -Path "$script:AppData\.minecraft\.bobby")
        }
        default {
            return [int64]0
        }

    }

}

function Stop-CleanupAppsIfAllowedVSO {

    param([array]$Tweaks,[bool]$AllowClose)
    if (-not $AllowClose) {
        return
    }
    $ids = @($Tweaks | Select-Object -ExpandProperty Id)
    $names = @()
    if ($ids -contains 'cleanup.spotify') {
        $names += 'Spotify'
    }
    if ($ids -contains 'cleanup.vscode') {
        $names += 'Code';
        $names += 'Code - Insiders'
    }
    if ($ids -contains 'cleanup.fortnite') {
        $names += 'FortniteClient-Win64-Shipping';
        $names += 'EpicGamesLauncher'
    }

    foreach ($name in @($names | Select-Object -Unique)) {

        $processMatches=@(Get-Process -Name $name -ErrorAction SilentlyContinue)
        try {

            foreach ($process in $processMatches) {

                $current=$null
                try {

                    $identity = Get-VSO7ProcessIdentity -Process $process
                    if ([string]::IsNullOrWhiteSpace([string]$identity.StartTimeUtc)) {

                        Write-VSO7Log ("No se cierra {0} para limpieza: no se pudo verificar suficientemente la identidad del proceso." -f $process.ProcessName) 'WARN'
                        continue

                    }
                    $current = Get-Process -Id $identity.Id -ErrorAction SilentlyContinue
                    if ($null -eq $current -or -not (Test-VSO7ProcessIdentityMatch -Expected $identity -Process $current)) {

                        Write-VSO7Log ("No se cierra {0} para limpieza: el proceso termino o su PID fue reutilizado." -f $process.ProcessName) 'WARN'
                        continue

                    }
                    Stop-Process -Id $identity.Id -Force -ErrorAction Stop
                    Write-VSO7Log ("Cerrado para limpieza: {0}" -f $process.ProcessName) 'CHANGE'

                } catch {

                    Write-VSO7Log ("No se pudo cerrar {0}: {1}" -f $process.ProcessName,$_.Exception.Message) 'WARN'

                } finally {
                    Close-VSO7ProcessObjectVSO -Process $current
                }

            }

        } finally {
            Close-VSO7ProcessCollectionVSO -Processes $processMatches
        }

    }

}

function Show-CleanupManagerVSO {

    $all=@(Get-CleanupTweaksVSO);
    $selected=@{}
    while($true){

        Write-Title;
        Write-CenteredLineVSO -Text 'LIMPIEZA GUIADA AUTOMATICA' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Selecciona exactamente que caches o temporales quieres limpiar. Entrar no borra nada.' -Color 'Green'
        Write-CenteredLineVSO -Text 'Minecraft protegido: no toca logs, crash-reports, saves, Xaero, JourneyMap ni resourcepacks.' -Color 'Green'
        Write-CenteredLineVSO -Text 'Las limpiezas eliminan cache o temporales y normalmente no tienen rollback.' -Color 'Yellow';
        Write-VSOHost ''
        $rows=@();
        for($i=0;$i-lt$all.Count;$i++){
            $tweak=$all[$i];
            $mark=if($selected.ContainsKey($tweak.Id)){
                'X'
            }else{
                ' '
            };
            $size=Get-CleanupSizeEstimateVSO -Id $tweak.Id;
            $sizeText=if($size-gt0){
                Format-BytesVSO -Bytes $size
            }else{
                '--'
            };
            $name=[string](Convert-VSOText -Value ([string]$tweak.Name));
            $desc=[string]$tweak.Desc;
            if([string]::IsNullOrWhiteSpace($desc)){
                $desc='Limpia cache o archivos temporales de esta categoria.'
            };
            $desc=[string](Convert-VSOText -Value $desc);
            $estimate=if($script:Language-eq'en'){
                "Current estimate: {0}."-f$sizeText
            }else{
                "Estimacion actual: {0}."-f$sizeText
            };
            $rows += [pscustomobject]@{
                Text=("[{0}] [{1}] {2}"-f($i+1),$mark,$name);
                Color='Gray';
                Description=("{0} {1}"-f$desc,$estimate)
            }
        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        $allNumber=$all.Count+1;
        $clearNumber=$all.Count+2;
        $cleanNumber=$all.Count+3
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar todas' -En '[{0}] Select all')-f$allNumber);Color='Gray';Description='Marca todas las categorias disponibles. Todavia no borra archivos.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Quitar toda la seleccion' -En '[{0}] Clear the selection')-f$clearNumber);Color='Gray';Description='Desmarca todo sin limpiar nada.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Limpiar la seleccion' -En '[{0}] Clean up selected items')-f$cleanNumber);Color='Yellow';Description='Muestra lo seleccionado y pide confirmacion antes de comenzar a borrar caches o temporales.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa sin ejecutar la limpieza pendiente.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Opcion / numero';
        if($choice-eq'0'){
            return
        };
        $number=0;
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }
        if($number-ge1-and$number-le$all.Count){
            $tweak=$all[$number-1];
            if($selected.ContainsKey($tweak.Id)){
                $selected.Remove($tweak.Id)
            }else{
                $selected[$tweak.Id]=$true
            };
            continue
        }
        if($number-eq$allNumber){
            $selected=@{};
            foreach($tweak in $all){
                $selected[$tweak.Id]=$true
            };
            continue
        }
        if($number-eq$clearNumber){
            $selected=@{};
            continue
        }
        if($number-eq$cleanNumber){

            $selection=@($all|Where-Object{
                $selected.ContainsKey($_.Id)
            });
            if($selection.Count-eq0){
                Write-CenteredLineVSO -Text 'No hay categorias de limpieza seleccionadas.' -Color $script:ThemeMuted;
                Pause-Vico;
                continue
            }
            Write-VSOHost '';
            Write-CenteredLineVSO -Text 'Se limpiara:' -Color $script:ThemeWarning;
            foreach($tweak in $selection){
                Write-VSOHost (" - {0}"-f$tweak.Name)
            }
            if((Read-CenteredPromptVSO -Text '¿Continuar? [S/N]')-notmatch'^[sSyY]$'){
                continue
            }
            $allowClose=((Read-CenteredPromptVSO -Text '¿Permitir cerrar Spotify/VS Code/Fortnite si hace falta? [S/N]')-match'^[sSyY]$');
            Stop-CleanupAppsIfAllowedVSO -Tweaks $selection -AllowClose $allowClose;
            $before=Get-VSO7LocalDiskFreeSnapshot
            foreach($tweak in $selection){
                try{
                    Invoke-VSOTweak -Tweak $tweak
                }catch{
                    Write-VSO7Log ("Limpieza detenida en {0}: {1}"-f$tweak.Name,$_.Exception.Message) 'ERROR';
                    break
                }
            }
            $after=Get-VSO7LocalDiskFreeSnapshot;
            $freed=Get-VSO7FreedBytesFromSnapshots -Before $before -After $after;
            if($freed-gt0){
                Add-VSO7CleanupHistory -BytesFreed $freed -Tweaks $selection;
                Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Espacio recuperado en esta ejecucion: {0}' -En 'Space recovered in this run: {0}')-f(Format-BytesVSO $freed)) -ForegroundColor Green
            };
            $selected=@{};
            Pause-Vico;
            continue

        }

    }

}

function Show-StorageDeepAnalysis {

    Write-Title
    Write-VSOHost 'ANALISIS PROFUNDO DE ALMACENAMIENTO (SOLO LECTURA)' -ForegroundColor Cyan
    Write-VSOHost '---------------------------------------------------'
    Write-VSOHost ''

    $targets = @(
        $script:LocalAppData,
        $script:AppData,
        $script:ProgramData,
        $script:ProgramFiles,
        $script:ProgramFilesX86
    ) | Where-Object {
        $_ -and (Test-Path -LiteralPath $_)
    }

    foreach ($p in $targets) {

        Write-VSOHost ("`n=== {0} ===" -f $p) -ForegroundColor Cyan
        $rows = foreach ($d in (Get-ChildItem -LiteralPath $p -Directory -Force -ErrorAction SilentlyContinue)) {

            $b = Get-PathSizeBytes -Path $d.FullName
            [pscustomobject]@{
                Carpeta=$d.Name;
                GB=[math]::Round($b/1GB,2)
            }

        }
        Write-CenteredTableVSO -Rows @($rows|Sort-Object GB -Descending|Select-Object -First 20) -Properties @('Carpeta','GB')

    }

    $systemDrive = if (-not [string]::IsNullOrWhiteSpace([string]$script:SystemDrive)) {
        [string]$script:SystemDrive
    } else {
        [IO.Path]::GetPathRoot([string]$script:WindowsRoot).TrimEnd('\')
    }
    $systemDriveRoot = $systemDrive.TrimEnd('\') + '\'
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es "`nArchivos individuales > 1 GB en {0} (hasta 30):" -En "`nIndividual files > 1 GB in {0} (up to 30):") -f $systemDrive) -ForegroundColor Cyan
    $largeFiles=@(Get-ChildItem -LiteralPath $systemDriveRoot -File -Force -Recurse -ErrorAction SilentlyContinue |
        Where-Object Length -gt 1GB |
        Sort-Object Length -Descending |
        Select-Object -First 30 FullName,@{
        N='GB';E={
            [math]::Round($_.Length/1GB,2)
        }
    })
    Write-CenteredTableVSO -Rows $largeFiles -Properties @('FullName','GB')

    $report = Join-Path $script:ReportRoot ("almacenamiento_{0}.txt" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    try {

        "Analisis mostrado en consola: $(Get-Date)" | Set-Content -LiteralPath $report -Encoding UTF8
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Informe base: {0}' -En 'Base report: {0}') -f $report) -ForegroundColor DarkGray

    } catch {}
    Pause-Vico

}

