function Test-VSO7ExtremeFeatureStateName {

    param([string]$State)
    # Get-WindowsOptionalFeature/DISM puede exponer nombres legacy (Enabled/Disabled)
    # y estados transitorios que requieren reinicio. Se aceptan para poder persistir
    # evidencia de una operacion real, pero los Pending NUNCA cuentan como baseline final.
    return @(
        'Enabled','Disabled','DisabledWithPayloadRemoved',
        'EnablePending','DisablePending',
        'Installed','NotPresent','Staged','Removed','InstallPending','UninstallPending','Superseded','PartiallyInstalled'
    ) -contains $State

}

function Get-VSO7ExtremeFeatureStateClassVSO {

    param([string]$State)
    switch -Exact ($State) {

        'Enabled' {
            return 'Enabled'
        }
        'Installed' {
            return 'Enabled'
        }
        'Disabled' {
            return 'Disabled'
        }
        'DisabledWithPayloadRemoved' {
            return 'Disabled'
        }
        'NotPresent' {
            return 'Disabled'
        }
        'Staged' {
            return 'Disabled'
        }
        'Removed' {
            return 'Disabled'
        }
        'EnablePending' {
            return 'EnablePending'
        }
        'InstallPending' {
            return 'EnablePending'
        }
        'DisablePending' {
            return 'DisablePending'
        }
        'UninstallPending' {
            return 'DisablePending'
        }
        'Superseded' {
            return 'Unsupported'
        }
        'PartiallyInstalled' {
            return 'Unsupported'
        }
        default {
            return $null
        }

    }

}

function Test-VSO7ExtremeFeatureStableStateVSO {

    param([string]$State)
    return @('Enabled','Disabled') -contains (Get-VSO7ExtremeFeatureStateClassVSO -State $State)

}

function Test-VSO7ExtremeFeatureAppliedDisableOwnedVSO {

    param([string]$CurrentState,[string]$RecordedAppliedState)
    $recorded=[string]$RecordedAppliedState;
    $current=[string]$CurrentState
    if(@('DisablePending','Disabled','UninstallPending','NotPresent')-notcontains$recorded){
        return $false
    }
    if($current-ieq$recorded){
        return $true
    }
    if($recorded-ieq'DisablePending'-and$current-ieq'Disabled'){
        return $true
    }
    if($recorded-ieq'UninstallPending'-and$current-ieq'NotPresent'){
        return $true
    }
    return $false

}

function Test-VSO7ExtremeFeaturePendingDisableOwnedVSO {

    param([string]$CurrentState,[string]$BaselineState)
    $baselineClass=Get-VSO7ExtremeFeatureStateClassVSO -State $BaselineState
    if($baselineClass-ine'Enabled'){
        return $false
    }
    # Sin -Remove, una desactivacion iniciada por VSO solo puede observarse como
    # DisablePending/Disabled (FeatureState) o UninstallPending/NotPresent (servicing).
    return @('DisablePending','Disabled','UninstallPending','NotPresent') -contains [string]$CurrentState

}

function Test-VSO7ExtremeFeatureRestorePendingForBaselineVSO {

    param([string]$CurrentState,[string]$BaselineState)
    $currentClass=Get-VSO7ExtremeFeatureStateClassVSO -State $CurrentState
    $baselineClass=Get-VSO7ExtremeFeatureStateClassVSO -State $BaselineState
    if($baselineClass-eq'Enabled'){
        return ($currentClass-eq'EnablePending')
    }
    if($baselineClass-eq'Disabled'){
        return ($currentClass-eq'DisablePending')
    }
    return $false

}

function ConvertTo-VSO7ValidatedExtremeState {

    param($Object)
    if($null-eq$Object){
        throw 'extreme-state.json esta vacio.'
    }
    $props=@($Object.PSObject.Properties|ForEach-Object{
        [string]$_.Name
    });
    $isV2=($props-contains'SchemaVersion')
    $required=if($isV2){
        @('SchemaVersion','Version','CreatedAt','Registry','Services','Features','PowerSettings','Hibernation','Bcd','PendingTweaks','AppliedTweaks')
    }else{
        @('Version','CreatedAt','Registry','Services','Features','PowerSettings','Hibernation','Bcd','PendingTweaks','AppliedTweaks')
    }
    if(-not(Test-VSO7ExactJsonProperties -Object $Object -Required $required)){
        throw 'extreme-state.json no coincide con un esquema reconocido.'
    }
    if($isV2 -and -not(Test-VSO7JsonInteger -Value $Object.SchemaVersion -Min 2 -Max 2)){
        throw 'SchemaVersion EXTREMO incompatible.'
    }
    if(-not($Object.Version -is [string]) -or [string]::IsNullOrWhiteSpace([string]$Object.Version) -or ([string]$Object.Version).Length -gt 32){
        throw 'Version EXTREMO invalida.'
    }
    if($isV2-and[string]$Object.Version-cne[string]$script:Version){
        throw ('extreme-state.json pertenece a VSO7 {0}; esta build exige estado schema v2 de VSO7 {1}.'-f[string]$Object.Version,[string]$script:Version)
    }
    if(-not($Object.CreatedAt -is [string]) -or -not(Test-VSO7IsoUtcTimestamp ([string]$Object.CreatedAt))){
        throw 'CreatedAt EXTREMO invalido.'
    }

    foreach($field in @('Registry','Services','Features','PowerSettings','Bcd','PendingTweaks','AppliedTweaks')){
        if($null-eq$Object.$field -or $Object.$field -is [string]){
            throw ("Coleccion EXTREMO invalida: {0}"-f$field)
        }
    }
    $registry=@($Object.Registry);
    $services=@($Object.Services);
    $features=@($Object.Features);
    $power=@($Object.PowerSettings);
    $bcd=@($Object.Bcd);
    $pending=@($Object.PendingTweaks);
    $applied=@($Object.AppliedTweaks)
    if($registry.Count-gt64-or$services.Count-gt32-or$features.Count-gt16-or$power.Count-gt16-or$bcd.Count-gt8-or$pending.Count-gt64-or$applied.Count-gt64){
        throw 'extreme-state.json excede limites de seguridad.'
    }
    if(-not$isV2-and($registry.Count-gt0-or$services.Count-gt0-or$features.Count-gt0-or$power.Count-gt0-or$bcd.Count-gt0-or$pending.Count-gt0-or$applied.Count-gt0-or$null-ne$Object.Hibernation)){
        throw 'extreme-state.json legado contiene rollback sin evidencia fuerte de ownership; 7.0.0 no lo ejecuta automaticamente.'
    }

    $normalizedPending=@();
    $normalizedApplied=@();
    $activeIds=@{};
    $pendingIds=@{}
    foreach($pair in @(@('Pending',$pending),@('Applied',$applied))){

        $kind=[string]$pair[0];
        $items=@($pair[1])
        foreach($item in $items){

            $timeField=if($kind-eq'Pending'){
                'StartedAt'
            }else{
                'AppliedAt'
            }
            if(-not(Test-VSO7ExactJsonProperties -Object $item -Required @('Id','Name','Risk','Reversible',$timeField))){
                throw ("Metadata {0} EXTREMO invalida."-f$kind)
            }
            if(-not($item.Id-is[string]) -or -not($item.Name-is[string]) -or [string]::IsNullOrWhiteSpace([string]$item.Id) -or ([string]$item.Name).Length-gt512){
                throw 'Id/Name EXTREMO invalido.'
            }
            $def=@(Get-VSO7ExtremeDefinitionById -Id ([string]$item.Id));
            if($def.Count-ne1-or-not[bool]$def[0].Reversible){
                throw ("Tweak EXTREMO fuera de allowlist reversible: {0}"-f$item.Id)
            }
            if(-not(Test-VSO7JsonInteger -Value $item.Risk -Min 1 -Max 4) -or [int]$item.Risk-ne[int]$def[0].Risk){
                throw 'Risk EXTREMO manipulado.'
            }
            if(-not($item.Reversible-is[bool]) -or -not[bool]$item.Reversible){
                throw 'Reversible EXTREMO invalido.'
            }
            if(-not($item.$timeField-is[string]) -or -not(Test-VSO7IsoUtcTimestamp ([string]$item.$timeField))){
                throw 'Timestamp de tweak EXTREMO invalido.'
            }
            $id=([string]$item.Id).ToLowerInvariant();
            if($activeIds.ContainsKey($id)){
                throw 'Tweak EXTREMO duplicado/Pending+Applied simultaneo.'
            };
            $activeIds[$id]=$true;
            if($kind-eq'Pending'){
                $pendingIds[$id]=$true
            }
            $normalized=[pscustomobject]@{
                Id=[string]$def[0].Id;
                Name=[string]$item.Name;
                Risk=[int]$def[0].Risk;
                Reversible=$true
            }
            if($kind-eq'Pending'){
                $normalized|Add-Member -NotePropertyName StartedAt -NotePropertyValue ([string]$item.StartedAt);
                $normalizedPending+=$normalized
            }else{
                $normalized|Add-Member -NotePropertyName AppliedAt -NotePropertyValue ([string]$item.AppliedAt);
                $normalizedApplied+=$normalized
            }

        }

    }

    $normalizedRegistry=@();
    $seen=@{}
    foreach($entry in $registry){

        $entryV2=(@($entry.PSObject.Properties.Name)-contains'Status');
        $req=if($entryV2){
            @('TweakId','Path','Name','Exists','Kind','Value','AppliedExists','AppliedKind','AppliedValue','Status')
        }else{
            @('TweakId','Path','Name','Exists','Kind','Value')
        }
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'Entrada Registry EXTREMO con esquema invalido.'
        }
        if(-not($entry.TweakId-is[string])-or-not($entry.Path-is[string])-or-not($entry.Name-is[string])){
            throw 'Registry EXTREMO tipos invalidos.'
        }
        $def=@(Get-VSO7ExtremeRegistryDefinition -TweakId ([string]$entry.TweakId) -Path ([string]$entry.Path) -Name ([string]$entry.Name));
        if($def.Count-ne1){
            throw 'Registry EXTREMO fuera de allowlist.'
        }
        $id=([string]$def[0].TweakId).ToLowerInvariant();
        if(-not$activeIds.ContainsKey($id)){
            throw 'Registry EXTREMO sin tweak Pending/Applied propietario.'
        }
        $key=$id+'|'+([string]$def[0].Path).ToLowerInvariant()+'|'+([string]$def[0].Name).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'Registry EXTREMO duplicado.'
        };
        $seen[$key]=$true
        if(-not($entry.Exists-is[bool])){
            throw 'Exists Registry EXTREMO invalido.'
        };
        $kind=$null;
        $value=$null
        if([bool]$entry.Exists){
            if(-not($entry.Kind-is[string])-or-not(Test-VSO7RegistryJsonValueShape -Value $entry.Value -Kind ([string]$entry.Kind))){
                throw 'Baseline Registry EXTREMO invalido.'
            };
            $kind=[string]$entry.Kind;
            $value=$entry.Value
        }else{
            if($null-ne$entry.Kind-and-not[string]::IsNullOrWhiteSpace([string]$entry.Kind)){
                throw 'Kind Registry EXTREMO debe ser null.'
            };
            if($null-ne$entry.Value){
                throw 'Value Registry EXTREMO debe ser null.'
            }
        }
        $status='Pending';
        if($entryV2){
            if(-not($entry.AppliedExists-is[bool])-or-not[bool]$entry.AppliedExists){
                throw 'AppliedExists EXTREMO invalido.'
            };
            if(-not($entry.AppliedKind-is[string])-or[string]$entry.AppliedKind-ine[string]$def[0].Kind){
                throw 'AppliedKind EXTREMO invalido.'
            };
            if(-not(Test-RegistryValueEqualVSO -Actual $entry.AppliedValue -Expected $def[0].Value -Kind ([string]$def[0].Kind))){
                throw 'AppliedValue EXTREMO fuera de allowlist.'
            };
            if(-not($entry.Status-is[string])-or@('Pending','Applied')-notcontains[string]$entry.Status){
                throw 'Status Registry EXTREMO invalido.'
            };
            $status=[string]$entry.Status
        }
        $normalizedRegistry+=[pscustomobject]@{
            TweakId=[string]$def[0].TweakId;
            Path=[string]$def[0].Path;
            Name=[string]$def[0].Name;
            Exists=[bool]$entry.Exists;
            Kind=$kind;
            Value=$value;
            AppliedExists=$true;
            AppliedKind=[string]$def[0].Kind;
            AppliedValue=$def[0].Value;
            Status=$status
        }

    }

    $normalizedServices=@();
    $seen=@{}
    foreach($entry in $services){

        $hasApplied=(@($entry.PSObject.Properties.Name)-contains'AppliedStartValue');
        $hasDelayedApplied=(@($entry.PSObject.Properties.Name)-contains'AppliedDelayedAutoStartExists');
        $hasStatus=(@($entry.PSObject.Properties.Name)-contains'Status');
        $req=if($hasDelayedApplied-or$hasStatus){
            @('TweakId','Name','StartValue','DelayedAutoStartExists','DelayedAutoStart','WasRunning','AppliedStartValue','AppliedDelayedAutoStartExists','AppliedDelayedAutoStart','Status')
        }elseif($hasApplied){
            @('TweakId','Name','StartValue','DelayedAutoStartExists','DelayedAutoStart','WasRunning','AppliedStartValue')
        }else{
            @('TweakId','Name','StartValue','DelayedAutoStartExists','DelayedAutoStart','WasRunning')
        };
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'Servicio EXTREMO esquema invalido.'
        }
        if(-not($entry.TweakId-is[string])-or-not($entry.Name-is[string])){
            throw 'Servicio EXTREMO tipos invalidos.'
        };
        $def=@(Get-VSO7ExtremeServiceDefinitions|Where-Object{
            $_.TweakId-ieq[string]$entry.TweakId-and$_.Name-ieq[string]$entry.Name
        });
        if($def.Count-ne1){
            throw 'Servicio EXTREMO fuera de allowlist.'
        };
        $id=([string]$def[0].TweakId).ToLowerInvariant();
        if(-not$activeIds.ContainsKey($id)){
            throw 'Servicio EXTREMO sin owner.'
        };
        $key=$id+'|'+([string]$def[0].Name).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'Servicio EXTREMO duplicado.'
        };
        $seen[$key]=$true
        if(-not(Test-VSO7JsonInteger -Value $entry.StartValue -Min 2 -Max 4)-or-not($entry.DelayedAutoStartExists-is[bool])-or-not($entry.WasRunning-is[bool])){
            throw 'Baseline de servicio EXTREMO invalido.'
        };
        $delayed=$null;
        if([bool]$entry.DelayedAutoStartExists){
            if(-not(Test-VSO7JsonInteger -Value $entry.DelayedAutoStart -Min 0 -Max 1)){
                throw 'DelayedAutoStart invalido.'
            };
            $delayed=[int]$entry.DelayedAutoStart
        }elseif($null-ne$entry.DelayedAutoStart){
            throw 'DelayedAutoStart debe ser null.'
        };
        if($hasApplied-and(-not(Test-VSO7JsonInteger -Value $entry.AppliedStartValue -Min 4 -Max 4))){
            throw 'AppliedStartValue manipulado.'
        };
        $appliedDelayedExists=$false;
        $appliedDelayed=$null;
        $status='UnknownPending';
        if($hasDelayedApplied-or$hasStatus){
            if(-not($entry.AppliedDelayedAutoStartExists-is[bool])){
                throw 'AppliedDelayedAutoStartExists invalido.'
            };
            $appliedDelayedExists=[bool]$entry.AppliedDelayedAutoStartExists;
            if($appliedDelayedExists){
                if(-not(Test-VSO7JsonInteger -Value $entry.AppliedDelayedAutoStart -Min 0 -Max 1)){
                    throw 'AppliedDelayedAutoStart invalido.'
                };
                $appliedDelayed=[int]$entry.AppliedDelayedAutoStart
            }elseif($null-ne$entry.AppliedDelayedAutoStart){
                throw 'AppliedDelayedAutoStart debe ser null.'
            };
            if(-not($entry.Status-is[string])-or@('Pending','Applied','UnknownPending')-notcontains[string]$entry.Status){
                throw 'Status Servicio EXTREMO invalido.'
            };
            $status=[string]$entry.Status
        }
        $normalizedServices+=[pscustomobject]@{
            TweakId=[string]$def[0].TweakId;
            Name=[string]$def[0].Name;
            StartValue=[int]$entry.StartValue;
            DelayedAutoStartExists=[bool]$entry.DelayedAutoStartExists;
            DelayedAutoStart=$delayed;
            WasRunning=[bool]$entry.WasRunning;
            AppliedStartValue=4;
            AppliedDelayedAutoStartExists=$appliedDelayedExists;
            AppliedDelayedAutoStart=$appliedDelayed;
            Status=$status
        }

    }

    $normalizedFeatures=@();
    $seen=@{}
    foreach($entry in $features){

        $v2=(@($entry.PSObject.Properties.Name)-contains'Status');
        $req=if($v2){
            @('TweakId','Name','State','AppliedState','Status')
        }else{
            @('TweakId','Name','State')
        };
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'Feature EXTREMO esquema invalido.'
        };
        if(-not($entry.TweakId-is[string])-or-not($entry.Name-is[string])-or-not($entry.State-is[string])){
            throw 'Feature EXTREMO tipos invalidos.'
        };
        $def=@(Get-VSO7ExtremeFeatureDefinitions|Where-Object{
            $_.TweakId-ieq[string]$entry.TweakId-and$_.Name-ieq[string]$entry.Name
        });
        if($def.Count-ne1-or-not(Test-VSO7ExtremeFeatureStateName ([string]$entry.State))){
            throw 'Feature EXTREMO fuera de allowlist/estado.'
        };
        $id=([string]$def[0].TweakId).ToLowerInvariant();
        if(-not$activeIds.ContainsKey($id)){
            throw 'Feature EXTREMO sin owner.'
        };
        $key=$id+'|'+([string]$def[0].Name).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'Feature EXTREMO duplicada.'
        };
        $seen[$key]=$true
        $baselineClass=Get-VSO7ExtremeFeatureStateClassVSO -State ([string]$entry.State)
        if(@('Enabled','Disabled')-notcontains$baselineClass){
            throw ('Baseline Feature no es un estado estable soportado por VSO7: {0}'-f$entry.State)
        }
        $appliedState=$null;
        $status='Pending'
        if($v2){

            if(-not($entry.Status-is[string])-or@('Pending','Applied','RestorePending')-notcontains[string]$entry.Status){
                throw 'Status Feature invalido.'
            }
            $status=[string]$entry.Status
            if($null-ne$entry.AppliedState-and-not($entry.AppliedState-is[string])){
                throw 'AppliedState Feature invalido.'
            }
            $appliedState=[string]$entry.AppliedState
            if($status-ieq'Pending'){

                if(-not[string]::IsNullOrWhiteSpace($appliedState)){
                    throw 'Feature Pending no puede afirmar AppliedState antes de confirmar la mutacion.'
                }

            }elseif($status-ieq'Applied'){

                if([string]::IsNullOrWhiteSpace($appliedState)-or-not(Test-VSO7ExtremeFeatureStateName $appliedState)){
                    throw 'AppliedState Feature ausente/invalido.'
                }
                if($baselineClass-eq'Enabled'){

                    if(-not(Test-VSO7ExtremeFeatureAppliedDisableOwnedVSO -CurrentState $appliedState -RecordedAppliedState $appliedState)){
                        throw 'Feature aplicada no refleja una desactivacion estable/pendiente.'
                    }

                }elseif($appliedState-ine[string]$entry.State){
                    throw 'Feature con baseline deshabilitado no fue mutada por VSO7; AppliedState debe coincidir exactamente con baseline.'
                }

            }elseif($status-ieq'RestorePending'){

                if($baselineClass-ne'Enabled'){
                    throw 'RestorePending solo es valido para una Feature que VSO7 deshabilito desde baseline Enabled.'
                }
                if([string]::IsNullOrWhiteSpace($appliedState)-or-not(Test-VSO7ExtremeFeatureStateName $appliedState)){
                    throw 'Feature RestorePending sin estado esperado.'
                }
                if(-not(Test-VSO7ExtremeFeatureRestorePendingForBaselineVSO -CurrentState $appliedState -BaselineState ([string]$entry.State))){
                    throw 'Feature RestorePending no progresa hacia su baseline.'
                }

            }

        }
        $normalizedFeatures+=[pscustomobject]@{
            TweakId=[string]$def[0].TweakId;
            Name=[string]$def[0].Name;
            State=[string]$entry.State;
            AppliedState=if([string]::IsNullOrWhiteSpace($appliedState)){
                $null
            }else{
                $appliedState
            };
            Status=$status
        }

    }

    $normalizedPower=@();
    $seen=@{}
    foreach($entry in $power){

        $hasApplied=(@($entry.PSObject.Properties.Name)-contains'AppliedAC');
        $hasStatus=(@($entry.PSObject.Properties.Name)-contains'Status');
        $req=if($hasStatus){
            @('TweakId','SchemeGuid','SubGroupAlias','SettingAlias','AC','DC','AppliedAC','AppliedDC','Status')
        }elseif($hasApplied){
            @('TweakId','SchemeGuid','SubGroupAlias','SettingAlias','AC','DC','AppliedAC','AppliedDC')
        }else{
            @('TweakId','SchemeGuid','SubGroupAlias','SettingAlias','AC','DC')
        };
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'PowerSettings EXTREMO esquema invalido.'
        };
        if(-not($entry.TweakId-is[string])-or-not($entry.SchemeGuid-is[string])-or-not($entry.SubGroupAlias-is[string])-or-not($entry.SettingAlias-is[string])){
            throw 'PowerSettings tipos invalidos.'
        };
        $def=@(Get-VSO7ExtremePowerDefinitions|Where-Object{
            $_.TweakId-ieq[string]$entry.TweakId-and$_.SubGroupAlias-ieq[string]$entry.SubGroupAlias-and$_.SettingAlias-ieq[string]$entry.SettingAlias
        });
        if($def.Count-ne1-or-not(Test-VSO7PowerSchemeGuid ([string]$entry.SchemeGuid))){
            throw 'PowerSettings fuera de allowlist.'
        };
        $id=([string]$def[0].TweakId).ToLowerInvariant();
        if(-not$activeIds.ContainsKey($id)){
            throw 'PowerSettings sin owner.'
        };
        $key=$id+'|'+([string]$entry.SchemeGuid).ToLowerInvariant()+'|'+([string]$def[0].SubGroupAlias).ToLowerInvariant()+'|'+([string]$def[0].SettingAlias).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'PowerSettings duplicado.'
        };
        $seen[$key]=$true
        if(-not(Test-VSO7JsonInteger -Value $entry.AC -Min 0 -Max 2147483647)-or-not(Test-VSO7JsonInteger -Value $entry.DC -Min 0 -Max 2147483647)){
            throw 'Baseline PowerSettings invalido.'
        };
        if($hasApplied-and(-not(Test-VSO7JsonInteger -Value $entry.AppliedAC -Min ([int]$def[0].AppliedValue) -Max ([int]$def[0].AppliedValue))-or-not(Test-VSO7JsonInteger -Value $entry.AppliedDC -Min ([int]$def[0].AppliedValue) -Max ([int]$def[0].AppliedValue)))){
            throw 'Applied PowerSettings manipulado.'
        };
        $status='Pending';
        if($hasStatus){
            if(-not($entry.Status-is[string])-or@('Pending','Applied')-notcontains[string]$entry.Status){
                throw 'Status PowerSettings invalido.'
            };
            $status=[string]$entry.Status
        }
        $normalizedPower+=[pscustomobject]@{
            TweakId=[string]$def[0].TweakId;
            SchemeGuid=([guid][string]$entry.SchemeGuid).ToString('D');
            SubGroupAlias=[string]$def[0].SubGroupAlias;
            SettingAlias=[string]$def[0].SettingAlias;
            AC=[int]$entry.AC;
            DC=[int]$entry.DC;
            AppliedAC=[int]$def[0].AppliedValue;
            AppliedDC=[int]$def[0].AppliedValue;
            Status=$status
        }

    }

    $normalizedBcd=@();
    $seen=@{}
    foreach($entry in $bcd){

        $v2=(@($entry.PSObject.Properties.Name)-contains'Status');
        $req=if($v2){
            @('TweakId','Name','Exists','Value','AppliedValue','Status')
        }else{
            @('TweakId','Name','Exists','Value')
        };
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'BCD EXTREMO esquema invalido.'
        };
        if(-not($entry.TweakId-is[string])-or-not($entry.Name-is[string])-or-not($entry.Exists-is[bool])){
            throw 'BCD EXTREMO tipos invalidos.'
        };
        $def=@(Get-VSO7ExtremeBcdDefinitions|Where-Object{
            $_.TweakId-ieq[string]$entry.TweakId-and$_.Name-ieq[string]$entry.Name
        });
        if($def.Count-ne1){
            throw 'BCD fuera de allowlist.'
        };
        $id=([string]$def[0].TweakId).ToLowerInvariant();
        if(-not$activeIds.ContainsKey($id)){
            throw 'BCD sin owner.'
        };
        $key=$id+'|'+([string]$def[0].Name).ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw 'BCD duplicado.'
        };
        $seen[$key]=$true
        $original=$null;
        if([bool]$entry.Exists){
            if(-not($entry.Value-is[string])-or@('Auto','Off')-notcontains[string]$entry.Value){
                throw 'Baseline BCD invalido.'
            };
            $original=[string]$entry.Value
        }elseif($null-ne$entry.Value-and-not[string]::IsNullOrWhiteSpace([string]$entry.Value)){
            throw 'BCD Value debe ser null cuando Exists=false.'
        };
        $status='Pending';
        if($v2){
            if(-not($entry.AppliedValue-is[string])-or[string]$entry.AppliedValue-ine[string]$def[0].AppliedValue){
                throw 'AppliedValue BCD manipulado.'
            };
            if(-not($entry.Status-is[string])-or@('Pending','Applied')-notcontains[string]$entry.Status){
                throw 'Status BCD invalido.'
            };
            $status=[string]$entry.Status
        }
        $normalizedBcd+=[pscustomobject]@{
            TweakId=[string]$def[0].TweakId;
            Name=[string]$def[0].Name;
            Exists=[bool]$entry.Exists;
            Value=$original;
            AppliedValue=[string]$def[0].AppliedValue;
            Status=$status
        }

    }

    $hib=$null
    if($null-ne$Object.Hibernation){

        $entry=$Object.Hibernation
        $props=@($entry.PSObject.Properties.Name)
        $v2=($props-contains'Status')
        $hasTypeEvidence=($props-contains'TypeExists')-and($props-contains'Type')
        $hasAppliedRegistry=($props-contains'AppliedSizePercentExists')-and($props-contains'AppliedSizePercent')-and($props-contains'AppliedTypeExists')-and($props-contains'AppliedType')
        if($v2-and(-not$hasTypeEvidence-or-not$hasAppliedRegistry)){
            throw 'Hibernation EXTREMO antigua sin evidencia exacta de tipo/tamano aplicado; rollback automatico denegado.'
        }
        $req=if($v2){
            @('TweakId','Enabled','SizePercentExists','SizePercent','TypeExists','Type','AppliedEnabled','AppliedSizePercentExists','AppliedSizePercent','AppliedTypeExists','AppliedType','Status')
        }else{
            @('TweakId','Enabled','SizePercentExists','SizePercent')
        }
        if(-not(Test-VSO7ExactJsonProperties -Object $entry -Required $req)){
            throw 'Hibernation EXTREMO esquema invalido.'
        }
        if(-not($entry.TweakId-is[string])-or[string]$entry.TweakId-ine'power.hibernate'-or-not$activeIds.ContainsKey('power.hibernate')){
            throw 'Hibernation fuera de allowlist/sin owner.'
        }
        if(-not($entry.Enabled-is[bool])-or-not($entry.SizePercentExists-is[bool])){
            throw 'Hibernation tipos invalidos.'
        }
        $pct=$null
        if([bool]$entry.SizePercentExists){
            if(-not(Test-VSO7JsonInteger -Value $entry.SizePercent -Min 0 -Max 100)){
                throw 'HiberFileSizePercent invalido.'
            };
            $pct=[int]$entry.SizePercent
        }elseif($null-ne$entry.SizePercent){
            throw 'SizePercent debe ser null.'
        }
        $typeExists=$false;
        $type=$null;
        $appliedSizeExists=$false;
        $appliedSize=$null;
        $appliedTypeExists=$false;
        $appliedType=$null;
        $status='Pending'
        if($v2){

            if(-not($entry.TypeExists-is[bool])-or-not($entry.AppliedEnabled-is[bool])-or[bool]$entry.AppliedEnabled-or-not($entry.AppliedSizePercentExists-is[bool])-or-not($entry.AppliedTypeExists-is[bool])){
                throw 'Hibernation evidencia aplicada manipulada.'
            }
            $typeExists=[bool]$entry.TypeExists
            if($typeExists){
                if(-not(Test-VSO7JsonInteger -Value $entry.Type -Min 0 -Max 2)){
                    throw 'HiberFileType invalido.'
                };
                $type=[int]$entry.Type;
                if([bool]$entry.Enabled-and$type-eq0){
                    throw 'HiberFileType=0 incompatible con baseline habilitado.'
                }
            }elseif($null-ne$entry.Type){
                throw 'Type debe ser null cuando TypeExists=false.'
            }
            $appliedSizeExists=[bool]$entry.AppliedSizePercentExists
            if($appliedSizeExists){
                if(-not(Test-VSO7JsonInteger -Value $entry.AppliedSizePercent -Min 0 -Max 100)){
                    throw 'Applied HiberFileSizePercent invalido.'
                };
                $appliedSize=[int]$entry.AppliedSizePercent
            }elseif($null-ne$entry.AppliedSizePercent){
                throw 'AppliedSizePercent debe ser null.'
            }
            $appliedTypeExists=[bool]$entry.AppliedTypeExists
            if($appliedTypeExists){
                if(-not(Test-VSO7JsonInteger -Value $entry.AppliedType -Min 0 -Max 2)){
                    throw 'Applied HiberFileType invalido.'
                };
                $appliedType=[int]$entry.AppliedType
            }elseif($null-ne$entry.AppliedType){
                throw 'AppliedType debe ser null.'
            }
            if(-not($entry.Status-is[string])-or@('Pending','Applied')-notcontains[string]$entry.Status){
                throw 'Status Hibernation invalido.'
            };
            $status=[string]$entry.Status

        }
        $hib=[pscustomobject]@{
            TweakId='power.hibernate';
            Enabled=[bool]$entry.Enabled;
            SizePercentExists=[bool]$entry.SizePercentExists;
            SizePercent=$pct;
            TypeExists=$typeExists;
            Type=$type;
            AppliedEnabled=$false;
            AppliedSizePercentExists=$appliedSizeExists;
            AppliedSizePercent=$appliedSize;
            AppliedTypeExists=$appliedTypeExists;
            AppliedType=$appliedType;
            Status=$status
        }

    }

    $evidence=@{};
    foreach($entry in @($normalizedRegistry+$normalizedServices+$normalizedFeatures+$normalizedPower+$normalizedBcd)){
        if($null-ne$entry){
            $evidence[([string]$entry.TweakId).ToLowerInvariant()]=$true
        }
    };
    if($null-ne$hib){
        $evidence['power.hibernate']=$true
    }
    foreach($item in $normalizedApplied){
        if(-not$evidence.ContainsKey(([string]$item.Id).ToLowerInvariant())){
            throw ("Tweak Applied sin evidencia de rollback: {0}"-f$item.Id)
        }
    }
    return @{
        SchemaVersion=2;
        Version=[string]$Object.Version;
        CreatedAt=[string]$Object.CreatedAt;
        Registry=$normalizedRegistry;
        Services=$normalizedServices;
        Features=$normalizedFeatures;
        PowerSettings=$normalizedPower;
        Hibernation=$hib;
        Bcd=$normalizedBcd;
        PendingTweaks=$normalizedPending;
        AppliedTweaks=$normalizedApplied
    }

}

function New-EmptyExtremeState {

    return @{
        SchemaVersion=2;
        Version=$script:Version;
        CreatedAt=(Get-Date).ToString('o');
        Registry=@();
        Services=@();
        Features=@();
        PowerSettings=@();
        Hibernation=$null;
        Bcd=@();
        PendingTweaks=@();
        AppliedTweaks=@()
    }

}

function Load-ExtremeState {

    if(-not(Test-Path -LiteralPath $script:ExtremeStateFile)){
        $script:ExtremeState=New-EmptyExtremeState;
        return
    }
    try{
        $o=Get-Content -LiteralPath $script:ExtremeStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop;
        $script:ExtremeState=ConvertTo-VSO7ValidatedExtremeState -Object $o;
        Resolve-PendingExtremeStateVSO
    }catch{
        Write-VSO7Log ("No se pudo validar extreme-state.json: {0}"-f$_.Exception.Message) 'ERROR';
        throw 'VSO7 no continuara sin poder validar semanticamente su estado de rollback EXTREMO.'
    }

}

function Save-ExtremeState {

    $recoveryPublishBundle=$null
    try{

        $validated=ConvertTo-VSO7ValidatedExtremeState -Object ([pscustomobject]$script:ExtremeState)
        $script:ExtremeState=$validated
        $tmp="$($script:ExtremeStateFile).tmp"
        ($validated|ConvertTo-Json -Depth 12)|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedExtremeState -Object $check)
        if(-not[string]::IsNullOrWhiteSpace($script:LastRecoveryBundle)-and(Test-Path -LiteralPath $script:LastRecoveryBundle)){

            $recoveryPublishBundle=Start-VSO7RecoveryPublishTransactionVSO -Bundle $script:LastRecoveryBundle

        }
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $script:ExtremeStateFile)
        $check=Get-Content -LiteralPath $script:ExtremeStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedExtremeState -Object $check)
        if(-not[string]::IsNullOrWhiteSpace([string]$recoveryPublishBundle)){

            [void](Publish-VSO7RecoveryGenerationVSO -Bundle $recoveryPublishBundle)
            Clear-VSO7RecoveryPublishJournalVSO

        }

    }catch{

        try{
            if(Test-Path -LiteralPath "$($script:ExtremeStateFile).tmp" -PathType Leaf){
                Remove-Item -LiteralPath "$($script:ExtremeStateFile).tmp" -Force -ErrorAction SilentlyContinue
            }
        }catch{}
        Write-VSO7Log ("No se pudo guardar/verificar extreme-state.json: {0}"-f$_.Exception.Message) 'ERROR'
        throw

    }

}

function Test-ExtremeTweakHasRecoveryEvidenceVSO {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    if (@($script:ExtremeState.Registry | Where-Object {
        $_.TweakId -eq $TweakId
    }).Count -gt 0) {
        return $true
    }
    if (@($script:ExtremeState.Services | Where-Object {
        $_.TweakId -eq $TweakId
    }).Count -gt 0) {
        return $true
    }
    if (@($script:ExtremeState.Features | Where-Object {
        $_.TweakId -eq $TweakId
    }).Count -gt 0) {
        return $true
    }
    if (@($script:ExtremeState.PowerSettings | Where-Object {
        $_.TweakId -eq $TweakId
    }).Count -gt 0) {
        return $true
    }
    if (@($script:ExtremeState.Bcd | Where-Object {
        $_.TweakId -eq $TweakId
    }).Count -gt 0) {
        return $true
    }
    if ($null -ne $script:ExtremeState.Hibernation -and [string]$script:ExtremeState.Hibernation.TweakId -eq $TweakId) {
        return $true
    }
    return $false

}

function Resolve-PendingExtremeStateVSO {

    if ($null -eq $script:ExtremeState -or $null -eq $script:ExtremeState.PendingTweaks) {
        return
    }
    $keep=@();
    $changed=$false
    foreach($pending in @($script:ExtremeState.PendingTweaks)){

        $id=[string]$pending.Id
        if([string]::IsNullOrWhiteSpace($id)){
            $changed=$true;
            continue
        }
        if(Test-ExtremeTweakHasRecoveryEvidenceVSO -TweakId $id){

            $keep += $pending
            Write-VSO7Log ("Tweak EXTREMO pendiente conservado para rollback: {0}" -f $id) 'WARN'

        }else{

            $changed=$true
            Write-VSO7Log ("Tweak EXTREMO Pending sin evidencia de modificacion descartado: {0}" -f $id) 'WARN'

        }

    }
    if($changed){
        $script:ExtremeState.PendingTweaks=@($keep);
        Save-ExtremeState
    }

}

function Start-PendingExtremeTweakVSO {

    param([Parameter(Mandatory=$true)]$Tweak)
    if(-not [bool]$Tweak.Reversible){
        return
    }
    if(@($script:ExtremeState.AppliedTweaks|Where-Object{
        $_.Id-eq$Tweak.Id
    }).Count-gt0){
        return
    }
    if(@($script:ExtremeState.PendingTweaks|Where-Object{
        $_.Id-eq$Tweak.Id
    }).Count-gt0){
        return
    }
    $script:ExtremeState.PendingTweaks += [pscustomobject]@{
        Id=$Tweak.Id;
        Name=$Tweak.Name;
        Risk=$Tweak.Risk;
        Reversible=$true;
        StartedAt=(Get-Date).ToString('o')
    }
    Save-ExtremeState

}

function Complete-AppliedExtremeTweakVSO {

    param([Parameter(Mandatory=$true)]$Tweak)
    $script:ExtremeState.PendingTweaks=@($script:ExtremeState.PendingTweaks|Where-Object{
        $_.Id-ne$Tweak.Id
    })
    if([bool]$Tweak.Reversible -and @($script:ExtremeState.AppliedTweaks|Where-Object{
        $_.Id-eq$Tweak.Id
    }).Count-eq0){

        $script:ExtremeState.AppliedTweaks += [pscustomobject]@{
            Id=$Tweak.Id;
            Name=$Tweak.Name;
            Risk=$Tweak.Risk;
            Reversible=$true;
            AppliedAt=(Get-Date).ToString('o')
        }

    }
    Save-ExtremeState

}

function Backup-ExtremeRegistryValue {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)]$AppliedValue,
        [Parameter(Mandatory=$true)][string]$AppliedKind,
        [Parameter(Mandatory=$true)]$ObservedSnapshot
    )
    $def=@(Get-VSO7ExtremeRegistryDefinition -TweakId $TweakId -Path $Path -Name $Name)
    if($def.Count-ne1-or[string]$def[0].Kind-ine$AppliedKind-or-not(Test-RegistryValueEqualVSO -Actual $AppliedValue -Expected $def[0].Value -Kind $AppliedKind)){
        throw 'Set-ExtremeRegistryValue intento usar un destino/valor fuera de allowlist.'
    }
    $already=@($script:ExtremeState.Registry|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name
    })
    if($already.Count-gt0){
        $already[0].AppliedExists=$true;
        $already[0].AppliedKind=$AppliedKind;
        $already[0].AppliedValue=$AppliedValue;
        $already[0].Status='Pending';
        Save-ExtremeState;
        return
    }
    $snap=Get-ExistingRegistryBaselineVSO -Path $Path -Name $Name
    if($null-eq$snap){

        if($null-eq$ObservedSnapshot-or[string]$ObservedSnapshot.Path-ine$Path-or[string]$ObservedSnapshot.Name-ine$Name){
            throw 'Snapshot observado invalido al crear rollback Registry EXTREMO.'
        }
        $snap=$ObservedSnapshot

    }
    $script:ExtremeState.Registry += [pscustomobject]@{
        TweakId=$TweakId;
        Path=$snap.Path;
        Name=$snap.Name;
        Exists=[bool]$snap.Exists;
        Kind=$snap.Kind;
        Value=$snap.Value;
        AppliedExists=$true;
        AppliedKind=$AppliedKind;
        AppliedValue=$AppliedValue;
        Status='Pending'
    }
    Save-ExtremeState

}

function Test-RegistryValueEqualVSO {

    param($Actual,$Expected,[string]$Kind)

    if ($Kind -eq 'Binary') {

        try {

            return ([BitConverter]::ToString([byte[]]$Actual) -ceq [BitConverter]::ToString([byte[]]$Expected))

        } catch {
            return $false
        }

    }
    if ($Kind -eq 'MultiString') {

        return ((@($Actual) -join "`0") -eq (@($Expected) -join "`0"))

    }
    return ([string]$Actual -eq [string]$Expected)

}

function Set-ExtremeRegistryValue {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)]$Value,
        [ValidateSet('DWord','QWord','String','ExpandString','MultiString','Binary')][string]$Type='DWord'
    )
    [void](Assert-VSO7NoNativeRegistryOwnershipVSO -Path $Path -Name $Name)
    $beforePending=Get-RegistrySnapshot -Path $Path -Name $Name
    $existingBefore=@($script:ExtremeState.Registry|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name
    })
    if($existingBefore.Count-gt1){
        throw 'Estado Registry EXTREMO duplicado antes de iniciar la transaccion.'
    }
    $hadExisting=($existingBefore.Count-eq1)
    $previousStatus=if($hadExisting){
        [string]$existingBefore[0].Status
    }else{
        $null
    }
    $previousAppliedExists=if($hadExisting){
        [bool]$existingBefore[0].AppliedExists
    }else{
        $false
    }
    $previousAppliedKind=if($hadExisting){
        $existingBefore[0].AppliedKind
    }else{
        $null
    }
    $previousAppliedValue=if($hadExisting){
        $existingBefore[0].AppliedValue
    }else{
        $null
    }
    Backup-ExtremeRegistryValue -TweakId $TweakId -Path $Path -Name $Name -AppliedValue $Value -AppliedKind $Type -ObservedSnapshot $beforePending

    try{

        if(Test-RegistryValueOwnedByNormalVSO -Path $Path -Name $Name){
            [void](Assert-VSO7SharedRegistryOwnershipCompatibleVSO -Path $Path -Name $Name)
        }
        $afterPending=Get-RegistrySnapshot -Path $Path -Name $Name

    }
    catch{

        if($hadExisting){
            $owned=@($script:ExtremeState.Registry|Where-Object{
                $_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name
            }|Select-Object -First 1);
            if($owned.Count-eq1){
                $owned[0].Status=$previousStatus;
                $owned[0].AppliedExists=$previousAppliedExists;
                $owned[0].AppliedKind=$previousAppliedKind;
                $owned[0].AppliedValue=$previousAppliedValue
            }
        }
        else{
            $script:ExtremeState.Registry=@($script:ExtremeState.Registry|Where-Object{
                -not($_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name)
            })
        }
        Save-ExtremeState
        throw ("No se pudo revalidar Registry EXTREMO antes de mutar; VSO7 retiro su Pending: {0}"-f$_.Exception.Message)

    }
    if(-not(Test-VSO7RegistrySnapshotEqualVSO -Left $beforePending -Right $afterPending)){

        if($hadExisting){
            $owned=@($script:ExtremeState.Registry|Where-Object{
                $_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name
            }|Select-Object -First 1);
            if($owned.Count-eq1){
                $owned[0].Status=$previousStatus;
                $owned[0].AppliedExists=$previousAppliedExists;
                $owned[0].AppliedKind=$previousAppliedKind;
                $owned[0].AppliedValue=$previousAppliedValue
            }
        }
        else{
            $script:ExtremeState.Registry=@($script:ExtremeState.Registry|Where-Object{
                -not($_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name)
            })
        }
        Save-ExtremeState
        throw 'Registro EXTREMO cambio entre snapshot y mutacion; VSO7 retiro su Pending sin tocar Windows.'

    }

    if(-not(Test-Path -LiteralPath $Path)){
        New-Item -Path $Path -Force -ErrorAction Stop|Out-Null
    }
    New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType $Type -Force -ErrorAction Stop|Out-Null
    $verify=Get-RegistrySnapshot -Path $Path -Name $Name
    if(-not[bool]$verify.Exists){
        throw ("No aparece el valor de Registro despues de escribirlo: {0}\{1}"-f$Path,$Name)
    }
    if(-not(Test-RegistryValueEqualVSO -Actual $verify.Value -Expected $Value -Kind $Type)){
        throw ("Verificacion fallida de Registro: {0}\{1}"-f$Path,$Name)
    }
    $owned=@($script:ExtremeState.Registry|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Path-ieq$Path-and$_.Name-ieq$Name
    }|Select-Object -First 1);
    if($owned.Count-ne1){
        throw 'Se perdio el rollback EXTREMO de Registro.'
    };
    $owned[0].Status='Applied';
    Save-ExtremeState
    Write-VSO7Log ("EXTREMO [{0}] Registro verificado: {1}\{2}"-f$TweakId,$Path,$Name) 'CHANGE'

}

function Get-VSO7ServiceStatusVSO {

    param([Parameter(Mandatory=$true)][string]$Name)
    if([string]::IsNullOrWhiteSpace($Name)-or$Name.Length-gt256-or$Name-notmatch'^[A-Za-z0-9_.-]+$'){
        throw 'Nombre de servicio invalido.'
    }
    $escaped=$Name.Replace("'","''")
    $rows=@(CimCmdlets\Get-CimInstance Win32_Service -Filter ("Name='{0}'"-f$escaped) -ErrorAction Stop)
    if($rows.Count-eq0){
        return $null
    }
    if($rows.Count-ne1){
        throw ("Win32_Service devolvio multiples filas para {0}."-f$Name)
    }
    return [string]$rows[0].State

}

function Backup-ExtremeService {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [Parameter(Mandatory=$true)][string]$Name
    )

    $existing = @($script:ExtremeState.Services | Where-Object {
        $_.TweakId -eq $TweakId -and $_.Name -eq $Name
    })
    if ($existing.Count -gt 0) {
        return $true
    }

    try{
        $serviceStatus=Get-VSO7ServiceStatusVSO -Name $Name
    }catch{
        Write-VSO7Log ("No se pudo consultar el servicio {0}: {1}"-f$Name,$_.Exception.Message) 'ERROR';
        return $false
    }
    if ($null -eq $serviceStatus) {
        return $false
    }
    if(@('Running','Stopped')-notcontains[string]$serviceStatus){
        Write-VSO7Log ("Servicio {0} en estado transitorio {1}; VSO7 no lo modifica."-f$Name,$serviceStatus) 'WARN';
        return $false
    }

    $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$Name"
    try {

        $startSnapshot=Get-RegistrySnapshot -Path $regPath -Name 'Start'
        if(-not[bool]$startSnapshot.Exists-or[string]$startSnapshot.Kind-ine'DWord'){
            throw 'Start del servicio no es REG_DWORD o no existe.'
        }
        $startValue=[int]$startSnapshot.Value
        if ($startValue -lt 2 -or $startValue -gt 4) {
            throw ("Start={0} no es un modo de servicio de usuario que VSO7 deba modificar." -f $startValue)
        }
        if($startValue-eq4-and$serviceStatus-eq'Running'){
            throw 'El servicio esta Running aunque Start=Disabled; VSO7 no puede prometer restaurar de forma exacta ese estado transitorio y se niega a modificarlo.'
        }

        $delayedSnapshot=Get-RegistrySnapshot -Path $regPath -Name 'DelayedAutoStart'
        if([bool]$delayedSnapshot.Exists-and[string]$delayedSnapshot.Kind-ine'DWord'){
            throw 'DelayedAutoStart del servicio existe pero no es REG_DWORD.'
        }
        $delayedExists=[bool]$delayedSnapshot.Exists
        $delayedValue=if($delayedExists){
            [int]$delayedSnapshot.Value
        }else{
            $null
        }

        $script:ExtremeState.Services += [pscustomobject]@{

            TweakId = $TweakId;
            Name = $Name;
            StartValue = $startValue
            DelayedAutoStartExists = $delayedExists;
            DelayedAutoStart = $delayedValue
            WasRunning = ($serviceStatus -eq 'Running');
            AppliedStartValue = 4
            AppliedDelayedAutoStartExists = $false;
            AppliedDelayedAutoStart = $null;
            Status = 'Pending'

        }
        Save-ExtremeState
        return $true

    } catch {

        Write-VSO7Log ("No se pudo respaldar el servicio {0}: {1}" -f $Name,$_.Exception.Message) 'ERROR'
        return $false

    }

}

function Disable-ExtremeService {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [Parameter(Mandatory=$true)][string]$Name
    )

    $existingBefore=@($script:ExtremeState.Services|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Name-ieq$Name
    })
    if($existingBefore.Count-gt0){
        throw ("Ya existe estado EXTREMO para el servicio {0}; no se inicia una segunda mutacion."-f$Name)
    }
    if (-not (Backup-ExtremeService -TweakId $TweakId -Name $Name)) {

        throw ("No se pudo crear un backup fiable del servicio {0}." -f $Name)

    }

    $owned=@($script:ExtremeState.Services|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Name-ieq$Name
    }|Select-Object -First 1)
    if($owned.Count-ne1){
        throw 'Se perdio el estado pendiente del servicio antes de revalidar.'
    }
    $regPath="HKLM:\SYSTEM\CurrentControlSet\Services\$Name"
    try{

        $statusNow=Get-VSO7ServiceStatusVSO -Name $Name
        $startNowSnap=Get-RegistrySnapshot -Path $regPath -Name 'Start'
        if(-not[bool]$startNowSnap.Exists-or[string]$startNowSnap.Kind-ine'DWord'){
            throw 'Start cambio de tipo/desaparecio durante revalidacion del servicio.'
        }
        $startNow=[int]$startNowSnap.Value
        $delayedNow=Get-RegistrySnapshot -Path $regPath -Name 'DelayedAutoStart'
        if([bool]$delayedNow.Exists-and[string]$delayedNow.Kind-ine'DWord'){
            throw 'DelayedAutoStart cambio a un tipo no DWORD durante revalidacion.'
        }
        $expectedState=if([bool]$owned[0].WasRunning){
            'Running'
        }else{
            'Stopped'
        }
        $baselineOk=([string]$statusNow-ieq$expectedState)-and($startNow-eq[int]$owned[0].StartValue)-and([bool]$delayedNow.Exists-eq[bool]$owned[0].DelayedAutoStartExists)
        if($baselineOk-and[bool]$delayedNow.Exists){
            $baselineOk=([int]$delayedNow.Value-eq[int]$owned[0].DelayedAutoStart)
        }
        if(-not$baselineOk){

            $script:ExtremeState.Services=@($script:ExtremeState.Services|Where-Object{
                -not($_.TweakId-ieq$TweakId-and$_.Name-ieq$Name)
            })
            Save-ExtremeState
            throw ("El servicio {0} cambio entre snapshot y mutacion; VSO7 retiro su Pending sin tocarlo."-f$Name)

        }

    }catch{

        if(@($script:ExtremeState.Services|Where-Object{
            $_.TweakId-ieq$TweakId-and$_.Name-ieq$Name
        }).Count-gt0 -and $_.Exception.Message -notlike 'El servicio * cambio entre snapshot*'){

            $script:ExtremeState.Services=@($script:ExtremeState.Services|Where-Object{
                -not($_.TweakId-ieq$TweakId-and$_.Name-ieq$Name)
            })
            Save-ExtremeState

        }
        throw

    }

    Set-Service -Name $Name -StartupType Disabled -ErrorAction Stop
    try {

        Stop-Service -Name $Name -Force -ErrorAction Stop

    } catch {

        Write-VSO7Log ("{0} quedo deshabilitado para el proximo inicio, pero Stop-Service devolvio error: {1}" -f $Name,$_.Exception.Message) 'WARN'

    }

    # No declaramos Applied solo porque Start=4: el objetivo del tweak incluye detener el
    # servicio en esta sesion. Algunos ServiceController pueden tardar unos instantes en
    # abandonar Stop Pending, asi que esperamos de forma acotada y fallamos cerrado si
    # sigue activo/transitorio. El estado permanece Pending para Recovery.
    $appliedServiceStatus=$null
    for($waitIndex=0;$waitIndex-lt25;$waitIndex++){

        $appliedServiceStatus=Get-VSO7ServiceStatusVSO -Name $Name
        if($appliedServiceStatus-ieq'Stopped'){
            break
        }
        Start-Sleep -Milliseconds 200

    }
    if($appliedServiceStatus-ine'Stopped'){

        throw ("El servicio {0} no quedo Stopped tras deshabilitarlo (estado={1}); no se marca Applied."-f$Name,$appliedServiceStatus)

    }

    $startNowSnapshot=Get-RegistrySnapshot -Path $regPath -Name 'Start'
    if(-not[bool]$startNowSnapshot.Exists-or[string]$startNowSnapshot.Kind-ine'DWord'){
        throw ("Start de {0} no quedo como REG_DWORD tras deshabilitar."-f$Name)
    }
    $startNow=[int]$startNowSnapshot.Value
    if ($startNow -ne 4) {
        throw ("No se pudo verificar Start=4 para {0}." -f $Name)
    }
    $appliedDelayedSnapshot=Get-RegistrySnapshot -Path $regPath -Name 'DelayedAutoStart'
    if([bool]$appliedDelayedSnapshot.Exists-and[string]$appliedDelayedSnapshot.Kind-ine'DWord'){
        throw ("DelayedAutoStart de {0} cambio a tipo no DWORD durante la aplicacion."-f$Name)
    }
    $appliedDelayedExists=[bool]$appliedDelayedSnapshot.Exists
    $appliedDelayed=if($appliedDelayedExists){
        [int]$appliedDelayedSnapshot.Value
    }else{
        $null
    }
    $owned=@($script:ExtremeState.Services|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Name-ieq$Name
    }|Select-Object -First 1)
    if($owned.Count-ne1){
        throw 'Se perdio el estado pendiente del servicio.'
    }
    $owned[0].AppliedDelayedAutoStartExists=[bool]$appliedDelayedExists
    $owned[0].AppliedDelayedAutoStart=$appliedDelayed
    $owned[0].Status='Applied'
    Save-ExtremeState
    Write-VSO7Log ("EXTREMO [{0}] Servicio deshabilitado/verificado: {1}" -f $TweakId,$Name) 'CHANGE'

}

function Restore-ExtremeServicesForTweak {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    $ok=$true
    foreach($entry in @($script:ExtremeState.Services|Where-Object{
        $_.TweakId-eq$TweakId
    })){

        try{

            $serviceStatus=Get-VSO7ServiceStatusVSO -Name ([string]$entry.Name)
            if($null-eq$serviceStatus){
                Write-VSO7Log ("Servicio {0} ya no existe; se libera ownership sin recrearlo."-f$entry.Name) 'WARN';
                continue
            }
            $regPath="HKLM:\SYSTEM\CurrentControlSet\Services\$($entry.Name)"
            $startSnapshot=Get-RegistrySnapshot -Path $regPath -Name 'Start'
            if(-not[bool]$startSnapshot.Exists-or[string]$startSnapshot.Kind-ine'DWord'){
                throw 'Start del servicio no existe o no es REG_DWORD.'
            }
            $delayedSnapshot=Get-RegistrySnapshot -Path $regPath -Name 'DelayedAutoStart'
            if([bool]$delayedSnapshot.Exists-and[string]$delayedSnapshot.Kind-ine'DWord'){
                throw 'DelayedAutoStart existe pero no es REG_DWORD.'
            }
            $currentStart=[int]$startSnapshot.Value;
            $startValue=[int]$entry.StartValue
            $currentDelayedExists=[bool]$delayedSnapshot.Exists;
            $currentDelayed=if($currentDelayedExists){
                [int]$delayedSnapshot.Value
            }else{
                $null
            }
            $baselineDelayed=($currentDelayedExists-eq[bool]$entry.DelayedAutoStartExists);
            if($baselineDelayed-and$currentDelayedExists){
                $baselineDelayed=([int]$currentDelayed-eq[int]$entry.DelayedAutoStart)
            }
            $baselineStart=($currentStart-eq$startValue)
            $baselineService=if([bool]$entry.WasRunning){
                $serviceStatus-ieq'Running'
            }else{
                $serviceStatus-ieq'Stopped'
            }
            if($baselineStart-and$baselineDelayed-and$baselineService){
                Write-VSO7Log ("Servicio {0} ya coincide completamente con su baseline; se libera ownership."-f$entry.Name) 'INFO';
                continue
            }

            if([string]$entry.Status-ieq'Pending'){

                # La secuencia de mutacion es determinista: primero Set-Service -> Start=4 y
                # despues Stop-Service. Si Start sigue exactamente en nuestro valor objetivo
                # Y DelayedAutoStart continua intacto respecto del baseline, podemos demostrar
                # ownership de la mutacion parcial de Start aun si hubo un crash antes de marcar
                # Applied. Cualquier otra combinacion sigue siendo ambigua y se conserva.
                $pendingOwnsStart=($currentStart-eq[int]$entry.AppliedStartValue)-and$baselineDelayed
                if(-not$pendingOwnsStart){

                    $ok=$false
                    Write-VSO7Log ("Servicio {0} Pending ambiguo: no se puede demostrar ownership exacto de la mutacion parcial; se conserva evidencia sin sobrescribir."-f$entry.Name) 'ERROR'
                    continue

                }
                $startupType=switch($startValue){
                    2{
                        'Automatic'
                    }3{
                        'Manual'
                    }4{
                        'Disabled'
                    }default{
                        throw ("Start original no soportado: {0}"-f$startValue)
                    }
                }
                Set-Service -Name ([string]$entry.Name) -StartupType $startupType -ErrorAction Stop
                if([bool]$entry.WasRunning){

                    $pendingStatus=Get-VSO7ServiceStatusVSO -Name ([string]$entry.Name)
                    if($pendingStatus-ine'Running'){
                        Start-Service -Name ([string]$entry.Name) -ErrorAction Stop
                    }

                }
                $pendingCheck=Get-RegistrySnapshot -Path $regPath -Name 'Start'
                if(-not[bool]$pendingCheck.Exists-or[string]$pendingCheck.Kind-ine'DWord'-or[int]$pendingCheck.Value-ne$startValue){
                    throw 'Start Pending del servicio no volvio al baseline.'
                }
                if([bool]$entry.WasRunning-and((Get-VSO7ServiceStatusVSO -Name ([string]$entry.Name))-ine'Running')){
                    throw 'El servicio Pending originalmente activo no pudo reanudarse.'
                }
                Write-VSO7Log ("Servicio Pending restaurado desde mutacion parcial demostrable: {0}"-f$entry.Name) 'CHANGE'
                continue

            }

            $restoreStart=($currentStart-eq[int]$entry.AppliedStartValue)
            if($restoreStart){

                $startupType=switch($startValue){
                    2{
                        'Automatic'
                    }3{
                        'Manual'
                    }4{
                        'Disabled'
                    }default{
                        throw ("Start original no soportado: {0}"-f$startValue)
                    }
                }
                Set-Service -Name ([string]$entry.Name) -StartupType $startupType -ErrorAction Stop

            }elseif(-not$baselineStart){
                Write-VSO7Log ("No se restaura Start del servicio {0}: valor externo detectado ({1}); se libera ownership de Start."-f$entry.Name,$currentStart) 'WARN'
            }

            $matchesAppliedDelayed=($currentDelayedExists-eq[bool]$entry.AppliedDelayedAutoStartExists)
            if($matchesAppliedDelayed-and$currentDelayedExists){
                $matchesAppliedDelayed=([int]$currentDelayed-eq[int]$entry.AppliedDelayedAutoStart)
            }
            $restoreDelayed=([string]$entry.Status-ieq'Applied'-and$matchesAppliedDelayed)
            if($restoreDelayed-and-not$baselineDelayed){

                if([bool]$entry.DelayedAutoStartExists){
                    New-ItemProperty -LiteralPath $regPath -Name DelayedAutoStart -Value ([int]$entry.DelayedAutoStart) -PropertyType DWord -Force -ErrorAction Stop|Out-Null
                }
                else{
                    $beforeDelete=Get-RegistrySnapshot -Path $regPath -Name 'DelayedAutoStart';
                    if([bool]$beforeDelete.Exists){
                        Remove-ItemProperty -LiteralPath $regPath -Name DelayedAutoStart -ErrorAction Stop
                    }
                }

            }elseif(-not$baselineDelayed){
                Write-VSO7Log ("No se restaura DelayedAutoStart de {0}: cambio externo detectado tras Applied."-f$entry.Name) 'WARN'
            }

            if([bool]$entry.WasRunning){

                $currentStatus=Get-VSO7ServiceStatusVSO -Name ([string]$entry.Name)
                if($currentStatus-ne'Running' -and ($restoreStart-or$baselineStart)){
                    Start-Service -Name ([string]$entry.Name) -ErrorAction Stop
                }

            }
            $checkStart=Get-RegistrySnapshot -Path $regPath -Name 'Start'
            if($restoreStart-and(-not[bool]$checkStart.Exists-or[string]$checkStart.Kind-ine'DWord'-or[int]$checkStart.Value-ne$startValue)){
                throw 'Start del servicio no coincide con baseline.'
            }
            if($restoreDelayed){
                $checkDelayed=Get-RegistrySnapshot -Path $regPath -Name 'DelayedAutoStart';
                if([bool]$checkDelayed.Exists-and[string]$checkDelayed.Kind-ine'DWord'){
                    throw 'DelayedAutoStart final no es REG_DWORD.'
                };
                if([bool]$checkDelayed.Exists-ne[bool]$entry.DelayedAutoStartExists){
                    throw 'DelayedAutoStart existencia no coincide.'
                };
                if([bool]$checkDelayed.Exists-and[int]$checkDelayed.Value-ne[int]$entry.DelayedAutoStart){
                    throw 'DelayedAutoStart no coincide.'
                }
            }
            if([bool]$entry.WasRunning-and($restoreStart-or$baselineStart)-and((Get-VSO7ServiceStatusVSO -Name ([string]$entry.Name))-ne'Running')){
                throw 'El servicio originalmente activo no pudo reanudarse.'
            }
            if($restoreStart-or$restoreDelayed){
                Write-VSO7Log ("Servicio restaurado/verificado con ownership: {0}"-f$entry.Name) 'CHANGE'
            }

        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar servicio {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
        }

    }
    return $ok

}

function Backup-ExtremeFeature {

    param([Parameter(Mandatory=$true)][string]$TweakId,[Parameter(Mandatory=$true)][string]$Name)
    $existing=@($script:ExtremeState.Features|Where-Object{
        $_.TweakId-eq$TweakId-and$_.Name-eq$Name
    }|Select-Object -First 1);
    if($existing.Count){
        return $existing[0]
    }
    try{

        $feature=Dism\Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop
        if($null-eq$feature){
            return $null
        }
        $state=[string]$feature.State
        if(-not(Test-VSO7ExtremeFeatureStateName $state)){
            throw ("{0} devolvio un estado DISM no reconocido ({1}); VSO7 falla cerrado."-f$Name,$state)
        }
        if(-not(Test-VSO7ExtremeFeatureStableStateVSO -State $state)){
            throw ("{0} no esta en un baseline estable modificable ({1}); reinicia/repara servicing antes de usar EXTREMO."-f$Name,$state)
        }
        $entry=[pscustomobject]@{
            TweakId=$TweakId;
            Name=$Name;
            State=$state;
            AppliedState=$null;
            Status='Pending'
        };
        $script:ExtremeState.Features+=$entry;
        Save-ExtremeState;
        return $entry

    }catch{
        Write-VSO7Log ("No se pudo respaldar la caracteristica {0}: {1}"-f$Name,$_.Exception.Message) 'ERROR';
        return $null
    }

}

function Disable-ExtremeFeature {

    param([Parameter(Mandatory=$true)][string]$TweakId,[Parameter(Mandatory=$true)][string]$Name)
    [void](Assert-VSO7NoNativeOptionalFeatureOwnershipVSO -Name $Name)
    $existingBefore=@($script:ExtremeState.Features|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Name-ieq$Name
    })
    if($existingBefore.Count-gt0){
        throw ("Ya existe estado EXTREMO para Feature {0}; no se inicia una segunda mutacion."-f$Name)
    }
    $backup=Backup-ExtremeFeature -TweakId $TweakId -Name $Name
    if($null-eq$backup){
        throw ("No se pudo crear un backup fiable de la caracteristica {0}."-f$Name)
    }

    try{
        $feature=Dism\Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop
    }
    catch{

        $reason=$_.Exception.Message
        $script:ExtremeState.Features=@($script:ExtremeState.Features|Where-Object{
            -not($_.TweakId-ieq$TweakId-and$_.Name-ieq$Name)
        })
        Save-ExtremeState
        throw ("No se pudo revalidar Feature antes de mutar; VSO7 retiro su Pending: {0}"-f$reason)

    }
    if([string]$feature.State-ine[string]$backup.State-or-not(Test-VSO7ExtremeFeatureStableStateVSO -State ([string]$feature.State))){

        $script:ExtremeState.Features=@($script:ExtremeState.Features|Where-Object{
            -not($_.TweakId-ieq$TweakId-and$_.Name-ieq$Name)
        })
        Save-ExtremeState
        throw ("Feature {0} cambio/entro en estado transitorio entre snapshot y mutacion; VSO7 retiro su Pending sin tocarla."-f$Name)

    }

    $baselineClass=Get-VSO7ExtremeFeatureStateClassVSO -State ([string]$feature.State)
    if($baselineClass-eq'Enabled'){

        Dism\Disable-WindowsOptionalFeature -Online -FeatureName $Name -NoRestart -ErrorAction Stop|Out-Null
        $after=Dism\Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop
        $afterClass=Get-VSO7ExtremeFeatureStateClassVSO -State ([string]$after.State)
        if(@('Disabled','DisablePending')-notcontains$afterClass){
            throw ("{0} no quedo deshabilitada ni pendiente de deshabilitar tras DISM: {1}"-f$Name,$after.State)
        }
        $backup.AppliedState=[string]$after.State;
        $backup.Status='Applied';
        Save-ExtremeState
        if($afterClass-eq'DisablePending'){

            Write-VSO7Log ("EXTREMO [{0}] Feature deshabilitada pendiente de reinicio: {1} -> {2}. Se conserva ownership."-f$TweakId,$Name,$after.State) 'WARN'

        }else{

            Write-VSO7Log ("EXTREMO [{0}] Caracteristica deshabilitada: {1} -> {2}"-f$TweakId,$Name,$after.State) 'CHANGE'

        }

    }elseif($baselineClass-eq'Disabled'){

        # Ya estaba deshabilitada: no se ha ejercido mutacion, pero se conserva la evidencia
        # hasta que el tweak completo termine para mantener consistencia transaccional.
        $backup.AppliedState=[string]$feature.State;
        $backup.Status='Applied';
        Save-ExtremeState
        Write-VSO7Log ("{0} ya estaba en estado {1}; no fue necesario cambiarla."-f$Name,$feature.State)

    }else{

        throw ("Estado baseline de Feature no soportado: {0}"-f$feature.State)

    }

}

function Restore-ExtremeFeaturesForTweak {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    $ok=$true
    foreach($entry in @($script:ExtremeState.Features|Where-Object{
        $_.TweakId-eq$TweakId
    })){

        try{

            $current=Dism\Get-WindowsOptionalFeature -Online -FeatureName ([string]$entry.Name) -ErrorAction Stop
            $currentState=[string]$current.State;
            $original=[string]$entry.State
            if($currentState-ieq$original){
                Write-VSO7Log ("Feature {0} ya coincide exactamente con baseline; se libera ownership."-f$entry.Name) 'INFO';
                continue
            }

            $status=[string]$entry.Status
            if($status-ieq'RestorePending'){

                if(Test-VSO7ExtremeFeatureRestorePendingForBaselineVSO -CurrentState $currentState -BaselineState $original){

                    $ok=$false
                    Write-VSO7Log ("Feature {0} sigue pendiente de completar rollback ({1}); reinicia Windows y reintenta Recovery. Se conserva evidencia."-f$entry.Name,$currentState) 'WARN'
                    continue

                }
                # Si servicing progreso hasta un estado estable pero no EXACTAMENTE al baseline,
                # no se adivina: puede haber cambio externo o diferencia de payload.
                $ok=$false
                Write-VSO7Log ("Feature {0} tenia RestorePending pero ahora esta en {1}, distinto del baseline exacto {2}; se conserva evidencia para revision."-f$entry.Name,$currentState,$original) 'ERROR'
                continue

            }

            if($status-ieq'Pending'){

                $pendingOriginalClass=Get-VSO7ExtremeFeatureStateClassVSO -State $original
                if($pendingOriginalClass-eq'Disabled'){

                    # VSO7 nunca habilita una Feature durante la aplicacion de este tweak. Si
                    # el baseline ya era Disabled y ahora difiere, el cambio no puede ser nuestro.
                    Write-VSO7Log ("Feature {0} Pending con baseline deshabilitado cambio externamente ({1} -> {2}); se libera ownership sin sobrescribir."-f$entry.Name,$original,$currentState) 'WARN'
                    continue

                }
                if(Test-VSO7ExtremeFeaturePendingDisableOwnedVSO -CurrentState $currentState -BaselineState $original){

                    # Crash despues de DISM y antes de grabar Applied: el estado observado solo
                    # puede proceder de la desactivacion sin -Remove que VSO habia preparado.
                    # Persistimos primero esa observacion para que otro crash durante el rollback
                    # siga siendo recuperable de forma idempotente.
                    $entry.AppliedState=$currentState
                    $entry.Status='Applied'
                    Save-ExtremeState
                    $status='Applied'
                    Write-VSO7Log ("Feature {0} Pending reconciliada como desactivacion propia demostrable ({1})."-f$entry.Name,$currentState) 'WARN'

                }else{

                    $ok=$false
                    Write-VSO7Log ("Feature {0} Pending ambigua ({1}); VSO7 no puede demostrar si llego a mutarla y conserva evidencia."-f$entry.Name,$currentState) 'ERROR'
                    continue

                }

            }

            if($status-ine'Applied'){
                throw ("Status Feature inesperado: {0}"-f$status)
            }
            $originalClass=Get-VSO7ExtremeFeatureStateClassVSO -State $original
            if($originalClass-eq'Enabled'){

                if(-not(Test-VSO7ExtremeFeatureAppliedDisableOwnedVSO -CurrentState $currentState -RecordedAppliedState ([string]$entry.AppliedState))){

                    Write-VSO7Log ("No se restaura Feature {0}: estado externo detectado ({1}) tras Applied; se libera ownership sin sobrescribir."-f$entry.Name,$currentState) 'WARN'
                    continue

                }
                Dism\Enable-WindowsOptionalFeature -Online -FeatureName ([string]$entry.Name) -NoRestart -ErrorAction Stop|Out-Null

            }elseif($originalClass-eq'Disabled'){

                # VSO7 solo deshabilita Features; un baseline Disabled no requirio mutacion.
                # Si ya no coincide exactamente, no intentamos reconstruir payload/tipo de Disabled.
                Write-VSO7Log ("No se restaura Feature {0}: baseline era {1} pero Windows esta en {2}; VSO7 no ejercio una habilitacion y no pisara el cambio externo."-f$entry.Name,$original,$currentState) 'WARN'
                continue

            }else{
                throw ("Estado original no soportado: {0}"-f$original)
            }

            $after=Dism\Get-WindowsOptionalFeature -Online -FeatureName ([string]$entry.Name) -ErrorAction Stop
            $afterState=[string]$after.State
            if($afterState-ieq$original){

                Write-VSO7Log ("Caracteristica restaurada/verificada con ownership: {0} -> {1}"-f$entry.Name,$afterState) 'CHANGE'
                continue

            }
            if(Test-VSO7ExtremeFeatureRestorePendingForBaselineVSO -CurrentState $afterState -BaselineState $original){

                $entry.Status='RestorePending'
                $entry.AppliedState=$afterState
                Save-ExtremeState
                $ok=$false
                Write-VSO7Log ("Rollback de Feature {0} aceptado por DISM pero pendiente de reinicio ({1}); se conserva evidencia hasta observar baseline estable {2}."-f$entry.Name,$afterState,$original) 'WARN'
                continue

            }
            throw ("Feature {0} no volvio al baseline exacto ni quedo pendiente hacia el: {1} (baseline {2})."-f$entry.Name,$afterState,$original)

        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
        }

    }
    return $ok

}

function Get-HibernationEnabledVSO {

    $snap=Get-RegistrySnapshot -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -Name 'HibernateEnabled'
    if([bool]$snap.Exists){

        if([string]$snap.Kind-ine'DWord'){
            throw 'HibernateEnabled no es REG_DWORD.'
        }
        return ([int]$snap.Value-ne0)

    }
    # Solo si el valor realmente no existe se acepta hiberfil.sys como segunda
    # evidencia. Un fallo de lectura de Registry ya habria lanzado excepcion arriba.
    $systemDrive=if($script:SystemDrive){
        [string]$script:SystemDrive
    }else{
        [IO.Path]::GetPathRoot([string]$script:WindowsRoot).TrimEnd('\')
    }
    try{
        return (Test-Path -LiteralPath ($systemDrive.TrimEnd('\')+'\hiberfil.sys') -ErrorAction Stop)
    }catch{
        throw 'No se pudo determinar de forma fiable si la hibernacion esta habilitada.'
    }

}

function Get-HibernationStateSnapshotVSO {

    $powerPath='HKLM:\SYSTEM\CurrentControlSet\Control\Power'
    $size=Get-RegistrySnapshot -Path $powerPath -Name 'HiberFileSizePercent'
    $type=Get-RegistrySnapshot -Path $powerPath -Name 'HiberFileType'
    $sizeValue=$null;
    $typeValue=$null
    if([bool]$size.Exists){

        if([string]$size.Kind-ine'DWord'){
            throw 'HiberFileSizePercent no es REG_DWORD.'
        }
        $sizeValue=[int]$size.Value
        if($sizeValue-lt0-or$sizeValue-gt100){
            throw 'HiberFileSizePercent fuera de rango.'
        }

    }
    if([bool]$type.Exists){

        if([string]$type.Kind-ine'DWord'){
            throw 'HiberFileType no es REG_DWORD.'
        }
        $typeValue=[int]$type.Value
        if($typeValue-lt0-or$typeValue-gt2){
            throw 'HiberFileType fuera de los valores soportados por VSO7.'
        }

    }
    return [pscustomobject]@{

        Enabled=[bool](Get-HibernationEnabledVSO)
        SizePercentExists=[bool]$size.Exists
        SizePercent=$sizeValue
        TypeExists=[bool]$type.Exists
        Type=$typeValue

    }

}

function Test-HibernationRegistryEvidenceVSO {

    param(
        [Parameter(Mandatory=$true)]$Current,
        [Parameter(Mandatory=$true)][bool]$ExpectedEnabled,
        [Parameter(Mandatory=$true)][bool]$ExpectedSizeExists,
        $ExpectedSize,
        [Parameter(Mandatory=$true)][bool]$ExpectedTypeExists,
        $ExpectedType
    )
    if([bool]$Current.Enabled-ne$ExpectedEnabled){
        return $false
    }
    if([bool]$Current.SizePercentExists-ne$ExpectedSizeExists){
        return $false
    }
    if($ExpectedSizeExists-and[int]$Current.SizePercent-ne[int]$ExpectedSize){
        return $false
    }
    if([bool]$Current.TypeExists-ne$ExpectedTypeExists){
        return $false
    }
    if($ExpectedTypeExists-and[int]$Current.Type-ne[int]$ExpectedType){
        return $false
    }
    return $true

}

function Disable-HibernationExtreme {

    param([Parameter(Mandatory=$true)][string]$TweakId)

    if($null-ne$script:ExtremeState.Hibernation){
        throw 'Ya existe estado de hibernacion EXTREMO; no se inicia otra mutacion hasta revertirlo.'
    }
    $baseline=Get-HibernationStateSnapshotVSO
    $script:ExtremeState.Hibernation = [pscustomobject]@{

        TweakId = $TweakId
        Enabled = [bool]$baseline.Enabled
        SizePercentExists = [bool]$baseline.SizePercentExists
        SizePercent = $baseline.SizePercent
        TypeExists = [bool]$baseline.TypeExists
        Type = $baseline.Type
        AppliedEnabled = $false
        AppliedSizePercentExists = $false
        AppliedSizePercent = $null
        AppliedTypeExists = $false
        AppliedType = $null
        Status = 'Pending'

    }
    Save-ExtremeState

    try{
        $recheck=Get-HibernationStateSnapshotVSO
    }
    catch{

        $reason=$_.Exception.Message
        $script:ExtremeState.Hibernation=$null
        Save-ExtremeState
        throw ("No se pudo revalidar hibernacion antes de mutar; VSO7 retiro su Pending: {0}"-f$reason)

    }
    if(-not(Test-HibernationRegistryEvidenceVSO -Current $recheck -ExpectedEnabled ([bool]$baseline.Enabled) -ExpectedSizeExists ([bool]$baseline.SizePercentExists) -ExpectedSize $baseline.SizePercent -ExpectedTypeExists ([bool]$baseline.TypeExists) -ExpectedType $baseline.Type)){

        $script:ExtremeState.Hibernation=$null
        Save-ExtremeState
        throw 'La hibernacion cambio entre snapshot y mutacion; VSO7 retiro su Pending sin ejecutar powercfg.'

    }

    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','off')
    $applied=Get-HibernationStateSnapshotVSO
    if([bool]$applied.Enabled){
        throw 'La hibernacion parece seguir habilitada tras powercfg /hibernate off.'
    }
    $script:ExtremeState.Hibernation.AppliedEnabled=$false
    $script:ExtremeState.Hibernation.AppliedSizePercentExists=[bool]$applied.SizePercentExists
    $script:ExtremeState.Hibernation.AppliedSizePercent=$applied.SizePercent
    $script:ExtremeState.Hibernation.AppliedTypeExists=[bool]$applied.TypeExists
    $script:ExtremeState.Hibernation.AppliedType=$applied.Type
    $script:ExtremeState.Hibernation.Status='Applied'
    Save-ExtremeState
    Write-VSO7Log 'Hibernacion deshabilitada y estado aplicado verificado.' 'CHANGE'

}

function Restore-ExtremeHibernationForTweakVSO {

    param([Parameter(Mandatory=$true)][string]$TweakId)

    $entry=$script:ExtremeState.Hibernation
    if($null-eq$entry-or[string]$entry.TweakId-ne$TweakId){
        return $true
    }

    try{

        $current=Get-HibernationStateSnapshotVSO
        $isBaseline=Test-HibernationRegistryEvidenceVSO -Current $current -ExpectedEnabled ([bool]$entry.Enabled) -ExpectedSizeExists ([bool]$entry.SizePercentExists) -ExpectedSize $entry.SizePercent -ExpectedTypeExists ([bool]$entry.TypeExists) -ExpectedType $entry.Type
        if($isBaseline){

            Write-VSO7Log 'Hibernacion ya coincide exactamente con el baseline; se libera ownership.' 'INFO'
            return $true

        }

        $owned=$false
        if([string]$entry.Status-ieq'Applied'){

            $owned=Test-HibernationRegistryEvidenceVSO -Current $current -ExpectedEnabled ([bool]$entry.AppliedEnabled) -ExpectedSizeExists ([bool]$entry.AppliedSizePercentExists) -ExpectedSize $entry.AppliedSizePercent -ExpectedTypeExists ([bool]$entry.AppliedTypeExists) -ExpectedType $entry.AppliedType

        }elseif([string]$entry.Status-ieq'Pending'){

            # En Pending solo consideramos nuestro el cambio si powercfg llego a apagar
            # hibernacion sin alterar los metadatos baseline de tamano/tipo. Cualquier
            # otra combinacion se trata como modificacion externa y no se pisa.
            $owned=(-not[bool]$current.Enabled)-and([bool]$current.SizePercentExists-eq[bool]$entry.SizePercentExists)-and([bool]$current.TypeExists-eq[bool]$entry.TypeExists)
            if($owned-and[bool]$entry.SizePercentExists){
                $owned=([int]$current.SizePercent-eq[int]$entry.SizePercent)
            }
            if($owned-and[bool]$entry.TypeExists){
                $owned=([int]$current.Type-eq[int]$entry.Type)
            }

        }
        if(-not$owned){

            if([string]$entry.Status-ieq'Pending'){

                Write-VSO7Log 'Hibernacion Pending ambigua: el estado no coincide con baseline ni con una mutacion demostrable; se conserva evidencia.' 'ERROR'
                return $false

            }
            Write-VSO7Log 'No se restaura hibernacion: tamano/tipo/estado cambiaron externamente tras Applied; se libera ownership sin sobrescribir.' 'WARN'
            return $true

        }

        if(-not[bool]$entry.Enabled){

            Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','off')

        }else{

            Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','on')
            if([bool]$entry.TypeExists){

                $type=[int]$entry.Type
                if($type-eq1){

                    # Microsoft exige que el SO vuelva a gestionar el tamano antes de
                    # seleccionar el hiberfile reducido.
                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/size','0')
                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/type','reduced')

                }elseif($type-eq2){

                    if([bool]$entry.SizePercentExists-and$null-ne$entry.SizePercent){

                        $pct=[int]$entry.SizePercent
                        if($pct-eq0){
                            Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/size','0')
                        }
                        elseif($pct-ge40-and$pct-le100){
                            Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/size',[string]$pct)
                        }
                        else{
                            throw 'Baseline de hiberfile full con tamano incompatible; rollback automatico denegado.'
                        }

                    }
                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/type','full')

                }else{
                    throw 'Baseline HiberFileType no restaurable automaticamente.'
                }

            }elseif([bool]$entry.SizePercentExists-and$null-ne$entry.SizePercent){

                # Sin HiberFileType persistido solo usamos la semantica documentada por
                # Microsoft sobre el porcentaje; la verificacion exacta posterior decide
                # si Windows reconstruyo realmente el baseline.
                $pct=[int]$entry.SizePercent
                if($pct-ge40-and$pct-le100){
                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/size',[string]$pct)
                }
                elseif($pct-gt0-and$pct-lt40){

                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/size','0')
                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/hibernate','/type','reduced')

                }

            }

        }

        $after=Get-HibernationStateSnapshotVSO
        if(-not(Test-HibernationRegistryEvidenceVSO -Current $after -ExpectedEnabled ([bool]$entry.Enabled) -ExpectedSizeExists ([bool]$entry.SizePercentExists) -ExpectedSize $entry.SizePercent -ExpectedTypeExists ([bool]$entry.TypeExists) -ExpectedType $entry.Type)){

            throw 'Hibernacion no coincide exactamente con Enabled/HiberFileSizePercent/HiberFileType del baseline tras rollback.'

        }
        Write-VSO7Log 'Hibernacion restaurada y verificada exactamente con ownership.' 'CHANGE'
        return $true

    }catch{

        Write-VSO7Log ("No se pudo restaurar hibernacion: {0}"-f$_.Exception.Message) 'ERROR'
        return $false

    }

}

function Get-PowerAliasGuidVSO {

    param([Parameter(Mandatory=$true)][string]$Alias)

    # Solo resolvemos los aliases que VSO7 usa realmente. Evita depender del formato/localizacion
    # de `powercfg /aliases` y mantiene una allowlist revisable para Windows PowerShell 5.1.
    $map=@{

        'SUB_USB'        = '2a737441-1930-4402-8d77-b2bebba308a3'
        'USBSELECTIVE'   = '48e6b7a6-50f5-4782-a5d4-53bb8f07e226'
        'SUB_PCIEXPRESS' = '501a4d13-42af-4429-9fd1-a8218c268e20'
        'ASPM'           = 'ee12f906-d277-404b-b6da-e5fa1a576df5'
        'SUB_PROCESSOR'  = '54533251-82be-4824-96c1-47b60b740d00'
        'PROCTHROTTLEMIN'= '893dee8e-2bef-41e0-89c6-b55d0929964c'
        'PROCTHROTTLEMAX'= 'bc5038f7-23e0-4960-96da-33abaf5935ec'
        'PERFBOOSTMODE'   = 'be337238-0d82-4146-a960-4f3749d470c7'
        'PERFEPP'         = '36687f9e-e3a5-4dbf-b1dc-15eb381c6863'
        'SYSCOOLPOL'      = '94d3a615-a899-4ac5-ae2b-e4d8f634367f'

    }
    $key=[string]$Alias
    if([string]::IsNullOrWhiteSpace($key)){
        return $null
    }
    $key=$key.ToUpperInvariant()
    if(-not$map.ContainsKey($key)){
        return $null
    }
    return ([string]$map[$key]).ToLowerInvariant()

}

function Initialize-VSO7PowerReadApiVSO {

    if($null-ne('VSO7.PowerReadNative' -as [type])){
        return
    }
    $source=@"
using System;
using System.Runtime.InteropServices;
namespace VSO7 {
    public static class PowerReadNative {
        [DllImport("powrprof.dll", SetLastError=false)]
        public static extern UInt32 PowerReadACValueIndex(IntPtr RootPowerKey, ref Guid SchemeGuid, ref Guid SubGroupOfPowerSettingsGuid, ref Guid PowerSettingGuid, out UInt32 AcValueIndex);
        [DllImport("powrprof.dll", SetLastError=false)]
        public static extern UInt32 PowerReadDCValueIndex(IntPtr RootPowerKey, ref Guid SchemeGuid, ref Guid SubGroupOfPowerSettingsGuid, ref Guid PowerSettingGuid, out UInt32 DcValueIndex);
    }
}
"@
    Add-Type -TypeDefinition $source -Language CSharp -ErrorAction Stop

}

function Get-VSO7PowerSettingProviderSnapshotVSO {

    param(
        [Parameter(Mandatory=$true)][string]$SubGroupAlias,
        [Parameter(Mandatory=$true)][string]$SettingAlias,
        [AllowNull()][string]$SchemeGuid
    )
    $schemeText=[string]$SchemeGuid
    if([string]::IsNullOrWhiteSpace($schemeText)){
        $schemeText=[string](Get-ActivePowerSchemeGuid)
    }
    if([string]::IsNullOrWhiteSpace($schemeText)-or-not(Test-VSO7PowerSchemeGuid -Value $schemeText)){
        throw 'No se pudo determinar un plan de energia valido.'
    }
    $subText=Get-PowerAliasGuidVSO -Alias $SubGroupAlias
    $settingText=Get-PowerAliasGuidVSO -Alias $SettingAlias
    if([string]::IsNullOrWhiteSpace($subText)-or[string]::IsNullOrWhiteSpace($settingText)){
        throw ('PowerSetting fuera de allowlist: {0}/{1}'-f$SubGroupAlias,$SettingAlias)
    }
    Initialize-VSO7PowerReadApiVSO
    $schemeGuidObj=New-Object Guid $schemeText
    $subGuidObj=New-Object Guid $subText
    $settingGuidObj=New-Object Guid $settingText
    [uint32]$ac=0
    [uint32]$dc=0
    $acRc=[VSO7.PowerReadNative]::PowerReadACValueIndex([IntPtr]::Zero,[ref]$schemeGuidObj,[ref]$subGuidObj,[ref]$settingGuidObj,[ref]$ac)
    $dcRc=[VSO7.PowerReadNative]::PowerReadDCValueIndex([IntPtr]::Zero,[ref]$schemeGuidObj,[ref]$subGuidObj,[ref]$settingGuidObj,[ref]$dc)
    if($acRc-ne0-or$dcRc-ne0){
        throw ('Power API no pudo leer {0}/{1} (AC={2}, DC={3}).'-f$SubGroupAlias,$SettingAlias,$acRc,$dcRc)
    }
    return [pscustomobject]@{
        SchemeGuid=$schemeText.ToLowerInvariant()
        SubGroupAlias=$SubGroupAlias
        SettingAlias=$SettingAlias
        AC=[int64]$ac
        DC=[int64]$dc
        Provider='PowerReadValueIndex'
    }

}

function Backup-ExtremePowerSettingVSO {

    param([Parameter(Mandatory=$true)][string]$TweakId,[Parameter(Mandatory=$true)][string]$SubGroupAlias,[Parameter(Mandatory=$true)][string]$SettingAlias,[Parameter(Mandatory=$true)][int]$AppliedValue)
    $existing=@($script:ExtremeState.PowerSettings|Where-Object{
        $_.TweakId-eq$TweakId-and$_.SubGroupAlias-eq$SubGroupAlias-and$_.SettingAlias-eq$SettingAlias
    }|Select-Object -First 1);
    if($existing.Count){
        return $existing[0]
    }
    $def=@(Get-VSO7ExtremePowerDefinitions|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.SubGroupAlias-ieq$SubGroupAlias-and$_.SettingAlias-ieq$SettingAlias-and[int]$_.AppliedValue-eq$AppliedValue
    });
    if($def.Count-ne1){
        throw 'Power setting EXTREMO fuera de allowlist.'
    }
    $schemeGuid=Get-ActivePowerSchemeGuid;
    if([string]::IsNullOrWhiteSpace($schemeGuid)){
        throw 'No se pudo determinar el plan de energia activo.'
    }
    $subGuid=Get-PowerAliasGuidVSO -Alias $SubGroupAlias;
    $settingGuid=Get-PowerAliasGuidVSO -Alias $SettingAlias;
    if([string]::IsNullOrWhiteSpace($subGuid)-or[string]::IsNullOrWhiteSpace($settingGuid)){
        throw ("PowerSetting fuera de la allowlist GUID de VSO7: {0}/{1}."-f$SubGroupAlias,$SettingAlias)
    }
    $providerSnap=Get-VSO7PowerSettingProviderSnapshotVSO -SubGroupAlias $SubGroupAlias -SettingAlias $SettingAlias -SchemeGuid $schemeGuid
    $entry=[pscustomobject]@{
        TweakId=$TweakId;
        SchemeGuid=$schemeGuid;
        SubGroupAlias=$SubGroupAlias;
        SettingAlias=$SettingAlias;
        AC=[int]$providerSnap.AC;
        DC=[int]$providerSnap.DC;
        AppliedAC=$AppliedValue;
        AppliedDC=$AppliedValue;
        Status='Pending'
    };
    $script:ExtremeState.PowerSettings+=$entry;
    Save-ExtremeState;
    return $entry

}

function Set-ExtremePowerSetting {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [Parameter(Mandatory=$true)][string]$SubGroup,
        [Parameter(Mandatory=$true)][string]$Setting,
        [Parameter(Mandatory=$true)][int]$Value
    )

    $currentOwnershipScheme=[string](Get-ActivePowerSchemeGuid)
    if([string]::IsNullOrWhiteSpace($currentOwnershipScheme)){
        throw 'No se pudo determinar el plan activo para comprobar ownership nativo.'
    }
    [void](Assert-VSO7NoNativePowerOwnershipVSO -SchemeGuid $currentOwnershipScheme -SubGroupAlias $SubGroup -SettingAlias $Setting)
    $existingBefore=@($script:ExtremeState.PowerSettings|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.SubGroupAlias-ieq$SubGroup-and$_.SettingAlias-ieq$Setting
    })
    if($existingBefore.Count-gt0){
        throw 'Ya existe estado EXTREMO para este PowerSetting; no se inicia otra mutacion.'
    }
    $backup = Backup-ExtremePowerSettingVSO -TweakId $TweakId -SubGroupAlias $SubGroup -SettingAlias $Setting -AppliedValue $Value
    $scheme = [string]$backup.SchemeGuid

    try{

        $schemeNow=[string](Get-ActivePowerSchemeGuid)
        $subGuid=Get-PowerAliasGuidVSO -Alias $SubGroup
        $settingGuid=Get-PowerAliasGuidVSO -Alias $Setting
        if([string]::IsNullOrWhiteSpace($subGuid)-or[string]::IsNullOrWhiteSpace($settingGuid)){
            throw 'No se pudieron resolver los GUID allowlisted del PowerSetting antes de la mutacion.'
        }
        $beforeMutation=Get-VSO7PowerSettingProviderSnapshotVSO -SubGroupAlias $SubGroup -SettingAlias $Setting -SchemeGuid $scheme
        if($schemeNow-ine$scheme-or[int]$beforeMutation.AC-ne[int]$backup.AC-or[int]$beforeMutation.DC-ne[int]$backup.DC){
            throw 'El plan o PowerSetting cambio entre snapshot y mutacion.'
        }

    }catch{

        $reason=$_.Exception.Message
        $script:ExtremeState.PowerSettings=@($script:ExtremeState.PowerSettings|Where-Object{
            -not($_.TweakId-ieq$TweakId-and$_.SubGroupAlias-ieq$SubGroup-and$_.SettingAlias-ieq$Setting)
        })
        Save-ExtremeState
        throw ("{0} VSO7 retiro su Pending sin ejecutar powercfg."-f$reason)

    }

    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setacvalueindex',$scheme,$subGuid,$settingGuid,[string]$Value)
    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setdcvalueindex',$scheme,$subGuid,$settingGuid,[string]$Value)

    $afterStored = Get-VSO7PowerSettingProviderSnapshotVSO -SubGroupAlias $SubGroup -SettingAlias $Setting -SchemeGuid $scheme
    if ([int]$afterStored.AC -ne $Value -or [int]$afterStored.DC -ne $Value) {
        throw ("El ajuste de energia {0}/{1} no coincide con el valor solicitado." -f $SubGroup,$Setting)
    }

    # Revalidar ownership del plan justo antes de aplicar. SCHEME_CURRENT es deliberado:
    # si otra aplicacion cambia de plan entre esta comprobacion y powercfg, VSO7 no reactiva
    # a la fuerza `$scheme`; como mucho re-aplica el plan que Windows tenga activo entonces.
    $activeBeforeApply=[string](Get-ActivePowerSchemeGuid)
    if($activeBeforeApply-ine$scheme){
        throw 'El plan activo cambio despues de escribir el PowerSetting; VSO7 no arrebatara el plan externo.'
    }
    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive','SCHEME_CURRENT')
    $activeAfterApply=[string](Get-ActivePowerSchemeGuid)
    if($activeAfterApply-ine$scheme){
        throw 'El plan activo cambio durante la aplicacion del PowerSetting; se requiere rollback inmediato.'
    }

    $backup.Status='Applied';
    Save-ExtremeState
    Write-VSO7Log ("Energia verificada [{0}] {1}/{2} = {3}" -f $TweakId,$SubGroup,$Setting,$Value) 'CHANGE'

}

function Restore-ExtremePowerForTweakVSO {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    $ok=$true
    foreach($entry in @($script:ExtremeState.PowerSettings|Where-Object{
        $_.TweakId-eq$TweakId
    })){

        try{

            $subGuid=Get-PowerAliasGuidVSO -Alias ([string]$entry.SubGroupAlias);
            $settingGuid=Get-PowerAliasGuidVSO -Alias ([string]$entry.SettingAlias);
            if([string]::IsNullOrWhiteSpace($subGuid)-or[string]::IsNullOrWhiteSpace($settingGuid)){
                throw 'No se resolvieron GUID de energia.'
            }
            $current=Get-VSO7PowerSettingProviderSnapshotVSO -SubGroupAlias ([string]$entry.SubGroupAlias) -SettingAlias ([string]$entry.SettingAlias) -SchemeGuid ([string]$entry.SchemeGuid)
            $curAC=[int]$current.AC;
            $curDC=[int]$current.DC
            $restoreAC=($curAC-eq[int]$entry.AppliedAC);
            $restoreDC=($curDC-eq[int]$entry.AppliedDC)
            $baselineAC=($curAC-eq[int]$entry.AC);
            $baselineDC=($curDC-eq[int]$entry.DC)
            if($baselineAC-and$baselineDC){

                # Puede ser la continuacion de un rollback que ya escribio el baseline y se
                # interrumpio antes de /setactive. Si este esquema sigue activo, reaplicar
                # SCHEME_CURRENT antes de liberar ownership hace idempotente la recuperacion.
                $activeBaseline=[string](Get-ActivePowerSchemeGuid)
                if($activeBaseline-ieq[string]$entry.SchemeGuid){

                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive','SCHEME_CURRENT')|Out-Null
                    $activeAfterBaselineApply=[string](Get-ActivePowerSchemeGuid)
                    if($activeAfterBaselineApply-ine[string]$entry.SchemeGuid){
                        Write-VSO7Log ("El plan activo cambio mientras se reaplicaba un baseline ya restaurado para {0}/{1}; no se reactivo el esquema anterior."-f$entry.SubGroupAlias,$entry.SettingAlias) 'WARN'
                    }

                }
                Write-VSO7Log ("Energia {0}/{1} ya coincide con baseline; se libera ownership."-f$entry.SubGroupAlias,$entry.SettingAlias) 'INFO'
                continue

            }
            $pendingAmbiguous=([string]$entry.Status-ieq'Pending')-and(((-not$baselineAC)-and(-not$restoreAC))-or((-not$baselineDC)-and(-not$restoreDC)))
            if($pendingAmbiguous){
                $ok=$false;
                Write-VSO7Log ("PowerSetting {0}/{1} Pending ambiguo; solo se restauraran componentes con ownership demostrable y se conservara el estado."-f$entry.SubGroupAlias,$entry.SettingAlias) 'ERROR'
            }

            if($restoreAC){
                Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setacvalueindex',[string]$entry.SchemeGuid,$subGuid,$settingGuid,[string]$entry.AC)|Out-Null
            }
            elseif(-not$baselineAC){
                Write-VSO7Log ("No se restaura AC {0}/{1}: cambio externo detectado ({2}); se libera ownership de AC."-f$entry.SubGroupAlias,$entry.SettingAlias,$curAC) 'WARN'
            }

            if($restoreDC){
                Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setdcvalueindex',[string]$entry.SchemeGuid,$subGuid,$settingGuid,[string]$entry.DC)|Out-Null
            }
            elseif(-not$baselineDC){
                Write-VSO7Log ("No se restaura DC {0}/{1}: cambio externo detectado ({2}); se libera ownership de DC."-f$entry.SubGroupAlias,$entry.SettingAlias,$curDC) 'WARN'
            }

            $after=Get-ItemProperty -LiteralPath $regPath -ErrorAction Stop
            if($restoreAC-and[int]$after.ACSettingIndex-ne[int]$entry.AC){
                throw 'AC no coincide con baseline tras rollback.'
            }
            if($restoreDC-and[int]$after.DCSettingIndex-ne[int]$entry.DC){
                throw 'DC no coincide con baseline tras rollback.'
            }

            if($restoreAC-or$restoreDC){

                # Los indices ya estan restaurados en el esquema. Si sigue siendo el plan activo,
                # re-aplicarlo es necesario para que el valor efectivo cambie inmediatamente.
                # SCHEME_CURRENT evita reactivar nuestro SchemeGuid si otra aplicacion cambia de plan
                # en la ventana entre revalidacion y powercfg.
                $activeBeforeApply=[string](Get-ActivePowerSchemeGuid)
                if($activeBeforeApply-ieq[string]$entry.SchemeGuid){

                    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive','SCHEME_CURRENT')|Out-Null
                    $activeAfterApply=[string](Get-ActivePowerSchemeGuid)
                    if($activeAfterApply-ieq[string]$entry.SchemeGuid){

                        Write-VSO7Log ("Ajuste de energia restaurado y reaplicado en el plan activo: {0}/{1}"-f$entry.SubGroupAlias,$entry.SettingAlias) 'CHANGE'

                    }else{

                        Write-VSO7Log ("El plan activo cambio durante el rollback de {0}/{1}; baseline almacenado restaurado sin reactivar el plan anterior."-f$entry.SubGroupAlias,$entry.SettingAlias) 'WARN'

                    }

                }else{

                    Write-VSO7Log ("Ajuste de energia restaurado en su esquema sin cambiar el plan activo externo: {0}/{1}"-f$entry.SubGroupAlias,$entry.SettingAlias) 'CHANGE'

                }

            }

        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar/verificar energia {0}/{1}: {2}"-f$entry.SubGroupAlias,$entry.SettingAlias,$_.Exception.Message) 'ERROR'
        }

    }
    return $ok

}

function Get-BitLockerProtectionStateVSO {

    try {

        if (Get-Command 'BitLocker\Get-BitLockerVolume' -ErrorAction SilentlyContinue) {

            $v = BitLocker\Get-BitLockerVolume -MountPoint $script:SystemDrive -ErrorAction Stop
            $status = [string]$v.ProtectionStatus
            if ($status -eq 'On') {
                return 'On'
            }
            if ($status -eq 'Off') {
                return 'Off'
            }

        }

    } catch {}

    try {

        $lines = Invoke-NativeCommandVSO -FilePath 'manage-bde.exe' -Arguments @('-status',$script:SystemDrive) -CaptureOutput -AllowNonZeroExit
        $raw = ($lines | Out-String)
        if ($raw -match '(?im)^\s*(Protection Status|Estado de protecci[oó]n)\s*:\s*(Protection On|Activada|On)\s*$') {
            return 'On'
        }
        if ($raw -match '(?im)^\s*(Protection Status|Estado de protecci[oó]n)\s*:\s*(Protection Off|Desactivada|Off)\s*$') {
            return 'Off'
        }

    } catch {}
    return 'Unknown'

}

function Test-SecuritySettingLockedVSO {

    param([ValidateSet('HVCI','VBS')]$Kind)
    try {

        $path = if ($Kind -eq 'HVCI') {
            'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity'
        } else {
            'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard'
        }
        $snap=Get-RegistrySnapshot -Path $path -Name 'Locked'
        if(-not[bool]$snap.Exists){
            return $false
        }
        if([string]$snap.Kind-ine'DWord'){
            return $null
        }
        $value=[int]$snap.Value
        if($value-eq1){
            return $true
        }
        if($value-eq0){
            return $false
        }
        return $null

    } catch {
        return $null
    }

}

function Test-CredentialGuardUefiLockVSO {

    try{

        $system=Get-RegistrySnapshot -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name 'LsaCfgFlags'
        $policy=Get-RegistrySnapshot -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeviceGuard' -Name 'LsaCfgFlags'
        foreach($snap in @($system,$policy)){

            if(-not[bool]$snap.Exists){
                continue
            }
            if([string]$snap.Kind-ine'DWord'){
                return $null
            }
            $value=[int]$snap.Value
            if($value-lt0-or$value-gt2){
                return $null
            }
            if($value-eq1){
                return $true
            }

        }
        return $false

    }catch{
        return $null
    }

}

function Get-BcdSnapshotVSO {

    param([Parameter(Mandatory=$true)][string]$Name)

    $lines = Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/enum','{current}') -CaptureOutput
    foreach ($line in $lines) {

        $text = [string]$line
        if ($text -match ("^\s*{0}\s+(.+)$" -f [regex]::Escape($Name))) {

            return [pscustomobject]@{
                Name=$Name;
                Exists=$true;
                Value=$Matches[1].Trim()
            }

        }

    }
    return [pscustomobject]@{
        Name=$Name;
        Exists=$false;
        Value=$null
    }

}

function Set-ExtremeBcdValue {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][string]$Value
    )

    $bitlocker=Get-BitLockerProtectionStateVSO
    if($bitlocker-ne'Off'){
        throw ("VSO7 bloquea cambios BCD: estado de proteccion BitLocker = {0}. Solo se permite BCD cuando se confirma Protection Off."-f$bitlocker)
    }
    $existing=@($script:ExtremeState.Bcd|Where-Object{
        $_.TweakId-eq$TweakId-and$_.Name-eq$Name
    })
    if($existing.Count-gt0){
        throw 'Ya existe estado BCD EXTREMO; no se inicia una segunda mutacion.'
    }
    $snapshot=Get-BcdSnapshotVSO -Name $Name
    $script:ExtremeState.Bcd += [pscustomobject]@{
        TweakId=$TweakId;
        Name=$Name;
        Exists=$snapshot.Exists;
        Value=$snapshot.Value;
        AppliedValue=$Value;
        Status='Pending'
    }
    Save-ExtremeState

    try{

        $beforeMutation=Get-BcdSnapshotVSO -Name $Name
        $same=([bool]$beforeMutation.Exists-eq[bool]$snapshot.Exists)
        if($same-and[bool]$snapshot.Exists){
            $same=([string]$beforeMutation.Value-ieq[string]$snapshot.Value)
        }
        if(-not$same){
            throw 'BCD cambio entre snapshot y mutacion.'
        }
        $bitlockerNow=Get-BitLockerProtectionStateVSO
        if($bitlockerNow-ne'Off'){
            throw ("BitLocker cambio a {0} antes de BCDEdit."-f$bitlockerNow)
        }

    }catch{

        $reason=$_.Exception.Message
        $script:ExtremeState.Bcd=@($script:ExtremeState.Bcd|Where-Object{
            -not($_.TweakId-ieq$TweakId-and$_.Name-ieq$Name)
        })
        Save-ExtremeState
        throw ("{0} VSO7 retiro su Pending y no modifica BCD."-f$reason)

    }

    Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/set','{current}',$Name,$Value)
    $after=Get-BcdSnapshotVSO -Name $Name
    if(-not$after.Exists-or[string]$after.Value-ine[string]$Value){
        throw ("BCDEdit no verifico {0}={1}."-f$Name,$Value)
    }
    $owned=@($script:ExtremeState.Bcd|Where-Object{
        $_.TweakId-ieq$TweakId-and$_.Name-ieq$Name
    }|Select-Object -First 1);
    if($owned.Count-ne1){
        throw 'Se perdio el estado BCD pendiente.'
    };
    $owned[0].Status='Applied';
    Save-ExtremeState
    Write-VSO7Log ("BCD verificado [{0}] {1}={2}"-f$TweakId,$Name,$Value) 'CHANGE'

}

function Restore-ExtremeRegistryForTweak {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    $ok=$true
    foreach($entry in @($script:ExtremeState.Registry|Where-Object{
        $_.TweakId-eq$TweakId
    })){

        try{

            if(Test-RegistryValueOwnedByNormalVSO -Path ([string]$entry.Path) -Name ([string]$entry.Name)){
                [void](Assert-VSO7SharedRegistryOwnershipCompatibleVSO -Path ([string]$entry.Path) -Name ([string]$entry.Name));
                Write-VSO7Log ("Rollback EXTREMO libera {0}\{1}, pero no toca el valor porque el sistema normal compatible sigue siendo propietario."-f$entry.Path,$entry.Name) 'CHANGE';
                continue
            }
            $curSnapshot=Get-RegistrySnapshot -Path ([string]$entry.Path) -Name ([string]$entry.Name);
            $curExists=[bool]$curSnapshot.Exists;
            $curKind=$curSnapshot.Kind;
            $curValue=$curSnapshot.Value
            $matchesOriginal=($curExists-eq[bool]$entry.Exists);
            if($matchesOriginal-and$curExists){
                $matchesOriginal=($curKind-ieq[string]$entry.Kind)-and(Test-RegistryValueEqualVSO -Actual $curValue -Expected $entry.Value -Kind ([string]$entry.Kind))
            };
            if($matchesOriginal){
                Write-VSO7Log ("Registro EXTREMO {0}\{1} ya coincide con baseline; se libera ownership."-f$entry.Path,$entry.Name) 'INFO';
                continue
            }
            $matchesApplied=($curExists-eq[bool]$entry.AppliedExists);
            if($matchesApplied-and$curExists){
                $matchesApplied=($curKind-ieq[string]$entry.AppliedKind)-and(Test-RegistryValueEqualVSO -Actual $curValue -Expected $entry.AppliedValue -Kind ([string]$entry.AppliedKind))
            }
            if(-not$matchesApplied){

                if([string]$entry.Status-ieq'Pending'){
                    throw 'Registry EXTREMO Pending ambiguo: no coincide con baseline ni con aplicado; se conserva evidencia.'
                }
                Write-VSO7Log ("No se restaura Registro EXTREMO {0}\{1}: cambio externo detectado tras Applied; se libera ownership."-f$entry.Path,$entry.Name) 'WARN';
                continue

            }
            if([bool]$entry.Exists){

                if(-not(Test-Path -LiteralPath $entry.Path)){
                    New-Item -Path $entry.Path -Force -ErrorAction Stop|Out-Null
                }
                New-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -Value $entry.Value -PropertyType ([string]$entry.Kind) -Force -ErrorAction Stop|Out-Null

            }else{

                if(Test-Path -LiteralPath $entry.Path){

                    $beforeDelete=Get-RegistrySnapshot -Path ([string]$entry.Path) -Name ([string]$entry.Name)
                    if([bool]$beforeDelete.Exists){
                        Remove-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -ErrorAction Stop
                    }

                }

            }
            $after=Get-RegistrySnapshot -Path ([string]$entry.Path) -Name ([string]$entry.Name)
            $afterMatches=([bool]$after.Exists-eq[bool]$entry.Exists)
            if($afterMatches-and[bool]$after.Exists){
                $afterMatches=([string]$after.Kind-ieq[string]$entry.Kind)-and(Test-RegistryValueEqualVSO -Actual $after.Value -Expected $entry.Value -Kind ([string]$entry.Kind))
            }
            if(-not$afterMatches){
                throw 'El valor Registry EXTREMO no coincide con el baseline tras rollback.'
            }
            Write-VSO7Log ("Registro extremo restaurado/verificado con ownership: {0}\{1}"-f$entry.Path,$entry.Name) 'CHANGE'

        }catch{
            $ok=$false;
            Write-VSO7Log ("Error restaurando {0}\{1}: {2}"-f$entry.Path,$entry.Name,$_.Exception.Message) 'ERROR'
        }

    }
    return $ok

}

function Restore-ExtremeBcdForTweak {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    $ok=$true
    foreach($entry in @($script:ExtremeState.Bcd|Where-Object{
        $_.TweakId-eq$TweakId
    })){

        try{

            $current=Get-BcdSnapshotVSO -Name ([string]$entry.Name)
            $matchesOriginal=([bool]$current.Exists-eq[bool]$entry.Exists);
            if($matchesOriginal-and[bool]$current.Exists){
                $matchesOriginal=([string]$current.Value-ieq[string]$entry.Value)
            };
            if($matchesOriginal){
                Write-VSO7Log ("BCD {0} ya coincide con baseline; se libera ownership."-f$entry.Name) 'INFO';
                continue
            }
            $matchesApplied=([bool]$current.Exists-and[string]$current.Value-ieq[string]$entry.AppliedValue)
            if(-not$matchesApplied){

                if([string]$entry.Status-ieq'Pending'){
                    $ok=$false;
                    Write-VSO7Log ("BCD {0} Pending ambiguo; se conserva evidencia sin sobrescribir."-f$entry.Name) 'ERROR';
                    continue
                }
                Write-VSO7Log ("No se restaura BCD {0}: cambio externo detectado tras Applied; se libera ownership."-f$entry.Name) 'WARN';
                continue

            }
            $bitlocker=Get-BitLockerProtectionStateVSO;
            if($bitlocker-ne'Off'){
                throw ("VSO7 no modificara BCD durante rollback: BitLocker={0}."-f$bitlocker)
            }
            if([bool]$entry.Exists){
                Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/set','{current}',[string]$entry.Name,[string]$entry.Value)|Out-Null
            }else{
                [void](Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/deletevalue','{current}',[string]$entry.Name) -CaptureOutput -AllowNonZeroExit)
            }
            $after=Get-BcdSnapshotVSO -Name ([string]$entry.Name);
            if([bool]$after.Exists-ne[bool]$entry.Exists){
                throw 'Existencia BCD no coincide con baseline.'
            };
            if([bool]$entry.Exists-and[string]$after.Value-ine[string]$entry.Value){
                throw 'Valor BCD no coincide con baseline.'
            }
            Write-VSO7Log ("BCD restaurado/verificado con ownership: {0}"-f$entry.Name) 'CHANGE'

        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar BCD {0}: {1}"-f$entry.Name,$_.Exception.Message) 'ERROR'
        }

    }
    return $ok

}

function Get-WindowsBuildVSO {

    try {
        return [int](CimCmdlets\Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).BuildNumber
    } catch {
        return 0
    }

}

function Confirm-UnvalidatedBuildIfNeeded {

    param([array]$Tweaks)
    $danger=@($Tweaks | Where-Object Risk -ge 3)
    if($danger.Count -eq 0){
        return $true
    }
    $build=Get-WindowsBuildVSO
    if($build-le0){

        Write-VSOHost ''
        Write-VSOHost 'No se pudo determinar de forma fiable la build de Windows. VSO7 bloquea ALTO/MUCHO PELIGRO por seguridad.' -ForegroundColor Red
        return $false

    }
    if($build -le $script:ValidatedBuildMax){
        return $true
    }
    Write-VSOHost ''
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Esta build de Windows ({0}) es posterior a la ultima build validada por VSO7 ({1}).' -En 'This Windows build ({0}) is newer than the latest build validated by VSO7 ({1}).') -f $build,$script:ValidatedBuildMax) -ForegroundColor Red
    Write-VSOHost 'VSO7 bloquea ALTO/MUCHO PELIGRO en builds posteriores hasta validarlas de forma real.' -ForegroundColor Yellow
    Write-VSOHost 'Los modos de diagnostico y los cambios de menor riesgo siguen disponibles cuando sus preflight individuales lo permiten.' -ForegroundColor DarkGray
    return $false

}

