    },
        [pscustomobject]@{
        Id='virtualization.hypervisorLaunchOff';Name='BCD hypervisorlaunchtype OFF';Risk=4;Restart=$true;Reversible=$true;Desc='Impide arrancar el hipervisor de Windows; rompe VBS/Hyper-V/WSL2 dependiente.'
    }
    )
    if ($script:Language -eq 'en') {

        foreach ($item in $items) {

            $item.Name = [string](Convert-VSOText -Value $item.Name)
            $item.Desc = [string](Convert-VSOText -Value $item.Desc)

        }

    }
    return $items

}

function Test-PowerSettingAvailableVSO {

    param([Parameter(Mandatory=$true)][string]$SubGroup,[Parameter(Mandatory=$true)][string]$Setting)
    try{

        $scheme=Get-ActivePowerSchemeGuid
        if([string]::IsNullOrWhiteSpace($scheme)){
            return $false
        }
        $subGuid=Get-PowerAliasGuidVSO -Alias $SubGroup
        $settingGuid=Get-PowerAliasGuidVSO -Alias $Setting
        if([string]::IsNullOrWhiteSpace($subGuid)-or[string]::IsNullOrWhiteSpace($settingGuid)){
            return $false
        }
        # Consultar por GUID evita depender de que una build concreta exponga el mismo alias textual.
        Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/query',$scheme,$subGuid,$settingGuid)|Out-Null
        return $true

    }catch{
        return $false
    }

}

function Get-VSO7ExtremeNativeOwnershipStateVSO {

    param([Parameter(Mandatory=$true)][string]$TweakId)
    if($TweakId-ine'gaming.gamemode'){
        return 'None'
    }
    $path='HKEY_CURRENT_USER\Software\Microsoft\GameBar';$name='AutoGameModeEnabled'
    $canonical=ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path $path
    $owners=@()
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{[string]$_.Status-cne'Restored'})){
        $owners+=@($session.Entries|Where-Object{
            [string]$_.Type-ieq'RegistryValue' -and
            (ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$_.Path))-ieq$canonical -and
            [string]$_.Name-ieq$name
        })
    }
    if($owners.Count-eq0){
        return 'None'
    }
    $desired=ConvertTo-VSO7NativeDesiredRegistrySnapshotVSO -Kind 'DWord' -Value 1
    foreach($owner in $owners){
        $recorded=[pscustomobject]@{
            Exists=($null-ne$owner.AppliedExists-and[bool]$owner.AppliedExists)
            Kind=$owner.AppliedKind
            Value=$owner.AppliedValue
        }
        if([string]$owner.Status-ine'Applied'-or-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $recorded -B $desired)){
            return 'Conflict'
        }
    }
    $current=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name $name
    if(Test-VSO7NativeRegistrySnapshotEqualVSO -A $current -B $desired){
        return 'AlreadyApplied'
    }
    return 'Conflict'

}

function Test-TweakAvailableVSO {

    param([Parameter(Mandatory=$true)]$Tweak)

    try {

        switch ([string]$Tweak.Id) {

            'gaming.gamemode' {
                return ((Get-VSO7ExtremeNativeOwnershipStateVSO -TweakId 'gaming.gamemode')-eq'None')
            }
            'search.indexing' {
                return ($null -ne (Get-VSO7ServiceStatusVSO -Name 'WSearch'))
            }
            'xbox.services' {

                $present = @('XblAuthManager','XblGameSave','XboxNetApiSvc' | Where-Object {
                    $null -ne (Get-VSO7ServiceStatusVSO -Name ([string]$_))
                })
                return ($present.Count -gt 0)

            }
            'telemetry.diagtrack' {
                return ($null -ne (Get-VSO7ServiceStatusVSO -Name 'DiagTrack'))
            }
            'services.spooler' {
                return ($null -ne (Get-VSO7ServiceStatusVSO -Name 'Spooler'))
            }
            'services.location' {
                return ($null -ne (Get-VSO7ServiceStatusVSO -Name 'lfsvc'))
            }
            'services.bluetooth' {
                return ($null -ne (Get-VSO7ServiceStatusVSO -Name 'bthserv'))
            }
            'virtualization.hyperv' {

                $f = Dism\Get-WindowsOptionalFeature -Online -FeatureName Microsoft-Hyper-V-Hypervisor -ErrorAction SilentlyContinue
                return ($null -ne $f -and [string]$f.State -like 'Enable*')

            }
            'virtualization.wsl' {

                $wsl = Dism\Get-WindowsOptionalFeature -Online -FeatureName Microsoft-Windows-Subsystem-Linux -ErrorAction SilentlyContinue
                $vmp = Dism\Get-WindowsOptionalFeature -Online -FeatureName VirtualMachinePlatform -ErrorAction SilentlyContinue
                return (($null -ne $wsl -and [string]$wsl.State -like 'Enable*') -or ($null -ne $vmp -and [string]$vmp.State -like 'Enable*'))

            }
            'virtualization.sandbox' {

                $f = Dism\Get-WindowsOptionalFeature -Online -FeatureName Containers-DisposableClientVM -ErrorAction SilentlyContinue
                return ($null -ne $f -and [string]$f.State -like 'Enable*')

            }
            'power.usbSuspend' {
                return (Test-PowerSettingAvailableVSO -SubGroup 'SUB_USB' -Setting 'USBSELECTIVE')
            }
            'power.pcieAspm' {
                return (Test-PowerSettingAvailableVSO -SubGroup 'SUB_PCIEXPRESS' -Setting 'ASPM')
            }
            'security.memoryIntegrity' {
                $locked=Test-SecuritySettingLockedVSO -Kind HVCI;
                return ($false-eq$locked)
            }
            'security.credentialGuard' {
                $locked=Test-CredentialGuardUefiLockVSO;
                return ($false-eq$locked)
            }
            'security.vbs' {
                $locked=Test-SecuritySettingLockedVSO -Kind VBS;
                return ($false-eq$locked)
            }
            'virtualization.hypervisorLaunchOff' {

                try{
                    [void](Resolve-VSOSystemExecutable -Name 'bcdedit.exe')
                }catch{
                    return $false
                }
                return ((Get-BitLockerProtectionStateVSO) -eq 'Off')

            }
            default {
                return $true
            }

        }

    } catch {
        return $false
    }

}

function Get-TweakUnavailableReasonVSO {

    param($Tweak)
    if (Test-TweakAvailableVSO -Tweak $Tweak) {
        return ''
    }
    switch ([string]$Tweak.Id) {

        'gaming.gamemode' {
            try{$nativeState=Get-VSO7ExtremeNativeOwnershipStateVSO -TweakId 'gaming.gamemode'}catch{return 'No se pudo validar de forma segura el ownership nativo de Game Mode.'}
            if($nativeState-eq'AlreadyApplied'){return 'Ya aplicado y protegido por una sesion Recovery de VSO7.'}
            if($nativeState-eq'Conflict'){return 'Una sesion Recovery de VSO7 posee Game Mode con un estado diferente o ambiguo; restaura/revisa esa sesion.'}
            return 'Game Mode no esta disponible.'
        }
        'power.usbSuspend' {
            return 'PowerCfg no expone este ajuste en el plan actual.'
        }
        'power.pcieAspm' {
            return 'PowerCfg no expone ASPM en el plan actual.'
        }
        'virtualization.hyperv' {
            return 'Hyper-V Hypervisor no esta habilitado; no hay nada que desactivar.'
        }
        'virtualization.wsl' {
            return 'WSL/VMP no estan habilitados; no hay nada que desactivar.'
        }
        'virtualization.sandbox' {
            return 'Windows Sandbox no esta habilitado.'
        }
        'security.memoryIntegrity' {
            return 'Memory Integrity/HVCI esta bloqueado o su estado Locked no pudo verificarse con certeza; VSO7 no continuara.'
        }
        'security.credentialGuard' {
            return 'Credential Guard usa UEFI lock o su estado no pudo verificarse con certeza; VSO7 no continuara.'
        }
        'security.vbs' {
            return 'VBS esta bloqueado o su estado Locked no pudo verificarse con certeza; VSO7 no continuara.'
        }
        'virtualization.hypervisorLaunchOff' {
            return ("BCD bloqueado: BitLocker={0}; VSO7 exige Protection Off." -f (Get-BitLockerProtectionStateVSO))
        }
        default {
            return 'Componente/servicio no presente o no modificable de forma segura en este Windows.'
        }

    }

}

function Get-VSO7PendingRebootStateVSO {

    $reasons=New-Object 'Collections.Generic.List[string]'
    $ignored=New-Object 'Collections.Generic.List[string]'
    try{
        if(Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending' -ErrorAction Stop){
            [void]$reasons.Add('CBS:RebootPending')
        }
        if(Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired' -ErrorAction Stop){
            [void]$reasons.Add('WindowsUpdate:RebootRequired')
        }

        $volatile=Get-RegistrySnapshot -Path 'HKLM:\SOFTWARE\Microsoft\Updates' -Name 'UpdateExeVolatile'
        if([bool]$volatile.Exists){
            [int64]$volatileValue=0
            if(-not[int64]::TryParse([string]$volatile.Value,[ref]$volatileValue)){
                throw 'UpdateExeVolatile contiene un valor no numerico.'
            }
            if($volatileValue-ne0){[void]$reasons.Add(('UpdateExeVolatile:{0}'-f$volatileValue))}
        }

        $activeName=Get-RegistrySnapshot -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -Name 'ComputerName'
        $configuredName=Get-RegistrySnapshot -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -Name 'ComputerName'
        if([bool]$activeName.Exists-and[bool]$configuredName.Exists){
            $active=([string]$activeName.Value).Trim();$configured=([string]$configuredName.Value).Trim()
            if(-not[string]::IsNullOrWhiteSpace($active)-and-not[string]::IsNullOrWhiteSpace($configured)-and$active-ine$configured){
                [void]$reasons.Add('ComputerName:PendingRename')
            }
        }

        foreach($valueName in @('PendingFileRenameOperations','PendingFileRenameOperations2')){
            $pendingRename=Get-RegistrySnapshot -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name $valueName
            if(-not[bool]$pendingRename.Exists){continue}
            if([string]$pendingRename.Kind-ine'MultiString'){
                throw ($valueName+' existe pero no es REG_MULTI_SZ.')
            }
            $values=@($pendingRename.Value)
            $sourceCount=0
            for($i=0;$i-lt$values.Count;$i+=2){
                if(-not[string]::IsNullOrWhiteSpace([string]$values[$i])){$sourceCount++}
            }
            if($sourceCount-gt0){
                [void]$reasons.Add(('{0}:{1}'-f$valueName,$sourceCount))
            }else{
                [void]$ignored.Add(($valueName+':Empty'))
            }
        }

        return [pscustomobject]@{
            IsPending=($reasons.Count-gt0)
            Reasons=@($reasons)
            Ignored=@($ignored)
            Error=''
        }
    }catch{
        return [pscustomobject]@{
            IsPending=$null
            Reasons=@($reasons)
            Ignored=@($ignored)
            Error=[string]$_.Exception.Message
        }
    }

}

function Test-PendingRebootVSO {

    $state=Get-VSO7PendingRebootStateVSO
    $script:LastPendingRebootStateVSO=$state
    if($null-eq$state.IsPending){
        Write-VSO7Log ('No se pudo determinar de forma fiable si Windows tiene un reinicio pendiente: '+[string]$state.Error) 'WARN'
        return $null
    }
    if([bool]$state.IsPending){
        Write-VSO7Log ('Reinicio pendiente confirmado por: '+(@($state.Reasons)-join', ')) 'INFO'
        return $true
    }
    if(@($state.Ignored).Count-gt0){
        Write-VSO7Log ('Marcadores de reinicio vacios ignorados: '+(@($state.Ignored)-join', ')) 'INFO'
    }
    return $false

}

function Invoke-VSO7Preflight {

    $errors = @();
    $warnings = @()
    Write-VSO7LifecycleCheckpointVSO -Name 'PREFLIGHT_ENTER'
    if (-not (Test-IsAdministrator)) {
        $errors += 'VSO7 no esta elevado como administrador.'
    }
    if (-not (Test-IsWindowsPowerShell51)) {
        $errors += 'El nucleo no esta ejecutandose en Windows PowerShell 5.1.'
    }
    foreach ($command in @('powercfg.exe','dism.exe','reg.exe')) {
        try{
            [void](Resolve-VSOSystemExecutable -Name $command)
        }catch{
            $errors += ("No se encontro {0} de forma segura en System32." -f $command)
        }
    }
    try{
        [void](Resolve-VSOSystemExecutable -Name 'bcdedit.exe')
    }catch{
        $warnings += 'BCDEdit no disponible en System32: el tweak BCD quedara no disponible.'
    }
    $preflightStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PREFLIGHT_PENDING_REBOOT'
    $pendingReboot=Test-PendingRebootVSO
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PREFLIGHT_PENDING_REBOOT' -StartedMs $preflightStage -Detail ('State='+[string]$pendingReboot)
    if ($true -eq $pendingReboot) {
        $reasonSummary=if($null-ne$script:LastPendingRebootStateVSO){@($script:LastPendingRebootStateVSO.Reasons)-join', '}else{'Unknown'}
        $warnings += Get-VSO7ConsoleTextVSO -Es ('Windows tiene un reinicio pendiente. VSO7 permitira diagnostico/limpieza, pero no es recomendable aplicar ALTO/MUCHO PELIGRO hasta reiniciar. Senales: {0}.'-f$reasonSummary) -En ('Windows has a pending restart. VSO7 allows diagnostics/cleanup, but HIGH/VERY DANGEROUS changes are not recommended until restart. Signals: {0}.'-f$reasonSummary)
    }
    elseif ($null -eq $pendingReboot) {
        $warnings += 'No se pudo determinar de forma fiable el estado de reinicio pendiente; ALTO/MUCHO PELIGRO se bloqueara de forma conservadora.'
    }
    $preflightStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PREFLIGHT_CONFIG_WRITE_TEST'
    try {

        New-Item -ItemType Directory -Path $script:ConfigRoot -Force -ErrorAction Stop | Out-Null
        $probe = Join-Path $script:ConfigRoot ('.write-test-{0}.tmp' -f [guid]::NewGuid().ToString('N'))
        Set-Content -LiteralPath $probe -Value 'ok' -Encoding ASCII -Force -ErrorAction Stop
        Remove-Item -LiteralPath $probe -Force -ErrorAction Stop

    } catch {
        $errors += ("Config no es escribible: {0}" -f $_.Exception.Message)
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PREFLIGHT_CONFIG_WRITE_TEST' -StartedMs $preflightStage
    $preflightStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PREFLIGHT_LOAD_STATE'
    try {
        Load-State
    } catch {
        $errors += $_.Exception.Message
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PREFLIGHT_LOAD_STATE' -StartedMs $preflightStage
    $preflightStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PREFLIGHT_LOAD_EXTREME'
    try {
        Load-ExtremeState
    } catch {
        $errors += $_.Exception.Message
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PREFLIGHT_LOAD_EXTREME' -StartedMs $preflightStage
    $preflightStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PREFLIGHT_LOAD_STARTUP'
    try {
        Load-StartupState
    } catch {
        $errors += $_.Exception.Message
    }
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PREFLIGHT_LOAD_STARTUP' -StartedMs $preflightStage
    foreach ($warning in $warnings) {
        Write-VSO7Log $warning 'WARN'
    }
    foreach ($preflightError in $errors) {
        Write-VSO7Log $preflightError 'ERROR'
    }
    $ok=($errors.Count -eq 0)
    Write-VSO7LifecycleCheckpointVSO -Name 'PREFLIGHT_EXIT' -Detail ('Ok='+[string]$ok+';Errors='+[string]$errors.Count+';Warnings='+[string]$warnings.Count)
    return $ok

}

function Get-RiskNameVSO {

    param([int]$Risk)
    if ($script:Language -eq 'en') {

        switch ($Risk) {
            1 {
                'LOW'
            } 2 {
                'MEDIUM'
            } 3 {
                'HIGH'
            } 4 {
                'VERY DANGEROUS'
            } default {
                '?'
            }
        }

    } else {

        switch ($Risk) {
            1 {
                'LEVE'
            } 2 {
                'MEDIO'
            } 3 {
                'ALTO'
            } 4 {
                'MUCHO PELIGRO'
            } default {
                '?'
            }
        }

    }

}

