        } 2 {
            'Yellow'
        } 3 {
            'DarkYellow'
        } 4 {
            'Red'
        } default {
            'Gray'
        }
    }

}

function Get-TweakDetectInfo {

    param([Parameter(Mandatory=$true)][string]$Id)

    try {

