            'cleanup.shaders' {

                [int64]$bytes = 0
                foreach ($path in @("$script:LocalAppData\NVIDIA\DXCache","$script:LocalAppData\NVIDIA\GLCache","$script:LocalAppData\D3DSCache")) {

                    $bytes += Get-PathSizeBytes -Path $path

                }
                return ("cache actual: {0}" -f (Format-BytesVSO -Bytes $bytes))

            }
            'cleanup.spotify' {
                return ("cache actual: {0}" -f (Format-BytesVSO -Bytes (Get-PathSizeBytes -Path "$script:LocalAppData\Packages\SpotifyAB.SpotifyMusic_zpdnekdrzrea0\LocalCache")))
            }
            'cleanup.lghub' {
                return ("cache actual: {0}" -f (Format-BytesVSO -Bytes (Get-PathSizeBytes -Path (Join-Path $script:ProgramData 'LGHUB\cache'))))
            }
            'cleanup.fortnite' {
                return ("cache actual: {0}" -f (Format-BytesVSO -Bytes (Get-PathSizeBytes -Path "$script:LocalAppData\FortniteGame\Saved\PersistentDownloadDir")))
            }
            'cleanup.bobby' {
                return ("cache actual: {0}" -f (Format-BytesVSO -Bytes (Get-PathSizeBytes -Path "$script:AppData\.minecraft\.bobby")))
            }
            'search.indexing' {

                $serviceStatus = Get-VSO7ServiceStatusVSO -Name 'WSearch'
                if ($null-ne$serviceStatus) {
                    return ("estado: {0}" -f $serviceStatus)
                }
                return 'no presente'

            }
            'virtualization.hyperv' {

                $feature = Dism\Get-WindowsOptionalFeature -Online -FeatureName Microsoft-Hyper-V-Hypervisor -ErrorAction SilentlyContinue
                if ($feature) {
                    return ("estado: {0}" -f $feature.State)
