            }
            default {
                return ''
            }

        }

    } catch {
        return ''
    }

}

function Get-FilesNoReparseVSO {

    param([Parameter(Mandatory=$true)][string]$Root)
    if ([string]::IsNullOrWhiteSpace($Root) -or -not [IO.Path]::IsPathRooted($Root)) {
        return
    }
    if (-not (Test-Path -LiteralPath $Root -PathType Container)) {
        return
    }
    try {
        $rootFull=[IO.Path]::GetFullPath($Root).TrimEnd('\')
    } catch {
        return
    }
    try {

        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $rootFull)
        $rootItem=Get-Item -LiteralPath $rootFull -Force -ErrorAction Stop
        if (($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {

            Write-VSO7Log ("Se omite raiz reparse point durante enumeracion: {0}" -f $rootFull) 'WARN'
            return

        }

    } catch {
        return
    }

    $stack = New-Object System.Collections.Stack
    $stack.Push($rootFull)
    while ($stack.Count -gt 0) {

        $dir = [string]$stack.Pop()
        try {

            $dirFull=[IO.Path]::GetFullPath($dir).TrimEnd('\')
            if($dirFull-ine$rootFull -and -not $dirFull.StartsWith($rootFull+'\',[StringComparison]::OrdinalIgnoreCase)){

                Write-VSO7Log ("Se omite directorio fuera de la raiz durante enumeracion: {0}" -f $dirFull) 'WARN'
                continue

            }
            $dirItem=Get-Item -LiteralPath $dirFull -Force -ErrorAction Stop
            if(-not$dirItem.PSIsContainer -or (($dirItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0)){

                Write-VSO7Log ("Se omite directorio inseguro/reparse point durante enumeracion: {0}" -f $dirFull) 'WARN'
                continue

            }

        } catch {
            continue
        }
        foreach ($item in @(Get-ChildItem -LiteralPath $dirFull -Force -ErrorAction SilentlyContinue)) {

            if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {

                Write-VSO7Log ("Se omite reparse point durante limpieza: {0}" -f $item.FullName) 'WARN'
                continue

            }
            if ($item.PSIsContainer) {
                $stack.Push($item.FullName)
            } else {
                Write-Output $item
            }

        }

    }

}

function Join-ValidatedDescendantPathVSO {

    param(
        [Parameter(Mandatory=$true)][string]$Base,
        [Parameter(Mandatory=$true)][string]$Relative
    )
    if([string]::IsNullOrWhiteSpace($Base)){
        throw 'Ruta base vacia.'
    }
    if(-not[IO.Path]::IsPathRooted($Base)){
        throw ("Ruta base no absoluta: {0}"-f$Base)
    }
    if([string]::IsNullOrWhiteSpace($Relative) -or [IO.Path]::IsPathRooted($Relative)){
        throw 'Ruta relativa invalida.'
    }
    $baseFull=[IO.Path]::GetFullPath($Base).TrimEnd('\')
    $candidate=[IO.Path]::GetFullPath((Join-Path $baseFull $Relative)).TrimEnd('\')
    if($candidate.Length-le$baseFull.Length -or -not $candidate.StartsWith($baseFull+'\',[StringComparison]::OrdinalIgnoreCase)){

        throw ("La ruta no es descendiente real de la base permitida: {0}"-f$candidate)

    }
    return $candidate

}

function Get-AllowedCleanupPathsVSO {

    $specs=@(
        @($script:LocalAppData,'Temp'),@($script:WindowsRoot,'Temp'),
        @($script:LocalAppData,'CrashDumps'),@($script:WindowsRoot,'LiveKernelReports'),
        @($script:LocalAppData,'NVIDIA\DXCache'),@($script:LocalAppData,'NVIDIA\GLCache'),@($script:LocalAppData,'D3DSCache'),
        @($script:AppData,'Code\CachedExtensionVSIXs'),@($script:AppData,'Code\CachedData'),@($script:AppData,'Code\Cache'),@($script:AppData,'Code\GPUCache'),@($script:AppData,'Code\Crashpad'),@($script:AppData,'Code\Code Cache'),@($script:AppData,'Code\DawnWebGPUCache'),
        @($script:AppData,'Code - Insiders\CachedExtensionVSIXs'),@($script:AppData,'Code - Insiders\CachedData'),@($script:AppData,'Code - Insiders\Cache'),@($script:AppData,'Code - Insiders\GPUCache'),@($script:AppData,'Code - Insiders\Crashpad'),@($script:AppData,'Code - Insiders\Code Cache'),@($script:AppData,'Code - Insiders\DawnWebGPUCache'),
        @($script:LocalAppData,'Packages\SpotifyAB.SpotifyMusic_zpdnekdrzrea0\LocalCache'),@($script:ProgramData,'LGHUB\cache'),@($script:LocalAppData,'FortniteGame\Saved\PersistentDownloadDir'),@($script:AppData,'.minecraft\.bobby'),
        @($script:LocalAppData,'npm-cache'),@($script:AppData,'npm-cache'),@($script:LocalAppData,'pip\Cache')
    )
    $paths=@()
    foreach($spec in $specs){

        try{
            if(-not[string]::IsNullOrWhiteSpace([string]$spec[0])){
                $paths += Join-ValidatedDescendantPathVSO -Base ([string]$spec[0]) -Relative ([string]$spec[1])
            }
        }catch{}

    }
    return @($paths|Sort-Object -Unique)

}

function Assert-CleanupPathAllowedVSO {

    param([Parameter(Mandatory=$true)][string]$Path)

    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        throw 'Ruta de limpieza vacia o no absoluta.'
    }
    $full = [IO.Path]::GetFullPath($Path).TrimEnd('\')
    $root=[IO.Path]::GetPathRoot($full).TrimEnd('\')
    if($full -ieq $root){
        throw 'VSO7 nunca limpiara la raiz de una unidad.'
    }
    $allowed = @(Get-AllowedCleanupPathsVSO)
    if ($allowed -notcontains $full) {
        throw ("Ruta de limpieza no autorizada por VSO7: {0}" -f $full)
    }
    return $full

}

function Assert-VSO7CleanupTargetSafeVSO {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$AllowedRoot,
        [switch]$RequireLeaf
    )
    $root=Assert-CleanupPathAllowedVSO -Path $AllowedRoot
    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        throw 'Target de limpieza vacio o no absoluto.'
    }
    $target=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if($target.Length-le$root.Length -or -not$target.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)){

        throw ("Target de limpieza fuera de su raiz autorizada: {0}"-f$target)

    }

    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $root)
    $rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop
    if(-not$rootItem.PSIsContainer -or (($rootItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0)){

        throw ("Raiz de limpieza insegura/reparse point: {0}"-f$root)

    }

    $relative=$target.Substring($root.Length).TrimStart('\')
    if([string]::IsNullOrWhiteSpace($relative)){
        throw 'Target de limpieza coincide con la raiz.'
    }
    $parts=@($relative.Split('\'))
    $cursor=$root
    for($i=0;$i-lt$parts.Count;$i++){

        if([string]::IsNullOrWhiteSpace([string]$parts[$i]) -or [string]$parts[$i]-eq'.' -or [string]$parts[$i]-eq'..'){
            throw 'Componente de ruta de limpieza invalido.'
        }
        $cursor=Join-Path $cursor ([string]$parts[$i])
        if(-not(Test-Path -LiteralPath $cursor)){
            throw ("Target de limpieza desaparecio durante la validacion: {0}"-f$cursor)
        }
        $item=Get-Item -LiteralPath $cursor -Force -ErrorAction Stop
        if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw ("Reparse point detectado antes de borrar: {0}"-f$cursor)
        }
        if($i-lt($parts.Count-1) -and -not$item.PSIsContainer){
            throw ("Componente intermedio no es directorio: {0}"-f$cursor)
        }
        if($i-eq($parts.Count-1) -and $RequireLeaf -and $item.PSIsContainer){
            throw ("Se esperaba archivo y se encontro directorio: {0}"-f$cursor)
        }

    }
    return $target

}

function Remove-VSO7CleanupFileSafeVSO {

    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$AllowedRoot
    )
    $target=Assert-VSO7CleanupTargetSafeVSO -Path $Path -AllowedRoot $AllowedRoot -RequireLeaf
    # Repetimos la validacion en la misma funcion inmediatamente antes de Remove-Item.
    # PowerShell 5.1 no ofrece una primitiva sencilla de delete-by-handle con verificacion de destino;
    # esta comprobacion reduce la carrera, pero una carrera de filesystem a nivel kernel sigue siendo una limitacion documentada.
    $target=Assert-VSO7CleanupTargetSafeVSO -Path $target -AllowedRoot $AllowedRoot -RequireLeaf
    Remove-Item -LiteralPath $target -Force -ErrorAction Stop

}

function Remove-DirectoryContentsSafe {

    param([Parameter(Mandatory=$true)][string]$Path)

    $safePath = Assert-CleanupPathAllowedVSO -Path $Path
    if (-not (Test-Path -LiteralPath $safePath -PathType Container)) {
        return [int64]0
    }

    $rootItem = Get-Item -LiteralPath $safePath -Force -ErrorAction Stop
    if (($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
        throw 'La raiz de cache es un reparse point; VSO7 se niega a limpiarla.'
    }

    [int64]$bytes = 0
    foreach ($file in @(Get-FilesNoReparseVSO -Root $safePath)) {

        try {

            $length = [int64]$file.Length
            Remove-VSO7CleanupFileSafeVSO -Path $file.FullName -AllowedRoot $safePath
            $bytes += $length

        } catch {
            Write-VSO7Log ("No se pudo borrar cache de forma segura: {0} ({1})" -f $file.FullName,$_.Exception.Message) 'WARN'
        }

    }

    # Deliberadamente NO se eliminan directorios vacios. Borrar solo archivos reduce la superficie
    # de carreras con junctions/reparse points en caches escribibles por el usuario.
    return $bytes

}

function Remove-VSCodeCachesVSO {

    [int64]$bytes = 0
    foreach ($root in @("$script:AppData\Code","$script:AppData\Code - Insiders")) {

        foreach ($name in @('CachedExtensionVSIXs','CachedData','Cache','GPUCache','Crashpad','Code Cache','DawnWebGPUCache')) {

            $bytes += Remove-DirectoryContentsSafe -Path (Join-Path $root $name)

        }

    }
    Write-VSO7Log ("VS Code caches limpiadas: aprox. {0}" -f (Format-BytesVSO $bytes)) 'CHANGE'

}

function Remove-OldDumpFilesVSO {

    param([int]$OlderThanDays = 7)

    $cutoff = (Get-Date).AddDays(-$OlderThanDays)
    [int64]$bytes = 0
    $roots=@()
    try{
        if($script:LocalAppData){
            $roots += Join-ValidatedDescendantPathVSO -Base ([string]$script:LocalAppData) -Relative 'CrashDumps'
        }
    }catch{}
    try{
        if($script:WindowsRoot){
            $roots += Join-ValidatedDescendantPathVSO -Base ([string]$script:WindowsRoot) -Relative 'LiveKernelReports'
        }
    }catch{}
    foreach ($root in @($roots|Select-Object -Unique)) {

        try{
            $safeRoot=Assert-CleanupPathAllowedVSO -Path $root
        }catch{
            Write-VSO7Log ("Se omite raiz de dumps fuera de allowlist: {0}"-f$root) 'WARN';
            continue
        }
        if (-not (Test-Path -LiteralPath $safeRoot -PathType Container)) {
            continue
        }
        $rootItem=Get-Item -LiteralPath $safeRoot -Force -ErrorAction SilentlyContinue
        if($null-eq$rootItem -or (($rootItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0)){
            Write-VSO7Log ("Se omite raiz de dumps insegura: {0}"-f$safeRoot) 'WARN';
            continue
        }
        foreach ($file in @(Get-FilesNoReparseVSO -Root $safeRoot)) {

            if ($file.Extension -ine '.dmp' -or $file.LastWriteTime -ge $cutoff) {
                continue
            }
            try {

                $length = [int64]$file.Length
                Remove-VSO7CleanupFileSafeVSO -Path $file.FullName -AllowedRoot $safeRoot
                $bytes += $length

            } catch {
                Write-VSO7Log ("No se pudo borrar dump de forma segura: {0} ({1})" -f $file.FullName,$_.Exception.Message) 'WARN'
            }

        }

    }
    Write-VSO7Log ("Crash dumps de mas de {0} dias eliminados: aprox. {1}" -f $OlderThanDays,(Format-BytesVSO $bytes)) 'CHANGE'

}

function Invoke-VSOTweak {

    param([Parameter(Mandatory=$true)]$Tweak)

    $id = [string]$Tweak.Id
    switch ($id) {

        'gaming.gamemode' {

            Set-ExtremeRegistryValue -TweakId $id -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AutoGameModeEnabled' -Value 1 -Type DWord

        }
        'gaming.gamedvr' {

            Set-ExtremeRegistryValue -TweakId $id -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' -Name 'AppCaptureEnabled' -Value 0 -Type DWord
            Set-ExtremeRegistryValue -TweakId $id -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -Value 0 -Type DWord

        }
        'ui.transparency' {

            Set-ExtremeRegistryValue -TweakId $id -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name 'EnableTransparency' -Value 0 -Type DWord

        }
        'ui.animations' {

            Set-ExtremeRegistryValue -TweakId $id -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name 'VisualFXSetting' -Value 2 -Type DWord
            Set-ExtremeRegistryValue -TweakId $id -Path 'HKCU:\Control Panel\Desktop\WindowMetrics' -Name 'MinAnimate' -Value '0' -Type String

        }
        'delivery.p2p' {

            Set-ExtremeRegistryValue -TweakId $id -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' -Name 'DODownloadMode' -Value 0 -Type DWord

        }
        'cleanup.temp' {
            Remove-OldTempFiles -OlderThanDays 7
        }
        'cleanup.shaders' {

            [int64]$bytes = 0
            foreach ($path in @("$script:LocalAppData\NVIDIA\DXCache","$script:LocalAppData\NVIDIA\GLCache","$script:LocalAppData\D3DSCache")) {

                $bytes += Remove-DirectoryContentsSafe -Path $path

            }
            Write-VSO7Log ("Shaders limpiados: aprox. {0}" -f (Format-BytesVSO $bytes)) 'CHANGE'

        }
        'cleanup.dev' {

            [int64]$bytes=0
            foreach($path in @(Get-AllowedCleanupPathsVSO|Where-Object{
                $_ -match '(?i)\\npm-cache$|\\pip\\Cache$'
            })){

                $bytes += Remove-DirectoryContentsSafe -Path $path

            }
            Write-VSO7Log ("Caches de desarrollo npm/pip limpiadas directamente desde rutas locales validadas: aprox. {0}" -f (Format-BytesVSO $bytes)) 'CHANGE'

        }
        'cleanup.vscode' {
            Remove-VSCodeCachesVSO
        }
        'cleanup.spotify' {

            $path = "$script:LocalAppData\Packages\SpotifyAB.SpotifyMusic_zpdnekdrzrea0\LocalCache"
            $bytes = Remove-DirectoryContentsSafe -Path $path
            Write-VSO7Log ("Spotify LocalCache: {0}" -f (Format-BytesVSO $bytes)) 'CHANGE'

        }
        'cleanup.lghub' {

            $bytes = Remove-DirectoryContentsSafe -Path (Join-Path $script:ProgramData 'LGHUB\cache')
            Write-VSO7Log ("LGHUB cache: {0}" -f (Format-BytesVSO $bytes)) 'CHANGE'

        }
        'cleanup.winsxs' {

            Invoke-NativeCommandVSO -FilePath 'dism.exe' -Arguments @('/Online','/Cleanup-Image','/StartComponentCleanup')

        }
        'power.hibernate' {
            Disable-HibernationExtreme -TweakId $id
        }
        'search.indexing' {
            Disable-ExtremeService -TweakId $id -Name 'WSearch'
        }
        'xbox.services' {

            foreach ($service in @('XblAuthManager','XblGameSave','XboxNetApiSvc')) {

                if ($null -ne (Get-VSO7ServiceStatusVSO -Name ([string]$service))) {

                    Disable-ExtremeService -TweakId $id -Name $service

                }

            }

        }
        'telemetry.diagtrack' {
            Disable-ExtremeService -TweakId $id -Name 'DiagTrack'
        }
        'power.usbSuspend' {
            Set-ExtremePowerSetting -TweakId $id -SubGroup 'SUB_USB' -Setting 'USBSELECTIVE' -Value 0
        }
        'power.pcieAspm' {
            Set-ExtremePowerSetting -TweakId $id -SubGroup 'SUB_PCIEXPRESS' -Setting 'ASPM' -Value 0
        }
        'cleanup.fortnite' {

            $path = "$script:LocalAppData\FortniteGame\Saved\PersistentDownloadDir"
            $bytes = Remove-DirectoryContentsSafe -Path $path
            Write-VSO7Log ("Fortnite PersistentDownloadDir: {0}" -f (Format-BytesVSO $bytes)) 'CHANGE'

        }
        'cleanup.bobby' {

            $path = [IO.Path]::GetFullPath("$script:AppData\.minecraft\.bobby").TrimEnd('\')
            $expected = [IO.Path]::GetFullPath((Join-Path $script:AppData '.minecraft\.bobby')).TrimEnd('\')
            if ($path -ne $expected) {
                throw 'La ruta de Bobby no coincide con la ruta protegida esperada.'
            }
            $bytes = Remove-DirectoryContentsSafe -Path $path
            Write-VSO7Log ("Bobby cache vaciada: {0}. No se tocaron logs/crash-reports/saves/Xaero/JourneyMap." -f (Format-BytesVSO -Bytes $bytes)) 'CHANGE'

        }
        'cleanup.dumps' {
            Remove-OldDumpFilesVSO -OlderThanDays 7
        }
        'services.spooler' {
            Disable-ExtremeService -TweakId $id -Name 'Spooler'
        }
        'services.location' {
            Disable-ExtremeService -TweakId $id -Name 'lfsvc'
        }
        'services.bluetooth' {
            Disable-ExtremeService -TweakId $id -Name 'bthserv'
        }
        'virtualization.hyperv' {
            Disable-ExtremeFeature -TweakId $id -Name 'Microsoft-Hyper-V-Hypervisor'
        }
        'virtualization.wsl' {

            Disable-ExtremeFeature -TweakId $id -Name 'Microsoft-Windows-Subsystem-Linux'
            Disable-ExtremeFeature -TweakId $id -Name 'VirtualMachinePlatform'

        }
        'virtualization.sandbox' {
            Disable-ExtremeFeature -TweakId $id -Name 'Containers-DisposableClientVM'
        }
        'security.memoryIntegrity' {

            $locked=Test-SecuritySettingLockedVSO -Kind HVCI
            if($null-eq$locked){
                throw 'No se pudo determinar con certeza Locked de Memory Integrity/HVCI; VSO7 falla cerrado.'
            }
            if($locked){
                throw 'Memory Integrity/HVCI tiene Locked=1; VSO7 no intentara saltarse el bloqueo.'
            }
            Set-ExtremeRegistryValue -TweakId $id -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity' -Name 'Enabled' -Value 0 -Type DWord

        }
        'security.credentialGuard' {

            $locked=Test-CredentialGuardUefiLockVSO
            if($null-eq$locked){
                throw 'No se pudo determinar con certeza el estado UEFI lock de Credential Guard; VSO7 falla cerrado.'
            }
            if($locked){
                throw 'Credential Guard parece usar UEFI lock; VSO7 se niega a forzar su desactivacion.'
            }
            Set-ExtremeRegistryValue -TweakId $id -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name 'LsaCfgFlags' -Value 0 -Type DWord
            Set-ExtremeRegistryValue -TweakId $id -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeviceGuard' -Name 'LsaCfgFlags' -Value 0 -Type DWord

        }
        'security.vbs' {

            $locked=Test-SecuritySettingLockedVSO -Kind VBS
            if($null-eq$locked){
                throw 'No se pudo determinar con certeza Locked de VBS; VSO7 falla cerrado.'
            }
            if($locked){
                throw 'VBS tiene Locked=1; VSO7 no intentara saltarse el bloqueo.'
            }
            Set-ExtremeRegistryValue -TweakId $id -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard' -Name 'EnableVirtualizationBasedSecurity' -Value 0 -Type DWord

        }
        'virtualization.hypervisorLaunchOff' {

            Set-ExtremeBcdValue -TweakId $id -Name 'hypervisorlaunchtype' -Value 'Off'

        }
        default {
            throw ("Tweak desconocido: {0}" -f $id)
        }

    }

}

function Assert-RecoveryBundleRequirementsVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle,[Parameter(Mandatory=$true)][array]$Tweaks)
    $ids=@($Tweaks|ForEach-Object{
        [string]$_.Id
    })
    $missing=@()

    $needsPower=@($ids|Where-Object{
        $_ -in @('power.hibernate','power.usbSuspend','power.pcieAspm')
    }).Count -gt0
    $needsBcd=$ids -contains 'virtualization.hypervisorLaunchOff'
    $needsServices=@($ids|Where-Object{
        $_ -match '^(search\.indexing|xbox\.services|telemetry\.diagtrack|services\.)'
    }).Count -gt0
    $needsFeatures=@($ids|Where-Object{
        $_ -match '^virtualization\.(hyperv|wsl|sandbox)$'
    }).Count -gt0

    function Test-RecoveryFileNonEmptyVSO([string]$Path) {

        try {

            $item=Get-Item -LiteralPath $Path -ErrorAction Stop
            return (-not $item.PSIsContainer -and [int64]$item.Length -gt 0)

        } catch {
            return $false
        }

    }
    function Test-RecoveryJsonVSO([string]$Path) {

        if(-not(Test-RecoveryFileNonEmptyVSO -Path $Path)){
            return $false
        }
        try{
            [void](Get-Content -LiteralPath $Path -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop);
            return $true
        }catch{
            return $false
        }

    }

    if($needsPower -and -not(Test-RecoveryFileNonEmptyVSO -Path (Join-Path $Bundle 'powercfg.txt'))){
        $missing+='powercfg.txt'
    }
    if($needsBcd -and -not(Test-RecoveryFileNonEmptyVSO -Path (Join-Path $Bundle 'BCD_BACKUP'))){
        $missing+='BCD_BACKUP'
    }
    if($needsServices -and -not(Test-RecoveryJsonVSO -Path (Join-Path $Bundle 'services-snapshot.json'))){
        $missing+='services-snapshot.json'
    }
    if($needsFeatures -and -not(Test-RecoveryJsonVSO -Path (Join-Path $Bundle 'optional-features.json'))){
        $missing+='optional-features.json'
    }
    if(-not(Test-RecoveryJsonVSO -Path (Join-Path $Bundle 'seleccion.json'))){
        $missing+='seleccion.json'
    }

    if($missing.Count -gt0){
        throw ("Recuperacion incompleta para la seleccion actual. Faltan: {0}. VSO7 NO aplicara ningun tweak."-f($missing -join ', '))
    }
    return $true

}

function Get-RecoveryStateHashVSO {

    param([string]$Path)
    if([string]::IsNullOrWhiteSpace($Path)-or-not(Test-Path -LiteralPath $Path -PathType Leaf)){
        return $null
    }
    try{
        return (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
    }catch{
        return $null
    }

}

function ConvertTo-VSO7ValidatedRecoveryOrigin {

    param($Object)
    if($null-eq$Object){
        throw 'origin.json esta vacio.'
    }
    $required=@(
        'Schema','Product','Version','RunnerSha256',
        'StateExpectedExists','StateExpectedSha256','StateBundleSha256',
        'ExtremeExpectedExists','ExtremeExpectedSha256','ExtremeBundleSha256',
        'StartupExpectedExists','StartupExpectedSha256','StartupBundleSha256',
        'UpdatedAt','AuthHmacSha256'
    )
    if(-not(Test-VSO7ExactJsonProperties -Object $Object -Required $required)){
        throw 'origin.json no coincide con el esquema permitido.'
    }
    if(-not(Test-VSO7JsonInteger -Value $Object.Schema -Min 5 -Max 5)){
        throw 'Schema de origin.json incompatible.'
    }
    if(-not($Object.Product-is[string])-or[string]$Object.Product-cne'VSO7'){
        throw 'Product invalido en origin.json.'
    }
    if(-not($Object.Version-is[string])-or[string]::IsNullOrWhiteSpace([string]$Object.Version)-or([string]$Object.Version).Length-gt32-or([string]$Object.Version).IndexOf([char]0)-ge0-or([string]$Object.Version).Contains("`r")-or([string]$Object.Version).Contains("`n")){
        throw 'Version invalida en origin.json.'
    }
    if([string]$Object.Version-cne[string]$script:Version){
        throw ('Recovery pertenece a VSO7 {0}; esta build solo acepta bundles autenticados de VSO7 {1}.'-f[string]$Object.Version,[string]$script:Version)
    }
    if(-not($Object.RunnerSha256-is[string])-or([string]$Object.RunnerSha256)-notmatch'^[0-9A-Fa-f]{64}$'){
        throw 'RunnerSha256 invalido en origin.json.'
    }
    if(-not($Object.UpdatedAt-is[string])-or-not(Test-VSO7IsoUtcTimestamp ([string]$Object.UpdatedAt))){
        throw 'UpdatedAt invalido en origin.json.'
    }

    $normalized=[ordered]@{
        Schema=5;
        Product='VSO7';
        Version=[string]$Object.Version;
        RunnerSha256=([string]$Object.RunnerSha256).ToUpperInvariant()
    }
    foreach($spec in @(
        @('StateExpectedExists','StateExpectedSha256','StateBundleSha256'),
        @('ExtremeExpectedExists','ExtremeExpectedSha256','ExtremeBundleSha256'),
        @('StartupExpectedExists','StartupExpectedSha256','StartupBundleSha256')
    )){

        $existsProp=[string]$spec[0];
        $expectedHashProp=[string]$spec[1];
        $bundleHashProp=[string]$spec[2]
        $exists=$Object.($existsProp)
        if(-not($exists-is[bool])){
            throw ("{0} no es booleano en origin.json."-f$existsProp)
        }
        $expectedHash=$Object.($expectedHashProp);
        $bundleHash=$Object.($bundleHashProp)
        if([bool]$exists){

            foreach($pair in @(@($expectedHashProp,$expectedHash),@($bundleHashProp,$bundleHash))){

                if(-not($pair[1]-is[string])-or([string]$pair[1])-notmatch'^[0-9A-Fa-f]{64}$'){
                    throw ("{0} no contiene un SHA-256 valido."-f$pair[0])
                }
                $normalized[[string]$pair[0]]=([string]$pair[1]).ToUpperInvariant()

            }

        }else{

            if($null-ne$expectedHash-or$null-ne$bundleHash){
                throw ("Hashes deben ser null cuando {0}=false."-f$existsProp)
            }
            $normalized[$expectedHashProp]=$null;
            $normalized[$bundleHashProp]=$null

        }
        $normalized[$existsProp]=[bool]$exists

    }
    $normalized['UpdatedAt']=[string]$Object.UpdatedAt
    if(-not($Object.AuthHmacSha256-is[string])-or([string]$Object.AuthHmacSha256)-notmatch'^[0-9A-Fa-f]{64}$'){
        throw 'AuthHmacSha256 invalido en origin.json.'
    }
    $normalized['AuthHmacSha256']=([string]$Object.AuthHmacSha256).ToUpperInvariant()
    return [pscustomobject]$normalized

}
function Assert-VSO7ManagedRecoveryBundleVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        throw 'Ruta Recovery gestionada invalida.'
    }
    $root=[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')
    $full=[IO.Path]::GetFullPath($Path).TrimEnd('\')
    if([IO.Path]::GetDirectoryName($full)-ine$root){
        throw 'El bundle no es hijo directo del RecoveryRoot protegido.'
    }
    [void](Protect-VSO7SecureDirectory -Path $root)
    if(-not(Test-Path -LiteralPath $full -PathType Container)){
        throw 'No existe el bundle Recovery gestionado.'
    }
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Bundle Recovery gestionado invalido/reparse point.'
    }
    Assert-VSO7ExistingSecureDirectoryProvenance -Path $full
    return $full

}

function Get-VSO7RecoveryPublishJournalPathVSO {

    if([string]::IsNullOrWhiteSpace([string]$script:SecureStateRoot)){
        throw 'SecureStateRoot no inicializado para journal de publicacion Recovery.'
    }
    return (Join-Path $script:SecureStateRoot 'recovery-publish-pending.json')

}

function Read-VSO7RecoveryPublishJournalVSO {

    $path=Get-VSO7RecoveryPublishJournalPathVSO
    [void](Protect-VSO7ProtectedFileVSO -Path $path -AllowedParent $script:SecureStateRoot -AllowMissing)
    if(-not(Test-Path -LiteralPath $path -PathType Leaf)){
        return $null
    }
    $item=Get-Item -LiteralPath $path -Force -ErrorAction Stop
    if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or[int64]$item.Length-le0-or[int64]$item.Length-gt262144){
        throw 'Journal de publicacion Recovery invalido/reparse point/excesivo.'
    }
    $obj=Get-Content -LiteralPath $path -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    if(-not(Test-VSO7ExactJsonProperties -Object $obj -Required @('Schema','BundlePath','UpdatedAt'))){
        throw 'Journal de publicacion Recovery con esquema invalido.'
    }
    if(-not(Test-VSO7JsonInteger -Value $obj.Schema -Min 1 -Max 1)){
        throw 'Schema incompatible del journal de publicacion Recovery.'
    }
    if(-not($obj.BundlePath-is[string])-or[string]::IsNullOrWhiteSpace([string]$obj.BundlePath)-or-not[IO.Path]::IsPathRooted([string]$obj.BundlePath)){
        throw 'BundlePath invalido en journal de publicacion Recovery.'
    }
    if(-not($obj.UpdatedAt-is[string])-or-not(Test-VSO7IsoUtcTimestamp ([string]$obj.UpdatedAt))){
        throw 'UpdatedAt invalido en journal de publicacion Recovery.'
    }
    $bundle=Assert-VSO7ManagedRecoveryBundleVSO -Path ([string]$obj.BundlePath)
    return [pscustomobject]@{
        Schema=1;
        BundlePath=$bundle;
        UpdatedAt=[string]$obj.UpdatedAt
    }

}

function Write-VSO7RecoveryPublishJournalVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle)
    $bundleFull=Assert-VSO7ManagedRecoveryBundleVSO -Path $Bundle
    $path=Get-VSO7RecoveryPublishJournalPathVSO
    [void](Protect-VSO7ProtectedFileVSO -Path $path -AllowedParent $script:SecureStateRoot -AllowMissing)
    $tmp=Join-Path $script:SecureStateRoot ('.recovery-publish-'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{

        $obj=[ordered]@{
            Schema=1;
            BundlePath=$bundleFull;
            UpdatedAt=(Get-Date).ToString('o')
        }
        $obj|ConvertTo-Json -Depth 3|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        if(-not(Test-VSO7ExactJsonProperties -Object $check -Required @('Schema','BundlePath','UpdatedAt'))){
            throw 'Temporal del journal Recovery con esquema invalido.'
        }
        if(-not(Test-VSO7JsonInteger -Value $check.Schema -Min 1 -Max 1)){
            throw 'Schema temporal del journal Recovery invalido.'
        }
        if([string]$check.BundlePath-ine$bundleFull-or-not(Test-VSO7IsoUtcTimestamp ([string]$check.UpdatedAt))){
            throw 'Temporal del journal Recovery no coincide con la transaccion.'
        }
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $path)
        $published=Read-VSO7RecoveryPublishJournalVSO
        if($null-eq$published-or[string]$published.BundlePath-ine$bundleFull){
            throw 'Journal de publicacion Recovery no pudo confirmarse.'
        }
        return $bundleFull

    }finally{

        if(Test-Path -LiteralPath $tmp -PathType Leaf){
            try{
                Remove-Item -LiteralPath $tmp -Force -ErrorAction Stop
            }catch{}
        }

    }

}

function Clear-VSO7RecoveryPublishJournalVSO {

    $path=Get-VSO7RecoveryPublishJournalPathVSO
    [void](Protect-VSO7ProtectedFileVSO -Path $path -AllowedParent $script:SecureStateRoot -AllowMissing)
    if(Test-Path -LiteralPath $path -PathType Leaf){

        $item=Get-Item -LiteralPath $path -Force -ErrorAction Stop
        if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'Journal Recovery a limpiar invalido/reparse point.'
        }
        Remove-Item -LiteralPath $path -Force -ErrorAction Stop

    }

}

function Complete-VSO7PendingRecoveryPublishVSO {

    try{

        $journal=Read-VSO7RecoveryPublishJournalVSO
        if($null-eq$journal){
            return $true
        }
        Write-VSO7Log ("Reanudando publicacion Recovery interrumpida para: {0}"-f$journal.BundlePath) 'WARN'
        [void](Publish-VSO7RecoveryGenerationVSO -Bundle ([string]$journal.BundlePath))
        Clear-VSO7RecoveryPublishJournalVSO
        Write-VSO7Log 'Publicacion Recovery pendiente completada y journal retirado.' 'CHANGE'
        return $true

    }catch{

        Write-VSO7Log ("No se pudo completar la publicacion Recovery pendiente: {0}"-f$_.Exception.Message) 'ERROR'
        return $false

    }

}

function Start-VSO7RecoveryPublishTransactionVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle)
    $existing=Read-VSO7RecoveryPublishJournalVSO
    if($null-ne$existing){

        if(-not(Complete-VSO7PendingRecoveryPublishVSO)){
            throw 'Existe una publicacion Recovery anterior pendiente que no pudo reconciliarse.'
        }

    }
    return (Write-VSO7RecoveryPublishJournalVSO -Bundle $Bundle)

}

function Write-RecoveryOriginMetadataVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle)
    $bundleFull=Assert-VSO7ManagedRecoveryBundleVSO -Path $Bundle
    $bundleItem=Get-Item -LiteralPath $bundleFull -Force -ErrorAction Stop
    if(($bundleItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'El bundle Recovery es un reparse point.'
    }
    foreach($target in @($script:StateFile,$script:ExtremeStateFile,$script:StartupStateFile)){
        [void](Protect-VSO7SecureStateLeaf -Path $target -AllowMissing)
    }

    $originPath=Join-Path $bundleFull 'origin.json'
    if(Test-Path -LiteralPath $originPath){

        $originItem=Get-Item -LiteralPath $originPath -Force -ErrorAction Stop
        if($originItem.PSIsContainer-or($originItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'origin.json existente es invalido/reparse point.'
        }

    }
    $stateExpected=Test-Path -LiteralPath $script:StateFile -PathType Leaf
    $extremeExpected=Test-Path -LiteralPath $script:ExtremeStateFile -PathType Leaf
    $startupExpected=Test-Path -LiteralPath $script:StartupStateFile -PathType Leaf
    $bundleState=Join-Path $bundleFull 'state.json';
    $bundleExtreme=Join-Path $bundleFull 'extreme-state.json';
    $bundleStartup=Join-Path $bundleFull 'startup-state.json'
    if((Test-Path -LiteralPath $bundleState -PathType Leaf)-ne[bool]$stateExpected){
        throw 'Presencia de state.json del bundle no coincide con el estado protegido.'
    }
    if((Test-Path -LiteralPath $bundleExtreme -PathType Leaf)-ne[bool]$extremeExpected){
        throw 'Presencia de extreme-state.json del bundle no coincide con el estado protegido.'
    }
    if((Test-Path -LiteralPath $bundleStartup -PathType Leaf)-ne[bool]$startupExpected){
        throw 'Presencia de startup-state.json del bundle no coincide con el estado protegido.'
    }
    if([string]::IsNullOrWhiteSpace([string]$script:RecoveryRunnerHash)-or[string]$script:RecoveryRunnerHash-notmatch'^[A-F0-9]{64}$'){
        throw 'Recovery Runner no tiene una identidad SHA-256 valida al crear origin.json.'
    }
    $meta=[ordered]@{

        Schema=5
        Product='VSO7'
        Version=$script:Version
        RunnerSha256=([string]$script:RecoveryRunnerHash).ToUpperInvariant()
        StateExpectedExists=[bool]$stateExpected
        StateExpectedSha256=(Get-RecoveryStateHashVSO -Path $script:StateFile)
        StateBundleSha256=(Get-RecoveryStateHashVSO -Path $bundleState)
        ExtremeExpectedExists=[bool]$extremeExpected
        ExtremeExpectedSha256=(Get-RecoveryStateHashVSO -Path $script:ExtremeStateFile)
        ExtremeBundleSha256=(Get-RecoveryStateHashVSO -Path $bundleExtreme)
        StartupExpectedExists=[bool]$startupExpected
        StartupExpectedSha256=(Get-RecoveryStateHashVSO -Path $script:StartupStateFile)
        StartupBundleSha256=(Get-RecoveryStateHashVSO -Path $bundleStartup)
        UpdatedAt=(Get-Date).ToString('o')
        AuthHmacSha256=$null

    }
    $meta.AuthHmacSha256=Get-VSO7RecoveryOriginHmacVSO -Origin ([pscustomobject]$meta)
    [void](ConvertTo-VSO7ValidatedRecoveryOrigin -Object ([pscustomobject]$meta))
    $tmp=$originPath+'.tmp'
    if(Test-Path -LiteralPath $tmp){

        $tmpItem=Get-Item -LiteralPath $tmp -Force -ErrorAction Stop
        if($tmpItem.PSIsContainer-or($tmpItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'Temporal origin.json es invalido/reparse point.'
        }
        Remove-Item -LiteralPath $tmp -Force -ErrorAction Stop

    }
    $meta|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
    $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    [void](ConvertTo-VSO7ValidatedRecoveryOrigin -Object $check)
    [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $originPath)
    $check=Get-Content -LiteralPath $originPath -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    [void](ConvertTo-VSO7ValidatedRecoveryOrigin -Object $check)

}

function Get-VSO7RecoveryPublishedDataRootVSO {

    param([Parameter(Mandatory=$true)][string]$BundleRoot)
    if([string]::IsNullOrWhiteSpace($BundleRoot)-or-not[IO.Path]::IsPathRooted($BundleRoot)){
        throw 'Ruta raiz Recovery invalida.'
    }
    $root=[IO.Path]::GetFullPath($BundleRoot).TrimEnd('\')
    if(-not(Test-Path -LiteralPath $root -PathType Container)){
        throw 'No existe la raiz del bundle Recovery.'
    }
    $rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop
    if(-not$rootItem.PSIsContainer-or($rootItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Raiz Recovery invalida/reparse point.'
    }

    $pointer=Join-Path $root 'CurrentGeneration.txt'
    $generations=Join-Path $root 'Generations'
    if(-not(Test-Path -LiteralPath $pointer -PathType Leaf)){

        if(Test-Path -LiteralPath $generations){

            throw 'Recovery contiene Generations pero no un CurrentGeneration.txt publicado; se conserva fail-closed.'

        }
        # Compatibilidad con bundles 7.0.0 anteriores al almacenamiento generacional.
        return $root

    }

    $pointerItem=Get-Item -LiteralPath $pointer -Force -ErrorAction Stop
    if($pointerItem.PSIsContainer-or($pointerItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or[int64]$pointerItem.Length-le0-or[int64]$pointerItem.Length-gt128){
        throw 'CurrentGeneration.txt invalido/reparse point/excesivo.'
    }
    $name=[string](Get-Content -LiteralPath $pointer -Raw -ErrorAction Stop).Trim()
    if($name-notmatch'^gen_[0-9a-fA-F]{32}$'){
        throw 'CurrentGeneration.txt contiene un identificador invalido.'
    }

    if(-not(Test-Path -LiteralPath $generations -PathType Container)){
        throw 'Falta Generations para la generacion publicada.'
    }
    $generationsItem=Get-Item -LiteralPath $generations -Force -ErrorAction Stop
    if(-not$generationsItem.PSIsContainer-or($generationsItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Generations invalido/reparse point.'
    }
    $data=[IO.Path]::GetFullPath((Join-Path $generations $name)).TrimEnd('\')
    if([IO.Path]::GetDirectoryName($data)-ine[IO.Path]::GetFullPath($generations).TrimEnd('\')){
        throw 'La generacion publicada escapa de Generations.'
    }
    if(-not(Test-Path -LiteralPath $data -PathType Container)){
        throw 'La generacion Recovery publicada no existe.'
    }
    $dataItem=Get-Item -LiteralPath $data -Force -ErrorAction Stop
    if(-not$dataItem.PSIsContainer-or($dataItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Generacion Recovery publicada invalida/reparse point.'
    }
    return $data

}

function Test-VSO7RecoveryGenerationDataVSO {

    param([Parameter(Mandatory=$true)][string]$DataRoot)
    $root=[IO.Path]::GetFullPath($DataRoot).TrimEnd('\')
    if(-not(Test-Path -LiteralPath $root -PathType Container)){
        throw 'Generacion Recovery a validar ausente.'
    }
    $item=Get-Item -LiteralPath $root -Force -ErrorAction Stop
    if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Generacion Recovery a validar invalida/reparse point.'
    }
    $originPath=Join-Path $root 'origin.json'
    if(-not(Test-Path -LiteralPath $originPath -PathType Leaf)){
        throw 'Generacion Recovery sin origin.json.'
    }
    $originItem=Get-Item -LiteralPath $originPath -Force -ErrorAction Stop
    if($originItem.PSIsContainer-or($originItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or[int64]$originItem.Length-le0-or[int64]$originItem.Length-gt262144){
        throw 'origin.json generacional invalido.'
    }
    $origin=ConvertTo-VSO7ValidatedRecoveryOrigin -Object (Get-Content -LiteralPath $originPath -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
    [void](Assert-VSO7RecoveryOriginAuthenticationVSO -Origin $origin)
    [void](Assert-VSO7RecoveryOriginMatchesProtectedStateVSO -Origin $origin)

    foreach($binding in @(
        @('state.json','StateExpectedExists','StateBundleSha256'),
        @('extreme-state.json','ExtremeExpectedExists','ExtremeBundleSha256'),
        @('startup-state.json','StartupExpectedExists','StartupBundleSha256')
    )){

        $path=Join-Path $root ([string]$binding[0]);
        $expected=[bool]$origin.([string]$binding[1]);
        $present=Test-Path -LiteralPath $path -PathType Leaf
        if($present-ne$expected){
            throw ("Generacion Recovery incoherente: presencia de {0}."-f$binding[0])
        }
        if($present){

            $fi=Get-Item -LiteralPath $path -Force -ErrorAction Stop
            if($fi.PSIsContainer-or($fi.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ("Archivo generacional {0} invalido/reparse point."-f$binding[0])
            }
            $hash=Get-RecoveryStateHashVSO -Path $path
            if($hash-ine[string]$origin.([string]$binding[2])){
                throw ("Hash generacional no coincide para {0}."-f$binding[0])
            }

        }

    }

    $normal=Join-Path $root 'state.json'
    if(Test-Path -LiteralPath $normal -PathType Leaf){
        [void](ConvertTo-VSO7ValidatedNormalState -Object (Get-Content -LiteralPath $normal -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))
    }
    $extreme=Join-Path $root 'extreme-state.json'
    if(Test-Path -LiteralPath $extreme -PathType Leaf){
        [void](ConvertTo-VSO7ValidatedExtremeState -Object (Get-Content -LiteralPath $extreme -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))
    }
    $startup=Join-Path $root 'startup-state.json'
    if(Test-Path -LiteralPath $startup -PathType Leaf){

        $oldStartupFile=$script:StartupStateFile
        try{

            $script:StartupStateFile=$startup
            $validatedStartup=ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $startup -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
            $stash=Get-VSO7StartupStashRoot
            foreach($entry in @($validatedStartup.Disabled|Where-Object{
                [string]$_.Type-ieq'File'
            })){

                $backup=[string]$entry.BackupPath
                if(Test-Path -LiteralPath $backup -PathType Leaf){

                    [void](Assert-VSO7StartupPathRuntimeSafe -Path $backup -AllowedParents @($stash))
                    $hash=(Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                    if($hash-ine[string]$entry.Sha256){
                        throw ("Backup Startup generacional alterado: {0}"-f$entry.Name)
                    }

                }elseif([string]$entry.Status-ieq'Disabled'){

                    throw ("Falta backup Startup generacional requerido: {0}"-f$entry.Name)

                }

            }

        }finally{
            $script:StartupStateFile=$oldStartupFile
        }

    }
    return $true

}

function Publish-VSO7RecoveryGenerationVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle)
    $bundleFull=Assert-VSO7ManagedRecoveryBundleVSO -Path $Bundle

    # Un corte duro antes de mover/publicar puede dejar staging incompleto como hijo
    # directo de RecoveryRoot. Nunca es visible para rollback; al entrar con el mutex
    # exclusivo de VSO7 podemos retirarlo de forma segura antes de otra publicacion.
    foreach($orphan in @(Get-ChildItem -LiteralPath $script:RecoveryRoot -Directory -Force -ErrorAction Stop|Where-Object{
        [string]$_.Name-match'^GenerationStage_[0-9a-fA-F]{32}$'
    })){

        try{

            if(($orphan.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw 'Staging Recovery huerfano es reparse point.'
            }
            if([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($orphan.FullName).TrimEnd('\'))-ine[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')){
                throw 'Staging Recovery huerfano fuera de RecoveryRoot.'
            }
            Assert-VSO7ExistingSecureDirectoryProvenance -Path $orphan.FullName
            Remove-Item -LiteralPath $orphan.FullName -Recurse -Force -ErrorAction Stop

        }catch{
            Write-VSO7Log ("No se pudo limpiar staging Recovery huerfano; se conserva: {0}"-f$_.Exception.Message) 'WARN'
        }

    }

    $stageName='GenerationStage_'+[guid]::NewGuid().ToString('N')
    $stage=Protect-VSO7SecureDirectory -Path (Join-Path $script:RecoveryRoot $stageName)
    $generationName='gen_'+[guid]::NewGuid().ToString('N')
    $generationsRoot=$null;
    $finalGeneration=$null;
    $previousName=$null
    try{

        # Captura coherente de los tres journals protegidos en una generacion aislada.
        foreach($target in @($script:StateFile,$script:ExtremeStateFile,$script:StartupStateFile)){
            [void](Protect-VSO7SecureStateLeaf -Path $target -AllowMissing)
        }
        if(Test-Path -LiteralPath $script:StateFile -PathType Leaf){
            [void](Copy-VSO7FileAtomicallyVSO -SourcePath $script:StateFile -DestinationPath (Join-Path $stage 'state.json'))
        }
        if(Test-Path -LiteralPath $script:ExtremeStateFile -PathType Leaf){
            [void](Copy-VSO7FileAtomicallyVSO -SourcePath $script:ExtremeStateFile -DestinationPath (Join-Path $stage 'extreme-state.json'))
        }
        if(Test-Path -LiteralPath $script:StartupStateFile -PathType Leaf){

            $oldStartup=$script:StartupState
            try{

                $startupObject=Get-Content -LiteralPath $script:StartupStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
                $script:StartupState=ConvertTo-VSO7ValidatedStartupState -Object $startupObject
                Export-StartupStateToBundleVSO -Bundle $stage

            }finally{
                $script:StartupState=$oldStartup
            }

        }
        Write-RecoveryOriginMetadataVSO -Bundle $stage
        [void](Test-VSO7RecoveryGenerationDataVSO -DataRoot $stage)

        $generationsRoot=Protect-VSO7SecureDirectory -Path (Join-Path $bundleFull 'Generations')
        $pointer=Join-Path $bundleFull 'CurrentGeneration.txt'
        if(Test-Path -LiteralPath $pointer -PathType Leaf){

            $pointerItem=Get-Item -LiteralPath $pointer -Force -ErrorAction Stop
            if($pointerItem.PSIsContainer-or($pointerItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or[int64]$pointerItem.Length-gt128){
                throw 'CurrentGeneration.txt preexistente invalido.'
            }
            $previousName=[string](Get-Content -LiteralPath $pointer -Raw -ErrorAction Stop).Trim()
            if($previousName-notmatch'^gen_[0-9a-fA-F]{32}$'){
                throw 'CurrentGeneration.txt preexistente contiene un identificador invalido.'
            }
            $previousPath=Join-Path $generationsRoot $previousName
            if(-not(Test-Path -LiteralPath $previousPath -PathType Container)){
                throw 'CurrentGeneration.txt preexistente apunta a una generacion ausente.'
            }

        }

        $finalGeneration=[IO.Path]::GetFullPath((Join-Path $generationsRoot $generationName)).TrimEnd('\')
        if([IO.Path]::GetDirectoryName($finalGeneration)-ine[IO.Path]::GetFullPath($generationsRoot).TrimEnd('\')){
            throw 'Destino generacional fuera de Generations.'
        }
        if(Test-Path -LiteralPath $finalGeneration){
            throw 'Colision inesperada de nombre generacional.'
        }
        [IO.Directory]::Move($stage,$finalGeneration)
        $stage=$null
        Assert-VSO7ExistingSecureDirectoryProvenance -Path $finalGeneration
        [void](Test-VSO7RecoveryGenerationDataVSO -DataRoot $finalGeneration)

        # UNICO punto de publicacion: el puntero cambia atomically despues de que la
        # generacion completa, sus hashes y HMAC hayan sido verificados.
        $pointerTemp=Join-Path $bundleFull ('.CurrentGeneration-'+[guid]::NewGuid().ToString('N')+'.tmp')
        try{

            Set-Content -LiteralPath $pointerTemp -Value $generationName -Encoding ASCII -Force -ErrorAction Stop
            [void](Commit-VSO7AtomicFileVSO -SourcePath $pointerTemp -DestinationPath $pointer)

        }finally{

            if(Test-Path -LiteralPath $pointerTemp -PathType Leaf){
                try{
                    Remove-Item -LiteralPath $pointerTemp -Force -ErrorAction Stop
                }catch{}
            }

        }
        $published=Get-VSO7RecoveryPublishedDataRootVSO -BundleRoot $bundleFull
        if([IO.Path]::GetFullPath($published).TrimEnd('\')-ine$finalGeneration){
            throw 'CurrentGeneration.txt no publico la generacion esperada.'
        }
        [void](Test-VSO7RecoveryGenerationDataVSO -DataRoot $published)

        # Conservar la generacion anterior como fallback de crash; las mas antiguas
        # son solo historico y se pueden retirar DESPUES de publicar la nueva.
        foreach($candidate in @(Get-ChildItem -LiteralPath $generationsRoot -Directory -Force -ErrorAction Stop)){

            if([string]$candidate.Name-ieq$generationName-or(-not[string]::IsNullOrWhiteSpace($previousName)-and[string]$candidate.Name-ieq$previousName)){
                continue
            }
            if([string]$candidate.Name-notmatch'^gen_[0-9a-fA-F]{32}$'){
                continue
            }
            try{

                if(($candidate.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                    throw 'Generacion historica reparse point.'
                }
                Assert-VSO7ExistingSecureDirectoryProvenance -Path $candidate.FullName
                Remove-Item -LiteralPath $candidate.FullName -Recurse -Force -ErrorAction Stop

            }catch{
                Write-VSO7Log ("No se pudo retirar una generacion Recovery historica; se conserva: {0}"-f$_.Exception.Message) 'WARN'
            }

        }
        return $published

    }catch{

        # Si el crash/fallo ocurre antes de publicar CurrentGeneration, la generacion
        # anterior sigue siendo la unica visible. Un staging huerfano nunca se publica.
        throw

    }finally{

        if(-not[string]::IsNullOrWhiteSpace([string]$stage)-and(Test-Path -LiteralPath $stage -PathType Container)){

            try{

                $stageItem=Get-Item -LiteralPath $stage -Force -ErrorAction Stop
                if(($stageItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-eq0){
                    Assert-VSO7ExistingSecureDirectoryProvenance -Path $stage;
                    Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction Stop
                }

            }catch{
                Write-VSO7Log ("No se pudo limpiar staging Recovery no publicado: {0}"-f$_.Exception.Message) 'WARN'
            }

        }

    }

}

function Test-VSO7RecoveryDesiredStateAlreadyCommittedVSO {

    param(
        [Parameter(Mandatory=$true)][ValidateSet('Normal','Extreme','Startup')][string]$Kind,
        [Parameter(Mandatory=$true)][string]$SourcePath,
        [Parameter(Mandatory=$true)][string]$TargetPath
    )
    $sourceExists=Test-Path -LiteralPath $SourcePath -PathType Leaf
    $targetExists=Test-Path -LiteralPath $TargetPath -PathType Leaf
    if($sourceExists-ne$targetExists){
        return $false
    }
    if(-not$sourceExists){
        return $true
    }
    try{

        $sourceObj=Get-Content -LiteralPath $SourcePath -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        $targetObj=Get-Content -LiteralPath $TargetPath -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        if($Kind-eq'Normal'){
            $a=ConvertTo-VSO7ValidatedNormalState -Object $sourceObj;
            $b=ConvertTo-VSO7ValidatedNormalState -Object $targetObj
        }
        elseif($Kind-eq'Extreme'){
            $a=ConvertTo-VSO7ValidatedExtremeState -Object $sourceObj;
            $b=ConvertTo-VSO7ValidatedExtremeState -Object $targetObj
        }
        else{

            $old=$script:StartupStateFile
            try{
                $script:StartupStateFile=$TargetPath;
                $a=ConvertTo-VSO7ValidatedStartupState -Object $sourceObj;
                $b=ConvertTo-VSO7ValidatedStartupState -Object $targetObj
            }finally{
                $script:StartupStateFile=$old
            }

        }
        return (($a|ConvertTo-Json -Depth 30 -Compress)-ceq($b|ConvertTo-Json -Depth 30 -Compress))

    }catch{
        return $false
    }

}

function Get-VSO7RecoveryReconcileJournalPathVSO {

    if([string]::IsNullOrWhiteSpace([string]$script:SecureStateRoot)){
        throw 'SecureStateRoot no inicializado para journal Recovery.'
    }
    return (Join-Path ([string]$script:SecureStateRoot) 'recovery-reconcile-pending.json')

}

function ConvertTo-VSO7ValidatedRecoveryReconcileJournalVSO {

    param($Object)
    if($null-eq$Object-or-not(Test-VSO7ExactJsonProperties -Object $Object -Required @('SchemaVersion','Version','StagePath','CreatedAt'))){
        throw 'Journal de reconciliacion Recovery invalido.'
    }
    if(-not(Test-VSO7JsonInteger -Value $Object.SchemaVersion -Min 1 -Max 1)){
        throw 'SchemaVersion de journal Recovery incompatible.'
    }
    if(-not($Object.Version-is[string])-or[string]$Object.Version-cne[string]$script:Version){
        throw 'Journal Recovery pertenece a otra version de VSO7.'
    }
    if(-not($Object.StagePath-is[string])-or[string]::IsNullOrWhiteSpace([string]$Object.StagePath)){
        throw 'StagePath ausente en journal Recovery.'
    }
    if(-not($Object.CreatedAt-is[string])-or-not(Test-VSO7IsoUtcTimestamp ([string]$Object.CreatedAt))){
        throw 'CreatedAt invalido en journal Recovery.'
    }
    $stage=Assert-VSO7ManagedRecoveryBundleVSO -Path ([string]$Object.StagePath)
    if([IO.Path]::GetFileName($stage)-notlike'RestoreStaging_*'){
        throw 'El journal Recovery solo puede referenciar staging protegido de VSO7.'
    }
    return [pscustomobject]@{
        SchemaVersion=1;
        Version=$script:Version;
        StagePath=$stage;
        CreatedAt=[string]$Object.CreatedAt
    }

}

function Get-VSO7RecoveryReconcileJournalVSO {

    $path=Get-VSO7RecoveryReconcileJournalPathVSO
    if(-not(Test-Path -LiteralPath $path -PathType Leaf)){
        return $null
    }
    [void](Protect-VSO7SecureStateLeaf -Path $path)
    $item=Get-Item -LiteralPath $path -Force -ErrorAction Stop
    if([int64]$item.Length-le0-or[int64]$item.Length-gt262144){
        throw 'Journal Recovery tiene tamano invalido.'
    }
    $obj=Get-Content -LiteralPath $path -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    return (ConvertTo-VSO7ValidatedRecoveryReconcileJournalVSO -Object $obj)

}

function Write-VSO7RecoveryReconcileJournalVSO {

    param([Parameter(Mandatory=$true)][string]$StagePath)
    $stage=Assert-VSO7ManagedRecoveryBundleVSO -Path $StagePath
    if([IO.Path]::GetFileName($stage)-notlike'RestoreStaging_*'){
        throw 'Solo un staging protegido puede iniciar journal de reconciliacion.'
    }
    $path=Get-VSO7RecoveryReconcileJournalPathVSO
    $existing=Get-VSO7RecoveryReconcileJournalVSO
    if($null-ne$existing){

        if([string]$existing.StagePath-ine$stage){
            throw 'Ya existe otra reconciliacion Recovery pendiente; VSO7 no la sobrescribira.'
        }
        return $path

    }
    $data=[pscustomobject]@{
        SchemaVersion=1;
        Version=$script:Version;
        StagePath=$stage;
        CreatedAt=(Get-Date).ToString('o')
    }
    [void](ConvertTo-VSO7ValidatedRecoveryReconcileJournalVSO -Object $data)
    $tmp=$path+'.tmp'
    try{

        $data|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedRecoveryReconcileJournalVSO -Object (Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $path)

    }finally{
        if(Test-Path -LiteralPath $tmp -PathType Leaf){
            try{
                Remove-Item -LiteralPath $tmp -Force -ErrorAction Stop
            }catch{}
        }
    }
    return $path

}

function Clear-VSO7RecoveryReconcileJournalVSO {

    $path=Get-VSO7RecoveryReconcileJournalPathVSO
    if(-not(Test-Path -LiteralPath $path)){
        return
    }
    [void](Protect-VSO7SecureStateLeaf -Path $path)
    Remove-Item -LiteralPath $path -Force -ErrorAction Stop

}

function Complete-VSO7PendingRecoveryReconcileVSO {

    $journal=Get-VSO7RecoveryReconcileJournalVSO
    if($null-eq$journal){
        return $true
    }
    Write-VSO7Log ("VSO7 encontro una reconciliacion Recovery interrumpida; reanudando desde staging protegido: {0}"-f$journal.StagePath) 'WARN'
    try{

        if(-not(Sync-RecoveryStateToOriginalVSO -Bundle ([string]$journal.StagePath) -ResumeJournal)){
            return $false
        }
        return $true

    }catch{

        Write-VSO7Log ("No se pudo completar la reconciliacion Recovery pendiente: {0}"-f$_.Exception.Message) 'ERROR'
        return $false

    }

}

function Sync-RecoveryStateToOriginalVSO {

    param([Parameter(Mandatory=$true)][string]$Bundle,[switch]$ResumeJournal)
    try{

        $bundleFull=Assert-VSO7ManagedRecoveryBundleVSO -Path $Bundle
        if([IO.Path]::GetFileName($bundleFull)-notlike'RestoreStaging_*'){
            throw 'La reconciliacion solo acepta staging protegido creado por VSO7.'
        }
        $bundleItem=Get-Item -LiteralPath $bundleFull -Force -ErrorAction Stop
        if(($bundleItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'El bundle Recovery es un reparse point.'
        }
        $originPath=Join-Path $bundleFull 'origin.json'
        if(-not(Test-Path -LiteralPath $originPath -PathType Leaf)){
            throw 'Falta origin.json.'
        }
        $originItem=Get-Item -LiteralPath $originPath -Force -ErrorAction Stop
        if(($originItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'origin.json es un reparse point.'
        }
        $origin=ConvertTo-VSO7ValidatedRecoveryOrigin -Object (Get-Content -LiteralPath $originPath -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
        [void](Assert-VSO7RecoveryOriginAuthenticationVSO -Origin $origin)

        $specs=@(
            [pscustomobject]@{
            Kind='Normal';BundleName='state.json';Target=[string]$script:StateFile;ExistsProp='StateExpectedExists';HashProp='StateExpectedSha256'
        },
            [pscustomobject]@{
            Kind='Extreme';BundleName='extreme-state.json';Target=[string]$script:ExtremeStateFile;ExistsProp='ExtremeExpectedExists';HashProp='ExtremeExpectedSha256'
        },
            [pscustomobject]@{
            Kind='Startup';BundleName='startup-state.json';Target=[string]$script:StartupStateFile;ExistsProp='StartupExpectedExists';HashProp='StartupExpectedSha256'
        }
        )
        foreach($spec in $specs){

            [void](Protect-VSO7SecureStateLeaf -Path $spec.Target -AllowMissing)
            $expectedExists=[bool]$origin.($spec.ExistsProp)
            $currentExists=Test-Path -LiteralPath $spec.Target -PathType Leaf
            $source=Join-Path $bundleFull $spec.BundleName
            $sourceExists=Test-Path -LiteralPath $source -PathType Leaf
            if($sourceExists){

                $sourceItem=Get-Item -LiteralPath $source -Force -ErrorAction Stop
                if(($sourceItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                    throw ("{0} es un reparse point."-f$spec.BundleName)
                }

            }
            # Para crash-resume se acepta exactamente uno de dos estados protegidos:
            # el hash original autenticado por origin.json (aun no commitado), o el
            # hash residual del staging protegido (este componente ya fue commitado).
            $matchesOriginal=($currentExists-eq$expectedExists)
            if($matchesOriginal-and$expectedExists){
                $matchesOriginal=((Get-RecoveryStateHashVSO -Path $spec.Target)-ieq[string]$origin.($spec.HashProp))
            }
            $matchesDesired=Test-VSO7RecoveryDesiredStateAlreadyCommittedVSO -Kind ([string]$spec.Kind) -SourcePath $source -TargetPath ([string]$spec.Target)
            if(-not$matchesOriginal-and-not$matchesDesired){
                throw ("Estado protegido {0} no coincide ni con preestado autenticado ni con residual de staging; reconciliacion bloqueada."-f$spec.Kind)
            }

        }

        if($ResumeJournal){

            $journal=Get-VSO7RecoveryReconcileJournalVSO
            if($null-eq$journal-or[string]$journal.StagePath-ine$bundleFull){
                throw 'Journal Recovery ausente o no corresponde al staging que intenta reanudarse.'
            }

        }else{

            [void](Write-VSO7RecoveryReconcileJournalVSO -StagePath $bundleFull)

        }

        # Normal y EXTREMO no contienen rutas de archivos externas; se validan y escriben solo en SecureStateRoot.
        foreach($spec in @($specs|Where-Object{
            $_.Kind-in@('Normal','Extreme')
        })){

            $source=Join-Path $bundleFull $spec.BundleName
            if(-not(Test-Path -LiteralPath $source -PathType Leaf)){
                continue
            }
            $obj=Get-Content -LiteralPath $source -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
            $validated=if($spec.Kind-eq'Normal'){
                ConvertTo-VSO7ValidatedNormalState -Object $obj
            }else{
                ConvertTo-VSO7ValidatedExtremeState -Object $obj
            }
            $tmp=$spec.Target+'.vso-recovery.tmp'
            if(Test-Path -LiteralPath $tmp){

                $tmpItem=Get-Item -LiteralPath $tmp -Force -ErrorAction Stop
                if($tmpItem.PSIsContainer-or($tmpItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                    throw ("Temporal de estado {0} invalido."-f$spec.Kind)
                }
                Remove-Item -LiteralPath $tmp -Force -ErrorAction Stop

            }
            ($validated|ConvertTo-Json -Depth 20)|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
            $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
            if($spec.Kind-eq'Normal'){
                [void](ConvertTo-VSO7ValidatedNormalState -Object $check)
            }else{
                [void](ConvertTo-VSO7ValidatedExtremeState -Object $check)
            }
            [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $spec.Target)
            [void](Protect-VSO7SecureStateLeaf -Path $spec.Target)

        }

        # Startup necesita trasladar/reconciliar tambien los backups asociados sin confiar en BackupPath del JSON.
        $startupSpec=@($specs|Where-Object{
            $_.Kind-eq'Startup'
        })[0]
        $startupSource=Join-Path $bundleFull $startupSpec.BundleName
        if(Test-Path -LiteralPath $startupSource -PathType Leaf){

            $oldStartupFile=$script:StartupStateFile
            $oldSecureState=$null
            try{

                $script:StartupStateFile=$startupSpec.Target
                if(Test-Path -LiteralPath $startupSpec.Target -PathType Leaf){

                    $oldSecureState=ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $startupSpec.Target -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)

                }

                $script:StartupStateFile=$startupSource
                $bundleStash=Get-VSO7StartupStashRoot
                $bundleState=ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $startupSource -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)

                $script:StartupStateFile=$startupSpec.Target
                $secureStash=Get-VSO7StartupStashRoot
                $fileEntries=@($bundleState.Disabled|Where-Object{
                    [string]$_.Type-ieq'File'
                })
                if($fileEntries.Count-gt0){

                    if(Test-Path -LiteralPath $secureStash){

                        [void](Protect-VSO7SecureDirectory -Path $secureStash)

                    }else{

                        [IO.Directory]::CreateDirectory($secureStash)|Out-Null
                        $stashDi=New-Object IO.DirectoryInfo($secureStash)
                        $stashDi.SetAccessControl((New-VSO7LockedDirectoryAcl))
                        [void](Protect-VSO7SecureDirectory -Path $secureStash)

                    }

                }

                foreach($entry in $fileEntries){

                    $sourceBackup=[string]$entry.BackupPath
                    $destBackup=[IO.Path]::GetFullPath((Join-Path $secureStash ([string]$entry.BackupName)))
                    if(-not(Test-VSO7StartupDirectChildPath -Path $destBackup -AllowedParents @($secureStash))){
                        throw 'Destino de backup Startup fuera del SecureStateRoot.'
                    }
                    $sourceExists=Test-Path -LiteralPath $sourceBackup -PathType Leaf
                    $destExists=Test-Path -LiteralPath $destBackup -PathType Leaf
                    if($sourceExists){

                        [void](Assert-VSO7StartupPathRuntimeSafe -Path $sourceBackup -AllowedParents @($bundleStash))
                        $sourceHash=(Get-FileHash -LiteralPath $sourceBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                        if($sourceHash-ine[string]$entry.Sha256){
                            throw ("Backup Startup del bundle alterado: {0}"-f$entry.Name)
                        }

                    }
                    if($destExists){

                        [void](Assert-VSO7StartupPathRuntimeSafe -Path $destBackup -AllowedParents @($secureStash))
                        $destHash=(Get-FileHash -LiteralPath $destBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                        if($destHash-ine[string]$entry.Sha256){
                            throw ("Backup Startup protegido no coincide: {0}"-f$entry.Name)
                        }

                    }elseif($sourceExists){

                        Copy-Item -LiteralPath $sourceBackup -Destination $destBackup -ErrorAction Stop
                        [void](Assert-VSO7StartupPathRuntimeSafe -Path $destBackup -AllowedParents @($secureStash))
                        $destHash=(Get-FileHash -LiteralPath $destBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                        if($destHash-ine[string]$entry.Sha256){
                            throw 'Copia de backup Startup al estado protegido no coincide.'
                        }

                    }elseif([string]$entry.Status-ieq'Disabled'){

                        throw ("Falta backup Startup necesario para conservar rollback: {0}"-f$entry.Name)

                    }

                }

                # Al cambiar StartupStateFile, el validador reconstruye BackupPath bajo el stash seguro actual.
                $secureState=ConvertTo-VSO7ValidatedStartupState -Object ([pscustomobject]$bundleState)
                $tmp=$startupSpec.Target+'.vso-recovery.tmp'
                if(Test-Path -LiteralPath $tmp){

                    $tmpItem=Get-Item -LiteralPath $tmp -Force -ErrorAction Stop
                    if($tmpItem.PSIsContainer-or($tmpItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                        throw 'Temporal Startup protegido invalido.'
                    }
                    Remove-Item -LiteralPath $tmp -Force -ErrorAction Stop

                }
                ($secureState|ConvertTo-Json -Depth 10)|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
                $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
                [void](ConvertTo-VSO7ValidatedStartupState -Object $check)
                [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $startupSpec.Target)
                [void](Protect-VSO7SecureStateLeaf -Path $startupSpec.Target)

                # Elimina solo backups que pertenecian al estado protegido anterior y que ya fueron restaurados.
                if($null-ne$oldSecureState){

                    $keep=@{}
                    foreach($entry in @($secureState.Disabled|Where-Object{
                        [string]$_.Type-ieq'File'
                    })){
                        $keep[([string]$entry.BackupName).ToLowerInvariant()]=$true
                    }
                    foreach($oldEntry in @($oldSecureState.Disabled|Where-Object{
                        [string]$_.Type-ieq'File'
                    })){

                        $oldName=([string]$oldEntry.BackupName).ToLowerInvariant()
                        if($keep.ContainsKey($oldName)){
                            continue
                        }
                        $oldBackup=[string]$oldEntry.BackupPath
                        if(Test-Path -LiteralPath $oldBackup -PathType Leaf){

                            [void](Assert-VSO7StartupPathRuntimeSafe -Path $oldBackup -AllowedParents @($secureStash))
                            $oldHash=(Get-FileHash -LiteralPath $oldBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                            if($oldHash-ieq[string]$oldEntry.Sha256){
                                Remove-Item -LiteralPath $oldBackup -Force -ErrorAction Stop
                            }else{
                                Write-VSO7Log ("Backup Startup protegido cambiado externamente; se conserva: {0}"-f$oldBackup) 'WARN'
                            }

                        }

                    }

                }

            }finally{
                $script:StartupStateFile=$oldStartupFile
            }

        }

        Clear-VSO7RecoveryReconcileJournalVSO
        Write-VSO7Log 'Estado Recovery reconciliado exclusivamente con el almacenamiento protegido de VSO7.' 'CHANGE'
        return $true

    }catch{

        Write-VSO7Log ("No se pudo reconciliar Recovery con el almacenamiento protegido: {0}"-f$_.Exception.Message) 'ERROR'
        return $false

    }

}

function New-RecoveryBundle {

    param([Parameter(Mandatory=$true)][array]$Tweaks)

    $stamp = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
    $recoveryRoot=[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')
    $recoveryItem=Get-Item -LiteralPath $recoveryRoot -Force -ErrorAction Stop
    if(-not$recoveryItem.PSIsContainer-or($recoveryItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'RecoveryRoot invalido/reparse point.'
    }
    $dir = Join-Path $recoveryRoot ("{0}_{1}"-f$stamp,([guid]::NewGuid().ToString('N')))
    if(Test-Path -LiteralPath $dir){
        throw 'Colision inesperada creando Recovery.'
    }
    $dir=Protect-VSO7SecureDirectory -Path $dir
    [void](Protect-VSO7SecureDirectory -Path (Join-Path $dir 'Registro'))

    # El bundle contiene solo datos. El codigo elevado vive exclusivamente en el Recovery Runner protegido de ProgramData.

    try {

        $powerDump = @()
        $powerDump += @(Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/list') -CaptureOutput)
        $powerDump += @(Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/getactivescheme') -CaptureOutput)
        $powerDump += @(Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/query') -CaptureOutput)
        $powerDump | Set-Content -LiteralPath (Join-Path $dir 'powercfg.txt') -Encoding UTF8 -ErrorAction Stop
        $activeGuid = Get-ActivePowerSchemeGuid
        if (-not [string]::IsNullOrWhiteSpace($activeGuid)) {
            Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/export',(Join-Path $dir 'power-plan-active.pow'),$activeGuid)
        }

    } catch {
        Write-VSO7Log ("No se pudo exportar completamente energia: {0}" -f $_.Exception.Message) 'WARN'
    }

    try {

        $bcdText = Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/enum','{current}') -CaptureOutput
        $bcdText | Set-Content -LiteralPath (Join-Path $dir 'bcd-current.txt') -Encoding UTF8 -ErrorAction Stop
        Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/export',(Join-Path $dir 'BCD_BACKUP'))

    } catch {
        Write-VSO7Log ("No se pudo exportar completamente BCD: {0}" -f $_.Exception.Message) 'WARN'
    }

    try {
        CimCmdlets\Get-CimInstance Win32_Service | Select-Object Name,State,StartMode | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $dir 'services-snapshot.json') -Encoding UTF8 -ErrorAction Stop
    } catch {
        Write-VSO7Log ("No se pudo crear snapshot de servicios: {0}" -f $_.Exception.Message) 'WARN'
    }
    try {
        Dism\Get-WindowsOptionalFeature -Online | Select-Object FeatureName,State | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $dir 'optional-features.json') -Encoding UTF8 -ErrorAction Stop
    } catch {
        Write-VSO7Log ("No se pudo crear snapshot de caracteristicas opcionales: {0}" -f $_.Exception.Message) 'WARN'
    }
    try {
        Invoke-NativeCommandVSO -FilePath 'systeminfo.exe' -Arguments @() -CaptureOutput | Set-Content -LiteralPath (Join-Path $dir 'systeminfo.txt') -Encoding UTF8 -ErrorAction Stop
    } catch {}
    $Tweaks | Select-Object Id,Name,Risk,Restart,Reversible,Desc | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $dir 'seleccion.json') -Encoding UTF8 -ErrorAction Stop

    $exports = @(
        @{
        K='HKCU\Software\Microsoft\GameBar';N='GameBar.reg'
    },@{
        K='HKCU\Software\Microsoft\Windows\CurrentVersion\GameDVR';N='GameDVR.reg'
    },
        @{
        K='HKLM\SYSTEM\CurrentControlSet\Control\DeviceGuard';N='DeviceGuard.reg'
    },@{
        K='HKLM\SYSTEM\CurrentControlSet\Control\Lsa';N='Lsa.reg'
    },
        @{
        K='HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization';N='DeliveryOptimization.reg'
    }
    )
    foreach ($entry in $exports) {

        try {
            Invoke-NativeCommandVSO -FilePath 'reg.exe' -Arguments @('export',$entry.K,(Join-Path $dir ('Registro\' + $entry.N)),'/y') | Out-Null
        } catch {}

    }

    [void](Assert-RecoveryBundleRequirementsVSO -Bundle $dir -Tweaks $Tweaks)
    # No publica LastRecoveryBundle hasta que el bundle inicial quede completamente
    # finalizado/verificado. Si Finalize falla, cualquier bundle valido anterior
    # permanece como ultimo bundle y esta creacion fallida nunca entra en Save-*.
    [void](Finalize-RecoveryBundle -Bundle $dir)
    $script:LastRecoveryBundle = $dir
    Write-VSO7Log ("Paquete de recuperacion creado: {0}" -f $dir) 'CHANGE'
    return $dir

}

function Finalize-RecoveryBundle {

    param([Parameter(Mandatory=$true)][string]$Bundle)
    $Bundle=Assert-VSO7ManagedRecoveryBundleVSO -Path $Bundle

    [void](Publish-VSO7RecoveryGenerationVSO -Bundle $Bundle)

    try {

        $os=CimCmdlets\Get-CimInstance Win32_OperatingSystem
        $disk=CimCmdlets\Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $script:SystemDrive)
        [pscustomobject]@{
            Time=(Get-Date).ToString('o');
            Processes=@(CimCmdlets\Get-CimInstance Win32_Process -ErrorAction SilentlyContinue).Count;
            FreeRamGB=[math]::Round([double]$os.FreePhysicalMemory/1MB,2);
            FreeDiskGB=[math]::Round([double]$disk.FreeSpace/1GB,2)
        } | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $Bundle 'rendimiento-despues.json') -Encoding UTF8 -ErrorAction Stop

    } catch{
        Write-VSO7Log ("No se pudo actualizar rendimiento-despues.json: {0}"-f$_.Exception.Message) 'WARN'
    }

    $runnerLeaf=[IO.Path]::GetFileName([string]$script:RecoveryRunnerScript)
    if([string]::IsNullOrWhiteSpace($runnerLeaf)-or$runnerLeaf-notmatch'^VSO7-RecoveryRunner-[0-9.]+-[A-F0-9]{64}\.ps1$'){
        throw 'Nombre invalido del Recovery Runner versionado.'
    }
    $cmd='@echo off' + "`r`n" +
        'setlocal' + "`r`n" +
        'set "VSO7_BUNDLE=%~dp0."' + "`r`n" +
        ('set "VSO7_RUNNER=%ProgramData%\VicoreDevelopment\VSO7\RecoveryRunners\{0}"' -f $runnerLeaf) + "`r`n" +
        'cd /d "%SystemRoot%\System32" || exit /b 6' + "`r`n" +
        'if not exist "%VSO7_RUNNER%" (echo Falta el Recovery Runner protegido/versionado de VSO7. 1>&2 & exit /b 5)' + "`r`n" +
        '"%SystemRoot%\System32\WindowsPowerShell\v1.0\powershell.exe" -NoLogo -NoProfile -File "%VSO7_RUNNER%" -SkipOrganize -RestoreFromBundle "%VSO7_BUNDLE%"' + "`r`n" +
        'set "RC=%ERRORLEVEL%"' + "`r`n" +
        'pause' + "`r`n" +
        'exit /b %RC%' + "`r`n"
    $rollback=Join-Path $Bundle 'ROLLBACK.cmd'
    Set-Content -LiteralPath $rollback -Value $cmd -Encoding ASCII -Force -ErrorAction Stop
    if(-not(Test-Path -LiteralPath $rollback -PathType Leaf)-or(Get-Item -LiteralPath $rollback -ErrorAction Stop).Length-le0){
        throw 'ROLLBACK.cmd no pudo crearse/verificarse.'
    }

    $readme=@"
VSO7 - PAQUETE DE RECUPERACION
==============================
Creado: $(Get-Date)

SEGURIDAD: ROLLBACK.cmd usa el Recovery Runner protegido y versionado por SHA-256 de %ProgramData%\VicoreDevelopment\VSO7.
origin.json autentica tambien el SHA-256 exacto de ese runner.
Los estados Recovery se publican por generaciones completas; CurrentGeneration.txt cambia de forma atomica solo tras validar una generacion nueva.
El bundle no contiene codigo PowerShell ejecutable: solo datos/snapshots y ROLLBACK.cmd.

Para revertir los cambios guardados en este paquete:
  1. Ejecuta ROLLBACK.cmd; VSO7 solicitara UAC cuando sea necesario.
  2. VSO7 restaurara y verificara Registro, energia, tweaks EXTREMOS e Inicio cuando exista estado para ello.
  3. Si la instalacion original no cambio desde la creacion del paquete, su Config se reconciliara de forma atomica.

Las LIMPIEZAS de cache/temporales/dumps son irreversibles por naturaleza.
Este paquete NO sustituye a una copia de seguridad completa de tus archivos personales.
"@
    Set-Content -LiteralPath (Join-Path $Bundle 'LEEME.txt') -Value $readme -Encoding UTF8 -Force -ErrorAction Stop
    return $true

}

function Restore-ExtremeTweak {

    param(
        [Parameter(Mandatory=$true)][string]$TweakId,
        [switch]$KeepState
    )

    Load-ExtremeState
    $meta = Get-VSOExtremeTweaks | Where-Object {
        $_.Id -eq $TweakId
    } | Select-Object -First 1
    if ($null -eq $meta) {
        Write-VSO7Log ("Tweak desconocido para revertir: {0}" -f $TweakId) 'WARN';
        return $false
    }
    if (-not [bool]$meta.Reversible) {
        Write-VSO7Log ("{0} es una limpieza irreversible." -f $meta.Name) 'WARN';
        return $false
    }

    $ok = $true
    if (-not (Restore-ExtremeRegistryForTweak -TweakId $TweakId)) {
        $ok = $false
    }
    if (-not (Restore-ExtremeServicesForTweak -TweakId $TweakId)) {
        $ok = $false
    }
    if (-not (Restore-ExtremeFeaturesForTweak -TweakId $TweakId)) {
        $ok = $false
    }
    if (-not (Restore-ExtremePowerForTweakVSO -TweakId $TweakId)) {
        $ok = $false
    }
    if (-not (Restore-ExtremeBcdForTweak -TweakId $TweakId)) {
        $ok = $false
    }

    if (-not (Restore-ExtremeHibernationForTweakVSO -TweakId $TweakId)) {
        $ok = $false
    }

    if (-not $ok) {

        Write-VSO7Log ("Rollback INCOMPLETO para {0}. Se conserva el estado para reintentar." -f $meta.Name) 'ERROR'
        return $false

    }

    if (-not $KeepState) {

        $script:ExtremeState.Registry = @($script:ExtremeState.Registry | Where-Object {
            $_.TweakId -ne $TweakId
        })
        $script:ExtremeState.Services = @($script:ExtremeState.Services | Where-Object {
            $_.TweakId -ne $TweakId
        })
        $script:ExtremeState.Features = @($script:ExtremeState.Features | Where-Object {
            $_.TweakId -ne $TweakId
        })
        $script:ExtremeState.PowerSettings = @($script:ExtremeState.PowerSettings | Where-Object {
            $_.TweakId -ne $TweakId
        })
        $script:ExtremeState.Bcd = @($script:ExtremeState.Bcd | Where-Object {
            $_.TweakId -ne $TweakId
        })
        if ($null -ne $script:ExtremeState.Hibernation -and [string]$script:ExtremeState.Hibernation.TweakId -eq $TweakId) {

            $script:ExtremeState.Hibernation = $null

        }
        $script:ExtremeState.AppliedTweaks = @($script:ExtremeState.AppliedTweaks | Where-Object {
            $_.Id -ne $TweakId
        })
        $script:ExtremeState.PendingTweaks = @($script:ExtremeState.PendingTweaks | Where-Object {
            $_.Id -ne $TweakId
        })
        Save-ExtremeState

    }

    Write-VSO7Log ("Rollback completo: {0}" -f $meta.Name) 'CHANGE'
    return $true

}

function Get-RecoverableExtremeTweakIdsVSO {

    $ids=@()
    foreach($item in @($script:ExtremeState.AppliedTweaks)){
        if([bool]$item.Reversible -and $ids -notcontains [string]$item.Id){
            $ids += [string]$item.Id
        }
    }
    foreach($item in @($script:ExtremeState.PendingTweaks)){
        if([bool]$item.Reversible -and (Test-ExtremeTweakHasRecoveryEvidenceVSO -TweakId ([string]$item.Id)) -and $ids -notcontains [string]$item.Id){
            $ids += [string]$item.Id
        }
    }
    return @($ids)

}

function Restore-AllExtremeChanges {

    Load-ExtremeState
    $ids=@(Get-RecoverableExtremeTweakIdsVSO)
    [array]::Reverse($ids)
    $failed=@()
    foreach($id in $ids){
        if(-not(Restore-ExtremeTweak -TweakId $id)){
            $failed+=$id
        }
    }
    if($failed.Count-gt0){
        Write-VSO7Log ("Quedaron rollbacks pendientes: {0}" -f ($failed-join', ')) 'ERROR';
        return $false
    }
    return $true

}

function Assert-VSO7RecoveryOriginMatchesProtectedStateVSO {

    param([Parameter(Mandatory=$true)]$Origin)
    $origin=ConvertTo-VSO7ValidatedRecoveryOrigin -Object $Origin
    [void](Assert-VSO7RecoveryOriginAuthenticationVSO -Origin $origin)
    if([string]::IsNullOrWhiteSpace([string]$script:RecoveryRunnerHash)-or[string]$origin.RunnerSha256-ine[string]$script:RecoveryRunnerHash){

        throw 'Recovery fue creado por otro Recovery Runner de VSO7. Ejecuta el ROLLBACK.cmd original del bundle para usar exactamente el runner autenticado que lo creo.'

    }
    $specs=@(
        [pscustomobject]@{
        Name='Normal';Target=[string]$script:StateFile;ExistsProp='StateExpectedExists';HashProp='StateExpectedSha256'
    },
        [pscustomobject]@{
        Name='Extreme';Target=[string]$script:ExtremeStateFile;ExistsProp='ExtremeExpectedExists';HashProp='ExtremeExpectedSha256'
    },
        [pscustomobject]@{
        Name='Startup';Target=[string]$script:StartupStateFile;ExistsProp='StartupExpectedExists';HashProp='StartupExpectedSha256'
    }
    )
    foreach($spec in $specs){

        [void](Protect-VSO7SecureStateLeaf -Path $spec.Target -AllowMissing)
        $expected=[bool]$origin.($spec.ExistsProp)
        $actual=Test-Path -LiteralPath $spec.Target -PathType Leaf
        if($expected-ne$actual){
            throw ("Recovery ya no corresponde al estado protegido actual ({0})."-f$spec.Name)
        }
        if($expected){

            $expectedHash=[string]$origin.($spec.HashProp)
            $actualHash=Get-RecoveryStateHashVSO -Path $spec.Target
            if($actualHash-ine$expectedHash){
                throw ("Recovery esta obsoleto: cambio el estado protegido {0}."-f$spec.Name)
            }

        }

    }
    return $true

}

function New-VSO7RecoveryStagingVSO {

    param([Parameter(Mandatory=$true)][string]$SourceBundle)
    if([string]::IsNullOrWhiteSpace($SourceBundle)-or-not(Test-Path -LiteralPath $SourceBundle -PathType Container)){
        throw 'No existe el paquete Recovery solicitado.'
    }
    $sourceFull=[IO.Path]::GetFullPath($SourceBundle).TrimEnd('\')
    if($sourceFull-notmatch'^[A-Za-z]:\\'){
        throw 'Recovery elevado rechaza rutas UNC/redirigidas; copia el bundle a una unidad local y vuelve a intentarlo.'
    }
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $sourceFull)
    $sourceItem=Get-Item -LiteralPath $sourceFull -Force -ErrorAction Stop
    if(-not$sourceItem.PSIsContainer-or($sourceItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'El directorio Recovery de origen es invalido/reparse point.'
    }

    $sourceDataRoot=Get-VSO7RecoveryPublishedDataRootVSO -BundleRoot $sourceFull
    $originSource=Join-Path $sourceDataRoot 'origin.json'
    if(-not(Test-Path -LiteralPath $originSource -PathType Leaf)){
        throw 'Falta origin.json en Recovery.'
    }
    $originItem=Get-Item -LiteralPath $originSource -Force -ErrorAction Stop
    if(($originItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or$originItem.PSIsContainer-or[int64]$originItem.Length-gt262144){
        throw 'origin.json de Recovery es invalido/reparse point/excesivo.'
    }
    $origin=ConvertTo-VSO7ValidatedRecoveryOrigin -Object (Get-Content -LiteralPath $originSource -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
    [void](Assert-VSO7RecoveryOriginMatchesProtectedStateVSO -Origin $origin)

    $stage=Protect-VSO7SecureDirectory -Path (Join-Path $script:RecoveryRoot ("RestoreStaging_{0}"-f([guid]::NewGuid().ToString('N'))))
    try{

        $limits=@{
            'origin.json'=262144;
            'state.json'=4194304;
            'extreme-state.json'=8388608;
            'startup-state.json'=8388608
        }
        foreach($name in @('origin.json','state.json','extreme-state.json','startup-state.json')){

            $src=Join-Path $sourceDataRoot $name
            if(-not(Test-Path -LiteralPath $src)){
                continue
            }
            $item=Get-Item -LiteralPath $src -Force -ErrorAction Stop
            if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ("{0} no es un archivo Recovery regular."-f$name)
            }
            if([int64]$item.Length-le0-or[int64]$item.Length-gt[int64]$limits[$name]){
                throw ("Tamano invalido para {0}."-f$name)
            }
            Copy-Item -LiteralPath $src -Destination (Join-Path $stage $name) -ErrorAction Stop

        }

        $stageOrigin=ConvertTo-VSO7ValidatedRecoveryOrigin -Object (Get-Content -LiteralPath (Join-Path $stage 'origin.json') -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
        [void](Assert-VSO7RecoveryOriginMatchesProtectedStateVSO -Origin $stageOrigin)
        foreach($binding in @(
            @('state.json','StateExpectedExists','StateBundleSha256'),
            @('extreme-state.json','ExtremeExpectedExists','ExtremeBundleSha256'),
            @('startup-state.json','StartupExpectedExists','StartupBundleSha256')
        )){

            $boundPath=Join-Path $stage ([string]$binding[0]);
            $mustExist=[bool]$stageOrigin.([string]$binding[1])
            $present=Test-Path -LiteralPath $boundPath -PathType Leaf
            if($present-ne$mustExist){
                throw ("Recovery incoherente: presencia de {0} no coincide con origin.json."-f$binding[0])
            }
            if($present){

                $boundHash=Get-RecoveryStateHashVSO -Path $boundPath
                if($boundHash-ine[string]$stageOrigin.([string]$binding[2])){
                    throw ("Recovery manipulado: hash del archivo exportado {0} no coincide con origin.json."-f$binding[0])
                }

            }

        }

        $normal=Join-Path $stage 'state.json'
        if(Test-Path -LiteralPath $normal -PathType Leaf){
            [void](ConvertTo-VSO7ValidatedNormalState -Object (Get-Content -LiteralPath $normal -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))
        }
        $extreme=Join-Path $stage 'extreme-state.json'
        if(Test-Path -LiteralPath $extreme -PathType Leaf){
            [void](ConvertTo-VSO7ValidatedExtremeState -Object (Get-Content -LiteralPath $extreme -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))
        }

        $startupSource=Join-Path $sourceDataRoot 'startup-state.json'
        $startupStage=Join-Path $stage 'startup-state.json'
        if(Test-Path -LiteralPath $startupSource -PathType Leaf){

            $oldStartupFile=$script:StartupStateFile
            try{

                $script:StartupStateFile=$startupSource
                $sourceStash=Get-VSO7StartupStashRoot
                $sourceState=ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $startupSource -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)
                $fileEntries=@($sourceState.Disabled|Where-Object{
                    [string]$_.Type-ieq'File'
                })
                if($fileEntries.Count-gt0){

                    $stageStash=Protect-VSO7SecureDirectory -Path (Join-Path $stage 'StartupDisabled')
                    foreach($entry in $fileEntries){

                        $srcBackup=[string]$entry.BackupPath
                        $dstBackup=[IO.Path]::GetFullPath((Join-Path $stageStash ([string]$entry.BackupName)))
                        if(-not(Test-VSO7StartupDirectChildPath -Path $dstBackup -AllowedParents @($stageStash))){
                            throw 'BackupName Startup escapa del staging.'
                        }
                        if(Test-Path -LiteralPath $srcBackup -PathType Leaf){

                            [void](Assert-VSO7StartupPathRuntimeSafe -Path $srcBackup -AllowedParents @($sourceStash))
                            $srcItem=Get-Item -LiteralPath $srcBackup -Force -ErrorAction Stop
                            if([int64]$srcItem.Length-gt1073741824){
                                throw 'Backup Startup excesivamente grande.'
                            }
                            $srcHash=(Get-FileHash -LiteralPath $srcBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                            if($srcHash-ine[string]$entry.Sha256){
                                throw ("Backup Startup alterado: {0}"-f$entry.Name)
                            }
                            Copy-Item -LiteralPath $srcBackup -Destination $dstBackup -ErrorAction Stop
                            $dstHash=(Get-FileHash -LiteralPath $dstBackup -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
                            if($dstHash-ine$srcHash){
                                throw 'Backup Startup copiado al staging no coincide.'
                            }

                        }elseif([string]$entry.Status-ieq'Disabled'){

                            throw ("Falta backup Startup obligatorio: {0}"-f$entry.Name)

                        }

                    }

                }

                $script:StartupStateFile=$startupStage
                [void](ConvertTo-VSO7ValidatedStartupState -Object (Get-Content -LiteralPath $startupStage -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))

            }finally{
                $script:StartupStateFile=$oldStartupFile
            }

        }

        # La presencia de cada estado debe coincidir con origin.json antes de tocar Windows.
        foreach($pair in @(
            @('state.json',[bool]$stageOrigin.StateExpectedExists),
            @('extreme-state.json',[bool]$stageOrigin.ExtremeExpectedExists),
            @('startup-state.json',[bool]$stageOrigin.StartupExpectedExists)
        )){

            $present=Test-Path -LiteralPath (Join-Path $stage ([string]$pair[0])) -PathType Leaf
            if($present-ne[bool]$pair[1]){
                throw ("Recovery incoherente: presencia inesperada de {0}."-f$pair[0])
            }

        }
        return $stage

    }catch{

        try{
            if(Test-Path -LiteralPath $stage -PathType Container){
                Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
            }
        }catch{}
        throw

    }

}

function Invoke-RestoreFromBundleVSO {

    param([string]$Bundle)
    Write-Title
    Write-VSOHost 'RECUPERACION DESDE PAQUETE VSO7' -ForegroundColor Red
    Write-VSOHost '--------------------------------'
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Paquete: {0}' -En 'Bundle: {0}') -f $Bundle)
    Write-VSOHost ''
    if(-not(Test-Path -LiteralPath $Bundle -PathType Container)){
        Write-VSOHost 'No existe el paquete.' -ForegroundColor Red;
        return $false
    }
    if(-not(Confirm-Word -Word 'REVERTIR' -Message 'Escribe REVERTIR para restaurar este paquete')){
        Write-VSOHost 'Cancelado.';
        return $false
    }

    $workingBundle=$null
    try{

        $workingBundle=New-VSO7RecoveryStagingVSO -SourceBundle $Bundle
        Write-VSO7Log ("Recovery importado a staging protegido: {0}"-f$workingBundle) 'CHANGE'

    }catch{

        Write-VSO7Log ("Recovery rechazado antes de modificar Windows: {0}"-f$_.Exception.Message) 'ERROR'
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Recovery rechazado antes de modificar Windows: {0}' -En 'Recovery was rejected before Windows was changed: {0}')-f$_.Exception.Message) -ForegroundColor Red
        return $false

    }

    # El commit-intent de reconciliacion se publica ANTES del primer write de rollback.
    # Si el proceso/PC cae desde este punto, el siguiente arranque reanuda desde este
    # RestoreStaging protegido antes de confiar otra vez en los journals de ProgramData.
    try{

        [void](Write-VSO7RecoveryReconcileJournalVSO -StagePath $workingBundle)

    }catch{

        Write-VSO7Log ("Recovery rechazado antes de modificar Windows porque no pudo publicarse el journal de reconciliacion: {0}"-f$_.Exception.Message) 'ERROR'
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Recovery rechazado antes de modificar Windows: no se pudo publicar el journal transaccional: {0}' -En 'Recovery was rejected before Windows was changed because the transaction journal could not be published: {0}')-f$_.Exception.Message) -ForegroundColor Red
        try{

            $stageFull=[IO.Path]::GetFullPath($workingBundle).TrimEnd('\')
            $recoveryFull=[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')
            if([IO.Path]::GetDirectoryName($stageFull)-ieq$recoveryFull-and[IO.Path]::GetFileName($stageFull)-like'RestoreStaging_*'){

                $stageItem=Get-Item -LiteralPath $stageFull -Force -ErrorAction Stop
                if(($stageItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-eq0){
                    Remove-Item -LiteralPath $stageFull -Recurse -Force -ErrorAction Stop
                }

            }

        }catch{
            Write-VSO7Log ("No se pudo limpiar staging tras fallar el journal Recovery; el GC protegido lo revisara en el siguiente inicio: {0}"-f$_.Exception.Message) 'WARN'
        }
        return $false

    }

    $safeOk=$true;
    $extOk=$true;
    $startupOk=$true
    $safe=Join-Path $workingBundle 'state.json';
    $ext=Join-Path $workingBundle 'extreme-state.json';
    $startup=Join-Path $workingBundle 'startup-state.json'

    # Normal y EXTREMO comparten la misma vista de staging durante todo el rollback.
    # De lo contrario cada lado podria consultar el ownership protegido antiguo y ambos
    # liberar una clave compartida sin que ninguno restaure el baseline.
    $oldStateFile=$script:StateFile;
    $oldState=$script:State
    $oldExtFile=$script:ExtremeStateFile;
    $oldExt=$script:ExtremeState
    $oldLastRecoveryBundle=$script:LastRecoveryBundle
    try{

        $script:LastRecoveryBundle=$null
        $script:StateFile=$safe
        if(Test-Path -LiteralPath $safe -PathType Leaf){
            Load-State
        }else{
            $script:State=New-EmptyState
        }
        $script:ExtremeStateFile=$ext
        if(Test-Path -LiteralPath $ext -PathType Leaf){
            Load-ExtremeState
        }else{
            $script:ExtremeState=New-EmptyExtremeState
        }

        if(Test-Path -LiteralPath $safe -PathType Leaf){

            try{
                $regOk=[bool](Restore-TrackedRegistry);
                $powerOk=[bool](Restore-PowerScheme);
                $safeOk=($regOk-and$powerOk)
            }
            catch{
                $safeOk=$false;
                Write-VSO7Log ("Error restaurando estado normal: {0}"-f$_.Exception.Message) 'ERROR'
            }

        }
        if(Test-Path -LiteralPath $ext -PathType Leaf){

            try{
                $extOk=[bool](Restore-AllExtremeChanges)
            }
            catch{
                $extOk=$false;
                Write-VSO7Log ("Error restaurando estado EXTREMO: {0}"-f$_.Exception.Message) 'ERROR'
            }

        }

    }finally{

        $script:StateFile=$oldStateFile;
        $script:State=$oldState
        $script:ExtremeStateFile=$oldExtFile;
        $script:ExtremeState=$oldExt
        $script:LastRecoveryBundle=$oldLastRecoveryBundle

    }

    if(Test-Path -LiteralPath $startup -PathType Leaf){

        $oldStartupFile=$script:StartupStateFile;
        $oldStartup=$script:StartupState;
        $oldLastRecoveryBundle=$script:LastRecoveryBundle
        try{
            $script:LastRecoveryBundle=$null;
            $script:StartupStateFile=$startup;
            Load-StartupState;
            $startupOk=[bool](Restore-AllStartupChangesVSO)
        }
        catch{
            $startupOk=$false;
            Write-VSO7Log ("Error restaurando Inicio: {0}"-f$_.Exception.Message) 'ERROR'
        }
        finally{
            $script:StartupStateFile=$oldStartupFile;
            $script:StartupState=$oldStartup;
            $script:LastRecoveryBundle=$oldLastRecoveryBundle
        }

    }

    # Incluso tras rollback parcial, sincroniza SOLO el estado residual validado al SecureStateRoot.
    $reconcileOk=$false
    try{
        $reconcileOk=[bool](Sync-RecoveryStateToOriginalVSO -Bundle $workingBundle -ResumeJournal)
    }catch{
        Write-VSO7Log ("Excepcion inesperada reconciliando Recovery; se preserva staging protegido y journal pendiente: {0}"-f$_.Exception.Message) 'ERROR';
        $reconcileOk=$false
    }
    $allOk=($safeOk-and$extOk-and$startupOk-and$reconcileOk)
    Write-VSOHost ''
    if($allOk){

        Write-VSOHost 'Recuperacion completada y estado protegido reconciliado. Reinicia Windows para completar servicios/virtualizacion.' -ForegroundColor Green
        try{

            $stageFull=[IO.Path]::GetFullPath($workingBundle).TrimEnd('\')
            $recoveryFull=[IO.Path]::GetFullPath([string]$script:RecoveryRoot).TrimEnd('\')
            if([IO.Path]::GetDirectoryName($stageFull)-ieq$recoveryFull-and[IO.Path]::GetFileName($stageFull)-like'RestoreStaging_*'){

                $stageItem=Get-Item -LiteralPath $stageFull -Force -ErrorAction Stop
                if(($stageItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-eq0){
                    Remove-Item -LiteralPath $stageFull -Recurse -Force -ErrorAction Stop
                }

            }

        }catch{
            Write-VSO7Log ("Recovery correcto, pero no se pudo limpiar staging protegido: {0}"-f$_.Exception.Message) 'WARN'
        }

    }else{

        Write-VSOHost 'Recuperacion INCOMPLETA. VSO7 ha conservado el estado pendiente y no afirmara que todo se restauro.' -ForegroundColor Red
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Staging protegido conservado para diagnostico/reintento: {0}' -En 'Protected staging was preserved for diagnostics or retry: {0}')-f$workingBundle) -ForegroundColor Yellow
        Write-VSOHost 'El paquete original no se modifica durante Recovery.' -ForegroundColor Yellow

    }
    return $allOk

}

function Invoke-ExtremeDryRun {

    param([array]$Tweaks,[switch]$SuppressPresentation)
    $items=@($Tweaks)
    if($items.Count-eq0){
        return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.DryRun' -Status Failed -Error 'No hay tweaks seleccionados para Dry Run.'
    }
    if(-not$SuppressPresentation){
        Write-Title
        Write-VSOHost 'DRY RUN - NADA SE MODIFICARA' -ForegroundColor Cyan
        Write-VSOHost '-----------------------------'
    }
    $steps=New-Object 'Collections.Generic.List[object]'
    foreach($t in $items){
        $risk=Get-RiskNameVSO $t.Risk;$info=$null;$ok=$true;$err=''
        try{$info=Get-TweakDetectInfo $t.Id}catch{$ok=$false;$err=[string]$_.Exception.Message}
        [void]$steps.Add([pscustomobject][ordered]@{Id=[string]$t.Id;Name=[string]$t.Name;Success=$ok;Risk=[int]$t.Risk;Detected=$info;Error=$err})
        if(-not$SuppressPresentation){
            Write-VSOHost ("[{0}] {1}" -f $risk,$t.Name) -ForegroundColor (Get-RiskColorVSO $t.Risk)
            Write-VSOHost ("    {0}" -f $t.Desc) -ForegroundColor Gray
            if($info){Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es '    Detectado: {0}' -En '    Detected: {0}') -f $info) -ForegroundColor DarkGray}
            if(-not$ok){Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es '    Error de deteccion: {0}' -En '    Detection error: {0}') -f $err) -ForegroundColor Yellow}
        }
    }
    if(-not$SuppressPresentation){
        $report=Join-Path $script:ReportRoot ("dryrun_extremo_{0}.txt" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
        try{
            $items | Select-Object Id,Name,@{N='Riesgo';E={Get-RiskNameVSO $_.Risk}},Restart,Reversible,Desc | Format-Table -AutoSize | Out-String | Set-Content $report -Encoding UTF8
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es "`nInforme: {0}" -En "`nReport: {0}") -f $report) -ForegroundColor DarkGray
        }catch{}
        Pause-Vico
    }
    $rows=@($steps.ToArray());$failed=@($rows|Where-Object{-not[bool]$_.Success});$passed=@($rows|Where-Object{[bool]$_.Success})
    $status=if($failed.Count-eq0){'Success'}elseif($passed.Count-eq0){'Failed'}else{'Partial'}
    $error=if($failed.Count){(@($failed|ForEach-Object{[string]$_.Id+': '+[string]$_.Error})-join'; ')}else{''}
    return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.DryRun' -Status $status -Steps $rows -FailedCount $failed.Count -Error $error
}

function Get-ExtremeConflictWarnings {

    param([array]$Tweaks)
    $ids=@($Tweaks | Select-Object -ExpandProperty Id)
    $warnings=@()
    if($ids -contains 'virtualization.wsl'){

        try{

            $distros=@(Invoke-NativeCommandVSO -FilePath 'wsl.exe' -Arguments @('-l','-q') -CaptureOutput -AllowNonZeroExit | Where-Object {
                -not [string]::IsNullOrWhiteSpace($_)
            })
            if($distros.Count -gt 0){
                $warnings += ("WSL tiene {0} distribucion(es) registrada(s)." -f $distros.Count)
            }

        }catch{}
        try{
            if(@(CimCmdlets\Get-CimInstance Win32_Process -ErrorAction Stop|Where-Object{
                $_.Name-ieq'Docker Desktop.exe'-or$_.Name-ieq'com.docker.backend.exe'
            }).Count-gt0){
                $warnings += 'Docker Desktop parece estar ejecutandose.'
            }
        }catch{}

    }
    if($ids -contains 'virtualization.hyperv'){

        try{
            if(Get-Command 'Hyper-V\Get-VM' -ErrorAction SilentlyContinue){
                $v=@(Hyper-V\Get-VM -ErrorAction SilentlyContinue);
                if($v.Count){
                    $warnings += ("Hyper-V tiene {0} VM(s) registrada(s)." -f $v.Count)
                }
            }
        }catch{}

    }
    if($ids -contains 'services.spooler'){

        try{
            if(Get-Command 'PrintManagement\Get-Printer' -ErrorAction SilentlyContinue){
                $p=@(PrintManagement\Get-Printer -ErrorAction SilentlyContinue);
                if($p.Count){
                    $warnings += ("Windows tiene {0} impresora(s)/cola(s) registrada(s)." -f $p.Count)
                }
            }
        }catch{}

    }
    if($ids -contains 'services.bluetooth'){

        try{
            if((Get-VSO7ServiceStatusVSO -Name 'bthserv') -eq 'Running'){
                $warnings += 'El servicio Bluetooth esta activo actualmente.'
            }
        }catch{}

    }
    if($ids -contains 'security.memoryIntegrity'){
        $warnings += 'Memory Integrity/HVCI protege codigo del kernel; desactivarlo reduce seguridad.'
    }
    if($ids -contains 'security.credentialGuard'){
        $warnings += 'Credential Guard protege credenciales mediante aislamiento; desactivarlo reduce seguridad.'
    }
    if($ids -contains 'security.vbs'){
        $warnings += 'VBS sirve de base a varias protecciones de Windows.'
    }
    if($ids -contains 'virtualization.hypervisorLaunchOff'){
        $warnings += 'hypervisorlaunchtype=off impide arrancar el hipervisor hasta revertir y reiniciar.'
    }
    if($ids -contains 'virtualization.hypervisorLaunchOff'){
        $bl=Get-BitLockerProtectionStateVSO;
        if($bl -ne 'Off'){
            $warnings += ("BCD bloqueado: estado BitLocker={0}; VSO7 exige Protection Off." -f $bl)
        }
    }
    return $warnings

}

function Show-ExtremeTweakInfo {

    param($Tweak)
    Write-Title
    if($null -eq $Tweak){
        Write-VSOHost 'Tweak no encontrado.' -ForegroundColor Red;
        Pause-Vico;
        return
    }
    $available=Test-TweakAvailableVSO $Tweak
    Write-VSOHost $Tweak.Name -ForegroundColor (Get-RiskColorVSO $Tweak.Risk)
    Write-VSOHost ('-' * $Tweak.Name.Length)
    Write-VSOHost ("ID          : {0}" -f $Tweak.Id)
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Riesgo      : {0}' -En 'Risk        : {0}') -f (Get-RiskNameVSO $Tweak.Risk))
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Disponible  : {0}' -En 'Available   : {0}') -f $(if($available){
        'SI'
    }else{
        'NO'
    })) -ForegroundColor $(if($available){
        'Green'
    }else{
        'Yellow'
    })
    if(-not$available){
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Motivo      : {0}' -En 'Reason      : {0}') -f (Get-TweakUnavailableReasonVSO $Tweak)) -ForegroundColor Yellow
    }
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Reversible  : {0}' -En 'Reversible  : {0}') -f $(if($Tweak.Reversible){
        'SI'
    }else{
        $(Get-VSO7ConsoleTextVSO -Es 'NO (limpieza)' -En 'NO (cleanup)')
    }))
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Reinicio    : {0}' -En 'Restart     : {0}') -f $(if($Tweak.Restart){
        'SI'
    }else{
        $(Get-VSO7ConsoleTextVSO -Es 'No normalmente' -En 'Not normally')
    }))
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Que hace    : {0}' -En 'What it does: {0}') -f $Tweak.Desc)
    $tech=Get-VSOTweakTechnicalDetails -Id $Tweak.Id;
    if($tech){
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Tecnico     : {0}' -En 'Technical   : {0}') -f $tech) -ForegroundColor DarkGray
    }
    $d=Get-TweakDetectInfo $Tweak.Id;
    if($d){
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Detectado   : {0}' -En 'Detected    : {0}') -f $d)
    }
    Pause-Vico

}

function Invoke-ApplyExtremeSelection {
    param([array]$Tweaks)

    $items=@($Tweaks)
    if($items.Count-eq0){
        Write-VSOHost 'No hay tweaks seleccionados.' -ForegroundColor Yellow
        return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Failed -Error 'No hay tweaks seleccionados.'
    }
    if(-not(Invoke-VSO7Preflight)){
        Pause-Vico
        return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Failed -Error 'El preflight global no se superó.'
    }
    $maxRisk=[int](($items|Measure-Object Risk -Maximum).Maximum)
    if($maxRisk-ge3){
        $pendingRiskState=Test-PendingRebootVSO
        if($true-eq$pendingRiskState){
            Write-VSOHost (Get-VSO7ConsoleTextVSO -Es 'Windows tiene un reinicio pendiente. VSO7 bloquea ALTO/MUCHO PELIGRO hasta reiniciar.' -En 'Windows has a pending restart. VSO7 blocks HIGH/VERY DANGEROUS changes until restart.') -ForegroundColor Red
            if($null-ne$script:LastPendingRebootStateVSO-and@($script:LastPendingRebootStateVSO.Reasons).Count-gt0){
                Write-VSOHost ((Get-VSO7ConsoleTextVSO -Es 'Senales: ' -En 'Signals: ')+(@($script:LastPendingRebootStateVSO.Reasons)-join', ')) -ForegroundColor Yellow
            }
            Pause-Vico
            return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Failed -Error 'Hay un reinicio pendiente.'
        }
        if($null-eq$pendingRiskState){
            Write-VSOHost 'No se pudo determinar de forma fiable si hay un reinicio pendiente. VSO7 bloquea ALTO/MUCHO PELIGRO por seguridad.' -ForegroundColor Red
            Pause-Vico
            return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Failed -Error 'No se pudo determinar el estado de reinicio pendiente.'
        }
    }
    if(-not(Confirm-UnvalidatedBuildIfNeeded -Tweaks $items)){
        Write-VSOHost 'Cancelado.';Pause-Vico
        return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Cancelled
    }

    Write-Title
    Write-VSOHost 'APLICAR SELECCION EXTREMA' -ForegroundColor Red
    Write-VSOHost '-------------------------'
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Tweaks: {0} | Riesgo maximo: {1}' -En 'Tweaks: {0} | Maximum risk: {1}') -f $items.Count,(Get-RiskNameVSO $maxRisk))
    Write-VSOHost 'VSO7 exigira un punto de restauracion NUEVO y creara Recuperacion antes de tocar Windows.' -ForegroundColor Yellow
    Write-VSOHost ''
    foreach($tweak in $items){Write-VSOHost (" - [{0}] {1}" -f (Get-RiskNameVSO $tweak.Risk),$tweak.Name) -ForegroundColor (Get-RiskColorVSO $tweak.Risk)}
    $conflicts=@(Get-ExtremeConflictWarnings -Tweaks $items)
    if($conflicts.Count){Write-VSOHost '';Write-VSOHost 'AVISOS DE COMPATIBILIDAD:' -ForegroundColor Yellow;foreach($warning in $conflicts){Write-VSOHost (" ! {0}" -f$warning) -ForegroundColor Yellow}}
    Write-VSOHost ''

    $confirmed=$false
    if($maxRisk-ge4){
        Write-VSOHost 'MUCHO PELIGRO reduce protecciones reales o modifica el arranque del hipervisor.' -ForegroundColor Red
        $confirmed=[bool](Confirm-Word -Word 'QUIERO ARRIESGAR WINDOWS' -Message 'Escribe exactamente: QUIERO ARRIESGAR WINDOWS')
    }elseif($maxRisk-ge3){$confirmed=[bool](Confirm-Word -Word 'ALTO' -Message 'Escribe ALTO para confirmar')}
    else{$confirmed=((Read-VSOHost '¿Continuar? [S/N]') -match '^[sSyY]$')}
    if(-not$confirmed){Write-VSOHost 'Cancelado.';Pause-Vico;return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Cancelled}

    if(-not(Require-RestorePoint -Aggressive)){
        Pause-Vico
        return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Failed -Error 'No se pudo satisfacer el requisito de punto de restauración.'
    }
    Load-State;Load-ExtremeState
    $bundle=$null
    try{$bundle=New-RecoveryBundle -Tweaks $items}catch{
        $msg=[string]$_.Exception.Message;Write-VSO7Log ("Cancelado antes de aplicar: no se pudo crear/verificar Recuperacion: {0}" -f$msg) 'ERROR';Pause-Vico
        return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status Failed -RollbackStatus NotAttempted -Error $msg
    }

    $steps=New-Object 'Collections.Generic.List[object]';$okCount=0;$failCount=0;$rollbackStatus='NotApplicable';$finalizeFailed=$false
    try{
        foreach($tweak in $items){
            Write-VSOHost '';Write-VSOHost (">> {0}" -f$tweak.Name) -ForegroundColor Cyan
            $step=[ordered]@{Id=[string]$tweak.Id;Name=[string]$tweak.Name;Status='Pending';Applied=$false;Rollback='NotApplicable';Error=''}
            $nativeState='None'
            if([string]$tweak.Id-ieq'gaming.gamemode'){
                try{$nativeState=Get-VSO7ExtremeNativeOwnershipStateVSO -TweakId 'gaming.gamemode'}catch{$nativeState='Conflict'}
            }
            if($nativeState-eq'AlreadyApplied'){
                $step.Status='AlreadyApplied';$step.Applied=$true;$step.Rollback='PreservedNative';[void]$steps.Add([pscustomobject]$step);$okCount++
                Write-VSO7Log ("Ya aplicado por Recovery nativo; se conserva el rollback original: {0}."-f$tweak.Name) 'WARN'
                continue
            }
            if(-not(Test-TweakAvailableVSO -Tweak $tweak)){
                $step.Status='Failed';$step.Error=(Get-TweakUnavailableReasonVSO -Tweak $tweak);[void]$steps.Add([pscustomobject]$step);$failCount++;Write-VSO7Log ("Se detiene: {0} ya no esta disponible. {1}" -f$tweak.Name,$step.Error) 'ERROR';break
            }
            if([bool]$tweak.Reversible-and@($script:ExtremeState.AppliedTweaks|Where-Object{$_.Id-eq$tweak.Id}).Count-gt0){
                Write-VSO7Log ("Ya estaba aplicado/registrado: {0}. Se conserva el rollback original." -f$tweak.Name) 'WARN';$step.Status='AlreadyApplied';$step.Applied=$true;[void]$steps.Add([pscustomobject]$step);$okCount++;continue
            }
            if([bool]$tweak.Reversible-and@($script:ExtremeState.PendingTweaks|Where-Object{$_.Id-eq$tweak.Id}).Count-gt0){
                $step.Status='Failed';$step.Error='Existe una transacción Pending previa.';[void]$steps.Add([pscustomobject]$step);$failCount++;Write-VSO7Log ("No se reaplica {0}: existe una transaccion Pending con evidencia de rollback. Revierte antes de continuar." -f$tweak.Name) 'ERROR';break
            }
            try{
                Start-PendingExtremeTweakVSO -Tweak $tweak;Invoke-VSOTweak -Tweak $tweak;Complete-AppliedExtremeTweakVSO -Tweak $tweak
                $step.Status='Success';$step.Applied=$true;[void]$steps.Add([pscustomobject]$step);$okCount++
            }catch{
                $originalError=[string]$_.Exception.Message;$step.Status='Failed';$step.Error=$originalError;$failCount++;Write-VSO7Log ("Fallo [{0}] {1}: {2}" -f$tweak.Id,$tweak.Name,$originalError) 'ERROR'
                if([bool]$tweak.Reversible){
                    $rolledBack=$false;try{$rolledBack=[bool](Restore-ExtremeTweak -TweakId $tweak.Id)}catch{Write-VSO7Log ("Excepcion durante rollback inmediato de {0}: {1}" -f$tweak.Name,$_.Exception.Message) 'ERROR'}
                    if($rolledBack){$step.Rollback='Complete';$rollbackStatus='Complete';Write-VSO7Log ("Rollback inmediato completado para: {0}" -f$tweak.Name) 'WARN'}else{$step.Rollback='Failed';$rollbackStatus='Failed';Load-ExtremeState;Write-VSO7Log ("Rollback incompleto. {0} conserva estado Pending y queda PENDIENTE DE REVERSION." -f$tweak.Name) 'ERROR'}
                }
                [void]$steps.Add([pscustomobject]$step);Write-VSO7Log 'VSO7 se detiene en el primer error. No se aplicaran los tweaks siguientes.' 'ERROR';break
            }
        }
    }finally{
        try{[void](Finalize-RecoveryBundle -Bundle $bundle)}catch{$finalizeFailed=$true;$failCount++;Write-VSO7Log ("No se pudo finalizar/verificar el paquete Recovery: {0}"-f$_.Exception.Message) 'ERROR'}
    }
    $status=if($failCount-eq0){'Success'}elseif($okCount-gt0){'Partial'}else{'Failed'}
    if($finalizeFailed-and$rollbackStatus-eq'NotApplicable'){$rollbackStatus='NotAttempted'}
    Write-VSOHost '';Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Aplicados: {0} | Fallos: {1}' -En 'Applied: {0} | Failed: {1}') -f$okCount,$failCount) -ForegroundColor $(if($failCount){'Yellow'}else{'Green'});Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Recuperacion: {0}' -En 'Recovery: {0}') -f$bundle) -ForegroundColor Cyan
    if(@($items|Where-Object{$_.Restart}).Count){Write-VSOHost 'Hay cambios que requieren REINICIAR Windows.' -ForegroundColor Yellow};Pause-Vico
    $err=if($failCount){(@($steps|Where-Object{$_.Status-eq'Failed'}|ForEach-Object{[string]$_.Id+': '+[string]$_.Error})-join'; ')}else{''}
    return New-VSO7OperationOutcomeR76VSO -Operation 'Extreme.Apply' -Status $status -Steps @($steps.ToArray()) -AppliedCount $okCount -FailedCount $failCount -RollbackStatus $rollbackStatus -RecoveryBundle ([string]$bundle) -Error $err
}

function Show-ExtremeRevertMenu {

    while($true){

        Write-Title;
        Load-ExtremeState
        Write-CenteredLineVSO -Text 'REVERTIR OPTIMIZACION EXTREMA' -Color 'Yellow'
        Write-CenteredLineVSO -Text 'Solo aparecen cambios extremos reversibles que VSO7 tiene registrados.' -Color $script:ThemeText
        $recoverableIds=@(Get-RecoverableExtremeTweakIdsVSO);
        $items=@(Get-VSOExtremeTweaks|Where-Object{
            [bool]$_.Reversible-and$recoverableIds-contains[string]$_.Id
        })
        if($items.Count-eq0){
            Write-CenteredLineVSO -Text 'No hay tweaks extremos reversibles registrados.' -Color $script:ThemeMuted;
            Pause-Vico;
            return
        }
        $rows=@();
        for($i=0;$i-lt$items.Count;$i++){
            $itemName=[string](Convert-VSOText -Value ([string]$items[$i].Name));
            $itemDesc=[string](Convert-VSOText -Value ([string]$items[$i].Desc));
            $rows += [pscustomobject]@{
                Text=("[{0}] {1}"-f($i+1),$itemName);
                Color='Gray';
                Description=$itemDesc
            }
        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        $allNumber=$items.Count+1
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Revertir TODOS los cambios extremos reversibles' -En '[{0}] Revert ALL reversible extreme changes')-f$allNumber);Color='Red';Description='Intenta devolver todos los tweaks extremos registrados a su estado anterior. Requiere confirmacion escrita.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa sin revertir nada.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Opcion';
        if($choice-eq'0'){
            return
        };
        $number=0;
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }
        if($number-eq$allNumber){
            if(Confirm-Word -Word 'REVERTIR' -Message 'Escribe REVERTIR'){
                if(Restore-AllExtremeChanges){
                    Write-VSOHost 'Reversion completada.' -ForegroundColor Green
                }else{
                    Write-VSOHost 'Reversion incompleta; el estado pendiente se ha conservado.' -ForegroundColor Red
                };
                Pause-Vico
            };
            continue
        }
        if($number-ge1-and$number-le$items.Count){
            $item=$items[$number-1];
            if(Confirm-Word -Word 'REVERTIR' -Message ("Escribe REVERTIR para: {0}"-f$item.Name)){
                if(Restore-ExtremeTweak -TweakId $item.Id){
                    Write-VSOHost 'Reversion completada.' -ForegroundColor Green
                }else{
                    Write-VSOHost 'Reversion incompleta; el estado pendiente se ha conservado.' -ForegroundColor Red
                };
                Pause-Vico
            }
        }

    }

}

function Show-ExtremeOptimizer {

    $all=@(Get-VSOExtremeTweaks);
    $selected=@{}
    while($true){

        Write-Title
        Write-CenteredLineVSO -Text 'OPTIMIZACION EXTREMA - VSO7' -Color 'Red'
        Write-CenteredLineVSO -Text 'Nada se aplica al entrar. Selecciona ajustes individualmente o usa un nivel de riesgo como atajo.' -Color $script:ThemeText
        Write-CenteredLineVSO -Text 'Antes de aplicar: pre-flight, punto de restauracion, Recuperacion, backup y verificacion.' -Color 'Green'
        $build=Get-WindowsBuildVSO;
        Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Build actual: {0} | Validado hasta: {1} ({2})' -En 'Current build: {0} | Validated up to: {1} ({2})')-f$build,$script:ValidatedBuildMax,$script:ValidatedOn) -Color $script:ThemeMuted;
        Write-VSOHost ''

        $extremeRows=@()
        for($i=0;$i-lt$all.Count;$i++){

            $tweak=$all[$i];
            $nativeState='None'
            if([string]$tweak.Id-ieq'gaming.gamemode'){
                try{$nativeState=Get-VSO7ExtremeNativeOwnershipStateVSO -TweakId 'gaming.gamemode'}catch{$nativeState='Conflict'}
            }
            $alreadyNative=($nativeState-eq'AlreadyApplied')
            $available=Test-TweakAvailableVSO -Tweak $tweak;
            if(-not$available-and$selected.ContainsKey($tweak.Id)){
                $selected.Remove($tweak.Id)
            }
            $mark=if($alreadyNative){
                'OK'
            }elseif(-not$available){
                '-'
            }elseif($selected.ContainsKey($tweak.Id)){
                'X'
            }else{
                ' '
            };
            $riskName=Get-RiskNameVSO -Risk $tweak.Risk;
            $suffix=if($alreadyNative){
                $(Get-VSO7ConsoleTextVSO -Es ' [YA APLICADO]' -En ' [ALREADY APPLIED]')
            }elseif($available){
                ''
            }else{
                $(Get-VSO7ConsoleTextVSO -Es ' [NO DISPONIBLE]' -En ' [UNAVAILABLE]')
            };
            $color=if($alreadyNative){
                'Green'
            }elseif($available){
                Get-RiskColorVSO -Risk $tweak.Risk
            }else{
                'DarkGray'
            }
            $tweakName=[string](Convert-VSOText -Value ([string]$tweak.Name));
            $tweakDesc=[string](Convert-VSOText -Value ([string]$tweak.Desc))
            $extremeRows += [pscustomobject]@{
                Text=("[{0}] [{1}] {2} - {3}{4}"-f($i+1),$mark,$riskName,$tweakName,$suffix);
                Color=$color;
                Description=$tweakDesc
            }

        }
        Write-VSO7TwoColumnOptionsVSO -Items $extremeRows

        $selection=@($all|Where-Object{
            $selected.ContainsKey($_.Id)
        })
        Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Seleccionados: {0} | Leve {1} | Medio {2} | Alto {3} | Mucho peligro {4}' -En 'Selected: {0} | Low {1} | Medium {2} | High {3} | Very dangerous {4}') -f $selection.Count,@($selection|Where-Object{
            $_.Risk-eq1
        }).Count,@($selection|Where-Object{
            $_.Risk-eq2
        }).Count,@($selection|Where-Object{
            $_.Risk-eq3
        }).Count,@($selection|Where-Object{
            $_.Risk-eq4
        }).Count) -Color 'Cyan'

        $leve=$all.Count+1;
        $medio=$all.Count+2;
        $alto=$all.Count+3;
        $todo=$all.Count+4;
        $clear=$all.Count+5;
        $info=$all.Count+6;
        $dry=$all.Count+7;
        $apply=$all.Count+8;
        $revert=$all.Count+9
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar solo riesgo LEVE' -En '[{0}] Select LOW-risk items only')-f$leve);Color='Green';Description='Marca de una vez los cambios de menor riesgo disponibles. Todavia no aplica nada.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar hasta riesgo MEDIO' -En '[{0}] Select up to MEDIUM risk')-f$medio);Color='Yellow';Description='Marca los cambios leves y medios disponibles. Revisa la lista antes de aplicar.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar hasta riesgo ALTO' -En '[{0}] Select up to HIGH risk')-f$alto);Color='DarkYellow';Description='Incluye cambios que pueden alterar comportamiento importante de Windows; requiere mas cuidado.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar TODO / MUCHO PELIGRO' -En '[{0}] Select ALL / VERY DANGEROUS')-f$todo);Color='Red';Description='Marca todo lo disponible, incluidos cambios con mayor posibilidad de efectos secundarios. No los aplica todavia.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Quitar toda la seleccion' -En '[{0}] Clear the selection')-f$clear);Color='Gray';Description='Desmarca todos los tweaks sin modificar Windows.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Ver informacion detallada de un tweak' -En '[{0}] View detailed tweak information')-f$info);Color='Gray';Description='Explica un ajuste concreto, su riesgo, disponibilidad y reversibilidad.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Simular seleccion (Dry Run)' -En '[{0}] Preview selection (Dry Run)')-f$dry);Color='Cyan';Description='Comprueba que haria VSO7 y que requisitos faltan sin aplicar los tweaks.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Aplicar la seleccion' -En '[{0}] Apply the selection')-f$apply);Color='Red';Description='Solo aqui comienza la modificacion real, con comprobaciones, recuperacion y confirmaciones.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Revertir cambios extremos registrados' -En '[{0}] Revert recorded extreme changes')-f$revert);Color='Yellow';Description='Abre el selector de recuperacion de tweaks extremos aplicados anteriormente.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Sale de esta pantalla sin aplicar la seleccion pendiente.';SeparatorBefore=$true
        }
        )
        $choice=Read-CenteredPromptVSO -Text 'Opcion / numero para marcar o desmarcar';
        if($choice-eq'0'){
            return
        };
        $number=0;
        if(-not[int]::TryParse($choice,[ref]$number)){
            continue
        }
        if($number-ge1-and$number-le$all.Count){
            $tweak=$all[$number-1];
            if(-not(Test-TweakAvailableVSO -Tweak $tweak)){
                Write-VSOHost (Get-TweakUnavailableReasonVSO -Tweak $tweak) -ForegroundColor Yellow;
                Start-Sleep -Seconds 1
            }elseif($selected.ContainsKey($tweak.Id)){
                $selected.Remove($tweak.Id)
            }else{
                $selected[$tweak.Id]=$true
            };
            continue
        }
        if($number-eq$clear){
            $selected=@{};
            continue
        }
        if($number-eq$leve){
            $selected=@{};
            foreach($tweak in @($all|Where-Object{
                $_.Risk-le1
            })){
                if(Test-TweakAvailableVSO -Tweak $tweak){
                    $selected[$tweak.Id]=$true
                }
            };
            continue
        }
        if($number-eq$medio){
            $selected=@{};
            foreach($tweak in @($all|Where-Object{
                $_.Risk-le2
            })){
                if(Test-TweakAvailableVSO -Tweak $tweak){
                    $selected[$tweak.Id]=$true
                }
            };
            continue
        }
        if($number-eq$alto){
            $selected=@{};
            foreach($tweak in @($all|Where-Object{
                $_.Risk-le3
            })){
                if(Test-TweakAvailableVSO -Tweak $tweak){
                    $selected[$tweak.Id]=$true
                }
            };
            continue
        }
        if($number-eq$todo){
            $selected=@{};
            foreach($tweak in $all){
                if(Test-TweakAvailableVSO -Tweak $tweak){
                    $selected[$tweak.Id]=$true
                }
            };
            continue
        }
        if($number-eq$info){
            $raw=Read-CenteredPromptVSO -AnimatedMenu -Text 'Numero del tweak';
            $detail=0;
            if([int]::TryParse($raw,[ref]$detail)-and$detail-ge1-and$detail-le$all.Count){
                Show-ExtremeTweakInfo -Tweak $all[$detail-1]
            };
            continue
        }
        if($number-eq$dry){
            Invoke-ExtremeDryRun -Tweaks @($all|Where-Object{
                $selected.ContainsKey($_.Id)
            });
            continue
        }
        if($number-eq$apply){
            Invoke-ApplyExtremeSelection -Tweaks @($all|Where-Object{
                $selected.ContainsKey($_.Id)
            });
            continue
        }
        if($number-eq$revert){
            Show-ExtremeRevertMenu;
            continue
        }

    }

}

function Test-VSO7NativeResourceIntegrityVSO {

    try {

        $items=@(
            [pscustomobject]@{
            Path=$script:VSO7FeatureCatalog;Expected=$script:ExpectedVSO7FeatureCatalogSha256;Label='catalogo de ajustes'
        },
            [pscustomobject]@{
            Path=$script:VSO7NativeTweaks;Expected=$script:ExpectedVSO7NativeTweaksSha256;Label='operaciones nativas'
        },
            [pscustomobject]@{
            Path=$script:VSO7AppCatalog;Expected=$script:ExpectedVSO7AppCatalogSha256;Label='catalogo de aplicaciones'
        }
        )
        foreach($item in $items){

            if(-not(Test-Path -LiteralPath $item.Path -PathType Leaf)){
                throw ('Falta recurso VSO7: {0}'-f$item.Label)
            }
            [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $item.Path)
            $actual=(Get-FileHash -LiteralPath $item.Path -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if($actual-cne[string]$item.Expected){
                throw ('Huella SHA-256 incorrecta para {0}.'-f$item.Label)
            }

        }
        return $true

    } catch {

        Write-VSO7Log ("Validacion de recursos nativos VSO7 fallo: {0}"-f$_.Exception.Message) 'ERROR'
        return $false

    }

}

function Get-VSO7NativeDataVSO {

    if(-not(Test-VSO7NativeResourceIntegrityVSO)){
        throw 'Los recursos nativos de VSO7 no superan su validacion SHA-256.'
    }
    return (Get-Content -LiteralPath $script:VSO7NativeTweaks -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)

}

function Get-VSO7NativeRegistryPartsVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    if($Path-notmatch'^(HKEY_LOCAL_MACHINE|HKEY_CURRENT_USER|HKEY_CLASSES_ROOT|HKEY_USERS|HKEY_CURRENT_CONFIG)(?:\\(.*))?$'){
        throw ('Ruta Registry nativa no permitida: {0}'-f$Path)
    }
    return [pscustomobject]@{
        Hive=$Matches[1];
        SubKey=[string]$Matches[2]
    }

}

function Open-VSO7NativeRegistryBaseVSO {

    param([Parameter(Mandatory=$true)][string]$Hive)
    $view=[Microsoft.Win32.RegistryView]::Registry64
    switch($Hive){

        'HKEY_LOCAL_MACHINE' {
            return [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,$view)
        }
        'HKEY_CURRENT_USER' {
            return [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::CurrentUser,$view)
        }
        'HKEY_CLASSES_ROOT' {
            return [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::ClassesRoot,$view)
        }
        'HKEY_USERS' {
            return [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::Users,$view)
        }
        'HKEY_CURRENT_CONFIG' {
            return [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::CurrentConfig,$view)
        }
        default {
            throw 'Hive Registry no permitida.'
        }

    }

}

function Get-VSO7NativeRegistryKeyFingerprintVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $parts=Get-VSO7NativeRegistryPartsVSO -Path $Path;
    $base=$null;
    $root=$null
    try{

        $base=Open-VSO7NativeRegistryBaseVSO -Hive $parts.Hive
        $root=$base.OpenSubKey($parts.SubKey,$false)
        if($null-eq$root){
            return $null
        }
        $builder=New-Object Text.StringBuilder
        $appendValue={

            param([Parameter(Mandatory=$true)][Microsoft.Win32.RegistryKey]$Key,[Parameter(Mandatory=$true)][AllowEmptyString()][string]$RelativePath)
            [string[]]$valueNames=@($Key.GetValueNames());
            [Array]::Sort($valueNames,[StringComparer]::OrdinalIgnoreCase)
            foreach($valueName in $valueNames){

                $kind=[string]$Key.GetValueKind($valueName)
                $value=$Key.GetValue($valueName,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                switch($kind){

                    'Binary' {
                        $payload=[Convert]::ToBase64String([byte[]]$value)
                    }
                    'MultiString' {
                        $payload=(@([string[]]$value|ForEach-Object{
                            [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$_))
                        })-join',')
                    }
                    'DWord' {
                        $payload=[Convert]::ToBase64String([BitConverter]::GetBytes([int32]$value))
                    }
                    'QWord' {
                        $payload=[Convert]::ToBase64String([BitConverter]::GetBytes([int64]$value))
                    }
                    'String' {
                        $payload=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$value))
                    }
                    'ExpandString' {
                        $payload=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$value))
                    }
                    'None' {
                        $payload=[Convert]::ToBase64String([byte[]]$value)
                    }
                    default {
                        throw ('Tipo Registry no soportado al crear fingerprint: {0}'-f$kind)
                    }

                }
                $normalizedName=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes(([string]$valueName).ToUpperInvariant()))
                [void]$builder.Append(('V|{0}|{1}|{2}|{3}`n'-f$RelativePath,$normalizedName,$kind,$payload))

            }
            [string[]]$subNames=@($Key.GetSubKeyNames());
            [Array]::Sort($subNames,[StringComparer]::OrdinalIgnoreCase)
            foreach($subName in $subNames){

                $child=$null
                try{

                    $child=$Key.OpenSubKey($subName,$false)
                    if($null-eq$child){
                        throw ('Subclave Registry desaparecio durante fingerprint: {0}\\{1}'-f$Path,$subName)
                    }
                    $childRel=if([string]::IsNullOrEmpty($RelativePath)){
                        ([string]$subName).ToUpperInvariant()
                    }else{
                        $RelativePath+'\\'+([string]$subName).ToUpperInvariant()
                    }
                    [void]$builder.Append(('K|{0}`n'-f$childRel))
                    & $appendValue $child $childRel
                    [void]$builder.Append(('E|{0}`n'-f$childRel))

                }finally{
                    if($null-ne$child){
                        $child.Dispose()
                    }
                }

            }

        }
        & $appendValue $root ''
        $sha=[Security.Cryptography.SHA256]::Create()
        try{
            return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($builder.ToString()))).Replace('-',''))
        }finally{
            $sha.Dispose()
        }

    }finally{
        if($null-ne$root){
            $root.Dispose()
        };
        if($null-ne$base){
            $base.Dispose()
        }
    }

}

function Test-VSO7NativeRegistryKeyBaselineMatchVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $exists=Test-VSO7NativeRegistryKeyExistsVSO -Path ([string]$Entry.Path)
    if(-not[bool]$Entry.Exists){
        return (-not$exists)
    }
    if(-not$exists){
        return $false
    }
    if(-not($Entry.PSObject.Properties.Name-contains'BaselineFingerprint')-or[string]::IsNullOrWhiteSpace([string]$Entry.BaselineFingerprint)){
        return $false
    }
    $current=Get-VSO7NativeRegistryKeyFingerprintVSO -Path ([string]$Entry.Path)
    return (-not[string]::IsNullOrWhiteSpace([string]$current)-and[string]$current-ceq[string]$Entry.BaselineFingerprint)

}

function Get-VSO7NativeRegistrySnapshotVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][AllowEmptyString()][string]$Name)
    $parts=Get-VSO7NativeRegistryPartsVSO -Path $Path;
    $base=$null;
    $key=$null
    try{

        $base=Open-VSO7NativeRegistryBaseVSO -Hive $parts.Hive
        $key=$base.OpenSubKey($parts.SubKey,$false)
        if($null-eq$key){
            return [pscustomobject]@{
                Exists=$false;
                Kind=$null;
                Value=$null
            }
        }
        $names=@($key.GetValueNames())
        if($names-inotcontains$Name){
            return [pscustomobject]@{
                Exists=$false;
                Kind=$null;
                Value=$null
            }
        }
        $kind=[string]$key.GetValueKind($Name)
        $value=$key.GetValue($Name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
        if($kind-eq'Binary'){
            $value=@([byte[]]$value|ForEach-Object{
                [int]$_
            })
        }
        elseif($kind-eq'MultiString'){
            $value=@([string[]]$value)
        }
        return [pscustomobject]@{
            Exists=$true;
            Kind=$kind;
            Value=$value
        }

    }finally{
        if($null-ne$key){
            $key.Dispose()
        };
        if($null-ne$base){
            $base.Dispose()
        }
    }

}

function Set-VSO7NativeRegistryValueRawVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][AllowEmptyString()][string]$Name,[Parameter(Mandatory=$true)][string]$Kind,$Value)
    $parts=Get-VSO7NativeRegistryPartsVSO -Path $Path;
    $base=$null;
    $key=$null
    try{

        $base=Open-VSO7NativeRegistryBaseVSO -Hive $parts.Hive
        $key=$base.CreateSubKey($parts.SubKey,[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree)
        if($null-eq$key){
            throw ('No se pudo abrir/crear {0}'-f$Path)
        }
        switch($Kind){

            'DWord' {

                if(Test-VSO7JsonInteger -Value $Value -Min -2147483648 -Max -1){

                    $u=[BitConverter]::ToUInt32([BitConverter]::GetBytes([int32]$Value),0)

                }else{
                    $u=[Convert]::ToUInt32([string]$Value,[Globalization.CultureInfo]::InvariantCulture)
                }
                $signed=[BitConverter]::ToInt32([BitConverter]::GetBytes($u),0)
                $key.SetValue($Name,$signed,[Microsoft.Win32.RegistryValueKind]::DWord)

            }
            'QWord' {
                $key.SetValue($Name,[int64]$Value,[Microsoft.Win32.RegistryValueKind]::QWord)
            }
            'String' {
                $key.SetValue($Name,[string]$Value,[Microsoft.Win32.RegistryValueKind]::String)
            }
            'ExpandString' {
                $key.SetValue($Name,[string]$Value,[Microsoft.Win32.RegistryValueKind]::ExpandString)
            }
            'MultiString' {
                $key.SetValue($Name,[string[]]@($Value),[Microsoft.Win32.RegistryValueKind]::MultiString)
            }
            'Binary' {
                $key.SetValue($Name,[byte[]]@($Value|ForEach-Object{
                    [byte][int]$_
                }),[Microsoft.Win32.RegistryValueKind]::Binary)
            }
            default {
                throw ('Tipo Registry nativo no permitido: {0}'-f$Kind)
            }

        }

    }finally{
        if($null-ne$key){
            $key.Dispose()
        };
        if($null-ne$base){
            $base.Dispose()
        }
    }

}

function Remove-VSO7NativeRegistryValueRawVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][AllowEmptyString()][string]$Name)
    $parts=Get-VSO7NativeRegistryPartsVSO -Path $Path;
    $base=$null;
    $key=$null
    try{

        $base=Open-VSO7NativeRegistryBaseVSO -Hive $parts.Hive;
        $key=$base.OpenSubKey($parts.SubKey,$true)
        if($null-ne$key){
            $key.DeleteValue($Name,$false)
        }

    }finally{
        if($null-ne$key){
            $key.Dispose()
        };
        if($null-ne$base){
            $base.Dispose()
        }
    }

}

function Remove-VSO7NativeRegistryKeyRawVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $parts=Get-VSO7NativeRegistryPartsVSO -Path $Path
    if([string]::IsNullOrWhiteSpace($parts.SubKey)){
        throw 'VSO7 nunca elimina una hive Registry completa.'
    }
    $base=$null
    try{
        $base=Open-VSO7NativeRegistryBaseVSO -Hive $parts.Hive;
        $base.DeleteSubKeyTree($parts.SubKey,$false)
    }finally{
        if($null-ne$base){
            $base.Dispose()
        }
    }

}

function Get-VSO7NativeBackupRootVSO {

    $root=Join-Path $script:ConfigRoot 'NativeTweakBackups'
    return (Protect-VSO7SecureDirectory -Path $root)

}

function ConvertTo-VSO7NativeBackupSessionPersistObjectVSO {

    param([Parameter(Mandatory=$true)]$Session,[switch]$LegacyShape)
    $ordered=[ordered]@{}
    $names=if($LegacyShape){
        @('Schema','Version','ProducerRevision','CreatedAt','Features','Status','Entries')
    }else{
        @('Schema','Version','ProducerRevision','CreatedAt','Features','Status','BatchKind','BatchId','BatchObjective','PreflightBaselines','FeatureResults','Entries')
    }
    $available=@($Session.PSObject.Properties.Name)
    foreach($name in $names){

        if($available-notcontains$name){
            continue
        }
        if($name-ceq'ProducerRevision'-and$null-eq$Session.ProducerRevision){
            continue
        }
        $ordered[$name]=$Session.$name

    }
    return [pscustomobject]$ordered

}

function Save-VSO7NativeBackupSessionVSO {

    param([Parameter(Mandatory=$true)]$Session)
    $path=Join-Path ([string]$Session.Directory) 'state.json';
    $tmp=$path+'.tmp'
    # Schema 2 anterior a R24 no tenia ProducerRevision. Preserva esa ausencia:
    # serializar null convertiría un journal historico valido en invalido al reabrirlo.
    ConvertTo-VSO7NativeBackupSessionPersistObjectVSO -Session $Session|ConvertTo-Json -Depth 14|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
    [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $path)

}

function New-VSO7NativeBackupSessionVSO {

    param([string[]]$Features=@(),[string]$BatchKind='',[string]$BatchId='',[string]$BatchObjective='',[object[]]$PreflightBaselines=@())
    $root=Get-VSO7NativeBackupRootVSO
    $stamp=(Get-Date -Format 'yyyyMMdd_HHmmss_fff')
    $dir=$null
    for($attempt=0;$attempt-lt8;$attempt++){

        $leaf=('{0}_{1}'-f$stamp,[guid]::NewGuid().ToString('N'))
        $candidate=Join-Path $root $leaf
        if(Test-Path -LiteralPath $candidate){
            continue
        }
        $dir=Protect-VSO7SecureDirectory -Path $candidate
        break

    }
    if([string]::IsNullOrWhiteSpace([string]$dir)){
        throw 'No se pudo crear un directorio de sesion nativa unico.'
    }
    $session=[pscustomobject]@{
        Schema=2;
        Version=$script:Version;
        ProducerRevision=[int]$script:NativeJournalRevision;
        CreatedAt=(Get-Date).ToString('o');
        Features=@($Features);
        Status='Pending';
        BatchKind=[string]$BatchKind;
        BatchId=[string]$BatchId;
        BatchObjective=[string]$BatchObjective;
        PreflightBaselines=@($PreflightBaselines);
        FeatureResults=@();
        Entries=@();
        Directory=$dir
    }
    Save-VSO7NativeBackupSessionVSO -Session $session
    return $session

}

function ConvertTo-VSO7NativeDesiredRegistrySnapshotVSO {

    param([Parameter(Mandatory=$true)][string]$Kind,$Value)
    switch($Kind){

        'DWord' {

            $u=[Convert]::ToUInt32([string]$Value,[Globalization.CultureInfo]::InvariantCulture)
            $signed=[BitConverter]::ToInt32([BitConverter]::GetBytes($u),0)
            return [pscustomobject]@{
                Exists=$true;
                Kind='DWord';
                Value=$signed
            }

        }
        'QWord' {
            return [pscustomobject]@{
                Exists=$true;
                Kind='QWord';
                Value=[int64]$Value
            }
        }
        'String' {
            return [pscustomobject]@{
                Exists=$true;
                Kind='String';
                Value=[string]$Value
            }
        }
        'ExpandString' {
            return [pscustomobject]@{
                Exists=$true;
                Kind='ExpandString';
                Value=[string]$Value
            }
        }
        'MultiString' {
            return [pscustomobject]@{
                Exists=$true;
                Kind='MultiString';
                Value=@([string[]]$Value)
            }
        }
        'Binary' {
            return [pscustomobject]@{
                Exists=$true;
                Kind='Binary';
                Value=@([byte[]]@($Value|ForEach-Object{
                    [byte][int]$_
                })|ForEach-Object{
                    [int]$_
                })
            }
        }
        default {
            throw ('Tipo Registry nativo no permitido para snapshot: {0}'-f$Kind)
        }

    }

}

function Test-VSO7NativeSequenceEqualVSO {

    param($A,$B)
    $aa=@($A);
    $bb=@($B);
    if($aa.Count-ne$bb.Count){
        return $false
    }
    for($i=0;$i-lt$aa.Count;$i++){
        if([string]$aa[$i]-cne[string]$bb[$i]){
            return $false
        }
    }
    return $true

}

function Test-VSO7NativeRegistrySnapshotEqualVSO {

    param([Parameter(Mandatory=$true)]$A,[Parameter(Mandatory=$true)]$B)
    if([bool]$A.Exists-ne[bool]$B.Exists){
        return $false
    }
    if(-not[bool]$A.Exists){
        return $true
    }
    if([string]$A.Kind-cne[string]$B.Kind){
        return $false
    }
    if([string]$A.Kind-in@('Binary','MultiString')){
        return (Test-VSO7NativeSequenceEqualVSO -A $A.Value -B $B.Value)
    }
    return ([string]$A.Value-ceq[string]$B.Value)

}

function Add-VSO7NativeValueBackupVSO {

    param(
        [Parameter(Mandatory=$true)]$Session,
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Name,
        [Parameter(Mandatory=$true)]$Intended,
        [AllowNull()][hashtable]$JournalMetadata
    )
    $key=($Path.ToLowerInvariant()+'|'+$Name.ToLowerInvariant())
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){

        if($null-ne$JournalMetadata){
            foreach($metadataKey in @($JournalMetadata.Keys)){
                if(-not($existing[0].PSObject.Properties.Name-contains[string]$metadataKey)-or[string]$existing[0].$metadataKey-cne[string]$JournalMetadata[$metadataKey]){
                    throw ('Registry journal metadata incompatible para target ya existente: {0}.'-f$metadataKey)
                }
            }
        }
        return $existing[0]

    }
    $snap=Get-VSO7NativeRegistrySnapshotVSO -Path $Path -Name $Name
    $entry=[pscustomobject]@{

        Type='RegistryValue';
        Key=$key;
        Path=$Path;
        Name=$Name;

        Exists=[bool]$snap.Exists;
        Kind=$snap.Kind;
        Value=$snap.Value;

        IntendedExists=[bool]$Intended.Exists;
        IntendedKind=$Intended.Kind;
        IntendedValue=$Intended.Value;

        AppliedExists=$null;
        AppliedKind=$null;
        AppliedValue=$null;
        Status='Pending'

    }
    if($null-ne$JournalMetadata){
        foreach($metadataKey in @($JournalMetadata.Keys)){
            $entry|Add-Member -NotePropertyName ([string]$metadataKey) -NotePropertyValue $JournalMetadata[$metadataKey] -Force
        }
    }
    $Session.Entries+=,$entry
    Save-VSO7NativeBackupSessionVSO -Session $Session
    return $entry

}

function Test-VSO7NativeRegistryKeyExistsVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $parts=Get-VSO7NativeRegistryPartsVSO -Path $Path;
    $base=$null;
    $sub=$null
    try{
        $base=Open-VSO7NativeRegistryBaseVSO -Hive $parts.Hive;
        $sub=$base.OpenSubKey($parts.SubKey,$false);
        return($null-ne$sub)
    }finally{
        if($null-ne$sub){
            $sub.Dispose()
        };
        if($null-ne$base){
            $base.Dispose()
        }
    }

}

function Assert-VSO7NativeRegistryExportFileVSO {

    param(
        [Parameter(Mandatory=$true)][string]$FilePath,
        [Parameter(Mandatory=$true)][string]$ExpectedRegistryPath,
        [string]$ExpectedSha256=''
    )
    $full=[IO.Path]::GetFullPath($FilePath)
    if([IO.Path]::GetExtension($full)-ine'.reg'){
        throw 'Extension de backup Registry no valida.'
    }
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'Backup .reg no puede ser contenedor ni reparse point.'
    }
    if([int64]$item.Length-le0-or[int64]$item.Length-gt134217728){
        throw 'Backup .reg tiene un tamano no permitido.'
    }
    $actualHash=(Get-FileHash -LiteralPath $full -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
    if(-not[string]::IsNullOrWhiteSpace([string]$ExpectedSha256)){

        $expected=([string]$ExpectedSha256).Trim().ToUpperInvariant()
        if($expected-notmatch'^[0-9A-F]{64}$'-or$actualHash-cne$expected){
            throw 'SHA-256 del backup .reg no coincide con el capturado.'
        }

    }
    $lines=[IO.File]::ReadAllLines($full)
    $firstNonEmpty=$null;
    $sectionCount=0
    foreach($raw in $lines){

        $line=([string]$raw).Trim()
        if([string]::IsNullOrWhiteSpace($line)){
            continue
        }
        if($null-eq$firstNonEmpty){
            $firstNonEmpty=$line;
            continue
        }
        if($line.StartsWith('[',[StringComparison]::Ordinal)){

            if($line-notmatch'^\[([^\]]+)\]$'){
                throw 'Backup .reg contiene una cabecera de seccion no valida.'
            }
            $section=[string]$Matches[1]
            if($section.StartsWith('-',[StringComparison]::Ordinal)){
                throw 'Backup .reg contiene una seccion de eliminacion no permitida.'
            }
            $inside=($section-ieq$ExpectedRegistryPath)-or$section.StartsWith(($ExpectedRegistryPath+'\'),[StringComparison]::OrdinalIgnoreCase)
            if(-not$inside){
                throw ('Backup .reg intenta escribir fuera de la clave esperada: {0}'-f$section)
            }
            $sectionCount++

        }

    }
    if([string]$firstNonEmpty-cne'Windows Registry Editor Version 5.00'){
        throw 'Backup .reg no tiene la cabecera esperada de reg.exe export.'
    }
    if($sectionCount-lt1){
        throw 'Backup .reg no contiene ninguna seccion Registry valida.'
    }
    return $actualHash

}

function Add-VSO7NativeKeyBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$Path,[bool]$IntendedExists=$false)
    $key=('key|'+$Path.ToLowerInvariant());
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1);
    if($existing.Count){
        return $existing[0]
    }
    $exists=Test-VSO7NativeRegistryKeyExistsVSO -Path $Path
    $export=$null;
    $baselineFingerprint=$null;
    $exportSha256=$null
    if($exists){

        $baselineFingerprint=Get-VSO7NativeRegistryKeyFingerprintVSO -Path $Path
        if([string]::IsNullOrWhiteSpace([string]$baselineFingerprint)){
            throw ('No se pudo capturar fingerprint del baseline Registry: {0}'-f$Path)
        }
        $export=Join-Path ([string]$Session.Directory) (('key_{0}.reg'-f(@($Session.Entries).Count+1)))
        $reg=Resolve-VSOSystemExecutable -Name 'reg.exe';
        & $reg export $Path $export /y | Out-Null;
        $rc=$LASTEXITCODE
        if($rc-ne0){
            throw ('reg.exe export termino con codigo {0}'-f$rc)
        }
        if(-not(Test-Path -LiteralPath $export -PathType Leaf)){
            throw 'No se creo el backup .reg esperado.'
        }
        $exportSha256=(Get-FileHash -LiteralPath $export -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        [void](Assert-VSO7NativeRegistryExportFileVSO -FilePath $export -ExpectedRegistryPath $Path -ExpectedSha256 $exportSha256)
        $afterExportFingerprint=Get-VSO7NativeRegistryKeyFingerprintVSO -Path $Path
        if([string]$afterExportFingerprint-cne[string]$baselineFingerprint){
            throw ('Registry key cambio durante la captura del baseline: {0}'-f$Path)
        }

    }
    $entry=[pscustomobject]@{
        Type='RegistryKey';
        Key=$key;
        Path=$Path;
        Exists=$exists;
        ExportFile=$export;
        ExportSha256=$exportSha256;
        BaselineFingerprint=$baselineFingerprint;
        IntendedExists=$IntendedExists;
        AppliedExists=$null;
        Status='Pending'
    }
    $Session.Entries+=,$entry;
    Save-VSO7NativeBackupSessionVSO -Session $Session;
    return $entry

}

function Get-VSO7NativeOptionalFeatureStateClassVSO {

    param([Parameter(Mandatory=$true)][string]$State)
    switch -Exact ($State){

        'Enabled' {
            return 'Enabled'
        }
        'Installed' {
            return 'Enabled'
        }
        'Disabled' {
            return 'Disabled'
        }
        'DisabledWithPayloadRemoved' {
            return 'Disabled'
        }
        'NotPresent' {
            return 'Disabled'
        }
        'Staged' {
            return 'Disabled'
        }
        'Removed' {
            return 'Disabled'
        }
        'EnablePending' {
            return 'EnablePending'
        }
        'InstallPending' {
            return 'EnablePending'
        }
        'DisablePending' {
            return 'DisablePending'
        }
        'UninstallPending' {
            return 'DisablePending'
        }
        'Superseded' {
            return 'Unsupported'
        }
        'PartiallyInstalled' {
            return 'Unsupported'
        }
        default {
            return $null
        }

    }

}

function Test-VSO7NativeOptionalFeatureAppliedOwnedVSO {

    param([Parameter(Mandatory=$true)][string]$CurrentState,[Parameter(Mandatory=$true)][string]$RecordedAppliedState)
    if([string]$CurrentState-ieq[string]$RecordedAppliedState){
        return $true
    }
    $recordedClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $RecordedAppliedState
    $currentClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $CurrentState
    if($recordedClass-eq'EnablePending'-and$currentClass-eq'Enabled'){
        return $true
    }
    if($recordedClass-eq'DisablePending'-and$currentClass-eq'Disabled'){
        return $true
    }
    return $false

}

function Test-VSO7NativeOptionalFeaturePendingOwnedVSO {

    param([Parameter(Mandatory=$true)][string]$CurrentState,[Parameter(Mandatory=$true)][ValidateSet('Enabled','Disabled')][string]$IntendedState)
    $currentClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $CurrentState
    if($IntendedState-eq'Enabled'){
        return @('Enabled','EnablePending')-contains$currentClass
    }
    return @('Disabled','DisablePending')-contains$currentClass

}

function Add-VSO7NativeOptionalFeatureBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][ValidateSet('Enabled','Disabled')][string]$IntendedState)
    $key=('feature|'+$Name.ToLowerInvariant());
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1);
    if($existing.Count){
        return $existing[0]
    }
    $state=(Dism\Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop).State.ToString()
    $stateClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $state
    if($stateClass-notin@('Enabled','Disabled')){
        throw ("VSO7 no modifica {0} porque su estado previo no es estable/reversible: {1}"-f$Name,$state)
    }
    # Recovery nativo solo puede demostrar/restaurar exactamente los baselines estables del cmdlet DISM.
    # Estados como Removed/DisabledWithPayloadRemoved/NotPresent/Installed se reconocen para ownership y compatibilidad,
    # pero no se mutan automaticamente porque un Enable/Disable posterior no garantiza reconstruir el mismo estado de payload.
    if($state-notin@('Enabled','Disabled')){
        throw ("VSO7 no modifica {0} porque el baseline DISM no es restaurable de forma exacta: {1}"-f$Name,$state)
    }
    $entry=[pscustomobject]@{
        Type='OptionalFeature';
        Key=$key;
        Name=$Name;
        State=$state;
        IntendedState=$IntendedState;
        AppliedState=$null;
        Status='Pending'
    }
    $Session.Entries+=,$entry;
    Save-VSO7NativeBackupSessionVSO -Session $Session;
    return $entry

}

function Add-VSO7NativeNonReversibleBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$Id,[Parameter(Mandatory=$true)][string]$Description)
    $key=('nonreversible|'+$Id.ToLowerInvariant());
    if(@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }).Count-gt0){
        return
    }
    $Session.Entries+=,[pscustomobject]@{
        Type='NonReversible';
        Key=$key;
        Id=$Id;
        Description=$Description
    }
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Invoke-VSO7NativeRegistryOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation,[AllowNull()][hashtable]$JournalMetadata)
    $action=[string]$Operation.Action;
    $path=[string]$Operation.Path
    switch($action){

        'SetValue' {

            $name=[string]$Operation.Name
            $intended=ConvertTo-VSO7NativeDesiredRegistrySnapshotVSO -Kind ([string]$Operation.Kind) -Value $Operation.Value
            $before=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name $name
            if(Test-VSO7NativeRegistrySnapshotEqualVSO -A $before -B $intended){
                return
            }
            $entry=Add-VSO7NativeValueBackupVSO -Session $Session -Path $path -Name $name -Intended $intended -JournalMetadata $JournalMetadata
            $baseline=[pscustomobject]@{
                Exists=[bool]$entry.Exists;
                Kind=$entry.Kind;
                Value=$entry.Value
            }
            if([string]$entry.Status-ceq'Applied'){

                if(Test-VSO7NativeRegistrySnapshotEqualVSO -A $before -B $intended){
                    return
                }
                throw ('Registry target ya fue aplicado por otra feature del lote y luego cambio: {0}\{1}'-f$path,$name)

            }
            if(-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $before -B $baseline)){
                throw ('Registry cambio entre baseline y mutacion: {0}\{1}'-f$path,$name)
            }
            Set-VSO7NativeRegistryValueRawVSO -Path $path -Name $name -Kind ([string]$Operation.Kind) -Value $Operation.Value
            $after=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name $name
            if(-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $after -B $intended)){
                throw ('No se verifico exactamente el valor Registry {0}\{1}'-f$path,$name)
            }
            $entry.AppliedExists=[bool]$after.Exists;
            $entry.AppliedKind=$after.Kind;
            $entry.AppliedValue=$after.Value;
            $entry.Status='Applied';
            Save-VSO7NativeBackupSessionVSO -Session $Session

        }
        'DeleteValue' {

            $name=[string]$Operation.Name;
            $intended=[pscustomobject]@{
                Exists=$false;
                Kind=$null;
                Value=$null
            }
            $before=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name $name
            if(-not[bool]$before.Exists){
                return
            }
            $entry=Add-VSO7NativeValueBackupVSO -Session $Session -Path $path -Name $name -Intended $intended -JournalMetadata $JournalMetadata
            $baseline=[pscustomobject]@{
                Exists=[bool]$entry.Exists;
                Kind=$entry.Kind;
                Value=$entry.Value
            }
            if([string]$entry.Status-ceq'Applied'){

                if(-not[bool]$before.Exists){
                    return
                }
                throw ('Registry target ya fue eliminado por otra feature del lote y luego reaparecio: {0}\{1}'-f$path,$name)

            }
            if(-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $before -B $baseline)){
                throw ('Registry cambio entre baseline y mutacion: {0}\{1}'-f$path,$name)
            }
            Remove-VSO7NativeRegistryValueRawVSO -Path $path -Name $name
            $after=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name $name
            if([bool]$after.Exists){
                throw ('No se verifico la eliminacion Registry {0}\{1}'-f$path,$name)
            }
            $entry.AppliedExists=$false;
            $entry.AppliedKind=$null;
            $entry.AppliedValue=$null;
            $entry.Status='Applied';
            Save-VSO7NativeBackupSessionVSO -Session $Session

        }
        'DeleteKey' {

            if(-not(Test-VSO7NativeRegistryKeyExistsVSO -Path $path)){
                return
            }
            $entry=Add-VSO7NativeKeyBackupVSO -Session $Session -Path $path -IntendedExists $false
            if(-not(Test-VSO7NativeRegistryKeyBaselineMatchVSO -Entry $entry)){
                throw ('Registry key cambio entre baseline y mutacion: {0}'-f$path)
            }
            Remove-VSO7NativeRegistryKeyRawVSO -Path $path
            if(Test-VSO7NativeRegistryKeyExistsVSO -Path $path){
                throw ('No se verifico la eliminacion Registry key {0}'-f$path)
            }
            $entry.AppliedExists=$false;
            $entry.Status='Applied';
            Save-VSO7NativeBackupSessionVSO -Session $Session

        }
        default {
            throw ('Operacion nativa desconocida: {0}'-f$action)
        }

    }

}

function Get-VSO7NativePowerSettingSnapshotVSO {

    param(
        [Parameter(Mandatory=$true)][string]$SubGroupAlias,
        [Parameter(Mandatory=$true)][string]$SettingAlias,
        [AllowNull()][string]$SchemeGuid
    )
    return (Get-VSO7PowerSettingProviderSnapshotVSO -SubGroupAlias $SubGroupAlias -SettingAlias $SettingAlias -SchemeGuid $SchemeGuid)

}

function Add-VSO7NativePowerSettingBackupVSO {

    param(
        [Parameter(Mandatory=$true)]$Session,
        [Parameter(Mandatory=$true)][string]$SubGroupAlias,
        [Parameter(Mandatory=$true)][string]$SettingAlias,
        [Parameter(Mandatory=$true)][int]$IntendedAC,
        [Parameter(Mandatory=$true)][int]$IntendedDC,
        [Parameter(Mandatory=$true)][bool]$OwnsAC,
        [Parameter(Mandatory=$true)][bool]$OwnsDC
    )
    if(-not$OwnsAC-and-not$OwnsDC){
        throw 'PowerSetting no declara ownership sobre AC ni DC.'
    }
    $snap=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $SubGroupAlias -SettingAlias $SettingAlias
    $key=('power|'+$snap.SchemeGuid+'|'+$SubGroupAlias+'|'+$SettingAlias).ToLowerInvariant();
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){

        $e=$existing[0]
        if(($e.PSObject.Properties.Name-contains'OwnsAC')-and([bool]$e.OwnsAC-ne$OwnsAC-or[bool]$e.OwnsDC-ne$OwnsDC)){
            throw 'PowerSetting duplicado con ownership AC/DC incompatible dentro del mismo lote.'
        }
        return $e

    }
    $entry=[pscustomobject]@{
        Type='PowerSetting';
        Key=$key;
        SchemeGuid=$snap.SchemeGuid;
        SubGroupAlias=$SubGroupAlias;
        SettingAlias=$SettingAlias;
        AC=$snap.AC;
        DC=$snap.DC;
        IntendedAC=$IntendedAC;
        IntendedDC=$IntendedDC;
        OwnsAC=$OwnsAC;
        OwnsDC=$OwnsDC;
        AppliedAC=$null;
        AppliedDC=$null;
        Status='Pending'
    }
    $Session.Entries+=,$entry;
    Save-VSO7NativeBackupSessionVSO -Session $Session;
    return $entry

}

function Invoke-VSO7NativePowerSettingOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'SetPowerSetting'){
        throw ('Operacion PowerSetting desconocida: {0}'-f$Operation.Action)
    }
    $sub=[string]$Operation.SubGroupAlias;
    $setting=[string]$Operation.SettingAlias
    $before=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $sub -SettingAlias $setting
    $requestedAC=$false;
    $requestedDC=$false;
    $targetAC=[int]$before.AC;
    $targetDC=[int]$before.DC
    if($Operation.PSObject.Properties.Name-contains'AC'-and[string]$Operation.AC-ine'Preserve'){
        $targetAC=[int]$Operation.AC;
        $requestedAC=$true
    }
    if($Operation.PSObject.Properties.Name-contains'DC'-and[string]$Operation.DC-ine'Preserve'){
        $targetDC=[int]$Operation.DC;
        $requestedDC=$true
    }
    if(-not$requestedAC-and-not$requestedDC){
        throw 'Operacion PowerSetting no modifica AC ni DC.'
    }
    $key=('power|'+$before.SchemeGuid+'|'+$sub+'|'+$setting).ToLowerInvariant()
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-ceq$key
    }|Select-Object -First 1)
    if($existing.Count-eq0){

        $entry=Add-VSO7NativePowerSettingBackupVSO -Session $Session -SubGroupAlias $sub -SettingAlias $setting -IntendedAC $targetAC -IntendedDC $targetDC -OwnsAC $requestedAC -OwnsDC $requestedDC

    }else{

        $entry=$existing[0]
        $oldOwnAC=[bool]$entry.OwnsAC;
        $oldOwnDC=[bool]$entry.OwnsDC
        if($requestedAC-and$oldOwnAC-and[int]$entry.IntendedAC-ne$targetAC){
            throw 'PowerSetting duplicado intenta un valor AC incompatible dentro del lote.'
        }
        if($requestedDC-and$oldOwnDC-and[int]$entry.IntendedDC-ne$targetDC){
            throw 'PowerSetting duplicado intenta un valor DC incompatible dentro del lote.'
        }
        $expectedAC=if($oldOwnAC){
            [int]$entry.IntendedAC
        }else{
            [int]$entry.AC
        }
        $expectedDC=if($oldOwnDC){
            [int]$entry.IntendedDC
        }else{
            [int]$entry.DC
        }
        if($before.SchemeGuid-ine[string]$entry.SchemeGuid-or$before.AC-ne$expectedAC-or$before.DC-ne$expectedDC){
            throw 'PowerSetting compartido cambio entre operaciones del lote.'
        }
        if($requestedAC){
            $entry.IntendedAC=$targetAC;
            $entry.OwnsAC=$true
        }
        if($requestedDC){
            $entry.IntendedDC=$targetDC;
            $entry.OwnsDC=$true
        }
        Save-VSO7NativeBackupSessionVSO -Session $Session

    }
    $finalAC=if([bool]$entry.OwnsAC){
        [int]$entry.IntendedAC
    }else{
        [int]$entry.AC
    }
    $finalDC=if([bool]$entry.OwnsDC){
        [int]$entry.IntendedDC
    }else{
        [int]$entry.DC
    }
    $subGuid=Get-PowerAliasGuidVSO -Alias $sub;
    $settingGuid=Get-PowerAliasGuidVSO -Alias $setting
    # AC/DC are separate writes. Revalidate the complete pair immediately before each
    # command so an external change in the gap is never overwritten as if it were ours.
    $preWrite=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $sub -SettingAlias $setting -SchemeGuid ([string]$entry.SchemeGuid)
    if(([string]$preWrite.SchemeGuid-and[string]$preWrite.SchemeGuid-ine[string]$entry.SchemeGuid)-or[int]$preWrite.AC-ne[int]$before.AC-or[int]$preWrite.DC-ne[int]$before.DC){
        throw 'PowerSetting cambio externamente antes de la primera escritura; VSO7 aborta sin sobrescribirlo.'
    }
    if([string](Get-ActivePowerSchemeGuid)-ine[string]$entry.SchemeGuid){throw 'El plan activo cambio antes de la mutacion PowerSetting.'}
    if($before.AC-ne$finalAC){
        Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setacvalueindex',[string]$entry.SchemeGuid,$subGuid,$settingGuid,[string]$finalAC)|Out-Null
        $afterAC=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $sub -SettingAlias $setting -SchemeGuid ([string]$entry.SchemeGuid)
        if(([string]$afterAC.SchemeGuid-and[string]$afterAC.SchemeGuid-ine[string]$entry.SchemeGuid)-or$afterAC.AC-ne$finalAC-or$afterAC.DC-ne$before.DC){throw 'No se verifico la escritura AC aislada del PowerSetting o DC cambio externamente durante ella.'}
        $entry.AppliedAC=[int]$afterAC.AC;Save-VSO7NativeBackupSessionVSO -Session $Session
    }elseif([bool]$entry.OwnsAC){$entry.AppliedAC=[int]$before.AC;Save-VSO7NativeBackupSessionVSO -Session $Session}
    $expectedBeforeDCAC=if($before.AC-ne$finalAC){[int]$finalAC}else{[int]$before.AC}
    $preDC=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $sub -SettingAlias $setting -SchemeGuid ([string]$entry.SchemeGuid)
    if(([string]$preDC.SchemeGuid-and[string]$preDC.SchemeGuid-ine[string]$entry.SchemeGuid)-or[int]$preDC.AC-ne$expectedBeforeDCAC-or[int]$preDC.DC-ne[int]$before.DC){
        throw 'PowerSetting cambio externamente entre las escrituras AC/DC; VSO7 no sobrescribe el lado modificado.'
    }
    if([string](Get-ActivePowerSchemeGuid)-ine[string]$entry.SchemeGuid){throw 'El plan activo cambio antes de la escritura DC PowerSetting.'}
    if($before.DC-ne$finalDC){
        Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setdcvalueindex',[string]$entry.SchemeGuid,$subGuid,$settingGuid,[string]$finalDC)|Out-Null
        $afterDC=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $sub -SettingAlias $setting -SchemeGuid ([string]$entry.SchemeGuid)
        if(([string]$afterDC.SchemeGuid-and[string]$afterDC.SchemeGuid-ine[string]$entry.SchemeGuid)-or$afterDC.AC-ne$expectedBeforeDCAC-or$afterDC.DC-ne$finalDC){throw 'No se verifico la escritura DC aislada del PowerSetting o AC cambio externamente durante ella.'}
        $entry.AppliedDC=[int]$afterDC.DC;Save-VSO7NativeBackupSessionVSO -Session $Session
    }elseif([bool]$entry.OwnsDC){$entry.AppliedDC=[int]$before.DC;Save-VSO7NativeBackupSessionVSO -Session $Session}
    $after=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias $sub -SettingAlias $setting -SchemeGuid ([string]$entry.SchemeGuid)
    if($after.SchemeGuid-ine[string]$entry.SchemeGuid-or$after.AC-ne$finalAC-or$after.DC-ne$finalDC){
        throw 'El PowerSetting no coincide con el estado agregado solicitado.'
    }
    if([string](Get-ActivePowerSchemeGuid)-ine[string]$entry.SchemeGuid){
        throw 'El plan activo cambio durante la mutacion; VSO7 no fuerza otro plan.'
    }
    Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive','SCHEME_CURRENT')|Out-Null
    if([string](Get-ActivePowerSchemeGuid)-ine[string]$entry.SchemeGuid){
        throw 'El plan activo cambio durante la aplicacion del PowerSetting.'
    }
    $entry.AppliedAC=[int]$after.AC;
    $entry.AppliedDC=[int]$after.DC;
    $entry.Status='Applied';
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Get-VSO7PhysicalAdapterTargetsVSO {

    param([switch]$OnlyUp)
    if($null-eq(Get-Command 'Get-NetAdapter' -ErrorAction SilentlyContinue)){
        return @()
    }
    $result=@()
    foreach($adapter in @(Get-NetAdapter -Physical -IncludeHidden -ErrorAction Stop)){

        if($OnlyUp-and[string]$adapter.Status-ine'Up'){
            continue
        }
        $guid=[string]$adapter.InterfaceGuid;
        $pnp=[string]$adapter.PnPDeviceID;
        $desc=[string]$adapter.InterfaceDescription
        if([string]::IsNullOrWhiteSpace($guid)-or[string]::IsNullOrWhiteSpace($desc)){
            continue
        }
        $result+=[pscustomobject]@{
            Name=[string]$adapter.Name;
            InterfaceGuid=$guid;
            PnPDeviceID=$pnp;
            InterfaceDescription=$desc;
            InterfaceIndex=[uint32]$adapter.InterfaceIndex;
            Status=[string]$adapter.Status;
            PhysicalMediaType=[string]$adapter.PhysicalMediaType
        }

    }
    return @($result)

}

function Resolve-VSO7NetAdapterIdentityVSO {

    param([Parameter(Mandatory=$true)]$Identity,[int]$WaitMilliseconds=0)
    $guid=[string]$Identity.InterfaceGuid
    if([string]::IsNullOrWhiteSpace($guid)){
        throw 'Falta InterfaceGuid para resolver la NIC de forma segura.'
    }
    $deadline=[DateTime]::UtcNow.AddMilliseconds([Math]::Max(0,$WaitMilliseconds))
    do{

        $matches=@(Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue|Where-Object{
            [string]$_.InterfaceGuid-ieq$guid
        })
        if($matches.Count-eq1){

            $adapter=$matches[0]
            $expectedPnp=[string]$Identity.PnPDeviceID
            if(-not[string]::IsNullOrWhiteSpace($expectedPnp)-and[string]$adapter.PnPDeviceID-ine$expectedPnp){
                throw 'InterfaceGuid coincide pero PnPDeviceID cambio; VSO7 falla cerrado.'
            }
            if($adapter.PSObject.Properties.Name-contains'HardwareInterface'){

                if(-not[bool]$adapter.HardwareInterface){
                    throw 'La identidad resuelta ya no corresponde a una interfaz hardware.'
                }

            }
            return $adapter

        }
        if([DateTime]::UtcNow-ge$deadline){
            break
        }
        Start-Sleep -Milliseconds 250

    }while($true)
    throw ('No se encontro exactamente una NIC con InterfaceGuid {0}.'-f$guid)

}

function Get-VSO7PhysicalRssTargetsVSO {

    if($null-eq(Get-Command 'Get-NetAdapterRss' -ErrorAction SilentlyContinue)){
        return @()
    }
    $identities=@(Get-VSO7PhysicalAdapterTargetsVSO -OnlyUp)
    if($identities.Count-eq0){
        return @()
    }
    # Una consulta bulk distingue correctamente "NIC sin RSS" de "provider RSS fallo".
    # Get-NetAdapterRss -Name '*' enumera solo adaptadores RSS-capable; cualquier error del provider es fatal.
    $rssRows=@(Get-NetAdapterRss -Name '*' -IncludeHidden -ErrorAction Stop)
    $targets=@()
    foreach($identity in $identities){

        $matches=@($rssRows|Where-Object{

            (($PSItem.PSObject.Properties.Name-contains'Name')-and([string]$PSItem.Name-ceq[string]$identity.Name))-or
            (($PSItem.PSObject.Properties.Name-contains'InterfaceDescription')-and([string]$PSItem.InterfaceDescription-ceq[string]$identity.InterfaceDescription))

        })
        if($matches.Count-eq0){
            continue
        }
        if($matches.Count-ne1){
            throw ('RSS devolvio una identidad ambigua para la NIC {0}.'-f$identity.Name)
        }
        $rss=$matches[0]
        $targets+=[pscustomobject]@{
            Name=[string]$identity.Name;
            InterfaceGuid=[string]$identity.InterfaceGuid;
            PnPDeviceID=[string]$identity.PnPDeviceID;
            InterfaceDescription=[string]$identity.InterfaceDescription;
            Enabled=[bool]$rss.Enabled
        }

    }
    return @($targets)

}

function Add-VSO7NativeRssBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Target,[Parameter(Mandatory=$true)][bool]$IntendedEnabled)
    $guid=[string]$Target.InterfaceGuid;
    if([string]::IsNullOrWhiteSpace($guid)){
        throw 'RSS requiere InterfaceGuid en backups creados por el esquema actual.'
    }
    $key=('rss|'+$guid.ToLowerInvariant());
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1);
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{
        Type='NetAdapterRss';
        Key=$key;
        Name=[string]$Target.Name;
        InterfaceGuid=$guid;
        PnPDeviceID=[string]$Target.PnPDeviceID;
        InterfaceDescription=[string]$Target.InterfaceDescription;
        Enabled=[bool]$Target.Enabled;
        IntendedEnabled=$IntendedEnabled;
        AppliedEnabled=$null;
        Status='Pending'
    }
    $Session.Entries+=,$entry;
    Save-VSO7NativeBackupSessionVSO -Session $Session;
    return $entry

}

function Get-VSO7RssCurrentForEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    if($Entry.PSObject.Properties.Name-contains'InterfaceGuid'-and-not[string]::IsNullOrWhiteSpace([string]$Entry.InterfaceGuid)){

        $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $Entry
        $rss=Get-NetAdapterRss -Name ([string]$adapter.Name) -ErrorAction Stop
        return [pscustomobject]@{
            Name=[string]$adapter.Name;
            InterfaceGuid=[string]$adapter.InterfaceGuid;
            PnPDeviceID=[string]$adapter.PnPDeviceID;
            InterfaceDescription=[string]$adapter.InterfaceDescription;
            Enabled=[bool]$rss.Enabled
        }

    }
    # Backups Schema 2 antiguos pueden no tener identidad NIC robusta; usa la descripción guardada como fallback.
    $desc=[string]$Entry.InterfaceDescription
    $adapters=@(Get-NetAdapter -IncludeHidden -ErrorAction Stop|Where-Object{
        [string]$_.InterfaceDescription-ceq$desc
    })
    if($adapters.Count-ne1){
        throw ('Backup RSS legado no puede resolverse inequivocamente: {0}'-f$desc)
    }
    $rss=Get-NetAdapterRss -InterfaceDescription $desc -ErrorAction Stop
    return [pscustomobject]@{
        Name=[string]$adapters[0].Name;
        InterfaceDescription=$desc;
        Enabled=[bool]$rss.Enabled
    }

}

function Invoke-VSO7NativeRssOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'EnableRss'){
        throw ('Operacion RSS desconocida: {0}'-f$Operation.Action)
    }
    $targets=@(Get-VSO7PhysicalRssTargetsVSO|Where-Object{
        -not[bool]$_.Enabled
    })
    if($targets.Count-eq0){
        return
    }

    # Transaction group: journal every target before the first mutation.
    $changes=@()
    foreach($target in $targets){

        $entry=Add-VSO7NativeRssBackupVSO -Session $Session -Target $target -IntendedEnabled $true
        $changes+=[pscustomobject]@{
            Entry=$entry
        }

    }
    foreach($change in $changes){

        $entry=$change.Entry;
        $before=Get-VSO7RssCurrentForEntryVSO -Entry $entry
        if([bool]$before.Enabled-ne[bool]$entry.Enabled){
            throw ('RSS cambio entre baseline y mutacion en {0}.'-f$entry.InterfaceDescription)
        }

    }
    foreach($change in $changes){

        $entry=$change.Entry;
        $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $entry
        Enable-NetAdapterRss -Name ([string]$adapter.Name) -Confirm:$false -ErrorAction Stop|Out-Null
        $after=Get-VSO7RssCurrentForEntryVSO -Entry $entry
        if(-not[bool]$after.Enabled){
            throw ('Windows no confirmo RSS activo en {0}.'-f$entry.InterfaceDescription)
        }
        $entry.AppliedEnabled=$true;
        $entry.Status='Applied';
        Save-VSO7NativeBackupSessionVSO -Session $Session

    }
    $targetStates=@()
    foreach($t in @(Get-VSO7PhysicalRssTargetsVSO)){

        $owned=@($Session.Entries|Where-Object{
            [string]$_.Type-eq'NetAdapterRss'-and[string]$_.InterfaceGuid-ieq[string]$t.InterfaceGuid
        })
        $state=if($owned.Count-eq0){
            if([bool]$t.Enabled){
                'Baseline'
            }else{
                'Error'
            }
        }elseif(@($owned|Where-Object{
            [string]$_.Status-ne'Applied'
        }).Count-eq0){
            'Applied'
        }else{
            'Partial'
        }
        $targetStates+=[pscustomobject]@{
            Target=[string]$t.InterfaceDescription;
            Identity=[string]$t.InterfaceGuid;
            State=$state
        }

    }
    $aggregate=Get-VSO7AggregateTargetStateVSO -Targets $targetStates
    $Session|Add-Member -NotePropertyName TargetStateSummary -NotePropertyValue $aggregate -Force
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Test-VSO7StringSequenceEqualVSO {

    param($A,$B)
    $aa=@($A|ForEach-Object{
        [string]$_
    });
    $bb=@($B|ForEach-Object{
        [string]$_
    })
    if($aa.Count-ne$bb.Count){
        return $false
    }
    for($i=0;$i-lt$aa.Count;$i++){
        if($aa[$i]-cne$bb[$i]){
            return $false
        }
    }
    return $true

}

function Get-VSO7AdapterAdvancedPropertySnapshotVSO {

    param([Parameter(Mandatory=$true)]$Identity,[Parameter(Mandatory=$true)][string]$RegistryKeyword)
    $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $Identity
    $all=@(Get-NetAdapterAdvancedProperty -Name ([string]$adapter.Name) -AllProperties -ErrorAction Stop)
    $props=@($all|Where-Object{
        [string]$_.RegistryKeyword-ieq$RegistryKeyword
    })
    if($props.Count-eq0){
        return $null
    }
    if($props.Count-ne1){
        throw ('Provider NetAdapter devolvio {0} propiedades para {1}/{2}; se aborta por ambiguedad.'-f$props.Count,$adapter.InterfaceDescription,$RegistryKeyword)
    }
    $p=$props[0]
    return [pscustomobject]@{

        Name=[string]$adapter.Name;
        InterfaceGuid=[string]$adapter.InterfaceGuid;
        PnPDeviceID=[string]$adapter.PnPDeviceID;
        InterfaceDescription=[string]$adapter.InterfaceDescription;

        RegistryKeyword=[string]$p.RegistryKeyword;
        RegistryValue=@($p.RegistryValue|ForEach-Object{
            [string]$_
        });
        ValidRegistryValues=@($p.ValidRegistryValues|ForEach-Object{
            [string]$_
        });
        DisplayName=[string]$p.DisplayName;
        DisplayValue=[string]$p.DisplayValue

    }

}

function Add-VSO7NativeAdapterPropertyBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Snapshot,[Parameter(Mandatory=$true)][string[]]$IntendedValue)
    $guid=[string]$Snapshot.InterfaceGuid;
    $keyword=[string]$Snapshot.RegistryKeyword
    if([string]::IsNullOrWhiteSpace($guid)-or[string]::IsNullOrWhiteSpace($keyword)){
        throw 'Snapshot de propiedad NIC sin identidad robusta.'
    }
    $key=('netadv|'+$guid+'|'+$keyword).ToLowerInvariant();
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1);
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{
        Type='NetAdapterAdvancedProperty';
        Key=$key;
        Name=[string]$Snapshot.Name;
        InterfaceGuid=$guid;
        PnPDeviceID=[string]$Snapshot.PnPDeviceID;
        InterfaceDescription=[string]$Snapshot.InterfaceDescription;
        RegistryKeyword=$keyword;
        RegistryValue=@($Snapshot.RegistryValue);
        IntendedValue=@($IntendedValue);
        AppliedValue=$null;
        Status='Pending'
    }
    $Session.Entries+=,$entry;
    Save-VSO7NativeBackupSessionVSO -Session $Session;
    return $entry

}

function Invoke-VSO7NativeAdapterAdvancedOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'SetAdvancedProperties'){
        throw ('Operacion NetAdapterAdvanced desconocida: {0}'-f$Operation.Action)
    }
    $specs=@($Operation.Properties);
    if($specs.Count-eq0){
        throw 'SetAdvancedProperties no contiene propiedades.'
    }

    # Discover and journal every adapter/property before the first mutation.
    $groups=@()
    foreach($identity in @(Get-VSO7PhysicalAdapterTargetsVSO -OnlyUp)){

        $changes=@()
        foreach($spec in $specs){

            $keyword=[string]$spec.RegistryKeyword;
            $desired=@([string]$spec.RegistryValue)
            $snap=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $identity -RegistryKeyword $keyword
            if($null-eq$snap){
                continue
            }
            $valid=@($snap.ValidRegistryValues)
            if($valid.Count-eq0-or@($desired|Where-Object{
                $valid-cnotcontains[string]$_
            }).Count-gt0){
                continue
            }
            if(Test-VSO7StringSequenceEqualVSO -A $snap.RegistryValue -B $desired){
                continue
            }
            $entry=Add-VSO7NativeAdapterPropertyBackupVSO -Session $Session -Snapshot $snap -IntendedValue $desired
            $changes+=[pscustomobject]@{
                Entry=$entry;
                Desired=$desired
            }

        }
        if($changes.Count-gt0){
            $groups+=,[pscustomobject]@{
                Changes=@($changes)
            }
        }

    }
    if($groups.Count-eq0){
        return
    }

    # Revalidate every baseline before starting any mutation.
    foreach($group in $groups){

        foreach($change in @($group.Changes)){

            $entry=$change.Entry;
            $before=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $entry -RegistryKeyword ([string]$entry.RegistryKeyword)
            if($null-eq$before-or-not(Test-VSO7StringSequenceEqualVSO -A $before.RegistryValue -B $entry.RegistryValue)){
                throw ('Propiedad NIC cambio entre baseline y mutacion: {0}/{1}'-f$entry.InterfaceDescription,$entry.RegistryKeyword)
            }

        }

    }

    foreach($group in $groups){

        $changes=@($group.Changes)
        foreach($change in $changes){

            $entry=$change.Entry;
            $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $entry
            Set-NetAdapterAdvancedProperty -Name ([string]$adapter.Name) -RegistryKeyword ([string]$entry.RegistryKeyword) -RegistryValue ([string[]]@($change.Desired)) -NoRestart -Confirm:$false -ErrorAction Stop|Out-Null
            $stored=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $entry -RegistryKeyword ([string]$entry.RegistryKeyword)
            if($null-eq$stored-or-not(Test-VSO7StringSequenceEqualVSO -A $stored.RegistryValue -B $change.Desired)){
                throw ('No se verifico la propiedad NIC almacenada: {0}/{1}'-f$entry.InterfaceDescription,$entry.RegistryKeyword)
            }

        }
        $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $changes[0].Entry
        Restart-NetAdapter -Name ([string]$adapter.Name) -Confirm:$false -ErrorAction Stop|Out-Null
        [void](Resolve-VSO7NetAdapterIdentityVSO -Identity $changes[0].Entry -WaitMilliseconds 10000)
        foreach($change in $changes){

            $entry=$change.Entry;
            $after=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $entry -RegistryKeyword ([string]$entry.RegistryKeyword)
            if($null-eq$after-or-not(Test-VSO7StringSequenceEqualVSO -A $after.RegistryValue -B $change.Desired)){
                throw ('La propiedad NIC no coincide despues del reinicio: {0}/{1}'-f$entry.InterfaceDescription,$entry.RegistryKeyword)
            }
            $entry.AppliedValue=@($after.RegistryValue);
            $entry.Status='Applied';
            Save-VSO7NativeBackupSessionVSO -Session $Session

        }

    }
    $targetStates=@()
    foreach($identity in @(Get-VSO7PhysicalAdapterTargetsVSO -OnlyUp)){

        $supported=0;
        $ownedCount=0;
        $ownedApplied=0
        foreach($spec in $specs){

            $snap=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $identity -RegistryKeyword ([string]$spec.RegistryKeyword)
            if($null-eq$snap){
                continue
            }
            $desired=@([string]$spec.RegistryValue);
            $valid=@($snap.ValidRegistryValues)
            if($valid.Count-eq0-or@($desired|Where-Object{
                $valid-cnotcontains[string]$_
            }).Count-gt0){
                continue
            }
            $supported++
            $owned=@($Session.Entries|Where-Object{
                [string]$_.Type-eq'NetAdapterAdvancedProperty'-and[string]$_.InterfaceGuid-ieq[string]$identity.InterfaceGuid-and[string]$_.RegistryKeyword-ieq[string]$spec.RegistryKeyword
            })
            if($owned.Count-gt0){
                $ownedCount++;
                if(@($owned|Where-Object{
                    [string]$_.Status-eq'Applied'
                }).Count-eq$owned.Count){
                    $ownedApplied++
                }
            }

        }
        $state=if($supported-eq0){
            'Unsupported'
        }elseif($ownedCount-eq0){
            'Baseline'
        }elseif($ownedApplied-eq$ownedCount){
            'Applied'
        }elseif($ownedApplied-gt0){
            'Partial'
        }else{
            'Error'
        }
        $targetStates+=[pscustomobject]@{
            Target=[string]$identity.InterfaceDescription;
            Identity=[string]$identity.InterfaceGuid;
            State=$state
        }

    }
    $aggregate=Get-VSO7AggregateTargetStateVSO -Targets $targetStates
    $Session|Add-Member -NotePropertyName TargetStateSummary -NotePropertyValue $aggregate -Force
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Get-VSO7GlobalOffloadStateVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('ReceiveSideScaling','ReceiveSegmentCoalescing','TaskOffload')][string]$Property)
    $o=Get-NetOffloadGlobalSetting -ErrorAction Stop
    $p=$o.PSObject.Properties[$Property];
    if($null-eq$p){
        throw ('Global offload no expone {0}.'-f$Property)
    }
    return [string]$p.Value

}

function Add-VSO7NativeGlobalOffloadBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$Property,[Parameter(Mandatory=$true)][string]$IntendedValue)
    $current=Get-VSO7GlobalOffloadStateVSO -Property $Property
    $key=('netglobal|'+$Property).ToLowerInvariant()
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{

        Type='NetOffloadGlobal';
        Key=$key;
        Property=$Property;
        Value=$current;
        IntendedValue=$IntendedValue;

        AppliedValue=$null;
        ConfiguredValue=$null;
        EffectiveState='Unknown';
        RestoreEffectiveState=$null;
        Status='Pending'

    }
    $Session.Entries+=,$entry
    Save-VSO7NativeBackupSessionVSO -Session $Session
    return $entry

}

function Set-VSO7GlobalOffloadStateVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('ReceiveSideScaling','ReceiveSegmentCoalescing','TaskOffload')][string]$Property,[Parameter(Mandatory=$true)][ValidateSet('Enabled','Disabled')][string]$Value)
    $params=@{
        Confirm=$false;
        ErrorAction='Stop'
    };
    $params[$Property]=$Value
    NetTCPIP\Set-NetOffloadGlobalSetting @params|Out-Null

}

function Invoke-VSO7NativeGlobalOffloadOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'SetGlobalOffload'){
        throw ('Operacion NetOffloadGlobal desconocida: {0}'-f$Operation.Action)
    }
    $property=[string]$Operation.Property
    $desired=[string]$Operation.Value
    $entry=Add-VSO7NativeGlobalOffloadBackupVSO -Session $Session -Property $property -IntendedValue $desired
    $before=Get-VSO7GlobalOffloadStateVSO -Property $property
    if($before-cne[string]$entry.Value){
        throw ('Global offload {0} cambio entre baseline y mutacion.'-f$property)
    }
    if($before-cne$desired){
        Set-VSO7GlobalOffloadStateVSO -Property $property -Value $desired
    }
    $after=Get-VSO7GlobalOffloadStateVSO -Property $property
    if($after-cne$desired){
        throw ('Global offload {0} no coincide con el estado configurado solicitado.'-f$property)
    }
    $entry.AppliedValue=$after
    $entry.ConfiguredValue=$after
    if($property-ieq'TaskOffload'){

        # Microsoft documents that TaskOffload changes take effect only after an
        # adapter or system restart. Read-back verifies Configured, not Effective.
        $entry.EffectiveState='PendingRestart'

    }else{

        $entry.EffectiveState='ConfiguredVerified'

    }
    $entry.Status='Applied'
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Get-VSO7TcpSettingTargetsVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('AutoTuningLevelLocal','EcnCapability','Timestamps')][string]$Property)
    $targets=@()
    foreach($setting in @(Get-NetTCPSetting -ErrorAction Stop)){

        $name=[string]$setting.SettingName
        if([string]::IsNullOrWhiteSpace($name)-or$name-ieq'Automatic'){
            continue
        }
        $propertyValue=$setting.PSObject.Properties[$Property]
        if($null-eq$propertyValue-or$null-eq$propertyValue.Value-or[string]::IsNullOrWhiteSpace([string]$propertyValue.Value)){
            continue
        }
        $effective=$null
        if($Property-ieq'AutoTuningLevelLocal'){

            $effectiveProperty=$setting.PSObject.Properties['AutoTuningLevelEffective']
            if($null-ne$effectiveProperty-and$null-ne$effectiveProperty.Value){
                $effective=[string]$effectiveProperty.Value
            }

        }
        $targets+=[pscustomobject]@{
            SettingName=$name;
            Property=$Property;
            Value=[string]$propertyValue.Value;
            EffectiveValue=$effective
        }

    }
    return @($targets)

}

function Add-VSO7NativeTcpSettingBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Target,[Parameter(Mandatory=$true)][string]$IntendedValue)
    $key=('tcp|'+[string]$Target.SettingName+'|'+[string]$Target.Property).ToLowerInvariant()
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{

        Type='NetTcpSetting';
        Key=$key;
        SettingName=[string]$Target.SettingName;
        Property=[string]$Target.Property;

        Value=[string]$Target.Value;
        EffectiveValue=$Target.EffectiveValue;
        IntendedValue=$IntendedValue;
        AppliedValue=$null;

        AppliedEffectiveValue=$null;
        Status='Pending'

    }
    $Session.Entries+=,$entry
    Save-VSO7NativeBackupSessionVSO -Session $Session
    return $entry

}

function Get-VSO7TcpSettingValueVSO {

    param([Parameter(Mandatory=$true)][string]$SettingName,[Parameter(Mandatory=$true)][ValidateSet('AutoTuningLevelLocal','EcnCapability','Timestamps')][string]$Property)
    $setting=Get-NetTCPSetting -SettingName $SettingName -ErrorAction Stop
    $propertyValue=$setting.PSObject.Properties[$Property]
    if($null-eq$propertyValue){
        throw ('TCP setting no expone {0}.'-f$Property)
    }
    return [string]$propertyValue.Value

}

function Set-VSO7TcpSettingValueVSO {

    param([Parameter(Mandatory=$true)][string]$SettingName,[Parameter(Mandatory=$true)][ValidateSet('AutoTuningLevelLocal','EcnCapability','Timestamps')][string]$Property,[Parameter(Mandatory=$true)][string]$Value)
    switch($Property){

        'AutoTuningLevelLocal' {
            NetTCPIP\Set-NetTCPSetting -SettingName $SettingName -AutoTuningLevelLocal $Value -ErrorAction Stop|Out-Null
        }
        'EcnCapability' {
            NetTCPIP\Set-NetTCPSetting -SettingName $SettingName -EcnCapability $Value -ErrorAction Stop|Out-Null
        }
        'Timestamps' {

            # Windows PowerShell 5.1 Set-NetTCPSetting exposes only Disabled/Enabled here.
            # The CIM class has a wider domain (including Allowed), which is handled by the
            # dedicated NetTcpCimSetting primitive instead of passing an invalid enum value.
            if(@('Disabled','Enabled')-notcontains[string]$Value){
                throw 'Set-NetTCPSetting -Timestamps solo admite Disabled/Enabled en el runtime objetivo; usa NetTcpCimSetting para Allowed.'
            }
            NetTCPIP\Set-NetTCPSetting -SettingName $SettingName -Timestamps $Value -ErrorAction Stop|Out-Null

        }
        default {
            throw 'Propiedad TCP fuera de allowlist.'
        }

    }

}

function Invoke-VSO7NativeTcpSettingOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'SetTcpSetting'){
        throw ('Operacion NetTcpSetting desconocida: {0}'-f$Operation.Action)
    }
    $property=[string]$Operation.Property
    $desired=[string]$Operation.Value
    $allowedSourceValues=@()
    if($Operation.PSObject.Properties.Name-contains'AllowedSourceValues'){
        $allowedSourceValues=@($Operation.AllowedSourceValues|ForEach-Object{
            [string]$_
        })
    }
    $targets=@(Get-VSO7TcpSettingTargetsVSO -Property $property|Where-Object{

        ([string]$_.Value-cne$desired)-and($allowedSourceValues.Count-eq0-or$allowedSourceValues-icontains[string]$_.Value)

    })
    if($targets.Count-eq0){
        return
    }

    # Transaction group: every selected profile baseline is Pending before first mutation.
    $changes=@()
    foreach($target in $targets){

        $entry=Add-VSO7NativeTcpSettingBackupVSO -Session $Session -Target $target -IntendedValue $desired
        $changes+=[pscustomobject]@{
            Entry=$entry
        }

    }
    foreach($change in $changes){

        $entry=$change.Entry
        $before=Get-VSO7TcpSettingValueVSO -SettingName ([string]$entry.SettingName) -Property ([string]$entry.Property)
        if($before-cne[string]$entry.Value){
            throw ('TCP setting {0}/{1} cambio entre baseline y mutacion.'-f$entry.SettingName,$entry.Property)
        }

    }
    foreach($change in $changes){

        $entry=$change.Entry
        Set-VSO7TcpSettingValueVSO -SettingName ([string]$entry.SettingName) -Property ([string]$entry.Property) -Value $desired
        $after=Get-VSO7TcpSettingValueVSO -SettingName ([string]$entry.SettingName) -Property ([string]$entry.Property)
        if($after-cne$desired){
            throw ('TCP setting {0}/{1} no se verifico.'-f$entry.SettingName,$entry.Property)
        }
        $entry.AppliedValue=$after
        if([string]$entry.Property-ieq'AutoTuningLevelLocal'){

            $now=@(Get-VSO7TcpSettingTargetsVSO -Property 'AutoTuningLevelLocal'|Where-Object{
                [string]$_.SettingName-ceq[string]$entry.SettingName
            }|Select-Object -First 1)
            if($now.Count-eq1){
                $entry.AppliedEffectiveValue=$now[0].EffectiveValue
            }

        }
        $entry.Status='Applied'
        Save-VSO7NativeBackupSessionVSO -Session $Session

    }

}

function ConvertTo-VSO7TcpTimestampCimValueVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('Disabled','Enabled','Allowed')][string]$Value)
    switch($Value){
        'Disabled'{
            return [byte]0
        };
        'Enabled'{
            return [byte]1
        };
        'Allowed'{
            return [byte]2
        };
        default{
            throw 'Estado TCP timestamp fuera de dominio.'
        }
    }

}

function ConvertFrom-VSO7TcpTimestampCimValueVSO {

    param([Parameter(Mandatory=$true)][int]$Value)
    switch($Value){
        0{
            return 'Disabled'
        };
        1{
            return 'Enabled'
        };
        2{
            return 'Allowed'
        };
        default{
            throw ('MSFT_NetTCPSetting.Timestamps devolvio valor no soportado: {0}'-f$Value)
        }
    }

}

function Get-VSO7TcpTimestampCimInstancesVSO {

    $items=@(CimCmdlets\Get-CimInstance -Namespace 'root/StandardCimv2' -ClassName 'MSFT_NetTCPSetting' -ErrorAction Stop)
    $result=@()
    foreach($item in $items){

        $name=[string]$item.SettingName
        if([string]::IsNullOrWhiteSpace($name)-or$name-ieq'Automatic'){
            continue
        }
        $raw=[int]$item.Timestamps
        $value=ConvertFrom-VSO7TcpTimestampCimValueVSO -Value $raw
        $result+=[pscustomobject]@{
            SettingName=$name;
            Property='Timestamps';
            Value=$value;
            RawValue=$raw;
            Instance=$item
        }

    }
    return @($result)

}

function Resolve-VSO7TcpTimestampCimInstanceVSO {

    param([Parameter(Mandatory=$true)][string]$SettingName)
    $matches=@(Get-VSO7TcpTimestampCimInstancesVSO|Where-Object{
        [string]$_.SettingName-ceq$SettingName
    })
    if($matches.Count-ne1){
        throw ('Perfil TCP CIM no resolvio de forma unica: {0} (matches={1})'-f$SettingName,$matches.Count)
    }
    return $matches[0]

}

function Add-VSO7NativeTcpTimestampCimBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Target,[Parameter(Mandatory=$true)][ValidateSet('Disabled','Enabled','Allowed')][string]$IntendedValue)
    $key=('tcpcim|'+[string]$Target.SettingName+'|timestamps').ToLowerInvariant()
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{

        Type='NetTcpCimSetting';
        Key=$key;
        SettingName=[string]$Target.SettingName;
        Property='Timestamps';

        Value=[string]$Target.Value;
        RawValue=[int]$Target.RawValue;
        IntendedValue=$IntendedValue;
        IntendedRawValue=[int](ConvertTo-VSO7TcpTimestampCimValueVSO -Value $IntendedValue);

        AppliedValue=$null;
        AppliedRawValue=$null;
        EffectiveState='Unknown';
        RestoreEffectiveState=$null;
        Status='Pending'

    }
    $Session.Entries+=,$entry;
    Save-VSO7NativeBackupSessionVSO -Session $Session;
    return $entry

}

function Set-VSO7TcpTimestampCimValueVSO {

    param([Parameter(Mandatory=$true)][string]$SettingName,[Parameter(Mandatory=$true)][ValidateSet('Disabled','Enabled','Allowed')][string]$Value)
    $target=Resolve-VSO7TcpTimestampCimInstanceVSO -SettingName $SettingName
    $raw=[byte](ConvertTo-VSO7TcpTimestampCimValueVSO -Value $Value)
    CimCmdlets\Set-CimInstance -InputObject $target.Instance -Property @{
        Timestamps=$raw
    } -Confirm:$false -ErrorAction Stop|Out-Null

}

function Invoke-VSO7NativeTcpTimestampCimOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'SetTcpTimestampCim'){
        throw ('Operacion NetTcpCimSetting desconocida: {0}'-f$Operation.Action)
    }
    $desired=[string]$Operation.Value
    [void](ConvertTo-VSO7TcpTimestampCimValueVSO -Value $desired)
    $allowed=@();
    if($Operation.PSObject.Properties.Name-contains'AllowedSourceValues'){
        $allowed=@($Operation.AllowedSourceValues|ForEach-Object{
            [string]$_
        })
    }
    foreach($v in $allowed){
        [void](ConvertTo-VSO7TcpTimestampCimValueVSO -Value $v)
    }
    $targets=@(Get-VSO7TcpTimestampCimInstancesVSO|Where-Object{
        [string]$_.Value-cne$desired-and($allowed.Count-eq0-or$allowed-icontains[string]$_.Value)
    })
    if($targets.Count-eq0){
        return
    }
    # Transaction group: journal every TCP profile before the first mutation.
    $changes=@();
    foreach($target in $targets){
        $changes+=[pscustomobject]@{
            Entry=(Add-VSO7NativeTcpTimestampCimBackupVSO -Session $Session -Target $target -IntendedValue $desired)
        }
    }
    foreach($change in $changes){
        $entry=$change.Entry;
        $cur=Resolve-VSO7TcpTimestampCimInstanceVSO -SettingName ([string]$entry.SettingName);
        if([string]$cur.Value-cne[string]$entry.Value-or[int]$cur.RawValue-ne[int]$entry.RawValue){
            throw ('TCP timestamp CIM {0} cambio entre baseline y mutacion.'-f$entry.SettingName)
        }
    }
    foreach($change in $changes){

        $entry=$change.Entry;
        Set-VSO7TcpTimestampCimValueVSO -SettingName ([string]$entry.SettingName) -Value $desired
        $after=Resolve-VSO7TcpTimestampCimInstanceVSO -SettingName ([string]$entry.SettingName)
        if([string]$after.Value-cne$desired-or[int]$after.RawValue-ne[int]$entry.IntendedRawValue){
            throw ('TCP timestamp CIM {0} no se verifico.'-f$entry.SettingName)
        }
        $entry.AppliedValue=[string]$after.Value;
        $entry.AppliedRawValue=[int]$after.RawValue;
        $entry.EffectiveState='ConfiguredVerifiedForNewConnections';
        $entry.Status='Applied';
        Save-VSO7NativeBackupSessionVSO -Session $Session

    }

}

function Restore-VSO7NativeTcpTimestampCimEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Resolve-VSO7TcpTimestampCimInstanceVSO -SettingName ([string]$Entry.SettingName)
    $matchesBaseline=([string]$cur.Value-ceq[string]$Entry.Value-and[int]$cur.RawValue-eq[int]$Entry.RawValue)
    $matchesIntended=([string]$cur.Value-ceq[string]$Entry.IntendedValue-and[int]$cur.RawValue-eq[int]$Entry.IntendedRawValue)
    $matchesApplied=($null-ne$Entry.AppliedValue-and[string]$cur.Value-ceq[string]$Entry.AppliedValue-and[int]$cur.RawValue-eq[int]$Entry.AppliedRawValue)
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline $matchesBaseline -CurrentMatchesIntended $matchesIntended -CurrentMatchesApplied $matchesApplied -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    };
    if($decision-ne'Owned'){
        throw 'TCP timestamp CIM presenta drift externo; VSO7 no lo sobrescribe.'
    }
    Set-VSO7TcpTimestampCimValueVSO -SettingName ([string]$Entry.SettingName) -Value ([string]$Entry.Value)
    $after=Resolve-VSO7TcpTimestampCimInstanceVSO -SettingName ([string]$Entry.SettingName)
    if([string]$after.Value-cne[string]$Entry.Value-or[int]$after.RawValue-ne[int]$Entry.RawValue){
        throw 'Rollback TCP timestamp CIM no coincidio con baseline.'
    }
    $Entry.RestoreEffectiveState='ConfiguredVerifiedForNewConnections';
    return $true

}

function ConvertFrom-VSO7FsutilTrimOutputVSO {

    param([Parameter(Mandatory=$true)]$Lines)
    $text=(@($Lines)|ForEach-Object{
        [string]$_
    })-join"`n"
    $ntfs=$null;
    $refs=$null;
    $refsSet=$false
    $m=[regex]::Match($text,'(?im)^\s*NTFS\s+DisableDeleteNotify\s*=\s*([01])\b')
    if($m.Success){
        $ntfs=[int]$m.Groups[1].Value
    }
    $m=[regex]::Match($text,'(?im)^\s*ReFS\s+DisableDeleteNotify\s*=\s*([01])\b')
    if($m.Success){
        $refs=[int]$m.Groups[1].Value;
        $refsSet=$true
    }
    elseif($text-match'(?im)^\s*ReFS\s+DisableDeleteNotify\s+is\s+not\s+currently\s+set'){
        $refsSet=$false
    }
    return [pscustomobject]@{
        NtfsDisabled=$ntfs;
        ReFsDisabled=$refs;
        ReFsExplicitlySet=$refsSet
    }

}

function Get-VSO7ReFsVolumeCountVSO {

    try{
        return [int]@(
        Storage\Get-Volume -ErrorAction Stop|Where-Object{
            [string]$_.FileSystem-ieq'ReFS'
        }
    ).Count
    }catch{
        throw ('No se pudo determinar si existen volumenes ReFS: {0}'-f$_.Exception.Message)
    }

}

function Get-VSO7FsutilTrimStateVSO {

    $lines=@(Invoke-NativeCommandVSO -FilePath 'fsutil.exe' -Arguments @('behavior','query','DisableDeleteNotify') -CaptureOutput)
    $state=ConvertFrom-VSO7FsutilTrimOutputVSO -Lines $lines
    if($null-eq$state.NtfsDisabled){
        throw 'fsutil no devolvio un estado NTFS DisableDeleteNotify reconocible.'
    }
    $state|Add-Member -NotePropertyName ReFsVolumeCount -NotePropertyValue (Get-VSO7ReFsVolumeCountVSO) -Force
    return $state

}

function Set-VSO7NtfsTrimDisabledStateVSO {

    param([Parameter(Mandatory=$true)][ValidateSet(0,1)][int]$Disabled)
    # On current Windows this is the documented global NTFS/ReFS-v1 switch. The
    # feature only calls it when no ReFS volume exists, preserving ownership scope.
    Invoke-NativeCommandVSO -FilePath 'fsutil.exe' -Arguments @('behavior','set','disabledeletenotify',[string]$Disabled)|Out-Null

}

function Add-VSO7NativeFsutilTrimBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][int]$IntendedDisabled)
    $snap=Get-VSO7FsutilTrimStateVSO
    $key='fsutil|ntfs|disabledeletenotify'
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{

        Type='FsutilNtfsTrim';
        Key=$key;
        Disabled=[int]$snap.NtfsDisabled;
        ReFsVolumeCount=[int]$snap.ReFsVolumeCount;

        IntendedDisabled=$IntendedDisabled;
        AppliedDisabled=$null;
        Status='Pending'

    }
    $Session.Entries+=,$entry
    Save-VSO7NativeBackupSessionVSO -Session $Session
    return $entry

}

function Invoke-VSO7NativeFsutilTrimOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'EnableNtfsTrim'){
        throw ('Operacion FsutilTrim desconocida: {0}'-f$Operation.Action)
    }
    $entry=Add-VSO7NativeFsutilTrimBackupVSO -Session $Session -IntendedDisabled 0
    $before=Get-VSO7FsutilTrimStateVSO
    if([int]$before.ReFsVolumeCount-ne0){
        throw 'Aparecio un volumen ReFS; VSO7 no usa el switch global de TRIM en este estado.'
    }
    if([int]$before.NtfsDisabled-ne[int]$entry.Disabled){
        throw 'TRIM NTFS cambio entre baseline y mutacion.'
    }
    if([int]$before.NtfsDisabled-ne0){
        Set-VSO7NtfsTrimDisabledStateVSO -Disabled 0
    }
    $after=Get-VSO7FsutilTrimStateVSO
    if([int]$after.ReFsVolumeCount-ne0-or[int]$after.NtfsDisabled-ne0){
        throw 'No se verifico TRIM NTFS habilitado sin ReFS.'
    }
    $entry.AppliedDisabled=[int]$after.NtfsDisabled
    $entry.Status='Applied'
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Get-VSO7ScheduledTaskXmlFingerprintsR76VSO {
    param([Parameter(Mandatory=$true)][string]$Xml)
    if([string]::IsNullOrWhiteSpace($Xml)){throw 'ScheduledTask XML vacio.'}
    $doc=New-Object Xml.XmlDocument
    $doc.PreserveWhitespace=$false
    try{$doc.LoadXml($Xml)}catch{throw ('ScheduledTask XML invalido: '+$_.Exception.Message)}
    $enabled=@($doc.SelectNodes("/*[local-name()='Task']/*[local-name()='Settings']/*[local-name()='Enabled']"))
    if($enabled.Count-ne1){throw ('ScheduledTask XML debe contener exactamente Task/Settings/Enabled; encontrados: '+$enabled.Count)}
    $value=[string]$enabled[0].InnerText
    if($value-inotmatch'^(true|false)$'){throw ('Task/Settings/Enabled contiene un valor invalido: '+$value)}
    # XmlDocument normaliza whitespace de presentacion. Solo el Enabled global de Settings se
    # sustituye en el fingerprint core; Enabled de triggers/acciones sigue protegido contra drift.
    $fullCanonical=[string]$doc.OuterXml
    $enabled[0].InnerText='__VSO7_TASK_ENABLED__'
    $coreCanonical=[string]$doc.OuterXml
    $sha=[Security.Cryptography.SHA256]::Create()
    try{
        $full=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($fullCanonical))).Replace('-',''))
        $coreHash=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($coreCanonical))).Replace('-',''))
        return [pscustomobject]@{DefinitionSha256=$full;DefinitionCoreSha256=$coreHash}
    }finally{$sha.Dispose()}
}

function Get-VSO7ScheduledTaskDefinitionFingerprintsVSO {
    param([Parameter(Mandatory=$true)][string]$TaskPath,[Parameter(Mandatory=$true)][string]$TaskName)
    $xml=[string](ScheduledTasks\Export-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop)
    if([string]::IsNullOrWhiteSpace($xml)){throw ('Export-ScheduledTask no devolvio una definicion para {0}{1}.'-f$TaskPath,$TaskName)}
    return Get-VSO7ScheduledTaskXmlFingerprintsR76VSO -Xml $xml
}

function Get-VSO7ScheduledTaskDefinitionSha256VSO {
    param([Parameter(Mandatory=$true)][string]$TaskPath,[Parameter(Mandatory=$true)][string]$TaskName)
    return [string](Get-VSO7ScheduledTaskDefinitionFingerprintsVSO -TaskPath $TaskPath -TaskName $TaskName).DefinitionSha256
}

function Get-VSO7ScheduledTaskSnapshotVSO {
    param([Parameter(Mandatory=$true)][string]$TaskPath,[Parameter(Mandatory=$true)][string]$TaskName)
    $items=@(ScheduledTasks\Get-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop)
    if($items.Count-ne1){throw ('No se encontro exactamente una tarea {0}{1}.'-f$TaskPath,$TaskName)}
    $task=$items[0]
    $fp=Get-VSO7ScheduledTaskDefinitionFingerprintsVSO -TaskPath $TaskPath -TaskName $TaskName
    $verify=@(ScheduledTasks\Get-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop)
    if($verify.Count-ne1-or(([string]$verify[0].State-ine'Disabled')-ne([string]$task.State-ine'Disabled'))){throw 'La tarea programada cambio durante la captura de baseline.'}
    $fpVerify=Get-VSO7ScheduledTaskDefinitionFingerprintsVSO -TaskPath $TaskPath -TaskName $TaskName
    if([string]$fpVerify.DefinitionSha256-cne[string]$fp.DefinitionSha256-or[string]$fpVerify.DefinitionCoreSha256-cne[string]$fp.DefinitionCoreSha256){throw 'La definicion de la tarea programada cambio durante la captura de baseline.'}
    return [pscustomobject]@{TaskPath=[string]$task.TaskPath;TaskName=[string]$task.TaskName;State=[string]$task.State;Enabled=([string]$task.State-ine'Disabled');DefinitionSha256=[string]$fp.DefinitionSha256;DefinitionCoreSha256=[string]$fp.DefinitionCoreSha256}
}

function Add-VSO7NativeScheduledTaskBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$TaskPath,[Parameter(Mandatory=$true)][string]$TaskName,[Parameter(Mandatory=$true)][bool]$IntendedEnabled)
    $snap=Get-VSO7ScheduledTaskSnapshotVSO -TaskPath $TaskPath -TaskName $TaskName
    $key=('task|'+$TaskPath+'|'+$TaskName).ToLowerInvariant()
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{
        Type='ScheduledTaskState';
        Key=$key;
        TaskPath=$snap.TaskPath;
        TaskName=$snap.TaskName;
        Enabled=[bool]$snap.Enabled;
        State=$snap.State;
        BaselineDefinitionSha256=[string]$snap.DefinitionSha256;
        BaselineDefinitionCoreSha256=[string]$snap.DefinitionCoreSha256;
        IntendedEnabled=$IntendedEnabled;
        AppliedEnabled=$null;
        AppliedDefinitionSha256=$null;
        AppliedDefinitionCoreSha256=$null;
        Status='Pending'
    }
    $Session.Entries+=,$entry
    Save-VSO7NativeBackupSessionVSO -Session $Session
    return $entry

}

function Set-VSO7ScheduledTaskEnabledVSO {

    param([Parameter(Mandatory=$true)][string]$TaskPath,[Parameter(Mandatory=$true)][string]$TaskName,[Parameter(Mandatory=$true)][bool]$Enabled)
    if($Enabled){
        ScheduledTasks\Enable-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop|Out-Null
    }
    else{
        ScheduledTasks\Disable-ScheduledTask -TaskPath $TaskPath -TaskName $TaskName -ErrorAction Stop|Out-Null
    }

}

function Invoke-VSO7NativeScheduledTaskOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    $action=[string]$Operation.Action
    if($action-notin@('EnableTask','DisableTask')){
        throw ('Operacion ScheduledTaskState desconocida: {0}'-f$action)
    }
    $desired=($action-ieq'EnableTask')
    $path=[string]$Operation.TaskPath;
    $name=[string]$Operation.TaskName
    $entry=Add-VSO7NativeScheduledTaskBackupVSO -Session $Session -TaskPath $path -TaskName $name -IntendedEnabled $desired
    $before=Get-VSO7ScheduledTaskSnapshotVSO -TaskPath $path -TaskName $name
    if([bool]$before.Enabled-ne[bool]$entry.Enabled-or[string]$before.DefinitionSha256-cne[string]$entry.BaselineDefinitionSha256-or[string]$before.DefinitionCoreSha256-cne[string]$entry.BaselineDefinitionCoreSha256){
        throw 'La tarea programada cambio entre baseline y mutacion.'
    }
    if([bool]$before.Enabled-ne$desired){
        Set-VSO7ScheduledTaskEnabledVSO -TaskPath $path -TaskName $name -Enabled $desired
    }
    $after=Get-VSO7ScheduledTaskSnapshotVSO -TaskPath $path -TaskName $name
    if([bool]$after.Enabled-ne$desired){
        throw 'No se verifico el estado de la tarea programada.'
    }
    $entry.AppliedEnabled=[bool]$after.Enabled;
    $entry.AppliedDefinitionSha256=[string]$after.DefinitionSha256;
    $entry.AppliedDefinitionCoreSha256=[string]$after.DefinitionCoreSha256;
    $entry.Status='Applied'
    Save-VSO7NativeBackupSessionVSO -Session $Session

}

function Get-VSO7NetAdapterPowerSnapshotVSO {

    param([Parameter(Mandatory=$true)]$Identity,[Parameter(Mandatory=$true)][ValidateSet('SelectiveSuspend','WakeOnMagicPacket','WakeOnPattern')][string]$Property)
    $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $Identity
    $pm=NetAdapter\Get-NetAdapterPowerManagement -Name ([string]$adapter.Name) -ErrorAction Stop
    $prop=$pm.PSObject.Properties[$Property]
    if($null-eq$prop){
        throw ('NetAdapterPowerManagement no expone {0}.'-f$Property)
    }
    $value=[string]$prop.Value
    return [pscustomobject]@{

        Name=[string]$adapter.Name;
        InterfaceGuid=[string]$adapter.InterfaceGuid;
        PnPDeviceID=[string]$adapter.PnPDeviceID;

        InterfaceDescription=[string]$adapter.InterfaceDescription;
        Property=$Property;
        Value=$value;
        Supported=($value-ine'Unsupported')

    }

}

function Get-VSO7NetAdapterPowerTargetsVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('SelectiveSuspend','WakeOnMagicPacket','WakeOnPattern')][string]$Property,[switch]$OnlyUp)
    $identities=@(Get-VSO7PhysicalAdapterTargetsVSO -OnlyUp:$OnlyUp)
    if($identities.Count-eq0){
        return @()
    }
    # El cmdlet bulk devuelve solo adaptadores power-management-capable. Un fallo del provider no equivale a "unsupported".
    $powerRows=@(NetAdapter\Get-NetAdapterPowerManagement -Name '*' -IncludeHidden -ErrorAction Stop)
    $targets=@()
    foreach($identity in $identities){

        $matches=@($powerRows|Where-Object{

            (($PSItem.PSObject.Properties.Name-contains'Name')-and([string]$PSItem.Name-ceq[string]$identity.Name))-or
            (($PSItem.PSObject.Properties.Name-contains'InterfaceDescription')-and([string]$PSItem.InterfaceDescription-ceq[string]$identity.InterfaceDescription))

        })
        if($matches.Count-eq0){
            continue
        }
        if($matches.Count-ne1){
            throw ('NetAdapterPowerManagement devolvio una identidad ambigua para la NIC {0}.'-f$identity.Name)
        }
        $prop=$matches[0].PSObject.Properties[$Property]
        if($null-eq$prop){
            throw ('NetAdapterPowerManagement no expone {0} para {1}.'-f$Property,$identity.Name)
        }
        $value=[string]$prop.Value
        if($value-ieq'Unsupported'){
            continue
        }
        $targets+=[pscustomobject]@{

            Name=[string]$identity.Name;
            InterfaceGuid=[string]$identity.InterfaceGuid;
            PnPDeviceID=[string]$identity.PnPDeviceID;

            InterfaceDescription=[string]$identity.InterfaceDescription;
            Property=$Property;
            Value=$value;
            Supported=$true

        }

    }
    return @($targets)

}

function Add-VSO7NativeNetAdapterPowerBackupVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Snapshot,[Parameter(Mandatory=$true)][string]$IntendedValue)
    $key=('nicpower|'+[string]$Snapshot.InterfaceGuid+'|'+[string]$Snapshot.Property).ToLowerInvariant()
    $existing=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($existing.Count){
        return $existing[0]
    }
    $entry=[pscustomobject]@{

        Type='NetAdapterPower';
        Key=$key;
        Name=[string]$Snapshot.Name;
        InterfaceGuid=[string]$Snapshot.InterfaceGuid;

        PnPDeviceID=[string]$Snapshot.PnPDeviceID;
        InterfaceDescription=[string]$Snapshot.InterfaceDescription;
        Property=[string]$Snapshot.Property;

        Value=[string]$Snapshot.Value;
        IntendedValue=$IntendedValue;
        AppliedValue=$null;
        ConfiguredValue=$null;
        EffectiveState='Unknown';
        RestoreEffectiveState=$null;
        Status='Pending'

    }
    $Session.Entries+=,$entry
    Save-VSO7NativeBackupSessionVSO -Session $Session
    return $entry

}

function Set-VSO7NetAdapterPowerValueVSO {

    param([Parameter(Mandatory=$true)]$Identity,[Parameter(Mandatory=$true)][ValidateSet('SelectiveSuspend','WakeOnMagicPacket','WakeOnPattern')][string]$Property,[Parameter(Mandatory=$true)][ValidateSet('Enabled','Disabled')][string]$Value)
    $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $Identity
    $params=@{
        Name=[string]$adapter.Name;
        NoRestart=$true;
        Confirm=$false;
        ErrorAction='Stop'
    }
    $params[$Property]=$Value
    NetAdapter\Set-NetAdapterPowerManagement @params|Out-Null

}

function Invoke-VSO7NativeNetAdapterPowerOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)]$Operation)
    if([string]$Operation.Action-ine'SetPowerProperty'){
        throw ('Operacion NetAdapterPower desconocida: {0}'-f$Operation.Action)
    }
    $property=[string]$Operation.Property;
    $desired=[string]$Operation.Value;
    $onlyUp=$false
    if($Operation.PSObject.Properties.Name-contains'OnlyUp'){
        $onlyUp=[bool]$Operation.OnlyUp
    }
    $targets=@(Get-VSO7NetAdapterPowerTargetsVSO -Property $property -OnlyUp:$onlyUp|Where-Object{
        [string]$_.Value-cne$desired
    })
    if($targets.Count-eq0){
        return
    }
    $changes=@()
    foreach($target in $targets){
        $entry=Add-VSO7NativeNetAdapterPowerBackupVSO -Session $Session -Snapshot $target -IntendedValue $desired;
        $changes+=[pscustomobject]@{
            Entry=$entry
        }
    }
    foreach($change in $changes){

        $entry=$change.Entry;
        $before=Get-VSO7NetAdapterPowerSnapshotVSO -Identity $entry -Property ([string]$entry.Property)
        if(-not[bool]$before.Supported-or[string]$before.Value-cne[string]$entry.Value){
            throw ('NIC power cambio entre baseline y mutacion: {0}/{1}'-f$entry.InterfaceDescription,$entry.Property)
        }

    }
    foreach($change in $changes){

        $entry=$change.Entry
        Set-VSO7NetAdapterPowerValueVSO -Identity $entry -Property ([string]$entry.Property) -Value $desired
        $after=Get-VSO7NetAdapterPowerSnapshotVSO -Identity $entry -Property ([string]$entry.Property)
        if(-not[bool]$after.Supported-or[string]$after.Value-cne$desired){
            throw ('No se verifico NIC power configurado: {0}/{1}'-f$entry.InterfaceDescription,$entry.Property)
        }
        $entry.AppliedValue=[string]$after.Value;
        $entry.ConfiguredValue=[string]$after.Value;
        $entry.EffectiveState='PendingRestart';
        $entry.Status='Applied'
        Save-VSO7NativeBackupSessionVSO -Session $Session

    }

}

function Get-VSO7GpuVendorNameVSO {

    param([AllowNull()][string]$AdapterCompatibility,[AllowNull()][string]$Name,[AllowNull()][string]$PnpDeviceId)
    $identity=([string]$AdapterCompatibility+' '+[string]$Name+' '+[string]$PnpDeviceId)
    if($identity-match'(?i)VEN_10DE|NVIDIA'){
        return 'NVIDIA'
    }
    if($identity-match'(?i)VEN_1002|AMD|Advanced Micro Devices|ATI'){
        return 'AMD'
    }
    if($identity-match'(?i)VEN_8086|Intel'){
        return 'Intel'
    }
    return 'Unknown'

}

function Get-VSO7ApplicabilityContextVSO {

    if($null-ne$script:VSO7ApplicabilityContext){
        return $script:VSO7ApplicabilityContext
    }
    $build=$null;
    $edition=$null;
    $cpuVendors=@();
    $gpuVendors=@();
    $gpuAdapters=@();
    $deviceType='Unknown';
    $physicalAdapterCount=0;
    $storageMediaTypes=@()
    try{

        $cv=Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
        $b=[string]$cv.CurrentBuildNumber;
        if([string]::IsNullOrWhiteSpace($b)){
            $b=[string]$cv.CurrentBuild
        }
        $bi=0;
        if([int]::TryParse(($b-split'\.')[0],[ref]$bi)){
            $build=$bi
        }
        $edition=[string]$cv.EditionID

    }catch{}
    try{

        foreach($cpu in @(CimCmdlets\Get-CimInstance Win32_Processor -ErrorAction Stop)){

            $m=[string]$cpu.Manufacturer
            if($m-match'(?i)Intel'){
                $cpuVendors+=@('Intel')
            }elseif($m-match'(?i)AMD'){
                $cpuVendors+=@('AMD')
            }elseif(-not[string]::IsNullOrWhiteSpace($m)){
                $cpuVendors+=@($m)
            }

        }

    }catch{}
    try{

        foreach($gpu in @(CimCmdlets\Get-CimInstance Win32_VideoController -ErrorAction Stop)){

            $vendor=Get-VSO7GpuVendorNameVSO -AdapterCompatibility ([string]$gpu.AdapterCompatibility) -Name ([string]$gpu.Name) -PnpDeviceId ([string]$gpu.PNPDeviceID)
            if($vendor-ne'Unknown'){
                $gpuVendors+=@($vendor)
            }
            $pci=Get-VSO7PciIdentityPartsVSO -PnpDeviceId ([string]$gpu.PNPDeviceID)
            $gpuAdapters+=,[pscustomobject]@{
                Name=[string]$gpu.Name;
                Vendor=$vendor;
                PNPDeviceID=[string]$gpu.PNPDeviceID;
                VendorId=$pci.VendorId;
                DeviceId=$pci.DeviceId;
                SubsystemId=$pci.SubsystemId;
                DriverVersion=[string]$gpu.DriverVersion;
                VideoProcessor=[string]$gpu.VideoProcessor;
                AdapterCompatibility=[string]$gpu.AdapterCompatibility
            }

        }

    }catch{}
    try{

        $cs=CimCmdlets\Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
        $battery=@(CimCmdlets\Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue)
        if($battery.Count-gt0-or[int]$cs.PCSystemType-eq2){
            $deviceType='Laptop'
        }elseif($null-ne$cs){
            $deviceType='Desktop'
        }

    }catch{}
    try{
        $physicalAdapterCount=@(Get-NetAdapter -Physical -ErrorAction Stop).Count
    }catch{}
    try{
        $storageMediaTypes=@(Storage\Get-PhysicalDisk -ErrorAction Stop|ForEach-Object{
            [string]$_.MediaType
        }|Where-Object{
            -not[string]::IsNullOrWhiteSpace($_)
        }|Sort-Object -Unique)
    }catch{}
    $gpuTopology=Get-VSO7GpuTopologyVSO -Adapters @($gpuAdapters)
    $script:VSO7ApplicabilityContext=[pscustomobject]@{

        WindowsBuild=$build;
        WindowsEdition=$edition;
        CpuVendors=@($cpuVendors|Sort-Object -Unique);
        GpuVendors=@($gpuVendors|Sort-Object -Unique);
        GpuAdapters=@($gpuAdapters);
        GpuCount=@($gpuAdapters).Count;
        MultiGpu=(@($gpuAdapters).Count-gt1);
        GpuTopology=$gpuTopology;

        DeviceType=$deviceType;
        PhysicalAdapterCount=[int]$physicalAdapterCount;
        StorageMediaTypes=@($storageMediaTypes)

    }
    return $script:VSO7ApplicabilityContext

}

function Test-VSO7ExternalConflictActiveVSO {

    param([Parameter(Mandatory=$true)][string]$ConflictId)
    switch([string]$ConflictId){

        'power.usbSuspend' {

            Load-ExtremeState
            return (@($script:ExtremeState.AppliedTweaks|Where-Object{
                [string]$_.Id-ieq'power.usbSuspend'
            }).Count-gt0-or@($script:ExtremeState.PendingTweaks|Where-Object{
                [string]$_.Id-ieq'power.usbSuspend'
            }).Count-gt0)

        }
        'power.pcieAspm' {

            Load-ExtremeState
            return (@($script:ExtremeState.AppliedTweaks|Where-Object{
                [string]$_.Id-ieq'power.pcieAspm'
            }).Count-gt0-or@($script:ExtremeState.PendingTweaks|Where-Object{
                [string]$_.Id-ieq'power.pcieAspm'
            }).Count-gt0)

        }
        'gaming.gamemode' {

            Load-State
            if(Test-RegistryValueOwnedByNormalVSO -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AutoGameModeEnabled'){
                return $true
            }
            Load-ExtremeState
            return (@($script:ExtremeState.AppliedTweaks|Where-Object{
                [string]$_.Id-ieq'gaming.gamemode'
            }).Count-gt0-or@($script:ExtremeState.PendingTweaks|Where-Object{
                [string]$_.Id-ieq'gaming.gamemode'
            }).Count-gt0)

        }
        default {
            throw ('ExternalConflict VSO7 desconocido/no implementado: {0}'-f$ConflictId)
        }

    }

}

function Complete-VSO7ApplicabilityResultVSO {

    param([Parameter(Mandatory=$true)]$Result)
    $applicable=[bool]$Result.Applicable
    $already=[bool]$Result.AlreadySatisfied
    $reasonEs=[string]$Result.ReasonEs
    $reasonEn=[string]$Result.ReasonEn
    $status='AVAILABLE'
    if($already){
        $status='ALREADY_OPTIMAL'
    }elseif(-not$applicable){
        $reason=($reasonEs+' '+$reasonEn)
        if($reason-match'(?i)requiere administrador|requires administrator'){
            $status='ADMIN'
        }elseif($reason-match'(?i)no se pudo verificar|could not be verified|no verificable|provider|ambig|unknown|desconocid'){
            $status='UNKNOWN'
        }elseif($reason-match'(?i)no existe|no disponible|unavailable|no expone|missing|falta cmdlet|falta modulo|unsupported'){
            $status='UNSUPPORTED'
        }else{
            $status='NOT_APPLICABLE'
        }
    }
    if($Result-is[Collections.IDictionary]){
        $Result['Status']=$status
        return [pscustomobject]$Result
    }
    try{ $Result.Status=$status }catch{}
    return $Result

}

function Get-VSO7FeatureApplicabilityVSO {

    param([Parameter(Mandatory=$true)]$Feature)
    $result=[ordered]@{
        Applicable=$true;
        AlreadySatisfied=$false;
        Status='AVAILABLE';
        ReasonEs='Aplicable';
        ReasonEn='Applicable';
        Details=@()
    }
    $prop=@($Feature.PSObject.Properties.Name)
    if($prop-notcontains'Applicability'-or$null-eq$Feature.Applicability){
        return (Complete-VSO7ApplicabilityResultVSO -Result $result)
    }
    $a=$Feature.Applicability
    try{

        $context=Get-VSO7ApplicabilityContextVSO
        if(($a.PSObject.Properties.Name-contains'WindowsBuildMin')-and($null-eq$context.WindowsBuild-or[int]$context.WindowsBuild-lt[int]$a.WindowsBuildMin)){
            $result.Applicable=$false;
            $result.ReasonEs='Build de Windows demasiado antigua o no verificable';
            $result.ReasonEn='Windows build is too old or could not be verified';
            return (Complete-VSO7ApplicabilityResultVSO -Result $result)
        }
        if(($a.PSObject.Properties.Name-contains'WindowsBuildMax')-and($null-eq$context.WindowsBuild-or[int]$context.WindowsBuild-gt[int]$a.WindowsBuildMax)){
            $result.Applicable=$false;
            $result.ReasonEs='Build de Windows fuera del rango revisado';
            $result.ReasonEn='Windows build is outside the reviewed range';
            return (Complete-VSO7ApplicabilityResultVSO -Result $result)
        }
        if($a.PSObject.Properties.Name-contains'WindowsEdition'){
            $allowed=@($a.WindowsEdition|ForEach-Object{
                [string]$_
            });
            if([string]::IsNullOrWhiteSpace([string]$context.WindowsEdition)-or$allowed-inotcontains[string]$context.WindowsEdition){
                $result.Applicable=$false;
                $result.ReasonEs='Edicion de Windows no aplicable';
                $result.ReasonEn='Windows edition is not applicable';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
        }
        if($a.PSObject.Properties.Name-contains'CpuVendor'){
            $allowed=@($a.CpuVendor|ForEach-Object{
                [string]$_
            });
            if(@($context.CpuVendors|Where-Object{
                $allowed-icontains[string]$_
            }).Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Vendor CPU no aplicable o no verificable';
                $result.ReasonEn='CPU vendor is not applicable or could not be verified';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
        }
        if($a.PSObject.Properties.Name-contains'GpuVendor'){
            $allowed=@($a.GpuVendor|ForEach-Object{
                [string]$_
            });
            if(@($context.GpuVendors|Where-Object{
                $allowed-icontains[string]$_
            }).Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Vendor GPU no aplicable o no verificable';
                $result.ReasonEn='GPU vendor is not applicable or could not be verified';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
        }
        if($a.PSObject.Properties.Name-contains'DeviceType'){
            $allowed=@($a.DeviceType|ForEach-Object{
                [string]$_
            });
            if([string]$context.DeviceType-ieq'Unknown'){
                $result.Applicable=$false;
                $result.ReasonEs='No se pudo verificar si el equipo es desktop o laptop';
                $result.ReasonEn='Could not verify whether the device is a desktop or laptop';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            if($allowed-inotcontains[string]$context.DeviceType){
                $result.Applicable=$false;
                $result.ReasonEs=('Tipo de equipo no aplicable: detectado {0}'-f[string]$context.DeviceType);
                $result.ReasonEn=('Device type is not applicable: detected {0}'-f[string]$context.DeviceType);
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
        }
        if(($a.PSObject.Properties.Name-contains'PhysicalAdapterRequired')-and[bool]$a.PhysicalAdapterRequired-and[int]$context.PhysicalAdapterCount-lt1){
            $result.Applicable=$false;
            $result.ReasonEs='No hay adaptador de red fisico detectable';
            $result.ReasonEn='No detectable physical network adapter';
            return (Complete-VSO7ApplicabilityResultVSO -Result $result)
        }
        if($a.PSObject.Properties.Name-contains'StorageMediaType'){
            $allowed=@($a.StorageMediaType|ForEach-Object{
                [string]$_
            });
            if(@($context.StorageMediaTypes|Where-Object{
                $allowed-icontains[string]$_
            }).Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Tipo de almacenamiento no aplicable o no verificable';
                $result.ReasonEn='Storage media type is not applicable or could not be verified';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
        }
        if($a.PSObject.Properties.Name-contains'StorageMediaAnyOf'){
            $allowed=@($a.StorageMediaAnyOf|ForEach-Object{
                [string]$_
            });
            if(@($context.StorageMediaTypes|Where-Object{
                $allowed-icontains[string]$_
            }).Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='No se detecto un tipo de almacenamiento requerido';
                $result.ReasonEn='No required storage media type was detected';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
        }
        if($a.PSObject.Properties.Name-contains'RequiredModules'){
            foreach($module in @($a.RequiredModules)){
                if($null-eq(Get-Module -ListAvailable -Name ([string]$module) -ErrorAction SilentlyContinue|Select-Object -First 1)){
                    $result.Applicable=$false;
                    $result.ReasonEs=('Falta modulo {0}'-f$module);
                    $result.ReasonEn=('Missing module {0}'-f$module);
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                }
            }
        }
        if($a.PSObject.Properties.Name-contains'ServiceExists'){
            foreach($service in @($a.ServiceExists)){
                if($null-eq(Get-Service -Name ([string]$service) -ErrorAction SilentlyContinue)){
                    $result.Applicable=$false;
                    $result.ReasonEs=('No existe el servicio {0}'-f$service);
                    $result.ReasonEn=('Service {0} does not exist'-f$service);
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                }
            }
        }
        if($a.PSObject.Properties.Name-contains'OptionalFeatureExists'){
            foreach($of in @($a.OptionalFeatureExists)){
                try{
                    [void](Dism\Get-WindowsOptionalFeature -Online -FeatureName ([string]$of) -ErrorAction Stop)
                }catch{
                    $result.Applicable=$false;
                    $result.ReasonEs=('Optional Feature no disponible: {0}'-f$of);
                    $result.ReasonEn=('Optional Feature unavailable: {0}'-f$of);
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                }
            }
        }
        if($a.PSObject.Properties.Name-contains'RegistryAnyDifferent'){

            $different=0;
            $total=0
            foreach($spec in @($a.RegistryAnyDifferent)){

                $total++
                $rs=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$spec.Path) -Name ([string]$spec.Name)
                $kindMatch=$true;
                if($spec.PSObject.Properties.Name-contains'Kind'){
                    $kindMatch=([string]$rs.Kind-ceq[string]$spec.Kind)
                }
                if(-not[bool]$rs.Exists-or-not$kindMatch-or[string]$rs.Value-cne[string]$spec.Value){
                    $different++
                }

            }
            if($total-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Regla Registry vacia';
                $result.ReasonEn='Empty Registry applicability rule';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            if($different-eq0){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='Ya configurado';
                $result.ReasonEn='Already configured'
            }
            $result.Details+=('Registry values different: {0}/{1}'-f$different,$total)

        }
        if($a.PSObject.Properties.Name-contains'RegistryValueExists'){
            foreach($rvx in @($a.RegistryValueExists)){
                $rs=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$rvx.Path) -Name ([string]$rvx.Name);
                if(-not[bool]$rs.Exists){
                    $result.Applicable=$false;
                    $result.ReasonEs='Falta un valor Registry requerido';
                    $result.ReasonEn='A required Registry value is missing';
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                }
            }
        }
        if(($a.PSObject.Properties.Name-contains'AdminRequired')-and[bool]$a.AdminRequired-and-not(Test-IsAdministrator)){
            $result.Applicable=$false;
            $result.ReasonEs='Requiere administrador';
            $result.ReasonEn='Requires administrator';
            return (Complete-VSO7ApplicabilityResultVSO -Result $result)
        }
        if($a.PSObject.Properties.Name-contains'RequiredCommands'){

            foreach($cmd in @($a.RequiredCommands)){
                if([string]$cmd-like'*.exe'){
                    try{
                        [void](Resolve-VSOSystemExecutable -Name ([string]$cmd))
                    }catch{
                        $result.Applicable=$false;
                        $result.ReasonEs=('Falta {0}'-f$cmd);
                        $result.ReasonEn=('Missing {0}'-f$cmd);
                        return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                    }
                }elseif($null-eq(Get-Command ([string]$cmd) -ErrorAction SilentlyContinue)){
                    $result.Applicable=$false;
                    $result.ReasonEs=('Falta cmdlet {0}'-f$cmd);
                    $result.ReasonEn=('Missing cmdlet {0}'-f$cmd);
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                }
            }

        }
        if(($a.PSObject.Properties.Name-contains'HagsSupported')-and[bool]$a.HagsSupported){

            $hags=Get-VSO7HagsStateVSO
            if(-not[bool]$hags.Verified){
                $result.Applicable=$false;
                $result.ReasonEs='No se pudo verificar soporte HAGS de forma segura';
                $result.ReasonEn='HAGS support could not be safely verified';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            if(-not[bool]$hags.Supported){
                $result.Applicable=$false;
                $result.ReasonEs='La GPU/controlador no anuncia soporte HAGS';
                $result.ReasonEn='The GPU/driver does not report HAGS support';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            if(-not[bool]$hags.Mutable-or$null-eq$hags.Enabled){
                $result.Applicable=$false;
                $result.ReasonEs='HAGS presenta un estado multi-GPU ambiguo; mutacion bloqueada';
                $result.ReasonEn='HAGS has an ambiguous multi-GPU state; mutation is blocked';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            $result.Details+=('HAGS aggregate: {0}; enabled: {1}'-f$hags.AggregateState,[bool]$hags.Enabled)

        }
        if($a.PSObject.Properties.Name-contains'HagsDesiredEnabled'){

            $hagsDesired=[bool]$a.HagsDesiredEnabled
            $hags=Get-VSO7HagsStateVSO
            if(-not[bool]$hags.Verified-or-not[bool]$hags.Supported-or-not[bool]$hags.Mutable-or$null-eq$hags.Enabled){
                $result.Applicable=$false;
                $result.ReasonEs='El estado HAGS no puede representarse de forma estable/no ambigua';
                $result.ReasonEn='HAGS state cannot be represented as stable and unambiguous';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            if(([bool]$hags.Enabled)-eq$hagsDesired){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='HAGS ya esta en el estado solicitado';
                $result.ReasonEn='HAGS is already in the requested state';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }

        }
        if($a.PSObject.Properties.Name-contains'GraphicsGlobalWindowedDesired'){

            $desired=[bool]$a.GraphicsGlobalWindowedDesired
            $snap=Get-VSO7NativeRegistrySnapshotVSO -Path $script:VSO7GraphicsUserPreferencePath -Name 'DirectXUserGlobalSettings'
            $raw=if([bool]$snap.Exists){
                [string]$snap.Value
            }else{
                ''
            }
            try{
                [void](Assert-VSO7GraphicsOwnedTokenSemanticVSO -Raw $raw -Key 'SwapEffectUpgradeEnable');
                $current=Get-VSO7GraphicsCompositeTokenVSO -Raw $raw -Key 'SwapEffectUpgradeEnable';
                $autoHdr=Get-VSO7GraphicsCompositeTokenVSO -Raw $raw -Key 'AutoHDREnable'
            }catch{
                $result.Applicable=$false;
                $result.ReasonEs='El valor grafico global tiene un formato que VSO7 no modificara';
                $result.ReasonEn='The global graphics value has a format VSO7 will not modify';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            $desiredToken=if($desired){
                '1'
            }else{
                '0'
            }
            if($null-ne$current-and[string]$current-ceq$desiredToken){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='La preferencia global ya esta en el estado solicitado';
                $result.ReasonEn='The global preference is already in the requested state';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            if(-not$desired-and$null-ne$autoHdr){
                $result.Applicable=$false;
                $result.ReasonEs='Existe una preferencia Auto HDR en el valor global; VSO7 no desactiva optimizaciones en ventana sin poder interpretar ese contrato de forma estable';
                $result.ReasonEn='An Auto HDR preference exists in the global value; VSO7 will not disable windowed optimizations without a stable contract for interpreting it';
                return (Complete-VSO7ApplicabilityResultVSO -Result $result)
            }
            $result.Details+=('Windowed optimization token: {0}'-f$(if($null-eq$current){
                '<default>'
            }else{
                $current
            }))

        }
        if($a.PSObject.Properties.Name-contains'PowerSetting'){

            $ps=$a.PowerSetting;
            $snap=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias ([string]$ps.SubGroupAlias) -SettingAlias ([string]$ps.SettingAlias)
            if($ps.PSObject.Properties.Name-contains'RequireDifferentFrom'){

                $desired=[int]$ps.RequireDifferentFrom;
                if($snap.AC-eq$desired-and$snap.DC-eq$desired){
                    $result.Applicable=$false;
                    $result.AlreadySatisfied=$true;
                    $result.ReasonEs='Ya configurado';
                    $result.ReasonEn='Already configured'
                }

            }
            if($ps.PSObject.Properties.Name-contains'RequireACEquals'){

                $required=[int]$ps.RequireACEquals
                if($snap.AC-ne$required){
                    $result.Applicable=$false;
                    if($snap.AC-ne0){
                        $result.AlreadySatisfied=$true
                    };
                    $result.ReasonEs='El valor AC no coincide con el caso revisado';
                    $result.ReasonEn='The AC value does not match the reviewed case'
                }

            }
            if($ps.PSObject.Properties.Name-contains'RequireDCEquals'){

                $required=[int]$ps.RequireDCEquals
                if($snap.DC-ne$required){
                    $result.Applicable=$false;
                    $result.ReasonEs='El valor DC no coincide con el caso revisado';
                    $result.ReasonEn='The DC value does not match the reviewed case'
                }

            }
            if($ps.PSObject.Properties.Name-contains'RequireACBelow'){

                $limit=[int]$ps.RequireACBelow
                if($snap.AC-ge$limit){
                    $result.Applicable=$false;
                    $result.AlreadySatisfied=$true;
                    $result.ReasonEs='El valor AC ya esta en el limite esperado';
                    $result.ReasonEn='The AC value is already at the expected limit'
                }

            }
            if($ps.PSObject.Properties.Name-contains'RequireACDifferentFrom'){

                $desired=[int]$ps.RequireACDifferentFrom
                if($snap.AC-eq$desired){
                    $result.Applicable=$false;
                    $result.AlreadySatisfied=$true;
                    $result.ReasonEs='El valor AC ya coincide';
                    $result.ReasonEn='The AC value already matches'
                }

            }
            if($ps.PSObject.Properties.Name-contains'RequireDCDifferentFrom'){

                $desired=[int]$ps.RequireDCDifferentFrom
                if($snap.DC-eq$desired){
                    $result.Applicable=$false;
                    $result.AlreadySatisfied=$true;
                    $result.ReasonEs='El valor DC ya coincide';
                    $result.ReasonEn='The DC value already matches'
                }

            }
            $result.Details+=('Power {0}/{1}: AC={2}, DC={3}'-f$ps.SubGroupAlias,$ps.SettingAlias,$snap.AC,$snap.DC)

        }
        if($a.PSObject.Properties.Name-contains'NetAdapterAdvancedProperties'){

            $rule=$a.NetAdapterAdvancedProperties;
            $specs=@($rule.Properties);
            $supported=0;
            $different=0;
            $adapterCount=0
            foreach($identity in @(Get-VSO7PhysicalAdapterTargetsVSO -OnlyUp)){

                $adapterSupported=$false
                foreach($spec in $specs){

                    $snap=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $identity -RegistryKeyword ([string]$spec.RegistryKeyword)
                    if($null-eq$snap){
                        continue
                    };
                    $desired=@([string]$spec.RegistryValue);
                    $valid=@($snap.ValidRegistryValues)
                    if($valid.Count-eq0-or@($desired|Where-Object{
                        $valid-cnotcontains[string]$_
                    }).Count-gt0){
                        continue
                    }
                    $supported++;
                    $adapterSupported=$true;
                    if(-not(Test-VSO7StringSequenceEqualVSO -A $snap.RegistryValue -B $desired)){
                        $different++
                    }

                }
                if($adapterSupported){
                    $adapterCount++
                }

            }
            if($supported-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Ninguna NIC fisica activa expone esta capability con el valor solicitado';
                $result.ReasonEn='No active physical NIC exposes this capability with the requested value'
            }
            elseif($different-eq0){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='Ya configurado en las NIC compatibles';
                $result.ReasonEn='Already configured on supported NICs'
            }
            $result.Details+=('NIC capabilities: adapters={0}; supported properties={1}; different={2}'-f$adapterCount,$supported,$different)

        }
        if($a.PSObject.Properties.Name-contains'NetOffloadGlobal'){

            $rule=$a.NetOffloadGlobal;
            $current=Get-VSO7GlobalOffloadStateVSO -Property ([string]$rule.Property);
            $desired=[string]$rule.Value
            if($current-ceq$desired){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='Ya configurado globalmente';
                $result.ReasonEn='Already configured globally'
            }
            $result.Details+=('Global {0}: {1}'-f$rule.Property,$current)

        }
        if($a.PSObject.Properties.Name-contains'NetTcpCimSetting'){

            $rule=$a.NetTcpCimSetting
            if([string]$rule.Property-ine'Timestamps'){
                throw 'NetTcpCimSetting solo admite Timestamps en esta RC.'
            }
            $targets=@(Get-VSO7TcpTimestampCimInstancesVSO);
            $allowed=@()
            if($rule.PSObject.Properties.Name-contains'AllowedSourceValues'){
                $allowed=@($rule.AllowedSourceValues|ForEach-Object{
                    [string]$_
                })
            }
            $different=@($targets|Where-Object{
                [string]$_.Value-cne[string]$rule.Value
            })
            $eligible=@($different|Where-Object{
                $allowed.Count-eq0-or$allowed-icontains[string]$_.Value
            })
            if($targets.Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Windows no expone perfiles TCP CIM configurables';
                $result.ReasonEn='Windows exposes no configurable CIM TCP profiles'
            }
            elseif($different.Count-eq0){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='Ya configurado en todos los perfiles TCP CIM';
                $result.ReasonEn='Already configured on all CIM TCP profiles'
            }
            elseif($eligible.Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Los perfiles TCP estan fuera del caso de origen revisado';
                $result.ReasonEn='TCP profiles are outside the reviewed source-state scope'
            }
            $result.Details+=('TCP CIM profiles: {0}; different={1}; eligible={2}'-f$targets.Count,$different.Count,$eligible.Count)

        }
        if($a.PSObject.Properties.Name-contains'NetTcpSetting'){

            $rule=$a.NetTcpSetting;
            $targets=@(Get-VSO7TcpSettingTargetsVSO -Property ([string]$rule.Property));
            $allowed=@()
            if($rule.PSObject.Properties.Name-contains'AllowedSourceValues'){
                $allowed=@($rule.AllowedSourceValues|ForEach-Object{
                    [string]$_
                })
            }
            $different=@($targets|Where-Object{
                [string]$_.Value-cne[string]$rule.Value
            })
            $eligible=@($different|Where-Object{
                $allowed.Count-eq0-or$allowed-icontains[string]$_.Value
            })
            if($targets.Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Windows no expone perfiles TCP configurables para este ajuste';
                $result.ReasonEn='Windows exposes no configurable TCP profiles for this setting'
            }
            elseif($different.Count-eq0){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='Ya configurado en todos los perfiles TCP';
                $result.ReasonEn='Already configured on all TCP profiles'
            }
            elseif($eligible.Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Los perfiles TCP estan fuera del caso de origen revisado';
                $result.ReasonEn='TCP profiles are outside the reviewed source-state scope'
            }
            $result.Details+=('TCP profiles: {0}; different={1}; eligible={2}'-f$targets.Count,$different.Count,$eligible.Count)

        }
        if($a.PSObject.Properties.Name-contains'ScheduledTaskDisabled'){

            $rule=$a.ScheduledTaskDisabled
            $task=Get-VSO7ScheduledTaskSnapshotVSO -TaskPath ([string]$rule.TaskPath) -TaskName ([string]$rule.TaskName)
            if([bool]$task.Enabled){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='La tarea ya esta habilitada';
                $result.ReasonEn='The task is already enabled'
            }
            $result.Details+=('Task {0}{1}: {2}'-f$task.TaskPath,$task.TaskName,$task.State)

        }
        if(($a.PSObject.Properties.Name-contains'FsutilNtfsTrimDisabledNoReFs')-and[bool]$a.FsutilNtfsTrimDisabledNoReFs){

            $trim=Get-VSO7FsutilTrimStateVSO
            if([int]$trim.ReFsVolumeCount-gt0){
                $result.Applicable=$false;
                $result.ReasonEs='Hay volumen ReFS; VSO7 no usa el switch global de TRIM';
                $result.ReasonEn='A ReFS volume exists; VSO7 will not use the global TRIM switch'
            }
            elseif([int]$trim.NtfsDisabled-ne1){
                $result.Applicable=$false;
                $result.AlreadySatisfied=([int]$trim.NtfsDisabled-eq0);
                $result.ReasonEs=if([int]$trim.NtfsDisabled-eq0){
                    'TRIM NTFS ya esta habilitado'
                }else{
                    'Estado TRIM NTFS no compatible'
                };
                $result.ReasonEn=if([int]$trim.NtfsDisabled-eq0){
                    'NTFS TRIM is already enabled'
                }else{
                    'Unsupported NTFS TRIM state'
                }
            }
            $result.Details+=('NTFS DisableDeleteNotify={0}; ReFS volumes={1}'-f$trim.NtfsDisabled,$trim.ReFsVolumeCount)

        }
        if($a.PSObject.Properties.Name-contains'NetAdapterPowerManagement'){

            $rule=$a.NetAdapterPowerManagement;
            $onlyUp=$false
            if($rule.PSObject.Properties.Name-contains'OnlyUp'){
                $onlyUp=[bool]$rule.OnlyUp
            }
            $targets=@(Get-VSO7NetAdapterPowerTargetsVSO -Property ([string]$rule.Property) -OnlyUp:$onlyUp)
            $different=@($targets|Where-Object{
                [string]$_.Value-cne[string]$rule.Value
            })
            if($targets.Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='Ninguna NIC fisica expone esta capability de energia';
                $result.ReasonEn='No physical NIC exposes this power capability'
            }
            elseif($different.Count-eq0){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='Ya configurado en NIC compatibles';
                $result.ReasonEn='Already configured on supported NICs'
            }
            $result.Details+=('NIC power {0}: targets={1}; different={2}'-f$rule.Property,$targets.Count,$different.Count)

        }
        if(($a.PSObject.Properties.Name-contains'PhysicalRssDisabledRequired')-and[bool]$a.PhysicalRssDisabledRequired){

            $targets=@(Get-VSO7PhysicalRssTargetsVSO);
            $disabled=@($targets|Where-Object{
                -not[bool]$_.Enabled
            })
            if($targets.Count-eq0){
                $result.Applicable=$false;
                $result.ReasonEs='No hay NIC fisica activa con RSS consultable';
                $result.ReasonEn='No active physical NIC with queryable RSS'
            }
            elseif($disabled.Count-eq0){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='RSS ya activo en NIC fisicas compatibles';
                $result.ReasonEn='RSS already enabled on supported physical NICs'
            }
            $result.Details+=('RSS targets: {0}; disabled: {1}'-f$targets.Count,$disabled.Count)

        }
        if($Feature.PSObject.Properties.Name-contains'ExternalConflicts'){

            foreach($external in @($Feature.ExternalConflicts)){

                if([string]::IsNullOrWhiteSpace([string]$external)){
                    throw 'ExternalConflict vacio en catalogo VSO7.'
                }
                if(Test-VSO7ExternalConflictActiveVSO -ConflictId ([string]$external)){

                    $result.Applicable=$false;
                    $result.ReasonEs=('Conflicto de ownership activo con otro motor VSO: {0}'-f$external);
                    $result.ReasonEn=('Active ownership conflict with another VSO engine: {0}'-f$external);
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)

                }

            }

        }
        if($a.PSObject.Properties.Name-contains'RegistryValue'){

            $rv=$a.RegistryValue;
            $snap=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$rv.Path) -Name ([string]$rv.Name)
            if(-not[bool]$snap.Exists){
                $result.Applicable=$false;
                $result.AlreadySatisfied=$true;
                $result.ReasonEs='El override no existe; Windows ya conserva el control normal';
                $result.ReasonEn='The override is not present; Windows already retains normal control'
            }else{

                try{
                    $num=[int64]$snap.Value
                }catch{
                    $result.Applicable=$false;
                    $result.ReasonEs='El valor no es numerico';
                    $result.ReasonEn='Value is not numeric';
                    return (Complete-VSO7ApplicabilityResultVSO -Result $result)
                }
                if(($rv.PSObject.Properties.Name-contains'NumericMin')-and$num-lt[int64]$rv.NumericMin){
                    $result.Applicable=$false;
                    $result.ReasonEs='Valor fuera del caso revisado';
                    $result.ReasonEn='Value is outside the reviewed case'
                }
                if(($rv.PSObject.Properties.Name-contains'NumericMax')-and$num-gt[int64]$rv.NumericMax){
                    $result.Applicable=$false;
                    $result.ReasonEs='Valor fuera del caso revisado';
                    $result.ReasonEn='Value is outside the reviewed case'
                }
                $result.Details+=('Configured {0}={1}'-f$rv.Name,$num)

            }

        }

    }catch{
        $result.Applicable=$false;
        $result.ReasonEs=('No se pudo verificar aplicabilidad: {0}'-f$_.Exception.Message);
        $result.ReasonEn=('Applicability could not be verified: {0}'-f$_.Exception.Message)
    }
    return (Complete-VSO7ApplicabilityResultVSO -Result $result)

}

function Get-VSO7EvidenceLabelVSO {

    param([AllowNull()][string]$Evidence)
    if([string]::IsNullOrWhiteSpace($Evidence)){
        return 'Unrated'
    }
    return $Evidence

}

function Get-VSO7MaturityLabelVSO {

    param([AllowNull()][string]$Maturity)
    if([string]::IsNullOrWhiteSpace($Maturity)){
        return 'Unrated'
    }
    return $Maturity

}

function Get-VSO7SpecializedChoiceFeatureIdsVSO {

    return @(
        'V7UI001','V7UI002','V7UI003',
        'V7MT004','V7MT005','V7MT006','V7MT007',
        'V7TB002','V7TB003','V7TB004','V7TB005',
        'V7TB011','V7TB012','V7TB013','V7TB014','V7TB015','V7TB016','V7TB017','V7TB018','V7TB019',
        'V7FE001','V7FE002','V7FE003','V7FE004','V7FE017','V7FE018','V7FE019','V7FE020',
        'V7ST008','V7ST009','V7ST010'
    )

}

function Assert-VSO7FeatureSelectionRelationsVSO {

    param(
        [Parameter(Mandatory=$true)][array]$Requested,
        [Parameter(Mandatory=$true)][array]$Catalog,
        [switch]$AllowSpecializedChoice
    )
    $selected=@()
    $specialized=if($AllowSpecializedChoice){
        @(Get-VSO7SpecializedChoiceFeatureIdsVSO)
    }else{
        @()
    }
    foreach($id in $Requested){

        $f=@($Catalog|Where-Object{
            [string]$_.FeatureId-ceq[string]$id
        }|Select-Object -First 1)
        if($f.Count-ne1){
            throw ('FeatureId no existe en catalogo: {0}'-f$id)
        }
        if($f[0].PSObject.Properties.Name-contains'Selectable' -and -not[bool]$f[0].Selectable){

            if(-not$AllowSpecializedChoice-or$specialized-inotcontains[string]$id){
                throw ('Feature no seleccionable en esta ruta: {0}'-f$id)
            }

        }
        foreach($conflict in @($f[0].ConflictsWith)){
            if($Requested-contains[string]$conflict){
                throw ('Features incompatibles seleccionadas: {0} / {1}'-f$id,$conflict)
            }
        }
        foreach($req in @($f[0].Requires)){
            if($Requested-notcontains[string]$req){
                throw ('Feature {0} requiere {1} en la misma seleccion.'-f$id,$req)
            }
        }
        $selected+=$f[0]

    }
    $groups=@($selected|Where-Object{
        -not[string]::IsNullOrWhiteSpace([string]$_.MutuallyExclusiveGroup)
    }|Group-Object MutuallyExclusiveGroup|Where-Object{
        $_.Count-gt1
    })
    if($groups.Count-gt0){

        $g=$groups[0];
        $ids=@($g.Group|ForEach-Object{
            [string]$_.FeatureId
        })-join', '
        throw ('Features mutuamente excluyentes seleccionadas ({0}): {1}'-f$g.Name,$ids)

    }
    return $true

}

function Assert-VSO7NativeFeatureSelectionVSO {

    param(
        [Parameter(Mandatory=$true)][array]$Requested,
        [Parameter(Mandatory=$true)][array]$Catalog,
        [switch]$AllowSpecializedChoice
    )
    [void](Assert-VSO7FeatureSelectionRelationsVSO -Requested $Requested -Catalog $Catalog -AllowSpecializedChoice:$AllowSpecializedChoice)
    foreach($id in $Requested){

        $f=@($Catalog|Where-Object{
            [string]$_.FeatureId-ceq[string]$id
        }|Select-Object -First 1)
        $app=Get-VSO7FeatureApplicabilityVSO -Feature $f[0]
        if(-not[bool]$app.Applicable){
            throw ('Feature {0} no aplicable: {1}'-f$id,$app.ReasonEs)
        }

    }
    return $true

}

function Confirm-VSO7HighRiskFeatureSelectionVSO {

    param([Parameter(Mandatory=$true)][array]$FeatureIds,[Parameter(Mandatory=$true)][array]$Catalog)
    $risk4=@($Catalog|Where-Object{
        ([int]$_.Risk-ge4)-and($FeatureIds-contains[string]$_.FeatureId)
    })
    if($risk4.Count-eq0){
        return $true
    }
    $isEn=($script:Language-eq'en')
    Write-CenteredLineVSO -Text $(if($isEn){
        'VERY HIGH RISK selected. Typed confirmation required.'
    }else{
        'RIESGO MUY ALTO seleccionado. Se exige confirmacion escrita.'
    }) -Color $script:ThemeDanger
    return [bool](Confirm-Word -Word 'RIESGO 4' -Message 'Escribe exactamente RIESGO 4 para continuar')

}

function Get-VSO7TrustedWingetDirectoryVSO {

    try{

        $windowsApps=[IO.Path]::GetFullPath((Join-Path $script:ProgramFiles 'WindowsApps')).TrimEnd('\')
        $pkg=@(Appx\Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction Stop|Where-Object{
            -not[string]::IsNullOrWhiteSpace([string]$_.InstallLocation)
        }|Sort-Object Version -Descending|Select-Object -First 1)
        if($pkg.Count-ne1){
            return $null
        }
        $loc=[IO.Path]::GetFullPath([string]$pkg[0].InstallLocation).TrimEnd('\')
        if(-not$loc.StartsWith(($windowsApps+'\'),[StringComparison]::OrdinalIgnoreCase)){
            throw 'App Installer esta fuera de Program Files\\WindowsApps.'
        }
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $loc)
        $exe=Join-Path $loc 'winget.exe'
        if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){
            return $null
        }
        $item=Get-Item -LiteralPath $exe -Force -ErrorAction Stop
        if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'winget.exe no es un archivo local confiable.'
        }
        return $loc

    }catch{
        Write-VSO7Log ("WinGet confiable no disponible: {0}"-f$_.Exception.Message) 'WARN';
        return $null
    }

}

function Invoke-VSO7WingetCommandExitCodeVSO {

    param([Parameter(Mandatory=$true)][string]$Exe,[Parameter(Mandatory=$true)][string[]]$Arguments)
    $process=Start-Process -FilePath $Exe -ArgumentList $Arguments -Wait -PassThru -WindowStyle Hidden -ErrorAction Stop
    try{
        return [int]$process.ExitCode
    }finally{
        $process.Dispose()
    }

}

function Get-VSO7WingetExactPackageStateVSO {

    param([Parameter(Mandatory=$true)][string]$Exe,[Parameter(Mandatory=$true)][string]$AppId)
    $code=Invoke-VSO7WingetCommandExitCodeVSO -Exe $Exe -Arguments @('list','--id',$AppId,'--exact','--disable-interactivity','--accept-source-agreements')
    if($code-eq0){
        return 'Present'
    }
    # APPINSTALLER_CLI_ERROR_NO_APPLICATIONS_FOUND (0x8A150014), exposed by Start-Process as signed Int32.
    if($code-eq-1978335212){
        return 'Absent'
    }
    throw ('winget list fallo para {0} con codigo {1}.'-f$AppId,$code)

}

function Test-VSO7AppxGroupPresenceVSO {

    param([Parameter(Mandatory=$true)][string[]]$AppIds)
    $ids=@($AppIds|Where-Object{
        -not[string]::IsNullOrWhiteSpace([string]$_)
    }|Select-Object -Unique)
    if($ids.Count-eq0){
        return $false
    }
    $provisioned=@(Dism\Get-AppxProvisionedPackage -Online -ErrorAction Stop)
    foreach($id in $ids){

        if(@(Appx\Get-AppxPackage -AllUsers -Name $id -ErrorAction Stop).Count-gt0){
            return $true
        }
        if(@($provisioned|Where-Object{
            [string]$_.DisplayName-ieq$id
        }).Count-gt0){
            return $true
        }

    }
    return $false

}

function Invoke-VSO7NonReversibleAppxGroupVSO {

    param(
        [Parameter(Mandatory=$true)]$Session,
        [Parameter(Mandatory=$true)][string]$Id,
        [Parameter(Mandatory=$true)][string]$Description,
        [Parameter(Mandatory=$true)][string[]]$AppIds
    )
    $ids=@($AppIds|Select-Object -Unique)
    # No journal irreversible debt unless VSO can prove that at least one target exists.
    if(-not(Test-VSO7AppxGroupPresenceVSO -AppIds $ids)){
        return $true
    }
    Add-VSO7NativeNonReversibleBackupVSO -Session $Session -Id $Id -Description $Description
    $ok=$true
    foreach($appId in $ids){
        if(-not(Invoke-VSO7RemoveAppIdVSO -AppId $appId -RemovalMethod 'Appx')){
            $ok=$false
        }
    }
    return $ok

}

function Invoke-VSO7RemoveAppIdVSO {

    param([Parameter(Mandatory=$true)][string]$AppId,[string]$RemovalMethod='Appx')
    $ok=$true
    if($RemovalMethod-ieq'WinGet'){

        try{

            $dir=Get-VSO7TrustedWingetDirectoryVSO;
            if([string]::IsNullOrWhiteSpace([string]$dir)){
                throw ('WinGet no esta disponible para desinstalar {0}.'-f$AppId)
            }
            $exe=Join-Path $dir 'winget.exe'
            if((Get-VSO7WingetExactPackageStateVSO -Exe $exe -AppId $AppId)-ceq'Absent'){
                return $true
            }
            $code=Invoke-VSO7WingetCommandExitCodeVSO -Exe $exe -Arguments @('uninstall','--id',$AppId,'--exact','--disable-interactivity','--accept-source-agreements')
            if($code-ne0-and$code-ne-1978335212){
                Write-VSO7Log ("winget uninstall fallo para {0} con codigo {1}."-f$AppId,$code) 'WARN';
                return $false
            }
            $after=Get-VSO7WingetExactPackageStateVSO -Exe $exe -AppId $AppId
            if($after-cne'Absent'){
                Write-VSO7Log ("Verificacion WinGet fallo para {0}: el paquete sigue instalado."-f$AppId) 'WARN';
                return $false
            }
            return $true

        }catch{
            Write-VSO7Log ("Error eliminando/verificando WinGet {0}: {1}"-f$AppId,$_.Exception.Message) 'ERROR';
            return $false
        }

    }
    try{

        $pkgs=@(Appx\Get-AppxPackage -AllUsers -Name $AppId -ErrorAction Stop)
        foreach($pkg in $pkgs){
            try{
                Appx\Remove-AppxPackage -Package $pkg.PackageFullName -AllUsers -ErrorAction Stop
            }catch{
                $ok=$false;
                Write-VSO7Log ("No se pudo quitar Appx {0}: {1}"-f$pkg.Name,$_.Exception.Message) 'WARN'
            }
        }
        $prov=@(Dism\Get-AppxProvisionedPackage -Online -ErrorAction Stop|Where-Object{
            [string]$_.DisplayName-ieq$AppId
        })
        foreach($pkg in $prov){
            try{
                Dism\Remove-AppxProvisionedPackage -Online -PackageName $pkg.PackageName -ErrorAction Stop|Out-Null
            }catch{
                $ok=$false;
                Write-VSO7Log ("No se pudo quitar provision Appx {0}: {1}"-f$pkg.DisplayName,$_.Exception.Message) 'WARN'
            }
        }
        $remainingInstalled=@(Appx\Get-AppxPackage -AllUsers -Name $AppId -ErrorAction Stop)
        $remainingProvisioned=@(Dism\Get-AppxProvisionedPackage -Online -ErrorAction Stop|Where-Object{
            [string]$_.DisplayName-ieq$AppId
        })
        if($remainingInstalled.Count-gt0-or$remainingProvisioned.Count-gt0){

            $ok=$false
            Write-VSO7Log ("Verificacion Appx fallo para {0}: instalados restantes={1}; provisionados restantes={2}."-f$AppId,$remainingInstalled.Count,$remainingProvisioned.Count) 'WARN'

        }

    }catch{
        $ok=$false;
        Write-VSO7Log ("Error eliminando/verificando app {0}: {1}"-f$AppId,$_.Exception.Message) 'ERROR'
    }
    return $ok

}

function Invoke-VSO7NativeAppRemovalVSO {

    param([Parameter(Mandatory=$true)][string[]]$Apps)
    $catalog=@(Get-VSO7AppCatalogVSO);
    $ok=$true
    foreach($id in @($Apps|Select-Object -Unique)){

        $entry=@($catalog|Where-Object{
            @($_.AppId)-icontains$id
        }|Select-Object -First 1)
        if($entry.Count-ne1){
            throw ('AppId no permitido por el catalogo VSO7: {0}'-f$id)
        }
        $method=[string]$entry[0].RemovalMethod
        if(-not(Invoke-VSO7RemoveAppIdVSO -AppId $id -RemovalMethod $method)){
            $ok=$false
        }

    }
    return $ok

}

function Test-VSO7EdgeMachineBrowserInstalledVSO {

    $roots=@($script:ProgramFilesX86,$script:ProgramFiles)|Where-Object{
        -not[string]::IsNullOrWhiteSpace([string]$_)
    }|Select-Object -Unique
    foreach($root in $roots){

        $exe=Join-Path $root 'Microsoft\Edge\Application\msedge.exe'
        if(Test-Path -LiteralPath $exe -PathType Leaf -ErrorAction Stop){
            return $true
        }

    }
    return $false

}

function Get-VSO7TrustedUserProfileRootsVSO {

    if([string]::IsNullOrWhiteSpace([string]$script:SystemDrive)-or[string]::IsNullOrWhiteSpace([string]$script:WindowsRoot)){
        throw 'Rutas confiables de Windows no estan inicializadas.'
    }
    $base=$null;
    $profileList=$null
    $roots=New-Object System.Collections.Generic.List[string]
    try{

        $base=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,[Microsoft.Win32.RegistryView]::Registry64)
        $profileList=$base.OpenSubKey('SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList',$false)
        if($null-eq$profileList){
            throw 'No existe ProfileList de Windows.'
        }
        foreach($subName in @($profileList.GetSubKeyNames())){

            $profileKey=$null
            try{

                $profileKey=$profileList.OpenSubKey([string]$subName,$false)
                if($null-eq$profileKey){
                    throw ('No se pudo abrir ProfileList\{0}.'-f$subName)
                }
                $raw=[string]$profileKey.GetValue('ProfileImagePath',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                if([string]::IsNullOrWhiteSpace($raw)){
                    continue
                }
                $expanded=$raw -replace '(?i)%SystemDrive%',[string]$script:SystemDrive
                $expanded=$expanded -replace '(?i)%SystemRoot%',[string]$script:WindowsRoot
                $expanded=$expanded -replace '(?i)%windir%',[string]$script:WindowsRoot
                if($expanded-match'%[^%]+%'){
                    throw ('ProfileImagePath contiene variables no permitidas: {0}'-f$raw)
                }
                if(-not[IO.Path]::IsPathRooted($expanded)){
                    throw ('ProfileImagePath no es absoluto: {0}'-f$raw)
                }
                $full=[IO.Path]::GetFullPath($expanded).TrimEnd('\')
                if($full-notmatch'^[A-Za-z]:\\'){
                    throw ('ProfileImagePath no es una ruta local de unidad: {0}'-f$full)
                }
                if(-not(Test-Path -LiteralPath $full -PathType Container -ErrorAction Stop)){
                    continue
                }
                [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $full)
                if(@($roots|Where-Object{
                    [string]$_-ieq$full
                }).Count-eq0){
                    [void]$roots.Add($full)
                }

            }finally{
                if($null-ne$profileKey){
                    try{
                        $profileKey.Close()
                    }catch{}
                }
            }

        }

    }finally{

        if($null-ne$profileList){
            try{
                $profileList.Close()
            }catch{}
        }
        if($null-ne$base){
            try{
                $base.Close()
            }catch{}
        }

    }
    return $roots.ToArray()

}

function Test-VSO7EdgeProfileBrowserInstalledVSO {

    param([Parameter(Mandatory=$true)][string]$ProfileRoot)
    $root=[IO.Path]::GetFullPath($ProfileRoot).TrimEnd('\')
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $root)
    $cursor=$root
    foreach($part in @('AppData','Local','Microsoft','Edge','Application','msedge.exe')){

        $cursor=Join-Path $cursor $part
        if(-not(Test-Path -LiteralPath $cursor -ErrorAction Stop)){
            return $false
        }
        $item=Get-Item -LiteralPath $cursor -Force -ErrorAction Stop
        if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw ('Edge per-user detectado bajo una ruta reparse/no confiable: {0}'-f$cursor)
        }
        if($part-ceq'msedge.exe'){

            if($item.PSIsContainer){
                throw ('La ruta esperada de msedge.exe es un directorio: {0}'-f$cursor)
            }
            return $true

        }
        if(-not$item.PSIsContainer){
            throw ('Componente de perfil esperado como directorio no lo es: {0}'-f$cursor)
        }

    }
    return $false

}

function Test-VSO7EdgePerUserBrowserInstalledVSO {

    foreach($profileRoot in @(Get-VSO7TrustedUserProfileRootsVSO)){

        if(Test-VSO7EdgeProfileBrowserInstalledVSO -ProfileRoot ([string]$profileRoot)){
            return $true
        }

    }
    if([string]::IsNullOrWhiteSpace([string]$script:LocalAppData)){
        throw 'LocalAppData confiable no esta inicializado.'
    }
    $edgeRoot=[IO.Path]::GetFullPath((Join-Path $script:LocalAppData 'Microsoft\Edge\Application')).TrimEnd('\')
    foreach($viewName in @('Registry64','Registry32')){

        $base=$null;
        $key=$null
        try{

            $view=$(if($viewName-ceq'Registry64'){
                [Microsoft.Win32.RegistryView]::Registry64
            }else{
                [Microsoft.Win32.RegistryView]::Registry32
            })
            $base=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::CurrentUser,$view)
            $key=$base.OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Microsoft Edge',$false)
            if($null-eq$key){
                continue
            }
            $raw=[string]$key.GetValue('InstallLocation',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            if([string]::IsNullOrWhiteSpace($raw)){
                continue
            }
            if(-not[IO.Path]::IsPathRooted($raw)){
                continue
            }
            $location=[IO.Path]::GetFullPath($raw).TrimEnd('\')
            if(-not$location.Equals($edgeRoot,[StringComparison]::OrdinalIgnoreCase)-and-not$location.StartsWith(($edgeRoot+'\'),[StringComparison]::OrdinalIgnoreCase)){
                continue
            }
            if(Test-Path -LiteralPath (Join-Path $location 'msedge.exe') -PathType Leaf -ErrorAction Stop){
                return $true
            }

        }finally{

            if($null-ne$key){
                try{
                    $key.Close()
                }catch{}
            }
            if($null-ne$base){
                try{
                    $base.Close()
                }catch{}
            }

        }

    }
    return $false

}

function Test-VSO7EdgeBrowserInstalledVSO {

    return [bool]((Test-VSO7EdgeMachineBrowserInstalledVSO)-or(Test-VSO7EdgePerUserBrowserInstalledVSO))

}

function ConvertFrom-VSO7EdgeUninstallStringSetupPathVSO {

    param([AllowNull()][string]$UninstallString)
    if([string]::IsNullOrWhiteSpace([string]$UninstallString)){
        return $null
    }
    $raw=[string]$UninstallString.Trim()
    if($raw.Length-lt3){
        return $null
    }
    if($raw[0]-eq'"'){

        $end=$raw.IndexOf('"',1)
        if($end-le1){
            return $null
        }
        return $raw.Substring(1,$end-1)

    }
    $match=[regex]::Match($raw,'^(?<exe>[^\s"]+setup\.exe)(?:\s|$)',[Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if($match.Success){
        return $match.Groups['exe'].Value
    }
    return $null

}

function Get-VSO7EdgeRegistryUninstallStringsVSO {

    $results=New-Object System.Collections.Generic.List[string]
    foreach($viewName in @('Registry64','Registry32')){

        $base=$null;
        $key=$null
        try{

            $view=$(if($viewName-ceq'Registry64'){
                [Microsoft.Win32.RegistryView]::Registry64
            }else{
                [Microsoft.Win32.RegistryView]::Registry32
            })
            $base=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,$view)
            $key=$base.OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Microsoft Edge',$false)
            if($null-eq$key){
                continue
            }
            $raw=[string]$key.GetValue('UninstallString',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            if(-not[string]::IsNullOrWhiteSpace($raw)-and-not$results.Contains($raw)){
                [void]$results.Add($raw)
            }

        }catch{

            Write-VSO7Log ("No se pudo consultar el registro de desinstalacion de Edge ({0}): {1}"-f$viewName,$_.Exception.Message) 'WARN'

        }finally{

            if($null-ne$key){
                try{
                    $key.Close()
                }catch{}
            }
            if($null-ne$base){
                try{
                    $base.Close()
                }catch{}
            }

        }

    }
    return $results.ToArray()

}

function Test-VSO7EdgeSetupPathInTrustedRootVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    if([string]::IsNullOrWhiteSpace($Path)-or-not[IO.Path]::IsPathRooted($Path)){
        return $false
    }
    try{
        $full=[IO.Path]::GetFullPath($Path)
    }catch{
        return $false
    }
    if([IO.Path]::GetFileName($full)-ine'setup.exe'){
        return $false
    }
    foreach($root in @($script:ProgramFilesX86,$script:ProgramFiles)|Where-Object{
        -not[string]::IsNullOrWhiteSpace([string]$_)
    }|Select-Object -Unique){

        $edgeRoot=[IO.Path]::GetFullPath((Join-Path $root 'Microsoft\Edge\Application')).TrimEnd('\')+'\'
        if(-not$full.StartsWith($edgeRoot,[StringComparison]::OrdinalIgnoreCase)){
            continue
        }
        $relative=$full.Substring($edgeRoot.Length)
        $parts=@($relative.Split('\'))
        if($parts.Count-eq3-and$parts[0]-match'^\d+(?:\.\d+){2,3}$'-and[string]$parts[1]-ieq'Installer'-and[string]$parts[2]-ieq'setup.exe'){
            return $true
        }

    }
    return $false

}

function Assert-VSO7EdgeSetupTrustedVSO {

    param([Parameter(Mandatory=$true)][string]$SetupPath)
    if(-not(Test-VSO7EdgeSetupPathInTrustedRootVSO -Path $SetupPath)){
        throw 'El desinstalador de Edge no esta bajo una raiz Microsoft Edge confiable.'
    }
    $full=Assert-VSO7LocalPathChainNoReparseVSO -Path $SetupPath
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if($item.PSIsContainer-or[IO.Path]::GetFileName([string]$item.FullName)-ine'setup.exe'){
        throw 'El desinstalador de Edge no es un setup.exe local valido.'
    }
    $signature=Microsoft.PowerShell.Security\Get-AuthenticodeSignature -FilePath $full -ErrorAction Stop
    if($null-eq$signature-or[string]$signature.Status-cne'Valid'-or$null-eq$signature.SignerCertificate){
        throw 'El desinstalador de Edge no tiene una firma Authenticode valida.'
    }
    $subject=[string]$signature.SignerCertificate.Subject
    if($subject-notmatch'(?i)(^|,\s*)(CN|O)=Microsoft Corporation(,|$)'){
        throw 'El desinstalador de Edge no esta firmado por Microsoft Corporation.'
    }
    return [IO.Path]::GetFullPath([string]$item.FullName)

}

function Get-VSO7EdgeUninstallSetupVSO {

    foreach($uninstallString in @(Get-VSO7EdgeRegistryUninstallStringsVSO)){

        $candidate=ConvertFrom-VSO7EdgeUninstallStringSetupPathVSO -UninstallString ([string]$uninstallString)
        if([string]::IsNullOrWhiteSpace([string]$candidate)){
            continue
        }
        try{
            return (Assert-VSO7EdgeSetupTrustedVSO -SetupPath $candidate)
        }catch{
            Write-VSO7Log ("Edge uninstall registry candidate rejected: {0}"-f$_.Exception.Message) 'WARN'
        }

    }
    $roots=@($script:ProgramFilesX86,$script:ProgramFiles)|Where-Object{
        -not[string]::IsNullOrWhiteSpace([string]$_)
    }|Select-Object -Unique
    foreach($root in $roots){

        $app=Join-Path $root 'Microsoft\Edge\Application'
        if(-not(Test-Path -LiteralPath $app -PathType Container -ErrorAction Stop)){
            continue
        }
        [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $app)
        $candidates=@(Get-ChildItem -LiteralPath $app -Directory -ErrorAction Stop|Where-Object{
            $_.Name-match'^\d+(?:\.\d+){2,3}$'
        }|Sort-Object {
            [version]$_.Name
        } -Descending)
        foreach($dir in $candidates){

            $candidate=Join-Path $dir.FullName 'Installer\setup.exe'
            if(-not(Test-Path -LiteralPath $candidate -PathType Leaf -ErrorAction Stop)){
                continue
            }
            try{
                return (Assert-VSO7EdgeSetupTrustedVSO -SetupPath $candidate)
            }catch{
                Write-VSO7Log ("Edge local uninstaller candidate rejected: {0}"-f$_.Exception.Message) 'WARN'
            }

        }

    }
    return $null

}

function Invoke-VSO7EdgeUninstallerVSO {

    param([Parameter(Mandatory=$true)][string]$SetupPath)
    $trusted=Assert-VSO7EdgeSetupTrustedVSO -SetupPath $SetupPath
    $p=Microsoft.PowerShell.Management\Start-Process -FilePath $trusted -ArgumentList @('--uninstall','--system-level','--verbose-logging','--force-uninstall') -Wait -PassThru -WindowStyle Hidden -ErrorAction Stop
    try{
        return ([int]$p.ExitCode-eq0)
    }finally{
        $p.Dispose()
    }

}

function Wait-VSO7EdgeBrowserAbsentVSO {

    param([int]$Attempts=10,[int]$DelayMilliseconds=500)
    if($Attempts-lt1){
        throw 'Attempts debe ser al menos 1.'
    }
    for($attempt=0;$attempt-lt$Attempts;$attempt++){

        if(-not(Test-VSO7EdgeBrowserInstalledVSO)){
            return $true
        }
        if($attempt-lt($Attempts-1)-and$DelayMilliseconds-gt0){
            Start-Sleep -Milliseconds $DelayMilliseconds
        }

    }
    return $false

}

function Invoke-VSO7ForceRemoveEdgeVSO {

    param($Session)
    $perUser=[bool](Test-VSO7EdgePerUserBrowserInstalledVSO)
    $machine=[bool](Test-VSO7EdgeMachineBrowserInstalledVSO)
    if(-not$perUser-and-not$machine){
        return $true
    }
    if($perUser){
        throw 'Se detecto una instalacion de Edge solo para el usuario. VSO7 no ejecuta desinstaladores desde LocalAppData con privilegios elevados; usa la desinstalacion de Windows para esa instalacion.'
    }
    $setup=Get-VSO7EdgeUninstallSetupVSO
    if([string]::IsNullOrWhiteSpace([string]$setup)){
        throw 'Microsoft Edge sigue instalado, pero no se encontro su desinstalador local.'
    }
    if($null-ne$Session){
        Add-VSO7NativeNonReversibleBackupVSO -Session $Session -Id 'V7SP008' -Description 'La desinstalacion forzada de Edge no tiene reinstalacion automatica en VSO7.'
    }
    if(-not(Invoke-VSO7EdgeUninstallerVSO -SetupPath $setup)){
        return $false
    }
    if(Wait-VSO7EdgeBrowserAbsentVSO){
        return $true
    }
    Write-VSO7Log 'La desinstalacion de Edge devolvio exito, pero alguna instalacion de msedge.exe sigue presente tras la verificacion final.' 'WARN'
    return $false

}

