        $ven=[string]$parts.VendorId;
        $dev=[string]$parts.DeviceId;
        $subsys=[string]$parts.SubsystemId
    }
    if([string]::IsNullOrWhiteSpace($ven)-and$null-ne$Adapter-and$Adapter.PSObject.Properties.Name-contains'VendorId' -and [uint32]$Adapter.VendorId-ne0){
        $ven=('{0:X4}'-f[uint32]$Adapter.VendorId)
    }
    if([string]::IsNullOrWhiteSpace($dev)-and$null-ne$Adapter-and$Adapter.PSObject.Properties.Name-contains'DeviceId' -and [uint32]$Adapter.DeviceId-ne0){
        $dev=('{0:X4}'-f[uint32]$Adapter.DeviceId)
    }
    if([string]::IsNullOrWhiteSpace($subsys)-and$null-ne$Adapter-and$Adapter.PSObject.Properties.Name-contains'SubSystemId' -and [uint32]$Adapter.SubSystemId-ne0){
        $subsys=('{0:X8}'-f[uint32]$Adapter.SubSystemId)
    }
    $persistent=if(-not[string]::IsNullOrWhiteSpace($pnp)){
        ('PNP|'+$pnp.ToUpperInvariant())
    }elseif($ven-and$dev-and$subsys){
        ('PCI|VEN_'+$ven+'&DEV_'+$dev+'&SUBSYS_'+$subsys)
    }else{
        ''
    }
    $luid=if($null-ne$Adapter-and$Adapter.PSObject.Properties.Name-contains'Luid'){
        [string]$Adapter.Luid
    }else{
        ''
    }
    return [pscustomobject]@{
        PersistentIdentity=$persistent;
        PnpDeviceId=$pnp;
        VendorId=$ven;
        DeviceId=$dev;
        SubsystemId=$subsys;
        RuntimeLuid=$luid;
        RuntimeIdentity=$(if($luid){
            'LUID|'+$luid
        }else{
            ''
        })
    }

}

function Resolve-VSO7PersistentGpuIdentityVSO {

    param([Parameter(Mandatory=$true)]$Identity,[AllowNull()][object[]]$Candidates)
    $items=@($Candidates);
    $pnp=[string]$Identity.PnpDeviceId
    if(-not[string]::IsNullOrWhiteSpace($pnp)){
        $m=@($items|Where-Object{
            [string]$_.PNPDeviceID-ieq$pnp
        });
        if($m.Count-eq1){
            return [pscustomobject]@{
                Status='Resolved';
                Evidence='ExactPnp';
                Adapter=$m[0]
            }
        };
        if($m.Count-gt1){
            return [pscustomobject]@{
                Status='Ambiguous';
                Evidence='DuplicatePnp';
                Adapter=$null
            }
        }
    }
    $ven=[string]$Identity.VendorId;
    $dev=[string]$Identity.DeviceId;
    $sub=[string]$Identity.SubsystemId
    if($ven-and$dev-and$sub){
        $m=@($items|Where-Object{
            $p=Get-VSO7PciIdentityPartsVSO -PnpDeviceId ([string]$_.PNPDeviceID);[string]$p.VendorId-ceq$ven-and[string]$p.DeviceId-ceq$dev-and[string]$p.SubsystemId-ceq$sub
        });
        if($m.Count-eq1){
            return [pscustomobject]@{
                Status='Resolved';
                Evidence='UniquePciTuple';
                Adapter=$m[0]
            }
        };
        if($m.Count-gt1){
            return [pscustomobject]@{
                Status='Ambiguous';
                Evidence='PciTupleCollision';
                Adapter=$null
            }
        }
    }
    return [pscustomobject]@{
        Status='Unresolved';
        Evidence='PersistentIdentityNotFound';
        Adapter=$null
    }

}

function Get-VSO7RuntimeAdapterCorrelationVSO {

    param([AllowNull()][object[]]$DxCore,[AllowNull()][object[]]$Dxgi)
    $out=New-Object Collections.Generic.List[object]
    foreach($d in @($DxCore)){
        $l=[string]$d.Luid;
        if([string]::IsNullOrWhiteSpace($l)){
            continue
        };
        $m=@($Dxgi|Where-Object{
            [string]$_.Luid-ceq$l
        });
        $status=if($m.Count-eq1){
            'Resolved'
        }elseif($m.Count-gt1){
            'Ambiguous'
        }else{
            'Unresolved'
        };
        [void]$out.Add([pscustomobject]@{
            Luid=$l;Status=$status;DxCore=$d;Dxgi=$(if($m.Count-eq1){
                $m[0]
            }else{
                $null
            });Evidence='RuntimeLuidOnly'
        })
    }
    return $out.ToArray()

}

function Get-VSO7GraphicsPreferenceMappingVSO {

    param([AllowNull()][object[]]$Adapters)
    $hardware=@($Adapters|Where-Object{
        $null-ne$_-and$_.PSObject.Properties.Name-contains'Software'-and$_.PSObject.Properties.Name-contains'MinimumPowerRank'-and$_.PSObject.Properties.Name-contains'HighPerformanceRank'-and-not[bool]$_.Software
    });
    $min=@($hardware|Where-Object{
        [int]$_.MinimumPowerRank-eq0
    });
    $high=@($hardware|Where-Object{
        [int]$_.HighPerformanceRank-eq0
    })
    return [pscustomobject]@{
        MinimumPower=$(if($min.Count-eq1){
            $min[0]
        }else{
            $null
        });
        HighPerformance=$(if($high.Count-eq1){
            $high[0]
        }else{
            $null
        });
        MinimumPowerStatus=$(if($min.Count-eq1){
            'Resolved'
        }elseif($min.Count-gt1){
            'Ambiguous'
        }else{
            'Unknown'
        });
        HighPerformanceStatus=$(if($high.Count-eq1){
            'Resolved'
        }elseif($high.Count-gt1){
            'Ambiguous'
        }else{
            'Unknown'
        });
        Evidence='DXGI/DXCore preference ordering; session-scoped'
    }

}

function Get-VSO7DisplayPersistentIdentityVSO {

    param([Parameter(Mandatory=$true)]$Display)
    $path=[string]$Display.DevicePath;
    $valid=($Display.PSObject.Properties.Name-contains'EdidIdsValid'-and[bool]$Display.EdidIdsValid);
    $m=[int]$Display.EdidManufacturerId;
    $p=[int]$Display.EdidProductId;
    $c=[uint32]$Display.ConnectorInstance
    $key=if(-not[string]::IsNullOrWhiteSpace($path)){
        ('PATH|'+$path.ToUpperInvariant())
    }elseif($valid-and($m-ne0-or$p-ne0)){
        ('EDID|{0:X4}|{1:X4}|CONN|{2}'-f$m,$p,$c)
    }else{
        ''
    }
    return [pscustomobject]@{
        PersistentIdentity=$key;
        DevicePath=$path;
        EdidIdsValid=$valid;
        EdidManufacturerId=$(if($valid){
            $m
        }else{
            0
        });
        EdidProductId=$(if($valid){
            $p
        }else{
            0
        });
        ConnectorInstance=$c;
        RuntimeAdapterLuid=[string]$Display.AdapterLuid;
        RuntimeTargetId=[uint32]$Display.TargetId;
        RuntimeSourceId=[uint32]$Display.SourceId
    }

}

function Resolve-VSO7PersistentDisplayIdentityVSO {

    param([Parameter(Mandatory=$true)]$Identity,[AllowNull()][object[]]$Candidates)
    $items=@($Candidates);
    $path=[string]$Identity.DevicePath
    if(-not[string]::IsNullOrWhiteSpace($path)){
        $m=@($items|Where-Object{
            [string]$_.DevicePath-ieq$path
        });
        if($m.Count-eq1){
            return [pscustomobject]@{
                Status='Resolved';
                Evidence='ExactDevicePath';
                Display=$m[0]
            }
        };
        if($m.Count-gt1){
            return [pscustomobject]@{
                Status='Ambiguous';
                Evidence='DuplicateDevicePath';
                Display=$null
            }
        }
    }
    $edidValid=($Identity.PSObject.Properties.Name-contains'EdidIdsValid'-and[bool]$Identity.EdidIdsValid);
    $man=[int]$Identity.EdidManufacturerId;
    $prod=[int]$Identity.EdidProductId;
    $conn=[uint32]$Identity.ConnectorInstance
    if($edidValid-and($man-ne0-or$prod-ne0)){
        $m=@($items|Where-Object{
            $_.PSObject.Properties.Name-contains'EdidIdsValid'-and[bool]$_.EdidIdsValid-and[int]$_.EdidManufacturerId-eq$man-and[int]$_.EdidProductId-eq$prod-and[uint32]$_.ConnectorInstance-eq$conn
        });
        if($m.Count-eq1){
            return [pscustomobject]@{
                Status='Resolved';
                Evidence='UniqueValidEdidConnector';
                Display=$m[0]
            }
        };
        if($m.Count-gt1){
            return [pscustomobject]@{
                Status='Ambiguous';
                Evidence='EdidConnectorCollision';
                Display=$null
            }
        }
    }
    return [pscustomobject]@{
        Status='Unresolved';
        Evidence='PersistentDisplayIdentityNotFound';
        Display=$null
    }

}

function Get-VSO7AdvancedColorSemanticsVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('Modern','Legacy')][string]$Contract,[Parameter(Mandatory=$true)][uint32]$Flags,[Nullable[uint32]]$ActiveColorMode=$null)
    if($Contract-eq'Modern'){

        $mode=if($null-eq$ActiveColorMode){
            'Unknown'
        }else{
            switch([uint32]$ActiveColorMode){
                0{
                    'SDR'
                }1{
                    'WCG'
                }2{
                    'HDR'
                }default{
                    'Unknown'
                }
            }
        }
        return [pscustomobject]@{
            AdvancedColorSupported=(($Flags-band1)-ne0);
            AdvancedColorActive=(($Flags-band2)-ne0);
            AdvancedColorForceDisabled=$null;
            AdvancedColorLimitedByPolicy=(($Flags-band8)-ne0);
            HdrSupported=(($Flags-band16)-ne0);
            HdrUserEnabled=(($Flags-band32)-ne0);
            HdrActive=$(if($mode-eq'Unknown'){
                $null
            }else{
                $mode-eq'HDR'
            });
            WcgSupported=(($Flags-band64)-ne0);
            WcgUserEnabled=(($Flags-band128)-ne0);
            WcgActive=$(if($mode-eq'Unknown'){
                $null
            }else{
                $mode-eq'WCG'
            });
            ActiveColorMode=$mode
        }

    }
    return [pscustomobject]@{
        AdvancedColorSupported=(($Flags-band1)-ne0);
        AdvancedColorActive=(($Flags-band2)-ne0);
        AdvancedColorForceDisabled=(($Flags-band8)-ne0);
        AdvancedColorLimitedByPolicy=$null;
        HdrSupported=$null;
        HdrUserEnabled=$null;
        HdrActive=$null;
        WcgSupported=$null;
        WcgUserEnabled=$null;
        WcgActive=$null;
        ActiveColorMode='Unknown'
    }

}

function Test-VSO7DisplayPathDrrVSO {

    param([Parameter(Mandatory=$true)][uint32]$QueryFlags,[Parameter(Mandatory=$true)][uint32]$PathFlags)
    if(($QueryFlags-band0x40)-eq0){
        return $null
    }
    return (($PathFlags-band0x10)-ne0)

}

function Get-VSO7DxCoreAdaptersVSO {

    if(-not(Initialize-VSO7GraphicsNativeProbeVSO)){
        return [pscustomobject]@{
            Available=$false;
            Error=[string]$script:VSO7GraphicsNativeTypeError;
            Adapters=@();
            HardwarePreferenceSupported=$false;
            MinimumPowerSupported=$false;
            HighPerformanceSupported=$false
        }
    }
    try{
        return [VsoR9GraphicsNative]::ProbeDxCore()
    }catch{
        return [pscustomobject]@{
            Available=$false;
            Error=$_.Exception.Message;
            Adapters=@();
            HardwarePreferenceSupported=$false;
            MinimumPowerSupported=$false;
            HighPerformanceSupported=$false
        }
    }

}

function Get-VSO7DxgiAdaptersVSO {

    if(-not(Initialize-VSO7GraphicsNativeProbeVSO)){
        return [pscustomobject]@{
            Available=$false;
            Error=[string]$script:VSO7GraphicsNativeTypeError;
            Adapters=@();
            Factory6=$false;
            TearingQueryAvailable=$false;
            TearingSupported=$null
        }
    }
    try{
        return [VsoR9GraphicsNative]::ProbeDxgi()
    }catch{
        return [pscustomobject]@{
            Available=$false;
            Error=$_.Exception.Message;
            Adapters=@();
            Factory6=$false;
            TearingQueryAvailable=$false;
            TearingSupported=$null
        }
    }

}

function Get-VSO7DisplayConfigTargetsVSO {

    if(-not(Initialize-VSO7GraphicsNativeProbeVSO)){
        return [pscustomobject]@{
            Available=$false;
            Error=[string]$script:VSO7GraphicsNativeTypeError;
            Displays=@();
            QueryFlags=0;
            VirtualRefreshAware=$false
        }
    }
    try{
        return [VsoR9GraphicsNative]::ProbeDisplays()
    }catch{
