            VirtualRefreshAware=$false
        }
    }

}

function Get-VSO7GraphicsNativeStateVSO {

    param([switch]$Refresh)
    if(-not$Refresh-and$null-ne$script:VSO7GraphicsNativeStateCache){
        return $script:VSO7GraphicsNativeStateCache
    }
    $dxcore=Get-VSO7DxCoreAdaptersVSO;
    $dxgi=Get-VSO7DxgiAdaptersVSO;
    $display=Get-VSO7DisplayConfigTargetsVSO
    $corr=if([bool]$dxcore.Available-and[bool]$dxgi.Available){
        @(Get-VSO7RuntimeAdapterCorrelationVSO -DxCore @($dxcore.Adapters) -Dxgi @($dxgi.Adapters))
    }else{
        @()
    }
    $pref=if([bool]$dxgi.Available){
        Get-VSO7GraphicsPreferenceMappingVSO -Adapters @($dxgi.Adapters)
    }else{
        [pscustomobject]@{
            MinimumPower=$null;
            HighPerformance=$null;
            MinimumPowerStatus='Unknown';
            HighPerformanceStatus='Unknown';
            Evidence='Native preference probe unavailable'
        }
    }
    $script:VSO7GraphicsNativeStateCache=[pscustomobject]@{
        DxCore=$dxcore;
        Dxgi=$dxgi;
        DisplayConfig=$display;
        AdapterCorrelation=$corr;
        PreferenceMapping=$pref;
        CapturedUtc=[DateTime]::UtcNow.ToString('o');
        IdentityRule='LUID is runtime/session identity only; persistent recovery uses PnP/PCI or monitor path/EDID.'
    }
    return $script:VSO7GraphicsNativeStateCache

}

function Get-VSO7GraphicsCompositeSegmentsVSO {

    param([AllowNull()][string]$Raw)
    $segments=New-Object System.Collections.Generic.List[object]
    if([string]::IsNullOrWhiteSpace([string]$Raw)){
        return @()
    }
    $seen=@{};
    $ordinal=0
    foreach($piece in @(([string]$Raw)-split';')){

        if([string]::IsNullOrWhiteSpace([string]$piece)){
            continue
        }
        $idx=$piece.IndexOf('=')
        if($idx-lt1){
            throw ('Formato UserGpuPreferences no reconocido: {0}'-f$piece)
        }
        $key=$piece.Substring(0,$idx).Trim();
        $value=$piece.Substring($idx+1).Trim()
        if($key-notmatch'^[A-Za-z][A-Za-z0-9_]*$'){
            throw ('Token UserGpuPreferences no reconocido: {0}'-f$key)
        }
        $lower=$key.ToLowerInvariant();
        if($seen.ContainsKey($lower)){
            throw ('Token UserGpuPreferences duplicado: {0}'-f$key)
        };
        $seen[$lower]=$true
        [void]$segments.Add([pscustomobject]@{
            Key=$key;Value=$value;Raw=[string]$piece;Ordinal=$ordinal
        });
        $ordinal++

    }
    return $segments.ToArray()

}

function Get-VSO7GraphicsCompositeTokenStateVSO {

    param([AllowNull()][string]$Raw,[Parameter(Mandatory=$true)][string]$Key)
    $matches=@(Get-VSO7GraphicsCompositeSegmentsVSO -Raw $Raw|Where-Object{
        [string]$_.Key-ieq$Key
    })
    if($matches.Count-eq0){
        return [pscustomobject]@{
            Present=$false;
            Value=$null;
            Raw=$null;
            Key=$Key
        }
    }
    if($matches.Count-ne1){
        throw ('Token grafico ambiguo: {0}'-f$Key)
    }
    return [pscustomobject]@{
        Present=$true;
        Value=[string]$matches[0].Value;
        Raw=[string]$matches[0].Raw;
        Key=[string]$matches[0].Key
    }

}

function Get-VSO7GraphicsCompositeTokenVSO {

    param([AllowNull()][string]$Raw,[Parameter(Mandatory=$true)][string]$Key)
    $state=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $Raw -Key $Key
    if(-not[bool]$state.Present){
        return $null
    }
    return [string]$state.Value

}

function Assert-VSO7GraphicsOwnedTokenSemanticVSO {

    param([AllowNull()][string]$Raw,[Parameter(Mandatory=$true)][ValidateSet('GpuPreference','SwapEffectUpgradeEnable')][string]$Key)
    $state=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $Raw -Key $Key
    if(-not[bool]$state.Present){
        return $state
    }
    if($Key-ieq'GpuPreference' -and @('0','1','2')-notcontains[string]$state.Value){
        throw ('GpuPreference existente no tiene un valor reconocido: {0}'-f$state.Value)
    }
    if($Key-ieq'SwapEffectUpgradeEnable' -and @('0','1')-notcontains[string]$state.Value){
        throw ('SwapEffectUpgradeEnable existente no tiene un valor reconocido: {0}'-f$state.Value)
    }
    return $state

}

function Test-VSO7GraphicsTokenStateEqualVSO {

    param([Parameter(Mandatory=$true)]$A,[Parameter(Mandatory=$true)]$B)
    if([bool]$A.Present-ne[bool]$B.Present){
        return $false
    }
    if(-not[bool]$A.Present){
        return $true
    }
    return ([string]$A.Value-ceq[string]$B.Value)

}

function Get-VSO7GraphicsUpdatedCompositeVSO {

    param([AllowNull()][string]$Raw,[Parameter(Mandatory=$true)][string]$Key,[AllowNull()][string]$Value,[switch]$Remove)
    if($Key-notmatch'^[A-Za-z][A-Za-z0-9_]*$'){
        throw 'Clave de token grafico invalida.'
    }
    $segments=@(Get-VSO7GraphicsCompositeSegmentsVSO -Raw $Raw);
    $out=New-Object System.Collections.Generic.List[string];
    $found=$false
    foreach($seg in $segments){

        if([string]$seg.Key-ieq$Key){
            $found=$true;
            if(-not$Remove){
                [void]$out.Add(('{0}={1}'-f$seg.Key,[string]$Value))
            }
        }
        else{
            [void]$out.Add([string]$seg.Raw)
        }

    }
    if(-not$found-and-not$Remove){
        [void]$out.Add(('{0}={1}'-f$Key,[string]$Value))
    }
    if($out.Count-eq0){
        return ''
    }
    return (($out.ToArray()-join';')+';')

}

function Get-VSO7GraphicsRollbackCompositeVSO {

    param([AllowNull()][string]$BaselineRaw,[AllowNull()][string]$CurrentRaw,[Parameter(Mandatory=$true)][string]$TokenKey)
    $baseline=@(Get-VSO7GraphicsCompositeSegmentsVSO -Raw $BaselineRaw)
    $current=@(Get-VSO7GraphicsCompositeSegmentsVSO -Raw $CurrentRaw)
    $baseOwned=@($baseline|Where-Object{
        [string]$_.Key-ieq$TokenKey
    })
    if($baseOwned.Count-gt1){
        throw 'Baseline GraphicsComposite ambiguo.'
    }
    $out=New-Object System.Collections.Generic.List[string];
    $found=$false
    foreach($seg in $current){

        if([string]$seg.Key-ieq$TokenKey){

            $found=$true
            if($baseOwned.Count-eq1){
                [void]$out.Add([string]$baseOwned[0].Raw)
            }

        }else{
            [void]$out.Add([string]$seg.Raw)
        }

    }
    if(-not$found-and$baseOwned.Count-eq1){
        [void]$out.Add([string]$baseOwned[0].Raw)
    }
    if($out.Count-eq0){
        return ''
    }
    return (($out.ToArray()-join';')+';')

}

function Invoke-VSO7GraphicsCompositeTokenOperationVSO {

    param(
        [Parameter(Mandatory=$true)]$Session,
        [Parameter(Mandatory=$true)][string]$ValueName,
        [Parameter(Mandatory=$true)][ValidateSet('GpuPreference','SwapEffectUpgradeEnable')][string]$TokenKey,
        [AllowNull()][string]$TokenValue,
        [switch]$Remove,
        [switch]$BlockWhenAutoHdrTokenPresent
    )
    $path=$script:VSO7GraphicsUserPreferencePath
    $before=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name $ValueName
    if([bool]$before.Exists-and[string]$before.Kind-notin@('String','ExpandString')){
        throw ('UserGpuPreferences tiene tipo inesperado para {0}: {1}'-f$ValueName,$before.Kind)
    }
    $raw=if([bool]$before.Exists){
        [string]$before.Value
    }else{
        ''
    }
    [void](Get-VSO7GraphicsCompositeSegmentsVSO -Raw $raw)
    $baselineOwned=Assert-VSO7GraphicsOwnedTokenSemanticVSO -Raw $raw -Key $TokenKey
    if(-not$Remove){

        if($TokenKey-ieq'GpuPreference' -and @('1','2')-notcontains[string]$TokenValue){
            throw 'GpuPreference solicitada no es valida.'
        }
        if($TokenKey-ieq'SwapEffectUpgradeEnable' -and @('0','1')-notcontains[string]$TokenValue){
            throw 'SwapEffectUpgradeEnable solicitado no es valido.'
        }

    }
    if($BlockWhenAutoHdrTokenPresent){

        $auto=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $raw -Key 'AutoHDREnable'
        if([bool]$auto.Present){
            throw 'VSO7 detecto un override Auto HDR en el mismo objeto. R44 no escribe ni interpreta sus valores opacos: desactiva/resetee Auto HDR desde Configuracion antes de forzar este override.'
        }

    }
    $updated=Get-VSO7GraphicsUpdatedCompositeVSO -Raw $raw -Key $TokenKey -Value $TokenValue -Remove:$Remove
    if($updated-ceq$raw){
        return $null
    }
    if([string]::IsNullOrEmpty($updated)){
        $op=[pscustomobject]@{
            Action='DeleteValue';
            Path=$path;
            Name=$ValueName
        }
    }
    else{
        $writeKind=if([bool]$before.Exists){
            [string]$before.Kind
        }else{
            'String'
        };
        $op=[pscustomobject]@{
            Action='SetValue';
            Path=$path;
            Name=$ValueName;
            Kind=$writeKind;
            Value=$updated
        }
    }
    Invoke-VSO7NativeRegistryOperationVSO -Session $Session -Operation $op -JournalMetadata @{
        Primitive='GraphicsCompositeToken';
        TokenKey=$TokenKey;
        BaselineOwnedTokenPresent=[bool]$baselineOwned.Present;
        BaselineOwnedTokenValue=$baselineOwned.Value
    }
    $key=($path.ToLowerInvariant()+'|'+$ValueName.ToLowerInvariant());
    $entry=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($entry.Count-eq1){

        $appliedOwned=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $updated -Key $TokenKey
        $entry[0]|Add-Member -NotePropertyName Primitive -NotePropertyValue 'GraphicsCompositeToken' -Force
        $entry[0]|Add-Member -NotePropertyName TokenKey -NotePropertyValue $TokenKey -Force
        $entry[0]|Add-Member -NotePropertyName BaselineOwnedTokenPresent -NotePropertyValue ([bool]$baselineOwned.Present) -Force
        $entry[0]|Add-Member -NotePropertyName BaselineOwnedTokenValue -NotePropertyValue $baselineOwned.Value -Force
        $entry[0]|Add-Member -NotePropertyName AppliedOwnedTokenPresent -NotePropertyValue ([bool]$appliedOwned.Present) -Force
        $entry[0]|Add-Member -NotePropertyName AppliedOwnedTokenValue -NotePropertyValue $appliedOwned.Value -Force
        $entry[0]|Add-Member -NotePropertyName ConfigurationVerification -NotePropertyValue 'PASS' -Force
        $entry[0]|Add-Member -NotePropertyName EffectiveVerification -NotePropertyValue 'PendingAppRestart' -Force
        $entry[0]|Add-Member -NotePropertyName EffectiveState -NotePropertyValue 'PendingAppRestart' -Force
        $entry[0]|Add-Member -NotePropertyName RestartRequirement -NotePropertyValue 'AppRestart' -Force
        Save-VSO7NativeBackupSessionVSO -Session $Session
        return $entry[0]

    }
    return $null

}

function Restore-VSO7GraphicsCompositeEntryVSO {
    param([Parameter(Mandatory=$true)]$Entry)
    if([string]::IsNullOrWhiteSpace([string]$Entry.TokenKey)){throw 'GraphicsComposite recovery no contiene TokenKey.'}
    $tokenKey=[string]$Entry.TokenKey
    $current=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)
    $baseline=[pscustomobject]@{Exists=[bool]$Entry.Exists;Kind=$Entry.Kind;Value=$Entry.Value}
    $intended=[pscustomobject]@{Exists=[bool]$Entry.IntendedExists;Kind=$Entry.IntendedKind;Value=$Entry.IntendedValue}
    $applied=[pscustomobject]@{Exists=[bool]$Entry.AppliedExists;Kind=$Entry.AppliedKind;Value=$Entry.AppliedValue}
    if(Test-VSO7NativeRegistrySnapshotEqualVSO -A $current -B $baseline){return $true}
    $reference=if([string]$Entry.Status-ceq'Pending'){$intended}else{$applied}
    if([bool]$current.Exists-and[string]$current.Kind-notin@('String','ExpandString')){throw 'GraphicsComposite cambio a un Registry kind no seguro; rollback fail-closed.'}
    if([bool]$reference.Exists-and[string]$reference.Kind-notin@('String','ExpandString')){throw 'GraphicsComposite ownership reference no tiene un Registry kind recuperable.'}
    if([bool]$current.Exists-and[bool]$reference.Exists-and[string]$current.Kind-cne[string]$reference.Kind){throw 'GraphicsComposite Registry kind presenta drift externo.'}
    $baselineRaw=if([bool]$baseline.Exists){[string]$baseline.Value}else{''}
    $referenceRaw=if([bool]$reference.Exists){[string]$reference.Value}else{''}
    $currentRaw=if([bool]$current.Exists){[string]$current.Value}else{''}
    $baselineOwned=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $baselineRaw -Key $tokenKey
    $referenceOwned=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $referenceRaw -Key $tokenKey
    $currentOwned=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $currentRaw -Key $tokenKey
    if(Test-VSO7GraphicsTokenStateEqualVSO -A $currentOwned -B $baselineOwned){return $true}
    if(-not(Test-VSO7GraphicsTokenStateEqualVSO -A $currentOwned -B $referenceOwned)){throw ('GraphicsComposite token {0} presenta drift externo; VSO7 no lo sobrescribe.'-f$tokenKey)}
    # If the full value is still exactly the Pending intention / Applied value, restore the exact baseline.
    # Otherwise an unrelated token changed; restore only the token owned by VSO7.
    if(Test-VSO7NativeRegistrySnapshotEqualVSO -A $current -B $reference){
        if([bool]$baseline.Exists){Set-VSO7NativeRegistryValueRawVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name) -Kind ([string]$baseline.Kind) -Value $baseline.Value}else{Remove-VSO7NativeRegistryValueRawVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)}
        $after=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)
        if(-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $after -B $baseline)){throw 'Rollback GraphicsComposite exacto no coincidio con baseline.'}
        return $true
    }
    $merged=Get-VSO7GraphicsRollbackCompositeVSO -BaselineRaw $baselineRaw -CurrentRaw $currentRaw -TokenKey $tokenKey
    if([string]::IsNullOrEmpty($merged)){
        Remove-VSO7NativeRegistryValueRawVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name);$expected=[pscustomobject]@{Exists=$false;Kind=$null;Value=$null}
    }else{
        $kind=if([bool]$current.Exists){[string]$current.Kind}elseif([bool]$baseline.Exists){[string]$baseline.Kind}else{'String'}
        Set-VSO7NativeRegistryValueRawVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name) -Kind $kind -Value $merged;$expected=[pscustomobject]@{Exists=$true;Kind=$kind;Value=$merged}
    }
    $after=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)
    if(-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $after -B $expected)){throw 'Rollback GraphicsComposite merge-safe no coincidio con el resultado esperado.'}
    $afterRaw=if([bool]$after.Exists){[string]$after.Value}else{''};$afterOwned=Get-VSO7GraphicsCompositeTokenStateVSO -Raw $afterRaw -Key $tokenKey
    if(-not(Test-VSO7GraphicsTokenStateEqualVSO -A $afterOwned -B $baselineOwned)){throw 'Rollback GraphicsComposite no restauro el token poseido.'}
    return $true
}

function Get-VSO7HagsAdapterStateFromDxDiagLineVSO {

    param([Parameter(Mandatory=$true)][string]$Line,[int]$Index=0,[AllowNull()][string]$Name,[AllowNull()][string]$DeviceIdentity,[AllowNull()][string]$DriverVersion)
    $state='Unknown';
    $enabled=$null;
    $format='Unknown'
    $m=[regex]::Match($Line,'(?i)Supported\s*:\s*(True|False).*Enabled\s*:\s*(True|False)')
    if($m.Success){

        $format='Legacy';
        $state=if($m.Groups[1].Value-ieq'True'){
            'Stable'
        }else{
            'AlwaysOff'
        };
        $enabled=($m.Groups[2].Value-ieq'True')

    }else{

        $m=[regex]::Match($Line,'(?i)DriverSupportState\s*:\s*([A-Za-z]+).*Enabled\s*:\s*(True|False)')
        if($m.Success){
            $format='Modern';
            $rawState=$m.Groups[1].Value;
            if($rawState-ieq'Stable'){
                $state='Stable'
            }elseif($rawState-ieq'AlwaysOff'){
                $state='AlwaysOff'
            }elseif($rawState-ieq'Experimental'){
                $state='Experimental'
            }else{
                $state='Unknown'
            };
            $enabled=($m.Groups[2].Value-ieq'True')
        }

    }
    return [pscustomobject]@{
        Index=$Index;
        Name=[string]$Name;
        DeviceIdentity=[string]$DeviceIdentity;
        DriverVersion=[string]$DriverVersion;
        SupportState=$state;
        Enabled=$enabled;
        Format=$format;
        Raw=[string]$Line
    }

}

function Get-VSO7HagsAggregateFromAdapterStatesVSO {

    param([AllowNull()][object[]]$Adapters)
    $items=@($Adapters|Where-Object{
        $null-ne$_
    });
    if($items.Count-eq0){
        return [pscustomobject]@{
            Verified=$false;
            Supported=$false;
            Mutable=$false;
            Enabled=$null;
            AggregateState='Unknown';
            Adapters=@();
            Reason='dxdiag did not expose Hardware Scheduling in a recognized format.'
        }
    }
    $stable=@($items|Where-Object{
        [string]$_.SupportState-ceq'Stable'
    });
    $experimental=@($items|Where-Object{
        [string]$_.SupportState-ceq'Experimental'
    });
    $unknown=@($items|Where-Object{
        [string]$_.SupportState-ceq'Unknown'
    });
    $alwaysOff=@($items|Where-Object{
        [string]$_.SupportState-ceq'AlwaysOff'
    })
    if($experimental.Count-gt0-or$unknown.Count-gt0){
        return [pscustomobject]@{
            Verified=$false;
            Supported=($stable.Count-gt0);
            Mutable=$false;
            Enabled=$null;
            AggregateState='Ambiguous';
            Adapters=$items;
            Reason='dxdiag includes Experimental/Unknown HAGS adapter state; mutation fails closed.'
        }
    }
    if($stable.Count-eq0){

        if($alwaysOff.Count-eq$items.Count){
            return [pscustomobject]@{
                Verified=$true;
                Supported=$false;
                Mutable=$false;
                Enabled=$false;
                AggregateState='AlwaysOff';
                Adapters=$items;
                Reason='All observed adapters report AlwaysOff.'
            }
        }
        return [pscustomobject]@{
            Verified=$false;
            Supported=$false;
            Mutable=$false;
            Enabled=$null;
            AggregateState='Unknown';
            Adapters=$items;
            Reason='HAGS support could not be aggregated safely.'
        }

    }
    $stableEnabled=@($stable|Where-Object{
        $_.Enabled-eq$true
    });
    $stableDisabled=@($stable|Where-Object{
        $_.Enabled-eq$false
    })
    if($stableEnabled.Count-gt0-and$stableDisabled.Count-gt0){
        return [pscustomobject]@{
            Verified=$true;
            Supported=$true;
            Mutable=$false;
            Enabled=$null;
            AggregateState='Ambiguous';
            Adapters=$items;
            Reason='Stable HAGS adapters disagree on effective Enabled state.'
        }
    }
    if($stableEnabled.Count-eq$stable.Count){
        return [pscustomobject]@{
            Verified=$true;
            Supported=$true;
            Mutable=$true;
            Enabled=$true;
            AggregateState='Enabled';
            Adapters=$items;
            Reason=''
        }
    }
    if($stableDisabled.Count-eq$stable.Count){
        return [pscustomobject]@{
            Verified=$true;
            Supported=$true;
            Mutable=$true;
            Enabled=$false;
            AggregateState='Disabled';
            Adapters=$items;
            Reason=''
        }
    }
    return [pscustomobject]@{
        Verified=$false;
        Supported=$true;
        Mutable=$false;
        Enabled=$null;
        AggregateState='Ambiguous';
        Adapters=$items;
        Reason='Stable HAGS adapter state is incomplete.'
    }

}

function Get-VSO7HagsStateFromDxDiagLinesVSO {

    param([AllowNull()][string[]]$Lines)
    $states=New-Object System.Collections.Generic.List[object];
    $i=0
    foreach($line in @($Lines|Where-Object{
        $null-ne$_-and-not[string]::IsNullOrWhiteSpace([string]$_)
    })){
        [void]$states.Add((Get-VSO7HagsAdapterStateFromDxDiagLineVSO -Line ([string]$line) -Index $i));
        $i++
    }
    return Get-VSO7HagsAggregateFromAdapterStatesVSO -Adapters $states.ToArray()

}

function Get-VSO7DxDiagHagsAdapterStatesVSO {

    param([Parameter(Mandatory=$true)][string]$Text)
    $states=New-Object System.Collections.Generic.List[object];
    $i=0
    $blocks=@([regex]::Matches($Text,'(?ims)^\s*Card name\s*:\s*(?<name>[^\r\n]+)(?<body>.*?)(?=^\s*Card name\s*:|\z)'))
    foreach($block in $blocks){

        $body=[string]$block.Groups['body'].Value;
        $hm=[regex]::Match($body,'(?im)^\s*Hardware Scheduling\s*:\s*(?<value>[^\r\n]+)')
        if(-not$hm.Success){
            continue
        }
        $device=[regex]::Match($body,'(?im)^\s*(?:Device Key|Device Id)\s*:\s*(?<value>[^\r\n]+)');
        $driver=[regex]::Match($body,'(?im)^\s*Driver Version\s*:\s*(?<value>[^\r\n]+)')
        [void]$states.Add((Get-VSO7HagsAdapterStateFromDxDiagLineVSO -Line $hm.Groups['value'].Value.Trim() -Index $i -Name $block.Groups['name'].Value.Trim() -DeviceIdentity $(if($device.Success){
            $device.Groups['value'].Value.Trim()
        }else{
            ''
        }) -DriverVersion $(if($driver.Success){
            $driver.Groups['value'].Value.Trim()
        }else{
            ''
        })));
        $i++

    }
    if($states.Count-eq0){
        foreach($m in @([regex]::Matches($Text,'(?im)^\s*Hardware Scheduling\s*:\s*([^\r\n]+)'))){
            [void]$states.Add((Get-VSO7HagsAdapterStateFromDxDiagLineVSO -Line $m.Groups[1].Value.Trim() -Index $i));
            $i++
        }
    }
    return $states.ToArray()

}

function Get-VSO7DxDiagGraphicsStateVSO {

    param([switch]$Refresh)
    if(-not$Refresh-and$null-ne$script:VSO7GraphicsDiagnosticsCache){
        return $script:VSO7GraphicsDiagnosticsCache
    }
    $result=[ordered]@{
        Verified=$false;
        HagsSupported=$false;
        HagsMutable=$false;
        HagsEnabled=$null;
        HagsAggregateState='Unknown';
        HagsAdapters=@();
        HardwareSchedulingLines=@();
        HybridLines=@();
        MpoLines=@();
        HdrLines=@();
        RawAvailable=$false;
        Reason=''
    }
    try{

        $dxdiag=Resolve-VSOSystemExecutable -Name 'dxdiag.exe'
        $temp=Join-Path ([IO.Path]::GetTempPath()) ('VSO7_dxdiag_'+[guid]::NewGuid().ToString('N')+'.txt')
        try{

            $psi=New-Object Diagnostics.ProcessStartInfo
            $psi.FileName=$dxdiag;
            $psi.UseShellExecute=$false;
            $psi.CreateNoWindow=$true;
            $psi.Arguments=('/dontskip /whql:off /t "{0}"'-f$temp)
            $p=New-Object Diagnostics.Process;
            $p.StartInfo=$psi
            try{
                if(-not$p.Start()){
                    throw 'No se pudo iniciar dxdiag.'
                };
                if(-not$p.WaitForExit(20000)){
                    try{
                        $p.Kill()
                    }catch{};
                    throw 'dxdiag excedio 20 segundos.'
                }
            }finally{
                $p.Dispose()
            }
            for($i=0;$i-lt20-and-not(Test-Path -LiteralPath $temp -PathType Leaf);$i++){
                Start-Sleep -Milliseconds 150
            }
            if(-not(Test-Path -LiteralPath $temp -PathType Leaf)){
                throw 'dxdiag no genero el informe.'
            }
            $text=[IO.File]::ReadAllText($temp);
            $result.RawAvailable=$true
            $result.HardwareSchedulingLines=@([regex]::Matches($text,'(?im)^\s*Hardware Scheduling\s*:\s*([^\r\n]+)')|ForEach-Object{
                $_.Groups[1].Value.Trim()
            })
            $result.HagsAdapters=@(Get-VSO7DxDiagHagsAdapterStatesVSO -Text $text)
            $hagsParsed=Get-VSO7HagsAggregateFromAdapterStatesVSO -Adapters $result.HagsAdapters
            $result.Verified=[bool]$hagsParsed.Verified;
            $result.HagsSupported=[bool]$hagsParsed.Supported;
            $result.HagsMutable=[bool]$hagsParsed.Mutable;
            $result.HagsEnabled=$hagsParsed.Enabled;
            $result.HagsAggregateState=[string]$hagsParsed.AggregateState;
            $result.Reason=[string]$hagsParsed.Reason
            $result.HybridLines=@([regex]::Matches($text,'(?im)^\s*Hybrid Graphics GPU\s*:\s*([^\r\n]+)')|ForEach-Object{
                $_.Groups[1].Value.Trim()
            })
            $result.MpoLines=@([regex]::Matches($text,'(?im)^\s*MPO (?:MaxPlanes|Caps)\s*:\s*([^\r\n]+)')|ForEach-Object{
                $_.Value.Trim()
            })
            $result.HdrLines=@([regex]::Matches($text,'(?im)^\s*(?:HDR Support|Advanced Color|Active Color Mode)\s*:\s*([^\r\n]+)')|ForEach-Object{
                $_.Value.Trim()
            })
            if(-not$result.Verified-and[string]::IsNullOrWhiteSpace([string]$result.Reason)){
                $result.Reason='dxdiag estaba disponible, pero su salida no expuso Hardware Scheduling en un formato verificable.'
            }

        }finally{
            if(-not[string]::IsNullOrWhiteSpace([string]$temp)-and(Test-Path -LiteralPath $temp)){
                Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
            }
        }

    }catch{
        $result.Reason=$_.Exception.Message
    }
    $script:VSO7GraphicsDiagnosticsCache=[pscustomobject]$result
    return $script:VSO7GraphicsDiagnosticsCache

}

function Get-VSO7HagsStateVSO {

    param([switch]$Refresh)
    $d=Get-VSO7DxDiagGraphicsStateVSO -Refresh:$Refresh
    return [pscustomobject]@{
        Verified=[bool]$d.Verified;
        Supported=[bool]$d.HagsSupported;
        Mutable=[bool]$d.HagsMutable;
        Enabled=$d.HagsEnabled;
        AggregateState=[string]$d.HagsAggregateState;
        Adapters=@($d.HagsAdapters);
        Source='dxdiag';
        Reason=[string]$d.Reason
    }

}

function Invoke-VSO7HagsOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][bool]$Enable)
    $before=Get-VSO7HagsStateVSO -Refresh
    if(-not[bool]$before.Verified){
        throw ('No se puede verificar HAGS: {0}'-f$before.Reason)
    }
    if(-not[bool]$before.Supported){
        throw 'HAGS no esta soportado por la GPU/controlador detectado.'
    }
    if(-not[bool]$before.Mutable-or$null-eq$before.Enabled){
        throw ('HAGS multi-GPU es ambiguo/no mutable: {0}'-f$before.Reason)
    }
    $desired=if($Enable){
        2
    }else{
        1
    }
    $path='HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
    $op=[pscustomobject]@{
        Action='SetValue';
        Path=$path;
        Name='HwSchMode';
        Kind='DWord';
        Value=$desired
    }
    Invoke-VSO7NativeRegistryOperationVSO -Session $Session -Operation $op -JournalMetadata @{
        Primitive='HAGS';
        SupportVerified=$true;
        HagsAggregateBefore=[string]$before.AggregateState;
        HagsAdaptersBefore=@($before.Adapters);
        EffectiveBefore=$before.Enabled;
        EffectiveDesired=[bool]$Enable
    }
    $key=($path.ToLowerInvariant()+'|'+'HwSchMode'.ToLowerInvariant());
    $entry=@($Session.Entries|Where-Object{
        [string]$_.Key-eq$key
    }|Select-Object -First 1)
    if($entry.Count-eq1){

        $entry[0]|Add-Member -NotePropertyName Primitive -NotePropertyValue 'HAGS' -Force
        $entry[0]|Add-Member -NotePropertyName SupportVerified -NotePropertyValue $true -Force
        $entry[0]|Add-Member -NotePropertyName HagsAggregateBefore -NotePropertyValue ([string]$before.AggregateState) -Force
        $entry[0]|Add-Member -NotePropertyName HagsAdaptersBefore -NotePropertyValue @($before.Adapters) -Force
        $entry[0]|Add-Member -NotePropertyName EffectiveBefore -NotePropertyValue $before.Enabled -Force
        $entry[0]|Add-Member -NotePropertyName EffectiveDesired -NotePropertyValue ([bool]$Enable) -Force
        $entry[0]|Add-Member -NotePropertyName ConfigurationVerification -NotePropertyValue 'PASS' -Force
        $entry[0]|Add-Member -NotePropertyName EffectiveVerification -NotePropertyValue 'PendingReboot' -Force
        $entry[0]|Add-Member -NotePropertyName EffectiveState -NotePropertyValue 'PendingReboot' -Force
        $entry[0]|Add-Member -NotePropertyName RestartRequirement -NotePropertyValue 'SystemRestart' -Force
        $entry[0]|Add-Member -NotePropertyName RebootRequired -NotePropertyValue $true -Force
        Save-VSO7NativeBackupSessionVSO -Session $Session

    }
    return $true

}

function Invoke-VSO7GraphicsGlobalWindowedOperationVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][bool]$Enable)
    $value=if($Enable){
        '1'
    }else{
        '0'
    }
    [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $Session -ValueName 'DirectXUserGlobalSettings' -TokenKey 'SwapEffectUpgradeEnable' -TokenValue $value -BlockWhenAutoHdrTokenPresent:(!$Enable))
    return $true

}

function Get-VSO7PciIdentityPartsVSO {

    param([AllowNull()][string]$PnpDeviceId)
    $ven=$null;
    $dev=$null;
    $subsys=$null;
    $id=[string]$PnpDeviceId
    $m=[regex]::Match($id,'(?i)VEN_([0-9A-F]{4})');
    if($m.Success){
        $ven=$m.Groups[1].Value.ToUpperInvariant()
    }
    $m=[regex]::Match($id,'(?i)DEV_([0-9A-F]{4})');
    if($m.Success){
        $dev=$m.Groups[1].Value.ToUpperInvariant()
    }
    $m=[regex]::Match($id,'(?i)SUBSYS_([0-9A-F]{8})');
    if($m.Success){
        $subsys=$m.Groups[1].Value.ToUpperInvariant()
    }
    return [pscustomobject]@{
        VendorId=$ven;
        DeviceId=$dev;
        SubsystemId=$subsys
    }

}

function Get-VSO7GpuAdapterCorrelationVSO {

    param([AllowNull()][object[]]$Adapters,[AllowNull()][object[]]$DxDiagAdapters)
    $adapterItems=@($Adapters|Where-Object{
        $null-ne$_
    });
    $dxDiagItems=@($DxDiagAdapters|Where-Object{
        $null-ne$_
    })
    $out=New-Object System.Collections.Generic.List[object]
    foreach($gpu in $adapterItems){

        $pci=Get-VSO7PciIdentityPartsVSO -PnpDeviceId ([string]$gpu.PNPDeviceID)
        $matches=@();
        $evidence='Unresolved'
        if(-not[string]::IsNullOrWhiteSpace([string]$pci.VendorId)-and-not[string]::IsNullOrWhiteSpace([string]$pci.DeviceId)){

            $matches=@($dxDiagItems|Where-Object{

                $dp=Get-VSO7PciIdentityPartsVSO -PnpDeviceId ([string]$_.DeviceIdentity)
                [string]$dp.VendorId-ceq[string]$pci.VendorId-and[string]$dp.DeviceId-ceq[string]$pci.DeviceId

            })
            if($matches.Count-eq1){
                $evidence='PCI VEN/DEV'
            }

        }
        if($matches.Count-ne1-and-not[string]::IsNullOrWhiteSpace([string]$gpu.Name)){

            $nameMatches=@($dxDiagItems|Where-Object{
                [string]$_.Name-ceq[string]$gpu.Name
            })
            if($nameMatches.Count-eq1){
                $matches=$nameMatches;
                $evidence='Exact unique name'
            }else{
                $matches=@()
            }

        }
        $dx=if($matches.Count-eq1){
            $matches[0]
        }else{
            $null
        }
        [void]$out.Add([pscustomobject]@{

            PNPDeviceID=[string]$gpu.PNPDeviceID;Vendor=[string]$gpu.Vendor;VendorId=[string]$pci.VendorId;DeviceId=[string]$pci.DeviceId;SubsystemId=[string]$pci.SubsystemId
            Description=[string]$gpu.Name;DriverVersion=[string]$gpu.DriverVersion;DxDiagCorrelated=($null-ne$dx);CorrelationEvidence=$evidence
            DxDiagIndex=$(if($null-ne$dx){
                $dx.Index
            }else{
                $null
            });DxDiagName=$(if($null-ne$dx){
                [string]$dx.Name
            }else{
                ''
            });DxDiagDeviceIdentity=$(if($null-ne$dx){
                [string]$dx.DeviceIdentity
            }else{
                ''
            });DxDiagDriverVersion=$(if($null-ne$dx){
                [string]$dx.DriverVersion
            }else{
                ''
            })

        })

    }
    return $out.ToArray()

}

function Get-VSO7GpuTopologyVSO {

    param([AllowNull()][object[]]$Adapters,[AllowNull()][object[]]$NativeAdapters)
    $items=@($Adapters|Where-Object{
        $null-ne$_
    });
    $hardware=@($items|Where-Object{
        [string]$_.PNPDeviceID-match'(?i)^PCI\\VEN_[0-9A-F]{4}&DEV_[0-9A-F]{4}'
    });
    $other=@($items|Where-Object{
        $hardware-notcontains$_
    })
    $vendors=@($hardware|ForEach-Object{
        [string]$_.Vendor
    }|Where-Object{
        $_-ne'Unknown'
    }|Sort-Object -Unique)
    $nativeHardware=@($NativeAdapters|Where-Object{
        $null-ne$_-and($_.PSObject.Properties.Name-notcontains'IsHardware'-or$null-eq$_.IsHardware-or[bool]$_.IsHardware)-and-not[bool]$_.Software
    })
    $integrated=@($nativeHardware|Where-Object{
        $_.PSObject.Properties.Name-contains'IsIntegrated'-and$_.IsIntegrated-eq$true
    })
    $discrete=@($nativeHardware|Where-Object{
        $_.PSObject.Properties.Name-contains'IsIntegrated'-and$_.IsIntegrated-eq$false
    })
    if($nativeHardware.Count-gt0){

        $class=if($nativeHardware.Count-eq1){
            'SingleHardwareGpu'
        }elseif($integrated.Count-gt0-and$discrete.Count-gt0){
            'HybridIntegratedDiscrete'
        }elseif($integrated.Count-eq0-and$discrete.Count-eq$nativeHardware.Count){
            'MultipleDiscrete'
        }else{
            'MultiGpuUnresolvedType'
        }
        $hybrid=if($class-eq'HybridIntegratedDiscrete'){
            $true
        }elseif($class-in@('SingleHardwareGpu','MultipleDiscrete')){
            $false
        }else{
            $null
        }
        return [pscustomobject]@{
            Class=$class;
            HardwareAdapterCount=$nativeHardware.Count;
            OtherAdapterCount=$other.Count;
            OtherAdapterNames=@($other|ForEach-Object{
                [string]$_.Name
            });
            Vendors=$vendors;
            HybridClassification=$class;
            LikelyHybrid=$hybrid;
            PowerSavingAdapter='Unknown';
            HighPerformanceAdapter='Unknown';
            MappingEvidence='DXCore IsIntegrated/IsHardware evidence; preference mapping is reported separately when proven'
        }

    }
    $class=if($hardware.Count-eq0){
        'UnknownOrSoftwareOnly'
    }elseif($hardware.Count-eq1){
        'SingleHardwareGpu'
    }elseif($vendors.Count-gt1){
        'MultiVendorHardware'
    }else{
        'MultiAdapterSameVendor'
    }
    return [pscustomobject]@{
        Class=$class;
        HardwareAdapterCount=$hardware.Count;
        OtherAdapterCount=$other.Count;
        OtherAdapterNames=@($other|ForEach-Object{
            [string]$_.Name
        });
        Vendors=$vendors;
        HybridClassification='UnknownUntilSupportedIntegratedGpuProbe';
        LikelyHybrid=$null;
        PowerSavingAdapter='Unknown';
        HighPerformanceAdapter='Unknown';
        MappingEvidence='Native integrated/discrete evidence not available in this call'
    }

}

function Get-VSO7GraphicsExecutablePathVSO {

    param([Parameter(Mandatory=$true)][string]$InputPath)
    $candidate=$InputPath.Trim().Trim('"')
    if([string]::IsNullOrWhiteSpace($candidate)){
        throw 'La ruta del ejecutable esta vacia.'
    }
    $expanded=[Environment]::ExpandEnvironmentVariables($candidate)
    if(-not[IO.Path]::IsPathRooted($expanded)){
        throw 'La preferencia por aplicacion requiere una ruta absoluta.'
    }
    $full=[IO.Path]::GetFullPath($expanded)
    if([IO.Path]::GetExtension($full)-ine'.exe'){
        throw 'La preferencia por aplicacion solo acepta un .exe.'
    }
    if(-not(Test-Path -LiteralPath $full -PathType Leaf)){
        throw 'El ejecutable no existe.'
    }
    [void](Assert-VSO7LocalPathChainNoReparseVSO -Path $full)
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'VSO7 no escribe preferencias sobre un ejecutable que sea reparse point.'
    }
    return [IO.Path]::GetFullPath([string]$item.FullName)

}

function Select-VSO7GraphicsExecutableVSO {

    if($script:GuiMode){

        $dialog=New-Object Microsoft.Win32.OpenFileDialog;
        $dialog.Filter='Executable (*.exe)|*.exe';
        $dialog.CheckFileExists=$true;
        $dialog.Multiselect=$false
        if($dialog.ShowDialog()-ne$true){
            return $null
        };
        return [string]$dialog.FileName

    }
    return Read-CenteredPromptVSO -Text $(if($script:Language-eq'en'){
        'EXE path (0 = back)'
    }else{
        'Ruta del EXE (0 = volver)'
    })

}

function Invoke-VSO7PerAppGraphicsChoiceVSO {

    param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][ValidateSet('GpuWindows','GpuSaving','GpuHigh','WindowedOn','WindowedOff','ResetGpu','ResetWindowed')][string]$Choice)
    $exe=Get-VSO7GraphicsExecutablePathVSO -InputPath $Executable
    [void](Assert-VSO7PerAppGraphicsOwnershipAvailableVSO -Executable $exe)
    $session=New-VSO7NativeBackupSessionVSO -Features @('V7GP-PERAPP')
    try{

        switch($Choice){

            'GpuWindows' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'GpuPreference' -Remove)
            }
            'GpuSaving' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'GpuPreference' -TokenValue '1')
            }
            'GpuHigh' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'GpuPreference' -TokenValue '2')
            }
            'WindowedOn' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'SwapEffectUpgradeEnable' -TokenValue '1')
            }
            'WindowedOff' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'SwapEffectUpgradeEnable' -TokenValue '0' -BlockWhenAutoHdrTokenPresent)
            }
            'ResetGpu' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'GpuPreference' -Remove)
            }
            'ResetWindowed' {
                [void](Invoke-VSO7GraphicsCompositeTokenOperationVSO -Session $session -ValueName $exe -TokenKey 'SwapEffectUpgradeEnable' -Remove)
            }

        }
        $session.Status='Applied';
        Save-VSO7NativeBackupSessionVSO -Session $session;
        return $true

    }catch{
        $session.Status='Partial';
        try{
            Save-VSO7NativeBackupSessionVSO -Session $session
        }catch{};
        throw
    }

}

function Show-VSO7GraphicsDiagnosticsVSO {

    $isEn=($script:Language-eq'en');
    Write-Title;
    Write-CenteredLineVSO -Text $(if($isEn){
        'GRAPHICS / GPU DIAGNOSTICS - R44'
    }else{
        'DIAGNOSTICO GRAFICO / GPU - R44'
    }) -Color $script:ThemeCopper;
    Write-VSOHost ''
    $ctx=Get-VSO7ApplicabilityContextVSO
    $native=Get-VSO7GraphicsNativeStateVSO -Refresh
    $nativeAdapters=if([bool]$native.DxCore.Available){
        @($native.DxCore.Adapters)
    }elseif([bool]$native.Dxgi.Available){
        @($native.Dxgi.Adapters)
    }else{
        @()
    }
    $topology=Get-VSO7GpuTopologyVSO -Adapters @($ctx.GpuAdapters) -NativeAdapters $nativeAdapters
    Write-VSOHost $(if($isEn){
        'Persistent GPU inventory:'
    }else{
        'Inventario GPU persistente:'
    }) -ForegroundColor Cyan
    foreach($g in @($ctx.GpuAdapters)){
        Write-VSOHost ('  - {0} | {1} | PCI {2}:{3} SUBSYS {4} | Driver {5}'-f$g.Vendor,$g.Name,$g.VendorId,$g.DeviceId,$g.SubsystemId,$g.DriverVersion) -ForegroundColor Gray;
        Write-VSOHost ('    PnP: '+$g.PNPDeviceID) -ForegroundColor DarkGray
    }
    Write-VSOHost ('  Topology: {0} | Hardware={1} | Hybrid={2}'-f$topology.Class,$topology.HardwareAdapterCount,$topology.LikelyHybrid) -ForegroundColor Gray
    Write-VSOHost '';
    Write-VSOHost 'DXCore:' -ForegroundColor Cyan
    if([bool]$native.DxCore.Available){
        foreach($a in @($native.DxCore.Adapters)){
            Write-VSOHost ('  - {0} | LUID(session) {1} | PCI {2:X4}:{3:X4} SUBSYS {4:X8} | HW={5} Integrated={6} | MinRank={7} HighRank={8}'-f$a.Description,$a.Luid,[uint32]$a.VendorId,[uint32]$a.DeviceId,[uint32]$a.SubSystemId,$a.IsHardware,$a.IsIntegrated,$a.MinimumPowerRank,$a.HighPerformanceRank) -ForegroundColor Gray
        }
    }else{
        Write-VSOHost ('  Unavailable: '+[string]$native.DxCore.Error) -ForegroundColor DarkGray
    }
    Write-VSOHost 'DXGI:' -ForegroundColor Cyan
    if([bool]$native.Dxgi.Available){
        Write-VSOHost ('  Factory6={0} | TearingQuery={1} | TearingSupported={2}'-f$native.Dxgi.Factory6,$native.Dxgi.TearingQueryAvailable,$native.Dxgi.TearingSupported) -ForegroundColor Gray;
        foreach($a in @($native.Dxgi.Adapters)){
            Write-VSOHost ('  - {0} | LUID(session) {1} | PCI {2:X4}:{3:X4} SUBSYS {4:X8} | Software={5} | MinRank={6} HighRank={7}'-f$a.Description,$a.Luid,[uint32]$a.VendorId,[uint32]$a.DeviceId,[uint32]$a.SubSystemId,$a.Software,$a.MinimumPowerRank,$a.HighPerformanceRank) -ForegroundColor Gray
        }
    }else{
        Write-VSOHost ('  Unavailable: '+[string]$native.Dxgi.Error) -ForegroundColor DarkGray
    }
    $pref=$native.PreferenceMapping;
    Write-VSOHost ('  Windows MinimumPower: {0}'-f$(if([string]$pref.MinimumPowerStatus-eq'Resolved'){
        [string]$pref.MinimumPower.Description
    }else{
        [string]$pref.MinimumPowerStatus
    })) -ForegroundColor Gray;
    Write-VSOHost ('  Windows HighPerformance: {0}'-f$(if([string]$pref.HighPerformanceStatus-eq'Resolved'){
        [string]$pref.HighPerformance.Description
    }else{
        [string]$pref.HighPerformanceStatus
    })) -ForegroundColor Gray
    foreach($c in @($native.AdapterCorrelation)){
        if([string]$c.Status-ne'Resolved'){
            Write-VSOHost ('  DXCore/DXGI correlation '+$c.Luid+': '+$c.Status) -ForegroundColor Yellow
        }
    }
    $d=Get-VSO7DxDiagGraphicsStateVSO -Refresh
    Write-VSOHost '';
    Write-VSOHost ('HAGS aggregate: {0} | Supported={1} | Mutable={2}'-f$d.HagsAggregateState,[bool]$d.HagsSupported,[bool]$d.HagsMutable) -ForegroundColor $(if([string]$d.HagsAggregateState-eq'Ambiguous'){
        'Yellow'
    }else{
        'Gray'
    });
    foreach($ha in @($d.HagsAdapters)){
        Write-VSOHost ('  HAGS[{0}] {1} | {2} | Enabled={3}'-f$ha.Index,$ha.Name,$ha.SupportState,$ha.Enabled) -ForegroundColor Gray
    };
    if(-not[bool]$d.Verified-and$d.Reason){
        Write-VSOHost ('  HAGS unverified: '+$d.Reason) -ForegroundColor Yellow
    }
    Write-VSOHost '';
    Write-VSOHost 'DisplayConfig:' -ForegroundColor Cyan
    if([bool]$native.DisplayConfig.Available){
        Write-VSOHost ('  QueryFlags=0x{0:X} | VirtualRefreshAware={1}'-f[uint32]$native.DisplayConfig.QueryFlags,$native.DisplayConfig.VirtualRefreshAware) -ForegroundColor DarkGray;
        foreach($x in @($native.DisplayConfig.Displays)){
            $id=Get-VSO7DisplayPersistentIdentityVSO -Display $x;
            Write-VSOHost ('  - {0} | {1:N2} Hz | Target={2} LUID(session)={3} | Output={4}'-f$(if($x.FriendlyName){
                $x.FriendlyName
            }else{
                'Unnamed display'
            }),[double]$x.RefreshHz,$x.TargetId,$x.AdapterLuid,$x.OutputTechnology) -ForegroundColor Gray;
            Write-VSOHost ('    Persistent: {0}'-f$(if($id.PersistentIdentity){
                $id.PersistentIdentity
            }else{
                'Unknown'
            })) -ForegroundColor DarkGray;
            Write-VSOHost ('    DRR={0} | AdvancedColor={1}/{2} | HDR support/user/active={3}/{4}/{5} | WCG support/user/active={6}/{7}/{8} | Mode={9} | Contract={10}'-f$x.DrrBoostActive,$x.AdvancedColorSupported,$x.AdvancedColorActive,$x.HdrSupported,$x.HdrUserEnabled,$x.HdrActive,$x.WcgSupported,$x.WcgUserEnabled,$x.WcgActive,$x.ActiveColorModeText,$x.AdvancedColorContract) -ForegroundColor Gray
        }
    }else{
        Write-VSOHost ('  Unavailable: '+[string]$native.DisplayConfig.Error) -ForegroundColor DarkGray
    }
    foreach($line in @($d.MpoLines)){
        Write-VSOHost ('  '+$line) -ForegroundColor Gray
    };
    if(@($d.MpoLines).Count-gt0){
        Write-VSOHost $(if($isEn){
            'MPO is diagnostic only. VSO7 does NOT apply Disable MPO.'
        }else{
            'MPO es solo diagnostico. VSO7 NO aplica Disable MPO.'
        }) -ForegroundColor Yellow
    }
    Write-VSOHost '';
    Write-VSOHost $(if($isEn){
        'Identity rule: PnP/PCI and monitor path/EDID are persistent evidence. DXGI/DXCore LUID and DisplayConfig source/target IDs are session/runtime identity only.'
    }else{
        'Regla de identidad: PnP/PCI y path/EDID del monitor son evidencia persistente. LUID DXGI/DXCore e IDs source/target DisplayConfig son identidad de sesion/runtime.'
    }) -ForegroundColor Cyan
    Write-VSOHost $(if($isEn){
        'HDR/WCG remains read-only in R44. VRR, Auto HDR, Auto SR and MPO remain diagnostic/conditional; no opaque registry magic is written.'
    }else{
        'HDR/WCG sigue read-only en R44. VRR, Auto HDR, Auto SR y MPO siguen diagnostic/conditional; no se escribe registry magic opaco.'
    }) -ForegroundColor Yellow
    Pause-Vico

}

function Show-VSO7PerAppGraphicsMenuVSO {

    while($true){

        $isEn=($script:Language-eq'en');
        Write-Title;
        Write-CenteredLineVSO -Text $(if($isEn){
            'PER-APP GRAPHICS'
        }else{
            'GRAFICOS POR APLICACION'
        }) -Color $script:ThemeCopper;
        Write-VSOHost ''
        Write-CenteredLineVSO -Text $(if($isEn){
            'Configuration read-back is verified; effective state remains pending until the app is restarted.'
        }else{
            'Se verifica la configuracion por lectura; el estado efectivo queda pendiente hasta reiniciar la aplicacion.'
        }) -Color $script:ThemeText
        $path=Select-VSO7GraphicsExecutableVSO
        if($null-eq$path-or$path-eq'0'){
            return
        }
        try{
            $exe=Get-VSO7GraphicsExecutablePathVSO -InputPath $path
        }catch{
            Write-CenteredLineVSO -Text $_.Exception.Message -Color $script:ThemeDanger;
            Pause-Vico;
            continue
        }
        $snap=Get-VSO7NativeRegistrySnapshotVSO -Path $script:VSO7GraphicsUserPreferencePath -Name $exe;
        $raw=if([bool]$snap.Exists){
            [string]$snap.Value
        }else{
            ''
        }
        try{
            $gpu=Get-VSO7GraphicsCompositeTokenVSO -Raw $raw -Key 'GpuPreference';
            $win=Get-VSO7GraphicsCompositeTokenVSO -Raw $raw -Key 'SwapEffectUpgradeEnable';
            $hdr=Get-VSO7GraphicsCompositeTokenVSO -Raw $raw -Key 'AutoHDREnable'
        }catch{
            Write-CenteredLineVSO -Text $_.Exception.Message -Color $script:ThemeDanger;
            Pause-Vico;
            continue
        }
        Write-VSOHost '';
        Write-VSOHost ('EXE: '+$exe) -ForegroundColor Gray;
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Actual: GpuPreference={0} | SwapEffectUpgradeEnable={1} | AutoHDREnable={2}' -En 'Current: GpuPreference={0} | SwapEffectUpgradeEnable={1} | AutoHDREnable={2}')-f$gpu,$win,$hdr) -ForegroundColor Gray;
        $nativePref=(Get-VSO7GraphicsNativeStateVSO).PreferenceMapping;
        if([string]$nativePref.MinimumPowerStatus-eq'Resolved'){
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Adaptador de ahorro energetico: ' -En 'Power saving adapter: ')+[string]$nativePref.MinimumPower.Description) -ForegroundColor DarkGray
        }else{
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Adaptador de ahorro energetico: ' -En 'Power saving adapter: ')+[string]$nativePref.MinimumPowerStatus) -ForegroundColor DarkGray
        };
        if([string]$nativePref.HighPerformanceStatus-eq'Resolved'){
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Adaptador de alto rendimiento: ' -En 'High performance adapter: ')+[string]$nativePref.HighPerformance.Description) -ForegroundColor DarkGray
        }else{
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Adaptador de alto rendimiento: ' -En 'High performance adapter: ')+[string]$nativePref.HighPerformanceStatus) -ForegroundColor DarkGray
        };
        Write-VSOHost $(Get-VSO7ConsoleTextVSO -Es 'Verificacion efectiva tras el cambio: pendiente de reiniciar la aplicacion' -En 'Effective verification after change: PendingAppRestart') -ForegroundColor Yellow;
        Write-VSOHost ''
        $items=@(
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[1] Windows decide' -En '[1] Let Windows decide');Color='Green';Description=$(Get-VSO7ConsoleTextVSO -Es 'Elimina solo el token GpuPreference explicito · Reiniciar aplicacion' -En 'Removes only the explicit GpuPreference token · AppRestart')
        },
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[2] Ahorro energetico' -En '[2] Power saving');Color='Green';Description=$(Get-VSO7ConsoleTextVSO -Es 'GpuPreference=1 · Reiniciar aplicacion' -En 'GpuPreference=1 · AppRestart')
        },
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[3] Alto rendimiento' -En '[3] High performance');Color='Yellow';Description=$(Get-VSO7ConsoleTextVSO -Es 'GpuPreference=2 · Reiniciar aplicacion' -En 'GpuPreference=2 · AppRestart')
        },
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[4] Activar optimizaciones para juegos en ventana' -En '[4] Windowed optimizations ON');Color='Green';Description=$(Get-VSO7ConsoleTextVSO -Es 'SwapEffectUpgradeEnable=1 · Reiniciar aplicacion' -En 'SwapEffectUpgradeEnable=1 · AppRestart')
        },
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[5] Desactivar optimizaciones para juegos en ventana' -En '[5] Windowed optimizations OFF');Color='Yellow';Description=$(Get-VSO7ConsoleTextVSO -Es 'Bloqueado si existe un token Auto HDR · Reiniciar aplicacion' -En 'Blocked if an Auto HDR token is present · AppRestart')
        },
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[6] Restablecer preferencia de GPU' -En '[6] Reset GPU preference');Color='Gray';Description=$(Get-VSO7ConsoleTextVSO -Es 'Elimina solo el token GpuPreference · Reiniciar aplicacion' -En 'Removes only the GpuPreference token · AppRestart')
        },
          [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[7] Restablecer preferencia de juegos en ventana' -En '[7] Reset windowed override');Color='Gray';Description=$(Get-VSO7ConsoleTextVSO -Es 'Elimina solo el token SwapEffectUpgradeEnable · Reiniciar aplicacion' -En 'Removes only the SwapEffectUpgradeEnable token · AppRestart')
        },
          [pscustomobject]@{
            Text='[0] Back';Color='Gray';Description=$(Get-VSO7ConsoleTextVSO -Es 'Sin cambios' -En 'No changes');SeparatorBefore=$true
        }
        );
        Write-CenteredMenuVSO -Items $items
        $c=Read-CenteredPromptVSO -AnimatedMenu -Text $(if($isEn){
            'Choose'
        }else{
            'Elige'
        });
        if($c-eq'0'){
            continue
        }
        $map=@{
            '1'='GpuWindows';
            '2'='GpuSaving';
            '3'='GpuHigh';
            '4'='WindowedOn';
            '5'='WindowedOff';
            '6'='ResetGpu';
            '7'='ResetWindowed'
        };
        if(-not$map.ContainsKey($c)){
            continue
        }
        try{
            [void](Invoke-VSO7PerAppGraphicsChoiceVSO -Executable $exe -Choice $map[$c]);
            Write-CenteredLineVSO -Text $(if($isEn){
                'ConfigurationVerification=PASS. EffectiveVerification=PendingAppRestart.'
            }else{
                'ConfigurationVerification=PASS. EffectiveVerification=PendingAppRestart.'
            }) -Color $script:ThemeSuccess
        }catch{
            Write-CenteredLineVSO -Text $_.Exception.Message -Color $script:ThemeDanger
        };
        Pause-Vico

    }

}

function Show-VSO7GraphicsMenuVSO {

    while($true){

        $isEn=($script:Language-eq'en');
        Write-Title;
        Write-CenteredLineVSO -Text $(if($isEn){
            'GRAPHICS & GPU - R44'
        }else{
            'GRAFICOS Y GPU - R44'
        }) -Color $script:ThemeCopper;
        Write-VSOHost ''
        $items=@(
          [pscustomobject]@{
            Text=$(if($isEn){
                '[1] Global graphics features'
            }else{
                '[1] Features graficas globales'
            });Color='Green';Description=$(if($isEn){
                'Windowed optimizations and HAGS with configured/effective separation.'
            }else{
                'Optimizaciones en ventana y HAGS separando configured/effective.'
            })
        },
          [pscustomobject]@{
            Text=$(if($isEn){
                '[2] Per-app graphics preferences'
            }else{
                '[2] Preferencias graficas por aplicacion'
            });Color='Cyan';Description=$(if($isEn){
                'Windows decides / power saving / high performance and windowed override.'
            }else{
                'Windows decide / ahorro / alto rendimiento y override de ventana.'
            })
        },
          [pscustomobject]@{
            Text=$(if($isEn){
                '[3] GPU / HAGS / MPO / hybrid diagnostics'
            }else{
                '[3] Diagnostico GPU / HAGS / MPO / hibrida'
            });Color='Cyan';Description=$(if($isEn){
                'Read-only adapter identity/topology and graphics diagnostics.'
            }else{
                'Identidad/topologia de adaptadores y diagnostico grafico de solo lectura.'
            })
        },
          [pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });Color='Gray';Description='';SeparatorBefore=$true
        }
        );
        Write-CenteredMenuVSO -Items $items;
        $c=Read-CenteredPromptVSO -AnimatedMenu -Text $(if($isEn){
            'Choose'
        }else{
            'Elige'
