        switch($c){
            '1'{
                Show-VSO7FeatureCategoryVSO -Categories @('Graphics & GPU')
            }'2'{
                Show-VSO7PerAppGraphicsMenuVSO
            }'3'{
                Show-VSO7GraphicsDiagnosticsVSO
            }'0'{
                return
            }
        }

    }

}

function Enable-VSO7NativeOptionalFeatureVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$Name)
    $entry=Add-VSO7NativeOptionalFeatureBackupVSO -Session $Session -Name $Name -IntendedState 'Enabled'
    Dism\Enable-WindowsOptionalFeature -Online -FeatureName $Name -NoRestart -ErrorAction Stop|Out-Null
    $after=(Dism\Get-WindowsOptionalFeature -Online -FeatureName $Name -ErrorAction Stop).State.ToString()
    $afterClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $after
    if(@('Enabled','EnablePending')-notcontains$afterClass){
        throw ('Optional Feature no quedo habilitada ni pendiente de habilitar: {0} -> {1}'-f$Name,$after)
    }
    $entry.AppliedState=$after;
    $entry.Status='Applied';
    Save-VSO7NativeBackupSessionVSO -Session $Session
    if($afterClass-eq'EnablePending'){
        Write-VSO7Log ("Optional Feature pendiente de reinicio: {0} -> {1}. Se conserva ownership para Recovery."-f$Name,$after) 'WARN'
    }

}

function Invoke-VSO7NativeSpecialFeatureVSO {

    param([Parameter(Mandatory=$true)]$Session,[Parameter(Mandatory=$true)][string]$FeatureId)
    switch($FeatureId){

        'V7GP001' {
            return [bool](Invoke-VSO7GraphicsGlobalWindowedOperationVSO -Session $Session -Enable $true)
        }
        'V7GP002' {
            return [bool](Invoke-VSO7GraphicsGlobalWindowedOperationVSO -Session $Session -Enable $false)
        }
        'V7GP003' {
            return [bool](Invoke-VSO7HagsOperationVSO -Session $Session -Enable $true)
        }
        'V7GP004' {
            return [bool](Invoke-VSO7HagsOperationVSO -Session $Session -Enable $false)
        }
        'V7SP003' {
            return [bool](Invoke-VSO7NonReversibleAppxGroupVSO -Session $Session -Id 'V7SP003' -Description 'Las aplicaciones eliminadas pueden requerir reinstalacion manual.' -AppIds @('Microsoft.GamingApp','Microsoft.XboxGameOverlay','Microsoft.XboxGamingOverlay'))
        }
        'V7SP004' {
            return [bool](Invoke-VSO7NonReversibleAppxGroupVSO -Session $Session -Id 'V7SP004' -Description 'Las aplicaciones OEM eliminadas pueden requerir reinstalacion manual.' -AppIds @('AD2F1837.HPAIExperienceCenter','AD2F1837.HPJumpStarts','AD2F1837.HPPCHardwareDiagnosticsWindows','AD2F1837.HPPowerManager','AD2F1837.HPPrivacySettings','AD2F1837.HPSupportAssistant','AD2F1837.HPSureShieldAI','AD2F1837.HPSystemInformation','AD2F1837.HPQuickDrop','AD2F1837.HPWorkWell','AD2F1837.myHP','AD2F1837.HPDesktopSupportUtilities','AD2F1837.HPQuickTouch','AD2F1837.HPEasyClean','AD2F1837.HPConnectedMusic','AD2F1837.HPFileViewer','AD2F1837.HPRegistration','AD2F1837.HPWelcome','AD2F1837.HPConnectedPhotopoweredbySnapfish','AD2F1837.HPPrinterControl'))
        }
        'V7TB007' {
            $ids=@('Microsoft.StartExperiencesApp','MicrosoftWindows.Client.WebExperience','Microsoft.WidgetsPlatformRuntime');
            if(-not(Test-VSO7AppxGroupPresenceVSO -AppIds $ids)){
                return $true
            };
            Add-VSO7NativeNonReversibleBackupVSO -Session $Session -Id 'V7TB007' -Description 'Los paquetes de Widgets eliminados pueden requerir reinstalacion manual.';
            try{
                Get-Process -ErrorAction SilentlyContinue|Where-Object{
                    $_.ProcessName-like'*Widget*'
                }|Stop-Process -Force -ErrorAction SilentlyContinue
            }catch{};
            $ok=$true;
            foreach($id in $ids){
                if(-not(Invoke-VSO7RemoveAppIdVSO -AppId $id -RemovalMethod 'Appx')){
                    $ok=$false
                }
            };
            return $ok
        }
        'V7SP008' {
            return [bool](Invoke-VSO7ForceRemoveEdgeVSO -Session $Session)
        }
        'V7OF001' {
            Enable-VSO7NativeOptionalFeatureVSO -Session $Session -Name 'Containers-DisposableClientVM';
            return $true
        }
        'V7OF002' {
            foreach($name in @('VirtualMachinePlatform','Microsoft-Windows-Subsystem-Linux')){
                Enable-VSO7NativeOptionalFeatureVSO -Session $Session -Name $name
            };
            return $true
        }
        'V7ST007' {
            throw 'La supresion de sugerencias de Store en busqueda esta deshabilitada hasta disponer de rollback nativo de ACL suficientemente robusto.'
        }
        'V7SP005' {
            return [bool](New-SafeRestorePoint)
        }
        'V7ST001' {
            throw 'La limpieza completa del menu Inicio esta deshabilitada hasta disponer de una implementacion VSO7 nativa segura.'
        }
        'V7ST002' {
            throw 'La limpieza del menu Inicio para todos los usuarios esta deshabilitada hasta disponer de una implementacion VSO7 nativa segura.'
        }
        'V7SP006' {
            throw 'La sustitucion de la configuracion de Inicio requiere una plantilla validada y no se expone como interruptor nativo en esta RC.'
        }
        'V7SP007' {
            throw 'La sustitucion de la configuracion de Inicio para todos los usuarios requiere una plantilla validada y no se expone como interruptor nativo en esta RC.'
        }
        'V7SP001' {
            return $true
        }
        'V7SP002' {
            return $true
        }
        default {
            throw ('Feature especial VSO7 no implementada: {0}'-f$FeatureId)
        }

    }

}

function Assert-VSO7NativeBatchTargetClaimsVSO {

    param([Parameter(Mandatory=$true)][string[]]$FeatureIds,[Parameter(Mandatory=$true)][array]$Definitions)
    $registry=@{};
    $power=@{}
    foreach($featureId in $FeatureIds){

        $def=@($Definitions|Where-Object{
            [string]$_.FeatureId-ceq[string]$featureId
        }|Select-Object -First 1)
        if($def.Count-ne1){
            throw ('No existe definicion nativa para target preflight: {0}.'-f$featureId)
        }
        switch([string]$def[0].Mode){

            'Registry' {

                foreach($op in @($def[0].Apply)){

                    if([string]$op.Action-notin@('SetValue','DeleteValue')){
                        continue
                    }
                    $key=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$op.Path)),([string]$op.Name).ToLowerInvariant())
                    $sig=if([string]$op.Action-ieq'DeleteValue'){
                        'DELETE'
                    }else{
                        ('SET|{0}|{1}'-f[string]$op.Kind,([string]$op.Value))
                    }
                    if($registry.ContainsKey($key)-and[string]$registry[$key].Signature-cne$sig){
                        throw ('El lote contiene dos intenciones Registry incompatibles sobre {0}: {1} / {2}.'-f$key,$registry[$key].FeatureId,$featureId)
                    }
                    if(-not$registry.ContainsKey($key)){
                        $registry[$key]=[pscustomobject]@{
                            FeatureId=$featureId;
                            Signature=$sig
                        }
                    }

                }

            }
            'PowerSetting' {

                foreach($op in @($def[0].Apply)){

                    if([string]$op.Action-ine'SetPowerSetting'){
                        continue
                    }
                    $base=('{0}|{1}'-f([string]$op.SubGroupAlias).ToLowerInvariant(),([string]$op.SettingAlias).ToLowerInvariant())
                    foreach($side in @('AC','DC')){

                        if(-not($op.PSObject.Properties.Name-contains$side)-or[string]$op.$side-ieq'Preserve'){
                            continue
                        }
                        $key=('POWER|{0}|{1}'-f$base,$side)
                        $value=[string]$op.$side
                        if($power.ContainsKey($key)-and[string]$power[$key].Value-cne$value){
                            throw ('El lote contiene dos intenciones PowerSetting incompatibles sobre {0}: {1} / {2}.'-f$key,$power[$key].FeatureId,$featureId)
                        }
                        if(-not$power.ContainsKey($key)){
                            $power[$key]=[pscustomobject]@{
                                FeatureId=$featureId;
                                Value=$value
                            }
                        }

                    }

                }

            }

        }

    }
    return $true

}

function Invoke-VSO7NativeTweaksVSO {

    [CmdletBinding()]
    param([string[]]$Features=@(),[string[]]$Apps=@(),[switch]$AppRemoval,[string]$BatchKind='',[string]$BatchId='',[string]$BatchObjective='',[object[]]$PreflightBaselines=@(),[switch]$AllowSpecializedChoice)
    try{

        if(-not(Test-VSO7NativeResourceIntegrityVSO)){
            throw 'Los recursos nativos VSO7 no son validos.'
        }
        if(@($Apps).Count-gt0-and@($Features|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}).Count-gt0){
            throw 'El motor nativo VSO7 no acepta Features y Apps simultaneamente: el caller debe ejecutar ambos planes de forma explicita para no ocultar una mitad de la operacion.'
        }
        if(@($Apps).Count-gt0){
            $appOk=[bool](Invoke-VSO7NativeAppRemovalVSO -Apps $Apps)
            if($appOk){try{[void](Save-VSO7LastAppliedSelectionR76VSO -Apps @($Apps))}catch{Write-VSO7Log ('No se pudo persistir la ultima seleccion de Apps: '+$_.Exception.Message) 'WARN'}}
            return $appOk
        }
        if($AppRemoval){
            Show-VSO7AppSelectorVSO;
            return $true
        }
        $data=Get-VSO7NativeDataVSO;
        $defs=@($data.Features);
        $requested=@($Features|Where-Object{
            -not[string]::IsNullOrWhiteSpace([string]$_)
        }|Select-Object -Unique)
        if($requested.Count-eq0){
            throw 'El motor nativo VSO7 recibio una seleccion de features vacia; no se declarara exito para una operacion sin objetivos.'
        }
        $catalog=@(Get-VSO7FeatureCatalogVSO);
        [void](Assert-VSO7NativeFeatureSelectionVSO -Requested $requested -Catalog $catalog -AllowSpecializedChoice:$AllowSpecializedChoice)
        [void](Assert-VSO7NativeBatchTargetClaimsVSO -FeatureIds $requested -Definitions $defs)
        [void](Assert-VSO7NativeOwnershipAvailableVSO -Requested $requested -Catalog $catalog -Definitions $defs)
        $session=New-VSO7NativeBackupSessionVSO -Features $requested -BatchKind $BatchKind -BatchId $BatchId -BatchObjective $BatchObjective -PreflightBaselines $PreflightBaselines;
        $ok=$true
        try{

            foreach($featureId in $requested){

                if($featureId-notmatch'^[A-Za-z][A-Za-z0-9]+$'){
                    throw ('FeatureId VSO7 invalido: {0}'-f$featureId)
                }
                $def=@($defs|Where-Object{
                    [string]$_.FeatureId-eq[string]$featureId
                }|Select-Object -First 1);
                if($def.Count-ne1){
                    throw ('FeatureId VSO7 no implementado: {0}'-f$featureId)
                }
                $featureResult=[pscustomobject]@{
                    FeatureId=[string]$featureId;
                    Status='Pending';
                    StartedAt=(Get-Date).ToString('o');
                    CompletedAt=$null;
                    Error=$null
                }
                $session.FeatureResults+=,$featureResult;
                Save-VSO7NativeBackupSessionVSO -Session $session
                Write-VSO7Log ("Aplicando feature nativa: {0}"-f$featureId) 'CHANGE'
                $featureOk=$true
                try{

                # Revalidate the globally captured baseline immediately before this
                # feature mutates anything. A mismatch is recorded as this feature's
                # Failed result, not lost as an anonymous batch failure.
                if(@($PreflightBaselines).Count-gt0){

                    $expected=@($PreflightBaselines|Where-Object{
                            [string]$_.FeatureId-eq[string]$featureId
                        }|Select-Object -First 1)
                    if($expected.Count-ne1){
                            throw ('Falta baseline global preflight para {0}.'-f$featureId)
                        }
                    $current=Get-VSO7NativeFeaturePreflightSnapshotVSO -FeatureId $featureId
                    if([string]$current.Hash-cne[string]$expected[0].Hash){
                            throw ('El baseline de {0} cambio despues del preflight global; se aborta para no aplicar sobre estado distinto.'-f$featureId)
                        }

                    }
                $entriesBefore=@($session.Entries).Count
                switch([string]$def[0].Mode){

                    'Registry' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeRegistryOperationVSO -Session $session -Operation $op
                            }
                        }
                    'PowerSetting' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativePowerSettingOperationVSO -Session $session -Operation $op
                            }
                        }
                    'NetAdapterRss' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeRssOperationVSO -Session $session -Operation $op
                            }
                        }
                    'NetAdapterAdvanced' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeAdapterAdvancedOperationVSO -Session $session -Operation $op
                            }
                        }
                    'NetOffloadGlobal' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeGlobalOffloadOperationVSO -Session $session -Operation $op
                            }
                        }
                    'NetTcpSetting' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeTcpSettingOperationVSO -Session $session -Operation $op
                            }
                        }
                    'NetTcpCimSetting' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeTcpTimestampCimOperationVSO -Session $session -Operation $op
                            }
                        }
                    'FsutilTrim' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeFsutilTrimOperationVSO -Session $session -Operation $op
                            }
                        }
                    'ScheduledTaskState' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeScheduledTaskOperationVSO -Session $session -Operation $op
                            }
                        }
                    'NetAdapterPower' {
                            foreach($op in @($def[0].Apply)){
                                Invoke-VSO7NativeNetAdapterPowerOperationVSO -Session $session -Operation $op
                            }
                        }
                    'Special' {
                            if(-not(Invoke-VSO7NativeSpecialFeatureVSO -Session $session -FeatureId $featureId)){
                                throw ('Feature especial devolvio fallo y StopOnFirstFailure exige abortar el lote: {0}'-f$featureId)
                            }
                        }
                    default {
                            throw ('Mode nativo VSO7 desconocido: {0}'-f$def[0].Mode)
                        }

                    }
                $entriesAfter=@($session.Entries).Count
                if($entriesAfter-eq$entriesBefore){
                        $featureResult.Status='NoChange';
                        $session.Features=@($session.Features|Where-Object{
                            [string]$_-cne[string]$featureId
                        })
                    }else{
                        $featureResult.Status=if($featureOk){
                            'Applied'
                        }else{
                            'Partial'
                        }
                    }
                $featureResult.CompletedAt=(Get-Date).ToString('o');
                    Save-VSO7NativeBackupSessionVSO -Session $session

                }catch{
                    $featureResult.Status='Failed';
                    $featureResult.CompletedAt=(Get-Date).ToString('o');
                    $featureResult.Error=$_.Exception.Message;
                    try{
                        Save-VSO7NativeBackupSessionVSO -Session $session
                    }catch{};
                    throw
                }

            }
            $reversibleEntryCount=@($session.Entries|Where-Object{
                [string]$_.Type-ine'NonReversible'
            }).Count
            if($ok-and(@($session.Features).Count-eq0-or$reversibleEntryCount-eq0)){
                $session.Status='Restored'
            }else{
                $session.Status=if($ok){
                    'Applied'
                }else{
                    'Partial'
                }
            };
            Save-VSO7NativeBackupSessionVSO -Session $session
            if($ok){try{[void](Save-VSO7LastAppliedSelectionR76VSO -Features @($requested))}catch{Write-VSO7Log ('No se pudo persistir la ultima seleccion de Features: '+$_.Exception.Message) 'WARN'}}
            return $ok

        }catch{
            $session.Status='Partial';
            try{
                Save-VSO7NativeBackupSessionVSO -Session $session
            }catch{};
            throw
        }

    }catch{
        Write-VSO7Log ("Motor nativo VSO7 fallo: {0}"-f$_.Exception.Message) 'ERROR';
        Write-VSOHost $_.Exception.Message -ForegroundColor Red;
        return $false
    }

}

function ConvertTo-VSO7NormalizedSchema2EntryVSO {

    param(
        [Parameter(Mandatory=$true)]$Entry,
        [Nullable[int]]$ProducerRevision=$null
    )
    if($null-eq$Entry-or$Entry-is[string]){
        throw 'Recovery nativo Schema 2 contiene una Entry invalida.'
    }
    $type=[string]$Entry.Type
    if($type-ieq'PowerSetting'){

        $hasAC=@($Entry.PSObject.Properties.Name)-contains'OwnsAC'
        $hasDC=@($Entry.PSObject.Properties.Name)-contains'OwnsDC'
        if(-not$hasAC-and-not$hasDC){

            if($null-ne$ProducerRevision-and[int]$ProducerRevision-ge24){
                throw 'PowerSetting Schema 2 R24+ carece de OwnsAC/OwnsDC; journal corrupto/incompleto.'
            }
            # Los Schema 2 pre-R24 reales no escribian ProducerRevision. Dentro de ese
            # epoch historico, el shape sin ambas masks corresponde al formato pre-R20.
            # Derivamos ownership únicamente de lados cuya intención/aplicado demuestra
            # una desviación respecto al baseline; nunca inventamos ownership de un lado igual.
            $ownsAC=($null-ne$Entry.AppliedAC-and[int]$Entry.AppliedAC-ne[int]$Entry.AC)-or($null-ne$Entry.IntendedAC-and[int]$Entry.IntendedAC-ne[int]$Entry.AC)
            $ownsDC=($null-ne$Entry.AppliedDC-and[int]$Entry.AppliedDC-ne[int]$Entry.DC)-or($null-ne$Entry.IntendedDC-and[int]$Entry.IntendedDC-ne[int]$Entry.DC)
            if(-not$ownsAC-and-not$ownsDC){
                throw 'PowerSetting historico no permite demostrar ownership de AC ni DC.'
            }
            $Entry|Add-Member -NotePropertyName OwnsAC -NotePropertyValue ([bool]$ownsAC) -Force
            $Entry|Add-Member -NotePropertyName OwnsDC -NotePropertyValue ([bool]$ownsDC) -Force

        }elseif($hasAC-xor$hasDC){
            throw 'PowerSetting historico contiene una sola mascara AC/DC; shape ambiguo.'
        }

    }
    if($type-ieq'ScheduledTaskState'){

        $hasBaseline=@($Entry.PSObject.Properties.Name)-contains'BaselineDefinitionSha256'
        $hasApplied=@($Entry.PSObject.Properties.Name)-contains'AppliedDefinitionSha256'
        if(-not$hasBaseline-or-not$hasApplied){

            if($null-ne$ProducerRevision-and[int]$ProducerRevision-ge24){
                throw 'ScheduledTaskState Schema 2 R24+ carece de fingerprints; journal corrupto/incompleto.'
            }
            # Los journals Schema 2 anteriores a la introduccion de fingerprints tampoco
            # tenian ProducerRevision. Se conserva el fallback historico de Enabled solo
            # en ese epoch; R24+ debe traer fingerprints completos.
            if(-not$hasBaseline){
                $Entry|Add-Member -NotePropertyName BaselineDefinitionSha256 -NotePropertyValue $null -Force
            }
            if(-not$hasApplied){
                $Entry|Add-Member -NotePropertyName AppliedDefinitionSha256 -NotePropertyValue $null -Force
            }

        }

           $hasBaselineCore=@($Entry.PSObject.Properties.Name)-contains'BaselineDefinitionCoreSha256'
        $hasAppliedCore=@($Entry.PSObject.Properties.Name)-contains'AppliedDefinitionCoreSha256'
        if(-not$hasBaselineCore-or-not$hasAppliedCore){
            if($null-ne$ProducerRevision-and[int]$ProducerRevision-ge26){throw 'ScheduledTaskState Schema 2 R26+ carece de fingerprints core; journal corrupto/incompleto.'}
            if(-not$hasBaselineCore){$Entry|Add-Member -NotePropertyName BaselineDefinitionCoreSha256 -NotePropertyValue $null -Force}
            if(-not$hasAppliedCore){$Entry|Add-Member -NotePropertyName AppliedDefinitionCoreSha256 -NotePropertyValue $null -Force}
        }

    }
    return $Entry

}

function Test-VSO7JsonStringArrayVSO {

    param($Value,[int]$MaxItems=4096,[int]$MaxItemLength=1048576)
    if($null-eq$Value-or$Value-is[string]){
        return $false
    }
    $items=@($Value)
    if($items.Count-gt$MaxItems){
        return $false
    }
    foreach($item in $items){
        if(-not($item-is[string])-or([string]$item).Length-gt$MaxItemLength){
            return $false
        }
    }
    return $true

}

function Test-VSO7JsonOptionalStringVSO {

    param($Value,[int]$MaxLength=1048576)
    return ($null-eq$Value-or($Value-is[string]-and([string]$Value).Length-le$MaxLength))

}

function Get-VSO7NativeBackupEntryExpectedKeyVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $type=[string]$Entry.Type
    switch($type){

        'RegistryValue' {

            $path=(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$Entry.Path)).ToLowerInvariant()
            return ($path+'|'+([string]$Entry.Name).ToLowerInvariant())

        }
        'RegistryKey' {
            return ('key|'+(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$Entry.Path))).ToLowerInvariant()
        }
        'OptionalFeature' {
            return ('feature|'+[string]$Entry.Name).ToLowerInvariant()
        }
        'NonReversible' {
            return ('nonreversible|'+[string]$Entry.Id).ToLowerInvariant()
        }
        'PowerSetting' {
            return ('power|'+[string]$Entry.SchemeGuid+'|'+[string]$Entry.SubGroupAlias+'|'+[string]$Entry.SettingAlias).ToLowerInvariant()
        }
        'NetAdapterRss' {
            return ('rss|'+[string]$Entry.InterfaceGuid).ToLowerInvariant()
        }
        'NetAdapterAdvancedProperty' {
            return ('netadv|'+[string]$Entry.InterfaceGuid+'|'+[string]$Entry.RegistryKeyword).ToLowerInvariant()
        }
        'NetOffloadGlobal' {
            return ('netglobal|'+[string]$Entry.Property).ToLowerInvariant()
        }
        'NetTcpSetting' {
            return ('tcp|'+[string]$Entry.SettingName+'|'+[string]$Entry.Property).ToLowerInvariant()
        }
        'NetTcpCimSetting' {
            return ('tcpcim|'+[string]$Entry.SettingName+'|timestamps').ToLowerInvariant()
        }
        'FsutilNtfsTrim' {
            return 'fsutil|ntfs|disabledeletenotify'
        }
        'ScheduledTaskState' {
            return ('task|'+[string]$Entry.TaskPath+'|'+[string]$Entry.TaskName).ToLowerInvariant()
        }
        'NetAdapterPower' {
            return ('nicpower|'+[string]$Entry.InterfaceGuid+'|'+[string]$Entry.Property).ToLowerInvariant()
        }
        default {
            throw ('No existe derivacion de Entry.Key para Type {0}.'-f$type)
        }

    }

}

function Assert-VSO7NativeBackupEntryShapeVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $props=@($Entry.PSObject.Properties.Name)
    foreach($required in @('Type','Key')){
        if($props-notcontains$required-or-not($Entry.$required-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.$required)){
            throw ('Recovery nativo Schema 2 contiene Entry sin {0} valido.'-f$required)
        }
    }
    $type=[string]$Entry.Type
    if($type-ine'NonReversible'){

        if($props-notcontains'Status'-or-not($Entry.Status-is[string])-or@('Pending','Applied','RestorePending')-notcontains[string]$Entry.Status){
            throw ('Recovery nativo Schema 2 contiene {0}.Status invalido.'-f$type)
        }

    }
    switch($type){

        'RegistryValue' {

            foreach($n in @('Path','Name','Exists','IntendedExists','AppliedExists')){
                if($props-notcontains$n){
                    throw ('RegistryValue Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.Path-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.Path)-or-not($Entry.Name-is[string])){
                throw 'RegistryValue Recovery contiene Path/Name invalidos.'
            }
            if(-not($Entry.Exists-is[bool])-or-not($Entry.IntendedExists-is[bool])){
                throw 'RegistryValue Recovery contiene Exists/IntendedExists no booleanos.'
            }
            if($null-ne$Entry.AppliedExists-and-not($Entry.AppliedExists-is[bool])){
                throw 'RegistryValue Recovery contiene AppliedExists no booleano/null.'
            }
            if(([bool]$Entry.Exists)-and($props-notcontains'Kind'-or-not($Entry.Kind-is[string])-or-not(Test-VSO7RegistryKindName ([string]$Entry.Kind)))){
                throw 'RegistryValue baseline existente carece de Kind valido.'
            }
            if(([bool]$Entry.Exists)-and($props-notcontains'Value'-or-not(Test-VSO7RegistryJsonValueShape -Value $Entry.Value -Kind ([string]$Entry.Kind)))){
                throw 'RegistryValue baseline contiene Value incompatible con Kind.'
            }
            if(([bool]$Entry.IntendedExists)-and($props-notcontains'IntendedKind'-or-not($Entry.IntendedKind-is[string])-or-not(Test-VSO7RegistryKindName ([string]$Entry.IntendedKind)))){
                throw 'RegistryValue intended existente carece de IntendedKind valido.'
            }
            if(([bool]$Entry.IntendedExists)-and($props-notcontains'IntendedValue'-or-not(Test-VSO7RegistryJsonValueShape -Value $Entry.IntendedValue -Kind ([string]$Entry.IntendedKind)))){
                throw 'RegistryValue intended contiene Value incompatible con Kind.'
            }
            if($Entry.AppliedExists-eq$true){

                if($props-notcontains'AppliedKind'-or-not($Entry.AppliedKind-is[string])-or-not(Test-VSO7RegistryKindName ([string]$Entry.AppliedKind))){
                    throw 'RegistryValue Applied existente carece de AppliedKind valido.'
                }
                if($props-notcontains'AppliedValue'-or-not(Test-VSO7RegistryJsonValueShape -Value $Entry.AppliedValue -Kind ([string]$Entry.AppliedKind))){
                    throw 'RegistryValue Applied contiene Value incompatible con Kind.'
                }

            }

        }
        'RegistryKey' {

            foreach($n in @('Path','Exists','IntendedExists','AppliedExists')){
                if($props-notcontains$n){
                    throw ('RegistryKey Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.Path-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.Path)-or-not($Entry.Exists-is[bool])-or-not($Entry.IntendedExists-is[bool])){
                throw 'RegistryKey Recovery contiene tipos invalidos.'
            }
            if($null-ne$Entry.AppliedExists-and-not($Entry.AppliedExists-is[bool])){
                throw 'RegistryKey AppliedExists debe ser bool/null.'
            }

        }
        'PowerSetting' {

            foreach($n in @('SchemeGuid','SubGroupAlias','SettingAlias','AC','DC','IntendedAC','IntendedDC','OwnsAC','OwnsDC','AppliedAC','AppliedDC')){
                if($props-notcontains$n){
                    throw ('PowerSetting Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.SchemeGuid-is[string])-or-not(Test-VSO7PowerSchemeGuid -Value ([string]$Entry.SchemeGuid))){
                throw 'PowerSetting Recovery contiene SchemeGuid invalido.'
            }
            if(-not($Entry.SubGroupAlias-is[string])-or-not($Entry.SettingAlias-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.SubGroupAlias)-or[string]::IsNullOrWhiteSpace([string]$Entry.SettingAlias)){
                throw 'PowerSetting Recovery contiene aliases invalidos.'
            }
            if(-not($Entry.OwnsAC-is[bool])-or-not($Entry.OwnsDC-is[bool])){
                throw 'PowerSetting Recovery contiene masks AC/DC no booleanas.'
            }
            foreach($n in @('AC','DC','IntendedAC','IntendedDC')){
                if(-not(Test-VSO7JsonInteger -Value $Entry.$n -Min 0 -Max 2147483647)){
                    throw ('PowerSetting Recovery contiene {0} invalido.'-f$n)
                }
            }
            foreach($n in @('AppliedAC','AppliedDC')){
                if($null-ne$Entry.$n-and-not(Test-VSO7JsonInteger -Value $Entry.$n -Min 0 -Max 2147483647)){
                    throw ('PowerSetting Recovery contiene {0} invalido.'-f$n)
                }
            }
            if(-not[bool]$Entry.OwnsAC-and-not[bool]$Entry.OwnsDC){
                throw 'PowerSetting Recovery no posee AC ni DC.'
            }

        }
        'NetAdapterRss' {
            foreach($n in @('InterfaceGuid','Enabled','IntendedEnabled','AppliedEnabled')){
                if($props-notcontains$n){
                    throw ('NetAdapterRss Recovery carece de {0}.'-f$n)
                }
            };
            if(-not($Entry.InterfaceGuid-is[string])-or-not($Entry.Enabled-is[bool])-or-not($Entry.IntendedEnabled-is[bool])-or($null-ne$Entry.AppliedEnabled-and-not($Entry.AppliedEnabled-is[bool]))){
                throw 'NetAdapterRss Recovery contiene tipos invalidos.'
            }
        }
        'NetAdapterAdvancedProperty' {

            foreach($n in @('InterfaceGuid','RegistryKeyword','RegistryValue','IntendedValue','AppliedValue')){
                if($props-notcontains$n){
                    throw ('NetAdapterAdvancedProperty Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.InterfaceGuid-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.InterfaceGuid)-or-not($Entry.RegistryKeyword-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.RegistryKeyword)){
                throw 'NetAdapterAdvancedProperty Recovery contiene identidad/keyword invalidos.'
            }
            if(-not(Test-VSO7JsonStringArrayVSO $Entry.RegistryValue)-or-not(Test-VSO7JsonStringArrayVSO $Entry.IntendedValue)-or($null-ne$Entry.AppliedValue-and-not(Test-VSO7JsonStringArrayVSO $Entry.AppliedValue))){
                throw 'NetAdapterAdvancedProperty Recovery contiene arrays de valores invalidos.'
            }

        }
        'NetOffloadGlobal' {

            foreach($n in @('Property','Value','IntendedValue','AppliedValue')){
                if($props-notcontains$n){
                    throw ('NetOffloadGlobal Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.Property-is[string])-or@('ReceiveSideScaling','ReceiveSegmentCoalescing','TaskOffload')-notcontains[string]$Entry.Property){
                throw 'NetOffloadGlobal Recovery contiene Property invalida.'
            }
            if(-not($Entry.Value-is[string])-or-not($Entry.IntendedValue-is[string])-or($null-ne$Entry.AppliedValue-and-not($Entry.AppliedValue-is[string]))){
                throw 'NetOffloadGlobal Recovery contiene valores no string.'
            }

        }
        'NetTcpSetting' {

            foreach($n in @('SettingName','Property','Value','IntendedValue','AppliedValue')){
                if($props-notcontains$n){
                    throw ('NetTcpSetting Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.SettingName-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.SettingName)-or-not($Entry.Property-is[string])-or@('AutoTuningLevelLocal','EcnCapability','Timestamps')-notcontains[string]$Entry.Property){
                throw 'NetTcpSetting Recovery contiene identidad/Property invalidas.'
            }
            if(-not($Entry.Value-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.Value)-or-not($Entry.IntendedValue-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.IntendedValue)-or-not(Test-VSO7JsonOptionalStringVSO $Entry.AppliedValue)){
                throw 'NetTcpSetting Recovery contiene valores invalidos.'
            }

        }
        'NetTcpCimSetting' {

            foreach($n in @('SettingName','Property','Value','RawValue','IntendedValue','IntendedRawValue','AppliedValue','AppliedRawValue')){
                if($props-notcontains$n){
                    throw ('NetTcpCimSetting Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.SettingName-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.SettingName)-or-not($Entry.Property-is[string])-or[string]$Entry.Property-cne'Timestamps'){
                throw 'NetTcpCimSetting Recovery contiene identidad/Property invalidas.'
            }
            if(-not($Entry.Value-is[string])-or@('Disabled','Enabled','Allowed')-notcontains[string]$Entry.Value-or-not($Entry.IntendedValue-is[string])-or@('Disabled','Enabled','Allowed')-notcontains[string]$Entry.IntendedValue){
                throw 'NetTcpCimSetting Recovery contiene estados invalidos.'
            }
            if(-not(Test-VSO7JsonInteger $Entry.RawValue 0 2)-or-not(Test-VSO7JsonInteger $Entry.IntendedRawValue 0 2)-or($null-ne$Entry.AppliedRawValue-and-not(Test-VSO7JsonInteger $Entry.AppliedRawValue 0 2))){
                throw 'NetTcpCimSetting Recovery contiene valores raw invalidos.'
            }
            if($null-ne$Entry.AppliedValue-and(-not($Entry.AppliedValue-is[string])-or@('Disabled','Enabled','Allowed')-notcontains[string]$Entry.AppliedValue)){
                throw 'NetTcpCimSetting Recovery contiene AppliedValue invalido.'
            }
            if([int]$Entry.RawValue-ne[int](ConvertTo-VSO7TcpTimestampCimValueVSO ([string]$Entry.Value))-or[int]$Entry.IntendedRawValue-ne[int](ConvertTo-VSO7TcpTimestampCimValueVSO ([string]$Entry.IntendedValue))){
                throw 'NetTcpCimSetting Recovery contiene Value/RawValue incoherentes.'
            }
            if($null-ne$Entry.AppliedValue-and($null-eq$Entry.AppliedRawValue-or[int]$Entry.AppliedRawValue-ne[int](ConvertTo-VSO7TcpTimestampCimValueVSO ([string]$Entry.AppliedValue)))){
                throw 'NetTcpCimSetting Recovery contiene Applied Value/Raw incoherentes.'
            }

        }
        'FsutilNtfsTrim' {

            foreach($n in @('Disabled','ReFsVolumeCount','IntendedDisabled','AppliedDisabled')){
                if($props-notcontains$n){
                    throw ('FsutilNtfsTrim Recovery carece de {0}.'-f$n)
                }
            }
            if(-not(Test-VSO7JsonInteger $Entry.Disabled 0 1)-or-not(Test-VSO7JsonInteger $Entry.IntendedDisabled 0 1)-or-not(Test-VSO7JsonInteger $Entry.ReFsVolumeCount 0 1048576)-or($null-ne$Entry.AppliedDisabled-and-not(Test-VSO7JsonInteger $Entry.AppliedDisabled 0 1))){
                throw 'FsutilNtfsTrim Recovery contiene tipos/rangos invalidos.'
            }

        }
        'ScheduledTaskState' {

            foreach($n in @('TaskPath','TaskName','Enabled','BaselineDefinitionSha256','BaselineDefinitionCoreSha256','IntendedEnabled','AppliedEnabled','AppliedDefinitionSha256','AppliedDefinitionCoreSha256')){
                if($props-notcontains$n){
                    throw ('ScheduledTaskState Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.TaskPath-is[string])-or-not($Entry.TaskName-is[string])-or-not($Entry.Enabled-is[bool])-or-not($Entry.IntendedEnabled-is[bool])-or($null-ne$Entry.AppliedEnabled-and-not($Entry.AppliedEnabled-is[bool]))){
                throw 'ScheduledTaskState Recovery contiene tipos invalidos.'
            }
            foreach($n in @('BaselineDefinitionSha256','BaselineDefinitionCoreSha256','AppliedDefinitionSha256','AppliedDefinitionCoreSha256')){
                if($null-ne$Entry.$n-and(-not($Entry.$n-is[string])-or([string]$Entry.$n-notmatch'^[0-9A-Fa-f]{64}$'))){
                    throw ('ScheduledTaskState {0} invalido.'-f$n)
                }
            }

        }
        'NetAdapterPower' {

            foreach($n in @('InterfaceGuid','Property','Value','IntendedValue','AppliedValue')){
                if($props-notcontains$n){
                    throw ('NetAdapterPower Recovery carece de {0}.'-f$n)
                }
            }
            if(-not($Entry.InterfaceGuid-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.InterfaceGuid)-or-not($Entry.Property-is[string])-or@('SelectiveSuspend','WakeOnMagicPacket','WakeOnPattern')-notcontains[string]$Entry.Property){
                throw 'NetAdapterPower Recovery contiene identidad/Property invalidas.'
            }
            foreach($n in @('Value','IntendedValue')){
                if(-not($Entry.$n-is[string])-or@('Enabled','Disabled')-notcontains[string]$Entry.$n){
                    throw ('NetAdapterPower Recovery contiene {0} invalido.'-f$n)
                }
            }
            if($null-ne$Entry.AppliedValue-and(-not($Entry.AppliedValue-is[string])-or@('Enabled','Disabled')-notcontains[string]$Entry.AppliedValue)){
                throw 'NetAdapterPower Recovery contiene AppliedValue invalido.'
            }

        }
        'OptionalFeature' {
            foreach($n in @('Name','State','IntendedState','AppliedState')){
                if($props-notcontains$n){
                    throw ('OptionalFeature Recovery carece de {0}.'-f$n)
                }
            };
            foreach($n in @('Name','State','IntendedState')){
                if(-not($Entry.$n-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.$n)){
                    throw ('OptionalFeature Recovery contiene {0} invalido.'-f$n)
                }
            };
            if($null-ne$Entry.AppliedState-and-not($Entry.AppliedState-is[string])){
                throw 'OptionalFeature AppliedState invalido.'
            }
        }
        'NonReversible' {
            foreach($n in @('Id','Description')){
                if($props-notcontains$n-or-not($Entry.$n-is[string])-or[string]::IsNullOrWhiteSpace([string]$Entry.$n)){
                    throw ('NonReversible Recovery carece de {0}.'-f$n)
                }
            }
        }
        default {
            throw ('Recovery nativo Schema 2 contiene Entry.Type desconocido: {0}.'-f$type)
        }

    }
    $expectedKey=Get-VSO7NativeBackupEntryExpectedKeyVSO -Entry $Entry
    if([string]$Entry.Key-ine[string]$expectedKey){
        throw ('Recovery nativo Schema 2 contiene Entry.Key que no corresponde a su target: {0} != {1}.'-f[string]$Entry.Key,[string]$expectedKey)
    }
    if($type-ine'NonReversible'-and[string]$Entry.Status-ceq'Applied'){

        switch($type){

            'RegistryValue' {
                if($null-eq$Entry.AppliedExists){
                    throw 'RegistryValue Applied requiere AppliedExists booleano.'
                }
            }
            'RegistryKey' {
                if($null-eq$Entry.AppliedExists){
                    throw 'RegistryKey Applied requiere AppliedExists booleano.'
                }
            }
            'PowerSetting' {
                if(([bool]$Entry.OwnsAC-and$null-eq$Entry.AppliedAC)-or([bool]$Entry.OwnsDC-and$null-eq$Entry.AppliedDC)){
                    throw 'PowerSetting Applied carece del valor aplicado de un lado owned.'
                }
            }
            'NetAdapterRss' {
                if($null-eq$Entry.AppliedEnabled){
                    throw 'NetAdapterRss Applied carece de AppliedEnabled.'
                }
            }
            'NetAdapterAdvancedProperty' {
                if($null-eq$Entry.AppliedValue){
                    throw 'NetAdapterAdvancedProperty Applied carece de AppliedValue.'
                }
            }
            'NetOffloadGlobal' {
                if($null-eq$Entry.AppliedValue){
                    throw 'NetOffloadGlobal Applied carece de AppliedValue.'
                }
            }
            'NetTcpSetting' {
                if($null-eq$Entry.AppliedValue){
                    throw 'NetTcpSetting Applied carece de AppliedValue.'
                }
            }
            'NetTcpCimSetting' {
                if($null-eq$Entry.AppliedValue-or$null-eq$Entry.AppliedRawValue){
                    throw 'NetTcpCimSetting Applied carece de AppliedValue/AppliedRawValue.'
                }
            }
            'FsutilNtfsTrim' {
                if($null-eq$Entry.AppliedDisabled){
                    throw 'FsutilNtfsTrim Applied carece de AppliedDisabled.'
                }
            }
            'ScheduledTaskState' {
                if($null-eq$Entry.AppliedEnabled){
                    throw 'ScheduledTaskState Applied carece de AppliedEnabled.'
                }
            }
            'NetAdapterPower' {
                if($null-eq$Entry.AppliedValue){
                    throw 'NetAdapterPower Applied carece de AppliedValue.'
                }
            }
            'OptionalFeature' {
                if([string]::IsNullOrWhiteSpace([string]$Entry.AppliedState)){
                    throw 'OptionalFeature Applied carece de AppliedState.'
                }
            }

        }

    }
    return $true

}

function Assert-VSO7NativeBackupEntrySemanticsVSO {

    param([Parameter(Mandatory=$true)]$Entry,[Parameter(Mandatory=$true)][string[]]$FeatureIds)
    $type=[string]$Entry.Type
    if([string]::IsNullOrWhiteSpace($type)){
        throw 'Recovery nativo Schema 2 contiene Entry.Type vacio.'
    }
    $primitive=''
    if($Entry.PSObject.Properties.Name-contains'Primitive'){
        $primitive=[string]$Entry.Primitive
    }
    if(-not[string]::IsNullOrWhiteSpace($primitive)-and@('GraphicsCompositeToken','HAGS')-notcontains$primitive){
        throw ('Recovery nativo Schema 2 contiene Primitive desconocido: {0}.'-f$primitive)
    }
    $native=@((Get-VSO7NativeDataVSO).Features)
    $matched=$false
    foreach($featureId in @($FeatureIds)){

        if([string]$featureId-ieq'V7GP-PERAPP'){

            $perAppShape=($type-ieq'RegistryValue')-and($primitive-ieq'GraphicsCompositeToken')-and([string]$Entry.Path-ieq[string]$script:VSO7GraphicsUserPreferencePath)-and(@('GpuPreference','SwapEffectUpgradeEnable')-icontains([string]$Entry.TokenKey))-and(-not[string]::IsNullOrWhiteSpace([string]$Entry.Name))
            if($perAppShape){

                try{
                    $appPath=[IO.Path]::GetFullPath([string]$Entry.Name);
                    if([IO.Path]::IsPathRooted($appPath)-and[IO.Path]::GetExtension($appPath)-ieq'.exe'){
                        $matched=$true
                    }
                }catch{}

            }
            if($matched){
                break
            }
            continue

        }
        $def=@($native|Where-Object{
            [string]$_.FeatureId-ceq[string]$featureId
        }|Select-Object -First 1)
        if($def.Count-ne1){
            continue
        }
        $mode=[string]$def[0].Mode;
        $ops=@($def[0].Apply)
        switch($type){

            'RegistryValue' {

                if($primitive-ieq'HAGS'){

                    if($featureId-in@('V7GP003','V7GP004')-and[string]$Entry.Path-ieq'HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'-and[string]$Entry.Name-ieq'HwSchMode'){
                        $matched=$true
                    }

                }elseif($primitive-ieq'GraphicsCompositeToken'){

                    if($featureId-in@('V7GP001','V7GP002')-and[string]$Entry.Path-ieq[string]$script:VSO7GraphicsUserPreferencePath-and[string]$Entry.Name-ieq'DirectXUserGlobalSettings'-and[string]$Entry.TokenKey-ieq'SwapEffectUpgradeEnable'){
                        $matched=$true
                    }

                }elseif([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'Registry'){

                    if(@($ops|Where-Object{
                        [string]$_.Action-in@('SetValue','DeleteValue')-and[string]$_.Path-ieq[string]$Entry.Path-and[string]$_.Name-ieq[string]$Entry.Name
                    }).Count-gt0){
                        $matched=$true
                    }

                }

            }
            'RegistryKey' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'Registry'-and@($ops|Where-Object{
                    [string]$_.Action-ieq'DeleteKey'-and[string]$_.Path-ieq[string]$Entry.Path
                }).Count-gt0){
                    $matched=$true
                }
            }
            'PowerSetting' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'PowerSetting'-and@($ops|Where-Object{
                    [string]$_.SubGroupAlias-ieq[string]$Entry.SubGroupAlias-and[string]$_.SettingAlias-ieq[string]$Entry.SettingAlias
                }).Count-gt0){
                    $matched=$true
                }
            }
            'NetAdapterRss' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'NetAdapterRss'-and@($ops|Where-Object{
                    [string]$_.Action-ieq'EnableRss'
                }).Count-gt0){
                    $matched=$true
                }
            }
            'NetAdapterAdvancedProperty' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'NetAdapterAdvanced'-and@($ops|ForEach-Object{
                    @($_.Properties)
                }|Where-Object{
                    [string]$_.RegistryKeyword-ieq[string]$Entry.RegistryKeyword
                }).Count-gt0){
                    $matched=$true
                }
            }
            'NetOffloadGlobal' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'NetOffloadGlobal'-and@($ops|Where-Object{
                    [string]$_.Property-ieq[string]$Entry.Property
                }).Count-gt0){
                    $matched=$true
                }
            }
            'NetTcpSetting' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'NetTcpSetting'-and@($ops|Where-Object{
                    [string]$_.Property-ieq[string]$Entry.Property
                }).Count-gt0){
                    $matched=$true
                }
            }
            'NetTcpCimSetting' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'NetTcpCimSetting'-and@($ops|Where-Object{
                    [string]$_.Property-ieq[string]$Entry.Property
                }).Count-gt0){
                    $matched=$true
                }
            }
            'FsutilNtfsTrim' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'FsutilTrim'-and@($ops|Where-Object{
                    [string]$_.Action-ieq'EnableNtfsTrim'
                }).Count-gt0){
                    $matched=$true
                }
            }
            'ScheduledTaskState' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'ScheduledTaskState'-and@($ops|Where-Object{
                    [string]$_.TaskPath-ieq[string]$Entry.TaskPath-and[string]$_.TaskName-ieq[string]$Entry.TaskName
                }).Count-gt0){
                    $matched=$true
                }
            }
            'NetAdapterPower' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$mode-ieq'NetAdapterPower'-and@($ops|Where-Object{
                    [string]$_.Property-ieq[string]$Entry.Property
                }).Count-gt0){
                    $matched=$true
                }
            }
            'OptionalFeature' {

                if([string]::IsNullOrWhiteSpace($primitive)-and(($featureId-ieq'V7OF001'-and[string]$Entry.Name-ieq'Containers-DisposableClientVM')-or($featureId-ieq'V7OF002'-and[string]$Entry.Name-in@('VirtualMachinePlatform','Microsoft-Windows-Subsystem-Linux')))){
                    $matched=$true
                }

            }
            'NonReversible' {
                if([string]::IsNullOrWhiteSpace($primitive)-and$featureId-in@('V7SP003','V7SP004','V7TB007','V7SP008')-and[string]$Entry.Id-ieq[string]$featureId){
                    $matched=$true
                }
            }

        }
        if($matched){
            break
        }

    }
    if(-not$matched){
        throw ('Recovery nativo Schema 2 contiene una entrada {0}/{1} cuyo target no pertenece a las features propietarias de la sesion.'-f$type,$primitive)
    }
    return $true

}

function ConvertTo-VSO7ValidatedNativeBackupSessionVSO {

    param([Parameter(Mandatory=$true)]$Object,[Parameter(Mandatory=$true)][string]$Directory)
    if($null-eq$Object-or$Object-is[string]){
        throw 'Recovery nativo contiene un state.json vacio o con tipo invalido.'
    }
    $properties=@($Object.PSObject.Properties.Name)
    foreach($required in @('CreatedAt','Features','Status','Entries')){
        if($properties-notcontains$required){
            throw ('Recovery nativo incompleto: falta {0}.'-f$required)
        }
    }
    if($Object.CreatedAt-is[datetime]-or$Object.CreatedAt-is[datetimeoffset]){
        $created=[datetimeoffset]$Object.CreatedAt
    }else{
        $created=[datetimeoffset]::MinValue;
        if(-not($Object.CreatedAt-is[string])-or[string]::IsNullOrWhiteSpace([string]$Object.CreatedAt)-or-not[datetimeoffset]::TryParse([string]$Object.CreatedAt,[ref]$created)){
            throw 'Recovery nativo contiene CreatedAt invalido.'
        }
    }
    if($null-eq$Object.Features-or$Object.Features-is[string]){
        throw 'Recovery nativo contiene Features invalido.'
    }
    $features=@($Object.Features)
    foreach($feature in $features){
        if($null-eq$feature-or-not($feature-is[string])-or[string]::IsNullOrWhiteSpace([string]$feature)-or([string]$feature).Length-gt128){
            throw 'Recovery nativo contiene un FeatureId invalido.'
        }
    }
    if(-not($Object.Status-is[string])-or@('Pending','Applied','Partial','RestoreIncomplete','Restored')-notcontains[string]$Object.Status){
        throw 'Recovery nativo contiene Status invalido.'
    }
    if([string]$Object.Status-cne'Restored'-and$features.Count-eq0){
        throw 'Recovery nativo activo no identifica ninguna feature; ownership desconocido.'
    }
    if($null-eq$Object.Entries-or$Object.Entries-is[string]){
        throw 'Recovery nativo contiene Entries invalido.'
    }
    $entries=@($Object.Entries)
    if($entries.Count-gt4096){
        throw 'Recovery nativo excede el limite de 4096 Entries.'
    }
    foreach($entry in $entries){
        if($null-eq$entry-or$entry-is[string]){
            throw 'Recovery nativo contiene una entrada invalida.'
        }
    }
    $schema=1
    if($properties-contains'Schema'-and$null-ne$Object.Schema){
        if(-not[int]::TryParse([string]$Object.Schema,[ref]$schema)-or$schema-lt1-or$schema-gt2){
            throw 'Recovery nativo usa un Schema no soportado.'
        }
    }
    if($schema-lt2){

        $modernSessionMarkers=@('BatchKind','BatchId','BatchObjective','PreflightBaselines','FeatureResults')|Where-Object{
            $properties-contains$_
        }
        $modernEntryMarkers=@($Object.Entries|Where-Object{
            $entryProps=@($_.PSObject.Properties.Name);($entryProps-contains'Key')-or($entryProps-contains'Status')-or@($entryProps|Where-Object{
                $_-match'^(Intended|Applied|Owns|Baseline)'
            }).Count-gt0
        })
        if($modernSessionMarkers.Count-gt0-or$modernEntryMarkers.Count-gt0){
            throw 'Recovery nativo parece un journal Schema 2 degradado/manipulado; no se permite fallback legacy.'
        }

    }else{

        if($properties-notcontains'Version'-or-not($Object.Version-is[string])-or[string]::IsNullOrWhiteSpace([string]$Object.Version)){
            throw 'Recovery nativo Schema 2 no contiene Version valida.'
        }
        if([string]$Object.Version-cne[string]$script:Version){
            throw ('Recovery nativo Schema 2 pertenece a VSO7 {0}; esta build exige VSO7 {1}.'-f[string]$Object.Version,[string]$script:Version)
        }
        $producerRevision=$null
        if($properties-contains'ProducerRevision'){

            $producerInt=0
            if($null-eq$Object.ProducerRevision-or-not[int]::TryParse([string]$Object.ProducerRevision,[ref]$producerInt)-or$producerInt-lt24-or$producerInt-gt[int]$script:NativeJournalRevision){
                throw 'Recovery nativo Schema 2 contiene ProducerRevision invalida/no soportada.'
            }
            $producerRevision=[Nullable[int]]$producerInt

        }
        $seenEntryKeys=@{}
        foreach($entry in $entries){

            $entry=ConvertTo-VSO7NormalizedSchema2EntryVSO -Entry $entry -ProducerRevision $producerRevision
            [void](Assert-VSO7NativeBackupEntryShapeVSO -Entry $entry)
            $identity=([string]$entry.Key).ToLowerInvariant()
            if($seenEntryKeys.ContainsKey($identity)){
                throw ('Recovery nativo Schema 2 contiene Entry.Key duplicado: {0}.'-f[string]$entry.Key)
            }
            $seenEntryKeys[$identity]=$true
            [void](Assert-VSO7NativeBackupEntrySemanticsVSO -Entry $entry -FeatureIds @($features))

        }

    }
    $Object|Add-Member -NotePropertyName Directory -NotePropertyValue $Directory -Force
    return $Object

}

function Get-VSO7NativeBackupInventoryVSO {

    param([switch]$SkipInvalid)
    $root=Get-VSO7NativeBackupRootVSO
    try{
        $directories=@(Get-ChildItem -LiteralPath $root -Directory -ErrorAction Stop)
    }catch{
        throw ('No se puede enumerar Recovery nativo de forma segura: {0}'-f$_.Exception.Message)
    }
    $valid=@();
    $invalid=@()
    foreach($directory in $directories){

        try{

            if(($directory.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ('Recovery nativo rechaza directorio de sesion reparse point: {0}.'-f$directory.FullName)
            }
            $state=Join-Path $directory.FullName 'state.json';
            if(-not(Test-Path -LiteralPath $state -PathType Leaf)){
                throw ('Recovery nativo incompleto: falta state.json en {0}.'-f$directory.FullName)
            }
            $stateItem=Get-Item -LiteralPath $state -Force -ErrorAction Stop;
            if($stateItem.PSIsContainer-or($stateItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                throw ('Recovery nativo rechaza state.json contenedor/reparse point: {0}.'-f$state)
            }
            $object=Get-Content -LiteralPath $state -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop;
            $valid+=,(ConvertTo-VSO7ValidatedNativeBackupSessionVSO -Object $object -Directory $directory.FullName)

        }catch{

            if(-not$SkipInvalid){
                throw ('No se puede validar Recovery nativo en {0}: {1}'-f$directory.FullName,$_.Exception.Message)
            }
            $invalid+=[pscustomobject]@{
                Directory=[string]$directory.FullName;
                Error=[string]$_.Exception.Message
            }
            Write-VSO7Log ("Recovery nativo conserva visible una sesion invalida: {0}: {1}"-f$directory.FullName,$_.Exception.Message) 'WARN'

        }

    }
    return [pscustomobject]@{
        Valid=@($valid|Sort-Object CreatedAt -Descending);
        Invalid=@($invalid);
        InvalidCount=@($invalid).Count;
        TotalCount=(@($valid).Count+@($invalid).Count)
    }

}

function Get-VSO7NativeBackupSessionsVSO {

    param([switch]$SkipInvalid)
    $inventory=Get-VSO7NativeBackupInventoryVSO -SkipInvalid:$SkipInvalid
    return @($inventory.Valid)

}

function Restore-VSO7NativeBackupSessionLegacyVSO {

    param([Parameter(Mandatory=$true)]$Session,[switch]$RequirePerEntryConfirmation)
    $entries=@($Session.Entries);
    $ok=$true
    for($i=$entries.Count-1;$i-ge0;$i--){

        $e=$entries[$i]
        try{

            if($RequirePerEntryConfirmation){
                $target=('{0}: {1}'-f[string]$e.Type,([string]$e.Key));
                if(-not(Confirm-Word -Word 'LEGACY' -Message ('Recovery legacy sin ownership moderno. Escribe LEGACY para restaurar SOLO '+$target))){
                    $ok=$false;
                    Write-VSO7Log ('Entrada legacy omitida por falta de confirmacion explicita: '+$target) 'WARN';
                    continue
                }
            }
            switch([string]$e.Type){

                'RegistryValue' {
                    if([bool]$e.Exists){
                        Set-VSO7NativeRegistryValueRawVSO -Path ([string]$e.Path) -Name ([string]$e.Name) -Kind ([string]$e.Kind) -Value $e.Value
                    }else{
                        Remove-VSO7NativeRegistryValueRawVSO -Path ([string]$e.Path) -Name ([string]$e.Name)
                    }
                }
                'RegistryKey' {

                    if([bool]$e.Exists){

                        $sessionDir=[IO.Path]::GetFullPath([string]$Session.Directory).TrimEnd('\')
                        $file=[IO.Path]::GetFullPath([string]$e.ExportFile)
                        if(-not$file.StartsWith(($sessionDir+'\'),[StringComparison]::OrdinalIgnoreCase)){
                            throw 'Backup .reg fuera de la sesion nativa.'
                        }
                        if([IO.Path]::GetExtension($file)-ine'.reg'){
                            throw 'Extension de backup Registry no valida.'
                        }
                        if(-not(Test-Path -LiteralPath $file -PathType Leaf)){
                            throw 'Falta un .reg de backup nativo.'
                        }
                        $fileInfo=Get-Item -LiteralPath $file -Force -ErrorAction Stop
                        if(($fileInfo.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                            throw 'Backup .reg no puede ser un reparse point.'
                        }
                        # Valida alcance/formato antes de tocar la clave actual. Los backups legacy no tienen hash persistido.
                        [void](Assert-VSO7NativeRegistryExportFileVSO -FilePath $file -ExpectedRegistryPath ([string]$e.Path))
                        Remove-VSO7NativeRegistryKeyRawVSO -Path ([string]$e.Path)
                        $reg=Resolve-VSOSystemExecutable -Name 'reg.exe';
                        & $reg import $file | Out-Null;
                        $rc=$LASTEXITCODE;
                        if($rc-ne0){
                            throw ('reg import termino con codigo {0}'-f$rc)
                        }

                    }else{
                        Remove-VSO7NativeRegistryKeyRawVSO -Path ([string]$e.Path)
                    }

                }
                'OptionalFeature' {

                    switch([string]$e.State){

                        'Enabled' {
                            Dism\Enable-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -NoRestart -ErrorAction Stop|Out-Null
                        }
                        'Disabled' {
                            Dism\Disable-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -NoRestart -ErrorAction Stop|Out-Null
                        }
                        default {
                            throw ('Estado previo de Optional Feature no restaurable automaticamente: {0}'-f$e.State)
                        }

                    }
                    $featureAfter=Dism\Get-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -ErrorAction Stop
                    $expectedState=[string]$e.State;
                    $afterState=[string]$featureAfter.State;
                    $afterClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $afterState
                    if($expectedState-ceq'Enabled'){
                        $stateMatches=($afterClass-in@('Enabled','EnablePending'))
                    }else{
                        $stateMatches=($afterClass-in@('Disabled','DisablePending'))
                    }
                    if(-not$stateMatches){
                        throw ('Optional Feature {0} no volvio al baseline {1} ni quedo pendiente de completarlo.'-f$e.Name,$expectedState)
                    }
                    if($afterClass-in@('EnablePending','DisablePending')){
                        $e|Add-Member -NotePropertyName RestoreEffectiveState -NotePropertyValue $afterState -Force;
                        $e|Add-Member -NotePropertyName RestartRequirement -NotePropertyValue 'SystemRestart' -Force
                    }

                }
                'NonReversible' {
                    Write-VSO7Log ("Historial irreversible conservado sin deuda de Recovery: {0}"-f$e.Description) 'WARN';
                    continue
                }
                default {
                    throw ('Tipo de entrada Recovery legado no soportado: {0}'-f$e.Type)
                }

            }

        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar entrada nativa {0}: {1}"-f$e.Type,$_.Exception.Message) 'ERROR'
        }

    }
    $state=Join-Path ([string]$Session.Directory) 'state.json'
    $Session.Status=if($ok){
        'Restored'
    }else{
        'RestoreIncomplete'
    }
    try{
        ConvertTo-VSO7NativeBackupSessionPersistObjectVSO -Session $Session -LegacyShape|ConvertTo-Json -Depth 12|Set-Content -LiteralPath ($state+'.tmp') -Encoding UTF8 -Force -ErrorAction Stop;
        [void](Commit-VSO7AtomicFileVSO -SourcePath ($state+'.tmp') -DestinationPath $state)
    }catch{
        if($ok){
            $Session.Status='RestoreIncomplete'
        };
        Write-VSO7Log ("No se pudo persistir el estado final de Recovery legado: {0}"-f$_.Exception.Message) 'ERROR';
        return $false
    }
    return $ok

}

function Get-VSO7RecoveryOwnershipDecisionVSO {

    param(
        [Parameter(Mandatory=$true)][bool]$CurrentMatchesBaseline,
        [Parameter(Mandatory=$true)][bool]$CurrentMatchesIntended,
        [Parameter(Mandatory=$true)][bool]$CurrentMatchesApplied,
        [Parameter(Mandatory=$true)][ValidateSet('Pending','Applied')][string]$Status
    )
    if($CurrentMatchesBaseline){
        return 'Baseline'
    }
    if($Status-eq'Pending' -and $CurrentMatchesIntended){
        return 'Owned'
    }
    if($Status-eq'Applied' -and $CurrentMatchesApplied){
        return 'Owned'
    }
    return 'Drift'

}

function Restore-VSO7NativeRegistryValueEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    if(($Entry.PSObject.Properties.Name-contains'Primitive')-and[string]$Entry.Primitive-ceq'GraphicsCompositeToken'){

        return [bool](Restore-VSO7GraphicsCompositeEntryVSO -Entry $Entry)

    }
    $current=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)
    $baseline=[pscustomobject]@{
        Exists=[bool]$Entry.Exists;
        Kind=$Entry.Kind;
        Value=$Entry.Value
    }
    $intended=[pscustomobject]@{
        Exists=[bool]$Entry.IntendedExists;
        Kind=$Entry.IntendedKind;
        Value=$Entry.IntendedValue
    }
    $applied=[pscustomobject]@{
        Exists=[bool]$Entry.AppliedExists;
        Kind=$Entry.AppliedKind;
        Value=$Entry.AppliedValue
    }
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline (Test-VSO7NativeRegistrySnapshotEqualVSO -A $current -B $baseline) -CurrentMatchesIntended (Test-VSO7NativeRegistrySnapshotEqualVSO -A $current -B $intended) -CurrentMatchesApplied (Test-VSO7NativeRegistrySnapshotEqualVSO -A $current -B $applied) -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    }
    if($decision-ne'Owned'){
        throw ('Drift/ownership ambiguo en Registry {0}\{1}; VSO7 no sobrescribe el cambio externo.'-f$Entry.Path,$Entry.Name)
    }
    if([bool]$Entry.Exists){
        Set-VSO7NativeRegistryValueRawVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name) -Kind ([string]$Entry.Kind) -Value $Entry.Value
    }else{
        Remove-VSO7NativeRegistryValueRawVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)
    }
    $after=Get-VSO7NativeRegistrySnapshotVSO -Path ([string]$Entry.Path) -Name ([string]$Entry.Name)
    if(-not(Test-VSO7NativeRegistrySnapshotEqualVSO -A $after -B $baseline)){
        throw 'Rollback Registry no coincidio con baseline.'
    }
    if(($Entry.PSObject.Properties.Name-contains'Primitive')-and[string]$Entry.Primitive-ceq'HAGS'){

        $Entry|Add-Member -NotePropertyName RestoreConfigurationVerification -NotePropertyValue 'PASS' -Force
        $Entry|Add-Member -NotePropertyName RestoreEffectiveVerification -NotePropertyValue 'PendingReboot' -Force
        $Entry|Add-Member -NotePropertyName RestoreEffectiveState -NotePropertyValue 'PendingReboot' -Force
        $Entry|Add-Member -NotePropertyName RestartRequirement -NotePropertyValue 'SystemRestart' -Force

    }
    return $true

}

function Restore-VSO7NativePowerEntryVSO {
    param([Parameter(Mandatory=$true)]$Entry)
    $ownsAC=if($Entry.PSObject.Properties.Name-contains'OwnsAC'){[bool]$Entry.OwnsAC}else{$true}
    $ownsDC=if($Entry.PSObject.Properties.Name-contains'OwnsDC'){[bool]$Entry.OwnsDC}else{$true}
    if(-not$ownsAC-and-not$ownsDC){throw 'PowerSetting Recovery no contiene ownership AC/DC valido.'}
    $cur=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias ([string]$Entry.SubGroupAlias) -SettingAlias ([string]$Entry.SettingAlias) -SchemeGuid ([string]$Entry.SchemeGuid)
    function Get-R76PowerSideDecision([bool]$Owned,[int]$Current,[int]$Baseline,$Intended,$Applied,[string]$Status){
        if(-not$Owned){return 'Unowned'}
        if($Current-eq$Baseline){return 'Baseline'}
        if($Status-eq'Pending'-and$null-ne$Intended-and$Current-eq[int]$Intended){return 'Owned'}
        if($null-ne$Applied-and$Current-eq[int]$Applied){return 'Owned'}
        if($Status-eq'Applied'-and$null-ne$Intended-and$Current-eq[int]$Intended){return 'Owned'}
        return 'Drift'
    }
    $acDecision=Get-R76PowerSideDecision $ownsAC ([int]$cur.AC) ([int]$Entry.AC) $Entry.IntendedAC $Entry.AppliedAC ([string]$Entry.Status)
    $dcDecision=Get-R76PowerSideDecision $ownsDC ([int]$cur.DC) ([int]$Entry.DC) $Entry.IntendedDC $Entry.AppliedDC ([string]$Entry.Status)
    $sub=Get-PowerAliasGuidVSO -Alias ([string]$Entry.SubGroupAlias);$setting=Get-PowerAliasGuidVSO -Alias ([string]$Entry.SettingAlias)
    if($acDecision-eq'Owned'){Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setacvalueindex',[string]$Entry.SchemeGuid,$sub,$setting,[string]$Entry.AC)|Out-Null}
    if($dcDecision-eq'Owned'){Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setdcvalueindex',[string]$Entry.SchemeGuid,$sub,$setting,[string]$Entry.DC)|Out-Null}
    $active=[string](Get-ActivePowerSchemeGuid);if($active-ieq[string]$Entry.SchemeGuid-and($acDecision-eq'Owned'-or$dcDecision-eq'Owned')){Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive',[string]$Entry.SchemeGuid)|Out-Null}
    $after=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias ([string]$Entry.SubGroupAlias) -SettingAlias ([string]$Entry.SettingAlias) -SchemeGuid ([string]$Entry.SchemeGuid)
    if($acDecision-ne'Drift'-and$ownsAC-and$after.AC-ne[int]$Entry.AC){throw 'Rollback PowerSetting no restauro AC al baseline.'}
    if($dcDecision-ne'Drift'-and$ownsDC-and$after.DC-ne[int]$Entry.DC){throw 'Rollback PowerSetting no restauro DC al baseline.'}
    if([string](Get-ActivePowerSchemeGuid)-ine$active){throw 'Rollback PowerSetting cambio el plan activo inesperadamente.'}
    $drift=@();if($acDecision-eq'Drift'){$drift+='AC'};if($dcDecision-eq'Drift'){$drift+='DC'}
    if($drift.Count){throw ('PowerSetting presenta drift externo en '+($drift-join'/')+'; los lados atribuibles a VSO7 se restauraron sin sobrescribir el drift.')}
    return $true
}

function Restore-VSO7NativeRssEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7RssCurrentForEntryVSO -Entry $Entry
    $matchesBaseline=([bool]$cur.Enabled-eq[bool]$Entry.Enabled)
    $matchesIntended=([bool]$cur.Enabled-eq[bool]$Entry.IntendedEnabled)
    $matchesApplied=($null-ne$Entry.AppliedEnabled-and[bool]$cur.Enabled-eq[bool]$Entry.AppliedEnabled)
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline $matchesBaseline -CurrentMatchesIntended $matchesIntended -CurrentMatchesApplied $matchesApplied -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    }
    if($decision-ne'Owned'){
        throw 'RSS presenta drift externo; VSO7 no lo sobrescribe.'
    }
    if($Entry.PSObject.Properties.Name-contains'InterfaceGuid'-and-not[string]::IsNullOrWhiteSpace([string]$Entry.InterfaceGuid)){
        $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $Entry;
        $name=[string]$adapter.Name;
        if([bool]$Entry.Enabled){
            Enable-NetAdapterRss -Name $name -Confirm:$false -ErrorAction Stop|Out-Null
        }else{
            Disable-NetAdapterRss -Name $name -Confirm:$false -ErrorAction Stop|Out-Null
        }
    }
    else{
        $desc=[string]$Entry.InterfaceDescription;
        if([bool]$Entry.Enabled){
            Enable-NetAdapterRss -InterfaceDescription $desc -Confirm:$false -ErrorAction Stop|Out-Null
        }else{
            Disable-NetAdapterRss -InterfaceDescription $desc -Confirm:$false -ErrorAction Stop|Out-Null
        }
    }
    $after=Get-VSO7RssCurrentForEntryVSO -Entry $Entry
    if([bool]$after.Enabled-ne[bool]$Entry.Enabled){
        throw 'Rollback RSS no coincidio con baseline.'
    }
    return $true

}

function Restore-VSO7NativeAdapterPropertyEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $Entry -RegistryKeyword ([string]$Entry.RegistryKeyword);
    if($null-eq$cur){
        throw 'La propiedad NIC ya no existe; rollback fail-closed.'
    }
    $matchesBaseline=Test-VSO7StringSequenceEqualVSO -A $cur.RegistryValue -B $Entry.RegistryValue
    $matchesIntended=Test-VSO7StringSequenceEqualVSO -A $cur.RegistryValue -B $Entry.IntendedValue
    $matchesApplied=($null-ne$Entry.AppliedValue-and(Test-VSO7StringSequenceEqualVSO -A $cur.RegistryValue -B $Entry.AppliedValue))
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline $matchesBaseline -CurrentMatchesIntended $matchesIntended -CurrentMatchesApplied $matchesApplied -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    };
    if($decision-ne'Owned'){
        throw 'Propiedad NIC presenta drift externo; VSO7 no la sobrescribe.'
    }
    $adapter=Resolve-VSO7NetAdapterIdentityVSO -Identity $Entry
    Set-NetAdapterAdvancedProperty -Name ([string]$adapter.Name) -RegistryKeyword ([string]$Entry.RegistryKeyword) -RegistryValue ([string[]]@($Entry.RegistryValue)) -Confirm:$false -ErrorAction Stop|Out-Null
    [void](Resolve-VSO7NetAdapterIdentityVSO -Identity $Entry -WaitMilliseconds 10000)
    $after=Get-VSO7AdapterAdvancedPropertySnapshotVSO -Identity $Entry -RegistryKeyword ([string]$Entry.RegistryKeyword)
    if($null-eq$after-or-not(Test-VSO7StringSequenceEqualVSO -A $after.RegistryValue -B $Entry.RegistryValue)){
        throw 'Rollback de propiedad NIC no coincidio con baseline.'
    };
    return $true

}

function Restore-VSO7NativeGlobalOffloadEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7GlobalOffloadStateVSO -Property ([string]$Entry.Property)
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline ($cur-ceq[string]$Entry.Value) -CurrentMatchesIntended ($cur-ceq[string]$Entry.IntendedValue) -CurrentMatchesApplied ($null-ne$Entry.AppliedValue-and$cur-ceq[string]$Entry.AppliedValue) -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    };
    if($decision-ne'Owned'){
        throw 'Global offload presenta drift externo; VSO7 no lo sobrescribe.'
    }
    Set-VSO7GlobalOffloadStateVSO -Property ([string]$Entry.Property) -Value ([string]$Entry.Value)
    if((Get-VSO7GlobalOffloadStateVSO -Property ([string]$Entry.Property))-cne[string]$Entry.Value){
        throw 'Rollback global offload no coincidio con baseline configurado.'
    }
    if([string]$Entry.Property-ieq'TaskOffload'){

        if(-not($Entry.PSObject.Properties.Name-contains'RestoreEffectiveState')){
            $Entry|Add-Member -NotePropertyName RestoreEffectiveState -NotePropertyValue 'PendingRestart'
        }else{
            $Entry.RestoreEffectiveState='PendingRestart'
        }

    }
    return $true

}

function Restore-VSO7NativeTcpSettingEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7TcpSettingValueVSO -SettingName ([string]$Entry.SettingName) -Property ([string]$Entry.Property)
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline ($cur-ceq[string]$Entry.Value) -CurrentMatchesIntended ($cur-ceq[string]$Entry.IntendedValue) -CurrentMatchesApplied ($null-ne$Entry.AppliedValue-and$cur-ceq[string]$Entry.AppliedValue) -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    };
    if($decision-ne'Owned'){
        throw 'TCP setting presenta drift externo; VSO7 no lo sobrescribe.'
    }
    Set-VSO7TcpSettingValueVSO -SettingName ([string]$Entry.SettingName) -Property ([string]$Entry.Property) -Value ([string]$Entry.Value)
    if((Get-VSO7TcpSettingValueVSO -SettingName ([string]$Entry.SettingName) -Property ([string]$Entry.Property))-cne[string]$Entry.Value){
        throw 'Rollback TCP setting no coincidio con baseline.'
    };
    return $true

}

function Restore-VSO7NativeFsutilTrimEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7FsutilTrimStateVSO
    if([int]$cur.ReFsVolumeCount-gt0){
        throw 'Aparecio un volumen ReFS; rollback TRIM falla cerrado.'
    }
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline ([int]$cur.NtfsDisabled-eq[int]$Entry.Disabled) -CurrentMatchesIntended ([int]$cur.NtfsDisabled-eq[int]$Entry.IntendedDisabled) -CurrentMatchesApplied ($null-ne$Entry.AppliedDisabled-and[int]$cur.NtfsDisabled-eq[int]$Entry.AppliedDisabled) -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    };
    if($decision-ne'Owned'){
        throw 'TRIM NTFS presenta drift externo; VSO7 no lo sobrescribe.'
    }
    Set-VSO7NtfsTrimDisabledStateVSO -Disabled ([int]$Entry.Disabled)
    $after=Get-VSO7FsutilTrimStateVSO
    if([int]$after.ReFsVolumeCount-gt0-or[int]$after.NtfsDisabled-ne[int]$Entry.Disabled){
        throw 'Rollback TRIM NTFS no coincidio con baseline.'
    }
    return $true

}

function Restore-VSO7NativeScheduledTaskEntryVSO {
    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7ScheduledTaskSnapshotVSO -TaskPath ([string]$Entry.TaskPath) -TaskName ([string]$Entry.TaskName)
    $hasFull=($Entry.PSObject.Properties.Name-contains'BaselineDefinitionSha256')-and-not[string]::IsNullOrWhiteSpace([string]$Entry.BaselineDefinitionSha256)
    $hasCore=($Entry.PSObject.Properties.Name-contains'BaselineDefinitionCoreSha256')-and-not[string]::IsNullOrWhiteSpace([string]$Entry.BaselineDefinitionCoreSha256)
    $baselineDefinitionMatches=if($hasCore){[string]$cur.DefinitionCoreSha256-ceq[string]$Entry.BaselineDefinitionCoreSha256}elseif($hasFull){[string]$cur.DefinitionSha256-ceq[string]$Entry.BaselineDefinitionSha256}else{$true}
    $hasAppliedFull=($Entry.PSObject.Properties.Name-contains'AppliedDefinitionSha256')-and-not[string]::IsNullOrWhiteSpace([string]$Entry.AppliedDefinitionSha256)
    $hasAppliedCore=($Entry.PSObject.Properties.Name-contains'AppliedDefinitionCoreSha256')-and-not[string]::IsNullOrWhiteSpace([string]$Entry.AppliedDefinitionCoreSha256)
    $appliedDefinitionMatches=if($hasAppliedCore){[string]$cur.DefinitionCoreSha256-ceq[string]$Entry.AppliedDefinitionCoreSha256}elseif($hasAppliedFull){[string]$cur.DefinitionSha256-ceq[string]$Entry.AppliedDefinitionSha256}elseif(-not$hasFull){$true}else{$false}
    $matchesBaseline=([bool]$cur.Enabled-eq[bool]$Entry.Enabled)-and$baselineDefinitionMatches
    # R80 journals persist a definition fingerprint with Enabled normalized out. During Pending,
    # matching IntendedEnabled + the unchanged core definition proves the interrupted toggle is ours.
    $matchesIntended=([bool]$cur.Enabled-eq[bool]$Entry.IntendedEnabled)-and$baselineDefinitionMatches
    $matchesApplied=($null-ne$Entry.AppliedEnabled-and[bool]$cur.Enabled-eq[bool]$Entry.AppliedEnabled)-and$appliedDefinitionMatches
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline $matchesBaseline -CurrentMatchesIntended $matchesIntended -CurrentMatchesApplied $matchesApplied -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){return $true}
    if($decision-ne'Owned'){throw 'Tarea programada presenta drift externo de estado o definicion; VSO7 no la sobrescribe.'}
    Set-VSO7ScheduledTaskEnabledVSO -TaskPath ([string]$Entry.TaskPath) -TaskName ([string]$Entry.TaskName) -Enabled ([bool]$Entry.Enabled)
    $after=Get-VSO7ScheduledTaskSnapshotVSO -TaskPath ([string]$Entry.TaskPath) -TaskName ([string]$Entry.TaskName)
    $afterDefinitionMatches=if($hasCore){[string]$after.DefinitionCoreSha256-ceq[string]$Entry.BaselineDefinitionCoreSha256}elseif($hasFull){[string]$after.DefinitionSha256-ceq[string]$Entry.BaselineDefinitionSha256}else{$true}
    if([bool]$after.Enabled-ne[bool]$Entry.Enabled-or-not$afterDefinitionMatches){throw 'Rollback de tarea programada no coincidio con baseline de estado/definicion.'}
    return $true
}

function Restore-VSO7NativeNetAdapterPowerEntryVSO {

    param([Parameter(Mandatory=$true)]$Entry)
    $cur=Get-VSO7NetAdapterPowerSnapshotVSO -Identity $Entry -Property ([string]$Entry.Property)
    if(-not[bool]$cur.Supported){
        throw 'La capability de energia NIC ya no esta soportada; rollback fail-closed.'
    }
    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline ([string]$cur.Value-ceq[string]$Entry.Value) -CurrentMatchesIntended ([string]$cur.Value-ceq[string]$Entry.IntendedValue) -CurrentMatchesApplied ($null-ne$Entry.AppliedValue-and[string]$cur.Value-ceq[string]$Entry.AppliedValue) -Status ([string]$Entry.Status)
    if($decision-eq'Baseline'){
        return $true
    };
    if($decision-ne'Owned'){
        throw 'NIC power presenta drift externo; VSO7 no lo sobrescribe.'
    }
    Set-VSO7NetAdapterPowerValueVSO -Identity $Entry -Property ([string]$Entry.Property) -Value ([string]$Entry.Value)
    $after=Get-VSO7NetAdapterPowerSnapshotVSO -Identity $Entry -Property ([string]$Entry.Property)
    if([string]$after.Value-cne[string]$Entry.Value){
        throw 'Rollback NIC power no coincidio con baseline configurado.'
    }
    if(-not($Entry.PSObject.Properties.Name-contains'RestoreEffectiveState')){
        $Entry|Add-Member -NotePropertyName RestoreEffectiveState -NotePropertyValue 'PendingRestart'
    }else{
        $Entry.RestoreEffectiveState='PendingRestart'
    }
    return $true

}

function Restore-VSO7NativeBackupSessionVSO {

    param([Parameter(Mandatory=$true)]$Session,[switch]$AllowLegacyRecovery)
    if([string]::IsNullOrWhiteSpace([string]$Session.Directory)){
        throw 'Recovery nativo no contiene Directory de sesion valido.'
    }
    $Session=ConvertTo-VSO7ValidatedNativeBackupSessionVSO -Object $Session -Directory ([string]$Session.Directory)
    if(-not($Session.PSObject.Properties.Name-contains'Schema')-or[int]$Session.Schema-lt2){
        if(-not$AllowLegacyRecovery){
            throw 'Recovery Schema 1 no tiene evidencia moderna de ownership/drift y no participa en restauracion automatica.'
        };
        return [bool](Restore-VSO7NativeBackupSessionLegacyVSO -Session $Session -RequirePerEntryConfirmation)
    }
    $entries=@($Session.Entries);
    $ok=$true
    for($i=$entries.Count-1;$i-ge0;$i--){

        $e=$entries[$i]
        try{

            switch([string]$e.Type){

                'RegistryValue' {
                    [void](Restore-VSO7NativeRegistryValueEntryVSO -Entry $e)
                }
                'RegistryKey' {

                    $current=Test-VSO7NativeRegistryKeyExistsVSO -Path ([string]$e.Path)
                    $baselineMatches=Test-VSO7NativeRegistryKeyBaselineMatchVSO -Entry $e
                    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline $baselineMatches -CurrentMatchesIntended ($current-eq[bool]$e.IntendedExists) -CurrentMatchesApplied ($null-ne$e.AppliedExists-and$current-eq[bool]$e.AppliedExists) -Status ([string]$e.Status)
                    if($decision-eq'Baseline'){
                        continue
                    }
                    if($decision-ne'Owned'){
                        throw 'RegistryKey presenta drift externo o baseline no demostrable; VSO7 no lo sobrescribe.'
                    }
                    if([bool]$e.Exists){

                        $sessionDir=[IO.Path]::GetFullPath([string]$Session.Directory).TrimEnd('\');
                        $file=[IO.Path]::GetFullPath([string]$e.ExportFile)
                        if(-not$file.StartsWith(($sessionDir+'\'),[StringComparison]::OrdinalIgnoreCase)-or[IO.Path]::GetExtension($file)-ine'.reg'){
                            throw 'Backup .reg fuera de la sesion o con extension invalida.'
                        }
                        $fi=Get-Item -LiteralPath $file -Force -ErrorAction Stop;
                        if(($fi.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
                            throw 'Backup .reg no puede ser reparse point.'
                        }
                        $expectedExportHash=if($e.PSObject.Properties.Name-contains'ExportSha256'){
                            [string]$e.ExportSha256
                        }else{
                            ''
                        }
                        [void](Assert-VSO7NativeRegistryExportFileVSO -FilePath $file -ExpectedRegistryPath ([string]$e.Path) -ExpectedSha256 $expectedExportHash)
                        $reg=Resolve-VSOSystemExecutable -Name 'reg.exe';
                        & $reg import $file|Out-Null;
                        if($LASTEXITCODE-ne0){
                            throw ('reg import termino con codigo {0}'-f$LASTEXITCODE)
                        }
                        if(($e.PSObject.Properties.Name-contains'BaselineFingerprint')-and-not[string]::IsNullOrWhiteSpace([string]$e.BaselineFingerprint)-and-not(Test-VSO7NativeRegistryKeyBaselineMatchVSO -Entry $e)){
                            throw 'Rollback RegistryKey importado no coincide con el fingerprint baseline.'
                        }

                    }else{

                        Remove-VSO7NativeRegistryKeyRawVSO -Path ([string]$e.Path)
                        if(Test-VSO7NativeRegistryKeyExistsVSO -Path ([string]$e.Path)){
                            throw 'Rollback RegistryKey no coincidio con baseline ausente.'
                        }

                    }

                }
                'OptionalFeature' {

                    $cur=(Dism\Get-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -ErrorAction Stop).State.ToString()
                    $baselineClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State ([string]$e.State)
                    if($baselineClass-notin@('Enabled','Disabled')){
                        throw 'Baseline Optional Feature invalido.'
                    }
                    $matchesIntended=Test-VSO7NativeOptionalFeaturePendingOwnedVSO -CurrentState $cur -IntendedState ([string]$e.IntendedState)
                    $matchesApplied=(-not[string]::IsNullOrWhiteSpace([string]$e.AppliedState)-and(Test-VSO7NativeOptionalFeatureAppliedOwnedVSO -CurrentState $cur -RecordedAppliedState ([string]$e.AppliedState)))
                    $decision=Get-VSO7RecoveryOwnershipDecisionVSO -CurrentMatchesBaseline ($cur-eq[string]$e.State) -CurrentMatchesIntended $matchesIntended -CurrentMatchesApplied $matchesApplied -Status ([string]$e.Status)
                    if($decision-eq'Baseline'){
                        continue
                    }
                    if($decision-ne'Owned'){
                        throw 'Optional Feature presenta drift externo; VSO7 no la sobrescribe.'
                    }
                    if($baselineClass-eq'Enabled'){
                        Dism\Enable-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -NoRestart -ErrorAction Stop|Out-Null
                    }else{
                        Dism\Disable-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -NoRestart -ErrorAction Stop|Out-Null
                    }
                    $after=(Dism\Get-WindowsOptionalFeature -Online -FeatureName ([string]$e.Name) -ErrorAction Stop).State.ToString();
                    $afterClass=Get-VSO7NativeOptionalFeatureStateClassVSO -State $after
                    $restoreMatches=($after-eq[string]$e.State)-or($baselineClass-eq'Enabled'-and$afterClass-eq'EnablePending')-or($baselineClass-eq'Disabled'-and$afterClass-eq'DisablePending')
                    if(-not$restoreMatches){
                        throw 'Rollback Optional Feature no coincidio con baseline ni quedo pendiente de completarlo.'
                    }
                    if($afterClass-in@('EnablePending','DisablePending')){
                        $e|Add-Member -NotePropertyName RestoreEffectiveState -NotePropertyValue $after -Force;
                        $e|Add-Member -NotePropertyName RestartRequirement -NotePropertyValue 'SystemRestart' -Force
                    }

                }
                'PowerSetting' {
                    [void](Restore-VSO7NativePowerEntryVSO -Entry $e)
                }
                'NetAdapterRss' {
                    [void](Restore-VSO7NativeRssEntryVSO -Entry $e)
                }
                'NetAdapterAdvancedProperty' {
                    [void](Restore-VSO7NativeAdapterPropertyEntryVSO -Entry $e)
                }
                'NetOffloadGlobal' {
                    [void](Restore-VSO7NativeGlobalOffloadEntryVSO -Entry $e)
                }
                'NetTcpSetting' {
                    [void](Restore-VSO7NativeTcpSettingEntryVSO -Entry $e)
                }
                'NetTcpCimSetting' {
                    [void](Restore-VSO7NativeTcpTimestampCimEntryVSO -Entry $e)
                }
                'FsutilNtfsTrim' {
                    [void](Restore-VSO7NativeFsutilTrimEntryVSO -Entry $e)
                }
                'ScheduledTaskState' {
                    [void](Restore-VSO7NativeScheduledTaskEntryVSO -Entry $e)
                }
                'NetAdapterPower' {
                    [void](Restore-VSO7NativeNetAdapterPowerEntryVSO -Entry $e)
                }
                'NonReversible' {
                    Write-VSO7Log ("Historial irreversible conservado sin deuda de Recovery: {0}"-f$e.Description) 'WARN';
                    continue
                }
                default {
                    throw ('Tipo de entrada nativa desconocido: {0}'-f$e.Type)
                }

            }

        }catch{
            $ok=$false;
            Write-VSO7Log ("No se pudo restaurar entrada nativa {0}: {1}"-f$e.Type,$_.Exception.Message) 'ERROR'
        }

    }
    $Session.Status=if($ok){
        'Restored'
    }else{
        'RestoreIncomplete'
    }
    try{
        Save-VSO7NativeBackupSessionVSO -Session $Session
    }catch{
        if($ok){
            $Session.Status='RestoreIncomplete'
        };
        Write-VSO7Log ("No se pudo persistir el estado final de Recovery nativo: {0}"-f$_.Exception.Message) 'ERROR';
        return $false
    }
    return $ok

}

function Select-VSO7NativeBackupSessionVSO {

    param(
        [Parameter(Mandatory=$true)][object[]]$Sessions,
        [string]$TitleEs='BACKUPS NATIVOS RECUPERABLES',
        [string]$TitleEn='RECOVERABLE NATIVE BACKUPS'
    )
    $ordered=@($Sessions|Sort-Object CreatedAt -Descending)
    if($ordered.Count-eq0){
        return $null
    }
    $isEn=($script:Language-eq'en')
    Write-CenteredLineVSO -Text $(if($isEn){
        $TitleEn
    }else{
        $TitleEs
    }) -Color $script:ThemeCopper
    $items=@()
    for($i=0;$i-lt$ordered.Count;$i++){

        $s=$ordered[$i]
        $kind=if(($s.PSObject.Properties.Name-contains'BatchKind')-and-not[string]::IsNullOrWhiteSpace([string]$s.BatchKind)){
            [string]$s.BatchKind
        }else{
            'Native'
        }
        $featureText=(@($s.Features|ForEach-Object{
            [string]$_
        })-join', ')
        if($featureText.Length-gt72){
            $featureText=$featureText.Substring(0,69)+'...'
        }
        $items+=[pscustomobject]@{
            Text=('[{0}] {1} · {2} · {3}'-f($i+1),[string]$s.CreatedAt,[string]$s.Status,$kind);
            Color='Cyan';
            Description=$featureText
        }

    }
    $items+=[pscustomobject]@{
        Text='[0] '+$(if($isEn){
            'Back'
        }else{
            'Volver'
        });
        Color='Gray';
        SeparatorBefore=$true
    }
    Write-CenteredMenuVSO -Items $items
    while($true){

        $choice=Read-CenteredPromptVSO -AnimatedMenu -Text $(if($isEn){
            'Backup'
        }else{
            'Backup'
        })
        if([string]$choice-ceq'0'){
            return $null
        }
        $index=0
        if([int]::TryParse([string]$choice,[ref]$index)-and$index-ge1-and$index-le$ordered.Count){
            return $ordered[$index-1]
        }
        Write-VSOHost $(if($isEn){
            'Invalid backup selection.'
        }else{
            'Seleccion de backup no valida.'
        }) -ForegroundColor Red

    }

}

function Show-VSO7NativeBackupRestoreVSO {

    $inventory=Get-VSO7NativeBackupInventoryVSO -SkipInvalid
    $sessions=@($inventory.Valid|Where-Object{
        [string]$_.Status-ne'Restored'
    })
    if([int]$inventory.InvalidCount-gt0){

        Write-CenteredLineVSO -Text $(if($script:Language-eq'en'){
            ('{0} INVALID native recovery session(s) were preserved and will not be hidden or restored automatically.'-f[int]$inventory.InvalidCount)
        }else{
            ('{0} sesion(es) INVALIDAS de Recovery nativo se conservan visibles y no se restauraran automaticamente.'-f[int]$inventory.InvalidCount)
        }) -Color $script:ThemeDanger
        foreach($bad in @($inventory.Invalid|Select-Object -First 5)){
            Write-VSO7Log ("Recovery invalido visible: {0}: {1}"-f$bad.Directory,$bad.Error) 'WARN'
        }

    }
    if($sessions.Count-eq0){
        Write-CenteredLineVSO -Text $(if($script:Language-eq'en'){
            'No VALID pending native tweak backup is available. Invalid sessions, if listed above, require review.'
        }else{
            'No hay backups nativos VALIDOS pendientes. Las sesiones invalidas indicadas arriba requieren revision.'
        }) -Color $script:ThemeMuted;
        Pause-Vico;
        return
    }
    $selected=Select-VSO7NativeBackupSessionVSO -Sessions $sessions
    if($null-eq$selected){
        return
    }
    if(Confirm-Word -Word 'RESTAURAR NATIVO' -Message ('Escribe exactamente RESTAURAR NATIVO para restaurar la sesion '+[string]$selected.CreatedAt)){
        $isLegacy=(-not($selected.PSObject.Properties.Name-contains'Schema')-or[int]$selected.Schema-lt2);
        $ok=[bool](Restore-VSO7NativeBackupSessionVSO -Session $selected -AllowLegacyRecovery:$isLegacy);
        Write-CenteredLineVSO -Text $(if($ok){
            if($script:Language-eq'en'){
                'Native backup restored.'
            }else{
                'Backup nativo restaurado.'
            }
        }else{
            if($script:Language-eq'en'){
                'Native restore was incomplete; the backup remains available.'
            }else{
                'La restauracion nativa fue incompleta; el backup sigue disponible.'
            }
        }) -Color $(if($ok){
            $script:ThemeSuccess
        }else{
            $script:ThemeDanger
        })
    }
    Pause-Vico

}

function Get-VSO7FeatureCatalogVSO {

    if(-not(Test-VSO7NativeResourceIntegrityVSO)){
        return @()
    }
    try{
        return @((Get-Content -LiteralPath $script:VSO7FeatureCatalog -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop).Features)
    }catch{
        Write-VSO7Log ("No se pudo leer el catalogo VSO7 verificado: {0}"-f$_.Exception.Message) 'ERROR';
        return @()
    }

}

function Get-VSO7PrivacyReviewFeaturesVSO {

    param([AllowNull()][array]$Catalog)
    if($null-eq$Catalog){
        $Catalog=@(Get-VSO7FeatureCatalogVSO)
    }
    return @($Catalog|Where-Object{

        [bool]$_.Selectable -and
        (@($_.ObjectiveDomains|ForEach-Object{
            [string]$_
        }) -contains 'Privacy')

    }|Sort-Object FeatureId)

}

function Show-VSO7PrivacyReviewVSO {

    $isEn=($script:Language-eq'en')
    $privacy=@(Get-VSO7PrivacyReviewFeaturesVSO)
    Write-Title
    Write-CenteredLineVSO -Text $(if($isEn){
        'PRIVACY · MANUAL REVIEW'
    }else{
        'PRIVACIDAD · REVISION MANUAL'
    }) -Color $script:ThemeCopper
    Write-VSOHost ''
    Write-CenteredLineVSO -Text $(if($isEn){
        'Privacy remains manual-only in R44. VSO7 lists only catalog features explicitly tagged for the Privacy objective; nothing is applied automatically.'
    }else{
        'Privacidad sigue siendo manual-only en R44. VSO7 muestra solo features que el catalogo etiqueta explicitamente para el objetivo Privacy; no se aplica nada automaticamente.'
    }) -Color $script:ThemeText
    Write-VSOHost ''
    if($privacy.Count-eq0){

        Write-CenteredLineVSO -Text $(if($isEn){
            'No selectable Privacy features are currently declared by the catalog.'
        }else{
            'El catalogo no declara actualmente features Privacy seleccionables.'
        }) -Color $script:ThemeWarning
        Pause-Vico
        return

    }
    Show-VSO7FeatureCategoryVSO -FeatureIds @($privacy|ForEach-Object{
        [string]$_.FeatureId
    })

}

