function Get-VSO7RiskLabelVSO {

    param([int]$Risk)
    if($script:Language-eq'en'){
        switch($Risk){
            1{
                'Low risk'
            }2{
                'Medium risk'
            }3{
                'High risk'
            }4{
                'Very high risk'
            }default{
                'Unknown risk'
            }
        }
    }
    else{
        switch($Risk){
            1{
                'Riesgo bajo'
            }2{
                'Riesgo medio'
            }3{
                'Riesgo alto'
            }4{
                'Riesgo muy alto'
            }default{
                'Riesgo desconocido'
            }
        }
    }

}

function Show-VSO7ChoiceGroupVSO {

    param(
        [Parameter(Mandatory=$true)][string]$TitleEs,
        [Parameter(Mandatory=$true)][string]$TitleEn,
        [Parameter(Mandatory=$true)][array]$Choices
    )
    while($true){

        $isEn=($script:Language-eq'en')
        Write-Title
        Write-CenteredLineVSO -Text $(if($isEn){
            $TitleEn
        }else{
            $TitleEs
        }) -Color $script:ThemeCopper
        Write-VSOHost ''
        Write-CenteredLineVSO -Text $(if($isEn){
            'Opening this list changes nothing. Choose one behavior, review it, and confirm before applying.'
        }else{
            'Abrir esta lista no cambia nada. Elige un comportamiento, revisalo y confirma antes de aplicarlo.'
        }) -Color $script:ThemeText
        Write-VSOHost ''
        $rows=@();
        $n=1
        foreach($choice in $Choices){

            $name=if($isEn){
                [string]$choice.NameEn
            }else{
                [string]$choice.NameEs
            }
            $desc=if($isEn){
                [string]$choice.DescEn
            }else{
                [string]$choice.DescEs
            }
            $risk=1;
            if($choice.PSObject.Properties.Name-contains'Risk'){
                $risk=[int]$choice.Risk
            }
            $rows+=[pscustomobject]@{
                Text=("[{0}] {1} · {2}"-f$n,$name,(Get-VSO7RiskLabelVSO -Risk $risk));
                Color='Gray';
                Description=$desc
            };
            $n++

        }
        $rows+=[pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });
            Color='Gray';
            Description=$(if($isEn){
                'Returns without changing this setting.'
            }else{
                'Vuelve sin cambiar este ajuste.'
            });
            SeparatorBefore=$true
        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        Write-VSOHost ''
        $raw=Read-CenteredPromptVSO -Text $(if($isEn){
            'Option'
        }else{
            'Opcion'
        });
        if($raw-eq'0'){
            return
        }
        $index=0;
        if(-not[int]::TryParse($raw,[ref]$index)-or$index-lt1-or$index-gt$Choices.Count){
            continue
        }
        $picked=$Choices[$index-1]
        $name=if($isEn){
            [string]$picked.NameEn
        }else{
            [string]$picked.NameEs
        }
        $desc=if($isEn){
            [string]$picked.DescEn
        }else{
            [string]$picked.DescEs
        }
        Write-VSOHost ''
        Write-CenteredLineVSO -Text $name -Color $script:ThemeWarning
        Write-CenteredLineVSO -Text $desc -Color $script:ThemeText
        Write-VSOHost ''
        $confirm=Read-CenteredPromptVSO -Text $(if($isEn){
            'Apply exactly this behavior? [Y/N]'
        }else{
            '¿Aplicar exactamente este comportamiento? [S/N]'
        })
        if($confirm-notmatch'^[sSyY]$'){
            continue
        }
        $featureIds=@($picked.FeatureIds|ForEach-Object{
            [string]$_
        })
        try{
            $catalog=@(Get-VSO7FeatureCatalogVSO);
            [void](Assert-VSO7NativeFeatureSelectionVSO -Requested $featureIds -Catalog $catalog -AllowSpecializedChoice)
        }catch{
            Write-CenteredLineVSO -Text $_.Exception.Message -Color $script:ThemeDanger;
            Pause-Vico;
            return
        }
        if(-not(Require-RestorePoint)){
            Pause-Vico;
            return
        }
        $ok=[bool](Invoke-VSO7NativeTweaksVSO -Features $featureIds -AllowSpecializedChoice)
        if($ok){
            Write-CenteredLineVSO -Text $(if($isEn){
                'Setting applied.'
            }else{
                'Ajuste aplicado.'
            }) -Color $script:ThemeSuccess
        }
        else{
            Write-CenteredLineVSO -Text $(if($isEn){
                'The VSO7 native engine reported a failure. Review the log.'
            }else{
                'El motor nativo de VSO7 indico un fallo. Revisa el log.'
            }) -Color $script:ThemeDanger
        }
        Pause-Vico
        return

    }

}

