                    NameEs='OneDrive';NameEn='OneDrive';DescEs='Abre OneDrive por defecto; requiere que OneDrive este configurado.';DescEn='Opens OneDrive by default; OneDrive must be configured.';FeatureIds=@('V7FE004');Risk=1
                })
