                },
                [pscustomobject]@{
                    NameEs='Letra despues del nombre';NameEn='Drive letter after name';DescEs='Mantiene la letra visible despues de la etiqueta.';DescEn='Keeps the drive letter visible after the label.';FeatureIds=@('V7FE018');Risk=1
                },
                [pscustomobject]@{
                    NameEs='Letra primero solo en unidades de red';NameEn='Network drive letters first';DescEs='Prioriza la letra antes del nombre en unidades de red.';DescEn='Places the drive letter first for network drives.';FeatureIds=@('V7FE019');Risk=1
                },
                [pscustomobject]@{
                    NameEs='Ocultar letras de unidad';NameEn='Hide drive letters';DescEs='Oculta C:, D:, etc. en las etiquetas del Explorador; las unidades y rutas siguen existiendo.';DescEn='Hides C:, D:, etc. in Explorer labels; drives and paths still exist.';FeatureIds=@('V7FE020');Risk=1
                })
            }
            '9'{
                Show-VSO7ChoiceGroupVSO -TitleEs 'TODAS LAS APLICACIONES - INICIO' -TitleEn 'ALL APPS - START' -Choices @(
                [pscustomobject]@{
                    NameEs='Vista por categorias';NameEn='Category view';DescEs='Agrupa Todas las aplicaciones por categorias cuando esta version de Windows lo admite.';DescEn='Groups All apps by category when supported by this Windows build.';FeatureIds=@('V7ST008');Risk=1
                },
                [pscustomobject]@{
