                })
            }
            '0'{
                return
            }

        }

    }

}

function Get-VSO7AppCatalogVSO {
    if($null-ne$script:VSO7AppCatalogObjectCache){return @($script:VSO7AppCatalogObjectCache)}
    if(-not(Test-VSO7NativeResourceIntegrityVSO)){return @()}
    try{
        $script:VSO7AppCatalogObjectCache=@((Get-Content -LiteralPath $script:VSO7AppCatalog -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop).Apps)
        return @($script:VSO7AppCatalogObjectCache)
    }catch{
        Write-VSO7Log ("No se pudo leer el catalogo de aplicaciones VSO7: {0}"-f$_.Exception.Message) 'ERROR'
        return @()
    }
}

function Get-VSO7AppRecommendationTextVSO {

    param([string]$Recommendation)
    $isEn=($script:Language-eq'en')
    switch(([string]$Recommendation).ToLowerInvariant()){

        'safe'{
            if($isEn){
                'Recommended removal'
            }else{
                'Recomendada para quitar'
            }
        }
        'optional'{
            if($isEn){
                'Optional'
            }else{
                'Opcional'
            }
        }
        'unsafe'{
            if($isEn){
                'Caution: may affect Windows features'
            }else{
                'Precaucion: puede afectar funciones de Windows'
            }
        }
        default{
            if($isEn){
                'Review before removal'
            }else{
                'Revisar antes de quitar'
            }
        }

    }

}

function ConvertTo-VSO7SearchKeyVSO {

    param([AllowNull()][string]$Text)
    if([string]::IsNullOrWhiteSpace([string]$Text)){
        return ''
    }
    $normalized=([string]$Text).Normalize([Text.NormalizationForm]::FormD)
    $builder=New-Object Text.StringBuilder
    foreach($ch in $normalized.ToCharArray()){
        $category=[Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch)
        if($category-ne[Globalization.UnicodeCategory]::NonSpacingMark){
            [void]$builder.Append($ch)
        }
    }
    $plain=$builder.ToString().Normalize([Text.NormalizationForm]::FormC).ToLowerInvariant()
    $plain=[regex]::Replace($plain,'[^a-z0-9]+',' ')
    return ([regex]::Replace($plain,'\s+',' ')).Trim()

}

function Get-VSO7LevenshteinDistanceVSO {

    param(
        [AllowEmptyString()][string]$A='',
        [AllowEmptyString()][string]$B=''
    )
    $aText=[string]$A
    $bText=[string]$B
    if($aText.Length-eq0){ return $bText.Length }
    if($bText.Length-eq0){ return $aText.Length }
    $previous=New-Object 'int[]' ($bText.Length+1)
    $current=New-Object 'int[]' ($bText.Length+1)
    for($j=0;$j-le$bText.Length;$j++){ $previous[$j]=$j }
    for($i=1;$i-le$aText.Length;$i++){
        $current[0]=$i
        for($j=1;$j-le$bText.Length;$j++){
            $cost=if($aText[$i-1]-eq$bText[$j-1]){0}else{1}
            $delete=$previous[$j]+1
            $insertCost=$current[$j-1]+1
            $replace=$previous[$j-1]+$cost
            $current[$j]=[math]::Min($delete,[math]::Min($insertCost,$replace))
        }
        $swap=$previous;$previous=$current;$current=$swap
    }
    return [int]$previous[$bText.Length]

}

function Find-VSO7AppCatalogMatchesVSO {

    param(
        [Parameter(Mandatory=$true)][object[]]$Apps,
        [Parameter(Mandatory=$true)][string]$Query,
        [ValidateRange(1,50)][int]$Limit=8
    )
    $q=ConvertTo-VSO7SearchKeyVSO -Text $Query
    if($q.Length-lt2){ return @() }
    $results=New-Object Collections.Generic.List[object]
    for($i=0;$i-lt$Apps.Count;$i++){
        $app=$Apps[$i]
        $name=ConvertTo-VSO7SearchKeyVSO -Text ([string]$app.FriendlyName)
        $ids=@(Get-VSO7AppIdsVSO -App $app|ForEach-Object{ConvertTo-VSO7SearchKeyVSO -Text ([string]$_)})
        $description=ConvertTo-VSO7SearchKeyVSO -Text ([string]$app.Description)
        $haystack=($name+' '+([string]::Join(' ',$ids))+' '+$description).Trim()
        [int]$score=0
        if($name-eq$q){
            $score=1200
        }elseif($name.StartsWith($q,[StringComparison]::OrdinalIgnoreCase)){
            $score=1100
        }elseif($haystack.Contains($q)){
            $score=1000-[math]::Min(200,[math]::Max(0,$haystack.IndexOf($q)))
        }else{
            $candidates=New-Object Collections.Generic.List[string]
            if(-not[string]::IsNullOrWhiteSpace($name)){[void]$candidates.Add($name)}
            foreach($word in @($name.Split(' ')+$description.Split(' ')+$ids)){
                if(-not[string]::IsNullOrWhiteSpace([string]$word)){[void]$candidates.Add([string]$word)}
            }
            $best=[int]::MaxValue
            foreach($candidate in $candidates){
                if([math]::Abs($candidate.Length-$q.Length)-gt[math]::Max(3,[math]::Ceiling($q.Length*0.45))){continue}
                $distance=Get-VSO7LevenshteinDistanceVSO -A $q -B $candidate
                if($distance-lt$best){$best=$distance}
            }
            $maxDistance=[math]::Max(1,[math]::Floor($q.Length*0.38))
            if($q.Length-ge6){$maxDistance=[math]::Max(2,$maxDistance)}
            if($best-le$maxDistance){
                $score=850-($best*90)-[math]::Abs($name.Length-$q.Length)
            }
        }
        if($score-gt0){
            [void]$results.Add([pscustomobject]@{Index=$i;App=$app;Score=$score})
        }
    }
    return @($results|Sort-Object @{Expression='Score';Descending=$true},@{Expression={ [string]$_.App.FriendlyName };Descending=$false}|Select-Object -First $Limit)

}

function Get-VSO7AppCatalogKeyVSO {

    param([Parameter(Mandatory=$true)]$App)
    $ids=@($App.AppId|ForEach-Object{
        [string]$_
    }|Where-Object{
        -not[string]::IsNullOrWhiteSpace($_)
    })
    return (([string]$App.FriendlyName)+'|'+[string]::Join('|',$ids))

}

function Get-VSO7AppIdsVSO {

    param([Parameter(Mandatory=$true)]$App)
    return @($App.AppId|ForEach-Object{
        [string]$_
    }|Where-Object{
        -not[string]::IsNullOrWhiteSpace($_)
    }|Select-Object -Unique)

}

function Show-VSO7ManualAppSelectorVSO {

    $apps=@(Get-VSO7AppCatalogVSO)
    if(-not$apps.Count){
        Write-CenteredLineVSO -Text $(if($script:Language-eq'en'){
            'The application catalog is unavailable.'
        }else{
            'El catalogo de aplicaciones no esta disponible.'
        }) -Color $script:ThemeDanger;
        Pause-Vico;
        return
    }
    $selected=New-Object Collections.Generic.List[string]
    $page=0;
    $pageSize=12;
    $pageCount=[math]::Ceiling($apps.Count/[double]$pageSize)
    while($true){

        $isEn=($script:Language-eq'en');
        $start=$page*$pageSize;
        $end=[math]::Min($apps.Count,$start+$pageSize)
        Write-Title;
        Write-CenteredLineVSO -Text $(if($isEn){
            'APPLICATION REMOVAL - SELECTOR'
        }else{
            'ELIMINAR APLICACIONES - SELECTOR'
        }) -Color $script:ThemeCopper;
        Write-VSOHost ''
        Write-CenteredLineVSO -Text $(if($isEn){
            'Opening this screen removes nothing. Select only apps you recognize; unsafe entries are never selected automatically.'
        }else{
            'Abrir esta pantalla no elimina nada. Selecciona solo apps que reconozcas; las opciones arriesgadas nunca se marcan automaticamente.'
        }) -Color $script:ThemeText
        Write-CenteredLineVSO -Text $(if($isEn){
            ("Page {0}/{1} · {2} apps · {3} selected"-f($page+1),$pageCount,$apps.Count,$selected.Count)
        }else{
            ("Pagina {0}/{1} · {2} apps · {3} seleccionadas"-f($page+1),$pageCount,$apps.Count,$selected.Count)
        }) -Color $script:ThemeMuted;
        Write-VSOHost ''
        $rows=@();
        $local=1
        for($i=$start;$i-lt$end;$i++){

            $app=$apps[$i];
            $id=Get-VSO7AppCatalogKeyVSO -App $app;
            $on=$selected.Contains($id);
            $mark=if($on){
                '[X]'
            }else{
                '[ ]'
            };
            $color=if($on){
                'Green'
            }elseif([string]$app.Recommendation-eq'unsafe'){
                'Yellow'
            }else{
                'Gray'
            }
            $friendly=[string]$app.FriendlyName;
            $rec=Get-VSO7AppRecommendationTextVSO -Recommendation ([string]$app.Recommendation)
            $desc=if($isEn){
                ([string]$app.Description+' · '+$rec)
            }else{
                ("{0}. Clasificacion: {1}. Revisa esta app antes de marcarla."-f$friendly,$rec.ToLowerInvariant())
            }
            $rows+=[pscustomobject]@{
                Text=("[{0}] {1} {2}"-f$local,$mark,$friendly);
                Color=$color;
                Description=$desc
            };
            $local++

        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows;
        Write-VSOHost ''
        $next=$local;
        $prev=$local+1;
        $recommended=$local+2;
        $clear=$local+3;
        $apply=$local+4
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=("[{0}] "-f$next)+$(if($isEn){
                'Next page'
            }else{
                'Pagina siguiente'
            });Color='Cyan';Description=$(if($isEn){
                'Shows the next group of applications.'
            }else{
                'Muestra el siguiente grupo de aplicaciones.'
            })
        },
            [pscustomobject]@{
            Text=("[{0}] "-f$prev)+$(if($isEn){
                'Previous page'
            }else{
                'Pagina anterior'
            });Color='Cyan';Description=$(if($isEn){
                'Shows the previous group of applications.'
            }else{
                'Muestra el grupo anterior de aplicaciones.'
            })
        },
            [pscustomobject]@{
            Text=("[{0}] "-f$recommended)+$(if($isEn){
                'Select recommended removals'
            }else{
                'Seleccionar las recomendadas para quitar'
            });Color='Green';Description=$(if($isEn){
                'Selects only entries classified as safe and recommended by VSO7.'
            }else{
                'Marca solo las entradas que VSO7 clasifica como seguras y recomendadas.'
            })
        },
            [pscustomobject]@{
            Text=("[{0}] "-f$clear)+$(if($isEn){
                'Clear selection'
            }else{
                'Quitar seleccion'
            });Color='Gray';Description=$(if($isEn){
                'Clears every selected app.'
            }else{
                'Desmarca todas las aplicaciones.'
            })
        },
            [pscustomobject]@{
            Text=("[{0}] "-f$apply)+$(if($isEn){
                'Review and remove selected apps'
            }else{
                'Revisar y eliminar seleccionadas'
            });Color='Yellow';Description=$(if($isEn){
                'Shows a final list, requires an explicit confirmation, and then uses the VSO7 removal engine.'
            }else{
                'Muestra la lista final, exige una confirmacion explicita y despues usa el motor de eliminacion de VSO7.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });Color='Gray';Description=$(if($isEn){
                'Returns without removing anything.'
            }else{
                'Vuelve sin eliminar nada.'
            });SeparatorBefore=$true
        }
        )
        Write-CenteredLineVSO -Text $(if($isEn){
            '[B] Fuzzy search all pages · [P#] Jump directly to page (example: P3)'
        }else{
            '[B] Busqueda aproximada en todas las paginas · [P#] Ir directamente a pagina (ejemplo: P3)'
        }) -Color $script:ThemeMuted
        $raw=Read-CenteredPromptVSO -AnimatedMenu -Text $(if($isEn){
            'Option / app number / search text'
        }else{
            'Opcion / numero de app / texto a buscar'
        });
        if($raw-eq'0'){
            return
        };
        if($raw-match'^(?i)P\s*(\d+)$'){
            $targetPage=[int]$Matches[1]
            if($targetPage-ge1-and$targetPage-le$pageCount){$page=$targetPage-1}
            continue
        }
        if($raw-ieq'B'-or-not($raw-match'^\d+$')){
            $query=if($raw-ieq'B'){
                Read-CenteredPromptVSO -Text $(if($isEn){'Search apps (typos allowed)'}else{'Buscar apps (se admiten errores al escribir)'})
            }else{
                [string]$raw
            }
            $matches=@(Find-VSO7AppCatalogMatchesVSO -Apps $apps -Query ([string]$query) -Limit 8)
            Write-VSOHost ''
            if($matches.Count-eq0){
                Write-CenteredLineVSO -Text $(if($isEn){'No sufficiently similar applications were found.'}else{'No se encontraron aplicaciones suficientemente parecidas.'}) -Color $script:ThemeWarning
                Start-Sleep -Milliseconds 700
                continue
            }
            $searchRows=@();$searchN=1
            foreach($match in $matches){
                $matchPage=[math]::Floor([int]$match.Index/[double]$pageSize)+1
                $searchRows+=[pscustomobject]@{
                    Text=("[{0}] {1} · {2} {3}"-f$searchN,[string]$match.App.FriendlyName,$(if($isEn){'Page'}else{'Pagina'}),$matchPage)
                    Color='Cyan'
                    Description=$(if($isEn){[string]$match.App.Description}else{Get-VSO7GuiStringVSO 'AppOptionalDesc' -Args @([string]$match.App.FriendlyName)})
                }
                $searchN++
            }
            Write-CenteredMenuVSO -Items $searchRows
            $pickText=Read-CenteredPromptVSO -AnimatedMenu -Text $(if($isEn){'Result number to jump to / 0 cancel'}else{'Numero de resultado para ir a su pagina / 0 cancelar'})
            $pick=0
            if([int]::TryParse($pickText,[ref]$pick)-and$pick-ge1-and$pick-le$matches.Count){
                $page=[math]::Floor([int]$matches[$pick-1].Index/[double]$pageSize)
            }
            continue
        }
        $choice=0;
        if(-not[int]::TryParse($raw,[ref]$choice)){
            continue
        }
        if($choice-ge1-and$choice-lt$local){
            $app=$apps[$start+$choice-1];
            $id=Get-VSO7AppCatalogKeyVSO -App $app;
            if($selected.Contains($id)){
                [void]$selected.Remove($id)
            }else{
                [void]$selected.Add($id)
            };
            continue
        }
        if($choice-eq$next){
            if($page+1-lt$pageCount){
                $page++
            };
            continue
        }
        if($choice-eq$prev){
            if($page-gt0){
                $page--
            };
            continue
        }
        if($choice-eq$recommended){
            $selected.Clear()
            foreach($key in @(Get-VSO7RecommendedAppCatalogKeysR52VSO)){[void]$selected.Add([string]$key)}
            continue
        }
        if($choice-eq$clear){
            $selected.Clear();
            continue
        }
        if($choice-eq$apply){

            if($selected.Count-eq0){
                Write-CenteredLineVSO -Text $(if($isEn){
                    'No applications are selected.'
                }else{
                    'No hay aplicaciones seleccionadas.'
                }) -Color $script:ThemeWarning;
                Start-Sleep -Milliseconds 700;
                continue
            }
            $selectedApps=@($apps|Where-Object{
                $selected.Contains((Get-VSO7AppCatalogKeyVSO -App $_))
            })
            $unsafe=@($selectedApps|Where-Object{
                [string]$_.Recommendation-eq'unsafe'
            })
            Write-VSOHost '';
            Write-CenteredLineVSO -Text $(if($isEn){
                ("Selected applications: {0}"-f$selectedApps.Count)
            }else{
                ("Aplicaciones seleccionadas: {0}"-f$selectedApps.Count)
            }) -Color $script:ThemeWarning
            foreach($app in $selectedApps){
                Write-CenteredLineVSO -Text ('  - '+[string]$app.FriendlyName) -Color $(if([string]$app.Recommendation-eq'unsafe'){
                    $script:ThemeDanger
                }else{
                    $script:ThemeText
                })
            }
            Write-VSOHost ''
            Write-CenteredLineVSO -Text $(if($isEn){
                'Removing an app is not the same as a registry tweak: VSO7 cannot guarantee automatic reinstallation. A restore point is still required.'
            }else{
                'Eliminar una app no es igual que cambiar el Registro: VSO7 no puede garantizar su reinstalacion automatica. Aun asi se exige un punto de restauracion.'
            }) -Color $script:ThemeWarning
            if($unsafe.Count){
                Write-CenteredLineVSO -Text $(if($isEn){
                    ("CAUTION: {0} selected app(s) are marked high risk by VSO7."-f$unsafe.Count)
                }else{
                    ("PRECAUCION: {0} app(s) seleccionadas estan marcadas como arriesgadas por VSO7."-f$unsafe.Count)
                }) -Color $script:ThemeDanger
            }
            Write-VSOHost ''
            if(-not(Confirm-Word -Word 'ELIMINAR APPS' -Message 'Escribe exactamente ELIMINAR APPS para continuar')){
                Write-CenteredLineVSO -Text $(if($isEn){
                    'Cancelled.'
                }else{
                    'Cancelado.'
                }) -Color $script:ThemeMuted;
                Pause-Vico;
                return
            }
            if(-not(Require-RestorePoint)){
                Pause-Vico;
                return
            }
            $ok=[bool](Invoke-VSO7NativeTweaksVSO -Apps @($selectedApps|ForEach-Object{
                Get-VSO7AppIdsVSO -App $_
            }))
            if($ok){
                Write-CenteredLineVSO -Text $(if($isEn){
                    'The removal engine finished. Review its output/log for per-app results.'
                }else{
                    'El motor de eliminacion termino. Revisa su salida/log para ver el resultado de cada app.'
                }) -Color $script:ThemeSuccess
            }else{
                Write-CenteredLineVSO -Text $(if($isEn){
                    'The removal engine reported a failure. Review the log.'
                }else{
                    'El motor de eliminacion indico un fallo. Revisa el log.'
                }) -Color $script:ThemeDanger
            }
            Pause-Vico;
            return

        }

    }

}

function Get-VSO7ScopedFeatureProposalVSO {
    param(
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][AllowNull()][string[]]$FeatureIds,
        [ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Objective='Balanced',
        [switch]$IncludeOptional
    )
    $ids=@($FeatureIds|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|Sort-Object -Unique)
    $allowed=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach($id in $ids){[void]$allowed.Add([string]$id)}
    $plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective $Objective -IncludeOptional:$IncludeOptional -ExplicitFeatureIds $ids
    $selected=@($plan.Selected|ForEach-Object{[string]$_.Feature.FeatureId}|Sort-Object -Unique)
    foreach($id in $selected){
        if(-not$allowed.Contains($id)){throw ('Recommendation escaped the permitted feature scope: '+$id)}
    }
    $details=@{}
    # Later groups take precedence, keeping the selected/already-optimal explanation.
    foreach($entry in (@($plan.Skipped)+@($plan.Optional)+@($plan.AlreadyOptimal)+@($plan.Selected))){
        $id=[string]$entry.Feature.FeatureId
        if($allowed.Contains($id)){$details[$id]=$entry}
    }
    return [pscustomobject]@{
        Schema='VSO7.ScopedFeatureProposal.v1';Objective=$Objective;AllowedFeatureIds=$ids
        SelectedFeatureIds=$selected;DetailsById=$details;Recommendation=$plan
    }
}

function Get-VSO7FeatureProposalExplanationVSO {
    param([Parameter(Mandatory=$true)]$Entry)
    $text=switch([string]$Entry.Status){
        'Selected' {Get-VSO7ConsoleTextVSO 'VSO recomienda esta opcion.' 'VSO recommends this item.';break}
        'AlreadyOptimal' {Get-VSO7ConsoleTextVSO 'Ya configurada/optima; no se selecciona para ejecutar.' 'Already configured/optimal; not selected for execution.';break}
        'ObjectiveMismatch' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: no corresponde al objetivo.' 'VSO did not select this automatically: outside the objective.';break}
        'Preference' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: es una preferencia personal.' 'VSO did not select this automatically: personal preference.';break}
        'Optional' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: opcion para revision manual.' 'VSO did not select this automatically: option for manual review.';break}
        'OptionalNotRequested' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: opcion adicional.' 'VSO did not select this automatically: optional addition.';break}
        'ConflictSkipped' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: conflicto con otra recomendacion.' 'VSO did not select this automatically: conflicts with another recommendation.';break}
        'DependencySkipped' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: falta un requisito.' 'VSO did not select this automatically: a requirement is not satisfied.';break}
        'DependencyCycle' {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: dependencias incompatibles.' 'VSO did not select this automatically: incompatible dependencies.';break}
        'NotApplicable' {Get-VSO7ConsoleTextVSO 'No aplicable; VSO no la selecciono automaticamente.' 'Not applicable; VSO did not select this automatically.';break}
        'Ambiguous' {Get-VSO7ConsoleTextVSO 'No verificable; VSO no la selecciono automaticamente.' 'Could not verify; VSO did not select this automatically.';break}
        default {Get-VSO7ConsoleTextVSO 'VSO no la selecciono automaticamente: requiere una decision manual o queda excluida por la politica actual.' 'VSO did not select this automatically: requires a manual decision or is excluded by current policy.'}
    }
    if($Entry.PSObject.Properties.Name-contains'Applicability'-and$null-ne$Entry.Applicability){
        $reason=if($script:Language-eq'en'){[string]$Entry.Applicability.ReasonEn}else{[string]$Entry.Applicability.ReasonEs}
        if(-not[string]::IsNullOrWhiteSpace($reason)){$text+=' '+$reason}
    }
    return $text
}

function Show-VSO7FeatureCategoryVSO {

    param(
        [string[]]$Categories,
        [AllowEmptyCollection()][AllowNull()][string[]]$FeatureIds
    )
    if(-not$PSBoundParameters.ContainsKey('FeatureIds')-and($null-eq$Categories-or$Categories.Count-eq0)){
        throw 'Show-VSO7FeatureCategoryVSO requiere Categories o FeatureIds.'
    }
    $allCatalog=@(Get-VSO7FeatureCatalogVSO)
    if($PSBoundParameters.ContainsKey('FeatureIds')){

        $wanted=@{};
        foreach($id in @($FeatureIds)){
            $wanted[[string]$id]=$true
        }
        $catalog=@($allCatalog|Where-Object{
            [bool]$_.Selectable-and$wanted.ContainsKey([string]$_.FeatureId)
        }|Sort-Object FeatureId)

    }else{

        $catalog=@($allCatalog|Where-Object{
            [string]$_.CategoryEn-in$Categories-and[bool]$_.Selectable
        })

    }
    if(-not$catalog.Count){
        Write-CenteredLineVSO -Text $(if($script:Language-eq'en'){
            'No selectable options exist in this category.'
        }else{
            'No hay opciones seleccionables en esta categoria.'
        }) -Color $script:ThemeWarning;
        Pause-Vico;
        return
    }
    $selected=@()
    $automatic=@{}
    $objective='Balanced'
    $proposal=$null
    $scopeIds=@($catalog|ForEach-Object{[string]$_.FeatureId}|Sort-Object -Unique)
    while($true){

        $isEn=($script:Language-eq'en')
        Write-Title;
        Write-CenteredLineVSO -Text $(if($isEn){
            'VSO7 FEATURE CATALOG'
        }else{
            'CATALOGO DE FEATURES VSO7'
        }) -Color $script:ThemeCopper;
        Write-VSOHost ''
        Write-CenteredLineVSO -Text $(if($isEn){
            'Risk says what can go wrong. Evidence says how strongly the expected behavior/benefit is supported. Unrated means this feature has not yet received an individual evidence review.'
        }else{
            'Risk indica que puede salir mal. Evidence indica cuanto respaldo tiene el comportamiento/beneficio esperado. Unrated significa que esa feature aun no ha recibido revision individual de evidencia.'
        }) -Color $script:ThemeText;
        Write-VSOHost ''
        if($null-ne$Categories-and$Categories-contains'Special'){
            Write-CenteredLineVSO -Text $(if($isEn){
                'SPECIAL OPERATIONS can be difficult or impossible to undo automatically.'
            }else{
                'Las OPERACIONES ESPECIALES pueden ser dificiles o imposibles de deshacer automaticamente.'
            }) -Color $script:ThemeDanger;
            Write-VSOHost ''
        }
        Write-CenteredLineVSO -Text ((Get-VSO7ConsoleTextVSO 'Objetivo para el siguiente calculo: ' 'Objective for the next calculation: ')+$objective) -Color $script:ThemeText
        Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO '[A] Seleccion automatica · [X] Seleccion manual · R reemplaza la seleccion actual.' '[A] Automatic selection · [X] Manual selection · R replaces the current selection.') -Color $script:ThemeMuted
        if($null-ne$proposal-and[string]$proposal.Objective-cne$objective){
            Write-CenteredLineVSO -Text ((Get-VSO7ConsoleTextVSO 'La propuesta visible usa ' 'The visible proposal uses ')+$proposal.Objective+(Get-VSO7ConsoleTextVSO '. Pulsa R para recalcular; cambiar objetivo conserva tu seleccion.' '. Press R to recalculate; changing objective preserves your selection.')) -Color $script:ThemeWarning
        }
        if($null-ne$proposal-and@($proposal.SelectedFeatureIds).Count-eq0){
            Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'VSO no tiene recomendaciones automaticas pendientes para esta seccion y objetivo. Puedes seleccionar manualmente.' 'VSO currently has no pending automatic recommendations for this section and objective. Manual selection remains available.') -Color $script:ThemeMuted
        }
        Write-VSOHost ''
        $rows=@();
        $states=@();
        $i=1
        foreach($f in $catalog){

            $id=[string]$f.FeatureId;
            $app=Get-VSO7FeatureApplicabilityVSO -Feature $f;
            $states+=,$app
            if(-not[bool]$app.Applicable){
                $selected=@($selected|Where-Object{
                    $_-ine$id
                })
            }
            $on=($selected-contains$id);
            $appStatus=[string]$app.Status
            $mark=if($on){
                if($automatic.ContainsKey($id)){'[A]'}else{'[X]'}
            }else{
                switch($appStatus){
                    'ALREADY_OPTIMAL' {'[OK]'}
                    'ADMIN' {'[ADMIN]'}
                    'UNKNOWN' {'[?]'}
                    'UNSUPPORTED' {'[UNSUPPORTED]'}
                    'NOT_APPLICABLE' {'[N/A]'}
                    default {'[ ]'}
                }
            }
            $name=if($isEn){
                [string]$f.NameEn
            }else{
                [string]$f.NameEs
            };
            $desc=if($isEn){
                [string]$f.DescriptionEn
            }else{
                [string]$f.DescriptionEs
            }
            $ev=Get-VSO7EvidenceLabelVSO -Evidence $(if($f.PSObject.Properties.Name-contains'Evidence'){
                [string]$f.Evidence
            }else{
                ''
            });
            $mat=Get-VSO7MaturityLabelVSO -Maturity $(if($f.PSObject.Properties.Name-contains'Maturity'){
                [string]$f.Maturity
            }else{
                ''
            })
            $rec=if($f.PSObject.Properties.Name-contains'Recommendation'){
                [string]$f.Recommendation
            }else{
                'Unrated'
            }
            if(-not[bool]$app.Applicable){
                $reason=if($isEn){
                    [string]$app.ReasonEn
                }else{
                    [string]$app.ReasonEs
                };
                $prefix=switch([string]$app.Status){
                    'ALREADY_OPTIMAL' { if($isEn){'Already optimal: '}else{'Ya optimo: '}; break }
                    'UNKNOWN' { if($isEn){'Could not verify: '}else{'No verificable: '}; break }
                    'UNSUPPORTED' { if($isEn){'Unsupported: '}else{'No soportado: '}; break }
                    'ADMIN' { if($isEn){'Administrator required: '}else{'Requiere administrador: '}; break }
                    default { if($isEn){'Not applicable: '}else{'No aplicable: '} }
                }
                $desc+=' · '+$prefix+$reason
            }
            if($on-and-not$automatic.ContainsKey($id)){
                $desc+=' · '+(Get-VSO7ConsoleTextVSO 'Seleccionada manualmente.' 'Selected manually.')
            }
            if($null-ne$proposal-and$proposal.DetailsById.ContainsKey($id)){
                $desc+=' · '+(Get-VSO7FeatureProposalExplanationVSO -Entry $proposal.DetailsById[$id])
            }
            $color=if($on){
                'Green'
            }elseif([string]$app.Status-eq'ALREADY_OPTIMAL'){
                'Green'
            }elseif([string]$app.Status-eq'UNKNOWN'){
                'Yellow'
            }elseif(-not[bool]$app.Applicable){
                'DarkGray'
            }else{
                'Gray'
            }
            $rows+=[pscustomobject]@{
                Text=("[{0}] {1} {2} · {3} · {4}/{5} · {6}"-f$i,$mark,$name,(Get-VSO7RiskLabelVSO -Risk ([int]$f.Risk)),$ev,$mat,$rec);
                Color=$color;
                Description=$desc
            };
            $i++

        }
        Write-VSO7TwoColumnOptionsVSO -Items $rows;
        Write-VSOHost ''
        $apply=$i;
        $clear=$i+1
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
                Text=Get-VSO7ConsoleTextVSO '[R] Seleccionar recomendadas para esta seccion' '[R] Select recommended for this section'
                Color='Cyan';Description=Get-VSO7ConsoleTextVSO 'Reemplaza la seleccion con recomendaciones del objetivo actual, solo dentro de este catalogo. No aplica nada.' 'Replaces the selection with recommendations for the current objective, only within this catalog. Applies nothing.'
            },
            [pscustomobject]@{
                Text=Get-VSO7ConsoleTextVSO '[O] Cambiar objetivo' '[O] Change objective'
                Color='Cyan';Description=Get-VSO7ConsoleTextVSO 'Conserva la seleccion; el nuevo objetivo se usa cuando pulses R.' 'Preserves the selection; the new objective is used when you press R.'
            },
            [pscustomobject]@{
                Text=Get-VSO7ConsoleTextVSO '[X] Quitar seleccion' '[X] Clear selection'
                Color='Gray';Description=Get-VSO7ConsoleTextVSO 'Desmarca todo sin modificar Windows.' 'Clears all selections without changing Windows.'
            },
            [pscustomobject]@{
            Text=("[{0}] "-f$apply)+$(if($isEn){
                'Apply selection'
            }else{
                'Aplicar seleccion'
            });Color='Green';Description=$(if($isEn){
                'Rechecks applicability, requires recovery, then applies only the selected reviewed state.'
            }else{
                'Recomprueba aplicabilidad, exige recuperacion y aplica solo el estado seleccionado.'
            })
        },
            [pscustomobject]@{
            Text=("[{0}] "-f$clear)+$(if($isEn){
                'Clear selection'
            }else{
                'Quitar seleccion'
            });Color='Gray';Description=$(if($isEn){
                'Clears every selection on this screen.'
            }else{
                'Desmarca todas las opciones de esta pantalla.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text $(if($isEn){
            'Option / number to toggle'
        }else{
            'Opcion / numero para activar-desactivar'
        });
        $n=0
        if($c-eq'0'){
            return
        };
        if($c-ieq'O'){
            $objective=Select-VSO7RecommendedObjectiveVSO -Current $objective -NoPrivacyReview
            continue
        }
        if($c-ieq'X'){
            $selected=@();$automatic=@{}
            continue
        }
        if($c-ieq'R'){
            try{
                $nextProposal=Get-VSO7ScopedFeatureProposalVSO -FeatureIds $scopeIds -Objective $objective
                $selected=@($nextProposal.SelectedFeatureIds)
                $automatic=@{}
                foreach($id in $selected){$automatic[[string]$id]=$true}
                $proposal=$nextProposal
            }catch{
                Write-CenteredLineVSO -Text ((Get-VSO7ConsoleTextVSO 'No se pudo calcular la recomendacion. Se conserva la seleccion anterior: ' 'Could not calculate recommendations. The previous selection is preserved: ')+$_.Exception.Message) -Color $script:ThemeDanger
                Pause-Vico
            }
            continue
        }
        if(-not[int]::TryParse($c,[ref]$n)){
            continue
        }
        if($n-ge1-and$n-le$catalog.Count){
            $f=$catalog[$n-1];
            $id=[string]$f.FeatureId;
            $app=Get-VSO7FeatureApplicabilityVSO -Feature $f;
            if(-not[bool]$app.Applicable){
                Write-CenteredLineVSO -Text $(if($isEn){
                    [string]$app.ReasonEn
                }else{
                    [string]$app.ReasonEs
                }) -Color $script:ThemeWarning;
                Start-Sleep -Milliseconds 650;
                continue
            };
            $automatic.Remove($id)
            if($selected-contains$id){
                $selected=@($selected|Where-Object{
                    $_-ine$id
                })
            }else{
                $selected+=,$id
            };
            continue
        }
        if($n-eq$clear){
            $selected=@();$automatic=@{}
            continue
        }
        if($n-eq$apply){

            if($selected.Count-eq0){
                Write-CenteredLineVSO -Text $(if($isEn){
                    'No options are selected.'
                }else{
                    'No hay opciones seleccionadas.'
                }) -Color $script:ThemeWarning;
                Start-Sleep -Milliseconds 650;
                continue
            }
            $reviewedIds=@($selected|Sort-Object -Unique)
            Write-VSOHost '';
            Write-CenteredLineVSO -Text $(if($isEn){
                'Exactly these features will be applied:'
            }else{
                'Se aplicaran exactamente estas features:'
            }) -Color $script:ThemeWarning
            foreach($id in $reviewedIds){
                $f=$catalog|Where-Object{
                    $_.FeatureId-eq$id
                }|Select-Object -First 1;
                $name=if($isEn){
                    [string]$f.NameEn
                }else{
                    [string]$f.NameEs
                };
                $ev=Get-VSO7EvidenceLabelVSO -Evidence $(if($f.PSObject.Properties.Name-contains'Evidence'){
                    [string]$f.Evidence
                }else{
                    ''
                });
                Write-CenteredLineVSO -Text ('  - '+$name+' · '+$ev) -Color $script:ThemeText
            }
            Write-VSOHost '';
            if((Read-CenteredPromptVSO -Text $(if($isEn){
                'Apply exactly this selection? [Y/N]'
            }else{
                '¿Aplicar exactamente esta seleccion? [S/N]'
            }))-notmatch'^[sSyY]$'){
                continue
            }
            if(-not(Confirm-VSO7HighRiskFeatureSelectionVSO -FeatureIds $reviewedIds -Catalog $catalog)){
                continue
            }
            try{
                $finalPlan=Get-VSO7FeatureSelectionPlanR75VSO -Operation Windows -FeatureIds $reviewedIds -Objective $objective
                # Standard preserves this selector's execution path, including manual/Special items.
                $execution=Invoke-VSO7FeaturePlanExecutionR75VSO -Plan $finalPlan -Mode Apply -ExecutionKind Standard
            }catch{
                Write-CenteredLineVSO -Text $_.Exception.Message -Color $script:ThemeDanger
                Pause-Vico
                continue
            }
            if([string]$execution.Status-ceq'Cancelled'){
                Pause-Vico
                continue
            }
            $ok=([string]$execution.Status-ceq'Succeeded')
            if(-not$ok-and-not[string]::IsNullOrWhiteSpace([string]$execution.Error)){
                Write-CenteredLineVSO -Text ([string]$execution.Error) -Color $script:ThemeDanger
            }
            if($ok){
                Write-CenteredLineVSO -Text $(if($isEn){
                    'Selection applied and verified.'
                }else{
                    'Seleccion aplicada y verificada.'
                }) -Color $script:ThemeSuccess
            }else{
                Write-CenteredLineVSO -Text $(if($isEn){
                    'The engine reported a failure; review Recovery/logs.'
                }else{
                    'El motor indico un fallo; revisa Recuperacion/logs.'
                }) -Color $script:ThemeDanger
            }
            Pause-Vico;
            return

        }

    }

}


function Get-VSO7PresetPlanR52VSO {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('Safe','Gaming','Balanced','Aggressive')][string]$Mode,
        [int[]]$SelectedIndexes
    )
    $items=New-Object 'Collections.Generic.List[object]'
    $addLegacy={
        param($n,$op,$nameKey,$reasonKey,$risk,$reversible,$restart)
        [void]$items.Add([pscustomobject]@{
            SelectionIndex=[int]$n;OperationId=[string]$op;FeatureId=$null;NameKey=[string]$nameKey;ReasonKey=[string]$reasonKey
            Risk=[int]$risk;Reversible=[bool]$reversible;Restart=[string]$restart;Fixed=$false;Raw=$null
        })
    }
    & $addLegacy 1 'EnableGameMode' 'EnableGameMode' 'PresetReasonGameMode' 1 $true 'None'
    & $addLegacy 2 'DisableBackgroundGameCapture' 'DisableCapture' 'PresetReasonCapture' 1 $true 'None'
    if($Mode-in@('Gaming','Balanced','Aggressive')){& $addLegacy 3 'SetHighPerformanceIfSafe' 'HighPerformance' 'PresetReasonPower' 2 $true 'None'}
    if($Mode-eq'Safe'){
        & $addLegacy 3 'RemoveOldTempFiles7Days' 'OldTemp' 'PresetReasonTemp' 1 $false 'None'
    }elseif($Mode-eq'Gaming'){
        & $addLegacy 4 'RemoveOldTempFiles7Days' 'OldTemp' 'PresetReasonTemp' 1 $false 'None'
    }else{
        if($Mode-eq'Aggressive'){& $addLegacy 4 'ApplyAggressiveVisualSettings' 'Transparency' 'PresetReasonVisual' 3 $true 'Logoff'}
        $cleanupIndex=if($Mode-eq'Aggressive'){5}else{4}
        & $addLegacy $cleanupIndex 'RemoveOldTempFiles7Days' 'OldTemp' 'PresetReasonTemp' 1 $false 'None'
        $nativeIds=@('V7PV002','V7PV007','V7PV008','DisableSearchHistory','V7AI001','V7AI002','V7AI003')
        $catalog=@(Get-VSO7FeatureCatalogVSO)
        foreach($id in $nativeIds){
            $f=@($catalog|Where-Object{[string]$_.FeatureId-ceq[string]$id}|Select-Object -First 1)
            if($f.Count-ne1){throw ('Preset references missing feature: '+$id)}
            [void]$items.Add([pscustomobject]@{
                SelectionIndex=0;OperationId='NativeFeature';FeatureId=[string]$id;NameKey='';ReasonKey='';Risk=[int]$f[0].Risk
                Reversible=$true;Restart=[string]$f[0].RebootRequirement;Fixed=$true;Raw=$f[0]
            })
        }
    }
    $editable=($Mode-in@('Safe','Gaming'))
    if($editable){
        $effective=if(-not$PSBoundParameters.ContainsKey('SelectedIndexes')){@($items|Where-Object{$_.SelectionIndex-gt0}|ForEach-Object{[int]$_.SelectionIndex})}else{@($SelectedIndexes|Sort-Object -Unique)}
        $selected=@($items|Where-Object{$_.SelectionIndex-gt0-and$effective-contains[int]$_.SelectionIndex})
    }else{$selected=$items.ToArray()}
    return [pscustomobject]@{
        Operation=$Mode;EditableSelection=[bool]$editable;Items=$items.ToArray();Selected=$selected
        NativeFeatureIds=@($selected|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_.FeatureId)}|ForEach-Object{[string]$_.FeatureId})
        LegacyOperations=@($selected|Where-Object{[string]::IsNullOrWhiteSpace([string]$_.FeatureId)}|ForEach-Object{[string]$_.OperationId})
    }
}

function Invoke-VSO7PresetPlanCoreR52VSO {
    param([Parameter(Mandatory=$true)]$Plan)
    if($null-eq$Plan-or@($Plan.Selected).Count-eq0){return $false}
    $restoreOk=if([string]$Plan.Operation-eq'Aggressive'){Require-RestorePoint -Aggressive}else{Require-RestorePoint}
    if(-not$restoreOk){return $false}
    Load-State
    foreach($item in @($Plan.Selected|Where-Object{[string]::IsNullOrWhiteSpace([string]$_.FeatureId)})){
        switch([string]$item.OperationId){
            'EnableGameMode'{[void](Enable-GameMode)}
            'DisableBackgroundGameCapture'{Disable-BackgroundGameCapture}
            'SetHighPerformanceIfSafe'{Set-HighPerformanceIfSafe}
            'ApplyAggressiveVisualSettings'{Apply-AggressiveVisualSettings}
            'RemoveOldTempFiles7Days'{Remove-OldTempFiles -OlderThanDays 7}
            default{throw ('Unknown canonical preset operation: '+[string]$item.OperationId)}
        }
    }
    $native=@($Plan.NativeFeatureIds)
    if($native.Count-gt0-and-not[bool](Invoke-VSO7NativeTweaksVSO -Features $native)){
        throw ('The VSO7 native engine could not apply one or more features for profile '+[string]$Plan.Operation+'.')
    }
    return $true
}

function New-VSO7CanonicalOperationResultR52VSO {
    param(
        [Parameter(Mandatory=$true)][string]$Operation,[string]$Objective='',
        [string[]]$SelectedFeatureIds=@(),[string[]]$SelectedAppIds=@(),[string[]]$ApplicableFeatureIds=@(),[string[]]$AlreadyOptimal=@(),
        [object[]]$Skipped=@(),[object[]]$Warnings=@(),[string[]]$LegacyOperations=@(),[bool]$RestartRequired=$false
    )
    [pscustomobject][ordered]@{
        Schema='VSO7.OperationResult.v1';Operation=$Operation;Objective=$Objective
        SelectedFeatureIds=@($SelectedFeatureIds|Where-Object{$_}|Sort-Object -Unique)
        SelectedAppIds=@($SelectedAppIds|Where-Object{$_}|Sort-Object -Unique)
        ApplicableFeatureIds=@($ApplicableFeatureIds|Where-Object{$_}|Sort-Object -Unique)
        AlreadyOptimal=@($AlreadyOptimal|Where-Object{$_}|Sort-Object -Unique)
        Skipped=@($Skipped);SkipReasons=@($Skipped|ForEach-Object{if($null-ne$_.PSObject.Properties['Reason']){[string]$_.Reason}else{[string]$_}})
        Warnings=@($Warnings);LegacyOperations=@($LegacyOperations|Where-Object{$_}|Sort-Object -Unique)
        ChangesPlanned=(@($SelectedFeatureIds).Count+@($SelectedAppIds).Count+@($LegacyOperations).Count)
        ChangesApplied=0;Failures=@();RestartRequired=[bool]$RestartRequired;RecoverySession=$null;FinalStatus='Planned'
    }
}

function Get-VSO7RecommendedAppRemovalPlanR52VSO {
    $apps=@(Get-VSO7AppCatalogVSO)
    $selected=@($apps|Where-Object{[bool]$_.SelectedByDefault-and[string]$_.Recommendation-ieq'safe'})
    $ids=@($selected|ForEach-Object{Get-VSO7AppIdsVSO -App $_}|Sort-Object -Unique)
    return New-VSO7CanonicalOperationResultR52VSO -Operation 'Applications' -SelectedAppIds $ids
}

function Get-VSO7RecommendedAppCatalogKeysR52VSO {
    $plan=Get-VSO7RecommendedAppRemovalPlanR52VSO
    $selectedIds=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach($id in @($plan.SelectedAppIds)){[void]$selectedIds.Add([string]$id)}
    $keys=New-Object 'Collections.Generic.List[string]'
    foreach($app in @(Get-VSO7AppCatalogVSO)){
        $match=$false
        foreach($id in @(Get-VSO7AppIdsVSO -App $app)){if($selectedIds.Contains([string]$id)){$match=$true;break}}
        if($match){[void]$keys.Add((Get-VSO7AppCatalogKeyVSO -App $app))}
    }
    return @($keys.ToArray())
}

function Get-VSO7CanonicalOperationPlanR52VSO {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('Recommended','Safe','Gaming','Balanced','Aggressive','Extreme','Windows','Applications')][string]$Operation,
        [ValidateSet('Balanced','Performance','Gaming','Responsiveness','PowerEfficiency')][string]$Objective='Performance',
        [switch]$IncludeOptional,[int[]]$SelectedIndexes,[string[]]$FeatureIds=@(),[string[]]$AppIds=@(),[switch]$RecommendedApps
    )
    if($Operation-eq'Recommended'){
        $plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective $Objective -IncludeOptional:$IncludeOptional
        $ids=@($plan.Selected|ForEach-Object{[string]$_.Feature.FeatureId})
        $applicable=@($plan.Selected|Where-Object{[bool]$_.Applicability.Applicable}|ForEach-Object{[string]$_.Feature.FeatureId})
        $optimal=@($plan.AlreadyOptimal|ForEach-Object{[string]$_.Feature.FeatureId})
        $restart=(@($plan.Selected|Where-Object{[string]$_.Feature.RebootRequirement-ine'None'}).Count-gt0)
        return New-VSO7CanonicalOperationResultR52VSO -Operation $Operation -Objective $Objective -SelectedFeatureIds $ids -ApplicableFeatureIds $applicable -AlreadyOptimal $optimal -Skipped @($plan.Skipped) -Warnings @($plan.Warnings) -RestartRequired $restart
    }
    if($Operation-in@('Safe','Gaming','Balanced','Aggressive')){
        $pp=if($PSBoundParameters.ContainsKey('SelectedIndexes')){Get-VSO7PresetPlanR52VSO -Mode $Operation -SelectedIndexes $SelectedIndexes}else{Get-VSO7PresetPlanR52VSO -Mode $Operation}
        $restart=(@($pp.Selected|Where-Object{[string]$_.Restart-ine'None'}).Count-gt0)
        return New-VSO7CanonicalOperationResultR52VSO -Operation $Operation -SelectedFeatureIds @($pp.NativeFeatureIds) -ApplicableFeatureIds @($pp.NativeFeatureIds) -LegacyOperations @($pp.LegacyOperations) -RestartRequired $restart
    }
    if($Operation-eq'Applications'){
        if($RecommendedApps){return Get-VSO7RecommendedAppRemovalPlanR52VSO}
        return New-VSO7CanonicalOperationResultR52VSO -Operation $Operation -SelectedAppIds $AppIds
    }
    $catalog=@(Get-VSO7FeatureCatalogVSO)
    $applicable=New-Object 'Collections.Generic.List[string]';$optimal=New-Object 'Collections.Generic.List[string]';$skipped=New-Object 'Collections.Generic.List[object]';$restart=$false
    foreach($id in @($FeatureIds|Sort-Object -Unique)){
        $f=@($catalog|Where-Object{[string]$_.FeatureId-ceq[string]$id}|Select-Object -First 1)
        if($f.Count-ne1){[void]$skipped.Add([pscustomobject]@{FeatureId=$id;Reason='Unknown FeatureId'});continue}
        $a=Get-VSO7FeatureApplicabilityVSO -Feature $f[0]
        if([bool]$a.Applicable){[void]$applicable.Add($id)}elseif([bool]$a.AlreadySatisfied){[void]$optimal.Add($id)}else{[void]$skipped.Add([pscustomobject]@{FeatureId=$id;Reason=[string]$a.ReasonEn})}
        if([string]$f[0].RebootRequirement-ine'None'){$restart=$true}
    }
    return New-VSO7CanonicalOperationResultR52VSO -Operation $Operation -SelectedFeatureIds $FeatureIds -ApplicableFeatureIds $applicable.ToArray() -AlreadyOptimal $optimal.ToArray() -Skipped $skipped.ToArray() -RestartRequired $restart
}

function Get-VSO7FeatureSelectionPlanR75VSO {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('Windows','Graphics','Recommended')][string]$Operation,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][string[]]$FeatureIds,
        [ValidateSet('Balanced','Performance','Gaming','Privacy','Responsiveness','PowerEfficiency')][string]$Objective='Performance',
        [AllowNull()]$SourcePlan=$null
    )
    $ids=@($FeatureIds|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|ForEach-Object{[string]$_}|Sort-Object -Unique)
    if($null-ne$SourcePlan){
        if([string]$SourcePlan.Schema-cne'VSO7.OperationResult.v1'){throw 'El plan fuente recomendado no cumple el contrato canonico VSO7.OperationResult.v1.'}
        if([string]$SourcePlan.Operation-cne'Recommended'){throw 'El plan fuente no pertenece a Recommended.'}
        if(-not[string]::IsNullOrWhiteSpace([string]$SourcePlan.Objective)-and[string]$SourcePlan.Objective-cne[string]$Objective){throw 'El objetivo actual ya no coincide con el preview recomendado confirmado.'}
        $allowed=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
        foreach($id in @($SourcePlan.SelectedFeatureIds)){[void]$allowed.Add([string]$id)}
        $outside=@($ids|Where-Object{-not$allowed.Contains([string]$_)})
        if($outside.Count-gt0){throw ('La seleccion visible contiene FeatureIds que no pertenecen al preview recomendado vigente: '+($outside-join', '))}
    }
    $catalog=@(Get-VSO7FeatureCatalogVSO)
    if($ids.Count-gt0){[void](Assert-VSO7FeatureSelectionRelationsVSO -Requested $ids -Catalog $catalog)}
    $applicable=New-Object 'Collections.Generic.List[string]'
    $optimal=New-Object 'Collections.Generic.List[string]'
    $skipped=New-Object 'Collections.Generic.List[object]'
    $restart=$false
    foreach($id in $ids){
        $f=@($catalog|Where-Object{[string]$_.FeatureId-ceq[string]$id}|Select-Object -First 1)
        if($f.Count-ne1){throw ('FeatureId desconocido en seleccion confirmada: '+[string]$id)}
        $a=Get-VSO7FeatureApplicabilityVSO -Feature $f[0]
        if([bool]$a.Applicable){[void]$applicable.Add([string]$id)}
        elseif([bool]$a.AlreadySatisfied){[void]$optimal.Add([string]$id)}
        else{[void]$skipped.Add([pscustomobject]@{FeatureId=[string]$id;Reason=[string]$(if($script:Language-eq'es'){$a.ReasonEs}else{$a.ReasonEn})})}
        if([string]$f[0].RebootRequirement-ine'None'){$restart=$true}
    }
    $plan=New-VSO7CanonicalOperationResultR52VSO -Operation $Operation -Objective $Objective -SelectedFeatureIds $ids -ApplicableFeatureIds $applicable.ToArray() -AlreadyOptimal $optimal.ToArray() -Skipped $skipped.ToArray() -RestartRequired $restart
    if($null-ne$SourcePlan-and$null-ne$SourcePlan.PSObject.Properties['PreviewId']){$plan|Add-Member -NotePropertyName SourcePreviewId -NotePropertyValue ([string]$SourcePlan.PreviewId) -Force}
    return $plan
}

function New-VSO7FeatureExecutionResultR75VSO {
    param(
        [Parameter(Mandatory=$true)]$Plan,
        [Parameter(Mandatory=$true)][ValidateSet('Planned','Succeeded','Partial','Failed','Cancelled')][string]$Status,
        [string[]]$ExecutedFeatureIds=@(),[AllowNull()]$Preflight=$null,[string]$BatchId='',[AllowNull()][Nullable[bool]]$EngineSucceeded=$null,[string]$Error=''
    )
    return [pscustomobject][ordered]@{
        Schema='VSO7.FeatureExecutionResult.v1';Status=$Status;Plan=$Plan
        SelectedFeatureIds=@($Plan.SelectedFeatureIds);ExecutedFeatureIds=@($ExecutedFeatureIds)
        AlreadyOptimal=@($Plan.AlreadyOptimal);Skipped=@($Plan.Skipped);Preflight=$Preflight;BatchId=$BatchId
        EngineSucceeded=$EngineSucceeded;Error=$Error
    }
}

function Invoke-VSO7FeaturePlanExecutionR75VSO {
    param(
        [Parameter(Mandatory=$true)]$Plan,
        [ValidateSet('Simulation','Apply')][string]$Mode='Apply',
        [ValidateSet('Standard','Recommended')][string]$ExecutionKind='Standard'
    )
    if([string]$Plan.Schema-cne'VSO7.OperationResult.v1'){throw 'El executor recibio un plan canonico invalido.'}
    $selected=@($Plan.SelectedFeatureIds|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)})
    if($selected.Count-eq0){return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Failed -Error 'La operacion no contiene FeatureIds seleccionados.'}
    if($Mode-eq'Simulation'){
        return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Planned -ExecutedFeatureIds @()
    }
    if(@($Plan.Skipped).Count-gt0){
        $detail=@($Plan.Skipped|ForEach-Object{if($null-ne$_.PSObject.Properties['FeatureId']){([string]$_.FeatureId+': '+[string]$_.Reason)}else{[string]$_}})-join'; '
        return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Failed -Error ('La seleccion contiene objetivos no aplicables: '+$detail)
    }
    $execute=@($Plan.ApplicableFeatureIds|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}|Sort-Object -Unique)
    if($execute.Count-eq0){
        if(@($Plan.AlreadyOptimal).Count-eq$selected.Count){return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Succeeded -ExecutedFeatureIds @() -EngineSucceeded $true}
        return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Failed -Error 'La seleccion confirmada no contiene ninguna mutacion aplicable.'
    }
    $preflight=$null;$batchId=''
    try{
        if($ExecutionKind-eq'Recommended'){
            $preflight=Invoke-VSO7RecommendedPreflightVSO -FeatureIds $execute
            if($null-eq$preflight-or-not[bool]$preflight.Pass){return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Failed -ExecutedFeatureIds $execute -Preflight $preflight -Error 'El preflight global recomendado no paso.'}
        }
        if(-not(Require-RestorePoint)){
            return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Cancelled -ExecutedFeatureIds @() -Preflight $preflight -Error 'No se autorizo o no se pudo verificar el punto de restauracion requerido.'
        }
        if($ExecutionKind-eq'Recommended'){
            $batchId=[guid]::NewGuid().ToString('N')
            $ok=[bool](Invoke-VSO7NativeTweaksVSO -Features $execute -BatchKind 'RecommendedOptimization' -BatchId $batchId -BatchObjective ([string]$Plan.Objective) -PreflightBaselines @($preflight.Baselines))
        }else{
            $ok=[bool](Invoke-VSO7NativeTweaksVSO -Features $execute)
        }
        return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status $(if($ok){'Succeeded'}else{'Failed'}) -ExecutedFeatureIds $execute -Preflight $preflight -BatchId $batchId -EngineSucceeded $ok -Error $(if($ok){''}else{'El motor nativo devolvio fallo.'})
    }catch{
        return New-VSO7FeatureExecutionResultR75VSO -Plan $Plan -Status Failed -ExecutedFeatureIds $execute -Preflight $preflight -BatchId $batchId -EngineSucceeded $false -Error ([string]$_.Exception.Message)
    }
}

function Reset-VSO7GuiRecommendedPlanR75VSO {
    param([AllowNull()]$Context=$null)
    $script:GuiRecommendedPlan=$null
    if($null-ne$Context-and$null-ne$Context.PSObject.Properties['Apply']-and$null-ne$Context.Apply){$Context.Apply.IsEnabled=$false}
}

function Invoke-VSO7GuiFeatureDryRunR75VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $ids=@($Context.Rows|Where-Object{$_.IsSelected}|ForEach-Object{[string]$_.Id})
    if($ids.Count-eq0){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'NoSelection');return $null}
    $plan=Get-VSO7FeatureSelectionPlanR75VSO -Operation ([string]$Context.Mode) -FeatureIds $ids -Objective $(if($null-ne$Context.PSObject.Properties['Objective']-and$null-ne$Context.Objective){Get-VSO7GuiObjectiveValueR69VSO -ComboBox $Context.Objective}else{'Performance'})
    $result=Invoke-VSO7FeaturePlanExecutionR75VSO -Plan $plan -Mode Simulation
    if([string]$result.Status-cne'Planned'){throw ([string]$result.Error)}
    $msg=Get-VSO7GuiStringVSO 'DryRunOk' -Args @(@($plan.ApplicableFeatureIds).Count)
    if(@($plan.AlreadyOptimal).Count-gt0){$msg+=' '+$(if($script:Language-eq'es'){'Ya óptimos: '}else{'Already optimal: '})+@($plan.AlreadyOptimal).Count+'.'}
    if(@($plan.Skipped).Count-gt0){$msg+=' '+$(if($script:Language-eq'es'){'No aplicables: '}else{'Not applicable: '})+@($plan.Skipped).Count+'.'}
    Set-VSO7GuiStatusVSO $msg
    return $result
}

function Invoke-VSO7GuiFeatureApplyR75VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $selected=@($Context.Rows|Where-Object{$_.IsSelected})
    if($selected.Count-eq0){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'NoSelection');return $null}
    $ids=@($selected|ForEach-Object{[string]$_.Id})
    $plan=Get-VSO7FeatureSelectionPlanR75VSO -Operation ([string]$Context.Mode) -FeatureIds $ids -Objective $(if($null-ne$Context.PSObject.Properties['Objective']-and$null-ne$Context.Objective){Get-VSO7GuiObjectiveValueR69VSO -ComboBox $Context.Objective}else{'Performance'})
    if(@($plan.Skipped).Count-gt0){throw ('La seleccion contiene ajustes no aplicables: '+(@($plan.Skipped|ForEach-Object{[string]$_.FeatureId})-join', '))}
    $restart=@($selected|Where-Object{$_.RestartText-notin@('No restart','Sin reinicio')})
    $riskCatalog=@(Get-VSO7FeatureCatalogVSO)
    if(-not(Confirm-VSO7HighRiskFeatureSelectionVSO -FeatureIds $ids -Catalog $riskCatalog)){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Cancelled');return New-VSO7FeatureExecutionResultR75VSO -Plan $plan -Status Cancelled}
    $msg=$(if($script:Language-eq'es'){"Aplicar $($selected.Count) cambios. $($restart.Count) requieren reinicio. ¿Continuar?"}else{"Apply $($selected.Count) changes. $($restart.Count) require restart. Continue?"})
    if(-not(Show-VSO7GuiConfirmVSO $msg)){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Cancelled');return New-VSO7FeatureExecutionResultR75VSO -Plan $plan -Status Cancelled}
    $result=Invoke-VSO7FeaturePlanExecutionR75VSO -Plan $plan -Mode Apply -ExecutionKind Standard
    if([string]$result.Status-ceq'Succeeded'){try{[void](Save-VSO7LastAppliedSelectionR76VSO -Features $ids)}catch{};Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Done');return $result}
    if([string]$result.Status-ceq'Cancelled'){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Cancelled');return $result}
    throw $(if([string]::IsNullOrWhiteSpace([string]$result.Error)){Get-VSO7GuiStringVSO 'OperationFailed'}else{[string]$result.Error})
}

function Invoke-VSO7GuiRecommendedApplyR75VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $source=$script:GuiRecommendedPlan
    if($null-eq$source){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'PreviewFirst');return $null}
    $objective=Get-VSO7GuiObjectiveValueR69VSO -ComboBox $Context.Objective
    $includeOptional=[bool]$Context.Optional.IsChecked
    if([string]$source.Objective-cne[string]$objective-or$null-eq$source.PSObject.Properties['IncludeOptional']-or[bool]$source.IncludeOptional-ne$includeOptional){Reset-VSO7GuiRecommendedPlanR75VSO -Context $Context;Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'PreviewFirst');return $null}
    $ids=@($Context.Rows|Where-Object{$_.IsSelected}|ForEach-Object{[string]$_.Id})
    if($ids.Count-eq0){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'NoSelection');return $null}
    $plan=Get-VSO7FeatureSelectionPlanR75VSO -Operation Recommended -FeatureIds $ids -Objective $objective -SourcePlan $source
    if(@($plan.Skipped).Count-gt0){throw ('La seleccion recomendada contiene ajustes que ya no son aplicables: '+(@($plan.Skipped|ForEach-Object{[string]$_.FeatureId})-join', '))}
    if(-not(Show-VSO7GuiConfirmVSO (Get-VSO7GuiStringVSO 'ConfirmApply'))){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Cancelled');return New-VSO7FeatureExecutionResultR75VSO -Plan $plan -Status Cancelled}
    $result=Invoke-VSO7FeaturePlanExecutionR75VSO -Plan $plan -Mode Apply -ExecutionKind Recommended
    if([string]$result.Status-ceq'Succeeded'){try{[void](Save-VSO7LastAppliedSelectionR76VSO -Features $ids)}catch{};Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Done');Reset-VSO7GuiRecommendedPlanR75VSO -Context $Context;return $result}
    Reset-VSO7GuiRecommendedPlanR75VSO -Context $Context
    if([string]$result.Status-ceq'Cancelled'){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Cancelled');return $result}
    throw $(if([string]::IsNullOrWhiteSpace([string]$result.Error)){Get-VSO7GuiStringVSO 'OperationFailed'}else{[string]$result.Error})
}

function New-VSO7OperationOutcomeR76VSO {
    param(
        [Parameter(Mandatory=$true)][string]$Operation,
        [Parameter(Mandatory=$true)][ValidateSet('Success','Partial','Failed','Cancelled')][string]$Status,
        [object[]]$Steps=@(),[int]$AppliedCount=0,[int]$FailedCount=0,
        [ValidateSet('NotApplicable','NotAttempted','Complete','Partial','Failed')][string]$RollbackStatus='NotApplicable',
        [string]$RecoveryBundle='',[string]$Error=''
    )
    return [pscustomobject][ordered]@{
        Schema='VSO7.OperationOutcome.v1';Operation=$Operation;Status=$Status;Steps=@($Steps)
        AppliedCount=[int]$AppliedCount;FailedCount=[int]$FailedCount;RollbackStatus=$RollbackStatus
        RecoveryBundle=$RecoveryBundle;Error=$Error
    }
}

function New-VSO7RecoveryStepResultR76VSO {
    param([Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][bool]$Success,[string]$Error='')
    return [pscustomobject][ordered]@{Name=$Name;Success=$Success;Error=$Error}
}

function Invoke-VSO7RecoveryOperationR76VSO {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('Normal','Extreme','Startup','Native','All')][string]$Operation,
        [AllowNull()]$Session=$null
    )
    $steps=New-Object 'Collections.Generic.List[object]'
    function Invoke-R76RecoveryStep {
        param([string]$Name,[scriptblock]$Code)
        $ok=$false;$err=''
        try{$ok=[bool](& $Code);if(-not$ok){$err='La operacion de recuperacion devolvio false.'}}catch{$err=[string]$_.Exception.Message;$ok=$false}
        [void]$steps.Add((New-VSO7RecoveryStepResultR76VSO -Name $Name -Success $ok -Error $err))
    }
    switch($Operation){
        'Normal'{
            Invoke-R76RecoveryStep -Name 'Registry' -Code { Restore-TrackedRegistry }
            Invoke-R76RecoveryStep -Name 'PowerScheme' -Code { Restore-PowerScheme }
        }
        'Extreme'{ Invoke-R76RecoveryStep -Name 'Extreme' -Code { Restore-AllExtremeChanges } }
        'Startup'{ Invoke-R76RecoveryStep -Name 'Startup' -Code { Restore-AllStartupChangesVSO } }
        'Native'{
            if($null-eq$Session){return New-VSO7OperationOutcomeR76VSO -Operation 'Recovery.Native' -Status Failed -Error 'No se proporciono una sesion nativa de Recovery.'}
            Invoke-R76RecoveryStep -Name 'Native' -Code { Restore-VSO7NativeBackupSessionVSO -Session $Session }
        }
        'All'{
            try{[void](Assert-VSO7RevertAllOrderSafeVSO)}catch{return New-VSO7OperationOutcomeR76VSO -Operation 'Recovery.All' -Status Failed -Error ([string]$_.Exception.Message)}
            $index=0
            foreach($nativeSession in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{[string]$_.Status-ne'Restored'}|Sort-Object CreatedAt -Descending)){
                $index++
                $captured=$nativeSession
                Invoke-R76RecoveryStep -Name ('Native#'+$index) -Code { Restore-VSO7NativeBackupSessionVSO -Session $captured }
            }
            Invoke-R76RecoveryStep -Name 'Extreme' -Code { Restore-AllExtremeChanges }
            Invoke-R76RecoveryStep -Name 'Registry' -Code { Restore-TrackedRegistry }
            Invoke-R76RecoveryStep -Name 'PowerScheme' -Code { Restore-PowerScheme }
            Invoke-R76RecoveryStep -Name 'Startup' -Code { Restore-AllStartupChangesVSO }
        }
    }
    $all=@($steps.ToArray());$failed=@($all|Where-Object{-not[bool]$_.Success});$passed=@($all|Where-Object{[bool]$_.Success})
    $status=if($failed.Count-eq0){'Success'}elseif($passed.Count-eq0){'Failed'}else{'Partial'}
    $error=if($failed.Count){(@($failed|ForEach-Object{[string]$_.Name+': '+[string]$_.Error})-join'; ')}else{''}
    return New-VSO7OperationOutcomeR76VSO -Operation ('Recovery.'+$Operation) -Status $status -Steps $all -AppliedCount $passed.Count -FailedCount $failed.Count -RollbackStatus $(if($failed.Count-eq0){'Complete'}elseif($passed.Count-eq0){'Failed'}else{'Partial'}) -Error $error
}

function Set-VSO7GuiOperationOutcomeR76VSO {
    param([Parameter(Mandatory=$true)]$Outcome)
    switch([string]$Outcome.Status){
        'Success'{Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Done')}
        'Cancelled'{Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'Cancelled')}
        'Partial'{Set-VSO7GuiStatusVSO $(if($script:Language-eq'es'){'Operación parcial: quedan elementos pendientes. Revisa Recuperación y el log.'}else{'Partial operation: some items remain pending. Check Recovery and the log.'})}
        default{Set-VSO7GuiStatusVSO $(if($script:Language-eq'es'){'La operación falló. Quedan elementos pendientes; revisa Recuperación y el log.'}else{'The operation failed. Pending items remain; check Recovery and the log.'})}
    }
    return $Outcome
}

