function Get-VSO7CanonicalPlanJsonR52VSO {param([Parameter(Mandatory=$true)]$Plan);return ($Plan|ConvertTo-Json -Depth 14 -Compress)}
function Get-VSO7CanonicalPlanHashR52VSO {
    param([Parameter(Mandatory=$true)]$Plan)
    $bytes=[Text.Encoding]::UTF8.GetBytes((Get-VSO7CanonicalPlanJsonR52VSO -Plan $Plan));$sha=[Security.Cryptography.SHA256]::Create()
    try{return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','')}finally{$sha.Dispose()}
}

