function Invoke-VSO7BalancedCoreVSO {
    return [bool](Invoke-VSO7PresetPlanCoreR52VSO -Plan (Get-VSO7PresetPlanR52VSO -Mode Balanced))
}

function Invoke-VSO7AggressiveCoreVSO {
    return [bool](Invoke-VSO7PresetPlanCoreR52VSO -Plan (Get-VSO7PresetPlanR52VSO -Mode Aggressive))
}

function Show-VSO7SafeSelector {

    $selected=@(1,2,3)
    while($true){

        Write-Title;
        Write-CenteredLineVSO -Text 'OPTIMIZACION SEGURA - SELECTOR' -Color $script:ThemeSuccess;
        Write-VSOHost ''
        Write-CenteredLineVSO -Text 'Entrar en esta pantalla NO aplica cambios. Activa o desactiva cada opcion y despues elige Aplicar seleccion.' -Color $script:ThemeText;
        Write-VSOHost ''
        $isEn=($script:Language-eq'en')
        $opts=if($isEn){
            @(
            [pscustomobject]@{
                N=1;Name='Enable Game Mode';Desc='Enables Windows Game Mode so Windows can prioritize the gaming experience when it detects a game.'
            },
            [pscustomobject]@{
                N=2;Name='Disable game recording and background capture';Desc='Stops Windows from keeping game recording/capture ready in the background. Manual captures still depend on the tools you use.'
            },
            [pscustomobject]@{
                N=3;Name='Clean old temporary files';Desc='Removes only temporary files older than 7 days using VSO7 safety exclusions.'
            }
        )
        }else{
            @(
            [pscustomobject]@{
                N=1;Name='Activar Modo de juego';Desc='Activa el Modo de juego de Windows para priorizar la experiencia de juego cuando detecta un juego.'
            },
            [pscustomobject]@{
                N=2;Name='Desactivar grabacion de juegos y capturas en segundo plano';Desc='Evita que Windows mantenga la grabacion/captura de juegos preparada en segundo plano. Las capturas manuales siguen dependiendo de las herramientas que uses.'
            },
            [pscustomobject]@{
                N=3;Name='Limpiar temporales antiguos';Desc='Elimina solo temporales con mas de 7 dias usando las exclusiones de seguridad de VSO7.'
            }
        )
        }
        $rows=@();
        foreach($o in $opts){
            $on=($selected-contains[int]$o.N);
            $mark='[ ]';
            $color='Gray';
            if($on){
                $mark='[X]';
                $color='Green'
            };
            $rows+=[pscustomobject]@{
                Text=("[{0}] {1} {2}"-f$o.N,$mark,$o.Name);
                Color=$color;
                Description=$o.Desc
            }
        }
        Write-CenteredMenuVSO -Items $rows;
        Write-VSOHost ''
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=$(if($isEn){
                '[4] Apply selection'
            }else{
                '[4] Aplicar seleccion'
            });Color='Green';Description=$(if($isEn){
                'Applies only the selected options after checking recovery.'
            }else{
                'Aplica solo las opciones marcadas despues de comprobar recuperacion.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[5] Select recommended'
            }else{
                '[5] Seleccionar recomendadas'
            });Color='Cyan';Description=$(if($isEn){
                'Selects the three conservative options again.'
            }else{
                'Vuelve a marcar las tres opciones conservadoras.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion / numero para activar-desactivar';
        $n=0;
        if($c-eq'0'){
            return
        };
        if(-not[int]::TryParse($c,[ref]$n)){
            continue
        }
        if($n-ge1-and$n-le3){
            if($selected-contains$n){
                $selected=@($selected|Where-Object{
                    $_-ne$n
                })
            }else{
                $selected+=,$n
            };
            continue
        }
        if($n-eq5){
            $selected=@(1,2,3);
            continue
        }
        if($n-eq4){

            if($selected.Count-eq0){
                Write-CenteredLineVSO -Text 'No hay opciones seleccionadas.' -Color $script:ThemeWarning;
                continue
            }
            try{
                if(-not(Invoke-VSO7SafeSelectionCoreVSO -Selected @($selected))){
                    Pause-Vico;
                    return
                }
                Write-VSOHost '';
                Write-CenteredLineVSO -Text 'Optimizacion segura terminada.' -Color $script:ThemeSuccess
            }catch{
                Write-VSO7Log ("Optimizacion segura interrumpida: {0}"-f$_.Exception.Message) 'ERROR';
                Write-VSOHost $_.Exception.Message -ForegroundColor Red;
                Write-CenteredLineVSO -Text $(if($isEn){
                    'The safe optimization was interrupted; an earlier selected change may already have been applied. Review Recovery/logs.'
                }else{
                    'La optimizacion segura fue interrumpida; algun cambio anterior seleccionado puede haberse aplicado. Revisa Recuperacion/logs.'
                }) -Color $script:ThemeWarning
            };
            Pause-Vico;
            return

        }

    }

}

function Show-VSO7GamingSelector {

    $selected=@(1,2,3,4)
    while($true){

        Write-Title;
        Write-CenteredLineVSO -Text 'OPTIMIZACION GAMING PERMANENTE - SELECTOR' -Color $script:ThemeSuccess;
        Write-VSOHost ''
        Write-CenteredLineVSO -Text 'Entrar en esta pantalla NO aplica cambios. Activa o desactiva cada opcion y despues elige Aplicar seleccion.' -Color $script:ThemeText;
        Write-VSOHost ''
        $isEn=($script:Language-eq'en')
        $opts=if($isEn){
            @(
            [pscustomobject]@{
                N=1;Name='Enable Game Mode';Desc='Enables Windows Game Mode so Windows can prioritize the gaming experience when it detects a game.'
            },
            [pscustomobject]@{
                N=2;Name='Disable game recording and background capture';Desc='Reduces Windows capture activity when you do not use its built-in recording.'
            },
            [pscustomobject]@{
                N=3;Name='Use High performance when safe';Desc='Only switches to a standard Windows plan if VSO7 can save and restore the previous one; OEM and custom plans are not replaced.'
            },
            [pscustomobject]@{
                N=4;Name='Clean old temporary files';Desc='Cleans temporary files older than 7 days using VSO7 safety exclusions.'
            }
        )
        }else{
            @(
            [pscustomobject]@{
                N=1;Name='Activar Modo de juego';Desc='Activa el Modo de juego de Windows para priorizar la experiencia de juego cuando detecta un juego.'
            },
            [pscustomobject]@{
                N=2;Name='Desactivar grabacion de juegos y capturas en segundo plano';Desc='Reduce la actividad de captura de Windows cuando no usas su grabacion integrada.'
            },
            [pscustomobject]@{
                N=3;Name='Usar Alto rendimiento si es seguro';Desc='Solo cambia a un plan estandar de Windows si VSO7 puede guardar y restaurar el anterior; no sustituye planes OEM o personalizados.'
            },
            [pscustomobject]@{
                N=4;Name='Limpiar temporales antiguos';Desc='Limpia temporales de mas de 7 dias con las exclusiones de seguridad de VSO7.'
            }
        )
        }
        $rows=@();
        foreach($o in $opts){
            $on=($selected-contains[int]$o.N);
            $mark='[ ]';
            $color='Gray';
            if($on){
                $mark='[X]';
                $color='Green'
            };
            $rows+=[pscustomobject]@{
                Text=("[{0}] {1} {2}"-f$o.N,$mark,$o.Name);
                Color=$color;
                Description=$o.Desc
            }
        }
        Write-CenteredMenuVSO -Items $rows;
        Write-VSOHost ''
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=$(if($isEn){
                '[5] Apply selection'
            }else{
                '[5] Aplicar seleccion'
            });Color='Green';Description=$(if($isEn){
                'Applies only the selected options after checking recovery.'
            }else{
                'Aplica solo las opciones marcadas despues de comprobar recuperacion.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[6] Select all'
            }else{
                '[6] Seleccionar todas'
            });Color='Cyan';Description=$(if($isEn){
                'Selects all four options in this gaming profile.'
            }else{
                'Marca las cuatro opciones de este perfil gaming.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[7] Clear selection'
            }else{
                '[7] Quitar seleccion'
            });Color='Gray';Description=$(if($isEn){
                'Clears everything so you can start from zero.'
            }else{
                'Desmarca todo para empezar desde cero.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion / numero para activar-desactivar';
        $n=0;
        if($c-eq'0'){
            return
        };
        if(-not[int]::TryParse($c,[ref]$n)){
            continue
        }
        if($n-ge1-and$n-le4){
            if($selected-contains$n){
                $selected=@($selected|Where-Object{
                    $_-ne$n
                })
            }else{
                $selected+=,$n
            };
            continue
        };
        if($n-eq6){
            $selected=@(1,2,3,4);
            continue
        };
        if($n-eq7){
            $selected=@();
            continue
        }
        if($n-eq5){
            if($selected.Count-eq0){
                Write-CenteredLineVSO -Text 'No hay opciones seleccionadas.' -Color $script:ThemeWarning;
                continue
            };
            try{
                if(-not(Invoke-VSO7GamingSelectionCoreVSO -Selected @($selected))){
                    Pause-Vico;
                    return
                }
                Write-CenteredLineVSO -Text 'Optimizacion gaming terminada.' -Color $script:ThemeSuccess
            }catch{
                Write-VSO7Log ("Optimizacion gaming interrumpida: {0}"-f$_.Exception.Message) 'ERROR';
                Write-VSOHost $_.Exception.Message -ForegroundColor Red;
                Write-CenteredLineVSO -Text $(if($isEn){
                    'The gaming optimization was interrupted; an earlier selected change may already have been applied. Review Recovery/logs.'
                }else{
                    'La optimizacion gaming fue interrumpida; algun cambio anterior seleccionado puede haberse aplicado. Revisa Recuperacion/logs.'
                }) -Color $script:ThemeWarning
            };
            Pause-Vico;
            return
        }

    }

}

function Invoke-VSO7BalancedOptimization {

    $isEn=($script:Language-eq'en')
    Write-Title;
    Write-CenteredLineVSO -Text $(if($isEn){
        'BALANCED OPTIMIZATION'
    }else{
        'OPTIMIZACION EQUILIBRADA'
    }) -Color $script:ThemeCopper;
    Write-VSOHost ''
    if($isEn){

        Write-VSOHost 'This is a quick low-to-medium risk mode. It shows exactly what it includes before applying.' -ForegroundColor Gray;
        Write-VSOHost ''
        Write-VSOHost 'Includes:' -ForegroundColor Cyan
        Write-VSOHost '  - Enable Windows Game Mode.'
        Write-VSOHost '  - Disable game recording/background capture.'
        Write-VSOHost '  - Use High performance only when the current power plan is a standard reversible Windows plan.'
        Write-VSOHost '  - Clean temporary files older than 7 days.'
        Write-VSOHost '  - Disable Windows suggestions, Edge/Settings ads and search history.'
        Write-VSOHost '  - Disable Copilot, Recall and Click to Do when available on this build.'
        Write-VSOHost ''
        Write-VSOHost 'It does NOT disable Defender, Firewall, Windows Update, VBS, existing BitLocker, or critical services.' -ForegroundColor Green
        Write-VSOHost '';
        Write-VSOHost 'Type BALANCED to apply; anything else cancels.' -ForegroundColor Yellow

    }else{

        Write-VSOHost 'Es un modo rapido de riesgo bajo-medio. Antes de aplicar muestra exactamente lo que incluye.' -ForegroundColor Gray;
        Write-VSOHost ''
        Write-VSOHost 'Incluye:' -ForegroundColor Cyan
        Write-VSOHost '  - Activar el Modo de juego de Windows.'
        Write-VSOHost '  - Desactivar grabacion/captura de juegos en segundo plano.'
        Write-VSOHost '  - Usar Alto rendimiento solo si el plan actual es estandar de Windows y reversible.'
        Write-VSOHost '  - Limpiar temporales de mas de 7 dias.'
        Write-VSOHost '  - Desactivar sugerencias de Windows, anuncios de Edge/Configuracion y el historial de busqueda.'
        Write-VSOHost '  - Desactivar Copilot, Recall y Click to Do cuando existan en esta build.'
        Write-VSOHost ''
        Write-VSOHost 'NO desactiva Defender, Firewall, Windows Update, VBS, BitLocker existente ni servicios criticos.' -ForegroundColor Green
        Write-VSOHost '';
        Write-VSOHost 'Escribe EQUILIBRADO para aplicar; cualquier otra cosa cancela.' -ForegroundColor Yellow

    }
    if(-not(Confirm-Word -Word 'EQUILIBRADO' -Message 'Escribe exactamente EQUILIBRADO para aplicar')){
        Write-VSOHost $(if($isEn){
            'Cancelled.'
        }else{
            'Cancelado.'
        });
        Pause-Vico;
        return
    }
    try{
        if(-not(Invoke-VSO7BalancedCoreVSO)){
            Pause-Vico;
            return
        }
        Write-VSOHost $(if($isEn){
            'Balanced optimization completed.'
        }else{
            'Optimizacion equilibrada terminada.'
        }) -ForegroundColor Green
    }catch{
        Write-VSO7Log ("Optimizacion equilibrada interrumpida: {0}"-f$_.Exception.Message) 'ERROR';
        Write-VSOHost $_.Exception.Message -ForegroundColor Red;
        Write-CenteredLineVSO -Text $(if($isEn){
            'Balanced optimization was INTERRUPTED: some earlier changes may already have been applied. Review Recovery/logs.'
        }else{
            'La optimizacion equilibrada fue INTERRUMPIDA: algunos cambios anteriores pueden haberse aplicado. Revisa Recuperacion/logs.'
        }) -Color $script:ThemeWarning
    };
    Pause-Vico

}

function Show-VSO7RestorePointPrompt {

    Write-Title;
    Write-CenteredLineVSO -Text 'PUNTO DE RESTAURACION' -Color $script:ThemeCopper;
    Write-VSOHost ''
    Write-CenteredLineVSO -Text 'Esta opcion comprueba Restauracion del sistema y puede crear un punto de restauracion manual.' -Color $script:ThemeText;
    Write-VSOHost ''
    $isEn=($script:Language-eq'en')
    $a=Read-CenteredPromptVSO -Text $(if($isEn){
        'Do you want to create/check a restore point now? [Y/N]'
    }else{
        '¿Quieres crear/comprobar un punto de restauracion ahora? [S/N]'
    })
    $accepted=if($isEn){
        $a-match'^[yY]$'
    }else{
        $a-match'^[sS]$'
    }
    if($accepted){
        Invoke-VSO7CreateRestoreCheckpointVSO
    }else{
        Write-VSOHost $(if($isEn){
            'Cancelled.'
        }else{
            'Cancelado.'
        }) -ForegroundColor Gray;
        Start-Sleep -Milliseconds 600
    }

}

function Get-VSO7RequiredGuiControlVSO {

    param(
        [Parameter(Mandatory=$true)]$Window,
        [Parameter(Mandatory=$true)][string]$Name
    )
    $control=$Window.FindName($Name)
    if($null-eq$control){
        throw ('Contrato GUI invalido: no se encontro el control WPF {0}.'-f$Name)
    }
    return $control

}

