function Get-VSO7GuiStringVSO {
    param([Parameter(Mandatory=$true)][string]$Key,[object[]]$Args=@())
    if(-not$script:VSO7GuiStrings.Contains($Key)){ throw ('Missing canonical English GUI key: '+$Key) }
    $row=$script:VSO7GuiStrings[$Key]
    $english=[string]$row.en
    if($null-eq$row.PSObject -or [string]::IsNullOrWhiteSpace($english)){
        throw ('Invalid canonical English GUI key: '+$Key)
    }
    $lang=if([string]$script:Language-ieq'es'){'es'}else{'en'}
    $value=if($lang-eq'es' -and -not[string]::IsNullOrWhiteSpace([string]$row.es)){[string]$row.es}else{$english}
    if($Args.Count-gt0){ return ($value -f $Args) }
    return $value
}


function Get-VSO7ResponsiveWindowMetricsVSO {
    param(
        [double]$PreferredWidth=840,
        [double]$PreferredHeight=560,
        [double]$BaseMinWidth=620,
        [double]$BaseMinHeight=420,
        [Nullable[double]]$WorkWidth=$null,
        [Nullable[double]]$WorkHeight=$null
    )
    if($null-eq$WorkWidth-or$null-eq$WorkHeight){Add-Type -AssemblyName PresentationFramework -ErrorAction Stop}
    $ww=if($null-ne$WorkWidth){[double]$WorkWidth}else{[double][Windows.SystemParameters]::WorkArea.Width}
    $wh=if($null-ne$WorkHeight){[double]$WorkHeight}else{[double][Windows.SystemParameters]::WorkArea.Height}
    if($ww-le0-or$wh-le0){throw 'Invalid WPF work area.'}
    # Values are WPF device-independent units. The work area therefore naturally
    # shrinks as Windows DPI scaling rises, without pixel-coordinate assumptions.
    $maxInitialWidth=[Math]::Max(320,[Math]::Floor($ww*0.92))
    $maxInitialHeight=[Math]::Max(240,[Math]::Floor($wh*0.88))
    $minWidth=[Math]::Min($BaseMinWidth,[Math]::Max(420,[Math]::Floor($maxInitialWidth*0.82)))
    $minHeight=[Math]::Min($BaseMinHeight,[Math]::Max(280,[Math]::Floor($maxInitialHeight*0.78)))
    $width=[Math]::Min($PreferredWidth,$maxInitialWidth)
    $height=[Math]::Min($PreferredHeight,$maxInitialHeight)
    if($width-lt$minWidth){$width=$minWidth}
    if($height-lt$minHeight){$height=$minHeight}
    return [pscustomobject]@{
        Width=[double]$width;Height=[double]$height;MinWidth=[double]$minWidth;MinHeight=[double]$minHeight
        WorkWidth=$ww;WorkHeight=$wh
    }
}

function Set-VSO7ResponsiveWindowBoundsVSO {
    param(
        [Parameter(Mandatory=$true)]$Window,
        [double]$PreferredWidth=840,
        [double]$PreferredHeight=560,
        [double]$BaseMinWidth=620,
        [double]$BaseMinHeight=420
    )
    $m=Get-VSO7ResponsiveWindowMetricsVSO -PreferredWidth $PreferredWidth -PreferredHeight $PreferredHeight -BaseMinWidth $BaseMinWidth -BaseMinHeight $BaseMinHeight
    $Window.MinWidth=$m.MinWidth;$Window.MinHeight=$m.MinHeight;$Window.Width=$m.Width;$Window.Height=$m.Height
    return $m
}

function Invoke-VSO7GuiCallbackFailureVSO {
    param([Parameter(Mandatory=$true)]$ErrorRecord,[string]$Context='GUI callback',[switch]$ReturnHome)
    $message=try{[string]$ErrorRecord.Exception.Message}catch{[string]$ErrorRecord}
    try{Write-VSO7Log (('GUI callback failure [{0}]: {1}'-f$Context,$message)) 'ERROR'}catch{}
    if($null-ne$script:GuiRuntimeCallbackErrors){try{[void]$script:GuiRuntimeCallbackErrors.Add([pscustomobject]@{Context=$Context;Message=$message;Type=try{$ErrorRecord.Exception.GetType().FullName}catch{''}})}catch{}}
    if([bool]$script:GuiSmokeFailFast){throw $ErrorRecord}
    if(-not[bool]$script:GuiSuppressErrorDialogs){
        try{Show-VSO7GuiErrorVSO $ErrorRecord}catch{try{[void][Windows.MessageBox]::Show($message,'VSO7',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Error)}catch{}}
    }
    if($ReturnHome){try{Show-VSO7GuiHomeVSO}catch{}}
}

function Get-VSO7GuiVisualDescendantsVSO {
    param([Parameter(Mandatory=$true)]$Root)
    $result=New-Object 'Collections.Generic.List[object]'
    $queue=New-Object 'Collections.Generic.Queue[object]'
    $queue.Enqueue($Root)
    while($queue.Count-gt0){
        $node=$queue.Dequeue()
        if($null-eq$node){continue}
        [void]$result.Add($node)
        $count=0
        try{$count=[Windows.Media.VisualTreeHelper]::GetChildrenCount($node)}catch{$count=0}
        for($i=0;$i-lt$count;$i++){try{$queue.Enqueue([Windows.Media.VisualTreeHelper]::GetChild($node,$i))}catch{}}
    }
    return $result.ToArray()
}

function Write-VSO7GuiPerformanceEventVSO {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [string]$NavigationTarget='',
        [Nullable[bool]]$CacheHit=$null,
        [Nullable[bool]]$BackgroundLoad=$null,
        [string]$Detail=''
    )
    if($null-eq$script:GuiPerformanceEvents){$script:GuiPerformanceEvents=New-Object 'Collections.Generic.List[object]'}
    $mono=if($null-ne$script:LifecycleStopwatch){[int64]$script:LifecycleStopwatch.ElapsedMilliseconds}else{[int64]0}
    [void]$script:GuiPerformanceEvents.Add([pscustomobject]@{
        Name=$Name;NavigationTarget=$NavigationTarget;MonoMs=$mono;CacheHit=$CacheHit;BackgroundLoad=$BackgroundLoad;Detail=$Detail
    })
}

function Export-VSO7GuiPerformanceTraceVSO {
    if([string]::IsNullOrWhiteSpace([string]$VSOProbeArtifactRoot)){return}
    try{
        $path=Join-Path ([IO.Path]::GetFullPath([string]$VSOProbeArtifactRoot)) ('VSO7_R80_GUI_PERFORMANCE_TRACE_'+[string]$VSOProbeOwnerToken+'.json')
        $events=if($null-eq$script:GuiPerformanceEvents){@()}elseif($script:GuiPerformanceEvents-is[Collections.Generic.List[object]]){$script:GuiPerformanceEvents.ToArray()}else{@($script:GuiPerformanceEvents)}
        $startup=@($events|Where-Object{[string]$_.Name-like'STARTUP_*'-or[string]$_.Name-in@('PROCESS_ENTRY','MUTEX','WINDOW_HWND_CREATED','WINDOW_LOADED','WINDOW_VISIBLE','WINDOW_TASKBAR_READY','WINDOW_CONTENT_RENDERED','WELCOME_VISIBLE','WELCOME_INTERACTIVE','WINDOW_INTERACTIVE')})
        $stageRows=New-Object 'Collections.Generic.List[object]'
        foreach($e in @($startup|Where-Object{[string]$_.Name-like'STARTUP_*'})){
            $duration=$null;if([string]$e.Detail-match'DurationMs=(?<D>[0-9]+)'){$duration=[int64]$matches.D}
            if($null-ne$duration){[void]$stageRows.Add([pscustomobject]@{Stage=[string]$e.Name;DurationMs=$duration})}
        }
        $top5=@($stageRows|Sort-Object DurationMs -Descending|Select-Object -First 5)
        $navSummary=New-Object 'Collections.Generic.List[object]'
        foreach($target in @($events|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_.NavigationTarget)}|Select-Object -ExpandProperty NavigationTarget -Unique)){
            $n=@($events|Where-Object{[string]$_.NavigationTarget-ceq[string]$target}|Sort-Object MonoMs)
            $begin=@($n|Where-Object{$_.Name-eq'NAVIGATION_BEGIN'}|Select-Object -First 1)
            $shell=@($n|Where-Object{$_.Name-in@('PAGE_SHELL_CREATED','SHELL_VISIBLE','FIRST_ROWS_VISIBLE')}|Select-Object -First 1)
            $ready=@($n|Where-Object{$_.Name-in@('VIEW_MODEL_READY','PAGE_INTERACTIVE')}|Select-Object -Last 1)
            $cache=@($n|Where-Object{$null-ne$_.CacheHit}|Select-Object -Last 1)
            $bg=@($n|Where-Object{$null-ne$_.BackgroundLoad}|Select-Object -Last 1)
            $base=if($begin.Count){[int64]$begin[0].MonoMs}elseif($n.Count){[int64]$n[0].MonoMs}else{0}
            [void]$navSummary.Add([pscustomobject]@{
                NavigationTarget=[string]$target
                ShellVisibleMs=if($shell.Count){[math]::Max(0,[int64]$shell[0].MonoMs-$base)}else{$null}
                DataReadyMs=if($ready.Count){[math]::Max(0,[int64]$ready[0].MonoMs-$base)}else{$null}
                InteractiveMs=if($ready.Count){[math]::Max(0,[int64]$ready[0].MonoMs-$base)}elseif($shell.Count){[math]::Max(0,[int64]$shell[0].MonoMs-$base)}else{$null}
                CacheHit=if($cache.Count){$cache[0].CacheHit}else{$null}
                BackgroundLoad=if($bg.Count){$bg[0].BackgroundLoad}else{$null}
            })
        }
        $out=[pscustomobject]@{Release='RC R80';Events=$events;Startup=$startup;StartupStages=$stageRows.ToArray();StartupTop5=$top5;Navigation=$navSummary.ToArray()}
        [IO.File]::WriteAllText($path,($out|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
    }catch{try{Write-VSO7Log ('GUI performance trace export failed: '+$_.Exception.Message+' | '+[string]$_.ScriptStackTrace) 'WARN'}catch{}}
}

function Get-VSO7GuiRiskPaletteR52VSO {
