    }
}

function Initialize-VSO7GuiReadOnlyResourceCacheR78VSO {
    if($null-eq$script:GuiFeatureCatalogCacheR78){
        $features=@(Get-VSO7FeatureCatalogVSO);if($features.Count-ne183){throw ('GUI feature cache expected 183 catalog rows; got '+$features.Count)};$script:GuiFeatureCatalogCacheR78=$features
    }
    if($null-eq$script:GuiNativeDefinitionsCacheR78){
        $native=Get-VSO7NativeDataVSO;if($null-eq$native-or@($native.Features).Count-ne183){throw 'GUI native cache could not load the frozen 183-feature native catalog.'};$script:GuiNativeDefinitionsCacheR78=$native
    }
    return $true
}

function Get-VSO7GuiFeatureCatalogR78VSO {
    [void](Initialize-VSO7GuiReadOnlyResourceCacheR78VSO)
    return @($script:GuiFeatureCatalogCacheR78)
}

function Get-VSO7GuiFeatureReversibilityMapR52VSO {
    if($null-ne$script:GuiFeatureReversibilityCache){return $script:GuiFeatureReversibilityCache}
    $map=@{}
    try{
        $native=if($null-ne$script:GuiNativeDefinitionsCacheR78){$script:GuiNativeDefinitionsCacheR78}else{Get-VSO7NativeDataVSO}
        $journalModes=@('Registry','PowerSetting','NetAdapterRss','NetAdapterAdvanced','NetOffloadGlobal','NetTcpSetting','NetTcpCimSetting','FsutilTrim','ScheduledTaskState','NetAdapterPower')
        $journaledSpecial=@('V7GP001','V7GP002','V7GP003','V7GP004','V7OF001','V7OF002')
        foreach($f in @($native.Features)){
            $mode=[string]$f.Mode;$id=[string]$f.FeatureId
            # GUI reversibility reflects the actual journal/rollback contract, not the legacy Undo recipe field.
            # Non-reversible AppX/Edge removals and restore-point creation remain explicitly false.
            $map[$id]=($journalModes-contains$mode-or($mode-ceq'Special'-and$journaledSpecial-contains$id))
        }
    }catch{}
    $script:GuiFeatureReversibilityCache=$map
    return $map
}

function Set-VSO7GuiFeatureDetailR52VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)]$Row,[switch]$CheckApplicability)
    if($CheckApplicability-and-not[bool]$Row.ApplicabilityChecked){
        try{
            $app=Get-VSO7FeatureApplicabilityVSO -Feature $Row.Raw
            $Row.Applicable=[bool]$app.Applicable;$Row.AlreadySatisfied=[bool]$app.AlreadySatisfied;$Row.Status=[string]$app.Status
            $Row.Reason=if($script:Language-eq'es'){[string]$app.ReasonEs}else{[string]$app.ReasonEn};$Row.ApplicabilityChecked=$true
        }catch{$Row.Status=Get-VSO7GuiStringVSO 'Error';$Row.Reason=[string]$_.Exception.Message;$Row.ApplicabilityChecked=$true}
    }
    $req=if([string]::IsNullOrWhiteSpace([string]$Row.Requires)){Get-VSO7GuiStringVSO 'NoRequirements'}else{[string]$Row.Requires}
    $meta=New-Object 'Collections.Generic.List[string]';[void]$meta.Add([string]$Row.RiskText)
    if([bool]$Row.Reversible){[void]$meta.Add((Get-VSO7GuiStringVSO 'ReversibleBadge'))}
    if([string]$Row.Restart-ine'None'){[void]$meta.Add((Get-VSO7GuiStringVSO 'RestartRequired'))}
    $why=[string]$Row.Reason
    if(-not[string]::IsNullOrWhiteSpace([string]$Row.RecommendedObjective)){
        $why=(Get-VSO7GuiStringVSO 'RecommendedFor' -Args @([string]$Row.RecommendedObjective))+'. '+[string]$Row.Description
    }
    $Context.DetailTitle.Text=[string]$Row.Name
    $Context.DetailMeta.Text=[string]::Join('  ·  ',$meta.ToArray())
    $Context.DetailAvailability.Text=if([string]::IsNullOrWhiteSpace([string]$Row.Status)){Get-VSO7GuiStringVSO 'AvailabilityNotChecked'}else{[string]$Row.Status}
    $Context.DetailWhy.Text=$why
    $Context.DetailDescription.Text=[string]$Row.Description
    $Context.DetailEvidence.Text=([string]$Row.Evidence+' · '+[string]$Row.Maturity)
    $Context.DetailRequirements.Text=$req
}

function Update-VSO7GuiFeatureSelectorVSO {
    param([Parameter(Mandatory=$true)]$Context)
    $q=([string]$Context.Search.Text).Trim();$riskIndex=[int]$Context.Risk.SelectedIndex;$categoryIndex=[int]$Context.Category.SelectedIndex;$cat=[string]$Context.Category.SelectedItem
    foreach($row in @($Context.Rows)){
        $visible=($q-eq''-or$row.Name.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0-or$row.Description.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0)
        if($riskIndex-gt0){$visible=($visible-and$row.Risk-eq$riskIndex)}
        if($categoryIndex-gt0){$visible=($visible-and$row.Category-eq$cat)}
        if($null-ne$row.Visual){$row.Visual.Visibility=if($visible){[Windows.Visibility]::Visible}else{[Windows.Visibility]::Collapsed}}
    }
    foreach($entry in @($Context.CategoryEntries)){
        $any=@($entry.Rows|Where-Object{$null-ne$_.Visual-and$_.Visual.Visibility-eq[Windows.Visibility]::Visible}).Count-gt0
        $entry.Panel.Visibility=if($any){[Windows.Visibility]::Visible}else{[Windows.Visibility]::Collapsed}
    }
    $Context.Count.Text=Get-VSO7GuiStringVSO 'SelectedCount' -Args @(@($Context.Rows|Where-Object{$_.IsSelected}).Count)
}

function Sync-VSO7GuiFeatureSelectionControlsR52VSO {
    param([Parameter(Mandatory=$true)]$Context)
    foreach($row in @($Context.Rows)){if($null-ne$row.CheckBox){$row.CheckBox.IsChecked=[bool]$row.IsSelected}}
    Update-VSO7GuiFeatureSelectorVSO -Context $Context
}

function Get-VSO7GuiInstalledAppCacheR52VSO { return $script:GuiAppInstalledCache }

function Stop-VSO7GuiAppDetectionR52VSO {
    param([switch]$DisposeWorker,[int]$StopTimeoutMs=1500)
    $c=$script:GuiAppDetectionContext
    if($null-eq$c){return}
    try{if($null-ne$c.Timer){$c.Timer.Stop()}}catch{}
    if($DisposeWorker-and$null-ne$c.PowerShell){
        $safeToDispose=$true
        try{
            if($null-ne$c.Async-and-not$c.Async.IsCompleted){
                $safeToDispose=$false
                $stopAsync=$c.PowerShell.BeginStop($null,$null)
                if($null-ne$stopAsync-and$stopAsync.AsyncWaitHandle.WaitOne([Math]::Max(1,$StopTimeoutMs))){try{$c.PowerShell.EndStop($stopAsync)}catch{};$safeToDispose=$true}
                else{try{Write-VSO7Log ('Applications detection worker did not stop within '+$StopTimeoutMs+' ms; synchronous Dispose was skipped during GUI shutdown.') 'WARN'}catch{}}
            }
        }catch{try{Write-VSO7Log ('Applications detection cancellation failed: '+$_.Exception.Message) 'WARN'}catch{};$safeToDispose=$false}
        if($safeToDispose){try{$c.PowerShell.Dispose()}catch{}}
    }
    $script:GuiAppDetectionContext=$null
}


function Resolve-VSO7GuiAppDetectionWorkerResultR76VSO {
    param([object[]]$Result=@(),[object[]]$StreamErrors=@())
    if(@($StreamErrors).Count-gt0){
        $first=$StreamErrors[0];$message=try{[string]$first.Exception.Message}catch{[string]$first}
        throw ('Applications installed-state worker emitted an error record: '+$message)
    }
    $rows=@($Result)
    if($rows.Count-ne1-or$null-eq$rows[0]-or-not[bool]$rows[0].Ok){
        $message=if($rows.Count-eq1-and$null-ne$rows[0]){[string]$rows[0].Error}else{'Applications installed-state worker returned no valid result.'}
        throw $message
    }
    if($null-eq$rows[0].Map){throw 'Applications installed-state worker returned no installed-state map.'}
    return $rows[0].Map
}

function Apply-VSO7GuiInstalledAppResultR52VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)]$InstalledMap,[bool]$CacheHit=$false)
    if([string]$script:GuiCurrentPageToken-cne[string]$Context.PageToken){return}
    foreach($row in @($Context.Rows)){
        $installed=$false
        foreach($id in @(Get-VSO7AppIdsVSO -App $row.Raw)){if($InstalledMap.ContainsKey([string]$id)-and[bool]$InstalledMap[[string]$id]){$installed=$true;break}}
        $row.Installed=[bool]$installed;$row.InstalledText=if($installed){Get-VSO7GuiStringVSO 'Installed'}else{Get-VSO7GuiStringVSO 'NotInstalled'}
    }
    Update-VSO7GuiAppsSelectorVSO -Context $Context
    $Context.Loading.Text=Get-VSO7GuiStringVSO $(if($CacheHit){'AppCacheReady'}else{'ApplicationsReady'});$Context.LoadingBar.Visibility=[Windows.Visibility]::Collapsed
}

function Start-VSO7GuiAppInstalledDetectionR52VSO {
    param([Parameter(Mandatory=$true)]$Context,[switch]$ForceRefresh)
    if(-not$ForceRefresh-and$null-ne$script:GuiAppInstalledCache){
        Write-VSO7GuiPerformanceEventVSO -Name 'INSTALLED_ENUMERATION_END' -NavigationTarget 'Applications' -CacheHit $true -BackgroundLoad $false -Detail 'session-cache'
        Apply-VSO7GuiInstalledAppResultR52VSO -Context $Context -InstalledMap $script:GuiAppInstalledCache -CacheHit $true
        Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_MODEL_READY' -NavigationTarget 'Applications' -CacheHit $true -BackgroundLoad $false
        Write-VSO7GuiPerformanceEventVSO -Name 'PAGE_INTERACTIVE' -NavigationTarget 'Applications' -CacheHit $true -BackgroundLoad $false
        return
    }
    $Context.Loading.Text=Get-VSO7GuiStringVSO 'DetectingInstalledApps';$Context.LoadingBar.Visibility=[Windows.Visibility]::Visible;$Context.LoadingBar.IsIndeterminate=$true
    # One read-only enumeration may be shared by multiple Applications page instances. Back/navigation
    # only replaces the consumer context; it never touches the old page after its token becomes stale.
    $existing=$script:GuiAppDetectionContext
    if($null-ne$existing-and$null-ne$existing.Async-and-not$existing.Async.IsCompleted){
        $existing.PageContext=$Context;$existing.PageToken=[string]$Context.PageToken
        Write-VSO7GuiPerformanceEventVSO -Name 'INSTALLED_ENUMERATION_BEGIN' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true -Detail 'reuse-inflight'
        return
    }
    if($null-ne$existing){Stop-VSO7GuiAppDetectionR52VSO -DisposeWorker}
    if($ForceRefresh){$script:GuiAppInstalledCache=$null;$script:GuiAppInstalledCacheTimestamp=$null}
    $ids=@($Context.Rows|ForEach-Object{@(Get-VSO7AppIdsVSO -App $_.Raw)}|Select-Object -Unique)
    Write-VSO7GuiPerformanceEventVSO -Name 'INSTALLED_ENUMERATION_BEGIN' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true -Detail ('Ids='+$ids.Count)
    $worker=[PowerShell]::Create()
    $workerScript=@'
param([object[]]$Ids)
$map=@{}
foreach($id in @($Ids)){$map[[string]$id]=$false}
try{
    Import-Module Appx -ErrorAction Stop
    $names=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach($pkg in @(Get-AppxPackage -ErrorAction Stop)){if($null-ne$pkg-and-not[string]::IsNullOrWhiteSpace([string]$pkg.Name)){[void]$names.Add([string]$pkg.Name)}}
    foreach($pkg in @(Get-AppxPackage -AllUsers -ErrorAction Stop)){if($null-ne$pkg-and-not[string]::IsNullOrWhiteSpace([string]$pkg.Name)){[void]$names.Add([string]$pkg.Name)}}
    foreach($id in @($Ids)){if($names.Contains([string]$id)){$map[[string]$id]=$true}}
    [pscustomobject]@{Ok=$true;Map=$map;Error=''}
}catch{[pscustomobject]@{Ok=$false;Map=$map;Error=[string]$_.Exception.Message}}
'@
    [void]$worker.AddScript($workerScript);[void]$worker.AddArgument($ids)
    $appJobId=[guid]::NewGuid().ToString('N')
    try{$async=$worker.BeginInvoke()}catch{
        $failed=[pscustomobject]@{Context='Applications.BackgroundDetection';JobId=$appJobId;UiContext=$Context}
        try{Register-VSO7GuiBackgroundFailureR76VSO -State $failed -ErrorRecord $_ -Phase 'Start'}catch{}
        try{$worker.Dispose()}catch{};$Context.Loading.Text=Get-VSO7GuiStringVSO 'AppDetectionFailed';$Context.LoadingBar.Visibility=[Windows.Visibility]::Collapsed
        Write-VSO7GuiPerformanceEventVSO -Name 'INSTALLED_ENUMERATION_END' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true -Detail 'start-failed';return
    }
    $timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds(100)
    $job=[pscustomobject]@{JobId=$appJobId;PowerShell=$worker;Async=$async;Timer=$timer;PageToken=[string]$Context.PageToken;PageContext=$Context;StartedMs=if($null-ne$script:LifecycleStopwatch){[int64]$script:LifecycleStopwatch.ElapsedMilliseconds}else{0}}
    $script:GuiAppDetectionContext=$job
    $timer.Add_Tick([System.EventHandler]{param($sender,$eventArgs)
        $job=$null
        try{
            $job=$script:GuiAppDetectionContext
            if($null-eq$job-or$job.Timer-ne$sender){$sender.Stop();return}
            if(-not$job.Async.IsCompleted){return}
            $sender.Stop()
            $result=@($job.PowerShell.EndInvoke($job.Async));$streamErrors=@($job.PowerShell.Streams.Error)
            $map=Resolve-VSO7GuiAppDetectionWorkerResultR76VSO -Result $result -StreamErrors $streamErrors
            $cache=@{};foreach($k in @($map.Keys)){$cache[[string]$k]=[bool]$map[$k]}
            $script:GuiAppInstalledCache=$cache;$script:GuiAppInstalledCacheTimestamp=Get-Date
            $elapsed=if($null-ne$script:LifecycleStopwatch){[math]::Max(0,[int64]$script:LifecycleStopwatch.ElapsedMilliseconds-[int64]$job.StartedMs)}else{-1}
            Write-VSO7GuiPerformanceEventVSO -Name 'INSTALLED_ENUMERATION_END' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true -Detail ('Ids='+$cache.Count+';DurationMs='+$elapsed)
            if([string]$script:GuiCurrentPageToken-ceq[string]$job.PageToken){
                Apply-VSO7GuiInstalledAppResultR52VSO -Context $job.PageContext -InstalledMap $cache
                Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_MODEL_READY' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true
                Write-VSO7GuiPerformanceEventVSO -Name 'PAGE_INTERACTIVE' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true
            }
        }catch{
            if($null-ne$job){
                $failed=[pscustomobject]@{Context='Applications.BackgroundDetection';JobId=[string]$job.JobId;UiContext=$job.PageContext}
                try{Register-VSO7GuiBackgroundFailureR76VSO -State $failed -ErrorRecord $_ -Phase 'Worker'}catch{}
                if([string]$script:GuiCurrentPageToken-ceq[string]$job.PageToken){try{$job.PageContext.Loading.Text=Get-VSO7GuiStringVSO 'AppDetectionFailed';$job.PageContext.LoadingBar.Visibility=[Windows.Visibility]::Collapsed}catch{}}
            }
            try{Write-VSO7GuiPerformanceEventVSO -Name 'INSTALLED_ENUMERATION_END' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $true -Detail 'failed'}catch{}
        }finally{
            if($null-ne$job-and$job.Async.IsCompleted){try{$job.PowerShell.Dispose()}catch{};if($script:GuiAppDetectionContext-eq$job){$script:GuiAppDetectionContext=$null}}
        }
    })
    $timer.Start()
}



function Update-VSO7GuiAppsSelectorVSO {
    param([Parameter(Mandatory=$true)]$Context)
    $q=([string]$Context.Search.Text).Trim()
    $only=[bool]$Context.InstalledOnly.IsChecked
    $recIndex=0
    if($null-ne$Context.AppRecommendationFilter){$recIndex=[int]$Context.AppRecommendationFilter.SelectedIndex}
    foreach($row in @($Context.Rows)){
        $matchesText=([string]::IsNullOrWhiteSpace($q)-or[string]$row.Name.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0-or[string]$row.Description.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0-or[string]$row.AppIdText.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0)
        $matchesInstalled=(-not$only-or$row.Installed-eq$true)
        $matchesRecommendation=($recIndex-eq0-or[int]$row.RecommendationGroupIndex-eq$recIndex)
        $row.Visibility=if($matchesText-and$matchesInstalled-and$matchesRecommendation){'Visible'}else{'Collapsed'}
        $row.Status=[string]$row.InstalledText
    }
    Refresh-VSO7GuiPrimaryListR53VSO -Context $Context
}


function Update-VSO7GuiProfilePreviewVSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)]$Profile)
    $Context.Rows.Clear()
    $catalog=@(Get-VSO7FeatureCatalogVSO);$rev=Get-VSO7GuiFeatureReversibilityMapR52VSO
    foreach($id in @($Profile.Features)){
        $f=@($catalog|Where-Object{[string]$_.FeatureId-ceq[string]$id}|Select-Object -First 1)
        if($f.Count-ne1){continue};$f=$f[0]
        $a=Get-VSO7FeatureApplicabilityVSO -Feature $f;$copy=Get-VSO7GuiHumanFeatureCopyR52VSO -Feature $f
        $status=if([bool]$a.AlreadySatisfied){$(if($script:Language-eq'es'){'Ya está configurado'}else{'Already configured'})}elseif([bool]$a.Applicable){$(if($script:Language-eq'es'){'Disponible en este PC'}else{'Available on this PC'})}else{$(if($script:Language-eq'es'){'No disponible en este PC'}else{'Not available on this PC'})}
        $row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $f -Id ([string]$f.FeatureId) -Name $(if($script:Language-eq'es'){[string]$f.NameEs}else{[string]$f.NameEn}) -Description ([string]$copy.Summary) -Category $(if($script:Language-eq'es'){[string]$f.CategoryEs}else{[string]$f.CategoryEn}) -Risk ([int]$f.Risk) -Restart ([string]$f.RebootRequirement) -Reversible ([bool]$rev[[string]$f.FeatureId]) -Selected $true -CanSelect $false -Status $status -Why ([string]$copy.Why) -Technical ('FeatureId: '+[string]$f.FeatureId+' · Applicability: '+[string]$a.Status)
        [void]$Context.Rows.Add($row)
    }
    foreach($id in @($Profile.Apps)){
        $app=@(Get-VSO7AppCatalogVSO|Where-Object{[string]$_.Id-ceq[string]$id}|Select-Object -First 1);$name=$id;$desc=''
        if($app.Count){$name=[string]$app[0].Name;$desc=if($script:Language-eq'es' -and $null-ne$app[0].PSObject.Properties['DescriptionEs']-and-not[string]::IsNullOrWhiteSpace([string]$app[0].DescriptionEs)){[string]$app[0].DescriptionEs}else{[string]$app[0].DescriptionEn}}
        $row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $(if($app.Count){$app[0]}else{$id}) -Id ([string]$id) -Name $name -Description $desc -Category $(if($script:Language-eq'es'){'Aplicaciones'}else{'Applications'}) -Risk 1 -Restart 'None' -Reversible $false -Selected $true -CanSelect $false -Status $(if($script:Language-eq'es'){'Se eliminará al aplicar el perfil'}else{'Will be removed when the profile is applied'}) -Why $(if($script:Language-eq'es'){'Esta aplicación forma parte del perfil importado.'}else{'This app is part of the imported profile.'}) -Technical ('AppId: '+[string]$id)
        $row.RiskVisibility='Collapsed';$row.RestartVisibility='Collapsed'
        [void]$Context.Rows.Add($row)
    }
    Refresh-VSO7GuiPrimaryListR53VSO -Context $Context
    $Context.Summary.Text=Get-VSO7GuiStringVSO 'ProfileLoaded' -Args @(@($Profile.Features).Count,@($Profile.Apps).Count,[string]$Profile.Preferences.Language)
}

function Test-VSO7GuiEventDelegateRegistrationVSO {
    Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase -ErrorAction Stop
    $rows=New-Object 'Collections.Generic.List[object]'
    $tests=@(
        @{Owner=(New-Object Windows.Controls.Button);Event='Click';Expected='System.Windows.RoutedEventHandler';Delegate=[Windows.RoutedEventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Controls.TextBox);Event='TextChanged';Expected='System.Windows.Controls.TextChangedEventHandler';Delegate=[Windows.Controls.TextChangedEventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Controls.ComboBox);Event='SelectionChanged';Expected='System.Windows.Controls.SelectionChangedEventHandler';Delegate=[Windows.Controls.SelectionChangedEventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Controls.DataGrid);Event='CurrentCellChanged';Expected='System.EventHandler`1[System.EventArgs]';Delegate=[System.EventHandler[System.EventArgs]]{param($s,$e)}},
        @{Owner=(New-Object Windows.Controls.TextBox);Event='KeyDown';Expected='System.Windows.Input.KeyEventHandler';Delegate=[Windows.Input.KeyEventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Window);Event='ContentRendered';Expected='System.EventHandler';Delegate=[System.EventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Window);Event='Closing';Expected='System.ComponentModel.CancelEventHandler';Delegate=[ComponentModel.CancelEventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Window);Event='Closed';Expected='System.EventHandler';Delegate=[System.EventHandler]{param($s,$e)}},
        @{Owner=(New-Object Windows.Threading.DispatcherTimer);Event='Tick';Expected='System.EventHandler';Delegate=[System.EventHandler]{param($s,$e)}}
    )
    foreach($t in $tests){$ok=$false;$delegateError='';try{$add=$t.Owner.GetType().GetMethod(('add_'+$t.Event));$remove=$t.Owner.GetType().GetMethod(('remove_'+$t.Event));if($null-eq$add-or$null-eq$remove){throw ('Missing CLR event accessor '+$t.Event)};[void]$add.Invoke($t.Owner,@($t.Delegate));[void]$t.Delegate.DynamicInvoke(@($t.Owner,$null));[void]$remove.Invoke($t.Owner,@($t.Delegate));$ok=$true}catch{$delegateError=$_.Exception.Message};[void]$rows.Add([pscustomobject]@{EventOwner=$t.Owner.GetType().FullName;EventName=$t.Event;ExpectedDelegate=$t.Expected;RegisteredDelegate=$t.Delegate.GetType().FullName;RuntimeRegistration=$ok;InvocationSmoke=$ok;Error=$delegateError})}
    return $rows.ToArray()
}

function Wait-VSO7GuiContextBuildR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[int]$TimeoutMs=15000)
    if($null-eq$Context.InitTimer-and$null-eq$Context.BuildTimer){return $true}
    $frame=New-Object Windows.Threading.DispatcherFrame
    $timer=New-Object Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromMilliseconds(25)
    $state=[pscustomobject]@{Context=$Context;Frame=$frame;Deadline=[DateTime]::UtcNow.AddMilliseconds($TimeoutMs);Success=$false}
    $timer.Tag=$state
    $handler=[System.EventHandler]{param($sender,$e);$st=$sender.Tag;if($null-eq$st){$sender.Stop();return};if($null-eq$st.Context.InitTimer-and$null-eq$st.Context.BuildTimer){$st.Success=$true;$st.Frame.Continue=$false;$sender.Stop();return};if([DateTime]::UtcNow-ge$st.Deadline){$st.Frame.Continue=$false;$sender.Stop()}}
    $timer.Add_Tick($handler);$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)
    try{$timer.Remove_Tick($handler)}catch{}
    if(-not$state.Success){throw ('Timed out waiting for categorized GUI build: '+[string]$Context.NavigationTarget)}
    return $true
}

function Wait-VSO7GuiButtonEnabledR53VSO {
    param([Parameter(Mandatory=$true)]$Button,[int]$TimeoutMs=60000,[string]$Name='button')
    if([bool]$Button.IsEnabled){return $true}
    $frame=New-Object Windows.Threading.DispatcherFrame
    $timer=New-Object Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromMilliseconds(40)
    $state=[pscustomobject]@{Button=$Button;Frame=$frame;Deadline=[DateTime]::UtcNow.AddMilliseconds($TimeoutMs);Success=$false}
    $timer.Tag=$state
    $handler=[System.EventHandler]{param($sender,$e);$st=$sender.Tag;if($null-eq$st){$sender.Stop();return};if([bool]$st.Button.IsEnabled){$st.Success=$true;$st.Frame.Continue=$false;$sender.Stop();return};if([DateTime]::UtcNow-ge$st.Deadline){$st.Frame.Continue=$false;$sender.Stop()}}
    $timer.Add_Tick($handler);$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)
    try{$timer.Remove_Tick($handler)}catch{}
    if(-not$state.Success){throw ('Timed out waiting for GUI '+$Name)}
    return $true
}

function Get-VSO7GuiCategorizedContextFromPageR53VSO {
    param([Parameter(Mandatory=$true)]$Root)
    if($null-ne$Root.DataContext-and$null-ne$Root.DataContext.PSObject.Properties['LayoutKind']-and[string]$Root.DataContext.LayoutKind-eq'Categorized'){return $Root.DataContext}
    foreach($x in @(Get-VSO7GuiVisualDescendantsVSO -Root $Root)){
