function Test-VSO7GuiResponsiveLayoutR53VSO {
    param([Parameter(Mandatory=$true)]$MainContext)
    $rows=New-Object 'Collections.Generic.List[object]'
    $oldLanguage=[string]$script:Language;$oldWidth=[double]$MainContext.Window.Width
    try{
        foreach($lang in @('en','es')){
            $script:Language=$lang
            $langPass=$true;$errors=New-Object 'Collections.Generic.List[string]'
            try{
                Show-VSO7GuiFeatureSelectorPageVSO -Mode Windows;$MainContext.Window.UpdateLayout()
                $ctx=$script:GuiFeaturePageContexts['Windows'];if($null-eq$ctx){throw 'Windows layout context missing.'};[void](Wait-VSO7GuiContextBuildR53VSO -Context $ctx)
                $columnResults=New-Object 'Collections.Generic.List[object]'
                $oldLayoutWidth=$ctx.LayoutRoot.Width
                try{
                    foreach($case in @(@{Width=1700;Expected=3},@{Width=1200;Expected=2},@{Width=900;Expected=1})){
                        # R80: force the categorized surface itself to the requested diagnostic width. Window.Width
                        # is host/work-area dependent and can stay clamped on a real desktop, which made the old
                        # matrix report 2 columns for every requested width even though production SizeChanged uses
                        # LayoutRoot.ActualWidth. The canonical decision helper is shared with production.
                        $ctx.LayoutRoot.Width=[double]$case.Width;$MainContext.Window.UpdateLayout();$ctx.LayoutRoot.UpdateLayout();Update-VSO7GuiCategorizedLayoutR53VSO -Context $ctx -AvailableWidth ([double]$case.Width);$ctx.LayoutRoot.UpdateLayout();$MainContext.Window.UpdateLayout()
                        $actual=[int]$ctx.ColumnCount;$cards=@($ctx.CategoryEntries);$actualLayoutWidth=[math]::Round([double]$ctx.LayoutRoot.ActualWidth,1)
                        # Do not compare DesiredSize with ActualHeight: DesiredSize can be recomputed for a new wrap
                        # width before the arranged height is refreshed, producing all-card false positives. Validate
                        # the arranged child box and reject explicit card height constraints instead.
                        $clipped=@($cards|Where-Object{
                            $panel=$_.Panel
                            if($null-eq$panel-or$null-eq$panel.Child-or[double]$panel.ActualHeight-le0-or[double]$panel.Child.ActualHeight-le0){$true}
                            elseif(-not[double]::IsNaN([double]$panel.Height)-or-not[double]::IsPositiveInfinity([double]$panel.MaxHeight)){$true}
                            else{
                                $inner=[double]$panel.ActualHeight-[double]$panel.Padding.Top-[double]$panel.Padding.Bottom-[double]$panel.BorderThickness.Top-[double]$panel.BorderThickness.Bottom
                                ([double]$panel.Child.ActualHeight-gt($inner+2.0))
                            }
                        }).Count
                        [void]$columnResults.Add([pscustomobject]@{RequestedWidth=$case.Width;ActualLayoutWidth=$actualLayoutWidth;ExpectedColumns=$case.Expected;ActualColumns=$actual;CategoryCards=$cards.Count;ClippedCards=$clipped;Pass=($actual-eq[int]$case.Expected-and$clipped-eq0)})
                        if($actual-ne[int]$case.Expected-or$clipped-ne0){$langPass=$false}
                    }
                }finally{$ctx.LayoutRoot.Width=$oldLayoutWidth;$MainContext.Window.UpdateLayout();Update-VSO7GuiCategorizedLayoutR53VSO -Context $ctx}
                # Validate the page-owned scroll contract through the context itself. Traversing the complete
                # WPF visual tree counts ScrollViewers injected by ComboBox/ListView templates and creates false
                # nested-scroll failures unrelated to the page architecture.
                $mainScrollOk=($null-ne$ctx.MainScroll-and$ctx.MainScroll-is[Windows.Controls.ScrollViewer])
                $windowsScrolls=if($mainScrollOk){1}else{0}
                $windowsListViews=0
                $nestedCategoryScrolls=0
                foreach($entry in @($ctx.CategoryEntries)){
                    $ownedVisuals=@(Get-VSO7GuiVisualDescendantsVSO -Root $entry.Panel)
                    $windowsListViews+=@($ownedVisuals|Where-Object{$_-is[Windows.Controls.ListView]}).Count
                    $nestedCategoryScrolls+=@($ownedVisuals|Where-Object{$_-is[Windows.Controls.ScrollViewer]}).Count
                }
                if($windowsListViews-ne0-or$windowsScrolls-ne1-or$nestedCategoryScrolls-ne0-or-not$mainScrollOk){$langPass=$false;[void]$errors.Add(('Windows layout expected one context-owned MainScroll and no per-card ListView/ScrollViewer; MainScroll='+$mainScrollOk+'; Lists='+$windowsListViews+'; NestedScrolls='+$nestedCategoryScrolls))}

                Show-VSO7GuiAppsPageVSO;$MainContext.Window.UpdateLayout();$apps=$script:GuiApplicationsPageContext
                if($null-eq$apps){throw 'Applications layout context missing.'}
                if($null-ne$apps.InitTimer){try{$apps.InitTimer.Stop()}catch{};$apps.InitTimer=$null}
                if($apps.Rows.Count-eq0){Initialize-VSO7GuiAppsCatalogR52VSO -Context $apps;$MainContext.Window.UpdateLayout()}
                $appLists=if($apps.PrimaryList-is[Windows.Controls.ListView]){1}else{0}
                $appOuterScrolls=@($apps.LayoutRoot.Children|Where-Object{$_-is[Windows.Controls.ScrollViewer]}).Count
                $appsPass=($appLists-eq1-and$appOuterScrolls-eq0-and$apps.CategoryEntries.Count-eq0-and$apps.Rows.Count-eq140-and$null-ne$apps.Search-and$null-ne$apps.InstalledOnly-and$null-ne$apps.RecommendedButton)
                if(-not$appsPass){$langPass=$false;[void]$errors.Add(('Applications layout contract failed: Lists='+$appLists+';OwnedScrolls='+$appOuterScrolls+';Grouped='+$apps.CategoryEntries.Count+';Rows='+$apps.Rows.Count))}
                [void]$rows.Add([pscustomobject]@{Language=$lang;WindowsColumns=$columnResults.ToArray();WindowsVerticalScrollViewers=$windowsScrolls;WindowsListViews=$windowsListViews;ApplicationsListViews=$appLists;ApplicationsScrollViewers=$appOuterScrolls;ApplicationsRows=$apps.Rows.Count;ApplicationsGroupedBlocks=$apps.CategoryEntries.Count;Result=$(if($langPass){'PASS'}else{'FAIL'});Errors=$errors.ToArray()})
            }catch{$langPass=$false;[void]$errors.Add([string]$_.Exception.Message);[void]$rows.Add([pscustomobject]@{Language=$lang;WindowsColumns=@();WindowsVerticalScrollViewers=-1;WindowsListViews=-1;ApplicationsListViews=-1;ApplicationsScrollViewers=-1;ApplicationsRows=-1;ApplicationsGroupedBlocks=-1;Result='FAIL';Errors=$errors.ToArray()})}
            try{Show-VSO7GuiHomeVSO;$MainContext.Window.UpdateLayout()}catch{}
        }
    }finally{$script:Language=$oldLanguage;$MainContext.Window.Width=$oldWidth;try{$MainContext.Window.UpdateLayout()}catch{}}
    return $rows.ToArray()
}

function Invoke-VSO7GuiPromptSmokeDeferredVSO {
    $c=$script:GuiPromptSmokeContext
    if($null-eq$c){throw 'R80 prompt smoke context is unavailable.'}
    switch([string]$c.Mode){
        'Enter' {
            if([bool]$c.AsSecureString){$c.Dialog.Tag=$c.SecureInput.SecurePassword.Copy()}else{$c.Dialog.Tag=[string]$c.Input.Text}
            $c.Dialog.DialogResult=$true
        }
        'Back' {$c.Back.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)))}
        'No' {$c.No.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)))}
        'Close' {$c.Dialog.Close()}
        default {if([bool]$c.IsYesNo){$c.Yes.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)))}else{$c.Ok.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)))}}
    }
}

