function Wait-VSO7GuiAppsCatalogR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[int]$TimeoutMs=15000)
    if($Context.Rows.Count-gt0){return $true}
    $frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds(25)
    $state=[pscustomobject]@{Context=$Context;Frame=$frame;Deadline=[DateTime]::UtcNow.AddMilliseconds($TimeoutMs);Success=$false};$timer.Tag=$state
    $handler=[System.EventHandler]{param($sender,$e);$st=$sender.Tag;if($st.Context.Rows.Count-gt0){$st.Success=$true;$st.Frame.Continue=$false;$sender.Stop();return};if([DateTime]::UtcNow-ge$st.Deadline){$st.Frame.Continue=$false;$sender.Stop()}}
    $timer.Add_Tick($handler);$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame);try{$timer.Remove_Tick($handler)}catch{}
    if(-not$state.Success){throw 'Timed out waiting for Applications catalog.'};return $true
}

