    $ctx=[pscustomobject]@{Main=$MainContext;Timer=$timer;Handler=$null;State=0;NextMs=0;DeadlineMs=0;SearchInteracted=$false;BackDuringLoad=$false;InflightReused=$false;CacheHitOpen=$false;Error=''}
    $script:GuiPerformanceSmokeContext=$ctx
