        $x=$script:GuiPerformanceSmokeContext;if($null-eq$x){$sender.Stop();return}
        try{
            $now=if($null-ne$script:LifecycleStopwatch){[int64]$script:LifecycleStopwatch.ElapsedMilliseconds}else{0}
            switch([int]$x.State){
                0 {
                    $x.Main.Start.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)));$x.Main.Window.UpdateLayout()
                    $card=Get-VSO7GuiHomeCardR52VSO -Action 'Apps';if($null-eq$card){throw 'R80 performance smoke cannot find Applications card.'}
