                    [void](Invoke-VSO7GuiSafeInteractionSmokeVSO -Action 'Apps');$x.SearchInteracted=$true;$x.State=1;$x.NextMs=$now+250
                }
                1 {
                    if($now-lt$x.NextMs){return};$script:GuiBackButton.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)));$x.Main.Window.UpdateLayout();$x.BackDuringLoad=$true;$x.State=2;$x.NextMs=$now+150
                }
                2 {
                    if($now-lt$x.NextMs){return};$card=Get-VSO7GuiHomeCardR52VSO -Action 'Apps';if($null-eq$card){throw 'R80 performance smoke cannot reopen Applications.'};$card.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)));$x.Main.Window.UpdateLayout();$x.InflightReused=($null-ne$script:GuiAppDetectionContext);$x.State=3;$x.DeadlineMs=$now+60000
                }
                3 {
                    if($null-eq$script:GuiAppInstalledCache){if($now-gt$x.DeadlineMs){throw 'R80 performance smoke timed out waiting for installed-app cache.'};return}
                    $script:GuiBackButton.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)));$x.Main.Window.UpdateLayout();$x.State=4;$x.NextMs=$now+150
                }
                4 {
                    if($now-lt$x.NextMs){return};$card=Get-VSO7GuiHomeCardR52VSO -Action 'Apps';if($null-eq$card){throw 'R80 performance smoke cannot perform cache-hit reopen.'};$before=[int64]$now;$card.RaiseEvent((New-Object Windows.RoutedEventArgs([Windows.Controls.Button]::ClickEvent)));$x.Main.Window.UpdateLayout();$x.CacheHitOpen=($null-ne$script:GuiAppInstalledCache-and$null-eq$script:GuiAppDetectionContext);Write-VSO7GuiPerformanceEventVSO -Name 'CACHE_HIT_REOPEN_CONFIRMED' -NavigationTarget 'Applications' -CacheHit $x.CacheHitOpen -BackgroundLoad $false -Detail ('ElapsedMs='+[math]::Max(0,([int64]$script:LifecycleStopwatch.ElapsedMilliseconds-$before)));$x.State=5;$x.NextMs=$now+250
                }
                5 {
                    if($now-lt$x.NextMs){return}
                    if(-not$x.SearchInteracted-or-not$x.BackDuringLoad-or-not$x.InflightReused-or-not$x.CacheHitOpen){throw 'R80 Applications responsiveness smoke contract failed.'}
                    Stop-VSO7GuiPerformanceSmokeR52VSO;$x.Main.Window.Close();return
                }
            }
        }catch{$x.Error=[string]$_.Exception.Message;$script:ProcessExitCode=1;try{Write-VSO7Log ('R80 performance smoke failed: '+$x.Error) 'ERROR'}catch{};Stop-VSO7GuiPerformanceSmokeR52VSO;try{$x.Main.Window.Close()}catch{}}
    }
    $ctx.Handler=$handler;$timer.Add_Tick($handler);$timer.Start()
}

