        $rows=@();if($null-ne$st.Rows){$rows=@($st.Rows.ToArray())}
        $payload=[pscustomobject]@{
            Release='RC R80'
            Phase=[string]$st.Phase
            CurrentAction=[string]$st.CurrentAction
            Completed=[bool]$st.Completed
            FatalError=[string]$st.FatalError
            Navigation=$rows
            CallbackErrorCount=$(if($null-ne$script:GuiRuntimeCallbackErrors){[int]$script:GuiRuntimeCallbackErrors.Count}else{0})
            RealWindowsNavigationMatrix=[string]$Result
        }
        [IO.File]::WriteAllText([string]$st.ReportPath,($payload|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
    }catch{}
}

