            try{$script:GuiSmokeFailFast=$false;$script:GuiSuppressErrorDialogs=$true;Show-VSO7GuiPageByActionVSO -Action '__R73_ERROR_BOUNDARY_SMOKE__';$c.Window.UpdateLayout();$boundaryNew=@($script:GuiRuntimeCallbackErrors|Select-Object -Skip $boundaryBefore);$boundaryExpected=@($boundaryNew|Where-Object{[string]$_.Context-ceq'PageRouter.__R73_ERROR_BOUNDARY_SMOKE__'});if($boundaryExpected.Count-ne1){throw 'R80 GUI error-boundary smoke did not record exactly one expected PageRouter failure.'};if($script:GuiHomeView.Visibility-ne[Windows.Visibility]::Visible-or-not$c.Window.IsLoaded){throw 'R80 GUI error-boundary smoke did not preserve MainWindow/Home.'};[void]$script:GuiRuntimeCallbackErrors.Remove($boundaryExpected[0]);$script:GuiErrorBoundarySmokePassed=$true}catch{$overallPass=$false}finally{$script:GuiSmokeFailFast=$oldFailFast;$script:GuiSuppressErrorDialogs=$oldSuppress}
            Write-VSO7GuiNavigationProbeHeartbeatVSO -Phase 'FINAL_REPORT'
            $report=[pscustomobject]@{Release='RC R80';Phase='COMPLETED';CurrentAction='';Navigation=$script:GuiNavigationSmokeResults;DelegateRuntime=$script:GuiEventDelegateRuntimeResults;CallbackErrors=$script:GuiRuntimeCallbackErrors.ToArray();Layout=$script:GuiLayoutSmokeResults;CustomControls=$controlRuntime;Localization=$localization;ErrorBoundary=[bool]$script:GuiErrorBoundarySmokePassed;LogoRendered=(Test-VSO7EmbeddedWelcomeLogoVSO -LogoControl $script:GuiWelcomeLogo -RequireRenderedArea);WelcomeStartHome=$true;RealWindowsNavigationMatrix=$(if($overallPass){'PASS'}else{'FAIL'})}
            [IO.File]::WriteAllText([string]$script:GuiNavigationProbeState.ReportPath,($report|ConvertTo-Json -Depth 14),[Text.UTF8Encoding]::new($false));$navigationCompleted=$true;$script:GuiNavigationProbeState.Completed=$true;$script:GuiNavigationProbeState.Phase='COMPLETED';$script:GuiNavigationProbeState.CurrentAction=''
            if(-not$overallPass){$script:ProcessExitCode=1}
        }catch{
            $navigationFatal=[string]$_.Exception.Message;$script:ProcessExitCode=1
            if($null-ne$script:GuiNavigationProbeState){$script:GuiNavigationProbeState.FatalError=$navigationFatal}
            try{Write-VSO7Log ('R80 navigation matrix aborted before final report: '+$navigationFatal) 'ERROR'}catch{}
            Write-VSO7GuiNavigationProbeHeartbeatVSO -Phase 'ABORTED_BEFORE_FINAL_REPORT' -CurrentAction $(if($null-ne$script:GuiNavigationProbeState){[string]$script:GuiNavigationProbeState.CurrentAction}else{''}) -Result 'INCOMPLETE' -FatalError $navigationFatal
            if($null-ne$script:GuiNavigationProbeState){$script:GuiNavigationProbeState.Completed=$true}
        }finally{
            $script:GuiSmokeFailFast=$oldNavigationFailFast
        }
        try{$c.Window.Close()}catch{}
        return
    }
    $c.Window.Close()
}

function New-VSO7ResponsiveChoiceDialogVSO {
    param(
        [Parameter(Mandatory=$true)][string]$Title,
        [Parameter(Mandatory=$true)][string]$Body,
        [string]$Label='',
        [string]$Value='',
        [Parameter(Mandatory=$true)][string]$PrimaryText,
        [Parameter(Mandatory=$true)][string]$SecondaryText,
        [string]$PrimaryResult='Primary',
        [string]$SecondaryResult='Secondary',
        [switch]$SmokeOnly,
        [switch]$LongTextStress
    )
    Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase -ErrorAction Stop
    if($LongTextStress){$Body=(($Body+' ')*80).Trim()}
    [xml]$dialogXaml=@"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="VSO7" Width="840" Height="560" MinWidth="420" MinHeight="280"
        ResizeMode="CanResize" WindowStartupLocation="CenterScreen"
        Background="#15120F" Foreground="#F4E7D0" ShowActivated="True">
  <Window.Resources>
    <Style x:Key="ChoiceButton" TargetType="Button">
      <Setter Property="Background" Value="#2B221B"/><Setter Property="Foreground" Value="#FFF4E0"/>
      <Setter Property="BorderBrush" Value="#765536"/><Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Cursor" Value="Hand"/><Setter Property="FocusVisualStyle" Value="{x:Null}"/>
      <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button">
        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="4" Padding="{TemplateBinding Padding}">
          <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#493522"/><Setter TargetName="Bd" Property="BorderBrush" Value="#D39A5B"/></Trigger>
          <Trigger Property="IsPressed" Value="True"><Setter TargetName="Bd" Property="Background" Value="#604125"/></Trigger>
          <Trigger Property="IsKeyboardFocused" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFD29B"/><Setter TargetName="Bd" Property="BorderThickness" Value="2"/></Trigger>
          <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Bd" Property="Opacity" Value="0.42"/></Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate></Setter.Value></Setter>
    </Style>
    <Style x:Key="PrimaryChoiceButton" TargetType="Button" BasedOn="{StaticResource ChoiceButton}"><Setter Property="Background" Value="#8A4E22"/><Setter Property="BorderBrush" Value="#D99B5A"/></Style>
  </Window.Resources>
  <Grid Margin="24">
    <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Name="DialogTitle" Grid.Row="0" FontSize="27" FontWeight="Bold" Foreground="#E3A35D" TextWrapping="Wrap" Margin="0,0,0,16"/>
    <ScrollViewer Name="ContentScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" CanContentScroll="False">
      <StackPanel Margin="0,0,12,0">
        <TextBlock Name="DialogBody" FontSize="15" Foreground="#F4E7D0" TextWrapping="Wrap" LineHeight="23"/>
        <Border Name="ValuePanel" Margin="0,20,0,0" Padding="14" Background="#211B16" BorderBrush="#5F4936" BorderThickness="1" CornerRadius="4">
          <StackPanel><TextBlock Name="DialogLabel" FontSize="12" Foreground="#BDA98D" Margin="0,0,0,6"/><TextBlock Name="DialogValue" FontSize="14" Foreground="#FFF4E0" TextWrapping="Wrap"/></StackPanel>
        </Border>
      </StackPanel>
    </ScrollViewer>
    <Grid Name="Actions" Grid.Row="2" Margin="0,18,0,0">
      <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right">
        <Button Name="Secondary" Style="{StaticResource ChoiceButton}" MinWidth="120" Padding="18,10" Margin="5"/>
        <Button Name="Primary" Style="{StaticResource PrimaryChoiceButton}" MinWidth="120" Padding="18,10" Margin="5"/>
      </StackPanel>
    </Grid>
  </Grid>
</Window>
"@
    $reader=New-Object System.Xml.XmlNodeReader $dialogXaml
    $dlg=[Windows.Markup.XamlReader]::Load($reader)
    if($null-eq$dlg){throw 'R80 responsive dialog XAML returned null.'}
    if($null-ne$script:GuiWindow-and$script:GuiWindow.IsVisible){try{$dlg.Owner=$script:GuiWindow;$dlg.ShowInTaskbar=$false;$dlg.WindowStartupLocation=[Windows.WindowStartupLocation]::CenterOwner}catch{}}
    [void](Set-VSO7ResponsiveWindowBoundsVSO -Window $dlg -PreferredWidth 840 -PreferredHeight 560 -BaseMinWidth 620 -BaseMinHeight 420)
    $titleControl=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'DialogTitle'
    $bodyControl=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'DialogBody'
    $labelControl=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'DialogLabel'
    $valueControl=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'DialogValue'
    $valuePanel=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'ValuePanel'
    $primary=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'Primary'
    $secondary=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'Secondary'
    $scroll=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'ContentScroll'
    $actions=Get-VSO7RequiredGuiControlVSO -Window $dlg -Name 'Actions'
    $dlg.Title=Get-VSO7GuiStringVSO 'AppTitle';$titleControl.Text=$Title;$bodyControl.Text=$Body
    $primary.Content=$PrimaryText;$secondary.Content=$SecondaryText
    if([string]::IsNullOrWhiteSpace($Label)-and[string]::IsNullOrWhiteSpace($Value)){$valuePanel.Visibility='Collapsed'}else{$labelControl.Text=$Label;$valueControl.Text=$Value}
    $ctx=[pscustomobject]@{Dialog=$dlg;PrimaryResult=$PrimaryResult;SecondaryResult=$SecondaryResult}
    $primary.DataContext=$ctx;$secondary.DataContext=$ctx
    $primaryHandler=[Windows.RoutedEventHandler]{param($sender,$eventArgs);try{$c=$sender.DataContext;$c.Dialog.Tag=$c.PrimaryResult;$c.Dialog.DialogResult=$true}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'FirstRun.Primary'}}
    $secondaryHandler=[Windows.RoutedEventHandler]{param($sender,$eventArgs);try{$c=$sender.DataContext;$c.Dialog.Tag=$c.SecondaryResult;$c.Dialog.DialogResult=$false}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'FirstRun.Secondary'}}
    $primary.Add_Click($primaryHandler);$secondary.Add_Click($secondaryHandler)
    try{
        if($SmokeOnly){
            $dlg.ShowInTaskbar=$false;$dlg.ShowActivated=$false;$dlg.Opacity=0
            $dlg.Show();$dlg.UpdateLayout()
            $p0=$primary.TransformToAncestor($dlg).Transform((New-Object Windows.Point(0,0)))
            $p1=$secondary.TransformToAncestor($dlg).Transform((New-Object Windows.Point(0,0)))
            $layout=[pscustomobject]@{
                Width=$dlg.ActualWidth;Height=$dlg.ActualHeight;MinWidth=$dlg.MinWidth;MinHeight=$dlg.MinHeight
                PrimaryWidth=$primary.ActualWidth;PrimaryHeight=$primary.ActualHeight;SecondaryWidth=$secondary.ActualWidth;SecondaryHeight=$secondary.ActualHeight
                PrimaryLeft=$p0.X;PrimaryTop=$p0.Y;PrimaryRight=($p0.X+$primary.ActualWidth);PrimaryBottom=($p0.Y+$primary.ActualHeight)
                SecondaryLeft=$p1.X;SecondaryTop=$p1.Y;SecondaryRight=($p1.X+$secondary.ActualWidth);SecondaryBottom=($p1.Y+$secondary.ActualHeight)
                ScrollViewportHeight=$scroll.ViewportHeight;ScrollExtentHeight=$scroll.ExtentHeight
                ActionsHeight=$actions.ActualHeight;ResizeMode=[string]$dlg.ResizeMode
            }
            return $layout
        }
        [void]$dlg.ShowDialog()
        if($null-eq$dlg.Tag){return $SecondaryResult}
        return [string]$dlg.Tag
    }finally{
        try{$primary.Remove_Click($primaryHandler)}catch{};try{$secondary.Remove_Click($secondaryHandler)}catch{}
        try{if($dlg.IsVisible){$dlg.Close()}}catch{}
    }
}

function Test-VSO7FirstRunDialogLayoutVSO {
    param([ValidateSet('en','es')][string]$Language='en',[switch]$LongTextStress)
    $previousLanguage=$script:Language
    try{
        $script:Language=$Language
        $layout=Show-VSO7FirstRunOrganizationDialogVSO -CurrentRoot ([IO.Path]::GetTempPath()) -SmokeOnly -LongTextStress:$LongTextStress
        $buttonsVisible=($layout.PrimaryWidth-gt0-and$layout.PrimaryHeight-gt0-and$layout.SecondaryWidth-gt0-and$layout.SecondaryHeight-gt0)
        $buttonsInside=($layout.PrimaryLeft-ge-1-and$layout.PrimaryTop-ge-1-and$layout.SecondaryLeft-ge-1-and$layout.SecondaryTop-ge-1-and$layout.PrimaryRight-le($layout.Width+1)-and$layout.PrimaryBottom-le($layout.Height+1)-and$layout.SecondaryRight-le($layout.Width+1)-and$layout.SecondaryBottom-le($layout.Height+1))
        $contentRegionValid=($layout.ScrollViewportHeight-gt0-and$layout.ScrollExtentHeight-ge0-and$layout.ActionsHeight-gt0)
        # R80: normal localized text is allowed to need scrolling at small work areas/high DPI.
        # The hard contract is that the fixed action row remains visible and overflow is accessible.
        $scrollBehaviorOk=if($LongTextStress){$layout.ScrollExtentHeight-gt($layout.ScrollViewportHeight+1)}else{$contentRegionValid}
        return [pscustomobject]@{
            Language=$Language;LongTextStress=[bool]$LongTextStress;ButtonsVisible=$buttonsVisible;ButtonsInsideWindow=$buttonsInside
            ContentRegionValid=$contentRegionValid;ScrollBehaviorOk=$scrollBehaviorOk;ResizeMode=$layout.ResizeMode;Width=$layout.Width;Height=$layout.Height;MinWidth=$layout.MinWidth;MinHeight=$layout.MinHeight
            ScrollViewportHeight=$layout.ScrollViewportHeight;ScrollExtentHeight=$layout.ScrollExtentHeight;ActionsHeight=$layout.ActionsHeight
            Pass=($buttonsVisible-and$buttonsInside-and$contentRegionValid-and$scrollBehaviorOk-and$layout.ResizeMode-eq'CanResize')
        }
    }finally{$script:Language=$previousLanguage}
}

function Show-VSO7FirstRunOrganizationDialogVSO {
    param([Parameter(Mandatory=$true)][string]$CurrentRoot,[switch]$SmokeOnly,[switch]$LongTextStress)
    $proposed=Join-Path (Join-Path ([IO.Path]::GetFullPath($CurrentRoot)) 'VSO7') 'VSO7.ps1'
    return New-VSO7ResponsiveChoiceDialogVSO -Title (Get-VSO7GuiStringVSO 'FirstRunTitle') -Body ((Get-VSO7GuiStringVSO 'FirstRunIntro')+"`n`n"+(Get-VSO7GuiStringVSO 'FirstRunOrganizationInfo')+"`n`n"+(Get-VSO7GuiStringVSO 'FirstRunKeepInfo')) -Label (Get-VSO7GuiStringVSO 'FirstRunRecommended') -Value $proposed -PrimaryText (Get-VSO7GuiStringVSO 'FirstRunOrganize') -SecondaryText (Get-VSO7GuiStringVSO 'FirstRunKeepHere') -PrimaryResult 'Organize' -SecondaryResult 'KeepHere' -SmokeOnly:$SmokeOnly -LongTextStress:$LongTextStress
}

