function Test-VSO7EmbeddedWelcomeLogoVSO {
    param([Parameter(Mandatory=$true)]$LogoControl,[switch]$RequireRenderedArea)
    try{
        if($LogoControl.GetType().FullName-cne 'System.Windows.Controls.Viewbox'){return $false}
        if([string]$LogoControl.Stretch-cne 'Uniform'){return $false}
        if($null-eq$LogoControl.Child){return $false}
        $paths=New-Object 'Collections.Generic.List[object]'
        $queue=New-Object 'Collections.Generic.Queue[object]';$queue.Enqueue($LogoControl.Child)
        while($queue.Count-gt0){
            $node=$queue.Dequeue();if($null-eq$node){continue}
            if($node-is[Windows.Shapes.Path]){[void]$paths.Add($node);continue}
            if($node-is[Windows.Controls.Panel]){foreach($child in @($node.Children)){if($null-ne$child){$queue.Enqueue($child)}};continue}
            if($node-is[Windows.Controls.Decorator]){if($null-ne$node.Child){$queue.Enqueue($node.Child)};continue}
            if($node-is[Windows.Controls.ContentControl]){if($null-ne$node.Content-and$node.Content-is[Windows.DependencyObject]){$queue.Enqueue($node.Content)}}
        }
        if($paths.Count-ne4){return $false}
        foreach($path in $paths){if($null-eq$path.Data-or$null-eq$path.Fill){return $false}}
        if($RequireRenderedArea){
            try{$LogoControl.UpdateLayout()}catch{}
            if($LogoControl.Visibility-ne[Windows.Visibility]::Visible-or$LogoControl.ActualWidth-le0-or$LogoControl.ActualHeight-le0){return $false}
            foreach($path in $paths){if($path.Visibility-ne[Windows.Visibility]::Visible){return $false}}
        }
        return $true
    }catch{try{Write-VSO7Log ('GUI R52 embedded logo validation failed: '+$_.Exception.Message) 'ERROR'}catch{};return $false}
}

function Show-VSO7GuiWelcomeVSO {
    Write-VSO7GuiPerformanceEventVSO -Name 'WELCOME_VISIBLE'
    if($null-eq$script:GuiWelcomeView){throw 'R80 WelcomeView is not initialized.'}
    $script:GuiWelcomeView.Visibility='Visible';$script:GuiHomeView.Visibility='Collapsed';$script:GuiActionView.Visibility='Collapsed';$script:GuiBackButton.Visibility='Collapsed'
    Set-VSO7GuiStatusVSO ''
    if($null-ne$script:GuiWelcomeLogo){
        $script:GuiWelcomeLogo.Visibility='Visible'
        if(-not(Test-VSO7EmbeddedWelcomeLogoVSO -LogoControl $script:GuiWelcomeLogo)){
            try{Write-VSO7Log 'GUI R52 embedded welcome logo definition is invalid; logo remains visible and release/runtime probes must fail.' 'ERROR'}catch{}
            Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'EmbeddedLogoValidationFailed')
        }
    }
}

function Show-VSO7GuiConfirmVSO {
    param([Parameter(Mandatory=$true)][string]$Message,[string]$Title='')
    if([string]::IsNullOrWhiteSpace($Title)){ $Title=Get-VSO7GuiStringVSO 'ConfirmApplyTitle' }
    return ([Windows.MessageBox]::Show($script:GuiWindow,$Message,$Title,[Windows.MessageBoxButton]::YesNo,[Windows.MessageBoxImage]::Warning)-eq[Windows.MessageBoxResult]::Yes)
}

function Show-VSO7GuiErrorVSO {
    param([Parameter(Mandatory=$true)][object]$ErrorObject)
    $technicalMessage=if($ErrorObject-is[Management.Automation.ErrorRecord]){[string]$ErrorObject.Exception.Message}else{[string]$ErrorObject}
    try{ Write-VSO7Log ('GUI R52: '+$technicalMessage) 'ERROR' }catch{}
    $userMessage=Get-VSO7GuiStringVSO 'GuiOperationFailed'
    [void][Windows.MessageBox]::Show($script:GuiWindow,$userMessage,(Get-VSO7GuiStringVSO 'Error'),[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Error)
}

function Set-VSO7GuiStatusVSO {
    param([AllowEmptyString()][string]$Text='')
    if($null-ne$script:GuiStatusText){$script:GuiStatusText.Text=$Text}
}

function New-VSO7GuiTextBlockR44VSO {
    param([string]$Text='',[double]$Size=14,[string]$Color='#F4E7D0',[switch]$Bold,[string]$Margin='0')
    $t=New-Object Windows.Controls.TextBlock
    $t.Text=$Text;$t.FontSize=$Size;$t.Foreground=Get-VSO7GuiBrushVSO $Color;$t.TextWrapping='Wrap';$t.Margin=$Margin
    if($Bold){$t.FontWeight='SemiBold'}
    return $t
}

function New-VSO7GuiButtonR44VSO {
    param([Parameter(Mandatory=$true)][string]$Text,[ValidateSet('Normal','Primary','Danger')][string]$Kind='Normal',[string]$Tag='')
    $b=New-Object Windows.Controls.Button
    $b.Content=$Text;$b.Margin='5';$b.Padding='14,8';$b.MinWidth=105
    if(-not[string]::IsNullOrWhiteSpace($Tag)){$b.Tag=$Tag}
    $styleKey=switch($Kind){'Primary'{'PrimaryButton'}'Danger'{'DangerButton'}default{'VsoButton'}}
    try{$b.Style=$script:GuiWindow.FindResource($styleKey)}catch{}
    return $b
}

function New-VSO7GuiBadgeR44VSO {
    param([Parameter(Mandatory=$true)][string]$Key)
    $palette=switch($Key){
        'LowRisk'{@('#21452B','#D9F5DF')};'MediumRisk'{@('#59451F','#FFE6AA')};'HighRisk'{@('#643B1E','#FFE0BD')};'VeryHighRisk'{@('#652A2A','#FFD8D3')}
        'VariableRisk'{@('#4A304F','#F3D9F7')};'ReadOnly'{@('#263B49','#D8ECF7')};'Rollback'{@('#37402A','#E4F0CB')};'Temporary'{@('#3B3158','#E9DFFF')}
        default{@('#3C3026','#F1D8B7')}
    }
    $border=New-Object Windows.Controls.Border;$border.Background=Get-VSO7GuiBrushVSO $palette[0];$border.BorderBrush=Get-VSO7GuiBrushVSO $palette[1];$border.BorderThickness='1';$border.CornerRadius='4';$border.Padding='7,3';$border.HorizontalAlignment='Left';$border.Margin='0,5,0,6'
    $badgeText=New-VSO7GuiTextBlockR44VSO -Text (Get-VSO7GuiStringVSO $Key) -Size 11 -Color $palette[1] -Bold;$badgeText.TextAlignment='Center';$badgeText.HorizontalAlignment='Center';$badgeText.VerticalAlignment='Center';$border.Child=$badgeText
    return $border
}

function New-VSO7GuiPageR44VSO {
    param([Parameter(Mandatory=$true)][string]$Title,[string]$Description='')
    $root=New-Object Windows.Controls.Grid
    $root.Margin='0,0,0,8'
    $r1=New-Object Windows.Controls.RowDefinition;$r1.Height='Auto';[void]$root.RowDefinitions.Add($r1)
    $r2=New-Object Windows.Controls.RowDefinition;$r2.Height='*';[void]$root.RowDefinitions.Add($r2)
    $r3=New-Object Windows.Controls.RowDefinition;$r3.Height='Auto';[void]$root.RowDefinitions.Add($r3)
    $header=New-Object Windows.Controls.StackPanel;$header.Margin='0,0,0,14';[Windows.Controls.Grid]::SetRow($header,0);[void]$root.Children.Add($header)
    [void]$header.Children.Add((New-VSO7GuiTextBlockR44VSO -Text $Title -Size 27 -Color '#E3A35D' -Bold))
    if(-not[string]::IsNullOrWhiteSpace($Description)){[void]$header.Children.Add((New-VSO7GuiTextBlockR44VSO -Text $Description -Size 13 -Color '#C9B89F' -Margin '0,5,0,0'))}
    $body=New-Object Windows.Controls.Grid;[Windows.Controls.Grid]::SetRow($body,1);[void]$root.Children.Add($body)
    $actions=New-Object Windows.Controls.StackPanel;$actions.Orientation='Horizontal';$actions.HorizontalAlignment='Right';$actions.Margin='0,12,0,0';[Windows.Controls.Grid]::SetRow($actions,2);[void]$root.Children.Add($actions)
    return [pscustomobject]@{Root=$root;Body=$body;Actions=$actions;Header=$header}
}

function Set-VSO7GuiPageR44VSO {
    param([Parameter(Mandatory=$true)]$Page)
    if($null-eq$script:GuiPageHost){return}
    if($null-eq$script:GuiCurrentPageToken){$script:GuiCurrentPageToken=[guid]::NewGuid().ToString('N')}
    $script:GuiPageHost.Content=$Page.Root
    $script:GuiHomeView.Visibility='Collapsed';$script:GuiActionView.Visibility='Visible';$script:GuiBackButton.Visibility='Visible'
}

function New-VSO7GuiDataGridR44VSO {
    param([switch]$ReadOnly)
    $g=New-Object Windows.Controls.DataGrid
    $g.AutoGenerateColumns=$true;$g.CanUserAddRows=$false;$g.CanUserDeleteRows=$false;$g.HeadersVisibility='Column';$g.GridLinesVisibility='Horizontal'
    $g.IsReadOnly=[bool]$ReadOnly;$g.SelectionMode='Single';$g.SelectionUnit='FullRow';$g.EnableRowVirtualization=$true;$g.EnableColumnVirtualization=$true
    $g.VerticalScrollBarVisibility='Auto';$g.HorizontalScrollBarVisibility='Auto';$g.Margin='0,5,0,5'
    return $g
}

function Get-VSO7GuiRiskTextR44VSO { param([int]$Risk) switch($Risk){1{Get-VSO7GuiStringVSO 'LowRisk'}2{Get-VSO7GuiStringVSO 'MediumRisk'}3{Get-VSO7GuiStringVSO 'HighRisk'}default{Get-VSO7GuiStringVSO 'VeryHighRisk'}} }

function Get-VSO7GuiStartupClassificationTextR52VSO {
    param([AllowNull()][string]$Classification)
    switch(([string]$Classification).ToUpperInvariant()){
        'MANTENER'{Get-VSO7GuiStringVSO 'StartupKeep'}
        'KEEP'{Get-VSO7GuiStringVSO 'StartupKeep'}
        'REVISAR'{Get-VSO7GuiStringVSO 'StartupReview'}
        'REVIEW'{Get-VSO7GuiStringVSO 'StartupReview'}
        'CANDIDATO'{Get-VSO7GuiStringVSO 'StartupOptional'}
        'CANDIDATE'{Get-VSO7GuiStringVSO 'StartupOptional'}
        default{[string]$Classification}
    }
}

function Convert-VSO7GuiTuningAreaR52VSO {
    param([AllowNull()][string]$Area)
    $key=[string]$Area
    if($script:Language-eq'es'){
        $map=@{
            'BCD / boot'='BCD / arranque';'BCD / timers'='BCD / temporizadores';'Gaming / capture policy'='Gaming / política de captura';'Gaming / fullscreen'='Gaming / pantalla completa';'Input / mouse'='Entrada / ratón';'MMCSS / Games'='MMCSS / Juegos';'MMCSS / red'='MMCSS / red';'Memoria'='Memoria';'Memoria / pagefile'='Memoria / archivo de paginación';'Power'='Energía';'Power / CPU'='Energía / CPU';'Power / USB'='Energía / USB';'Red / NIC'='Red / NIC';'Red / TCP'='Red / TCP';'Red / offload'='Red / offload';'Security / Defender'='Seguridad / Defender';'Security / HVCI'='Seguridad / HVCI';'Security / VBS'='Seguridad / VBS';'Storage / TRIM'='Almacenamiento / TRIM';'Storage / maintenance'='Almacenamiento / mantenimiento'
        }
    }else{
        $map=@{'MMCSS / red'='MMCSS / network';'Memoria'='Memory';'Memoria / pagefile'='Memory / pagefile';'Red / NIC'='Network / NIC';'Red / TCP'='Network / TCP';'Red / offload'='Network / offload'}
    }
    if($map.ContainsKey($key)){return [string]$map[$key]}
    return $key
}

function Convert-VSO7GuiTuningItemR52VSO {
    param([AllowNull()][string]$Item)
    $key=[string]$Item
    if($script:Language-eq'es'){
        $map=@{
            'Defender exclusions'='Exclusiones de Defender';'Fullscreen Optimization compatibility flags'='Flags de compatibilidad de optimizaciones de pantalla completa';'Lectura BCD'='Lectura BCD';'Maximum processor state'='Estado máximo del procesador';'Memory Compression'='Compresión de memoria';'Memory Integrity'='Integridad de memoria';'Minimum processor state'='Estado mínimo del procesador';'Nagle / delayed ACK overrides'='Overrides de Nagle / ACK retrasado';'Pagefile personalizado'='Archivo de paginación personalizado';'Real-time protection'='Protección en tiempo real';'Receive Window Auto-Tuning'='Ajuste automático de ventana de recepción';'ReceiveSideScaling global'='RSS global';'Scheduled drive optimization'='Optimización programada de unidades';'USB selective suspend'='Suspensión selectiva USB';'Virtualization-Based Security'='Seguridad basada en virtualización';'Windows pointer acceleration'='Aceleración del puntero de Windows'
        }
    }else{
        $map=@{'Lectura BCD'='BCD read';'Pagefile personalizado'='Custom pagefile'}
    }
    if($map.ContainsKey($key)){return [string]$map[$key]}
    return $key
}

function Convert-VSO7GuiTuningFindingR52VSO {
    param([Parameter(Mandatory=$true)]$Finding)
    [pscustomobject]@{
        Risk=Get-VSO7GuiRiskTextR44VSO([int]$Finding.Risk)
        Area=Convert-VSO7GuiTuningAreaR52VSO -Area ([string]$Finding.Area)
        Item=Convert-VSO7GuiTuningItemR52VSO -Item ([string]$Finding.Item)
        Configured=[string]$Finding.Configured
        Effective=[string]$Finding.Effective
        Evidence=[string]$Finding.Evidence
        Maturity=[string]$Finding.Maturity
        Explanation=if($script:Language-eq'es'){[string]$Finding.WhyEs}else{[string]$Finding.WhyEn}
        RecommendedAction=if($script:Language-eq'es'){[string]$Finding.RecommendationEs}else{[string]$Finding.RecommendationEn}
    }
}

function Convert-VSO7GuiScoreCheckR52VSO {
    param([Parameter(Mandatory=$true)]$Check)
    $nameMap=@{
        'Modo de juego'='ScoreGameMode';'Captura en segundo plano'='ScoreBackgroundCapture';'Espacio libre del sistema'='ScoreSystemFreeSpace';'Inicio automatico'='ScoreStartup';'Plan de energia'='ScorePowerPlan';'Punto de restauracion reciente'='ScoreRecentRestore';'Overlays/launchers activos'='ScoreOverlays';'CPU de fondo (10 s)'='ScoreBackgroundCpu';'RAM en reposo (10 s)'='ScoreRamUsage';'Reinicio pendiente'='ScorePendingReboot';'Actividad DPC (10 s)'='ScoreDpc'
    }
    $rawName=[string]$Check.Comprobacion;$name=if($nameMap.ContainsKey($rawName)){Get-VSO7GuiStringVSO $nameMap[$rawName]}else{$rawName}
    $detail=[string]$Check.Detalle
    if($rawName-eq'Inicio automatico'-and$detail-match'^(?<N>[0-9]+) candidato\(s\)$'){$detail=Get-VSO7GuiStringVSO 'GuiStartupItemsFound' -Args @([int]$matches.N)}
    elseif($rawName-eq'Overlays/launchers activos'-and$detail-match'^(?<A>[0-9]+) candidato\(s\), (?<B>[0-9]+) revisar, (?<C>[0-9]+) protegido\(s\); (?<D>[0-9]+) proceso\(s\) detectado\(s\)$'){$detail=Get-VSO7GuiStringVSO 'GuiOverlayProcessesFound' -Args @([int]$matches.A,[int]$matches.B,[int]$matches.C,[int]$matches.D)}
    elseif($rawName-eq'Reinicio pendiente'){$detail=if($detail-eq'SI'){Get-VSO7GuiStringVSO 'GuiYes'}elseif($detail-eq'NO'){Get-VSO7GuiStringVSO 'GuiNo'}else{$detail}}
    elseif($detail-like'NO DISPONIBLE:*'){$detail=(Get-VSO7GuiStringVSO 'GuiUnavailable')+': '+$detail.Substring(14).Trim()}
    [pscustomobject]@{Check=$name;Points=[int]$Check.Puntos;Max=[int]$Check.Max;Detail=$detail}
}


function Get-VSO7GuiRestartTextR52VSO {
    param([AllowNull()][string]$Restart)
    $value=([string]$Restart).Trim()
    if([string]::IsNullOrWhiteSpace($value)-or$value-in@('None','False','No','0')){return $(if($script:Language-eq'es'){'Sin reinicio'}else{'No restart'})}
    switch -Regex ($value){
        'System|Windows|Reboot|True|Required'{return $(if($script:Language-eq'es'){'Reiniciar Windows'}else{'Restart Windows'})}
        'Logoff|SignOut'{return $(if($script:Language-eq'es'){'Cerrar sesión'}else{'Sign out required'})}
        'Network|Adapter'{return $(if($script:Language-eq'es'){'Reinicia la red'}else{'Network restarts'})}
        'App'{return $(if($script:Language-eq'es'){'Reiniciar la aplicación'}else{'Restart the app'})}
        default{return $value}
    }
}

function Get-VSO7GuiReversibleTextR52VSO {
    param([bool]$Reversible)
    if($Reversible){return $(if($script:Language-eq'es'){'Se puede deshacer'}else{'Reversible'})}
    return $(if($script:Language-eq'es'){'No se puede deshacer automáticamente'}else{'Not automatically reversible'})
}

function Get-VSO7GuiUnifiedRiskPaletteR52VSO {
    param([int]$Risk)
    switch($Risk){
        1{return [pscustomobject]@{Background='#193A24';Border='#52C878';Foreground='#E9FFF0'}}
        2{return [pscustomobject]@{Background='#4A3B13';Border='#E7BC45';Foreground='#FFF5CE'}}
        3{return [pscustomobject]@{Background='#4A2814';Border='#E58A43';Foreground='#FFF0DF'}}
        default{return [pscustomobject]@{Background='#4A1E1E';Border='#E26868';Foreground='#FFF0F0'}}
    }
}

function Get-VSO7GuiHumanFeatureCopyR52VSO {
    param([Parameter(Mandatory=$true)]$Feature)
    $id=[string]$Feature.FeatureId
    $isEs=([string]$script:Language-ceq'es')
    $map=@{
        EnableUsbSelectiveSuspend=@(
            'Lets Windows put idle USB devices into a low-power state again.','This restores normal Windows USB power management only when something disabled it.',
            'Permite que Windows vuelva a poner en bajo consumo los dispositivos USB que están inactivos.','Restaura la gestión de energía USB normal de Windows solo cuando algo la había desactivado.'
        )
        RestorePhysicalNicChecksumOffloads=@(
            'Lets the network adapter handle checksum work instead of leaving all of it to the CPU.','This can avoid unnecessary CPU work while moving network traffic when the adapter supports it.',
            'Permite que la tarjeta de red haga el trabajo de comprobación de paquetes en vez de dejarlo todo a la CPU.','Puede evitar trabajo innecesario de CPU al mover tráfico de red cuando la tarjeta lo soporta.'
        )
        RestoreGlobalReceiveSideScaling=@(
            'Lets Windows spread incoming network traffic across several CPU cores.','If RSS was disabled, restoring it avoids concentrating receive processing on a single CPU core.',
            'Permite que Windows reparta el tráfico de red entrante entre varios núcleos de CPU.','Si RSS estaba desactivado, restaurarlo evita concentrar todo el procesamiento de recepción en un solo núcleo.'
        )
        RestoreGlobalTaskOffload=@(
            'Lets Windows use supported network hardware offloading again.','Restoring the global switch can reduce CPU work during network traffic without forcing unsupported adapter options.',
            'Permite que Windows vuelva a usar la aceleración de red que soporte el hardware.','Restaurar el control global puede reducir trabajo de CPU durante el tráfico sin forzar funciones que la tarjeta no soporte.'
        )
        RestoreTcpAutoTuningNormal=@(
            'Returns TCP receive-window tuning to Windows automatic mode.','This removes fixed or disabled receive-window behavior that can unnecessarily limit network throughput.',
            'Devuelve el ajuste de la ventana de recepción TCP al modo automático de Windows.','Evita configuraciones fijas o desactivadas que pueden limitar innecesariamente el rendimiento de red.'
        )
        RestorePhysicalNicEee=@(
            'Lets compatible Ethernet hardware save power while the link is mostly idle.','This is a power-efficiency choice, not a universal latency or FPS improvement.',
            'Permite que el hardware Ethernet compatible ahorre energía cuando el enlace está casi inactivo.','Es una opción de eficiencia energética, no una mejora universal de latencia ni FPS.'
        )
        EnableNtfsTrimWhenDisabledNoReFs=@(
            'Turns SSD/NVMe TRIM notifications back on when NTFS has them disabled.','TRIM tells compatible storage which deleted blocks are free so the drive can manage them correctly.',
            'Vuelve a activar TRIM en SSD/NVMe cuando NTFS lo tenía desactivado.','TRIM avisa al almacenamiento de qué bloques borrados están libres para que la unidad pueda gestionarlos correctamente.'
        )
        EnableScheduledDriveOptimization=@(
            'Restores Windows scheduled Optimize Drives maintenance.','Windows can then run the appropriate maintenance for the drive type, such as retrim for SSDs.',
            'Restaura el mantenimiento programado de Optimizar unidades de Windows.','Windows puede volver a ejecutar el mantenimiento apropiado para cada unidad, como retrim en SSD.'
        )
        RestorePowerThrottlingToUserControl=@(
            'Gives Windows and the user normal control of background power throttling again.','This removes a blanket policy that disabled Power Throttling everywhere instead of forcing one behavior for every workload.',
            'Devuelve a Windows y al usuario el control normal del ahorro de energía de procesos en segundo plano.','Elimina una política global que lo desactivaba para todo, en vez de imponer el mismo comportamiento a cualquier carga.'
        )
        RestoreMaxProcessorStateOnAcDesktop=@(
            'Restores the maximum CPU state to 100% on plugged-in desktop PCs when it was capped.','This removes an artificial processor ceiling while the desktop is on AC power.',
            'Restaura el máximo de CPU al 100% en sobremesas conectados a corriente cuando estaba limitado.','Elimina un límite artificial del procesador mientras el sobremesa está conectado a la corriente.'
        )
        SetProcessorEppEfficiencyOnBatteryLaptop=@(
            'Asks the CPU to favor battery life more while the laptop is unplugged.','It only targets battery use; it is intentionally not presented as a performance improvement.',
            'Pide a la CPU que priorice más la batería cuando el portátil está desenchufado.','Solo afecta al uso con batería; no se presenta como una mejora de rendimiento.'
        )
        EnableActiveCoolingOnAcLaptop=@(
            'Prefers increasing active cooling before slowing the CPU while the laptop is plugged in.','This can preserve performance under heat on AC power, at the cost of potentially more fan noise.',
            'Prefiere aumentar la refrigeración activa antes de reducir la CPU cuando el portátil está enchufado.','Puede mantener mejor el rendimiento con temperatura alta en corriente, a cambio de poder usar más los ventiladores.'
        )
        RestoreNicSelectiveSuspendOnLaptops=@(
            'Lets Windows suspend an idle network adapter on laptops when the adapter supports it.','This is aimed at reducing idle power use on laptops, not at improving gaming latency.',
            'Permite que Windows suspenda una tarjeta de red inactiva en portátiles cuando el adaptador lo soporta.','Busca reducir consumo en reposo del portátil, no mejorar la latencia en juegos.'
        )
        V7GM101=@(
            'Turns on Windows Game Mode.','This lets Windows use its built-in gaming resource policy; it does not promise higher FPS on every PC.',
            'Activa el Game Mode de Windows.','Permite que Windows use su política integrada para juegos; no promete más FPS en todos los PCs.'
        )
        V7PW103=@(
            'Disables CPU turbo/boost only while the laptop is running on battery.','This can reduce battery drain and temperature, with lower peak CPU performance while unplugged.',
            'Desactiva el turbo/boost de la CPU solo cuando el portátil funciona con batería.','Puede reducir consumo y temperatura, a cambio de menos rendimiento máximo de CPU mientras está desenchufado.'
        )
        V7PW104=@(
            'Uses a moderate PCIe power-saving mode while the laptop is on battery.','This is a battery-efficiency trade-off and is not applied as a general performance tweak.',
            'Usa un ahorro de energía PCIe moderado mientras el portátil está con batería.','Es un compromiso para ahorrar batería y no se aplica como tweak general de rendimiento.'
        )
    }
    if($map.ContainsKey($id)){$v=$map[$id];if($isEs){return [pscustomobject]@{Summary=[string]$v[2];Why=[string]$v[3]}};return [pscustomobject]@{Summary=[string]$v[0];Why=[string]$v[1]}}
    $summary=if($isEs){[string]$Feature.DescriptionEs}else{[string]$Feature.DescriptionEn}
    return [pscustomobject]@{Summary=$summary;Why=$summary}
}

function ConvertTo-VSO7GuiUnifiedRowR52VSO {
    param(
        [Parameter(Mandatory=$true)]$InputObject,
        [string]$Id='', [string]$Name='', [string]$Description='', [string]$Category='',
        [int]$Risk=1, [AllowNull()][string]$Restart='None', [bool]$Reversible=$true,
        [bool]$Selected=$false, [bool]$CanSelect=$true, [string]$Status='', [string]$Why='', [string]$Technical=''
    )
    $pal=Get-VSO7GuiUnifiedRiskPaletteR52VSO $Risk
    [pscustomobject]@{
        IsSelected=$Selected;CanSelect=$CanSelect;Id=$Id;Name=$Name;Description=$Description;Category=$Category;Risk=$Risk;RiskText=(Get-VSO7GuiRiskTextR44VSO $Risk)
        RiskBackground=$pal.Background;RiskBorder=$pal.Border;RiskForeground=$pal.Foreground;RiskVisibility='Visible'
        RestartText=(Get-VSO7GuiRestartTextR52VSO $Restart);RestartVisibility='Visible'
        ReversibleText=(Get-VSO7GuiReversibleTextR52VSO $Reversible);ReversibleVisibility='Visible'
        Status=$Status;StatusVisibility=$(if([string]::IsNullOrWhiteSpace($Status)){'Collapsed'}else{'Visible'})
        Why=$Why;Technical=$Technical;Raw=$InputObject;Visibility='Visible';CategoryAccent='#E3A35D';Visual=$null;CheckBox=$null
    }
}

function Get-VSO7GuiCompactBlockRowTemplateR52VSO {
    if($null-ne$script:GuiCompactBlockRowTemplateR52){return $script:GuiCompactBlockRowTemplateR52}
    [xml]$templateXml=@'
<DataTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation">
  <Border Visibility="{Binding Visibility}" Margin="0,1" Padding="4,3" BorderBrush="#33271E" BorderThickness="0,0,0,1" Background="Transparent">
    <Grid>
      <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
      <CheckBox Grid.Column="0" IsChecked="{Binding IsSelected,Mode=TwoWay,UpdateSourceTrigger=PropertyChanged}" IsEnabled="{Binding CanSelect}" Margin="2,4,8,2" VerticalAlignment="Top"/>
      <StackPanel Grid.Column="1" Margin="0,0,6,0">
        <TextBlock Text="{Binding Name}" FontWeight="SemiBold" FontSize="12" Foreground="#FFF4E0" TextWrapping="Wrap"/>
        <WrapPanel Margin="0,2,0,0">
          <Border Visibility="{Binding RestartVisibility}" Background="#3B3158" CornerRadius="3" Padding="5,1" Margin="0,0,5,0"><TextBlock Text="{Binding RestartText}" Foreground="#E9DFFF" FontSize="9" TextAlignment="Center" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
          <Border Visibility="{Binding ReversibleVisibility}" Background="#273B2A" CornerRadius="3" Padding="5,1" Margin="0,0,5,0"><TextBlock Text="{Binding ReversibleText}" Foreground="#D8F0D8" FontSize="9" TextAlignment="Center" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
          <TextBlock Visibility="{Binding StatusVisibility}" Text="{Binding Status}" Foreground="#A9977E" FontSize="9" Margin="2,2,0,0"/>
        </WrapPanel>
      </StackPanel>
      <Border Grid.Column="2" Visibility="{Binding RiskVisibility}" Background="{Binding RiskBackground}" BorderBrush="{Binding RiskBorder}" BorderThickness="1" CornerRadius="3" Padding="6,2" Margin="5,2,0,2" VerticalAlignment="Top"><TextBlock Text="{Binding RiskText}" Foreground="{Binding RiskForeground}" FontSize="9" FontWeight="Bold" TextAlignment="Center" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>
    </Grid>
  </Border>
</DataTemplate>
'@
    $reader=New-Object System.Xml.XmlNodeReader $templateXml
    $script:GuiCompactBlockRowTemplateR52=[Windows.Markup.XamlReader]::Load($reader)
    return $script:GuiCompactBlockRowTemplateR52
}


function New-VSO7GuiCategoryBlockListR52VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)][string]$Title,[Parameter(Mandatory=$true)][object[]]$Rows)
    return New-VSO7GuiCategoryCardR53VSO -Context $Context -Title $Title -Rows $Rows
}

