        ColumnsGrid=$null
        MainScroll=$null
        MainHost=$null
        LayoutRoot=$null
        SizeChangedHandler=$null
        DetailRoot=$null
        DetailTitle=$null
        DetailSummary=$null
        DetailWhy=$null
        DetailStatus=$null
        DetailRestart=$null
        DetailReversible=$null
        DetailTechnical=$null
        PrimaryList=$null
        PrimaryView=$null
        InstalledOnly=$null
        AppRecommendationFilter=$null
        PageToken=''
        Loading=$null
        LoadingBar=$null
        Refresh=$null
        ProfileText=$null
        Optional=$null
        Preview=$null
        PreviewRequestId=''
        Allow=$null
        CurrentProfile=$null
        Summary=$null
        Apply=$null
        RecommendedButton=$null
        RecommendationSummary=$null
        SelectionHelp=$null
        BulkRiskButton=$null
        SelectionPopup=$null
        Editable=$false
        Grid=$null
        Status=$null
        Button=$null
        Before=$null
        After=$null
        Compare=$null
        InitTimer=$null
        InitData=$null
        InitCategory=$null
        LayoutKind=''
    }
}


function Assert-VSO7GuiContextPropertyR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)][string]$Name)
    if($null-eq$Context.PSObject.Properties[$Name]){throw ('GUI context contract missing property: '+$Name)}
    return $true
}

function Set-VSO7GuiContextPropertyR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)][string]$Name,[AllowNull()]$Value)
    [void](Assert-VSO7GuiContextPropertyR53VSO -Context $Context -Name $Name)
    $Context.$Name=$Value
}

function Test-VSO7GuiSelectionContextContractR53VSO {
    $required=@('Rows','Count','Search','Risk','Category','Objective','Mode','NavigationTarget','SingleSelection','Lists','CategoryEntries','BuildQueue','BuildIndex','BuildTimer','Columns','ColumnWeights','ColumnCount','ColumnsGrid','MainScroll','MainHost','LayoutRoot','SizeChangedHandler','DetailRoot','DetailTitle','DetailSummary','DetailWhy','DetailStatus','DetailRestart','DetailReversible','DetailTechnical','PrimaryList','InstalledOnly','PageToken','Loading','LoadingBar','Refresh','ProfileText','Optional','Preview','PreviewRequestId','Allow','CurrentProfile','Summary','Apply','RecommendedButton','Editable','Grid','Status','Button','Before','After','Compare','InitTimer','LayoutKind')
    $ctx=New-VSO7GuiSelectionContextR53VSO -Rows (New-Object Collections.ArrayList) -NavigationTarget 'ContextContractSmoke'
    $missing=@($required|Where-Object{$null-eq$ctx.PSObject.Properties[[string]$_]})
    if($missing.Count-gt0){throw ('GUI selection context contract is incomplete: '+($missing-join', '))}
    foreach($name in $required){[void](Assert-VSO7GuiContextPropertyR53VSO -Context $ctx -Name ([string]$name))}
    return [pscustomobject]@{Required=$required.Count;Missing=$missing;Pass=$true}
}

function New-VSO7GuiTweakRowControlR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)]$Row)
    $border=New-Object Windows.Controls.Border
    $border.Margin='0,1';$border.Padding='5,4';$border.BorderBrush=Get-VSO7GuiBrushVSO '#33271E'
    $border.BorderThickness='0,0,0,1';$border.Background=[Windows.Media.Brushes]::Transparent
    $grid=New-Object Windows.Controls.Grid
    foreach($width in @('Auto','*','Auto')){$c=New-Object Windows.Controls.ColumnDefinition;$c.Width=$width;[void]$grid.ColumnDefinitions.Add($c)}
    $check=New-Object Windows.Controls.CheckBox
    $check.IsChecked=[bool]$Row.IsSelected;$check.IsEnabled=[bool]$Row.CanSelect
    $check.Margin='2,4,8,2';$check.VerticalAlignment='Top'
    $check.DataContext=$Row;$check.Tag=$Context
    [Windows.Controls.Grid]::SetColumn($check,0);[void]$grid.Children.Add($check)
    $center=New-Object Windows.Controls.StackPanel
    [Windows.Controls.Grid]::SetColumn($center,1);[void]$grid.Children.Add($center)
    $name=New-VSO7GuiTextBlockR44VSO -Text ([string]$Row.Name) -Size 12 -Color '#FFF4E0' -Bold
    $name.TextWrapping=[Windows.TextWrapping]::Wrap
    [void]$center.Children.Add($name)
    $meta=New-Object Windows.Controls.WrapPanel;$meta.Margin='0,2,0,0'
    if([string]$Row.RestartVisibility-ne'Collapsed'){
        $rb=New-Object Windows.Controls.Border;$rb.Background=Get-VSO7GuiBrushVSO '#3B3158';$rb.CornerRadius='3';$rb.Padding='5,1';$rb.Margin='0,0,5,0'
        $rbText=New-VSO7GuiTextBlockR44VSO -Text ([string]$Row.RestartText) -Size 9 -Color '#E9DFFF';$rbText.TextAlignment='Center';$rbText.HorizontalAlignment='Center';$rbText.VerticalAlignment='Center';$rb.Child=$rbText
        [void]$meta.Children.Add($rb)
    }
    if([string]$Row.ReversibleVisibility-ne'Collapsed'){
        $ub=New-Object Windows.Controls.Border;$ub.Background=Get-VSO7GuiBrushVSO '#273B2A';$ub.CornerRadius='3';$ub.Padding='5,1';$ub.Margin='0,0,5,0'
        $ubText=New-VSO7GuiTextBlockR44VSO -Text ([string]$Row.ReversibleText) -Size 9 -Color '#D8F0D8';$ubText.TextAlignment='Center';$ubText.HorizontalAlignment='Center';$ubText.VerticalAlignment='Center';$ub.Child=$ubText
        [void]$meta.Children.Add($ub)
    }
    if([string]$Row.StatusVisibility-ne'Collapsed' -and -not[string]::IsNullOrWhiteSpace([string]$Row.Status)){
        [void]$meta.Children.Add((New-VSO7GuiTextBlockR44VSO -Text ([string]$Row.Status) -Size 9 -Color '#A9977E' -Margin '2,2,0,0'))
    }
    [void]$center.Children.Add($meta)
    if([string]$Row.RiskVisibility-ne'Collapsed'){
        $risk=New-Object Windows.Controls.Border;$risk.Background=Get-VSO7GuiBrushVSO ([string]$Row.RiskBackground)
        $risk.BorderBrush=Get-VSO7GuiBrushVSO ([string]$Row.RiskBorder);$risk.BorderThickness='1';$risk.CornerRadius='3'
        $risk.Padding='6,2';$risk.Margin='5,2,0,2';$risk.VerticalAlignment='Top'
        $riskText=New-VSO7GuiTextBlockR44VSO -Text ([string]$Row.RiskText) -Size 9 -Color ([string]$Row.RiskForeground) -Bold;$riskText.TextAlignment='Center';$riskText.HorizontalAlignment='Center';$riskText.VerticalAlignment='Center';$risk.Child=$riskText
        [Windows.Controls.Grid]::SetColumn($risk,2);[void]$grid.Children.Add($risk)
    }
    $border.Child=$grid;$border.Tag=$Row;$border.DataContext=$Context
    $check.Add_Checked([Windows.RoutedEventHandler]{param($sender,$e);Invoke-VSO7GuiRowToggleR53VSO -Context $sender.Tag -Row $sender.DataContext -Checked $true})
    $check.Add_Unchecked([Windows.RoutedEventHandler]{param($sender,$e);Invoke-VSO7GuiRowToggleR53VSO -Context $sender.Tag -Row $sender.DataContext -Checked $false})
    $border.Add_MouseLeftButtonUp([Windows.Input.MouseButtonEventHandler]{param($sender,$e);Set-VSO7GuiUnifiedDetailR52VSO -Context $sender.DataContext -Row $sender.Tag})
    $Row.Visual=$border;$Row.CheckBox=$check
    return $border
}

function New-VSO7GuiCategoryCardR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)][string]$Title,[Parameter(Mandatory=$true)][object[]]$Rows)
    $panel=New-Object Windows.Controls.Border
    $panel.HorizontalAlignment='Stretch';$panel.Margin='6';$panel.Padding='10'
    $panel.BorderBrush=Get-VSO7GuiBrushVSO '#5F4936';$panel.BorderThickness='1';$panel.CornerRadius='5'
    $panel.Background=Get-VSO7GuiBrushVSO '#1B1713'
    $stack=New-Object Windows.Controls.StackPanel;$panel.Child=$stack
    $accent='#E3A35D';$first=@($Rows|Select-Object -First 1)
    if($first.Count-and$null-ne$first[0].PSObject.Properties['CategoryAccent']-and-not[string]::IsNullOrWhiteSpace([string]$first[0].CategoryAccent)){$accent=[string]$first[0].CategoryAccent}
    [void]$stack.Children.Add((New-VSO7GuiTextBlockR44VSO -Text $Title -Size 15 -Color $accent -Bold -Margin '0,0,0,6'))
    foreach($row in @($Rows)){[void]$stack.Children.Add((New-VSO7GuiTweakRowControlR53VSO -Context $Context -Row $row))}
    $entry=[pscustomobject]@{Panel=$panel;Rows=@($Rows);Name=$Title;Weight=([math]::Max(1,@($Rows).Count+1))}
    [void]$Context.CategoryEntries.Add($entry)
    return $panel
}

function Invoke-VSO7GuiRowToggleR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)]$Row,[bool]$Checked)
    $Row.IsSelected=[bool]$Checked
    if([bool]$Context.SingleSelection-and$Checked){
        foreach($x in @($Context.Rows)){
