        $cd=New-Object Windows.Controls.ColumnDefinition;$cd.Width=if($i-eq0){'*'}else{'0'};[void]$columnsGrid.ColumnDefinitions.Add($cd)
        $sp=New-Object Windows.Controls.StackPanel;$sp.HorizontalAlignment='Stretch'
