    $scroll.Content=$columnsGrid
    $detail=New-VSO7GuiUnifiedDetailPanelR53VSO
    [Windows.Controls.Grid]::SetRow($detail.Root,0);[Windows.Controls.Grid]::SetColumn($detail.Root,1);[void]$outer.Children.Add($detail.Root)
    $ctx.LayoutRoot=$outer;$ctx.MainScroll=$scroll;$ctx.ColumnsGrid=$columnsGrid;$ctx.DetailRoot=$detail.Root
    $ctx.DetailTitle=$detail.Title;$ctx.DetailSummary=$detail.Summary;$ctx.DetailWhy=$detail.Why;$ctx.DetailStatus=$detail.Status
    $ctx.DetailRestart=$detail.Restart;$ctx.DetailReversible=$detail.Reversible;$ctx.DetailTechnical=$detail.Technical
    $sizeHandler=[Windows.SizeChangedEventHandler]{param($sender,$e);Update-VSO7GuiCategorizedLayoutR53VSO -Context $sender.DataContext}
    $ctx.SizeChangedHandler=$sizeHandler;$outer.DataContext=$ctx;$outer.Add_SizeChanged($sizeHandler)
    return [pscustomobject]@{Root=$outer;Context=$ctx;Detail=$detail}
