function Get-VSO7GuiCategorizedLayoutDecisionR79VSO {
    param([Parameter(Mandatory=$true)][double]$AvailableWidth)
    if($AvailableWidth-le0){throw 'Categorized layout requires a positive available width.'}
    return [pscustomobject]@{AvailableWidth=$AvailableWidth;DetailRight=($AvailableWidth-ge1500);ColumnCount=$(if($AvailableWidth-ge1500){3}elseif($AvailableWidth-ge1000){2}else{1})}
}

function Update-VSO7GuiCategorizedLayoutR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[Nullable[double]]$AvailableWidth=$null)
    if($null-eq$Context.LayoutRoot-or$null-eq$Context.ColumnsGrid){return}
    $width=if($null-ne$AvailableWidth){[double]$AvailableWidth}else{[double]$Context.LayoutRoot.ActualWidth}
    if($width-le0-and$null-ne$script:GuiWindow){$width=[double]$script:GuiWindow.ActualWidth}
    if($width-le0){$width=1280}
    $decision=Get-VSO7GuiCategorizedLayoutDecisionR79VSO -AvailableWidth $width
    $detailRight=[bool]$decision.DetailRight
    $count=[int]$decision.ColumnCount
    $Context.ColumnCount=$count
    for($i=0;$i-lt3;$i++){$Context.ColumnsGrid.ColumnDefinitions[$i].Width=if($i-lt$count){'*'}else{'0'}}
    if($detailRight){
        $Context.LayoutRoot.RowDefinitions[0].Height='*';$Context.LayoutRoot.RowDefinitions[1].Height='0'
        $Context.LayoutRoot.ColumnDefinitions[0].Width='*';$Context.LayoutRoot.ColumnDefinitions[1].Width='360'
        [Windows.Controls.Grid]::SetRow($Context.DetailRoot,0);[Windows.Controls.Grid]::SetColumn($Context.DetailRoot,1);[Windows.Controls.Grid]::SetColumnSpan($Context.DetailRoot,1)
        $Context.DetailRoot.Margin='12,0,0,0'
    }else{
        $Context.LayoutRoot.RowDefinitions[0].Height='*';$Context.LayoutRoot.RowDefinitions[1].Height='Auto'
        $Context.LayoutRoot.ColumnDefinitions[0].Width='*';$Context.LayoutRoot.ColumnDefinitions[1].Width='0'
        [Windows.Controls.Grid]::SetRow($Context.DetailRoot,1);[Windows.Controls.Grid]::SetColumn($Context.DetailRoot,0);[Windows.Controls.Grid]::SetColumnSpan($Context.DetailRoot,2)
        $Context.DetailRoot.Margin='0,12,0,0'
    }
    Reflow-VSO7GuiCategoryCardsR53VSO -Context $Context
}

function Reflow-VSO7GuiCategoryCardsR53VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $count=[math]::Max(1,[math]::Min(3,[int]$Context.ColumnCount))
    foreach($column in @($Context.Columns)){$column.Children.Clear()}
    $weights=@(0,0,0)
    foreach($entry in @($Context.CategoryEntries)){
        $target=0
        for($i=1;$i-lt$count;$i++){if($weights[$i]-lt$weights[$target]){$target=$i}}
        [void]$Context.Columns[$target].Children.Add($entry.Panel)
        $weights[$target]+=[int]$entry.Weight
    }
    $Context.ColumnWeights=$weights
}

function Start-VSO7GuiGroupedBlockBuildR52VSO {
    param([Parameter(Mandatory=$true)]$Context,[string[]]$CategoryOrder=@())
    Start-VSO7GuiCategorizedBuildR53VSO -Context $Context -CategoryOrder $CategoryOrder
}

function Start-VSO7GuiCategorizedBuildR53VSO {
    param([Parameter(Mandatory=$true)]$Context,[string[]]$CategoryOrder=@())
    if($null-ne$Context.BuildTimer){try{$Context.BuildTimer.Stop()}catch{}}
    foreach($column in @($Context.Columns)){$column.Children.Clear()}
    $Context.CategoryEntries.Clear();$Context.BuildIndex=0
    $groups=@($Context.Rows|Group-Object Category)
    if($CategoryOrder.Count-gt0){
        $rank=@{};for($i=0;$i-lt$CategoryOrder.Count;$i++){$rank[[string]$CategoryOrder[$i]]=$i}
        $groups=@($groups|Sort-Object @{Expression={if($rank.ContainsKey([string]$_.Name)){$rank[[string]$_.Name]}else{1000}}},Name)
    }else{$groups=@($groups|Sort-Object Name)}
    $Context.BuildQueue=$groups
    Update-VSO7GuiCategorizedLayoutR53VSO -Context $Context
    if($groups.Count-eq0){
        Write-VSO7GuiPerformanceEventVSO -Name 'PAGE_INTERACTIVE' -NavigationTarget ([string]$Context.NavigationTarget) -CacheHit $false -BackgroundLoad $false
        return
    }
    $timer=New-Object Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromMilliseconds(1);$timer.Tag=$Context;$Context.BuildTimer=$timer
    $timer.Add_Tick([System.EventHandler]{param($sender,$e);Invoke-VSO7GuiCategorizedBuildTickR53VSO -Timer $sender})
    $timer.Start()
}

function Invoke-VSO7GuiCategorizedBuildTickR53VSO {
    param([Parameter(Mandatory=$true)]$Timer)
    $c=$Timer.Tag
    if($null-eq$c){$Timer.Stop();return}
    $built=0
    while($c.BuildIndex-lt@($c.BuildQueue).Count-and$built-lt1){
        $g=$c.BuildQueue[$c.BuildIndex];$c.BuildIndex++;$built++
        [void](New-VSO7GuiCategoryCardR53VSO -Context $c -Title ([string]$g.Name) -Rows @($g.Group))
    }
    Reflow-VSO7GuiCategoryCardsR53VSO -Context $c
    if($c.BuildIndex-ge@($c.BuildQueue).Count){
        $Timer.Stop();$c.BuildTimer=$null
        Refresh-VSO7GuiCategorizedSurfaceR53VSO -Context $c
        Write-VSO7GuiPerformanceEventVSO -Name 'FIRST_ROWS_VISIBLE' -NavigationTarget ([string]$c.NavigationTarget) -CacheHit $false -BackgroundLoad $false -Detail ('Categories='+@($c.BuildQueue).Count)
        Write-VSO7GuiPerformanceEventVSO -Name 'PAGE_INTERACTIVE' -NavigationTarget ([string]$c.NavigationTarget) -CacheHit $false -BackgroundLoad $false
    }
}


