function New-VSO7GuiPrimaryListSurfaceR53VSO {
    param(
        [Parameter(Mandatory=$true)]$Rows,
        [string]$NavigationTarget='',
        [switch]$SingleSelection,
        [switch]$ShowDetail,
        [switch]$Applications
    )
    $ctx=New-VSO7GuiSelectionContextR53VSO -Rows $Rows -NavigationTarget $NavigationTarget -SingleSelection:$SingleSelection
    $ctx.LayoutKind=if($Applications){'Applications'}else{'RuntimeList'}
    $root=New-Object Windows.Controls.Grid
    foreach($h in @('*','Auto')){$r=New-Object Windows.Controls.RowDefinition;$r.Height=$h;[void]$root.RowDefinitions.Add($r)}
    foreach($w in @('*','0')){$c=New-Object Windows.Controls.ColumnDefinition;$c.Width=$w;[void]$root.ColumnDefinitions.Add($c)}
    $list=New-Object Windows.Controls.ListView
    $list.BorderBrush=Get-VSO7GuiBrushVSO '#5F4936';$list.BorderThickness='1';$list.Background=Get-VSO7GuiBrushVSO '#17130F'
    $list.HorizontalContentAlignment='Stretch';$list.SelectionMode=[Windows.Controls.SelectionMode]::Single
    $list.ItemTemplate=if($Applications){Get-VSO7GuiAppRowTemplateR53VSO}else{Get-VSO7GuiPrimaryRowTemplateR53VSO}
    if($Applications){
        $view=[Windows.Data.CollectionViewSource]::GetDefaultView($Rows)
        try{$view.GroupDescriptions.Clear()}catch{}
        $gd=New-Object Windows.Data.PropertyGroupDescription;$gd.PropertyName='RecommendationGroup';[void]$view.GroupDescriptions.Add($gd)
        $gs=New-Object Windows.Controls.GroupStyle;$gs.HeaderTemplate=Get-VSO7GuiAppGroupHeaderTemplateR69VSO;[void]$list.GroupStyle.Add($gs)
        [Windows.Controls.VirtualizingPanel]::SetIsVirtualizingWhenGrouping($list,$true)
        $list.ItemsSource=$view;$ctx.PrimaryView=$view
    }else{$list.ItemsSource=$Rows}
    $list.DataContext=$ctx
    [Windows.Controls.VirtualizingPanel]::SetIsVirtualizing($list,$true)
    [Windows.Controls.VirtualizingPanel]::SetVirtualizationMode($list,[Windows.Controls.VirtualizationMode]::Recycling)
    [Windows.Controls.ScrollViewer]::SetCanContentScroll($list,$true)
    [Windows.Controls.ScrollViewer]::SetVerticalScrollBarVisibility($list,[Windows.Controls.ScrollBarVisibility]::Auto)
    [Windows.Controls.Grid]::SetRow($list,0);[Windows.Controls.Grid]::SetColumn($list,0);[void]$root.Children.Add($list)
    $ctx.PrimaryList=$list;$ctx.Lists.Add($list)|Out-Null;$ctx.LayoutRoot=$root
    $list.AddHandler([Windows.Controls.Primitives.ToggleButton]::CheckedEvent,[Windows.RoutedEventHandler]{param($sender,$e);if($null-ne$e.OriginalSource.DataContext){Invoke-VSO7GuiRowToggleR53VSO -Context $sender.DataContext -Row $e.OriginalSource.DataContext -Checked $true}})
    $list.AddHandler([Windows.Controls.Primitives.ToggleButton]::UncheckedEvent,[Windows.RoutedEventHandler]{param($sender,$e);if($null-ne$e.OriginalSource.DataContext){Invoke-VSO7GuiRowToggleR53VSO -Context $sender.DataContext -Row $e.OriginalSource.DataContext -Checked $false}})
    if($ShowDetail){
