        $ctx.DetailRoot=$detail.Root;$ctx.DetailTitle=$detail.Title;$ctx.DetailSummary=$detail.Summary;$ctx.DetailWhy=$detail.Why
        $ctx.DetailStatus=$detail.Status;$ctx.DetailRestart=$detail.Restart;$ctx.DetailReversible=$detail.Reversible;$ctx.DetailTechnical=$detail.Technical
        $list.Add_SelectionChanged([Windows.Controls.SelectionChangedEventHandler]{param($sender,$e);if($e.AddedItems.Count-gt0){Set-VSO7GuiUnifiedDetailR52VSO -Context $sender.DataContext -Row $e.AddedItems[0]}})
        $sizeHandler=[Windows.SizeChangedEventHandler]{param($sender,$e);Update-VSO7GuiPrimaryListLayoutR53VSO -Context $sender.DataContext}
        $ctx.SizeChangedHandler=$sizeHandler;$root.DataContext=$ctx;$root.Add_SizeChanged($sizeHandler)
    }
    return [pscustomobject]@{Root=$root;Context=$ctx;List=$list}
}


