    foreach($row in @($Context.Rows)){$visible=($riskIdx-eq0-or[int]$row.Risk-eq$riskIdx)-and($cat-eq$all-or[string]$row.Category-ceq$cat)-and([string]::IsNullOrWhiteSpace($q)-or[string]$row.Name.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0-or[string]$row.Description.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0);$row.Visibility=if($visible){'Visible'}else{'Collapsed'}}
