function New-VSO7GuiUnifiedDetailPanelR53VSO {
    $border=New-Object Windows.Controls.Border
    $border.Margin='12,0,0,0';$border.Padding='14'
    $border.BorderBrush=Get-VSO7GuiBrushVSO '#674B34';$border.BorderThickness='1'
    $border.Background=Get-VSO7GuiBrushVSO '#1D1814'
    $stack=New-Object Windows.Controls.StackPanel
    $border.Child=$stack
    $title=New-VSO7GuiTextBlockR44VSO -Text ($(if($script:Language-eq'es'){'Selecciona una opción'}else{'Select an option'})) -Size 20 -Color '#FFF4E0' -Bold -Margin '0,0,0,8'
    [void]$stack.Children.Add($title)
    $summary=New-VSO7GuiTextBlockR44VSO -Text '' -Size 12 -Color '#EAD8BE' -Margin '0,0,0,10'
    [void]$stack.Children.Add($summary)
    $fields=@{}
    foreach($spec in @(
        @('Why',$(if($script:Language-eq'es'){'Por qué puede ser útil'}else{'Why it may help'})),
        @('Status',$(if($script:Language-eq'es'){'En este PC'}else{'On this PC'})),
        @('Restart',$(if($script:Language-eq'es'){'Reinicio'}else{'Restart'})),
        @('Reversible',$(if($script:Language-eq'es'){'Deshacer'}else{'Undo'}))
    )){
        [void]$stack.Children.Add((New-VSO7GuiTextBlockR44VSO -Text ([string]$spec[1]) -Size 11 -Color '#E3A35D' -Bold -Margin '0,8,0,2'))
        $v=New-VSO7GuiTextBlockR44VSO -Text '' -Size 12 -Color '#EAD8BE'
        [void]$stack.Children.Add($v)
        $fields[[string]$spec[0]]=$v
    }
    $exp=New-Object Windows.Controls.Expander
    $exp.Header=$(if($script:Language-eq'es'){'Detalles técnicos'}else{'Technical details'})
    $exp.Foreground=Get-VSO7GuiBrushVSO '#BDA98D';$exp.Margin='0,12,0,0'
    $tech=New-VSO7GuiTextBlockR44VSO -Text '' -Size 11 -Color '#A9977E'
    $exp.Content=$tech
    [void]$stack.Children.Add($exp)
    return [pscustomobject]@{
        Root=$border;Title=$title;Summary=$summary;Why=$fields.Why;Status=$fields.Status
        Restart=$fields.Restart;Reversible=$fields.Reversible;Technical=$tech;TechnicalExpander=$exp
    }
}

function Get-VSO7GuiBackgroundScriptContextR77VSO {
    # R80: explicit worker state contract. Keep this list aligned with the transitive `$script:*`
    # dependencies of Start-VSO7GuiBackgroundFunctionR52VSO targets. WPF/UI objects are never shared.
    $names=@(
        'AppData','BuiltInPowerSchemes','ConfigRoot','DisplayVersion',
        'ExpectedVSO7AppCatalogSha256','ExpectedVSO7FeatureCatalogSha256','ExpectedVSO7NativeTweaksSha256',
        'ExtremeState','ExtremeStateFile','Language','LastRecoveryBundle','LegacyTranslationsEsToEn','LogFile',
        'NativeJournalRevision','ProgramData','ProtectedProcessesFile','RecoveryAuthKeyFile','RecoveryRoot','RecoveryRunnerHash',
        'SecureStateRoot','StartupState','StartupStateFile','State','StateFile','SystemDirectory','SystemDrive',
        'ThemeCopper','ThemeDanger','ThemeMuted','ThemeSuccess','ThemeText','ThemeWarning',
        'TranslationsEn','TranslationsEs','VSO7AppCatalog','VSO7AppCatalogObjectCache','VSO7ApplicabilityContext',
        'VSO7FeatureCatalog','VSO7GraphicsDiagnosticsCache','VSO7GraphicsUserPreferencePath','VSO7NativeTweaks','Version','WindowsRoot'
    )
    $context=@{}
    foreach($name in $names){
        $v=Get-Variable -Scope Script -Name $name -ErrorAction SilentlyContinue
        if($null-ne$v){$context[$name]=$v.Value}
    }
    # Background workers must never call back into live WPF objects. Functions that branch on these
    # values take the non-GUI path in the worker and their presentation happens later on Dispatcher.
    $context['GuiMode']=$false
    $context['GuiOutput']=$null
    $context['GuiOutputParagraph']=$null
    $context['GuiWindow']=$null
    return $context
}

function Invoke-VSO7GuiBackgroundEntryR77VSO {
    param(
        [Parameter(Mandatory=$true)][string]$FunctionName,
        [hashtable]$Parameters=@{},
        [Parameter(Mandatory=$true)][hashtable]$ScriptContext
    )
    foreach($name in @($ScriptContext.Keys)){
        $n=[string]$name
        if($n-notmatch'^[A-Za-z_][A-Za-z0-9_]*$'){throw ('Invalid background script-context variable name: '+$n)}
        Set-Variable -Scope Script -Name $n -Value $ScriptContext[$name] -Force
    }
    $target=Get-Command -Name $FunctionName -CommandType Function -ErrorAction SilentlyContinue | Select-Object -First 1
    if($null-eq$target){throw ('Background worker function not found: '+$FunctionName)}
    & $FunctionName @Parameters
}

function Get-VSO7GuiBackgroundRunspaceR52VSO {
    # R80: each operation owns its runspace. Functions are installed once; script state is injected
    # explicitly by Invoke-VSO7GuiBackgroundEntryR77VSO immediately before the target worker runs.
    $iss=[Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
    foreach($cmd in @(Get-Command -CommandType Function -ErrorAction SilentlyContinue)){
        try{
            if([string]::IsNullOrWhiteSpace([string]$cmd.Name)-or[string]$cmd.Name-like'prompt'){continue}
            [void]$iss.Commands.Add((New-Object Management.Automation.Runspaces.SessionStateFunctionEntry([string]$cmd.Name,[string]$cmd.Definition)))
        }catch{}
    }
    $rs=[Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($iss);$rs.ApartmentState='MTA';$rs.ThreadOptions='ReuseThread';$rs.Open()
    return $rs
}

function Complete-VSO7GuiBackgroundUiR76VSO {
    param([Parameter(Mandatory=$true)]$State)
    $c=$State.UiContext;if($null-eq$c){return}
    if([string]$State.CompletionKind-in@('RestorePointStatus','RestorePointCreate')){
        $generation=if($null-ne$State.Tag-and$null-ne$State.Tag.PSObject.Properties['Generation']){[int]$State.Tag.Generation}else{-1}
        if($null-ne$c.PSObject.Properties['RestorePointGeneration']-and$generation-ne[int]$c.RestorePointGeneration){return}
        if([string]$State.Status-cne'Succeeded'-and[string]$State.CompletionKind-ceq'RestorePointCreate'){$c.RestorePointBusy=$false}
        if([bool]$c.RestorePointBusy){return}
        try{$c.Create.IsEnabled=$true}catch{};try{$c.Progress.Visibility='Collapsed'}catch{}
        return
    }
    foreach($n in @('Button','Refresh','Before','After','RecommendedButton','Preview','Create')){
        if($null-ne$c.PSObject.Properties[$n]-and$null-ne$c.$n){try{$c.$n.IsEnabled=$true}catch{}}
    }
    foreach($n in @('Loading','Progress')){if($null-ne$c.PSObject.Properties[$n]-and$null-ne$c.$n){try{$c.$n.Visibility='Collapsed'}catch{}}}
    if([string]$State.CompletionKind-ceq'RecommendedPreview'-and[string]$State.Status-cne'Succeeded'){try{Reset-VSO7GuiRecommendedPlanR75VSO -Context $c}catch{}}
}

function Register-VSO7GuiBackgroundFailureR76VSO {
    param([Parameter(Mandatory=$true)]$State,[Parameter(Mandatory=$true)]$ErrorRecord,[string]$Phase='Worker')
    $message=try{[string]$ErrorRecord.Exception.Message}catch{[string]$ErrorRecord}
    try{Write-VSO7Log (('Background GUI operation failed [{0}] ({1}): {2}'-f[string]$State.Context,$Phase,$message)) 'ERROR'}catch{}
    if($null-ne$script:GuiRuntimeCallbackErrors){
        try{[void]$script:GuiRuntimeCallbackErrors.Add([pscustomobject]@{Context=[string]$State.Context;Message=$message;Type=try{$ErrorRecord.Exception.GetType().FullName}catch{''};Source='BackgroundWorker';Phase=$Phase;JobId=[string]$State.JobId})}catch{}
    }
    $c=$State.UiContext;if($null-ne$c-and$null-ne$c.PSObject.Properties['Status']-and$null-ne$c.Status){try{$c.Status.Text=$(if($script:Language-eq'es'){'No se pudo completar esta operación. Revisa el log si necesitas el detalle.'}else{'This operation could not be completed. Check the log if you need the technical detail.'})}catch{}}
}

function Get-VSO7GuiBackgroundOperationStatusR76VSO {
    param([Parameter(Mandatory=$true)][string]$Context)
    if($null-ne$script:GuiBackgroundLastByContextR76-and$script:GuiBackgroundLastByContextR76.ContainsKey($Context)){return $script:GuiBackgroundLastByContextR76[$Context]}
    return $null
}

function Start-VSO7GuiBackgroundFunctionR52VSO {
    param([Parameter(Mandatory=$true)][string]$FunctionName,[hashtable]$Parameters=@{},[Parameter(Mandatory=$true)][string]$CompletionKind,[Parameter(Mandatory=$true)]$UiContext,[string]$Context='Background',[AllowNull()]$Tag=$null)
    $jobId=[guid]::NewGuid().ToString('N');$rs=$null;$ps=$null;$timer=$null
    $state=[pscustomobject][ordered]@{JobId=$jobId;PowerShell=$null;Runspace=$null;Async=$null;Timer=$null;Handler=$null;CompletionKind=$CompletionKind;UiContext=$UiContext;Context=$Context;Tag=$Tag;Status='Starting';ResultStatus='';StartedAt=[DateTime]::UtcNow;FinishedAt=$null;Error='';StreamErrorCount=0}
    $script:GuiBackgroundLastByContextR76[$Context]=$state
    try{
        $workerContext=Get-VSO7GuiBackgroundScriptContextR77VSO
        $rs=Get-VSO7GuiBackgroundRunspaceR52VSO
        $ps=[PowerShell]::Create();$ps.Runspace=$rs
        [void]$ps.AddCommand('Invoke-VSO7GuiBackgroundEntryR77VSO')
        [void]$ps.AddParameter('FunctionName',$FunctionName)
        [void]$ps.AddParameter('Parameters',$Parameters)
        [void]$ps.AddParameter('ScriptContext',$workerContext)
        $async=$ps.BeginInvoke()
        $timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds(80)
        $state.PowerShell=$ps;$state.Runspace=$rs;$state.Async=$async;$state.Timer=$timer;$state.Status='Running'
        $handler=[EventHandler]{param($sender,$e);Complete-VSO7GuiBackgroundFunctionR52VSO -Timer $sender}
        $state.Handler=$handler;$timer.Tag=$state;$timer.Add_Tick($handler);$script:GuiBackgroundJobsR76[$jobId]=$state;$timer.Start();return $state
    }catch{
        $state.Status='Failed';$state.Error=[string]$_.Exception.Message;$state.FinishedAt=[DateTime]::UtcNow
        Register-VSO7GuiBackgroundFailureR76VSO -State $state -ErrorRecord $_ -Phase 'Start'
        Complete-VSO7GuiBackgroundUiR76VSO -State $state
        try{if($null-ne$ps){$ps.Dispose()}}catch{};try{if($null-ne$rs){$rs.Close();$rs.Dispose()}}catch{}
        return $state
    }
}

function Complete-VSO7GuiBackgroundFunctionR52VSO {
    param([Parameter(Mandatory=$true)]$Timer)
    $st=$Timer.Tag;if($null-eq$st-or$null-eq$st.Async-or-not$st.Async.IsCompleted){return}
    try{$Timer.Stop()}catch{};if($null-ne$st.Handler){try{$Timer.Remove_Tick($st.Handler)}catch{}}
    $result=@();$err=$null;$streamErrors=@()
    try{
        try{$result=@($st.PowerShell.EndInvoke($st.Async))}catch{$err=$_}
        try{$streamErrors=@($st.PowerShell.Streams.Error)}catch{}
        $st.StreamErrorCount=[int]$streamErrors.Count
        if($null-eq$err-and$streamErrors.Count-gt0){$err=$streamErrors[0]}
        if($null-ne$err){
            $st.Status='Failed';$st.Error=try{[string]$err.Exception.Message}catch{[string]$err};Register-VSO7GuiBackgroundFailureR76VSO -State $st -ErrorRecord $err -Phase $(if($streamErrors.Count){'Streams.Error'}else{'EndInvoke'})
        }else{
            try{Invoke-VSO7GuiBackgroundCompletionR52VSO -State $st -Result $result -ErrorRecord $null;if([string]$st.Status-ceq'Running'){$st.Status='Succeeded'}}catch{
                $st.Status='Failed';$st.Error=[string]$_.Exception.Message;Register-VSO7GuiBackgroundFailureR76VSO -State $st -ErrorRecord $_ -Phase 'Presentation';try{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context ('BackgroundCompletion.'+[string]$st.Context)}catch{}
            }
        }
    }finally{
        Complete-VSO7GuiBackgroundUiR76VSO -State $st;$st.FinishedAt=[DateTime]::UtcNow
        try{$st.PowerShell.Dispose()}catch{};try{$st.Runspace.Close()}catch{};try{$st.Runspace.Dispose()}catch{}
        try{[void]$script:GuiBackgroundJobsR76.Remove([string]$st.JobId)}catch{}
    }
}

function Set-VSO7GuiBackgroundErrorR52VSO {
    param([Parameter(Mandatory=$true)]$State,[Parameter(Mandatory=$true)]$ErrorRecord)
    Register-VSO7GuiBackgroundFailureR76VSO -State $State -ErrorRecord $ErrorRecord -Phase 'Compatibility'
    Complete-VSO7GuiBackgroundUiR76VSO -State $State
}

function Invoke-VSO7GuiBackgroundCompletionR52VSO {
    param([Parameter(Mandatory=$true)]$State,[object[]]$Result=@(),[AllowNull()]$ErrorRecord)
    $c=$State.UiContext;if($null-ne$ErrorRecord){Set-VSO7GuiBackgroundErrorR52VSO -State $State -ErrorRecord $ErrorRecord;return}
    switch([string]$State.CompletionKind){
        'Score'{
            $score=@($Result|Select-Object -Last 1);if($score.Count-eq0){throw 'Score worker returned no result.'};$score=$score[0];try{Save-VSO7ScoreHistory $score}catch{};$c.Global.Text=((Get-VSO7GuiStringVSO 'Global')+(' {0}/100' -f$score.Score));$c.Config.Text=((Get-VSO7GuiStringVSO 'Configuration')+(' {0}/100' -f$score.ConfigurationScore));$c.State.Text=((Get-VSO7GuiStringVSO 'CurrentState')+(' {0}/100' -f$score.StateScore));$c.Grid.ItemsSource=@($score.Checks|ForEach-Object{Convert-VSO7GuiScoreCheckR52VSO -Check $_});$c.Status.Text=Get-VSO7GuiStringVSO 'Done'
        }
        'Benchmark'{
            $m=@($Result|Select-Object -Last 1);if($m.Count-eq0){throw 'Benchmark worker returned no result.'};$m=$m[0];if([string]$State.Tag-eq'BASELINE'){$script:LastBenchmarkBaseline=$m}else{$script:LastBenchmarkPost=$m};$c.Grid.ItemsSource=@($m.PSObject.Properties|Where-Object{$_.Name-notin@('Timestamp','Label')}|ForEach-Object{[pscustomobject]@{Metric=$_.Name;Value=$_.Value}});$c.Status.Text=Get-VSO7GuiStringVSO 'Done'
        }
        'ReadOnly'{
            if([string]$State.Tag-eq'TuningAudit'){$c.Grid.ItemsSource=@($Result|ForEach-Object{Convert-VSO7GuiTuningFindingR52VSO -Finding $_});$c.Status.Text=Get-VSO7GuiStringVSO 'Done'}else{
                $payload=@($Result|Where-Object{[string]$_.Schema-ceq'VSO7.ReadOnlyInventoryResult.v1'}|Select-Object -Last 1);if($payload.Count-ne1){throw 'Read-only inventory worker returned no structured result.'};$payload=$payload[0];$c.Grid.ItemsSource=@($payload.Rows);$State.ResultStatus=[string]$payload.Status
                if([string]$payload.Status-ceq'Failed'){throw ('Read-only inventory failed: '+(@($payload.Errors)-join'; '))}
                if([string]$payload.Status-ceq'Partial'){$State.Status='Partial';$c.Status.Text=$(if($script:Language-eq'es'){'Resultado parcial. Algunas fuentes obligatorias fallaron; revisa el log.'}else{'Partial result. Some required sources failed; check the log.'})}
                else{$c.Status.Text=$(if(@($payload.Warnings).Count){if($script:Language-eq'es'){'Completado; alguna fuente opcional no estaba disponible.'}else{'Completed; an optional source was unavailable.'}}else{Get-VSO7GuiStringVSO 'Done'})}
            }
        }
        'RecommendedSelection'{
            $plan=@($Result|Select-Object -Last 1);if($plan.Count-eq0){throw 'Recommendation worker returned no plan.'};$plan=$plan[0];$set=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal);foreach($id in @($plan.SelectedFeatureIds)){[void]$set.Add([string]$id)};foreach($x in @($c.Rows)){$x.IsSelected=$set.Contains([string]$x.Id)};Refresh-VSO7GuiGroupedBlockListsR52VSO -Context $c;Update-VSO7GuiUnifiedSelectedCountR52VSO -Context $c;$summary=Get-VSO7GuiStringVSO 'RecommendedSummary' -Args @(@($plan.SelectedFeatureIds).Count,@($plan.AlreadyOptimal).Count,@($plan.Skipped).Count);if($null-ne$c.RecommendationSummary){$c.RecommendationSummary.Text=$summary};Set-VSO7GuiStatusVSO $summary
        }
        'RecommendedPreview'{
            $tag=$State.Tag;$currentObjective=Get-VSO7GuiObjectiveValueR69VSO -ComboBox $c.Objective;$currentOptional=[bool]$c.Optional.IsChecked;$currentRequest=$(if($null-ne$c.PSObject.Properties['PreviewRequestId']){[string]$c.PreviewRequestId}else{''});if($null-eq$tag-or[string]$tag.RequestId-cne$currentRequest-or[string]$tag.Objective-cne[string]$currentObjective-or[bool]$tag.IncludeOptional-ne$currentOptional){Reset-VSO7GuiRecommendedPlanR75VSO -Context $c;return};$plan=@($Result|Select-Object -Last 1);if($plan.Count-eq0){throw 'Recommendation worker returned no plan.'};$plan=$plan[0];$plan|Add-Member -NotePropertyName PreviewId -NotePropertyValue ([string]$tag.RequestId) -Force;$plan|Add-Member -NotePropertyName IncludeOptional -NotePropertyValue ([bool]$tag.IncludeOptional) -Force;$catalog=@(Get-VSO7FeatureCatalogVSO);$rev=Get-VSO7GuiFeatureReversibilityMapR52VSO;$c.Rows.Clear();foreach($id in @($plan.SelectedFeatureIds)){$f=@($catalog|Where-Object{[string]$_.FeatureId-ceq[string]$id}|Select-Object -First 1);if($f.Count-ne1){continue};$f=$f[0];$copy=Get-VSO7GuiHumanFeatureCopyR52VSO -Feature $f;$row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $f -Id ([string]$f.FeatureId) -Name $(if($script:Language-eq'es'){[string]$f.NameEs}else{[string]$f.NameEn}) -Description ([string]$copy.Summary) -Category $(if($script:Language-eq'es'){[string]$f.CategoryEs}else{[string]$f.CategoryEn}) -Risk ([int]$f.Risk) -Restart ([string]$f.RebootRequirement) -Reversible ([bool]$rev[[string]$f.FeatureId]) -Selected $true -Status $(if($script:Language-eq'es'){'Recomendado para este PC'}else{'Recommended for this PC'}) -Why ([string]$copy.Why) -Technical ('FeatureId: '+[string]$f.FeatureId+' · Evidence: '+[string]$f.Evidence+' · Maturity: '+[string]$f.Maturity);[void]$c.Rows.Add($row)};Start-VSO7GuiCategorizedBuildR53VSO -Context $c;Update-VSO7GuiUnifiedSelectedCountR52VSO -Context $c;$c.Apply.IsEnabled=$true;$script:GuiRecommendedPlan=$plan
        }
        'StartupInventory'{
            $c.Rows.Clear();foreach($entry in @($Result)){$class=Get-VSO7GuiStartupClassificationTextR52VSO -Classification ([string]$entry.Classification);$desc=[string]$entry.Command;if($desc.Length-gt220){$desc=$desc.Substring(0,220)+'…'};$row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $entry -Id ([string]$entry.Name) -Name ([string]$entry.Name) -Description $desc -Category $class -Risk 2 -Restart 'None' -Reversible $true -Status ([string]$entry.Location) -Why $(if($script:Language-eq'es'){'Evita que esta aplicación se abra automáticamente al iniciar sesión. Puedes restaurarla desde Recuperación.'}else{'Prevents this app from opening automatically when you sign in. You can restore it from Recovery.'}) -Technical ('Location: '+[string]$entry.Location+' · Classification: '+[string]$entry.Classification);[void]$c.Rows.Add($row)};Refresh-VSO7GuiPrimaryListR53VSO -Context $c;Update-VSO7GuiUnifiedSelectedCountR52VSO -Context $c
        }
        'RecoveryInventory'{
            $c.Rows.Clear();$inventory=@($Result|Select-Object -Last 1);if($inventory.Count){$inventory=$inventory[0];foreach($x in @($inventory.Valid)){$reqs=@();try{$reqs=@($x.Entries|ForEach-Object{[string]$_.RestartRequirement}|Where-Object{-not[string]::IsNullOrWhiteSpace($_)})}catch{};$restart=if($reqs-match'SystemRestart|Reboot'){'SystemRestart'}elseif($reqs-match'Logoff|SignOut'){'Logoff'}elseif($reqs-match'Network|Adapter'){'Network'}elseif($reqs-match'App'){'App'}else{'None'};$desc=$(if($script:Language-eq'es'){"Creada $([string]$x.CreatedAt). Estado: $([string]$x.Status)."}else{"Created $([string]$x.CreatedAt). Status: $([string]$x.Status)."});$row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $x -Id ([string]$x.BatchId) -Name ([string]$x.BatchKind+' · '+[string]$x.CreatedAt) -Description $desc -Category ([string]$x.BatchKind) -Risk 1 -Restart $restart -Reversible $true -Status ([string]$x.Status) -Why $(if($script:Language-eq'es'){'Restaura el estado que VSO guardó antes de aplicar cambios.'}else{'Restores the state VSO saved before applying changes.'}) -Technical ('BatchId: '+[string]$x.BatchId+' · Directory: '+[string]$x.Directory);[void]$c.Rows.Add($row)}};Refresh-VSO7GuiPrimaryListR53VSO -Context $c
        }
        'StorageInventory'{$d=@($Result|Select-Object -Last 1);if($d.Count){$c.Grid.ItemsSource=@($d[0].Physical)};$c.Status.Visibility='Collapsed'}
        'GamingSessionInventory'{
            $c.Rows.Clear();foreach($g in @($Result|Select-Object -First 30)){$mb=[Math]::Round(([double]$g.WorkingSet64/1MB),0);$row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $g -Id ([string]$g.Id) -Name ([string]$g.ProcessName) -Description ([string]$g.Path) -Category $(if($script:Language-eq'es'){'Juegos detectados'}else{'Detected games'}) -Risk 1 -Restart 'None' -Reversible $true -Status ("$mb MB RAM") -Why $(if($script:Language-eq'es'){'La sesión Gaming es temporal y VSO intenta restaurar el estado cuando termina el juego.'}else{'The Gaming session is temporary and VSO attempts to restore the previous state when the game exits.'}) -Technical ('PID: '+[string]$g.Id+' · Path: '+[string]$g.Path);[void]$c.Rows.Add($row)};Refresh-VSO7GuiPrimaryListR53VSO -Context $c;$c.ProfileText.Text=$(if($script:Language-eq'es'){"Juegos detectados: $($c.Rows.Count)"}else{"Detected games: $($c.Rows.Count)"})
        }
        'OverlayInventory'{
            $c.Rows.Clear();foreach($entry in @($Result)){$row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $entry -Id ([string]$entry.Id) -Name ([string]$entry.Process) -Description ([string]$entry.Path) -Category $(if($script:Language-eq'es'){'Procesos detectados'}else{'Detected processes'}) -Risk 2 -Restart 'None' -Reversible $true -Status (([string]$entry.RAM_MB)+' MB RAM') -Why $(if($script:Language-eq'es'){'Cerrar un overlay o launcher puede liberar recursos durante esta sesión. No se desinstala nada.'}else{'Closing an overlay or launcher can free resources for this session. Nothing is uninstalled.'}) -Technical ('PID: '+[string]$entry.Id+' · Started: '+[string]$entry.StartTimeUtc);[void]$c.Rows.Add($row)};Refresh-VSO7GuiPrimaryListR53VSO -Context $c
        }
        'RestorePointStatus'{
            $generation=if($null-ne$State.Tag-and$null-ne$State.Tag.PSObject.Properties['Generation']){[int]$State.Tag.Generation}else{-1}
            if($null-ne$c.PSObject.Properties['RestorePointGeneration']-and$generation-ne[int]$c.RestorePointGeneration){return}
            $phase=if($null-ne$State.Tag){[string]$State.Tag.Phase}else{''}
            if([bool]$c.RestorePointBusy-and$phase-cne'AfterCreate'){return}
            $info=@($Result|Select-Object -Last 1);if($info.Count-eq0-or-not[bool]$info[0].Exists){$c.Status.Text=Get-VSO7GuiStringVSO 'RestorePointNone';$c.Detail.Text=''}else{$i=$info[0];$c.Status.Text=Get-VSO7GuiStringVSO 'RestorePointLast' -Args @([string]$i.Created);$c.Detail.Text=(Get-VSO7GuiStringVSO 'RestorePointAge' -Args @([string]$i.AgeHours))}
            if($phase-ceq'AfterCreate'){$c.RestorePointBusy=$false}
        }
        'RestorePointCreate'{
            $generation=if($null-ne$State.Tag-and$null-ne$State.Tag.PSObject.Properties['Generation']){[int]$State.Tag.Generation}else{-1};if($generation-ne[int]$c.RestorePointGeneration){return}
            $op=@($Result|Select-Object -Last 1);if($op.Count-eq0-or[string]$op[0].Schema-cne'VSO7.RestorePointResult.v1'-or-not[bool]$op[0].Success){$c.Status.Text=Get-VSO7GuiStringVSO 'RestorePointFailed';$c.RestorePointBusy=$false;throw (Get-VSO7GuiStringVSO 'RestorePointFailed')}
            if([string]$op[0].Status-ceq'Created'){$c.Status.Text=Get-VSO7GuiStringVSO 'RestorePointCreated'}else{$c.Status.Text=$(if($script:Language-eq'es'){'Ya existe un punto de restauración reciente y se ha verificado.'}else{'A recent restore point already exists and was verified.'})};$c.Detail.Text=''
            [void](Start-VSO7GuiBackgroundFunctionR52VSO -FunctionName 'Get-VSO7GuiRestorePointInfoR69VSO' -CompletionKind 'RestorePointStatus' -UiContext $c -Context 'RestorePoint.StatusAfterCreate' -Tag ([pscustomobject]@{Generation=$generation;Phase='AfterCreate'}))
        }
        default{throw ('Unknown GUI background completion kind: '+[string]$State.CompletionKind)}
    }
}

function Stop-VSO7GuiBackgroundRunspaceR52VSO {
    param([int]$StopTimeoutMs=1500)
    $jobs=@();if($null-ne$script:GuiBackgroundJobsR76){$jobs=@($script:GuiBackgroundJobsR76.Values)}
    foreach($st in $jobs){
        try{if($null-ne$st.Timer){$st.Timer.Stop();if($null-ne$st.Handler){$st.Timer.Remove_Tick($st.Handler)}}}catch{}
        $st.Status='Cancelling';$stopped=$false
        if($null-ne$st.PowerShell){
            try{
                $ar=$st.PowerShell.BeginStop($null,$null)
                if($null-ne$ar-and$ar.AsyncWaitHandle.WaitOne([Math]::Max(1,$StopTimeoutMs))){try{$st.PowerShell.EndStop($ar)}catch{};$stopped=$true}
            }catch{try{Write-VSO7Log ('Background cancellation begin failed ['+[string]$st.Context+']: '+$_.Exception.Message) 'WARN'}catch{}}
        }
        if($stopped){$st.Status='Cancelled';try{$st.PowerShell.Dispose()}catch{};try{$st.Runspace.Close()}catch{};try{$st.Runspace.Dispose()}catch{}}
        else{$st.Status='Abandoned';try{Write-VSO7Log ('Background job did not stop within '+$StopTimeoutMs+' ms during GUI shutdown; synchronous Close/Dispose was skipped: '+[string]$st.Context) 'WARN'}catch{}}
        $st.FinishedAt=[DateTime]::UtcNow;try{[void]$script:GuiBackgroundJobsR76.Remove([string]$st.JobId)}catch{}
    }
    $script:GuiBackgroundRunspaceR52=$null
}

function Start-VSO7GuiReadOnlyRefreshR52VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $Context.Refresh.IsEnabled=$false;$Context.Status.Text=$(if($script:Language-eq'es'){'Actualizando…'}else{'Refreshing…'});[void](Start-VSO7GuiBackgroundFunctionR52VSO -FunctionName ([string]$Context.FunctionName) -CompletionKind 'ReadOnly' -UiContext $Context -Tag ([string]$Context.CompletionTag) -Context ('ReadOnly.'+[string]$Context.Mode))
