function Get-VSO7GuiAnalysisRowsR52VSO {
    $rows=@();$errors=@();$warnings=@()
    try{$os=CimCmdlets\Get-CimInstance Win32_OperatingSystem -ErrorAction Stop;if($null-eq$os){throw 'Win32_OperatingSystem returned no row.'};$rows+=[pscustomobject]@{Area='Windows';Item=[string]$os.Caption;Detail=([string]$os.Version+' build '+[string]$os.BuildNumber)}}catch{$errors+=('Windows: '+$_.Exception.Message)}
    try{$cpu=CimCmdlets\Get-CimInstance Win32_Processor -ErrorAction Stop|Select-Object -First 1;if($null-eq$cpu){throw 'Win32_Processor returned no row.'};$rows+=[pscustomobject]@{Area='CPU';Item=[string]$cpu.Name;Detail=''}}catch{$errors+=('CPU: '+$_.Exception.Message)}
    try{$ram=Get-RamDiagnostics;if($null-eq$ram){throw 'RAM diagnostics returned no result.'};$rows+=[pscustomobject]@{Area='RAM';Item=('{0} GB'-f$ram.TotalGB);Detail=(@($ram.Modules).Count.ToString()+' module(s)')}}catch{$errors+=('RAM: '+$_.Exception.Message)}
    try{foreach($g in @(Get-GpuDiagnostics)){$rows+=[pscustomobject]@{Area='GPU';Item=[string]$g.Name;Detail=[string]$g.DriverVersion}}}catch{$warnings+=('GPU: '+$_.Exception.Message)}
    $status=if($errors.Count-eq0){'Complete'}elseif($rows.Count-eq0){'Failed'}else{'Partial'}
    return [pscustomobject]@{Schema='VSO7.ReadOnlyInventoryResult.v1';Kind='Analysis';Status=$status;Rows=@($rows);Errors=@($errors);Warnings=@($warnings)}
}

function Get-VSO7GuiDiagnosticsRowsR52VSO {
    $rows=@();$errors=@();$warnings=@()
    try{$r=Get-RamDiagnostics;if($null-eq$r){throw 'RAM diagnostics returned no result.'};$rows+=[pscustomobject]@{Area='RAM';Status='OK';Detail=('{0} GB · {1} modules'-f$r.TotalGB,@($r.Modules).Count)}}catch{$errors+=('RAM: '+$_.Exception.Message)}
    try{foreach($g in @(Get-GpuDiagnostics)){$rows+=[pscustomobject]@{Area='GPU';Status=[string]$g.DriverVersion;Detail=[string]$g.Name}}}catch{$warnings+=('GPU: '+$_.Exception.Message)}
    try{$d=Get-DiskDiagnostics;if($null-eq$d){throw 'Disk diagnostics returned no result.'};$rows+=[pscustomobject]@{Area='Storage';Status='OK';Detail=(@($d.Physical).Count.ToString()+' physical disk(s)')}}catch{$errors+=('Storage: '+$_.Exception.Message)}
    try{$plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective Balanced;foreach($x in @($plan.Selected)){$f=$x.Feature;$rows+=[pscustomobject]@{Area=[string]$f.CategoryEn;Status='Recommended';Detail=[string]$f.NameEn}};foreach($x in @($plan.AlreadyOptimal)){$f=$x.Feature;$rows+=[pscustomobject]@{Area=[string]$f.CategoryEn;Status='Already optimal';Detail=[string]$f.NameEn}}}catch{$warnings+=('Recommendation: '+$_.Exception.Message)}
    $status=if($errors.Count-eq0){'Complete'}elseif($rows.Count-eq0){'Failed'}else{'Partial'}
    return [pscustomobject]@{Schema='VSO7.ReadOnlyInventoryResult.v1';Kind='Diagnostics';Status=$status;Rows=@($rows);Errors=@($errors);Warnings=@($warnings)}
}


