    $compare.Add_Click([Windows.RoutedEventHandler]{param($sender,$e);try{$c=$sender.DataContext;if($null-eq$script:LastBenchmarkBaseline-or$null-eq$script:LastBenchmarkPost){throw (Get-VSO7GuiStringVSO 'BaselineRequired')};$c.Grid.ItemsSource=@(Compare-VSO7Benchmarks -Before $script:LastBenchmarkBaseline -After $script:LastBenchmarkPost)}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Benchmark.Compare'}});Set-VSO7GuiPageR44VSO $p
