    $border=New-Object Windows.Controls.Border;$border.Background=Get-VSO7GuiBrushVSO '#1B1713';$border.BorderBrush=Get-VSO7GuiBrushVSO '#8A674B';$border.BorderThickness='1';$border.CornerRadius='5';$border.Padding='6';$border.Margin='0,4,0,0'
    $stack=New-Object Windows.Controls.StackPanel;$border.Child=$stack;$popup.Child=$border
