        $b=New-VSO7GuiButtonR44VSO -Text (Get-VSO7GuiStringVSO ([string]$spec[1]));$b.HorizontalContentAlignment='Left';$b.MinWidth=230;$b.Tag=[int]$spec[0]
        $b.DataContext=[pscustomobject]@{Context=$Context;Popup=$popup;Label=(Get-VSO7GuiStringVSO ([string]$spec[1]))}
        $b.Add_Click([Windows.RoutedEventHandler]{param($s,$e);$st=$s.DataContext;$limit=[int]$s.Tag;$selected=0;foreach($row in @($st.Context.Rows)){if([bool]$row.CanSelect){$row.IsSelected=([int]$row.Risk-le$limit);if([bool]$row.IsSelected){$selected++}}};Refresh-VSO7GuiCategorizedSurfaceR53VSO -Context $st.Context;Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'RiskBulkResult' -Args @($selected,[string]$st.Label));$st.Popup.IsOpen=$false})
        [void]$stack.Children.Add($b)
    }
    $Context.SelectionPopup=$popup;$popup.IsOpen=$true
}

function Get-VSO7GuiReadOnlyPageMapR69VSO {
    param([Parameter(Mandatory=$true)][ValidateSet('Analysis','Diagnostics','TuningAudit')][string]$Mode)
    switch($Mode){
        # R80: Analysis/Diagnostics must point at workers that implement the structured
        # VSO7.ReadOnlyInventoryResult.v1 contract consumed by the common completion path.
        'Analysis'{return [pscustomobject]@{TitleKey='SystemOverviewTitle';DescKey='SystemOverviewDesc';FunctionName='Get-VSO7GuiAnalysisRowsR52VSO';CompletionTag='Analysis'}}
        'Diagnostics'{return [pscustomobject]@{TitleKey='SystemOverviewTitle';DescKey='SystemOverviewDesc';FunctionName='Get-VSO7GuiDiagnosticsRowsR52VSO';CompletionTag='Diagnostics'}}
        'TuningAudit'{return [pscustomobject]@{TitleKey='TuningTitle';DescKey='TuningDesc';FunctionName='Get-VSO7TuningSanityFindingsVSO';CompletionTag='TuningAudit'}}
    }
}

function Test-VSO7GuiRouteLocalizationR69VSO {
    $keys=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
    foreach($cap in @(Get-VSO7GuiCapabilitiesR44VSO)){[void]$keys.Add([string]$cap.Title);[void]$keys.Add([string]$cap.Desc)}
    foreach($m in @('Analysis','Diagnostics','TuningAudit')){$map=Get-VSO7GuiReadOnlyPageMapR69VSO -Mode $m;[void]$keys.Add([string]$map.TitleKey);[void]$keys.Add([string]$map.DescKey)}
    $missing=New-Object 'Collections.Generic.List[string]'
    foreach($k in $keys){if(-not$script:VSO7GuiStrings.Contains($k)){[void]$missing.Add($k);continue};$row=$script:VSO7GuiStrings[$k];if($null-eq$row-or[string]::IsNullOrWhiteSpace([string]$row.en)-or[string]::IsNullOrWhiteSpace([string]$row.es)){[void]$missing.Add($k)}}
    if($missing.Count){throw ('Missing GUI route localization: '+($missing.ToArray()-join', '))}
    return [pscustomobject]@{Keys=$keys.Count;Missing=0;Result='PASS'}
}

function Get-VSO7GuiSystemOverviewRowsR69VSO {
    $rows=New-Object Collections.ArrayList
    try{$os=CimCmdlets\Get-CimInstance Win32_OperatingSystem -ErrorAction Stop;[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'SystemSection');Item='Windows';Detail=([string]$os.Caption+' · '+[string]$os.Version+' build '+[string]$os.BuildNumber)})}catch{}
    try{$cpu=CimCmdlets\Get-CimInstance Win32_Processor -ErrorAction Stop|Select-Object -First 1;[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'SystemSection');Item='CPU';Detail=[string]$cpu.Name})}catch{}
    try{$ram=Get-RamDiagnostics;[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'SystemSection');Item='RAM';Detail=(Get-VSO7GuiStringVSO 'RamDetected' -Args @($ram.TotalGB,@($ram.Modules).Count))})}catch{}
    try{foreach($g in @(Get-GpuDiagnostics)){[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'SystemSection');Item='GPU';Detail=([string]$g.Name+' · '+(Get-VSO7GuiStringVSO 'DriverLabel')+' '+[string]$g.DriverVersion)})}}catch{}
    try{$d=Get-DiskDiagnostics;[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'SystemSection');Item=(Get-VSO7GuiStringVSO 'Storage');Detail=(Get-VSO7GuiStringVSO 'PhysicalDisksDetected' -Args @(@($d.Physical).Count))})}catch{}
    try{
        $plan=Get-VSO7RecommendedOptimizationPlanVSO -Objective Balanced
        foreach($x in @($plan.Selected)){$f=$x.Feature;[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'FindingsTitle');Item=$(if($script:Language-eq'es'){[string]$f.NameEs}else{[string]$f.NameEn});Detail=(Get-VSO7GuiStringVSO 'RecommendedFinding')})}
        foreach($x in @($plan.AlreadyOptimal)){$f=$x.Feature;[void]$rows.Add([pscustomobject]@{Section=(Get-VSO7GuiStringVSO 'FindingsTitle');Item=$(if($script:Language-eq'es'){[string]$f.NameEs}else{[string]$f.NameEn});Detail=(Get-VSO7GuiStringVSO 'AlreadyOptimalStatus')})}
    }catch{}
    return $rows.ToArray()
}

function Get-VSO7ExtremePresentationCategoryR69VSO {
    param([Parameter(Mandatory=$true)][string]$Id)
    $key=switch -Regex ($Id){
        '^gaming\.'{'ExtremeCategoryGaming';break}
        '^ui\.'{'ExtremeCategoryAppearance';break}
        '^delivery\.'{'ExtremeCategoryDelivery';break}
        '^cleanup\.'{'ExtremeCategoryCleanup';break}
        '^power\.'{'ExtremeCategoryPower';break}
        '^search\.'{'ExtremeCategorySearch';break}
        '^(xbox|telemetry|services)\.'{'ExtremeCategoryServices';break}
        '^virtualization\.'{'ExtremeCategoryVirtualization';break}
        '^security\.'{'ExtremeCategorySecurity';break}
        default{$null}
    }
    if([string]::IsNullOrWhiteSpace([string]$key)){return $null}
    return Get-VSO7GuiStringVSO $key
}

function Update-VSO7GuiExtremeFilterR69VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $q=([string]$Context.Search.Text).Trim();$ri=if($null-ne$Context.Risk){[int]$Context.Risk.SelectedIndex}else{0};$cat=if($null-ne$Context.Category-and$Context.Category.SelectedIndex-gt0){[string]$Context.Category.SelectedItem}else{''}
    foreach($row in @($Context.Rows)){
        $textOk=([string]::IsNullOrWhiteSpace($q)-or[string]$row.Name.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0-or[string]$row.Description.IndexOf($q,[StringComparison]::OrdinalIgnoreCase)-ge0)
        $riskOk=($ri-eq0-or[int]$row.Risk-eq$ri);$catOk=([string]::IsNullOrWhiteSpace($cat)-or[string]$row.Category-ceq$cat)
        $row.Visibility=if($textOk-and$riskOk-and$catOk){'Visible'}else{'Collapsed'}
    }
    Refresh-VSO7GuiCategorizedSurfaceR53VSO -Context $Context
}


function Invoke-VSO7GuiFeatureRowBuildTickR78VSO {
    param([Parameter(Mandatory=$true)]$Timer)
    $c=$Timer.Tag;if($null-eq$c-or$null-eq$c.InitData){try{$Timer.Stop()}catch{};return}
    $d=$c.InitData;$sw=[Diagnostics.Stopwatch]::StartNew();$built=0
    while($d.Index-lt$d.Catalog.Count-and$built-lt24-and$sw.ElapsedMilliseconds-lt12){
        $f=$d.Catalog[$d.Index];$d.Index++;$built++
        $copy=Get-VSO7GuiHumanFeatureCopyR52VSO -Feature $f
        $row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $f -Id ([string]$f.FeatureId) -Name $(if($script:Language-eq'es'){[string]$f.NameEs}else{[string]$f.NameEn}) -Description ([string]$copy.Summary) -Category $(if($script:Language-eq'es'){[string]$f.CategoryEs}else{[string]$f.CategoryEn}) -Risk ([int]$f.Risk) -Restart ([string]$f.RebootRequirement) -Reversible ([bool]$d.Reversibility[[string]$f.FeatureId]) -Status (Get-VSO7GuiStringVSO 'AvailabilityNotChecked') -Why ([string]$copy.Why) -Technical ('FeatureId: '+[string]$f.FeatureId+' · Evidence: '+[string]$f.Evidence+' · Maturity: '+[string]$f.Maturity+' · Requires: '+(@($f.Requires)-join', '))
        [void]$c.Rows.Add($row)
    }
    if($d.Index-ge$d.Catalog.Count){
        $Timer.Stop();$c.InitTimer=$null
        foreach($cat in @($c.Rows.Category|Sort-Object -Unique)){[void]$c.InitCategory.Items.Add([string]$cat)};$c.InitCategory.SelectedIndex=0
        foreach($ctl in @($d.Controls)){if($null-ne$ctl){try{$ctl.IsEnabled=$true}catch{}}}
        Start-VSO7GuiCategorizedBuildR53VSO -Context $c
        Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_MODEL_READY' -NavigationTarget ([string]$c.NavigationTarget) -CacheHit $false -BackgroundLoad $false -Detail ('Rows='+$c.Rows.Count)
    }
}

function Start-VSO7GuiFeatureRowsR78VSO {
    param([Parameter(Mandatory=$true)]$Context,[Parameter(Mandatory=$true)][ValidateSet('Windows','Graphics')][string]$Mode,[Parameter(Mandatory=$true)]$Category,[object[]]$Controls=@())
    [void](Initialize-VSO7GuiReadOnlyResourceCacheR78VSO)
    $catalog=@(Get-VSO7GuiFeatureCatalogR78VSO|Where-Object{[bool]$_.Selectable-and($Mode-ne'Graphics'-or[string]$_.CategoryEn-eq'Graphics & GPU')})
    $Context.Rows.Clear();$Context.InitCategory=$Category;$Context.InitData=[pscustomobject]@{Catalog=$catalog;Index=0;Reversibility=(Get-VSO7GuiFeatureReversibilityMapR52VSO);Controls=@($Controls)}
    foreach($ctl in @($Controls)){if($null-ne$ctl){try{$ctl.IsEnabled=$false}catch{}}}
    $timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds(1);$timer.Tag=$Context;$Context.InitTimer=$timer
    $timer.Add_Tick([System.EventHandler]{param($sender,$e);Invoke-VSO7GuiFeatureRowBuildTickR78VSO -Timer $sender});$timer.Start()
}

function Show-VSO7GuiFeatureSelectorPageVSO {
    param([ValidateSet('Windows','Graphics')][string]$Mode='Windows')
    $navName=$Mode
    Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_CREATE_BEGIN' -NavigationTarget $navName -CacheHit $false -BackgroundLoad $false
    $p=New-VSO7GuiPageR44VSO -Title (Get-VSO7GuiStringVSO $(if($Mode-eq'Graphics'){'GraphicsTitle'}else{'WindowsTitle'})) -Description (Get-VSO7GuiStringVSO $(if($Mode-eq'Graphics'){'GraphicsDesc'}else{'WindowsDesc'}))
    $root=New-Object Windows.Controls.Grid
    foreach($h in @('Auto','*')){$rr=New-Object Windows.Controls.RowDefinition;$rr.Height=$h;[void]$root.RowDefinitions.Add($rr)}
    $controlStack=New-Object Windows.Controls.StackPanel;$controlStack.Margin='0,0,10,8';[void]$root.Children.Add($controlStack)
    [void]$controlStack.Children.Add((New-VSO7GuiTextBlockR44VSO -Text (Get-VSO7GuiStringVSO 'FiltersLabel') -Size 11 -Color '#E3A35D' -Bold -Margin '4,0,0,2'))
    $filters=New-Object Windows.Controls.WrapPanel;[void]$controlStack.Children.Add($filters)
    $search=New-Object Windows.Controls.TextBox;$search.Width=230;$search.Margin='4';$search.ToolTip=Get-VSO7GuiStringVSO 'SearchTweaks';[void]$filters.Children.Add($search)
    $category=New-Object Windows.Controls.ComboBox;$category.Width=190;$category.Margin='4';[void]$category.Items.Add((Get-VSO7GuiStringVSO 'All'));[void]$filters.Children.Add($category)
    $risk=New-Object Windows.Controls.ComboBox;$risk.Width=155;$risk.Margin='4'
    foreach($x in @((Get-VSO7GuiStringVSO 'All');(Get-VSO7GuiStringVSO 'LowRisk');(Get-VSO7GuiStringVSO 'MediumRisk');(Get-VSO7GuiStringVSO 'HighRisk');(Get-VSO7GuiStringVSO 'VeryHighRisk'))){[void]$risk.Items.Add($x)}
