function Initialize-VSO7GuiAppsCatalogR52VSO {
    param([Parameter(Mandatory=$true)]$Context)
    if($Context.Rows.Count-gt0){return}
    $groupObjects=@{
        safe=[pscustomobject]@{Key='safe';Text=(Get-VSO7GuiStringVSO 'AppGroupRecommended');Background='#173D2A';Border='#68C58A';Foreground='#D8F0DF'}
        optional=[pscustomobject]@{Key='optional';Text=(Get-VSO7GuiStringVSO 'AppGroupOptional');Background='#4B3B17';Border='#E2B654';Foreground='#FFE9A8'}
        unsafe=[pscustomobject]@{Key='unsafe';Text=(Get-VSO7GuiStringVSO 'AppGroupNotRecommended');Background='#4C2525';Border='#E16A6A';Foreground='#FFD9D9'}
    }
    $catalog=@(Get-VSO7AppCatalogVSO | Sort-Object @{Expression={switch(([string]$_.Recommendation).ToLowerInvariant()){'safe'{1}'optional'{2}'unsafe'{3}default{2}}}},FriendlyName)
    foreach($a in $catalog){
        $rec=[string]$a.Recommendation
        $recNorm=$rec.ToLowerInvariant();if($recNorm-notin@('safe','optional','unsafe')){$recNorm='optional'}
        $recKey=switch($recNorm){'safe'{'RecommendedApp'}'unsafe'{'NotRecommendedApp'}default{'OptionalApp'}}
        $recText=Get-VSO7GuiStringVSO $recKey
        $rank=switch($recNorm){'safe'{1}'optional'{2}'unsafe'{3}}
        $palette=switch($recNorm){
            'safe'{@('#173D2A','#68C58A','#D8F0DF')}
            'unsafe'{@('#4C2525','#E16A6A','#FFD9D9')}
            default{@('#4B3B17','#E2B654','#FFE9A8')}
        }
        $descProp='Description'+$(if($script:Language-eq'es'){'Es'}else{'En'})
        $desc=if($null-ne$a.PSObject.Properties[$descProp]-and-not[string]::IsNullOrWhiteSpace([string]$a.$descProp)){[string]$a.$descProp}elseif($script:Language-eq'es'){Get-VSO7GuiStringVSO 'AppOptionalDesc' -Args @([string]$a.FriendlyName)}else{[string]$a.Description}
        if([string]::IsNullOrWhiteSpace($desc)){$desc=if($script:Language-eq'es'){Get-VSO7GuiStringVSO 'AppOptionalDesc' -Args @([string]$a.FriendlyName)}else{[string]$a.Description}}
        $row=[pscustomobject]@{
            IsSelected=$false;CanSelect=$true;Id=(Get-VSO7AppCatalogKeyVSO -App $a);Name=[string]$a.FriendlyName;Description=$desc
            Category='Applications';CategoryAccent='#E3A35D';Risk=0;RiskText='';RiskBackground='Transparent';RiskBorder='Transparent';RiskForeground='Transparent';RiskVisibility='Collapsed'
            RestartText='';RestartVisibility='Collapsed';ReversibleText=$(if($script:Language-eq'es'){'Se puede reinstalar'}else{'Can be reinstalled'});ReversibleVisibility='Visible'
            Status=Get-VSO7GuiStringVSO 'InstalledStatusUnknown';StatusVisibility='Visible'
            Why=$(if($recNorm-eq'safe'){if($script:Language-eq'es'){'VSO la considera normalmente prescindible si no la usas.'}else{'VSO considers it normally safe to remove if you do not use it.'}}elseif($recNorm-eq'unsafe'){if($script:Language-eq'es'){'Puede formar parte de funciones que muchos usuarios sí necesitan.'}else{'It may be part of features many users still need.'}}else{if($script:Language-eq'es'){'Depende de si utilizas esta aplicación o función.'}else{'It depends on whether you use this app or feature.'}})
            Technical=('App IDs: '+(@(Get-VSO7AppIdsVSO -App $a)-join', '));Raw=$a;Visibility='Visible';Installed=$null;InstalledText=Get-VSO7GuiStringVSO 'InstalledStatusUnknown'
            AppIdText=(@(Get-VSO7AppIdsVSO -App $a)-join', ');Recommendation=$recNorm;RecommendationText=$recText
            RecommendationBackground=$palette[0];RecommendationBorder=$palette[1];RecommendationForeground=$palette[2]
            RecommendationGroup=$groupObjects[$recNorm];RecommendationGroupIndex=$rank
            Visual=$null;CheckBox=$null
        }
        [void]$Context.Rows.Add($row)
    }
    Write-VSO7GuiPerformanceEventVSO -Name 'CATALOG_READY' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $false -Detail ('Rows='+$Context.Rows.Count)
    Refresh-VSO7GuiPrimaryListR53VSO -Context $Context
    Write-VSO7GuiPerformanceEventVSO -Name 'FIRST_ROWS_VISIBLE' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $false -Detail ('Rows='+$Context.Rows.Count)
    Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_CREATE_END' -NavigationTarget 'Applications' -CacheHit $false -BackgroundLoad $false
    Start-VSO7GuiAppInstalledDetectionR52VSO -Context $Context
}



function Start-VSO7GuiDeferredAppsCatalogR52VSO {
    param([Parameter(Mandatory=$true)]$Context)
    $timer=New-Object Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromMilliseconds(1);$timer.Tag=$Context
    Set-VSO7GuiContextPropertyR53VSO -Context $Context -Name InitTimer -Value $timer
    $timer.Add_Tick([System.EventHandler]{param($sender,$e);$sender.Stop();try{Initialize-VSO7GuiAppsCatalogR52VSO -Context $sender.Tag}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Applications.Catalog'}})
    $timer.Start()
}

