function Show-VSO7GuiPresetPlanPageR52VSO {
    param([Parameter(Mandatory=$true)][ValidateSet('Safe','Gaming','Balanced','Aggressive')][string]$Mode)
    $titleKey=switch($Mode){'Safe'{'SafeTitle'}'Gaming'{'GamingTitle'}'Balanced'{'BalancedTitle'}default{'AggressiveTitle'}}
    $descKey=switch($Mode){'Safe'{'SafeDesc'}'Gaming'{'GamingDesc'}'Balanced'{'BalancedDesc'}default{'AggressiveDesc'}}
    $p=New-VSO7GuiPageR44VSO -Title (Get-VSO7GuiStringVSO $titleKey) -Description (Get-VSO7GuiStringVSO $descKey)
    $plan=Get-VSO7PresetPlanR52VSO -Mode $Mode
    $rows=New-Object Collections.ArrayList;$rev=Get-VSO7GuiFeatureReversibilityMapR52VSO
    foreach($item in @($plan.Items)){
        $f=$item.Raw
        $name=if($null-ne$f){if($script:Language-eq'es'){[string]$f.NameEs}else{[string]$f.NameEn}}else{Get-VSO7GuiStringVSO ([string]$item.NameKey)}
        $copy=if($null-ne$f){Get-VSO7GuiHumanFeatureCopyR52VSO -Feature $f}else{$null}
        $desc=if($null-ne$f){[string]$copy.Summary}else{Get-VSO7GuiStringVSO ([string]$item.ReasonKey)}
        $cat=if($null-ne$f){if($script:Language-eq'es'){[string]$f.CategoryEs}else{[string]$f.CategoryEn}}else{switch([string]$item.OperationId){'EnableGameMode'{'Gaming'}'DisableBackgroundGameCapture'{'Gaming'}'SetHighPerformanceIfSafe'{if($script:Language-eq'es'){'CPU y energía'}else{'CPU & Power'}}'ApplyAggressiveVisualSettings'{if($script:Language-eq'es'){'Apariencia'}else{'Appearance'}}default{if($script:Language-eq'es'){'Limpieza'}else{'Cleanup'}}}}
        $restart=if($null-ne$f){[string]$f.RebootRequirement}else{[string]$item.Restart}
        $reversible=if($null-ne$f){[bool]$rev[[string]$f.FeatureId]}else{[bool]$item.Reversible}
        $rowId=if($null-ne$f-and-not[string]::IsNullOrWhiteSpace([string]$f.FeatureId)){[string]$f.FeatureId}else{[string]$item.OperationId}
        $status=if([bool]$plan.EditableSelection){$(if($script:Language-eq'es'){'Puedes desmarcarlo'}else{'You can unselect it'})}else{$(if($script:Language-eq'es'){'Incluido en este modo'}else{'Included in this mode'})}
        $row=ConvertTo-VSO7GuiUnifiedRowR52VSO -InputObject $item -Id $rowId -Name $name -Description $desc -Category $cat -Risk ([int]$item.Risk) -Restart $restart -Reversible $reversible -Selected $true -CanSelect ([bool]$plan.EditableSelection) -Status $status -Why $(if($null-ne$copy){[string]$copy.Why}else{$desc}) -Technical ('Mode: '+$Mode+' · Selection index: '+[string]$item.SelectionIndex)
        $row|Add-Member -NotePropertyName SelectionIndex -NotePropertyValue ([int]$item.SelectionIndex)
        [void]$rows.Add($row)
    }
    $surface=New-VSO7GuiCategorizedTweakSurfaceR53VSO -Rows $rows -NavigationTarget $Mode
    if($rows.Count-le5){$surface.Root.MaxWidth=820;$surface.Root.HorizontalAlignment='Center';$surface.Root.VerticalAlignment='Center'}
    [void]$p.Body.Children.Add($surface.Root)
    if(-not[bool]$plan.EditableSelection){[void]$p.Header.Children.Add((New-VSO7GuiTextBlockR44VSO -Text ($(if($script:Language-eq'es'){'La selección está bloqueada porque este modo ejecuta exactamente el mismo plan que CLI.'}else{'Selection is locked because this mode executes exactly the same plan as CLI.'})) -Size 11 -Color '#BDA98D' -Margin '0,4,0,0'))}
    $count=New-VSO7GuiTextBlockR44VSO -Text '' -Size 12 -Color '#C9B89F';[void]$p.Actions.Children.Add($count)
    $apply=New-VSO7GuiButtonR44VSO -Text (Get-VSO7GuiStringVSO 'Apply') -Kind $(if($Mode-eq'Aggressive'){'Danger'}else{'Primary'});[void]$p.Actions.Children.Add($apply)
    $ctx=$surface.Context
    Set-VSO7GuiContextPropertyR53VSO -Context $ctx -Name Count -Value $count
    Set-VSO7GuiContextPropertyR53VSO -Context $ctx -Name Mode -Value $Mode
    Set-VSO7GuiContextPropertyR53VSO -Context $ctx -Name Editable -Value ([bool]$plan.EditableSelection)
    $apply.DataContext=$ctx;Update-VSO7GuiUnifiedSelectedCountR52VSO -Context $ctx
