function Get-VSO7GuiRestorePointInfoR69VSO {
    $latest=Get-LatestRestorePoint
    if($null-eq$latest){return [pscustomobject]@{Exists=$false;Description='';Created='';AgeHours=-1}}
    $date=Convert-RestorePointDate -RestorePoint $latest;$age=[math]::Max(0,((Get-Date)-$date).TotalHours)
    return [pscustomobject]@{Exists=$true;Description=[string]$latest.Description;Created=$date.ToString('g');AgeHours=[math]::Round($age,1)}
}


function Invoke-VSO7GuiRestorePointOperationR78VSO {
    $before=$null;$beforeSequence=-1;$beforeRecent=$false
    try{$before=Get-LatestRestorePoint}catch{}
    if($null-ne$before){try{$beforeSequence=[int64]$before.SequenceNumber}catch{};try{$beforeRecent=((Get-Date)-(Convert-RestorePointDate -RestorePoint $before)).TotalHours-le24}catch{}}
    $ok=[bool](New-SafeRestorePoint)
    if(-not$ok){return [pscustomobject]@{Schema='VSO7.RestorePointResult.v1';Status='Failed';Success=$false;Created=$false;ExistingRecent=$false;SequenceNumber=$null;CreatedAt=''}}
    $after=$null;try{$after=Get-LatestRestorePoint}catch{}
    if($null-eq$after){return [pscustomobject]@{Schema='VSO7.RestorePointResult.v1';Status='Failed';Success=$false;Created=$false;ExistingRecent=$false;SequenceNumber=$null;CreatedAt=''}}
    $afterSequence=try{[int64]$after.SequenceNumber}catch{-1};$afterDate=try{Convert-RestorePointDate -RestorePoint $after}catch{$null}
    $wasCreated=(-not$beforeRecent-and$afterSequence-ne$beforeSequence)
    return [pscustomobject]@{Schema='VSO7.RestorePointResult.v1';Status=$(if($wasCreated){'Created'}else{'ExistingRecent'});Success=$true;Created=[bool]$wasCreated;ExistingRecent=[bool](-not$wasCreated);SequenceNumber=$afterSequence;CreatedAt=$(if($null-ne$afterDate){$afterDate.ToString('o')}else{''})}
}

