    $summary=New-VSO7GuiTextBlockR44VSO -Text '' -Size 13 -Color '#D8C7AE' -Margin '0,0,0,8'
    [void]$root.Children.Add($summary)
    $rows=New-Object Collections.ArrayList
    $surface=New-VSO7GuiPrimaryListSurfaceR53VSO -Rows $rows -NavigationTarget 'Profiles' -ShowDetail
    [Windows.Controls.Grid]::SetRow($surface.Root,1);[void]$root.Children.Add($surface.Root);[void]$p.Body.Children.Add($root)
    $export=New-VSO7GuiButtonR44VSO -Text (Get-VSO7GuiStringVSO 'ExportLast')
