    foreach($b in @($export,$import,$apply)){[void]$p.Actions.Children.Add($b)}
    $ctx=$surface.Context
    Set-VSO7GuiContextPropertyR53VSO -Context $ctx -Name CurrentProfile -Value $null
    Set-VSO7GuiContextPropertyR53VSO -Context $ctx -Name Summary -Value $summary
    Set-VSO7GuiContextPropertyR53VSO -Context $ctx -Name Apply -Value $apply
    foreach($ctl in @($export,$import,$apply)){$ctl.DataContext=$ctx}
    $export.Add_Click([Windows.RoutedEventHandler]{param($sender,$e);try{$last=Get-VSO7LastAppliedSelectionR76VSO;if($null-eq$last){throw (Get-VSO7GuiStringVSO 'NoAppliedSession')};$path=Get-VSO7ConfigurationProfilePathVSO -Mode Save;if([string]::IsNullOrWhiteSpace($path)){return};$saved=Save-VSO7ConfigurationProfileVSO -Path $path -Features @($last.Features) -Apps @($last.Apps);Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'ProfileSaved' -Args @($saved))}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Profiles.Export'}})
    $import.Add_Click([Windows.RoutedEventHandler]{param($sender,$e);$c=$sender.DataContext;try{$path=Get-VSO7ConfigurationProfilePathVSO -Mode Open;if([string]::IsNullOrWhiteSpace($path)){return};$c.CurrentProfile=Read-VSO7ConfigurationProfileVSO -Path $path;Update-VSO7GuiProfilePreviewVSO -Context $c -Profile $c.CurrentProfile;$c.Apply.IsEnabled=$true}catch{$c.CurrentProfile=$null;$c.Apply.IsEnabled=$false;Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Profiles.Import'}})
    $apply.Add_Click([Windows.RoutedEventHandler]{param($sender,$e);$c=$sender.DataContext;try{$currentProfile=$c.CurrentProfile;if($null-eq$currentProfile){throw (Get-VSO7GuiStringVSO 'PreviewFirst')};$catalog=@(Get-VSO7FeatureCatalogVSO);$notApplicable=@();$featuresToApply=@();$maxRisk=0;foreach($id in @($currentProfile.Features)){$f=$catalog|Where-Object{[string]$_.FeatureId-ceq$id}|Select-Object -First 1;$a=Get-VSO7FeatureApplicabilityVSO -Feature $f;if(-not[bool]$a.Applicable-and-not[bool]$a.AlreadySatisfied){$notApplicable+=,$id};if([bool]$a.Applicable){$featuresToApply+=,$id};if([int]$f.Risk-gt$maxRisk){$maxRisk=[int]$f.Risk}};if($notApplicable.Count){throw (Get-VSO7GuiStringVSO 'ProfileNotApplicable' -Args @([string]::Join(', ',$notApplicable)))};if(-not(Show-VSO7GuiConfirmVSO (Get-VSO7GuiStringVSO 'ConfirmApply'))){return};if(-not(Confirm-VSO7HighRiskFeatureSelectionVSO -FeatureIds @($currentProfile.Features) -Catalog $catalog)){return};if(@($currentProfile.Apps).Count-and-not(Show-VSO7GuiConfirmVSO (Get-VSO7GuiStringVSO 'ConfirmApps'))){return};if(-not(Require-RestorePoint)){return};$ok=$true;if($featuresToApply.Count){$ok=[bool](Invoke-VSO7NativeTweaksVSO -Features $featuresToApply)};if($ok-and@($currentProfile.Apps).Count){$ok=[bool](Invoke-VSO7NativeTweaksVSO -Apps @($currentProfile.Apps))};if(-not$ok){throw (Get-VSO7GuiStringVSO 'ProfileApplyFailed')};$persistWarning=$false;try{[void](Save-VSO7LastAppliedSelectionR76VSO -Features @($currentProfile.Features) -Apps @($currentProfile.Apps))}catch{$persistWarning=$true;try{Write-VSO7Log ('Profile applied but last-selection persistence failed: '+$_.Exception.Message) 'WARN'}catch{}};try{[void](Set-VSO7LanguageR76VSO -Language ([string]$currentProfile.Preferences.Language) -Persist)}catch{$persistWarning=$true;try{Write-VSO7Log ('Profile applied but language preference persistence failed: '+$_.Exception.Message) 'WARN'}catch{}};if($persistWarning){Set-VSO7GuiStatusVSO $(if($script:Language-eq'es'){'Perfil aplicado; alguna preferencia no pudo guardarse. Revisa el log.'}else{'Profile applied; a preference could not be persisted. Check the log.'})}else{Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'ProfileApplied')}}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Profiles.Apply'}})
    Set-VSO7GuiPageR44VSO $p
}

function Stop-VSO7GuiGamingSessionMonitorVSO {
    param([switch]$RestoreState)
    $timer=$script:GuiGamingSessionTimer;$handler=$script:GuiGamingSessionTimerHandler
    if($null-ne$timer){try{$timer.Stop()}catch{};if($null-ne$handler){try{$timer.Remove_Tick($handler)}catch{}}}
    $script:GuiGamingSessionTimer=$null;$script:GuiGamingSessionTimerHandler=$null;$script:GuiGamingSessionIdentity=$null
    if($RestoreState-and(Test-Path -LiteralPath $script:GamingSessionStateFile -PathType Leaf)){return [bool](Restore-VSO7GamingSessionState)}
    return $true
}

function Start-VSO7GuiGamingSessionMonitorVSO {
    param([Parameter(Mandatory=$true)]$GameIdentity)
    if($null-ne$script:GuiGamingSessionTimer){throw (Get-VSO7GuiStringVSO 'GamingSessionAlreadyActive')}
    $timer=New-Object Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromSeconds(2)
    $identity=$GameIdentity
    $script:GuiGamingSessionIdentity=$GameIdentity
    $handler=[System.EventHandler]{
        param($sender,$eventArgs)
        try{
            $identity=$script:GuiGamingSessionIdentity;$alive=$false;$proc=$null
            try{$proc=Get-Process -Id ([int]$identity.Id) -ErrorAction SilentlyContinue;if($null-ne$proc){$alive=[bool](Test-VSO7ProcessIdentityMatch -Expected $identity -Process $proc)}}catch{$alive=$false}finally{if($null-ne$proc){Close-VSO7ProcessObjectVSO -Process $proc}}
            if(-not$alive){$ok=Stop-VSO7GuiGamingSessionMonitorVSO -RestoreState;if($ok){Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'GamingSessionRestored')}else{Set-VSO7GuiStatusVSO (Get-VSO7GuiStringVSO 'GamingSessionRestoreFailed')}}
        }catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'GamingSession.Timer'}
    }
    $script:GuiGamingSessionTimer=$timer;$script:GuiGamingSessionTimerHandler=$handler
    $timer.Add_Tick($handler);$timer.Start()
}



