function Show-VSO7GuiHomeVSO {
    $script:GuiCurrentPageToken=[guid]::NewGuid().ToString('N');if($null-ne$script:GuiWelcomeView){$script:GuiWelcomeView.Visibility='Collapsed'};if($null-eq$script:GuiHomeView){return}
    $script:GuiActionView.Visibility='Collapsed';$script:GuiHomeView.Visibility='Visible';$script:GuiBackButton.Visibility='Collapsed';Set-VSO7GuiStatusVSO ''
    if([bool]$script:GuiHomeBuilt){Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_SHOW' -NavigationTarget 'Home' -CacheHit $true -BackgroundLoad $false;return}
    Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_CREATE_BEGIN' -NavigationTarget 'Home' -CacheHit $false -BackgroundLoad $false
    if($null-ne$script:GuiHomeCards){$script:GuiHomeCards.Children.Clear()}
    foreach($cap in @(Get-VSO7GuiCapabilitiesR44VSO|Where-Object{$_['HomeVisible']-ne$false})){$button=New-Object Windows.Controls.Button;$button.Width=335;$button.Height=145;$button.Margin='7';$button.Padding='14';$button.Tag=[string]$cap.Action;try{$button.Style=$script:GuiWindow.FindResource('CardButton')}catch{};$sp=New-Object Windows.Controls.StackPanel;[void]$sp.Children.Add((New-VSO7GuiTextBlockR44VSO -Text (Get-VSO7GuiStringVSO $cap.Title) -Size 18 -Color '#FFF4E0' -Bold));[void]$sp.Children.Add((New-VSO7GuiBadgeR44VSO -Key ([string]$cap.Badge)));[void]$sp.Children.Add((New-VSO7GuiTextBlockR44VSO -Text (Get-VSO7GuiStringVSO $cap.Desc) -Size 12 -Color '#C9B89F'));$button.Content=$sp;if($null-ne$script:GuiCardClickHandler){$button.Add_Click($script:GuiCardClickHandler)}else{$button.Add_Click([Windows.RoutedEventHandler]{param($s,$e);Show-VSO7GuiPageByActionVSO -Action ([string]$s.Tag)})};if($null-ne$script:GuiCardButtons){[void]$script:GuiCardButtons.Add($button)};[void]$script:GuiHomeCards.Children.Add($button)}
    $script:GuiHomeBuilt=$true;Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_CREATE_END' -NavigationTarget 'Home' -CacheHit $false -BackgroundLoad $false;Write-VSO7GuiPerformanceEventVSO -Name 'PAGE_INTERACTIVE' -NavigationTarget 'Home' -CacheHit $false -BackgroundLoad $false
}


function Show-VSO7GuiPageByActionVSO {
    param([Parameter(Mandatory=$true)][string]$Action)
    $script:GuiCurrentPageToken=[guid]::NewGuid().ToString('N');Write-VSO7GuiPerformanceEventVSO -Name 'NAV_CLICK' -NavigationTarget $Action;Write-VSO7GuiPerformanceEventVSO -Name 'NAVIGATION_BEGIN' -NavigationTarget $Action
    $cacheable=($Action-in@('Score','Benchmark','Analysis','Diagnostics','TuningAudit','Recommended','Safe','GamingSession','Gaming','Balanced','Aggressive','Extreme','Recovery','Windows','Graphics','Apps','Tools','Language'))
    $hit=($cacheable-and$null-ne$script:GuiPageCache-and$script:GuiPageCache.ContainsKey($Action));Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_CACHE_LOOKUP' -NavigationTarget $Action -CacheHit $hit -BackgroundLoad $false
    try{
        if($hit){$script:GuiPageHost.Content=$script:GuiPageCache[$Action];$script:GuiHomeView.Visibility='Collapsed';$script:GuiActionView.Visibility='Visible';$script:GuiBackButton.Visibility='Visible';if($Action-eq'Apps'-and$null-ne$script:GuiApplicationsPageContext){$script:GuiApplicationsPageContext.PageToken=[string]$script:GuiCurrentPageToken;Start-VSO7GuiAppInstalledDetectionR52VSO -Context $script:GuiApplicationsPageContext};if($Action-eq'Recovery'-and$null-ne$script:GuiRecoveryPageContext-and[bool]$script:GuiRecoveryPageContext.Refresh.IsEnabled){Start-VSO7GuiRecoveryRefreshR52VSO -Context $script:GuiRecoveryPageContext};Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_SHOW' -NavigationTarget $Action -CacheHit $true -BackgroundLoad ($Action-eq'Apps');Write-VSO7GuiPerformanceEventVSO -Name 'PAGE_INTERACTIVE' -NavigationTarget $Action -CacheHit $true -BackgroundLoad ($Action-eq'Apps');return}
        switch($Action){'Score'{Show-VSO7GuiScorePageVSO}'Benchmark'{Show-VSO7GuiBenchmarkPageVSO}'Analysis'{Show-VSO7GuiReadOnlyPageVSO Analysis}'Diagnostics'{Show-VSO7GuiReadOnlyPageVSO Diagnostics}'TuningAudit'{Show-VSO7GuiReadOnlyPageVSO TuningAudit}'Recommended'{Show-VSO7GuiRecommendedPageVSO}'Safe'{Show-VSO7GuiSimpleSelectorPageVSO Safe}'GamingSession'{Show-VSO7GuiGamingSessionPageVSO}'Gaming'{Show-VSO7GuiSimpleSelectorPageVSO Gaming}'Balanced'{Show-VSO7GuiPresetPageVSO Balanced}'Aggressive'{Show-VSO7GuiPresetPageVSO Aggressive}'Extreme'{Show-VSO7GuiExtremePageVSO}'RestorePoint'{Show-VSO7GuiRestorePointPageVSO}'Recovery'{Show-VSO7GuiRecoveryPageVSO}'Windows'{Show-VSO7GuiFeatureSelectorPageVSO Windows}'Graphics'{Show-VSO7GuiFeatureSelectorPageVSO Graphics}'Apps'{Show-VSO7GuiAppsPageVSO}'Tools'{Show-VSO7GuiToolsPageVSO}'Language'{Show-VSO7GuiLanguagePageVSO}default{throw (Get-VSO7GuiStringVSO 'UnknownGuiAction' -Args @($Action))}}
        if($cacheable-and$null-ne$script:GuiPageHost.Content){$script:GuiPageCache[$Action]=$script:GuiPageHost.Content};Write-VSO7GuiPerformanceEventVSO -Name 'VIEW_SHOW' -NavigationTarget $Action -CacheHit $false -BackgroundLoad ($Action-eq'Apps')
    }catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context ('PageRouter.'+$Action) -ReturnHome}
}

function Invoke-VSO7GuiActionVSO { param([Parameter(Mandatory=$true)][string]$Action,[string]$Title='');Show-VSO7GuiPageByActionVSO -Action $Action }

function Repair-VSO7GuiWindowBoundsVSO {
    param([Parameter(Mandatory=$true)]$Window)
    try{
        if([double]::IsNaN($Window.Left)-or[double]::IsNaN($Window.Top)){return}
        $l=[Windows.SystemParameters]::VirtualScreenLeft;$t=[Windows.SystemParameters]::VirtualScreenTop;$r=$l+[Windows.SystemParameters]::VirtualScreenWidth;$b=$t+[Windows.SystemParameters]::VirtualScreenHeight
        if(($Window.Left+$Window.ActualWidth)-lt$l -or $Window.Left-gt$r -or ($Window.Top+$Window.ActualHeight)-lt$t -or $Window.Top-gt$b){$Window.WindowStartupLocation='CenterScreen';$Window.Left=[double]::NaN;$Window.Top=[double]::NaN}
    }catch{}
}

function Get-VSO7MainWindowInteropStateR52VSO {
    param([Parameter(Mandatory=$true)]$Window,[string]$Stage='')
    $hwnd=[IntPtr]::Zero;$isWindow=$false;$visible=$false;$exStyle=[int64]0
    try{$hwnd=(New-Object Windows.Interop.WindowInteropHelper($Window)).Handle}catch{}
    if($hwnd-ne[IntPtr]::Zero-and('VSO7.Interop.Foreground' -as[type])){
        try{$isWindow=[bool][VSO7.Interop.Foreground]::IsWindow($hwnd)}catch{}
        try{$visible=[bool][VSO7.Interop.Foreground]::IsWindowVisible($hwnd)}catch{}
        try{$exStyle=[int64][VSO7.Interop.Foreground]::GetWindowLongPtr($hwnd,[VSO7.Interop.Foreground]::GWL_EXSTYLE).ToInt64()}catch{}
    }
    $ownerNull=($null-eq$Window.Owner)
    [pscustomobject]@{
        Stage=$Stage;Handle=[int64]$hwnd.ToInt64();IsWindow=$isWindow;IsWindowVisible=$visible;ExStyle=$exStyle
        IsForeground=($hwnd-ne[IntPtr]::Zero-and([VSO7.Interop.Foreground]::GetForegroundWindow()-eq$hwnd))
        WsExAppWindow=(($exStyle-band[int64][VSO7.Interop.Foreground]::WS_EX_APPWINDOW)-ne0)
        WsExToolWindow=(($exStyle-band[int64][VSO7.Interop.Foreground]::WS_EX_TOOLWINDOW)-ne0)
        ShowInTaskbar=[bool]$Window.ShowInTaskbar;ShowActivated=[bool]$Window.ShowActivated;WindowState=[string]$Window.WindowState
        Visibility=[string]$Window.Visibility;OwnerNull=$ownerNull;Topmost=[bool]$Window.Topmost;AllowsTransparency=[bool]$Window.AllowsTransparency;WindowStyle=[string]$Window.WindowStyle
    }
}

function Write-VSO7MainWindowInteropStateR52VSO {
    param([Parameter(Mandatory=$true)]$Window,[Parameter(Mandatory=$true)][string]$Stage)
    $state=Get-VSO7MainWindowInteropStateR52VSO -Window $Window -Stage $Stage
    $detail=('Handle={0};IsWindow={1};Visible={2};Foreground={3};ExStyle=0x{4:X};APPWINDOW={5};TOOLWINDOW={6};ShowInTaskbar={7};ShowActivated={8};WindowState={9};Visibility={10};OwnerNull={11};Topmost={12};WindowStyle={13};AllowsTransparency={14}'-f $state.Handle,$state.IsWindow,$state.IsWindowVisible,$state.IsForeground,$state.ExStyle,$state.WsExAppWindow,$state.WsExToolWindow,$state.ShowInTaskbar,$state.ShowActivated,$state.WindowState,$state.Visibility,$state.OwnerNull,$state.Topmost,$state.WindowStyle,$state.AllowsTransparency)
    try{Write-VSO7LifecycleCheckpointVSO -Name $Stage -Detail $detail}catch{}
    try{Write-VSO7GuiPerformanceEventVSO -Name $Stage -Detail $detail}catch{}
    return $state
}

function Configure-VSO7MainWindowBeforeShowR52VSO {
    param([Parameter(Mandatory=$true)]$Window)
    if($Window.IsLoaded){throw 'MainWindow pre-show configuration must run before the window is shown.'}
    $Window.Owner=$null
    $Window.ShowInTaskbar=$true
    $Window.ShowActivated=$true
    $Window.WindowState=[Windows.WindowState]::Normal
    $Window.Topmost=$false
    $Window.AllowsTransparency=$false
    $Window.WindowStyle=[Windows.WindowStyle]::SingleBorderWindow
    Repair-VSO7GuiWindowBoundsVSO -Window $Window
    Write-VSO7LifecycleCheckpointVSO -Name 'MAINWINDOW_PRESHOW_CONFIGURED' -Detail 'Owner=null;ShowInTaskbar=True;ShowActivated=True;WindowState=Normal;Topmost=False'
}

function Activate-VSO7MainWindowAfterShowR52VSO {
    param([Parameter(Mandatory=$true)]$Window)
    try{
        if(-not$Window.IsLoaded){return}
        Repair-VSO7GuiWindowBoundsVSO -Window $Window
        if([Windows.WindowState]$Window.WindowState-eq[Windows.WindowState]::Minimized){$Window.WindowState=[Windows.WindowState]::Normal}
        [void]$Window.Activate()
        $state=Write-VSO7MainWindowInteropStateR52VSO -Window $Window -Stage 'WINDOW_TASKBAR_READY'
        if(-not$state.IsWindow-or-not$state.IsWindowVisible-or$state.WsExToolWindow-or-not$state.ShowInTaskbar-or-not$state.OwnerNull){
            throw 'MainWindow post-show taskbar contract is invalid.'
        }
        return $state
    }catch{try{Write-VSO7Log ('Initial WPF activation request failed: '+$_.Exception.Message) 'WARN'}catch{};return $null}
}

function Show-VSO7Gui {

    param(
        [switch]$SmokeOnly,
        [ValidateSet('CloseWindow','CloseButton','StartHome','NavigationMatrix','Taskbar','PerformanceMatrix','CallbackMatrix')][string]$SmokeAction='CloseWindow'
    )

    try{
        Write-VSO7LifecycleCheckpointVSO -Name 'GUI_ENTER'
        if([bool]$script:TranscriptActive){ Stop-VSO7TranscriptVSO }
        Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase -ErrorAction Stop
        $script:GuiMode=$true
        [void](Initialize-VSO7GuiReadOnlyResourceCacheR78VSO)

        if(-not('VSO7.Interop.Foreground' -as[type])){
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace VSO7.Interop {
    public static class Foreground {
        public const int GWL_EXSTYLE = -20;
        public const long WS_EX_TOOLWINDOW = 0x00000080L;
        public const long WS_EX_APPWINDOW = 0x00040000L;
        [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
        [DllImport("user32.dll")] public static extern bool IsWindow(IntPtr hWnd);
        [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
        [DllImport("user32.dll", EntryPoint="GetWindowLong")] private static extern int GetWindowLong32(IntPtr hWnd, int nIndex);
        [DllImport("user32.dll", EntryPoint="GetWindowLongPtr")] private static extern IntPtr GetWindowLongPtr64(IntPtr hWnd, int nIndex);
        public static IntPtr GetWindowLongPtr(IntPtr hWnd, int nIndex) { return IntPtr.Size == 8 ? GetWindowLongPtr64(hWnd,nIndex) : new IntPtr(GetWindowLong32(hWnd,nIndex)); }
    }
}
'@ -ErrorAction Stop
        }

