"@
        $reader=New-Object System.Xml.XmlNodeReader $xaml
        $window=[Windows.Markup.XamlReader]::Load($reader)
        if($null-eq$window){throw 'XamlReader returned a null R52 GUI window.'}
        [void](Set-VSO7ResponsiveWindowBoundsVSO -Window $window -PreferredWidth 1220 -PreferredHeight 820 -BaseMinWidth 900 -BaseMinHeight 620)

        $script:GuiWindow=$window
        $script:GuiWelcomeView=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'WelcomeView'
        $script:GuiWelcomeLogo=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'WelcomeLogo'
        $script:GuiWelcomeStartButton=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'WelcomeStart'
        $welcomeTitle=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'WelcomeTitle'
        $welcomeSubtitle=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'WelcomeSubtitle'
        $script:GuiHomeView=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'HomeView'
        $script:GuiActionView=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'ActionView'
        $script:GuiHomeCards=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'Cards'
        $script:GuiPageHost=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'PageHost'
        $script:GuiStatusText=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'StatusText'
        $script:GuiBackButton=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'Back'
        $homeClose=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'HomeClose'
        $actionClose=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'ActionClose'
        $homeSubtitle=Get-VSO7RequiredGuiControlVSO -Window $window -Name 'HomeSubtitle'
        $window.Title=Get-VSO7GuiStringVSO 'AppTitle'
        $welcomeTitle.Text=Get-VSO7GuiStringVSO 'WelcomeTitle'
        $welcomeSubtitle.Text=Get-VSO7GuiStringVSO 'WelcomeSubtitle'
        $script:GuiWelcomeStartButton.Content=Get-VSO7GuiStringVSO 'Start'
        $homeSubtitle.Text=Get-VSO7GuiStringVSO 'HomeSubtitle'
        $homeClose.Content=Get-VSO7GuiStringVSO 'Close'
        $actionClose.Content=Get-VSO7GuiStringVSO 'Close'
        $script:GuiBackButton.Content=Get-VSO7GuiStringVSO 'Back'
        $script:GuiBackButton.Visibility='Collapsed'
        if(-not$SmokeOnly-or[string]$SmokeAction-in@('Taskbar','PerformanceMatrix')){
            Configure-VSO7MainWindowBeforeShowR52VSO -Window $window
            Write-VSO7LifecycleCheckpointVSO -Name 'GUI_CONSTRUCTION_BEGIN'
            [void](Write-VSO7MainWindowInteropStateR52VSO -Window $window -Stage 'WINDOW_PRE_SHOW')
        }

        $script:GuiCardButtons=New-Object 'Collections.Generic.List[object]'
        $script:GuiRuntimeCallbackErrors=New-Object 'Collections.Generic.List[object]'
        $script:GuiNavigationSmokeResults=$null
        $script:GuiEventDelegateRuntimeResults=$null
        $script:GuiSmokeFailFast=([bool]$SmokeOnly-and[string]$SmokeAction-ne'NavigationMatrix');$script:GuiSuppressErrorDialogs=$false;$script:GuiErrorBoundarySmokePassed=$false

        $windowContext=[pscustomobject]@{Window=$window;ForegroundEnabled=(-not[bool]$SmokeOnly-or[string]$SmokeAction-in@('Taskbar','PerformanceMatrix'))}
        $window.DataContext=$windowContext;$homeClose.DataContext=$windowContext;$actionClose.DataContext=$windowContext;$script:GuiBackButton.DataContext=$windowContext;$script:GuiWelcomeStartButton.DataContext=$windowContext

        $script:GuiCardClickHandler=[Windows.RoutedEventHandler]{
            param($sender,$eventArgs)
            try{if($null-eq$sender-or$null-eq$sender.Tag){return};Show-VSO7GuiPageByActionVSO -Action ([string]$sender.Tag)}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Home.CardClick' -ReturnHome}
        }
        $script:GuiWelcomeStartHandler=[Windows.RoutedEventHandler]{param($sender,$eventArgs);try{Show-VSO7GuiHomeVSO}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Welcome.Start'}}
        $script:GuiWelcomeStartButton.Add_Click($script:GuiWelcomeStartHandler)
        if($SmokeOnly){
            if(-not(Test-VSO7EmbeddedWelcomeLogoVSO -LogoControl $script:GuiWelcomeLogo)){throw 'R80 embedded Welcome logo definition runtime contract failed.'}
            if([string]::IsNullOrWhiteSpace([string]$welcomeTitle.Text)-or[string]::IsNullOrWhiteSpace([string]$welcomeSubtitle.Text)-or[string]::IsNullOrWhiteSpace([string]$script:GuiWelcomeStartButton.Content)){throw 'R80 Welcome title/subtitle/Start runtime contract failed.'}
        }
        Show-VSO7GuiWelcomeVSO

        $guiDispatcher=$window.Dispatcher
        $script:GuiLifecycleDispatcher=$guiDispatcher
        $backHandler=[Windows.RoutedEventHandler]{param($sender,$eventArgs);try{Show-VSO7GuiHomeVSO}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Navigation.Back'}}
        $closeHandler=[Windows.RoutedEventHandler]{param($sender,$eventArgs);try{$c=$sender.DataContext;if($null-eq$c-or$null-eq$c.Window){throw 'R80 GUI callback has no stable Window context.'};Write-VSO7LifecycleCheckpointVSO -Name 'GUI_CLOSE_REQUESTED' -Detail 'InternalCloseButton';$c.Window.Close()}catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Window.CloseButton'}}
        $loadedHandler=[Windows.RoutedEventHandler]{
            param($sender,$eventArgs)
            try{
                [void](Write-VSO7MainWindowInteropStateR52VSO -Window $sender -Stage 'WINDOW_HWND_CREATED')
                [void](Write-VSO7MainWindowInteropStateR52VSO -Window $sender -Stage 'WINDOW_LOADED')
                Write-VSO7EarlyStartupTimelineVSO -Name 'GUI_HWND'
                Write-VSO7EarlyStartupTimelineVSO -Name 'GUI_SHOW'
                $c=$sender.DataContext
                if($null-ne$c-and[bool]$c.ForegroundEnabled){[void](Activate-VSO7MainWindowAfterShowR52VSO -Window $sender)}
                [void](Write-VSO7MainWindowInteropStateR52VSO -Window $sender -Stage 'WINDOW_VISIBLE')
            }catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Window.Loaded'}
        }
        $contentRenderedHandler=[System.EventHandler]{
            param($sender,$eventArgs)
            try{
                Write-VSO7LifecycleCheckpointVSO -Name 'GUI_CONTENT_RENDERED'
                [void](Write-VSO7MainWindowInteropStateR52VSO -Window $sender -Stage 'WINDOW_CONTENT_RENDERED')
                $sender.UpdateLayout()
                if(-not(Test-VSO7EmbeddedWelcomeLogoVSO -LogoControl $script:GuiWelcomeLogo -RequireRenderedArea)){throw 'R80 embedded Welcome logo rendered-area contract failed.'}
                Write-VSO7GuiPerformanceEventVSO -Name 'WELCOME_VISIBLE'
                Write-VSO7EarlyStartupTimelineVSO -Name 'WELCOME_VISIBLE'
                Write-VSO7GuiPerformanceEventVSO -Name 'WELCOME_INTERACTIVE'
                Write-VSO7EarlyStartupTimelineVSO -Name 'WELCOME_INTERACTIVE'
                [void](Write-VSO7MainWindowInteropStateR52VSO -Window $sender -Stage 'WINDOW_INTERACTIVE')
            }catch{Invoke-VSO7GuiCallbackFailureVSO -ErrorRecord $_ -Context 'Window.ContentRendered'}
        }
        $closingHandler=[ComponentModel.CancelEventHandler]{param($sender,$eventArgs);try{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_CLOSE_REQUESTED' -Detail 'Window.Closing'}catch{}}
        $closedHandler=[System.EventHandler]{param($sender,$eventArgs);try{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_CLOSED_EVENT'}catch{};try{if($null-ne$script:GuiNavigationProbeState-and-not[bool]$script:GuiNavigationProbeState.Completed){$script:ProcessExitCode=1;Write-VSO7GuiNavigationProbeHeartbeatVSO -Phase 'WINDOW_CLOSED_BEFORE_COMPLETION' -CurrentAction ([string]$script:GuiNavigationProbeState.CurrentAction) -Result 'INCOMPLETE' -FatalError 'MainWindow closed before NavigationMatrix reached its terminal report.';$script:GuiNavigationProbeState.Completed=$true}}catch{};try{if($null-ne$script:GuiMainFrameR52){$script:GuiMainFrameR52.Continue=$false}}catch{}}

        $script:GuiBackButton.Add_Click($backHandler)
        $homeClose.Add_Click($closeHandler);$actionClose.Add_Click($closeHandler)
        $window.Add_Loaded($loadedHandler);$window.Add_ContentRendered($contentRenderedHandler);$window.Add_Closing($closingHandler);$window.Add_Closed($closedHandler)

        $smokeDelegate=$null
        if($SmokeOnly){
            if([string]$SmokeAction-notin@('Taskbar','PerformanceMatrix')){$window.Opacity=0;$window.ShowActivated=$false;$window.ShowInTaskbar=$false}
            $script:GuiSmokeContext=[pscustomobject]@{Window=$window;Close=$homeClose;Mode=[string]$SmokeAction;Start=$script:GuiWelcomeStartButton;Home=$script:GuiHomeView;Welcome=$script:GuiWelcomeView}
            if([string]$SmokeAction-eq'NavigationMatrix'){
                $navigationReportPath=Join-Path ([IO.Path]::GetFullPath([string]$VSOProbeArtifactRoot)) ('VSO7_R80_GUI_NAVIGATION_'+[string]$VSOProbeOwnerToken+'.json')
                $script:GuiNavigationProbeState=[pscustomobject]@{ReportPath=$navigationReportPath;Phase='SCHEDULED';CurrentAction='';Completed=$false;FatalError='';Rows=(New-Object 'Collections.Generic.List[object]')}
                Write-VSO7GuiNavigationProbeHeartbeatVSO -Phase 'SCHEDULED'
            }
            $smokeDelegate=[Action](Get-Command Invoke-VSO7GuiDeferredSmokeVSO -CommandType Function -ErrorAction Stop).ScriptBlock
            [void]$window.Dispatcher.BeginInvoke([Windows.Threading.DispatcherPriority]::ApplicationIdle,$smokeDelegate)
        }

        if(-not$SmokeOnly-or[string]$SmokeAction-in@('Taskbar','PerformanceMatrix')){[void](Write-VSO7MainWindowInteropStateR52VSO -Window $window -Stage 'WINDOW_BEFORE_SHOW')}
        Write-VSO7LifecycleCheckpointVSO -Name 'GUI_BEFORE_SHOW'
        $script:GuiMainFrameR52=New-Object Windows.Threading.DispatcherFrame
        try{
            $window.Show()
            Write-VSO7LifecycleCheckpointVSO -Name 'GUI_AFTER_SHOW'
            [Windows.Threading.Dispatcher]::PushFrame($script:GuiMainFrameR52)
            Write-VSO7LifecycleCheckpointVSO -Name 'GUI_AFTER_DISPATCHER_FRAME'
        }finally{
            Write-VSO7LifecycleCheckpointVSO -Name 'BEFORE_GUI_RESOURCE_CLEANUP' -Detail 'Show-VSO7Gui.R52'
            if($null-ne$script:GuiGamingSessionTimer){try{[void](Stop-VSO7GuiGamingSessionMonitorVSO -RestoreState)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_RESOURCE_CLEANUP_ERROR' -Detail ('Gaming restore: '+$_.Exception.Message)}}
            try{Stop-VSO7GuiAppDetectionR52VSO -DisposeWorker}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_RESOURCE_CLEANUP_ERROR' -Detail ('Applications worker: '+$_.Exception.Message)}
            try{Stop-VSO7GuiBackgroundRunspaceR52VSO}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_RESOURCE_CLEANUP_ERROR' -Detail ('Background worker: '+$_.Exception.Message)}
            try{Stop-VSO7GuiPerformanceSmokeR52VSO}catch{}
            try{Stop-VSO7GuiCallbackSmokeR52VSO}catch{}
            foreach($cardButton in @($script:GuiCardButtons.ToArray())){try{$cardButton.Remove_Click($script:GuiCardClickHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}}
            if($null-ne$script:GuiWelcomeStartHandler-and$null-ne$script:GuiWelcomeStartButton){try{$script:GuiWelcomeStartButton.Remove_Click($script:GuiWelcomeStartHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}}
            try{$script:GuiBackButton.Remove_Click($backHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$homeClose.Remove_Click($closeHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$actionClose.Remove_Click($closeHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$window.Remove_Loaded($loadedHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$window.Remove_ContentRendered($contentRenderedHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$window.Remove_Closing($closingHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$window.Remove_Closed($closedHandler)}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_HANDLER_CLEANUP_ERROR' -Detail $_.Exception.Message}
            if($null-ne$guiDispatcher){Write-VSO7LifecycleCheckpointVSO -Name 'GUI_DISPATCHER_STATE' -Detail ('started='+$guiDispatcher.HasShutdownStarted+';finished='+$guiDispatcher.HasShutdownFinished)}
            try{if($window.IsLoaded){$window.Close()}}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_RESOURCE_CLEANUP_ERROR' -Detail $_.Exception.Message}
            try{$window.Content=$null}catch{Write-VSO7LifecycleCheckpointVSO -Name 'GUI_RESOURCE_CLEANUP_ERROR' -Detail $_.Exception.Message}
            $script:GuiLifecycleHandlers=$null;$script:GuiLifecycleDispatcher=$null;$script:GuiSmokeContext=$null
            Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_GUI_RESOURCE_CLEANUP' -Detail 'Show-VSO7Gui.R52'
        }
        if($SmokeOnly){return $true}

    }catch{
        if($SmokeOnly){throw}
        $script:GuiMode=$false
        try{[void][Windows.MessageBox]::Show(((Get-VSO7GuiStringVSO 'GuiOpenFailed')+' '+$_.Exception.Message),'VSO7',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Error)}catch{Write-VSOHost ('Could not open the graphical interface: '+$_.Exception.Message) -ForegroundColor Red}
    }finally{
        $script:GuiMode=$false;$script:GuiWindow=$null;$script:GuiOutput=$null;$script:GuiOutputParagraph=$null
        $script:GuiWelcomeView=$null;$script:GuiWelcomeLogo=$null;$script:GuiWelcomeStartButton=$null;$script:GuiWelcomeStartHandler=$null
        $script:GuiHomeView=$null;$script:GuiActionView=$null;$script:GuiHomeCards=$null;$script:GuiPageHost=$null;$script:GuiStatusText=$null;$script:GuiBackButton=$null
        $script:GuiCardButtons=$null;$script:GuiCardClickHandler=$null;$script:GuiRecommendedPlan=$null;$script:GuiSmokeContext=$null;$script:GuiPromptSmokeContext=$null;$script:GuiNavigationProbeState=$null;$script:GuiSmokeFailFast=$false;$script:GuiSuppressErrorDialogs=$false;$script:GuiErrorBoundarySmokePassed=$false
        $script:GuiGamingSessionTimer=$null;$script:GuiGamingSessionTimerHandler=$null;$script:GuiGamingSessionIdentity=$null;$script:GuiMainFrameR52=$null;$script:GuiBackgroundRunspaceR52=$null;$script:GuiCallbackSmokeContext=$null
    }
}

function Invoke-AggressiveOptimization {

    $isEn=($script:Language-eq'en')
    Write-Title;
    Write-CenteredLineVSO -Text $(if($isEn){
        'AGGRESSIVE OPTIMIZATION (CONTROLLED)'
    }else{
        'OPTIMIZACIÓN AGRESIVA (CONTROLADA)'
    }) -Color $script:ThemeWarning;
    Write-VSOHost ''
    if($isEn){

        Write-VSOHost 'This mode does NOT start when you open it. It includes exactly:' -ForegroundColor Cyan;
        Write-VSOHost ''
        Write-VSOHost 'Gaming:' -ForegroundColor Yellow
        Write-VSOHost '  - Enable Windows Game Mode.'
        Write-VSOHost '  - Disable game recording/background capture.'
        Write-VSOHost '  - It may use High performance ONLY when the current plan is a standard Windows plan and VSO7 can save it for rollback.'
        Write-VSOHost '  - Clean temporary files older than 7 days using VSO7 safety exclusions.'
        Write-VSOHost ''
        Write-VSOHost 'Interface:' -ForegroundColor Yellow
        Write-VSOHost '  - Disable transparency.'
        Write-VSOHost '  - Reduce animations and visual effects so the interface feels more immediate.'
        Write-VSOHost ''
        Write-VSOHost 'Privacy / Windows noise:' -ForegroundColor Yellow
        Write-VSOHost '  - Disable suggestions, Edge/Settings ads, search history, Copilot, Recall and Click to Do when available.'
        Write-VSOHost ''
        Write-VSOHost 'It does NOT touch Defender, Firewall, VBS, critical services, BCD/HPET, pagefile, HAGS, existing BitLocker, or Windows Update.' -ForegroundColor Green
        Write-VSOHost 'It does NOT replace OEM or custom power plans.' -ForegroundColor Green
        Write-VSOHost ''
        Write-VSOHost 'Type AGGRESSIVE to apply. Any other answer cancels and applies nothing.' -ForegroundColor Yellow

    }else{

        Write-VSOHost 'Este modo NO empieza al entrar. Incluye exactamente:' -ForegroundColor Cyan;
        Write-VSOHost ''
        Write-VSOHost 'Gaming:' -ForegroundColor Yellow
        Write-VSOHost '  - Activa el Modo de juego de Windows.'
        Write-VSOHost '  - Desactiva grabacion/captura de juegos en segundo plano.'
        Write-VSOHost '  - Puede usar Alto rendimiento SOLO si el plan actual es estandar de Windows y queda guardado para rollback.'
        Write-VSOHost '  - Limpia temporales de mas de 7 dias con exclusiones de seguridad.'
        Write-VSOHost ''
        Write-VSOHost 'Interfaz:' -ForegroundColor Yellow
        Write-VSOHost '  - Desactiva transparencias.'
        Write-VSOHost '  - Reduce animaciones y efectos visuales para que la interfaz responda mas rapido.'
        Write-VSOHost ''
        Write-VSOHost 'Privacidad / ruido de Windows:' -ForegroundColor Yellow
        Write-VSOHost '  - Desactiva sugerencias, anuncios de Edge/Configuracion, historial de busqueda, Copilot, Recall y Click to Do cuando existan.'
        Write-VSOHost ''
        Write-VSOHost 'NO toca Defender, Firewall, VBS, servicios criticos, BCD/HPET, pagefile, HAGS, BitLocker existente ni Windows Update.' -ForegroundColor Green
        Write-VSOHost 'NO reemplaza planes de energia OEM o personalizados.' -ForegroundColor Green
        Write-VSOHost ''
        Write-VSOHost 'Escribe AGRESIVO para aplicar. Cualquier otra respuesta cancela y no aplica nada.' -ForegroundColor Yellow

    }
    if(-not(Confirm-Word -Word 'AGRESIVO' -Message 'Escribe exactamente AGRESIVO para aplicar')){
        Write-VSOHost $(if($isEn){
            'Cancelled.'
        }else{
            'Cancelado.'
        }) -ForegroundColor Gray;
        Pause-Vico;
        return
    }
    $ok=$true;
    try{
        if(-not(Invoke-VSO7AggressiveCoreVSO)){
            Pause-Vico;
            return
        }
    }catch{
        $ok=$false;
        Write-VSO7Log ("La optimizacion agresiva encontro un error: {0}"-f$_.Exception.Message) 'ERROR'
    }
    Write-VSOHost '';
    if($ok){
        Write-VSOHost $(if($isEn){
            'Aggressive optimization completed.'
        }else{
            'Optimizacion agresiva terminada.'
        }) -ForegroundColor Green;
        Write-VSOHost $(if($isEn){
            'Sign out or restart if you want every visual change to take full effect.'
        }else{
            'Cierra sesion o reinicia si quieres aplicar completamente los cambios visuales.'
        })
    }else{
        Write-VSOHost $(if($isEn){
            'Aggressive optimization was INTERRUPTED: some earlier changes may have been applied.'
        }else{
            'Optimizacion agresiva INTERRUMPIDA: algunos cambios anteriores pueden haberse aplicado.'
        }) -ForegroundColor Yellow;
        Write-VSOHost $(if($isEn){
            'Review the log or use Recovery to restore them.'
        }else{
            'Revisa el log o usa Recuperacion para restaurarlos.'
        }) -ForegroundColor Yellow
    };
    Pause-Vico

}

function Show-Analysis {

    $isEn=($script:Language-eq'en')
    Write-Title
    Write-VSOHost $(if($isEn){
        'PC ANALYSIS (READ-ONLY)'
    }else{
        'ANÁLISIS DEL PC (NO MODIFICA NADA)'
    }) -ForegroundColor Cyan
    Write-VSOHost '----------------------------------'
    Write-VSOHost ''

    try {

        $os = CimCmdlets\Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        Write-VSOHost ($(if($isEn){
            'Windows : {0}'
        }else{
            'Windows : {0}'
        }) -f $os.Caption)
        Write-VSOHost ($(if($isEn){
            'Version : {0}  Build {1}'
        }else{
            'Versión : {0}  Build {1}'
        }) -f $os.Version, $os.BuildNumber)

    } catch {

        try{

            $cv=Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
            $buildText=[string]$cv.CurrentBuildNumber
            if([string]::IsNullOrWhiteSpace($buildText)){
                $buildText=[string]$cv.CurrentBuild
            }
            $buildNumber=0;
            [void][int]::TryParse(($buildText-split'\.')[0],[ref]$buildNumber)
            $product=[string]$cv.ProductName
            if([string]::IsNullOrWhiteSpace($product)){
                $product='Microsoft Windows'
            }
            if($buildNumber-ge22000-and$product-match'Windows 10'){
                $product=$product-replace'Windows 10','Windows 11'
            }
            $display=[string]$cv.DisplayVersion
            if([string]::IsNullOrWhiteSpace($display)){
                $display=[string]$cv.ReleaseId
            }
            Write-VSOHost ('Windows : {0}' -f $product)
            Write-VSOHost ($(if($isEn){
                'Version : {0}  Build {1}'
            }else{
                'Versión : {0}  Build {1}'
            }) -f $display,$buildText)

        }catch{

            $fallback=[Environment]::OSVersion.Version
            Write-VSOHost ($(if($isEn){
                'Windows : detected, detailed edition unavailable'
            }else{
                'Windows : detectado, edición detallada no disponible'
            })) -ForegroundColor Yellow
            Write-VSOHost ($(if($isEn){
                'Version : {0}'
            }else{
                'Versión : {0}'
            }) -f $fallback)

        }

    }

    try {

        $cpu = CimCmdlets\Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1
        Write-VSOHost ("CPU     : {0}" -f $cpu.Name.Trim())

    } catch {}

    try {

        $cs = CimCmdlets\Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
        $ramGB = [math]::Round([double]$cs.TotalPhysicalMemory / 1GB, 1)
        Write-VSOHost ("RAM     : {0} GB" -f $ramGB)

    } catch {}

    try {

        $gpus = @(CimCmdlets\Get-CimInstance Win32_VideoController -ErrorAction Stop | ForEach-Object {
            $_.Name
        })
        if ($gpus.Count -gt 0) {
            Write-VSOHost ("GPU     : {0}" -f ($gpus -join ' | '))
        }

    } catch {}

    try {

        $driveId = $script:SystemDrive
        $disk = CimCmdlets\Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $driveId) -ErrorAction Stop
        $freeGB = [math]::Round([double]$disk.FreeSpace / 1GB, 1)
        $sizeGB = [math]::Round([double]$disk.Size / 1GB, 1)
        Write-VSOHost ($(if($isEn){
            'Disk    : {0} GB free of {1} GB on {2}'
        }else{
            'Disco   : {0} GB libres de {1} GB en {2}'
        }) -f $freeGB,$sizeGB,$driveId)

    } catch {}

    $batteryInfo=Test-HasBattery
    $batteryText=if($true-eq$batteryInfo){
        if($isEn){
            'Laptop / battery detected'
        }else{
            'Portátil / batería detectada'
        }
    }elseif($false-eq$batteryInfo){
        if($isEn){
            'Desktop / no battery detected'
        }else{
            'Sobremesa / sin batería detectada'
        }
    }else{
        if($isEn){
            'Battery status UNAVAILABLE'
        }else{
            'Estado de batería NO DISPONIBLE'
        }
    }
    Write-VSOHost ($(if($isEn){
        'Device  : {0}'
    }else{
        'Equipo   : {0}'
    }) -f $batteryText)

    $power = Get-ActivePowerSchemeInfo
    Write-VSOHost ($(if($isEn){
        'Power   : {0}'
    }else{
        'Energía  : {0}'
    }) -f $(if ($power.Raw) {
        $power.Raw
    } else {
        if($isEn){
            '<unavailable>'
        }else{
            '<no disponible>'
        }
    }))
    if ($power.IsCustom) {

        Write-VSOHost $(if($isEn){
            '           Custom/OEM plan detected: presets will NOT replace it.'
        }else{
            '           Plan personalizado/OEM detectado: los presets NO lo sustituirán.'
        }) -ForegroundColor Green

    }

    $gameMode = Get-RegValueFriendly -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AutoGameModeEnabled'
    $capture = Get-RegValueFriendly -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' -Name 'AppCaptureEnabled'
    $dvr = Get-RegValueFriendly -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled'
    $transparency = Get-RegValueFriendly -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name 'EnableTransparency'
    $animations = Get-RegValueFriendly -Path 'HKCU:\Control Panel\Desktop\WindowMetrics' -Name 'MinAnimate'

    Write-VSOHost ''
    Write-VSOHost $(if($isEn){
        'Gaming / interface:'
    }else{
        'Gaming / interfaz:'
    }) -ForegroundColor Cyan
    Write-VSOHost ($(if($isEn){
        '  Game Mode              : {0}'
    }else{
        '  Modo de juego          : {0}'
    }) -f $gameMode)
    Write-VSOHost ("  AppCaptureEnabled      : {0}" -f $capture)
    Write-VSOHost ("  GameDVR_Enabled        : {0}" -f $dvr)
    Write-VSOHost ($(if($isEn){
        '  Transparency           : {0}'
    }else{
        '  Transparencia          : {0}'
    }) -f $transparency)
    Write-VSOHost ($(if($isEn){
        '  Window animations      : {0}'
    }else{
        '  Animación ventanas     : {0}'
    }) -f $animations)

    $startup = Get-StartupEntries
    Write-VSOHost ''
    Write-VSOHost ($(if($isEn){
        'Detected startup entries: {0}'
    }else{
        'Inicio automatico detectado: {0} entradas'
    }) -f $startup.Count) -ForegroundColor Cyan
    if ($startup.Count -gt 0) {

        foreach($entry in @($startup|Select-Object -First 12)){

            $name=[string]$entry.Name;
            $location=[string]$entry.Location
            Write-VSOHost ('  {0}  |  {1}' -f $name,$location) -ForegroundColor Gray

        }
        if ($startup.Count -gt 12) {
            Write-VSOHost ($(if($isEn){
                '  ... and {0} more.'
            }else{
                '  ... y {0} más.'
            }) -f ($startup.Count - 12)) -ForegroundColor DarkGray
        }

    }

    Write-VSOHost ''
    Write-VSOHost $(if($isEn){
        'System Restore:'
    }else{
        'Restauración del sistema:'
    }) -ForegroundColor Cyan
    $rp = Get-LatestRestorePoint
    if ($null -ne $rp) {

        $rpDate = Convert-RestorePointDate -RestorePoint $rp
        Write-VSOHost ($(if($isEn){
            '  Latest restore point: {0} | {1}'
        }else{
            '  Último punto: {0} | {1}'
        }) -f $rpDate,$rp.Description)

    } else {

        Write-VSOHost $(if($isEn){
            '  No restore point could be found.'
        }else{
            '  No se pudo encontrar un punto de restauración.'
        }) -ForegroundColor Yellow

    }

    Write-VSOHost ''
    Write-VSOHost $(if($isEn){
        'The analysis did not change any settings.'
    }else{
        'El análisis no ha cambiado ninguna configuración.'
    }) -ForegroundColor Green
    Pause-Vico

}

function Invoke-VSO7CreateRestoreCheckpointVSO {

    $isEn=($script:Language-eq'en')
    Write-Title
    Write-VSOHost $(if($isEn){
        'CREATE RESTORE POINT'
    }else{
        'CREAR PUNTO DE RESTAURACIÓN'
    }) -ForegroundColor Cyan
    Write-VSOHost '----------------------------'
    Write-VSOHost ''

    $ok = New-SafeRestorePoint

    Write-VSOHost ''
    if ($ok) {

        Write-VSOHost $(if($isEn){
            'A recent restore point is available.'
        }else{
            'Hay un punto de restauración reciente disponible.'
        }) -ForegroundColor Green

    } else {

        Write-VSOHost $(if($isEn){
            'A restore point could not be guaranteed.'
        }else{
            'No se ha podido garantizar un punto de restauración.'
        }) -ForegroundColor Red
        Write-VSOHost $(if($isEn){
            'Optimizations will not run while this remains unresolved.'
        }else{
            'No se ejecutarán optimizaciones mientras esto siga así.'
        })

    }

    Pause-Vico

}

function Get-VSO7RevertAllCrossEngineOverlapVSO {

    $claims=@()
    try{
        Load-State
    }catch{}
    try{
        Load-ExtremeState
    }catch{}
    if($null-ne$script:State-and$null-ne$script:State.Registry){
        foreach($e in @($script:State.Registry)){
            $claims+=[pscustomobject]@{
                Engine='Normal';
                Target=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$e.Path)),([string]$e.Name).ToLowerInvariant())
            }
        }
    }
    if($null-ne$script:ExtremeState){

        $active=@(@($script:ExtremeState.AppliedTweaks)+@($script:ExtremeState.PendingTweaks)|ForEach-Object{
            [string]$_.Id
        })
        foreach($e in @($script:ExtremeState.Registry|Where-Object{
            $active-contains[string]$_.TweakId
        })){
            $claims+=[pscustomobject]@{
                Engine='Extreme';
                Target=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$e.Path)),([string]$e.Name).ToLowerInvariant())
            }
        }
        foreach($e in @($script:ExtremeState.PowerSettings|Where-Object{
            $active-contains[string]$_.TweakId
        })){
            $claims+=[pscustomobject]@{
                Engine='Extreme';
                Target=('POWER|{0}|{1}|{2}'-f([string]$e.SchemeGuid).ToLowerInvariant(),([string]$e.SubGroupAlias).ToLowerInvariant(),([string]$e.SettingAlias).ToLowerInvariant())
            }
        }
        foreach($e in @($script:ExtremeState.Features|Where-Object{
            $active-contains[string]$_.TweakId
        })){
            $claims+=[pscustomobject]@{
                Engine='Extreme';
                Target=('FEATURE|{0}'-f([string]$e.Name).ToLowerInvariant())
            }
        }

    }
    foreach($session in @(Get-VSO7NativeBackupSessionsVSO -SkipInvalid|Where-Object{
        [string]$_.Status-cne'Restored'
    })){

        foreach($e in @($session.Entries)){

            switch([string]$e.Type){

                'RegistryValue' {
                    $claims+=[pscustomobject]@{
                        Engine='Native';
                        Target=('REG|{0}|{1}'-f(ConvertTo-VSO7CanonicalOwnershipRegistryPathVSO -Path ([string]$e.Path)),([string]$e.Name).ToLowerInvariant())
                    }
                }
                'PowerSetting' {
                    $claims+=[pscustomobject]@{
                        Engine='Native';
                        Target=('POWER|{0}|{1}|{2}'-f([string]$e.SchemeGuid).ToLowerInvariant(),([string]$e.SubGroupAlias).ToLowerInvariant(),([string]$e.SettingAlias).ToLowerInvariant())
                    }
                }
                'OptionalFeature' {
                    $claims+=[pscustomobject]@{
                        Engine='Native';
                        Target=('FEATURE|{0}'-f([string]$e.Name).ToLowerInvariant())
                    }
                }

            }

        }

    }
    return @($claims|Group-Object Target|Where-Object{
        @($_.Group.Engine|Select-Object -Unique).Count-gt1
    }|ForEach-Object{
        [pscustomobject]@{
            Target=[string]$_.Name;Engines=@($_.Group.Engine|Select-Object -Unique)
        }
    })

}

function Assert-VSO7RevertAllOrderSafeVSO {

    $inventory=Get-VSO7NativeBackupInventoryVSO -SkipInvalid
    if([int]$inventory.InvalidCount-gt0){
        throw ('Revertir TODOS detecto {0} sesion(es) nativa(s) invalidas. El ownership global es desconocido; no se toca Windows.'-f[int]$inventory.InvalidCount)
    }
    $overlap=@(Get-VSO7RevertAllCrossEngineOverlapVSO)
    if($overlap.Count-gt0){

        $sample=@($overlap|Select-Object -First 5|ForEach-Object{
            ('{0} [{1}]'-f$_.Target,($_.Engines-join'+'))
        })-join'; '
        throw ('Revertir TODOS detecto ownership cross-engine historico sin cronologia global demostrable. No se toca Windows. Restaura primero la capa mas reciente de forma individual. Targets: {0}'-f$sample)

    }
    return $true

}

function Invoke-Revert {

    while($true){

        $isEn=($script:Language-eq'en')
        Write-Title
        Write-CenteredLineVSO -Text $(if($isEn){
            'VSO7 RECOVERY'
        }else{
            'RECUPERACION DE VSO7'
        }) -Color 'Yellow'
        Write-VSOHost ''
        Load-State;
        Load-ExtremeState;
        Load-StartupState
        $hasRegistry=($null-ne$script:State.Registry-and@($script:State.Registry).Count-gt0)
        $hasPower=-not[string]::IsNullOrWhiteSpace([string]$script:State.OriginalPowerScheme)
        $hasExtreme=@(Get-RecoverableExtremeTweakIdsVSO).Count-gt0
        $hasStartup=@($script:StartupState.Disabled).Count-gt0
        $nativeBackupCount=$null;
        $nativeInvalidCount=0;
        $nativeBackupStatusKnown=$true
        try{
            $nativeInventory=Get-VSO7NativeBackupInventoryVSO -SkipInvalid;
            $nativeBackupCount=@($nativeInventory.Valid|Where-Object{
                [string]$_.Status-ne'Restored'
            }).Count;
            $nativeInvalidCount=[int]$nativeInventory.InvalidCount
        }catch{
            $nativeBackupStatusKnown=$false;
            Write-VSO7Log ("No se pudo determinar el inventario de backups nativos: {0}"-f$_.Exception.Message) 'ERROR'
        }
        $hasVsoRecovery=($hasRegistry-or$hasPower-or$hasExtreme-or$hasStartup-or($nativeBackupStatusKnown-and($nativeBackupCount-gt0-or$nativeInvalidCount-gt0)))
        if(-not$hasVsoRecovery){

            Write-CenteredLineVSO -Text $(if($isEn){
                'VSO7 has no recorded normal/extreme/startup changes to restore.'
            }else{
                'VSO7 no tiene cambios normales, extremos o de inicio registrados para restaurar.'
            }) -Color $script:ThemeMuted
            Write-CenteredLineVSO -Text $(if($isEn){
                'System Restore and native VSO7 backups remain available below.'
            }else{
                'Restaurar sistema y los backups nativos de VSO7 siguen disponibles abajo.'
            }) -Color $script:ThemeText
            Write-VSOHost ''

        }
        $nativeLabel=if(-not$nativeBackupStatusKnown){
            if($isEn){
                '[5] Native VSO7 tweak backups (status unavailable)'
            }else{
                '[5] Backups nativos de ajustes VSO7 (estado no disponible)'
            }
        }elseif($nativeInvalidCount-gt0){
            if($isEn){
                ('[5] Native VSO7 backups ({0} valid pending, {1} INVALID)'-f$nativeBackupCount,$nativeInvalidCount)
            }else{
                ('[5] Backups nativos VSO7 ({0} validos pendientes, {1} INVALIDOS)'-f$nativeBackupCount,$nativeInvalidCount)
            }
        }elseif($isEn){
            ('[5] Native VSO7 tweak backups ({0} pending)'-f$nativeBackupCount)
        }else{
            ('[5] Backups nativos de ajustes VSO7 ({0} pendientes)'-f$nativeBackupCount)
        }
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=$(if($isEn){
                '[1] Restore recorded normal or safe changes'
            }else{
                '[1] Revertir cambios normales o seguros registrados'
            });Color='Gray';Description=$(if($isEn){
                'Restores normal settings changed by VSO7 when their previous state was saved.'
            }else{
                'Restaura ajustes normales que VSO7 modifico y para los que guardo el estado anterior.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[2] Restore one EXTREME change'
            }else{
                '[2] Revertir un cambio EXTREMO individual'
            });Color='Yellow';Description=$(if($isEn){
                'Opens the list of reversible extreme tweaks so you can recover only the one you choose.'
            }else{
                'Abre una lista de tweaks extremos reversibles para recuperar solo el que elijas.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[3] Restore ALL reversible VSO7 changes'
            }else{
                '[3] Revertir TODOS los cambios reversibles de VSO7'
            });Color='Red';Description=$(if($isEn){
                'Attempts native, normal, extreme and startup recovery together. Nothing runs until you explicitly confirm it.'
            }else{
                'Intenta recuperar de una vez ajustes nativos, normales, extremos e inicio. No ejecuta nada hasta que lo confirmes expresamente.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[4] Restore startup entries disabled by VSO7'
            }else{
                '[4] Restaurar aplicaciones de inicio deshabilitadas por VSO7'
            });Color='Gray';Description=$(if($isEn){
                'Shows only startup entries VSO7 disabled and knows how to restore.'
            }else{
                'Muestra solo las entradas de autoarranque que VSO7 deshabilito y sabe como restaurar.'
            })
        },
            [pscustomobject]@{
            Text=$nativeLabel;Color='Cyan';Description=$(if($isEn){
                'Lets you choose a valid native VSO7 recovery session. Registry, power, network, tasks and optional-feature entries are restored only when ownership is still demonstrable; removed applications are not reinstalled.'
            }else{
                'Permite elegir una sesion valida de Recovery nativo. Registro, energia, red, tareas y funciones opcionales solo se restauran cuando el ownership sigue siendo demostrable; las aplicaciones eliminadas no se reinstalan.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[6] Open Windows System Restore'
            }else{
                '[6] Abrir Restaurar sistema de Windows'
            });Color='Gray';Description=$(if($isEn){
                'Opens the native Windows restore-point tool. VSO7 does not start a system restore by itself.'
            }else{
                'Abre la herramienta nativa de puntos de restauracion. VSO7 no inicia una restauracion del sistema por si solo.'
            })
        },
            [pscustomobject]@{
            Text=$(if($isEn){
                '[0] Back'
            }else{
                '[0] Volver'
            });Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text $(if($isEn){
            'Option'
        }else{
            'Opcion'
        })
        switch($c){

            '1'{
                if(-not($hasRegistry-or$hasPower)){
                    Write-CenteredLineVSO -Text $(if($isEn){
                        'There are no recorded normal changes to restore.'
                    }else{
                        'No hay cambios normales registrados para restaurar.'
                    }) -Color $script:ThemeMuted;
                    Pause-Vico;
                    continue
                };
                if(Confirm-Word -Word 'REVERTIR' -Message 'Escribe REVERTIR'){
                    $regOk=[bool](Restore-TrackedRegistry);
                    $powerOk=[bool](Restore-PowerScheme);
                    if($regOk-and$powerOk){
                        Write-VSOHost $(if($isEn){
                            'Normal changes restored and verified.'
                        }else{
                            'Cambios normales restaurados y verificados.'
                        }) -ForegroundColor Green
                    }else{
                        Write-VSOHost $(if($isEn){
                            'Normal recovery was incomplete; the pending state is preserved.'
                        }else{
                            'La restauracion normal fue incompleta; el estado pendiente se conserva.'
                        }) -ForegroundColor Red
                    };
                    Pause-Vico
                }
            }
            '2'{
                if(-not$hasExtreme){
                    Write-CenteredLineVSO -Text $(if($isEn){
                        'There are no recorded EXTREME changes to restore.'
                    }else{
                        'No hay cambios EXTREMOS registrados para restaurar.'
                    }) -Color $script:ThemeMuted;
                    Pause-Vico;
                    continue
                };
                Show-ExtremeRevertMenu
            }
            '3'{
                if(-not$hasVsoRecovery){
                    Write-CenteredLineVSO -Text $(if($isEn){
                        'There are no recorded VSO7 changes to restore.'
                    }else{
                        'No hay cambios de VSO7 registrados para restaurar.'
                    }) -Color $script:ThemeMuted;
                    Pause-Vico;
                    continue
                };
                if(Confirm-Word -Word 'REVERTIR TODO' -Message 'Escribe exactamente: REVERTIR TODO'){
                    try{
                        [void](Assert-VSO7RevertAllOrderSafeVSO)
                    }catch{
                        Write-VSOHost $_.Exception.Message -ForegroundColor Red;
                        Write-VSO7Log $_.Exception.Message 'ERROR';
                        Pause-Vico;
                        continue
                    };
                    $nativeOk=$true;
                    try{
                        foreach($nativeSession in @(Get-VSO7NativeBackupSessionsVSO|Where-Object{
                            [string]$_.Status-ne'Restored'
                        }|Sort-Object CreatedAt -Descending)){
                            if(-not(Restore-VSO7NativeBackupSessionVSO -Session $nativeSession)){
                                $nativeOk=$false
                            }
                        }
                    }catch{
                        $nativeOk=$false;
                        Write-VSO7Log ("Recovery nativo total fallo cerrado: {0}"-f$_.Exception.Message) 'ERROR'
                    };
                    $extOk=[bool](Restore-AllExtremeChanges);
                    $regOk=[bool](Restore-TrackedRegistry);
                    $powerOk=[bool](Restore-PowerScheme);
                    $startupOk=[bool](Restore-AllStartupChangesVSO);
                    if($nativeOk-and$extOk-and$regOk-and$powerOk-and$startupOk){
                        Write-VSOHost $(if($isEn){
                            'All reversible VSO7 changes were restored and verified.'
                        }else{
                            'Todos los cambios reversibles de VSO7 fueron restaurados y verificados.'
                        }) -ForegroundColor Green
                    }else{
                        Write-VSOHost $(if($isEn){
                            'Full recovery was INCOMPLETE; VSO7 preserves pending state so it can be retried.'
                        }else{
                            'La reversion total fue INCOMPLETA; VSO7 conserva los estados pendientes para reintentar.'
                        }) -ForegroundColor Red
                    };
                    Write-VSOHost $(if($isEn){
                        'Cache/temporary cleanups cannot be undone.'
                    }else{
                        'Las limpiezas de cache/temporales no pueden deshacerse.'
                    }) -ForegroundColor Yellow;
                    Pause-Vico
                }
            }
            '4'{
                if(-not$hasStartup){
                    Write-CenteredLineVSO -Text $(if($isEn){
                        'There are no startup entries disabled by VSO7 to restore.'
                    }else{
                        'No hay entradas de inicio deshabilitadas por VSO7 para restaurar.'
                    }) -Color $script:ThemeMuted;
                    Pause-Vico;
                    continue
                };
                Show-StartupRestoreMenuVSO
            }
            '5'{
                Show-VSO7NativeBackupRestoreVSO
            }
            '6'{
                try{
                    Start-Process -FilePath (Resolve-VSOSystemExecutable -Name 'rstrui.exe') -ErrorAction Stop|Out-Null
                }catch{
                    Write-VSOHost ($(if($isEn){
                        'Could not open System Restore: {0}'
                    }else{
                        'No se pudo abrir Restauracion del sistema: {0}'
                    })-f$_.Exception.Message) -ForegroundColor Red
                };
                Pause-Vico
            }
            '0'{
                return
            }
            default{
                Write-VSOHost $(if($isEn){
                    'Invalid option.'
                }else{
                    'Opcion no valida.'
                }) -ForegroundColor Red;
                Start-Sleep -Milliseconds 600
            }

        }

    }

}

