function Get-VSO7PerfSnapshot {

    $cpuPct=$null;
    $dpcPct=$null;
    $interrupts=$null;
    $ctx=$null;
    $queue=$null;
    $diskT=$null;
    $diskRead=$null;
    $diskWrite=$null;
    $availMB=$null;
    $ramUsedPct=$null
    try{
        $p=CimCmdlets\Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop;
        $cpuPct=[double]$p.PercentProcessorTime;
        $dpcPct=[double]$p.PercentDPCTime;
        $interrupts=[double]$p.InterruptsPersec
    }catch{}
    try{
        $s=CimCmdlets\Get-CimInstance Win32_PerfFormattedData_PerfOS_System -ErrorAction Stop;
        $ctx=[double]$s.ContextSwitchesPersec;
        $queue=[double]$s.ProcessorQueueLength
    }catch{}
    try{
        $d=CimCmdlets\Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'" -ErrorAction Stop;
        $diskT=[double]$d.DiskTransfersPersec;
        $diskRead=[double]$d.DiskReadBytesPersec/1MB;
        $diskWrite=[double]$d.DiskWriteBytesPersec/1MB
    }catch{}
    try{
        $m=CimCmdlets\Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory -ErrorAction Stop;
        $availMB=[double]$m.AvailableMBytes
    }catch{}
    try{
        $os=CimCmdlets\Get-CimInstance Win32_OperatingSystem -ErrorAction Stop;
        if([double]$os.TotalVisibleMemorySize-gt0){
            $ramUsedPct=[math]::Round((1-([double]$os.FreePhysicalMemory/[double]$os.TotalVisibleMemorySize))*100,2)
        }
    }catch{}
    [pscustomobject]@{

        Timestamp=(Get-Date).ToString('o')
        CpuPct=$(if($null-ne$cpuPct){
            [math]::Round([double]$cpuPct,2)
        }else{
            $null
        })
        CpuIdlePct=$(if($null-ne$cpuPct){
            [math]::Round((100-[double]$cpuPct),2)
        }else{
            $null
        })
        DpcPct=$(if($null-ne$dpcPct){
            [math]::Round([double]$dpcPct,3)
        }else{
            $null
        })
        InterruptsPerSec=$(if($null-ne$interrupts){
            [math]::Round([double]$interrupts,0)
        }else{
            $null
        })
        ContextSwitchesPerSec=$(if($null-ne$ctx){
            [math]::Round([double]$ctx,0)
        }else{
            $null
        })
        ProcessorQueueLength=$(if($null-ne$queue){
            [math]::Round([double]$queue,2)
        }else{
            $null
        })
        DiskTransfersPerSec=$(if($null-ne$diskT){
            [math]::Round([double]$diskT,1)
        }else{
            $null
        })
        DiskReadMBps=$(if($null-ne$diskRead){
            [math]::Round([double]$diskRead,2)
        }else{
            $null
        })
        DiskWriteMBps=$(if($null-ne$diskWrite){
            [math]::Round([double]$diskWrite,2)
        }else{
            $null
        })
        AvailableMemoryMB=$(if($null-ne$availMB){
            [math]::Round([double]$availMB,0)
        }else{
            $null
        })
        RamUsedPct=$ramUsedPct
        ProcessCount=@(CimCmdlets\Get-CimInstance Win32_Process -ErrorAction SilentlyContinue).Count

    }

}

function Get-VSO7Average {

    param([array]$Items,[string]$Property)
    $values=@();
    foreach($item in @($Items)){
        try{
            $p=$item.PSObject.Properties[$Property];
            if($null-ne$p-and$null-ne$p.Value){
                $values += [double]$p.Value
            }
        }catch{}
    }
    if($values.Count-eq0){
        return $null
    }
    return [math]::Round([double](($values|Measure-Object -Average).Average),2)

}

function Get-VSO7Maximum {

    param([array]$Items,[string]$Property)
    $values=@();
    foreach($item in @($Items)){
        try{
            $p=$item.PSObject.Properties[$Property];
            if($null-ne$p-and$null-ne$p.Value){
                $values += [double]$p.Value
            }
        }catch{}
    }
    if($values.Count-eq0){
        return $null
    }
    return [math]::Round([double](($values|Measure-Object -Maximum).Maximum),2)

}

function Measure-VSO7Performance {

    param(
        [ValidateRange(3,60)][int]$Seconds=10,
        [ValidateSet('BASELINE','POST','MANUAL')][string]$Label='MANUAL',
        [AllowNull()][scriptblock]$ProgressCallback
    )
    $samples=@()
    $timer=[Diagnostics.Stopwatch]::StartNew()
    try{
        $sampleNumber=0
        do{
            $sampleNumber++
            $pct=[math]::Min(99,[math]::Round(($timer.Elapsed.TotalSeconds/[double]$Seconds)*100,0))
            if($null-ne$ProgressCallback){
                try{& $ProgressCallback $pct $sampleNumber ([double]$timer.Elapsed.TotalSeconds) $Seconds}catch{}
            }else{
                Write-Progress -Activity 'VSO7 - midiendo actividad de fondo' -Status ("Muestra {0} · {1:N1}/{2} s" -f $sampleNumber,$timer.Elapsed.TotalSeconds,$Seconds) -PercentComplete $pct
            }
            $samples+=Get-VSO7PerfSnapshot
            $remaining=[double]$Seconds-$timer.Elapsed.TotalSeconds
            if($remaining-gt0){
                $sleepMs=[int][math]::Min(1000,[math]::Max(1,[math]::Floor($remaining*1000)))
                if($script:GuiMode-and$null-ne$script:GuiWindow){
                    # Keep the STA dispatcher responsive while preserving the same elapsed-time
                    # sampling contract. No extra samples are introduced.
                    $left=$sleepMs
                    while($left-gt0){
                        $chunk=[math]::Min(100,$left)
                        Start-Sleep -Milliseconds $chunk
                        $left-=$chunk
                        try{[void]$script:GuiWindow.Dispatcher.Invoke([Action]{},[Windows.Threading.DispatcherPriority]::Background)}catch{}
                    }
                }else{
                    Start-Sleep -Milliseconds $sleepMs
                }
            }
        }while($timer.Elapsed.TotalSeconds-lt[double]$Seconds)
    }finally{
        $timer.Stop()
        if($null-ne$ProgressCallback){try{& $ProgressCallback 100 $sampleNumber ([double]$timer.Elapsed.TotalSeconds) $Seconds}catch{}}
        else{Write-Progress -Activity 'VSO7 - midiendo actividad de fondo' -Completed}
    }
    $elapsedSeconds=[math]::Round([double]$timer.Elapsed.TotalSeconds,2)
    $osBuild=0
    try{$osBuild=[int](CimCmdlets\Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).BuildNumber}catch{}
    $driveFree=$null
    try{
        $systemDrive=if($script:SystemDrive){[string]$script:SystemDrive}else{[IO.Path]::GetPathRoot([string]$script:WindowsRoot).TrimEnd('\')}
        $disk=CimCmdlets\Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'"-f$systemDrive) -ErrorAction Stop
        if($null-ne$disk.FreeSpace){$driveFree=[math]::Round([double]$disk.FreeSpace/1GB,2)}
    }catch{}
    return [pscustomobject]@{
        Schema=1;Product='VSO7';Version=$script:Version;Label=$Label;Timestamp=(Get-Date).ToString('o');
        RequestedSeconds=$Seconds;Seconds=$elapsedSeconds;SampleCount=@($samples).Count;WindowsBuild=$osBuild;
        CpuAvgPct=(Get-VSO7Average $samples 'CpuPct');CpuMaxPct=(Get-VSO7Maximum $samples 'CpuPct');
        DpcAvgPct=(Get-VSO7Average $samples 'DpcPct');DpcMaxPct=(Get-VSO7Maximum $samples 'DpcPct');
        InterruptsAvg=(Get-VSO7Average $samples 'InterruptsPerSec');ContextSwitchesAvg=(Get-VSO7Average $samples 'ContextSwitchesPerSec');
        QueueAvg=(Get-VSO7Average $samples 'ProcessorQueueLength');DiskTransfersAvg=(Get-VSO7Average $samples 'DiskTransfersPerSec');
        DiskReadAvgMBps=(Get-VSO7Average $samples 'DiskReadMBps');DiskWriteAvgMBps=(Get-VSO7Average $samples 'DiskWriteMBps');
        RamUsedAvgPct=(Get-VSO7Average $samples 'RamUsedPct');ProcessCountAvg=(Get-VSO7Average $samples 'ProcessCount');
        FreeDiskGB=$driveFree;Samples=$samples
    }
}

function Save-VSO7Benchmark {

    param([Parameter(Mandatory=$true)]$Benchmark)
    New-Item -ItemType Directory -Path $script:BenchmarkRoot -Force -ErrorAction Stop | Out-Null
    $stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
    $path=Join-Path $script:BenchmarkRoot ("benchmark_{0}_{1}.json" -f $stamp,$Benchmark.Label)
    $Benchmark | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $path -Encoding UTF8 -Force -ErrorAction Stop
    return $path

}

function Get-LatestVSO7Benchmark {

    param([string]$Label='')
    if(-not(Test-Path -LiteralPath $script:BenchmarkRoot)){
        return $null
    }
    $files=Get-ChildItem -LiteralPath $script:BenchmarkRoot -File -Filter 'benchmark_*.json' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending
    foreach($f in $files){

        try{

            $b=Get-Content -LiteralPath $f.FullName -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if([string]::IsNullOrWhiteSpace($Label) -or [string]$b.Label -eq $Label){
                return [pscustomobject]@{
                    Path=$f.FullName;
                    Data=$b
                }
            }

        }catch{}

    }
    return $null

}

function Get-VSO7PercentDelta {

    param([double]$Before,[double]$After)
    if([math]::Abs($Before) -lt 0.000001){
        return $null
    }
    return [math]::Round((($After-$Before)/$Before)*100,1)

}

function Compare-VSO7Benchmarks {

    param([Parameter(Mandatory=$true)]$Before,[Parameter(Mandatory=$true)]$After)
    $defs=@(@('CPU media %','CpuAvgPct','Menor'),@('CPU pico %','CpuMaxPct','Menor'),@('DPC medio %','DpcAvgPct','Menor'),@('DPC pico %','DpcMaxPct','Menor'),@('Interrupciones/s','InterruptsAvg','Menor'),@('Context switches/s','ContextSwitchesAvg','Menor'),@('Cola CPU','QueueAvg','Menor'),@('Transferencias disco/s','DiskTransfersAvg','Menor'),@('RAM usada %','RamUsedAvgPct','Menor'),@('Procesos','ProcessCountAvg','Menor'))
    $rows=@()
    foreach($d in $defs){

        $br=$Before.($d[1]);
        $ar=$After.($d[1])
        if($null-eq$br-or$null-eq$ar){
            $rows += [pscustomobject]@{
                Metrica=$d[0];
                Antes='N/D';
                Despues='N/D';
                Delta=$null;
                CambioPct=$null;
                Preferencia=$d[2];
                Resultado='NO DISPONIBLE'
            };
            continue
        }
        $b=[double]$br;
        $a=[double]$ar;
        $pct=Get-VSO7PercentDelta $b $a;
        $delta=[math]::Round($a-$b,2)
        $verdict='SIMILAR';
        if($null-ne$pct-and$pct-le-5){
            $verdict='MEJORA'
        }elseif($null-ne$pct-and$pct-ge5){
            $verdict='SUBE'
        }
        $rows += [pscustomobject]@{
            Metrica=$d[0];
            Antes=$b;
            Despues=$a;
            Delta=$delta;
            CambioPct=$pct;
            Preferencia=$d[2];
            Resultado=$verdict
        }

    }
    $script:LastBenchmarkComparison=$rows
    return $rows

}

function Export-VSO7BenchmarkHtml {

    param([Parameter(Mandatory=$true)]$Rows,[Parameter(Mandatory=$true)]$Before,[Parameter(Mandatory=$true)]$After)
    $path=Join-Path $script:ReportRoot ("VSO7_AB_{0}.html" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    $style='body{background:#0b0907;color:#eadbc8;font-family:Segoe UI,Arial;margin:36px}h1{color:#c58b52}table{border-collapse:collapse;width:100%;max-width:1050px}th,td{padding:9px;border-bottom:1px solid #4b3424;text-align:left}th{color:#e6b980}.small{color:#a58e7b}'
    $table=$Rows | Select-Object Metrica,Antes,Despues,Delta,CambioPct,Resultado | ConvertTo-Html -Fragment
    $html="<html><head><meta charset='utf-8'><style>$style</style></head><body><h1>VSO7 - Comparacion A/B</h1><p class='small'>Baseline: $($Before.Timestamp) | Post: $($After.Timestamp) | No es un benchmark de FPS; mide ruido de fondo del sistema.</p>$table</body></html>"
    Set-Content -LiteralPath $path -Value $html -Encoding UTF8 -Force
    return $path

}

function Enable-VSO7GitHubTls {

    # Windows PowerShell 5.1 puede arrancar sin TLS 1.2 habilitado en algunos equipos.
    # Esto afecta solo al proceso actual de VSO7.
    try {

        $tls12 = [Net.SecurityProtocolType]::Tls12
        if (([Net.ServicePointManager]::SecurityProtocol -band $tls12) -eq 0) {

            [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor $tls12

        }

    } catch {}

}

function ConvertTo-VSO7ValidatedPresentMonMetadata {

    param([Parameter(Mandatory=$true)]$Object)
    if($null-eq$Object){
        throw 'Metadata PresentMon vacia.'
    }
    $allowed=@('SchemaVersion','Product','InstalledBy','InstalledAt','Release','Asset','Source','DownloadUrl','Sha256','GitHubDigestVerified','FileVersion','AuthenticodeStatus')
    $props=@($Object.PSObject.Properties.Name)
    foreach($p in $props){
        if($allowed-notcontains[string]$p){
            throw ("Metadata PresentMon contiene propiedad no permitida: {0}"-f$p)
        }
    }
    foreach($p in $allowed){
        if($props-notcontains$p){
            throw ("Metadata PresentMon incompleta: falta {0}."-f$p)
        }
    }
    $schema=0;
    if(-not[int]::TryParse([string]$Object.SchemaVersion,[ref]$schema)-or$schema-ne1){
        throw 'SchemaVersion PresentMon no soportada.'
    }
    if([string]$Object.Product-ne'PresentMon'-or[string]$Object.InstalledBy-ne'VSO7'){
        throw 'Identidad de metadata PresentMon invalida.'
    }
    if($Object.GitHubDigestVerified-isnot[bool]-or-not[bool]$Object.GitHubDigestVerified){
        throw 'GitHubDigestVerified PresentMon invalido.'
    }
    $installed=[datetime]::MinValue;
    if(-not[datetime]::TryParse([string]$Object.InstalledAt,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$installed)){
        throw 'InstalledAt PresentMon invalido.'
    }
    $release=[string]$Object.Release;
    if([string]::IsNullOrWhiteSpace($release)-or$release.Length-gt128-or$release-notmatch'^[0-9A-Za-z._-]+$'){
        throw 'Release PresentMon invalida.'
    }
    $asset=[string]$Object.Asset;
    if($asset.Length-gt180-or$asset-notmatch'^PresentMon-[0-9A-Za-z._-]*x64[^\\/]*\.exe$'){
        throw 'Asset PresentMon invalido.'
    }
    $sha=[string]$Object.Sha256;
    if($sha-notmatch'^[0-9A-Fa-f]{64}$'){
        throw 'SHA-256 PresentMon invalido.'
    };
    $sha=$sha.ToUpperInvariant()
    $download=$null;
    try{
        $download=[Uri][string]$Object.DownloadUrl
    }catch{
        throw 'DownloadUrl PresentMon invalida.'
    }
    if($download.Scheme-ne'https'-or$download.Host-ne'github.com'-or$download.AbsolutePath-notlike'/GameTechDev/PresentMon/releases/download/*'){
        throw 'DownloadUrl PresentMon fuera del origen oficial.'
    }
    $source=$null;
    try{
        $source=[Uri][string]$Object.Source
    }catch{
        throw 'Source PresentMon invalida.'
    }
    if($source.Scheme-ne'https'-or$source.Host-ne'github.com'-or$source.AbsolutePath-notlike'/GameTechDev/PresentMon/releases/*'){
        throw 'Source PresentMon fuera del origen oficial.'
    }
    $fileVersion=[string]$Object.FileVersion;
    if($fileVersion.Length-gt128){
        throw 'FileVersion PresentMon demasiado larga.'
    }
    $auth=[string]$Object.AuthenticodeStatus;
    if($auth.Length-gt64){
        throw 'AuthenticodeStatus PresentMon demasiado largo.'
    }
    return [pscustomobject][ordered]@{

        SchemaVersion=1;
        Product='PresentMon';
        InstalledBy='VSO7';
        InstalledAt=$installed.ToString('o');
        Release=$release;
        Asset=$asset;

        Source=$source.AbsoluteUri;
        DownloadUrl=$download.AbsoluteUri;
        Sha256=$sha;
        GitHubDigestVerified=$true;
        FileVersion=$fileVersion;
        AuthenticodeStatus=$auth

    }

}

function Get-VSO7PresentMonMetadata {

    try{

        [void](Protect-VSO7SecureDirectory -Path $script:PresentMonRoot)
        [void](Assert-VSO7ProtectedDirectChildFileVSO -Path $script:PresentMonMetaFile -AllowedParent $script:PresentMonRoot)
        $item=Get-Item -LiteralPath $script:PresentMonMetaFile -Force -ErrorAction Stop
        if([int64]$item.Length-gt256KB){
            throw 'presentmon-meta.json excede el tamano permitido.'
        }
        $raw=Get-Content -LiteralPath $script:PresentMonMetaFile -Raw -ErrorAction Stop
        return (ConvertTo-VSO7ValidatedPresentMonMetadata -Object ($raw|ConvertFrom-Json -ErrorAction Stop))

    }catch{
        return $null
    }

}

function Test-VSO7PresentMonTrusted {

    param([switch]$Quiet,[switch]$RequireGitHubDigest)
    try{

        $root=Protect-VSO7SecureDirectory -Path $script:PresentMonRoot
        if([IO.Path]::GetFullPath($root).TrimEnd('\')-ine[IO.Path]::GetFullPath($script:PresentMonRoot).TrimEnd('\')){
            throw 'PresentMonRoot inesperado.'
        }
        [void](Protect-VSO7ProtectedFileVSO -Path $script:PresentMonExe -AllowedParent $root)
        [void](Protect-VSO7ProtectedFileVSO -Path $script:PresentMonMetaFile -AllowedParent $root)
        $meta=Get-VSO7PresentMonMetadata
        if($null-eq$meta){
            return $false
        }
        $expected=[string]$meta.Sha256
        if($RequireGitHubDigest){

            $online=Get-VSO7LatestPresentMonRelease
            if([string]$online.Tag-ne[string]$meta.Release -or [string]$online.Name-ne[string]$meta.Asset -or [string]$online.Url-ne[string]$meta.DownloadUrl -or [string]$online.Sha256-ne$expected){

                if(-not$Quiet){
                    Write-VSO7Log 'PresentMon protegido rechazado: metadata/digest no coincide con la release estable actual de GitHub.' 'ERROR'
                }
                return $false

            }

        }
        # Revalidar el mismo leaf protegido inmediatamente antes de devolver confianza.
        [void](Assert-VSO7ProtectedDirectChildFileVSO -Path $script:PresentMonExe -AllowedParent $root)
        $actual=(Get-FileHash -LiteralPath $script:PresentMonExe -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($actual-ne$expected){
            if(-not$Quiet){
                Write-VSO7Log 'PresentMon protegido rechazado: SHA-256 actual no coincide con metadata.' 'ERROR'
            };
            return $false
        }
        return $true

    }catch{
        if(-not$Quiet){
            Write-VSO7Log ("PresentMon protegido no pudo validarse: {0}"-f$_.Exception.Message) 'ERROR'
        };
        return $false
    }

}

function Find-VSO7PresentMon {

    if(Test-VSO7PresentMonTrusted -Quiet){
        return [IO.Path]::GetFullPath($script:PresentMonExe)
    }
    return $null

}

function Get-VSO7LatestPresentMonRelease {

    Enable-VSO7GitHubTls
    $headers = @{

        'Accept' = 'application/vnd.github+json'
        'User-Agent' = ('VSO7/{0} PresentMon downloader' -f $script:Version)
        'X-GitHub-Api-Version' = '2026-03-10'

    }
    $release = Invoke-RestMethod -Uri $script:PresentMonApi -Method Get -Headers $headers -ErrorAction Stop
    if ($null -eq $release -or [bool]$release.draft -or [bool]$release.prerelease) {

        throw 'GitHub no devolvio una release estable valida de PresentMon.'

    }

    $assets = @($release.assets)
    $asset = $assets | Where-Object {

        ([string]$_.state -eq 'uploaded') -and ([string]$_.name -match '^PresentMon-[0-9][0-9A-Za-z._-]*-x64\.exe$')

    } | Select-Object -First 1
    if ($null -eq $asset) {

        $asset = $assets | Where-Object {

            ([string]$_.state -eq 'uploaded') -and ([string]$_.name -match '^PresentMon-.*x64.*\.exe$')

        } | Select-Object -First 1

    }
    if ($null -eq $asset) {
        throw 'La release oficial no contiene un binario PresentMon x64 reconocido.'
    }

    $digest = [string]$asset.digest
    if ($digest -notmatch '^sha256:([0-9a-fA-F]{64})$') {

        throw 'GitHub no proporciono un digest SHA-256 verificable para este asset. VSO7 no lo instalara.'

    }
    $expectedHash = $Matches[1].ToUpperInvariant()

    $downloadUrl = [string]$asset.browser_download_url
    $uri = $null
    try {
        $uri = [Uri]$downloadUrl
    } catch {
        throw 'La URL de descarga devuelta por GitHub no es valida.'
    }
    if ($uri.Scheme -ne 'https' -or $uri.Host -ne 'github.com' -or $uri.AbsolutePath -notlike '/GameTechDev/PresentMon/releases/download/*') {

        throw 'VSO7 rechazo una URL de descarga que no pertenece a la release oficial GameTechDev/PresentMon.'

    }

    return [pscustomobject]@{

        Tag = [string]$release.tag_name
        Name = [string]$asset.name
        Url = $downloadUrl
        Size = [int64]$asset.size
        Sha256 = $expectedHash
        PublishedAt = [string]$release.published_at
        ReleaseUrl = [string]$release.html_url

    }

}

function Install-VSO7PresentMon {

    param([switch]$Force)
    Write-Title;
    Write-CenteredLineVSO -Text $(Get-VSO7ConsoleTextVSO -Es 'PRESENTMON - INSTALACION PROTEGIDA' -En 'PRESENTMON - PROTECTED INSTALLATION') -Color $script:ThemeCopper
    Write-CenteredLineVSO -Text 'Fuente: GitHub oficial GameTechDev/PresentMon. No se instala nada globalmente.' -Color $script:ThemeText
    Write-CenteredLineVSO -Text 'El binario se guarda en el almacenamiento protegido de VSO7 dentro de ProgramData.' -Color $script:ThemeMuted;
    Write-VSOHost ''
    $existing=Find-VSO7PresentMon
    if($existing-and-not$Force){
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'PresentMon ya esta disponible y verificado: {0}' -En 'PresentMon is already available and verified: {0}')-f$existing) -ForegroundColor Green;
        return $existing
    }
    $root=$null;
    $temp=$null;
    $metaTemp=$null
    try{

        $root=Protect-VSO7SecureDirectory -Path $script:PresentMonRoot
        if([IO.Path]::GetFullPath($root).TrimEnd('\')-ine[IO.Path]::GetFullPath($script:PresentMonRoot).TrimEnd('\')){
            throw 'PresentMonRoot inesperado.'
        }
        [void](Protect-VSO7ProtectedFileVSO -Path $script:PresentMonExe -AllowedParent $root -AllowMissing)
        [void](Protect-VSO7ProtectedFileVSO -Path $script:PresentMonMetaFile -AllowedParent $root -AllowMissing)
        Write-VSOHost 'Consultando la release estable mas reciente...' -ForegroundColor Cyan
        $info=Get-VSO7LatestPresentMonRelease
        if($info.Size-le0-or$info.Size-gt200MB){
            throw 'El tamano anunciado del asset es invalido o inesperado.'
        }
        $token=[guid]::NewGuid().ToString('N')
        $temp=Join-Path $root ('.PresentMon.download.{0}.tmp'-f$token)
        $metaTemp=Join-Path $root ('.PresentMon.meta.{0}.tmp'-f$token)
        foreach($x in @($temp,$metaTemp)){
            [void](Assert-VSO7ProtectedDirectChildFileVSO -Path $x -AllowedParent $root -AllowMissing);
            if(Test-Path -LiteralPath $x){
                throw 'Colision inesperada de staging PresentMon.'
            }
        }

        Invoke-WebRequest -Uri $info.Url -OutFile $temp -Headers @{
            'User-Agent'=('VSO7/{0} PresentMon downloader'-f$script:Version)
        } -UseBasicParsing -ErrorAction Stop
        [void](Protect-VSO7ProtectedFileVSO -Path $temp -AllowedParent $root)
        $downloaded=Get-Item -LiteralPath $temp -Force -ErrorAction Stop
        if([int64]$downloaded.Length-ne[int64]$info.Size){
            throw 'Tamano descargado inesperado.'
        }
        $actualHash=(Get-FileHash -LiteralPath $temp -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        if($actualHash-ne$info.Sha256){
            throw 'SHA-256 descargado no coincide con el digest de GitHub.'
        }
        $fileInfo=[Diagnostics.FileVersionInfo]::GetVersionInfo($temp)
        $signatureStatus='No comprobada';
        try{
            $signatureStatus=[string](Get-AuthenticodeSignature -FilePath $temp -ErrorAction Stop).Status
        }catch{}
        $meta=[ordered]@{
            SchemaVersion=1;
            Product='PresentMon';
            InstalledBy='VSO7';
            InstalledAt=(Get-Date).ToString('o');
            Release=$info.Tag;
            Asset=$info.Name;
            Source=$info.ReleaseUrl;
            DownloadUrl=$info.Url;
            Sha256=$actualHash;
            GitHubDigestVerified=$true;
            FileVersion=[string]$fileInfo.FileVersion;
            AuthenticodeStatus=$signatureStatus
        }
        $validatedMeta=ConvertTo-VSO7ValidatedPresentMonMetadata -Object ([pscustomobject]$meta)
        $validatedMeta|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $metaTemp -Encoding UTF8 -Force -ErrorAction Stop
        [void](Protect-VSO7ProtectedFileVSO -Path $metaTemp -AllowedParent $root)
        [void](ConvertTo-VSO7ValidatedPresentMonMetadata -Object (Get-Content -LiteralPath $metaTemp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop))

        # EXE y metadata se reemplazan individualmente de forma atomica dentro del
        # directorio protegido. Si el proceso muere entre ambos commits, el par no
        # coincidira y Test-VSO7PresentMonTrusted lo rechazara hasta reinstalar.
        [void](Commit-VSO7AtomicFileVSO -SourcePath $temp -DestinationPath $script:PresentMonExe);
        $temp=$null
        [void](Commit-VSO7AtomicFileVSO -SourcePath $metaTemp -DestinationPath $script:PresentMonMetaFile);
        $metaTemp=$null
        if((Get-FileHash -LiteralPath $script:PresentMonExe -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()-ne$actualHash){
            throw 'El binario instalado cambio despues del movimiento final.'
        }
        if(-not(Test-VSO7PresentMonTrusted)){
            throw 'PresentMon no supero la revalidacion final de confianza.'
        }
        Write-VSOHost '';
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es '[OK] PresentMon {0} instalado y revalidado en almacenamiento protegido.' -En '[OK] PresentMon {0} was installed and revalidated in protected storage.')-f$info.Tag) -ForegroundColor Green;
        Write-VSOHost ("SHA256: {0}"-f$actualHash) -ForegroundColor DarkGray;
        Write-VSO7Log ("PresentMon {0} instalado en ProgramData protegido; SHA256 {1}."-f$info.Tag,$actualHash) 'CHANGE';
        return $script:PresentMonExe

    }catch{

        $installError=$_.Exception.Message
        try{
            foreach($x in @($temp,$metaTemp)){
                if($x-and(Test-Path -LiteralPath $x)){
                    [void](Assert-VSO7ProtectedDirectChildFileVSO -Path $x -AllowedParent $root);
                    Remove-Item -LiteralPath $x -Force -ErrorAction SilentlyContinue
                }
            }
        }catch{}
        Write-VSOHost '';
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'No se pudo instalar PresentMon: {0}' -En 'PresentMon could not be installed: {0}')-f$installError) -ForegroundColor Red;
        Write-VSO7Log ("Fallo instalando PresentMon: {0}"-f$installError) 'ERROR';
        return $null

    }

}

function Ensure-VSO7PresentMon {

    $pm = Find-VSO7PresentMon
    if ($pm) {
        return $pm
    }

    Write-VSOHost ''
    Write-VSOHost 'PresentMon no esta instalado en VSO7.' -ForegroundColor Yellow
    Write-VSOHost 'VSO7 puede descargar automaticamente el binario x64 desde la release oficial de GameTechDev/PresentMon,' -ForegroundColor Gray
    Write-VSOHost 'verificar su SHA-256 con el digest publicado por GitHub y guardarlo en ProgramData protegido.' -ForegroundColor Gray
    $answer = Read-VSOHost '¿Descargar e instalar PresentMon ahora? [S/N]'
    if ($answer -notmatch '^[sSyY]$') {
        return $null
    }
    return (Install-VSO7PresentMon -Force)

}

function Show-VSO7PresentMonManager {

    while ($true) {

        Write-Title
        Write-CenteredLineVSO -Text 'PRESENTMON' -Color $script:ThemeCopper
        $pm = Find-VSO7PresentMon
        $meta = Get-VSO7PresentMonMetadata
        if ($pm) {

            Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Estado: INSTALADO | {0}' -En 'Status: INSTALLED | {0}') -f $pm) -Color 'Green'
            if ($meta -and $meta.Release) {
                Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Release registrada: {0}' -En 'Registered release: {0}') -f $meta.Release) -Color $script:ThemeText
            }

        } else {

            Write-CenteredLineVSO -Text 'Estado: NO INSTALADO' -Color 'Yellow'

        }
        Write-VSOHost ''
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text='[1] Descargar e instalar la ultima release estable de PresentMon';Color='Cyan';Description='Descarga PresentMon desde su fuente configurada, verifica lo esperado y lo prepara para mediciones de FPS.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[2] Comprobar si hay una version nueva de PresentMon' -En '[2] Check for a new PresentMon version');Color='Green';Description='Compara la version instalada y solo ofrece actualizar si hay una release mas reciente.'
        },
            [pscustomobject]@{
            Text='[3] Ver version y SHA-256 de PresentMon';Color='Gray';Description='Solo lectura: muestra que binario tiene VSO7 y su huella SHA-256.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';SeparatorBefore=$true
        }
        )
        $c = Read-CenteredPromptVSO -Text 'Opcion'
        if ($c -eq '0') {
            return
        }
        if ($c -eq '1') {
            [void](Install-VSO7PresentMon -Force);
            Pause-Vico;
            continue
        }
        if ($c -eq '2') {

            try {

                $latest = Get-VSO7LatestPresentMonRelease
                $current = Get-VSO7PresentMonMetadata
                if ((Find-VSO7PresentMon) -and $current -and ([string]$current.Release -eq [string]$latest.Tag)) {

                    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Ya tienes la release mas reciente: {0}.' -En 'You already have the latest release: {0}.') -f $latest.Tag) -ForegroundColor Green

                } else {

                    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Release disponible: {0}.' -En 'Available release: {0}.') -f $latest.Tag) -ForegroundColor Cyan
                    if ((Read-VSOHost '¿Descargar/verificar/actualizar ahora? [S/N]') -match '^[sSyY]$') {
                        [void](Install-VSO7PresentMon -Force)
                    }

                }

            } catch {
                Write-VSOHost $_.Exception.Message -ForegroundColor Red
            }
            Pause-Vico;
            continue

        }
        if ($c -eq '3') {

            $pm = Find-VSO7PresentMon
            if (-not $pm) {
                Write-VSOHost 'PresentMon no esta instalado.' -ForegroundColor Yellow
            }
            else {

                Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Ruta: {0}' -En 'Path: {0}') -f $pm) -ForegroundColor Gray
                try {
                    Write-VSOHost ((Get-FileHash -LiteralPath $pm -Algorithm SHA256|Format-List|Out-String -Width 220).TrimEnd())
                } catch {}
                $meta = Get-VSO7PresentMonMetadata
                if ($meta) {
                    Write-VSOHost (($meta|Format-List|Out-String -Width 220).TrimEnd())
                }

            }
            Pause-Vico

        }

    }

}

# Latency / hardware diagnostics and multi-target state
function Get-VSO7AggregateTargetStateVSO {

    param([Parameter(Mandatory=$true)][AllowEmptyCollection()][array]$Targets)
    $items=@($Targets)
    if($items.Count-eq0){
        return [pscustomobject]@{
            Aggregate='Unsupported';
            Counts=@{};
            Targets=@()
        }
    }
    $states=@($items|ForEach-Object{
        if($_.PSObject.Properties.Name-contains'State'){
            [string]$_.State
        }else{
            [string]$_
        }
    })
    $counts=@{}
    foreach($s in $states){
        if([string]::IsNullOrWhiteSpace($s)){
            $s='Error'
        };
        if(-not$counts.ContainsKey($s)){
            $counts[$s]=0
        };
        $counts[$s]=[int]$counts[$s]+1
    }
    $aggregate=$null
    foreach($priority in @('Error','Ambiguous','Drift')){

        if($counts.ContainsKey($priority)){
            $aggregate=$priority;
            break
        }

    }
    if($null-eq$aggregate){

        $unique=@($states|Select-Object -Unique)
        if($unique.Count-eq1){
            $aggregate=[string]$unique[0]
        }
        elseif($counts.ContainsKey('PendingRestart')){
            $aggregate='PendingRestart'
        }
        else{
            $aggregate='Partial'
        }

    }
    return [pscustomobject]@{
        Aggregate=$aggregate;
        Counts=$counts;
        Targets=$items
    }

}

function Initialize-VSO7CpuSetNativeVSO {

    if(('VsoR9CpuSetNative'-as[type]) -ne $null){
        return
    }
    $src=@"
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;

public static class VsoR9CpuSetNative {
    [DllImport("kernel32.dll", SetLastError=true)]
    private static extern bool GetSystemCpuSetInformation(
        IntPtr Information,
        uint BufferLength,
        out uint ReturnedLength,
        IntPtr Process,
        uint Flags);

    public sealed class Entry {
        public uint Size;
        public uint Type;
        public uint Id;
        public ushort Group;
        public byte LogicalProcessorIndex;
        public byte CoreIndex;
        public byte LastLevelCacheIndex;
        public byte NumaNodeIndex;
        public byte EfficiencyClass;
        public byte AllFlags;
        public byte SchedulingClass;
        public ulong AllocationTag;
        public bool Parked;
        public bool Allocated;
        public bool AllocatedToTargetProcess;
        public bool RealTime;
    }

    public static Entry[] Query() {
        uint needed=0;
        GetSystemCpuSetInformation(IntPtr.Zero,0,out needed,IntPtr.Zero,0);
        if(needed==0) return new Entry[0];
        IntPtr buffer=Marshal.AllocHGlobal((int)needed);
        try {
            uint returned=0;
            if(!GetSystemCpuSetInformation(buffer,needed,out returned,IntPtr.Zero,0)) {
                throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
            }
            List<Entry> result=new List<Entry>();
            long offset=0;
            while(offset+8<=returned) {
                IntPtr p=IntPtr.Add(buffer,(int)offset);
                uint size=(uint)Marshal.ReadInt32(p,0);
                uint type=(uint)Marshal.ReadInt32(p,4);
                if(size<8 || offset+size>returned) break;
                if(type==0 && size>=32) {
                    Entry e=new Entry();
                    e.Size=size;e.Type=type;
                    e.Id=(uint)Marshal.ReadInt32(p,8);
                    e.Group=(ushort)Marshal.ReadInt16(p,12);
                    e.LogicalProcessorIndex=Marshal.ReadByte(p,14);
                    e.CoreIndex=Marshal.ReadByte(p,15);
                    e.LastLevelCacheIndex=Marshal.ReadByte(p,16);
                    e.NumaNodeIndex=Marshal.ReadByte(p,17);
                    e.EfficiencyClass=Marshal.ReadByte(p,18);
                    e.AllFlags=Marshal.ReadByte(p,19);
                    e.SchedulingClass=Marshal.ReadByte(p,20);
                    e.AllocationTag=(ulong)Marshal.ReadInt64(p,24);
                    e.Parked=(e.AllFlags&1)!=0;
                    e.Allocated=(e.AllFlags&2)!=0;
                    e.AllocatedToTargetProcess=(e.AllFlags&4)!=0;
                    e.RealTime=(e.AllFlags&8)!=0;
                    result.Add(e);
                }
                offset+=size;
            }
            return result.ToArray();
        } finally { Marshal.FreeHGlobal(buffer); }
    }
}
"@
    Add-Type -TypeDefinition $src -Language CSharp -ErrorAction Stop

}

function ConvertFrom-VSO7CpuSetTopologyVSO {

    param([Parameter(Mandatory=$true)][AllowNull()][AllowEmptyCollection()][array]$CpuSets)
    $sets=@($CpuSets|Where-Object{
        $null-ne$_
    })
    if($sets.Count-eq0){
        return [pscustomobject]@{
            Available=$false;
            Error='No CPU sets returned';
            LogicalProcessors=0;
            PhysicalCores=0;
            Groups=0;
            SMT=$null;
            Heterogeneous=$null;
            EfficiencyClasses=@();
            CpuSets=@()
        }
    }
    $required=@('Id','Group','LogicalProcessorIndex','CoreIndex','LastLevelCacheIndex','NumaNodeIndex','EfficiencyClass','SchedulingClass','Parked','Allocated','RealTime')
    foreach($set in $sets){
        if(@($required|Where-Object{
            $set.PSObject.Properties.Name-notcontains$_
        }).Count-gt0){
            return [pscustomobject]@{
                Available=$false;
                Error='Malformed CPU set data';
                LogicalProcessors=0;
                PhysicalCores=0;
                Groups=0;
                SMT=$null;
                Heterogeneous=$null;
                EfficiencyClasses=@();
                CpuSets=@()
            }
        }
    }
    $coreKeys=@($sets|ForEach-Object{
        ("{0}:{1}"-f[int]$_.Group,[int]$_.CoreIndex)
    }|Select-Object -Unique)
    $groups=@($sets|ForEach-Object{
        [int]$_.Group
    }|Select-Object -Unique)
    $eff=@($sets|ForEach-Object{
        [int]$_.EfficiencyClass
    }|Select-Object -Unique|Sort-Object)
    return [pscustomobject]@{

        Available=$true;
        Error=$null;
        LogicalProcessors=$sets.Count;
        PhysicalCores=$coreKeys.Count;
        Groups=$groups.Count
        SMT=($sets.Count-gt$coreKeys.Count);
        Heterogeneous=($eff.Count-gt1);
        EfficiencyClasses=$eff
        CpuSets=@($sets|ForEach-Object{
            [pscustomobject]@{
                Id=[uint32]$_.Id;Group=[int]$_.Group;LogicalProcessorIndex=[int]$_.LogicalProcessorIndex;CoreIndex=[int]$_.CoreIndex;LastLevelCacheIndex=[int]$_.LastLevelCacheIndex;NumaNodeIndex=[int]$_.NumaNodeIndex;EfficiencyClass=[int]$_.EfficiencyClass;SchedulingClass=[int]$_.SchedulingClass;Parked=[bool]$_.Parked;Allocated=[bool]$_.Allocated;RealTime=[bool]$_.RealTime
            }
        })

    }

}

function Get-VSO7CpuTopologyVSO {

    try{

        Initialize-VSO7CpuSetNativeVSO
        $sets=@([VsoR9CpuSetNative]::Query())

    }catch{

        return [pscustomobject]@{
            Available=$false;
            Error=$_.Exception.Message;
            LogicalProcessors=$null;
            PhysicalCores=$null;
            Groups=$null;
            SMT=$null;
            Heterogeneous=$null;
            EfficiencyClasses=@();
            CpuSets=@()
        }

    }
    return (ConvertFrom-VSO7CpuSetTopologyVSO -CpuSets $sets)

}

function Get-VSO7DpcIsrOverviewVSO {

    param([ValidateRange(1,20)][int]$Samples=5,[ValidateRange(0,5000)][int]$IntervalMs=250)
    $rows=@()
    for($i=0;$i-lt$Samples;$i++){

        try{

            $x=CimCmdlets\Get-CimInstance -ClassName Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop
            $rows+=[pscustomobject]@{

                PercentDPCTime=[double]$x.PercentDPCTime
                PercentInterruptTime=[double]$x.PercentInterruptTime
                InterruptsPersec=[double]$x.InterruptsPersec
                DPCsQueuedPersec=[double]$x.DPCsQueuedPersec

            }

        }catch{}
        if($i+1-lt$Samples-and$IntervalMs-gt0){
            Start-Sleep -Milliseconds $IntervalMs
        }

    }
    if($rows.Count-eq0){
        return [pscustomobject]@{
            Available=$false;
            Samples=0;
            Error='Win32_PerfFormattedData_PerfOS_Processor unavailable';
            DriverAttribution='UnavailableWithoutEtwTrace'
        }
    }
    $avgDpc=[double](($rows|Measure-Object PercentDPCTime -Average).Average)
    $maxDpc=[double](($rows|Measure-Object PercentDPCTime -Maximum).Maximum)
    $avgIsr=[double](($rows|Measure-Object PercentInterruptTime -Average).Average)
    $maxIsr=[double](($rows|Measure-Object PercentInterruptTime -Maximum).Maximum)
    $avgInt=[double](($rows|Measure-Object InterruptsPersec -Average).Average)
    $avgQueued=[double](($rows|Measure-Object DPCsQueuedPersec -Average).Average)
    $wpr=Get-Command 'wpr.exe' -ErrorAction SilentlyContinue
    $xperf=Get-Command 'xperf.exe' -ErrorAction SilentlyContinue
    return [pscustomobject]@{

        Available=$true;
        Samples=$rows.Count
        DpcAvgPct=[math]::Round($avgDpc,3);
        DpcMaxPct=[math]::Round($maxDpc,3)
        IsrAvgPct=[math]::Round($avgIsr,3);
        IsrMaxPct=[math]::Round($maxIsr,3)
        InterruptsPerSecAvg=[math]::Round($avgInt,1);
        DpcQueuedPerSecAvg=[math]::Round($avgQueued,1)
        EtwWprAvailable=($null-ne$wpr);
        EtwXperfAvailable=($null-ne$xperf)
        DriverAttribution=if($null-ne$xperf){
            'AvailableWithExplicitEtwTrace'
        }elseif($null-ne$wpr){
            'TraceCaptureAvailable;AttributionRequiresAnalyzer'
        }else{
            'UnavailableWithoutEtwTrace'
        }

    }

}

function ConvertTo-VSO7HexBytesVSO {

    param([AllowNull()]$Value)
    if($null-eq$Value){
        return $null
    }
    if($Value-is[byte[]]){
        return (($Value|ForEach-Object{
            $_.ToString('X2')
        })-join'')
    }
    return [string]$Value

}

function Get-VSO7InterruptOverrideStateVSO {

    param([bool]$MsiValueExists,[AllowNull()]$MsiValue,[AllowNull()]$DevicePolicy,[AllowNull()][string]$AssignmentSetOverride)
    $msiState=if(-not$MsiValueExists){
        'InheritedOrDriverDefault'
    }elseif([int]$MsiValue-eq1){
        'ExplicitEnabled'
    }elseif([int]$MsiValue-eq0){
        'ExplicitDisabled'
    }else{
        'UnknownExplicitValue'
    }
    $affinityState=if($null-eq$DevicePolicy-and[string]::IsNullOrWhiteSpace($AssignmentSetOverride)){
        'InheritedOrDriverDefault'
    }else{
        'ExplicitOverride'
    }
    return [pscustomobject]@{
        MsiOverrideState=$msiState;
        AffinityOverrideState=$affinityState
    }

}

function Get-VSO7InterruptDeviceInventoryVSO {

    $result=@()
    $devices=@()
    try{
        $devices=@(CimCmdlets\Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction Stop)
    }catch{
        return @()
    }
    foreach($d in $devices){

        $id=[string]$d.PNPDeviceID
        if([string]::IsNullOrWhiteSpace($id)){
            continue
        }
        $cls=[string]$d.PNPClass
        if($cls-notin @('Display','Net','MEDIA','USB','SCSIAdapter','HDC','System')){
            continue
        }
        $base=('Registry::HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Enum\{0}\Device Parameters\Interrupt Management'-f$id)
        $msg=Join-Path $base 'MessageSignaledInterruptProperties'
        $aff=Join-Path $base 'Affinity Policy'
        $msiExists=$false;
        $msi=$null;
        $limit=$null
        try{

            $p=Get-ItemProperty -LiteralPath $msg -ErrorAction Stop
            if($p.PSObject.Properties.Name-contains'MSISupported'){
                $msiExists=$true;
                $msi=[int]$p.MSISupported
            }
            if($p.PSObject.Properties.Name-contains'MessageNumberLimit'){
                $limit=[int]$p.MessageNumberLimit
            }

        }catch{}
        $policy=$null;
        $mask=$null
        try{

            $a=Get-ItemProperty -LiteralPath $aff -ErrorAction Stop
            if($a.PSObject.Properties.Name-contains'DevicePolicy'){
                $policy=[int]$a.DevicePolicy
            }
            if($a.PSObject.Properties.Name-contains'AssignmentSetOverride'){
                $mask=ConvertTo-VSO7HexBytesVSO $a.AssignmentSetOverride
            }

        }catch{}
        $overrideClass=Get-VSO7InterruptOverrideStateVSO -MsiValueExists:$msiExists -MsiValue $msi -DevicePolicy $policy -AssignmentSetOverride $mask
        $result+=[pscustomobject]@{

            Name=[string]$d.Name;
            Class=$cls;
            PnPDeviceId=$id;
            Status=[string]$d.Status
            MsiOverride=if($msiExists){
                $msi
            }else{
                $null
            }
            MsiOverrideState=[string]$overrideClass.MsiOverrideState
            MessageNumberLimit=$limit
            AffinityDevicePolicy=$policy;
            AssignmentSetOverride=$mask
            AffinityOverrideState=[string]$overrideClass.AffinityOverrideState

        }

    }
    return @($result)

}

function Get-VSO7NicInterruptCapabilityVSO {

