                Name=[string]$_.Name;InterfaceDescription=[string]$_.InterfaceDescription
                MsiSupported=$_.MsiSupported;MsiEnabled=$_.MsiEnabled;MsiXSupported=$_.MsiXSupported;MsiXEnabled=$_.MsiXEnabled
                NumMsiMessages=$_.NumMsiMessages;NumMsixTableEntries=$_.NumMsixTableEntries;NumaNode=$_.NumaNode
                MsiXMessageAffinity=@($_.MsixMessageAffinityArray)

