        return @()
    }

}

function Get-VSO7CimReferenceDeviceIdVSO {

    param([AllowNull()]$Reference)
    if($null-eq$Reference){
        return $null
    }
    try{

        $prop=$Reference.PSObject.Properties['DeviceID']
        if($null-ne$prop-and-not[string]::IsNullOrWhiteSpace([string]$prop.Value)){
            return [string]$prop.Value
        }

    }catch{}
    $raw=[string]$Reference
    if($raw-match 'DeviceID="(.+)"'){
        return ([string]$matches[1]-replace '\\\\','\')
    }
    return $null

}

function Get-VSO7UsbTopologyVSO {

    $controllers=@()
    try{
        $controllers=@(CimCmdlets\Get-CimInstance -ClassName Win32_USBController -ErrorAction Stop)
    }catch{
        return @()
    }
    $associations=@()
    try{
        $associations=@(CimCmdlets\Get-CimInstance -ClassName Win32_USBControllerDevice -ErrorAction Stop)
    }catch{}
    $entities=@()
    try{
        $entities=@(CimCmdlets\Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction Stop)
    }catch{}
    $controllerMap=@{};
    $entityMap=@{}
    foreach($c in $controllers){
        $k=[string]$c.DeviceID;
        if(-not[string]::IsNullOrWhiteSpace($k)){
            $controllerMap[$k.ToUpperInvariant()]=$c
        }
    }
    foreach($e in $entities){
        $k=[string]$e.PNPDeviceID;
        if(-not[string]::IsNullOrWhiteSpace($k)){
            $entityMap[$k.ToUpperInvariant()]=$e
        }
    }
    $rows=@()
    foreach($a in $associations){

        # Win32_USBControllerDevice is an association: Antecedent and Dependent are
        # CIM references. Prefer the referenced DeviceID directly; parse the legacy
        # reference string only as a compatibility fallback.
        $cid=Get-VSO7CimReferenceDeviceIdVSO -Reference $a.Antecedent
        $did=Get-VSO7CimReferenceDeviceIdVSO -Reference $a.Dependent
        if([string]::IsNullOrWhiteSpace($cid)-or[string]::IsNullOrWhiteSpace($did)){
            continue
        }
        $c=$null;
        $e=$null
        if($controllerMap.ContainsKey($cid.ToUpperInvariant())){
            $c=$controllerMap[$cid.ToUpperInvariant()]
        }
        if($entityMap.ContainsKey($did.ToUpperInvariant())){
            $e=$entityMap[$did.ToUpperInvariant()]
        }
        $name=if($null-ne$e){
            [string]$e.Name
        }else{
            $did
        }
        $pclass=if($null-ne$e){
            [string]$e.PNPClass
        }else{
            ''
        }
        $lower=([string]$name).ToLowerInvariant()
        $kind='Unknown'
        if($pclass-ieq'HIDClass'-or$lower-match'mouse|keyboard|game controller|controller'){
            $kind='Input/HID'
        }
        elseif($pclass-ieq'MEDIA'-or$lower-match'audio|headset|microphone'){
            $kind='Audio'
        }
        elseif($pclass-ieq'DiskDrive'-or$lower-match'storage|disk|flash'){
            $kind='Storage'
        }
        elseif($pclass-ieq'USB'-and$lower-match'hub'){
            $kind='Hub'
        }
        elseif($pclass-ieq'USB'){
            $kind='USB device'
        }
        $rows+=[pscustomobject]@{

            Controller=if($null-ne$c){
                [string]$c.Name
            }else{
                $cid
            };
            ControllerId=$cid
            Device=$name;
            DeviceId=$did;
            PnPClass=$pclass;
            Classification=$kind
            Status=if($null-ne$e){
                [string]$e.Status
            }else{
                $null
            }
            AssociationResolution=if($null-ne$c-and$null-ne$e){
                'CimReferenceResolved'
            }elseif($null-ne$c){
                'ControllerResolved'
            }else{
                'ReferenceOnly'
            }

        }

    }
    return @($rows|Sort-Object ControllerId,DeviceId -Unique)

}

function Get-VSO7UsbPowerDiagnosticVSO {

