            [pscustomobject]@{

                Name=[string]$_.Name;DeviceID=[string]$_.DeviceID;Status=[string]$_.Status
                PowerManagementSupported=$_.PowerManagementSupported
                ConfigManagerErrorCode=$_.ConfigManagerErrorCode

            }

        })

    }catch{}
    return [pscustomobject]@{

        SelectiveSuspendAC=if($null-ne$power){
            $power.AC
        }else{
