        }
        SelectiveSuspendDC=if($null-ne$power){
            $power.DC
        }else{
            $null
        }
        Hubs=$hubs
        Recommendation='DiagnosticOnly'
        Note='Windows generally recommends keeping USB selective suspend enabled; VSO7 does not expose a global disable-everything action here.'

    }

}

