            try{
                $r=Get-StorageReliabilityCounter -PhysicalDisk $d -ErrorAction Stop
            }catch{}

        }
        $out+=[pscustomobject]@{

            FriendlyName=[string]$d.FriendlyName;
            SerialNumber=[string]$d.SerialNumber;
            MediaType=[string]$d.MediaType;
            BusType=[string]$d.BusType
            HealthStatus=[string]$d.HealthStatus;
            OperationalStatus=(@($d.OperationalStatus)-join',');
            SizeGB=[math]::Round(([double]$d.Size/1GB),2)
            Temperature=if($null-ne$r){
                $r.Temperature
            }else{
                $null
            };
            TemperatureMax=if($null-ne$r){
                $r.TemperatureMax
            }else{
                $null
            }
            Wear=if($null-ne$r){
                $r.Wear
            }else{
                $null
            };
            PowerOnHours=if($null-ne$r){
                $r.PowerOnHours
            }else{
                $null
            }
            ReadErrorsTotal=if($null-ne$r){
                $r.ReadErrorsTotal
            }else{
                $null
            };
            WriteErrorsTotal=if($null-ne$r){
                $r.WriteErrorsTotal
            }else{
                $null
            }
            ReadErrorsUncorrected=if($null-ne$r){
                $r.ReadErrorsUncorrected
            }else{
                $null
            };
            WriteErrorsUncorrected=if($null-ne$r){
                $r.WriteErrorsUncorrected
            }else{
                $null
            }
            ReliabilityCountersAvailable=($null-ne$r)

        }

    }
    return $out

}

