}

function Get-VSO7WifiMediumClassificationVSO {

    param([AllowNull()]$NdisPhysicalMedium,[AllowNull()]$NdisMedium,[AllowNull()]$InterfaceType,[AllowNull()][string]$InterfaceDescription)
    $physical=$null;
    $medium=$null;
    $ifType=$null
    try{
        if($null-ne$NdisPhysicalMedium){
            $physical=[int]$NdisPhysicalMedium
        }
    }catch{}
    try{
        if($null-ne$NdisMedium){
            $medium=[int]$NdisMedium
        }
    }catch{}
    try{
        if($null-ne$InterfaceType){
            $ifType=[int]$InterfaceType
        }
    }catch{}
    if($physical-in@(1,9)){
        return 'NdisPhysicalMedium'
    }
    if($medium-eq16){
        return 'NdisMediumNative802_11'
    }
    if($ifType-eq71){
        return 'InterfaceType80211'
    }
    if([string]$InterfaceDescription-match'(?i)wireless|wi-?fi|802\.11'){
        return 'DescriptionFallback'
    }
    return $null

}

function Get-VSO7WifiCapabilityInventoryVSO {

    $adapters=@()
    try{
        $adapters=@(CimCmdlets\Get-CimInstance -Namespace root/StandardCimv2 -ClassName MSFT_NetAdapter -ErrorAction Stop)
    }catch{
        return @()
    }
    $wifi=@()
    foreach($a in $adapters){

        $physical=$null;
        $medium=$null;
        $ifType=$null
        if($a.PSObject.Properties.Name-contains'NdisPhysicalMedium'){
            try{
                $physical=[int]$a.NdisPhysicalMedium
            }catch{}
        }
        if($a.PSObject.Properties.Name-contains'NdisMedium'){
            try{
                $medium=[int]$a.NdisMedium
            }catch{}
        }
        if($a.PSObject.Properties.Name-contains'InterfaceType'){
            try{
                $ifType=[int]$a.InterfaceType
            }catch{}
        }
        # NDIS_PHYSICAL_MEDIUM: WirelessLan=1, Native802_11=9; NDIS_MEDIUM Native802_11=16; IF_TYPE_IEEE80211=71.
        $source=Get-VSO7WifiMediumClassificationVSO -NdisPhysicalMedium $physical -NdisMedium $medium -InterfaceType $ifType -InterfaceDescription ([string]$a.InterfaceDescription)
        if($null-ne$source){

            $wifi+=,[pscustomobject]@{
                Adapter=$a;
                DetectionSource=$source;
                NdisPhysicalMedium=$physical;
                NdisMedium=$medium;
                InterfaceType=$ifType
            }

        }

    }
    $out=@()
    foreach($w in $wifi){

        $a=$w.Adapter;
        $props=@()
        if($null-ne(Get-Command Get-NetAdapterAdvancedProperty -ErrorAction SilentlyContinue)){

            try{
                $props=@(Get-NetAdapterAdvancedProperty -InterfaceDescription ([string]$a.InterfaceDescription) -AllProperties -ErrorAction Stop|ForEach-Object{

                [pscustomobject]@{
                        RegistryKeyword=[string]$_.RegistryKeyword;RegistryValue=@($_.RegistryValue);ValidRegistryValues=@($_.ValidRegistryValues);DisplayName=[string]$_.DisplayName;DisplayValue=[string]$_.DisplayValue
                    }

                })
            }catch{}

        }
        $out+=[pscustomobject]@{

            Name=[string]$a.Name;
            InterfaceDescription=[string]$a.InterfaceDescription;
            Status=[string]$a.MediaConnectState
            InterfaceIndex=if($a.PSObject.Properties.Name-contains'InterfaceIndex'){
                $a.InterfaceIndex
            }else{
                $null
            }
            DetectionSource=[string]$w.DetectionSource;
            NdisPhysicalMedium=$w.NdisPhysicalMedium;
            NdisMedium=$w.NdisMedium;
            InterfaceType=$w.InterfaceType
            AdvancedProperties=$props

        }

    }
    return @($out|Sort-Object InterfaceDescription,Name -Unique)

}

