function Get-VSO7ServiceDependencyInventoryVSO {

    $out=@()
    foreach($s in @(Get-Service -ErrorAction SilentlyContinue)){

        $deps=@();
        $required=@()
        try{
            $deps=@($s.DependentServices|ForEach-Object{
                $_.Name
            })
        }catch{}
        try{
            $required=@($s.ServicesDependedOn|ForEach-Object{
                $_.Name
            })
        }catch{}
        if($deps.Count-eq0-and$required.Count-eq0){
            continue
        }
        $out+=[pscustomobject]@{
            Name=[string]$s.Name;
            DisplayName=[string]$s.DisplayName;
            Status=[string]$s.Status;
            DependentServices=$deps;
            ServicesDependedOn=$required
        }

    }
    return $out

}

function Invoke-VSO7PingSampleVSO {

    param([Parameter(Mandatory=$true)][string]$TargetHost,[ValidateRange(1,20)][int]$Count=5,[ValidateRange(100,5000)][int]$TimeoutMs=1000)
    $p=New-Object System.Net.NetworkInformation.Ping
    try{

        $ok=@();
        $fail=0
        for($i=0;$i-lt$Count;$i++){

            try{
                $r=$p.Send($TargetHost,$TimeoutMs);
                if($r.Status-eq[System.Net.NetworkInformation.IPStatus]::Success){
                    $ok+=[double]$r.RoundtripTime
                }else{
                    $fail++
                }
            }catch{
                $fail++
            }

        }
        if($ok.Count-eq0){
            return [pscustomobject]@{
                Host=$TargetHost;
                Sent=$Count;
                Received=0;
                LossPct=100.0;
                AvgMs=$null;
                MinMs=$null;
                MaxMs=$null;
                JitterMs=$null
            }
        }
        $avg=[double](($ok|Measure-Object -Average).Average);
        $min=[double](($ok|Measure-Object -Minimum).Minimum);
        $max=[double](($ok|Measure-Object -Maximum).Maximum)
        $jit=0.0;
        if($ok.Count-gt1){
            $d=@();
            for($j=1;$j-lt$ok.Count;$j++){
                $d += [math]::Abs($ok[$j]-$ok[$j-1])
            };
            $jit=[double](($d|Measure-Object -Average).Average)
        }
        return [pscustomobject]@{
            Host=$TargetHost;
            Sent=$Count;
            Received=$ok.Count;
            LossPct=[math]::Round((100.0*($Count-$ok.Count)/$Count),2);
            AvgMs=[math]::Round($avg,2);
            MinMs=$min;
            MaxMs=$max;
            JitterMs=[math]::Round($jit,2)
        }

    }finally{
        $p.Dispose()
    }

}

function Select-VSO7DefaultRouteVSO {

    param([Parameter(Mandatory=$true)][AllowNull()][AllowEmptyCollection()][array]$Routes)
    return ($Routes|Where-Object{
        $null-ne$_-and$_.NextHop-and[string]$_.NextHop-ne'0.0.0.0'
    }|Sort-Object @{
        Expression={
            ([int64]$_.RouteMetric+[int64]$_.InterfaceMetric)
        }
    },RouteMetric,InterfaceMetric,InterfaceIndex|Select-Object -First 1)

}

function Get-VSO7NetworkQualityDiagnosticVSO {

    $gateway=$null;
    $adapter=$null;
    $route=$null;
    $correlation='Unavailable'
    if($null-ne(Get-Command Get-NetRoute -ErrorAction SilentlyContinue)){

        try{

            $route=Select-VSO7DefaultRouteVSO -Routes @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction Stop)
            if($null-ne$route){
                $gateway=[string]$route.NextHop
            }

        }catch{}

    }
    if($null-ne$route-and$null-ne(Get-Command Get-NetAdapter -ErrorAction SilentlyContinue)){

        try{

            $matches=@(Get-NetAdapter -InterfaceIndex ([uint32]$route.InterfaceIndex) -IncludeHidden -ErrorAction Stop)
            if($matches.Count-eq1){
                $adapter=$matches[0];
                $correlation='DefaultRouteInterfaceIndex'
            }
            elseif($matches.Count-gt1){
                $correlation='AmbiguousInterfaceIndex'
            }
            else{
                $correlation='RouteAdapterNotFound'
            }

        }catch{
            $correlation='RouteAdapterLookupFailed'
        }

    }
    $gw=$null;
    if(-not[string]::IsNullOrWhiteSpace($gateway)){
        $gw=Invoke-VSO7PingSampleVSO -TargetHost $gateway -Count 5 -TimeoutMs 1000
    }
    return [pscustomobject]@{

        Gateway=$gateway;
        GatewayPing=$gw
        RouteInterfaceIndex=if($null-ne$route){
            $route.InterfaceIndex
        }else{
            $null
        }
        RouteMetric=if($null-ne$route){
            $route.RouteMetric
        }else{
            $null
        }
        InterfaceMetric=if($null-ne$route){
            $route.InterfaceMetric
        }else{
            $null
        }
        Adapter=if($null-ne$adapter){
            [string]$adapter.Name
        }else{
            $null
        }
        AdapterInterfaceIndex=if($null-ne$adapter){
            $adapter.InterfaceIndex
        }else{
            $null
        }
        LinkSpeed=if($null-ne$adapter){
            [string]$adapter.LinkSpeed
        }else{
            $null
        }
        AdapterCorrelation=$correlation
        Scope='LocalGatewayOnlyByDefault'
        Note='Adapter/link data is correlated to the selected default route by InterfaceIndex. Gateway latency isolates local/LAN problems; it is not an ISP or game-server latency guarantee.'

    }

}

function Get-VSO7QosPolicyDiagnosticVSO {

    if($null-eq(Get-Command Get-NetQosPolicy -ErrorAction SilentlyContinue)){
