    }

}

function Show-VSO7LatencyHardwareLabVSO {

    while($true){

        Write-Title
        Write-CenteredLineVSO -Text $(Get-VSO7ConsoleTextVSO -Es 'LABORATORIO DE LATENCIA / HARDWARE - R44' -En 'LATENCY / HARDWARE LAB - R44') -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Diagnostico first: no convierte una metrica indirecta en "input lag".' -Color 'Yellow'
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[1] Topologia de CPU / clases P-E' -En '[1] CPU topology / P-E classes');Color='Cyan';Description='CPU Sets, grupos, SMT y EfficiencyClass cuando Windows lo expone.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[2] Resumen del sistema DPC / ISR' -En '[2] DPC / ISR system overview');Color='Cyan';Description='Muestrea contadores del sistema; attribution por driver requiere ETW.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[3] MSI/MSI-X + afinidad de interrupciones' -En '[3] MSI/MSI-X + interrupt affinity');Color='Cyan';Description='Distingue capability NIC de overrides Registry explicitos/inherited.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[4] Topologia USB' -En '[4] USB topology');Color='Cyan';Description='Controlador -> dispositivo y clasificacion funcional aproximada.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[5] Salud / fiabilidad del almacenamiento' -En '[5] Storage health / reliability');Color='Cyan';Description='Salud, temperatura, wear y contadores si el driver los expone.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[6] Inventario de controladores' -En '[6] Driver advisor inventory');Color='Cyan';Description='Version/fecha/provider/firma. No afirma que exista una version mas nueva.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[7] Capacidades de NIC + Wi-Fi' -En '[7] NIC + Wi-Fi capabilities');Color='Cyan';Description='Keywords y valores que el propio driver anuncia como validos.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[8] Calidad de la red local' -En '[8] Network local quality');Color='Cyan';Description='Gateway ping/jitter/loss y link speed; separa LAN de Internet/ISP.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[9] Contexto de audio / entrada' -En '[9] Audio / input context');Color='Cyan';Description='Dispositivos/controladores y preferencias; no los vende como latency magic.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[10] Firmware / dependencias de servicios' -En '[10] Firmware / service dependencies');Color='Cyan';Description='BIOS/UEFI read-only y dependencias de servicios.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[11] Inventario de politicas activas QoS/DSCP' -En '[11] QoS/DSCP active policy inventory');Color='Cyan';Description='Lee politicas activas. DSCP no implica menor ping si la red no respeta QoS.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion'
        if($c-eq'0'){
            return
        }
        try{

            Write-VSOHost ''
            switch($c){

                '1'{
                    $x=Get-VSO7CpuTopologyVSO;
                    Write-VSOHost (($x|Select-Object Available,LogicalProcessors,PhysicalCores,Groups,SMT,Heterogeneous,EfficiencyClasses,Error|Format-List|Out-String -Width 220).TrimEnd());
                    if($x.Available){
                        Write-CenteredTableVSO -Rows @($x.CpuSets) -Properties @('Id','Group','LogicalProcessorIndex','CoreIndex','EfficiencyClass','SchedulingClass','Parked')
                    }
                }
                '2'{
                    $x=Get-VSO7DpcIsrOverviewVSO;
                    Write-VSOHost (($x|Format-List|Out-String -Width 220).TrimEnd())
                }
                '3'{
                    $nic=@(Get-VSO7NicInterruptCapabilityVSO);
                    $dev=@(Get-VSO7InterruptDeviceInventoryVSO);
                    if($nic.Count){
                        Write-VSOHost $(Get-VSO7ConsoleTextVSO -Es 'Capacidades de interrupcion del hardware NIC:' -En 'NIC hardware interrupt capabilities:') -ForegroundColor Cyan;
                        Write-CenteredTableVSO -Rows $nic -Properties @('Name','MsiSupported','MsiEnabled','MsiXSupported','MsiXEnabled','NumMsiMessages','NumMsixTableEntries','NumaNode')
                    };
                    Write-VSOHost $(Get-VSO7ConsoleTextVSO -Es 'Politica explicita/heredada de interrupciones del dispositivo:' -En 'Explicit/inherited device interrupt policy:') -ForegroundColor Cyan;
                    Write-CenteredTableVSO -Rows $dev -Properties @('Name','Class','MsiOverrideState','MessageNumberLimit','AffinityOverrideState','AffinityDevicePolicy')
                }
                '4'{
                    $x=@(Get-VSO7UsbTopologyVSO);
                    Write-CenteredTableVSO -Rows $x -Properties @('Controller','Device','PnPClass','Classification','Status');
                    $p=Get-VSO7UsbPowerDiagnosticVSO;
                    Write-VSOHost (($p|Select-Object SelectiveSuspendAC,SelectiveSuspendDC,Recommendation,Note|Format-List|Out-String -Width 220).TrimEnd())
                }
                '5'{
                    $x=@(Get-VSO7StorageHealthVSO);
                    Write-CenteredTableVSO -Rows $x -Properties @('FriendlyName','MediaType','BusType','HealthStatus','Temperature','Wear','PowerOnHours','ReadErrorsUncorrected','WriteErrorsUncorrected')
                }
                '6'{
                    $x=@(Get-VSO7DriverAdvisorInventoryVSO);
                    Write-CenteredTableVSO -Rows $x -Properties @('DeviceName','DeviceClass','DriverVersion','DriverDate','Provider','IsSigned')
                }
                '7'{
                    $n=@(Get-VSO7NetAdapterCapabilityInventoryVSO);
                    Write-CenteredTableVSO -Rows $n -Properties @('Name','InterfaceDescription','Status','LinkSpeed');
                    $w=@(Get-VSO7WifiCapabilityInventoryVSO);
                    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Adaptadores Wi-Fi: {0}' -En 'Wi-Fi adapters: {0}')-f$w.Count) -ForegroundColor Cyan;
                    foreach($a in $w){
                        Write-VSOHost ("{0} - {1}"-f$a.Name,$a.InterfaceDescription) -ForegroundColor Gray;
                        Write-CenteredTableVSO -Rows @($a.AdvancedProperties) -Properties @('RegistryKeyword','RegistryValue','ValidRegistryValues','DisplayValue')
                    }
                }
                '8'{
                    $x=Get-VSO7NetworkQualityDiagnosticVSO;
                    Write-VSOHost (($x|Format-List|Out-String -Width 220).TrimEnd())
                }
                '9'{
                    $a=Get-VSO7AudioDiagnosticVSO;
                    $i=Get-VSO7InputPreferenceDiagnosticVSO;
                    Write-VSOHost (($a|Select-Object Note,DpcContext|Format-List|Out-String -Width 220).TrimEnd());
                    Write-CenteredTableVSO -Rows @($a.Devices) -Properties @('Name','Manufacturer','Status');
                    Write-VSOHost (($i|Format-List|Out-String -Width 220).TrimEnd())
                }
                '10'{
                    $f=Get-VSO7FirmwareInventoryVSO;
                    Write-VSOHost (($f|Format-List|Out-String -Width 220).TrimEnd());
                    $s=@(Get-VSO7ServiceDependencyInventoryVSO);
                    Write-CenteredTableVSO -Rows $s -Properties @('Name','Status','ServicesDependedOn','DependentServices')
                }
                '11'{
                    $x=@(Get-VSO7QosPolicyDiagnosticVSO);
                    Write-CenteredTableVSO -Rows $x -Properties @('Name','AppPathNameMatchCondition','DSCPAction','IPProtocolMatchCondition','NetworkProfile')
                }

            }

        }catch{
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Diagnostico no disponible: {0}' -En 'Diagnostics unavailable: {0}')-f$_.Exception.Message) -ForegroundColor Yellow
        }
        Pause-Vico

    }

}

function Get-VSO7Percentile {

    param([double[]]$Values,[double]$Percentile)
    if($null-eq$Values -or $Values.Count-eq0){
        return 0.0
    }
    $sorted=@($Values|Sort-Object)
    $idx=[math]::Ceiling(($sorted.Count-1)*$Percentile)
    if($idx-lt0){
        $idx=0
    };
    if($idx-ge$sorted.Count){
        $idx=$sorted.Count-1
    }
    return [double]$sorted[[int]$idx]

}

function Read-VSO7PresentMonCsv {

    param([Parameter(Mandatory=$true)][string]$Path)
    if(-not(Test-Path -LiteralPath $Path)){
        throw 'No se genero el CSV de PresentMon.'
    }
    $rows=@(Import-Csv -LiteralPath $Path -ErrorAction Stop)
    if($rows.Count-lt30){
        throw ("Muy pocos frames capturados: {0}."-f$rows.Count)
    }
    $prop=$null
    foreach($n in @($rows[0].PSObject.Properties.Name)){
        if($n-ieq'msBetweenPresents'){
            $prop=$n;
            break
        }
    }
    if(-not$prop){
        throw 'El CSV no contiene msBetweenPresents. VSO7 usa --v1_metrics para mantener este formato.'
    }
    $ft=@();
    $rejected=0;
    $invalidExamples=@()
    foreach($r in $rows){

        $raw=[string]$r.$prop;
        $v=0.0
        $parsed=[double]::TryParse($raw,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$v)
        if($parsed-and-not[double]::IsNaN($v)-and-not[double]::IsInfinity($v)-and$v-gt0){
            $ft += [double]$v
        }
        else{
            $rejected++;
            if($invalidExamples.Count-lt5){
                $invalidExamples+=$raw
            }
        }

    }
    if($ft.Count-lt30){
        throw 'No hay suficientes frametimes validos.'
    }
    $avg=[double](($ft|Measure-Object -Average).Average)
    $p95=Get-VSO7Percentile -Values $ft -Percentile 0.95;
    $p99=Get-VSO7Percentile -Values $ft -Percentile 0.99;
    $p999=Get-VSO7Percentile -Values $ft -Percentile 0.999
    $slow=@($ft|Sort-Object -Descending);
    $count1=[math]::Max(1,[int][math]::Ceiling($slow.Count*0.01));
    $count01=[math]::Max(1,[int][math]::Ceiling($slow.Count*0.001))
    $fpsWorst1=@($slow|Select-Object -First $count1|ForEach-Object{
        1000.0/[double]$_
    });
    $fpsWorst01=@($slow|Select-Object -First $count01|ForEach-Object{
        1000.0/[double]$_
    })
    $low1=[double](($fpsWorst1|Measure-Object -Average).Average);
    $low01=[double](($fpsWorst01|Measure-Object -Average).Average)
    [pscustomobject]@{

        Frames=$ft.Count;
        TotalRows=$rows.Count;
        AcceptedRows=$ft.Count;
        RejectedRows=$rejected;
        RejectedExamples=@($invalidExamples)
        DataQuality=if($rejected-eq0){
            'Valid'
        }else{
            'InvalidRowsPresent'
        };
        MaxFrameMs=[math]::Round([double](($ft|Measure-Object -Maximum).Maximum),3)
        AvgFrameMs=[math]::Round($avg,3);
        P95FrameMs=[math]::Round([double]$p95,3);
        P99FrameMs=[math]::Round([double]$p99,3);
        P999FrameMs=[math]::Round([double]$p999,3)
        AvgFPS=[math]::Round((1000.0/$avg),2);
        OnePercentLow=[math]::Round($low1,2);
        PointOnePercentLow=[math]::Round($low01,2);
        OnePercentFrames=$count1;
        PointOnePercentFrames=$count01
        LowMethod='Average instantaneous FPS of slowest 1% / 0.1% frames; long stalls are retained'

    }

}

function Get-VSO7ProcessClientResolutionVSO {

    param([Parameter(Mandatory=$true)][int]$ProcessId)
    $process=$null
    try{

        $process=Get-Process -Id $ProcessId -ErrorAction Stop
        $handle=[intptr]$process.MainWindowHandle
        if($handle-eq[intptr]::Zero){
            return 'Unknown'
        }
        if($null-eq('VsoR44WindowProbe' -as [type])){

            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class VsoR44WindowProbe {
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
    [DllImport("user32.dll", SetLastError=true)] public static extern bool GetClientRect(IntPtr hWnd, out RECT rect);
}
'@ -Language CSharp -ErrorAction Stop

        }
        $rect=New-Object VsoR44WindowProbe+RECT
        if(-not[VsoR44WindowProbe]::GetClientRect($handle,[ref]$rect)){
            return 'Unknown'
        }
        $width=[int]$rect.Right-[int]$rect.Left;
        $height=[int]$rect.Bottom-[int]$rect.Top
        if($width-lt64-or$height-lt64-or$width-gt32768-or$height-gt32768){
            return 'Unknown'
        }
        return ('{0}x{1}'-f$width,$height)

    }catch{
        return 'Unknown'
    }finally{
        if($null-ne$process){
            try{
                $process.Dispose()
            }catch{}
        }
    }

}

function Get-VSO7PresentMonWorkloadIdentityVSO {

    param([Parameter(Mandatory=$true)]$Game,[Parameter(Mandatory=$true)][int]$Seconds)
    $path=[string]$Game.Path
    if(-not[string]::IsNullOrWhiteSpace($path)){
        try{
            $path=[IO.Path]::GetFullPath($path).TrimEnd('\')
        }catch{}
    }
    $fileVersion='';
    $productVersion=''
    $resolution=Get-VSO7ProcessClientResolutionVSO -ProcessId ([int]$Game.Id)
    if(-not[string]::IsNullOrWhiteSpace($path)-and(Test-Path -LiteralPath $path -PathType Leaf)){

        try{
            $vi=(Get-Item -LiteralPath $path -Force -ErrorAction Stop).VersionInfo;
            $fileVersion=[string]$vi.FileVersion;
            $productVersion=[string]$vi.ProductVersion
        }catch{}

    }
    $displaySignature='Unknown';
    $hardwareSignature='Unknown'
    try{

        $native=Get-VSO7GraphicsNativeStateVSO
        $displayParts=@()
        if($null-ne$native.DisplayConfig-and[bool]$native.DisplayConfig.Available){

            foreach($d in @($native.DisplayConfig.Displays)){

                $id=Get-VSO7DisplayPersistentIdentityVSO -Display $d
                $displayParts+=('{0}|{1}|{2}'-f[string]$id.PersistentIdentity,[math]::Round([double]$d.RefreshHz,3),[string]$d.ActiveColorModeText)

            }

        }
        if($displayParts.Count-gt0){
            $displaySignature=(@($displayParts|Sort-Object)-join';')
        }
        $gpuParts=@()
        foreach($a in @($native.DxCore.Adapters)){

            $id=Get-VSO7GraphicsNativeIdentityVSO -Adapter $a -PnpDeviceId ''
            $gpuParts+=('{0}|{1}|{2}'-f[string]$id.PersistentIdentity,[string]$a.Description,[string]$a.DriverVersion)

        }
        $build=''
        try{
            $cv=Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop;
            $build=[string]$cv.CurrentBuildNumber;
            if([string]::IsNullOrWhiteSpace($build)){
                $build=[string]$cv.CurrentBuild
            }
        }catch{}
        if($gpuParts.Count-gt0-or-not[string]::IsNullOrWhiteSpace($build)){
            $hardwareSignature=('WIN='+$build+';GPU='+(@($gpuParts|Sort-Object)-join';'))
        }

    }catch{}
    return [pscustomobject]@{

        NormalizedExecutablePath=$path
        ProcessName=[string]$Game.ProcessName
        FileVersion=$fileVersion
        ProductVersion=$productVersion
        DurationSeconds=$Seconds
        DisplayContext=$displaySignature
        Resolution=[string]$resolution
        PresentMonContext='v1_metrics'
        HardwareContext=$hardwareSignature

    }

}

function Test-VSO7PresentMonContextCompatibilityVSO {

    param([Parameter(Mandatory=$true)]$Before,[Parameter(Mandatory=$true)]$After)
    if(-not($Before.PSObject.Properties.Name-contains'WorkloadIdentity')-or-not($After.PSObject.Properties.Name-contains'WorkloadIdentity')){
        return [pscustomobject]@{
            Compatible=$false;
            Status='ContextMismatch';
            Reason='WorkloadIdentity is missing from one or both samples.'
        }
    }
    $a=$Before.WorkloadIdentity;
    $b=$After.WorkloadIdentity;
    if($null-eq$a-or$null-eq$b){
        return [pscustomobject]@{
            Compatible=$false;
            Status='ContextMismatch';
            Reason='WorkloadIdentity is null.'
        }
    }
    $pa=[string]$a.NormalizedExecutablePath;
    $pb=[string]$b.NormalizedExecutablePath
    if(-not[string]::IsNullOrWhiteSpace($pa)-and-not[string]::IsNullOrWhiteSpace($pb)){
        if($pa-ine$pb){
            return [pscustomobject]@{
                Compatible=$false;
                Status='ContextMismatch';
                Reason='Executable paths differ.'
            }
        }
    }elseif([string]$a.ProcessName-ine[string]$b.ProcessName){
        return [pscustomobject]@{
            Compatible=$false;
            Status='ContextMismatch';
            Reason='Process identities differ and no stable executable path is available.'
        }
    }
    foreach($field in @('ProductVersion','FileVersion')){
        $va=[string]$a.$field;
        $vb=[string]$b.$field;
        if(-not[string]::IsNullOrWhiteSpace($va)-and-not[string]::IsNullOrWhiteSpace($vb)-and$va-ine$vb){
            return [pscustomobject]@{
                Compatible=$false;
                Status='ContextMismatch';
                Reason=($field+' differs between samples.')
            }
        }
    }
    $da=[double]$a.DurationSeconds;
    $db=[double]$b.DurationSeconds;
    if($da-lt10-or$db-lt10){
        return [pscustomobject]@{
            Compatible=$false;
            Status='Invalid';
            Reason='Benchmark duration is below 10 seconds.'
        }
    }
    $ratio=[math]::Abs($da-$db)/[math]::Max($da,$db);
    if($ratio-gt0.25){
        return [pscustomobject]@{
            Compatible=$false;
            Status='ContextMismatch';
            Reason='Benchmark durations differ by more than 25%.'
        }
    }
    foreach($field in @('DisplayContext','HardwareContext','Resolution','PresentMonContext')){

        $va=[string]$a.$field;
        $vb=[string]$b.$field
        if([string]::IsNullOrWhiteSpace($va)-or[string]::IsNullOrWhiteSpace($vb)-or$va-ieq'Unknown'-or$vb-ieq'Unknown'){
            return [pscustomobject]@{
                Compatible=$false;
                Status='Unverifiable';
                Reason=($field+' is unknown; VSO7 will not emit an automatic metric verdict.')
            }
        }
        if($va-ine$vb){
            return [pscustomobject]@{
                Compatible=$false;
                Status='ContextMismatch';
                Reason=($field+' differs between samples.')
            }
        }

    }
    return [pscustomobject]@{
        Compatible=$true;
        Status='Compatible';
        Reason='Workload identity and comparable context match.'
    }

}

function Invoke-VSO7PresentMonCapture {

    param([ValidateSet('FPS_BASELINE','FPS_POST','FPS_MANUAL')][string]$Label='FPS_MANUAL',[ValidateRange(10,300)][int]$Seconds=60)
    $pm=Find-VSO7PresentMon
    if(-not$pm){
        $pm=Ensure-VSO7PresentMon;
        if(-not$pm){
            return $null
        }
    }
    $games=@(Get-VSO7GameCandidates);
    if($games.Count-eq0){
        Write-VSOHost 'No hay aplicaciones/juegos con ventana detectados.' -ForegroundColor Yellow;
        Pause-Vico;
        return $null
    }
    Write-Title;
    Write-CenteredLineVSO -Text 'CAPTURA PRESENTMON' -Color $script:ThemeCopper
    Write-CenteredLineVSO -Text 'Usa la MISMA escena/ruta/configuracion en BASELINE y POST.' -Color 'Yellow'
    $rows=@();
    for($i=0;$i-lt[math]::Min($games.Count,25);$i++){
        $rows += [pscustomobject]@{
            Text=("[{0,2}] {1,-32} PID {2}"-f($i+1),$games[$i].ProcessName,$games[$i].Id);
            Color='Gray'
        }
    };
    Write-CenteredMenuVSO -Items $rows
    $n=0;
    $raw=Read-CenteredPromptVSO -AnimatedMenu $(Get-VSO7ConsoleTextVSO -Es 'Juego' -En 'Game');
    if(-not([int]::TryParse($raw,[ref]$n))-or$n-lt1-or$n-gt[math]::Min($games.Count,25)){
        return $null
    }
    $g=$games[$n-1]
    $gIdentity=[pscustomobject]@{
        Id=[int]$g.Id;
        Name=[string]$g.ProcessName;
        Path=[string]$g.Path;
        StartTimeUtc=[string]$g.StartTimeUtc
    }
    $current=$null;
    $identityOk=$false
    try{

        $current=Get-Process -Id $gIdentity.Id -ErrorAction SilentlyContinue
        $identityOk=($null-ne$current-and-not[string]::IsNullOrWhiteSpace([string]$gIdentity.StartTimeUtc)-and(Test-VSO7ProcessIdentityMatch -Expected $gIdentity -Process $current))

    }finally{
        Close-VSO7ProcessObjectVSO -Process $current
    }
    if(-not$identityOk){

        Write-VSOHost 'El proceso seleccionado termino o cambio de identidad antes de iniciar PresentMon.' -ForegroundColor Yellow
        return $null

    }
    $csv=Join-Path $script:BenchmarkRoot ("presentmon_{0}_{1}_{2}.csv"-f(Get-Date -Format 'yyyyMMdd_HHmmss'),$Label,$g.ProcessName)
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Capturando {0} s...' -En 'Capturing for {0} s...')-f$Seconds) -ForegroundColor Cyan
    if(-not(Test-VSO7PresentMonTrusted -RequireGitHubDigest)){
        throw 'PresentMon no supero la revalidacion SHA-256 contra GitHub justo antes de ejecutarse. Comprueba Internet o actualizalo desde VSO7.'
    }
    $root=Protect-VSO7SecureDirectory -Path $script:PresentMonRoot
    $pm=Assert-VSO7ProtectedDirectChildFileVSO -Path $script:PresentMonExe -AllowedParent $root
    $meta=Get-VSO7PresentMonMetadata;
    if($null-eq$meta){
        throw 'Metadata PresentMon desaparecio antes de la ejecucion.'
    }
    # Ultimo hash sobre el leaf protegido. Un usuario no elevado no puede sustituirlo; queda documentada
    # una carrera teorica frente a OTRO proceso ya elevado/SYSTEM porque PS 5.1 no ejecuta desde un handle verificado abierto.
    $lastHash=(Get-FileHash -LiteralPath $pm -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
    if($lastHash-ne[string]$meta.Sha256){
        throw 'PresentMon cambio entre la validacion online y la ejecucion.'
    }
    $presentMonArgs=@('--process_id',[string]$gIdentity.Id,'--output_file',(Quote-VSOArg $csv),'--timed',[string]$Seconds,'--terminate_after_timed','--v1_metrics','--no_console_stats')
    $proc=$null;
    $exitCode=$null
    try{

        $proc=Start-Process -FilePath $pm -ArgumentList $presentMonArgs -WorkingDirectory $root -Wait -PassThru -NoNewWindow -ErrorAction Stop
        $exitCode=$proc.ExitCode

    }finally{
        if($null-ne$proc){
            try{
                $proc.Dispose()
            }catch{}
        }
    }
    if($exitCode-ne0){
        throw ("PresentMon devolvio codigo {0}."-f$exitCode)
    }
    $metrics=Read-VSO7PresentMonCsv -Path $csv
    $workload=Get-VSO7PresentMonWorkloadIdentityVSO -Game $g -Seconds $Seconds
    $obj=[pscustomobject]@{
        Product='VSO7';
        Version=$script:Version;
        Label=$Label;
        Timestamp=(Get-Date).ToString('o');
        Game=$g.ProcessName;
        Seconds=$Seconds;
        Csv=$csv;
        Metrics=$metrics;
        WorkloadIdentity=$workload
    }
    $json=[IO.Path]::ChangeExtension($csv,'.json');
    $obj|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $json -Encoding UTF8 -Force
    Write-VSOHost '';
    Write-VSOHost (($metrics|Format-List|Out-String -Width 220).TrimEnd());
    Write-VSOHost ("CSV: {0}"-f$csv) -ForegroundColor DarkGray
    return $obj

}

function Get-LatestVSO7PresentMonResult {

    param([string]$Label)
    $files=Get-ChildItem $script:BenchmarkRoot -File -Filter 'presentmon_*.json' -ErrorAction SilentlyContinue|Sort-Object LastWriteTime -Descending
    foreach($f in $files){
        try{
            $x=Get-Content $f.FullName -Raw|ConvertFrom-Json;
            if([string]$x.Label-eq$Label){
                return $x
            }
        }catch{}
    }
    return $null

}

function Get-VSO7PresentMonABVerdictVSO {

    param($Before,$After)
    if($null-eq$Before-or$null-eq$After){
        return [pscustomobject]@{
            Verdict='Invalid';
            Reason='Missing sample';
            Signals=@();
            ContextStatus='Invalid'
        }
    }
    if($null-eq$Before.Metrics-or$null-eq$After.Metrics){
        return [pscustomobject]@{
            Verdict='Invalid';
            Reason='Missing metrics';
            Signals=@();
            ContextStatus='Invalid'
        }
    }
    if(([string]$Before.Metrics.DataQuality-ne'Valid')-or([string]$After.Metrics.DataQuality-ne'Valid')){
        return [pscustomobject]@{
            Verdict='Invalid';
            Reason='PresentMon CSV contains rejected/invalid rows; no automatic verdict is produced.';
            Signals=@();
            ContextStatus='Invalid';
            Classification='DataQualityGate'
        }
    }
    try{

        if([int]$Before.Metrics.Frames-lt120-or[int]$After.Metrics.Frames-lt120){

            return [pscustomobject]@{
                Verdict='Invalid';
                Reason='Too few valid frames for an automatic A/B verdict (minimum 120 per sample).';
                Signals=@();
                ContextStatus='Invalid'
            }

        }

    }catch{
        return [pscustomobject]@{
            Verdict='Invalid';
            Reason='Frame counts are unavailable or invalid.';
            Signals=@();
            ContextStatus='Invalid'
        }
    }
    $context=Test-VSO7PresentMonContextCompatibilityVSO -Before $Before -After $After
    if(-not[bool]$context.Compatible){

        return [pscustomobject]@{
            Verdict=[string]$context.Status;
            Reason=[string]$context.Reason;
            Signals=@();
            ContextStatus=[string]$context.Status;
            Policy='No metric verdict is produced until workload/context compatibility passes.';
            Classification='ContextGate'
        }

    }
    $signals=@()
    $avg=(Get-VSO7PercentDelta ([double]$Before.Metrics.AvgFPS) ([double]$After.Metrics.AvgFPS))
    $low=(Get-VSO7PercentDelta ([double]$Before.Metrics.OnePercentLow) ([double]$After.Metrics.OnePercentLow))
    $p99=(Get-VSO7PercentDelta ([double]$Before.Metrics.P99FrameMs) ([double]$After.Metrics.P99FrameMs))
    $signals += [pscustomobject]@{
        Metric='AvgFPS';
        DeltaPct=$avg;
        Direction=if($avg-ge2.0){
            'Improved'
        }elseif($avg-le-2.0){
            'Regressed'
        }else{
            'NoiseBand'
        }
    }
    $signals += [pscustomobject]@{
        Metric='OnePercentLow';
        DeltaPct=$low;
        Direction=if($low-ge3.0){
            'Improved'
        }elseif($low-le-3.0){
            'Regressed'
        }else{
            'NoiseBand'
        }
    }
    $signals += [pscustomobject]@{
        Metric='P99FrameMs';
        DeltaPct=$p99;
        Direction=if($p99-le-3.0){
            'Improved'
        }elseif($p99-ge3.0){
            'Regressed'
        }else{
            'NoiseBand'
        }
    }
    $improved=@($signals|Where-Object{
        $_.Direction-eq'Improved'
    }).Count
    $regressed=@($signals|Where-Object{
        $_.Direction-eq'Regressed'
    }).Count
    $verdict='Inconclusive';
    $reason='Changes remain inside the conservative noise gates or metrics disagree.'
    if($improved-ge2-and$regressed-eq0){
        $verdict='Improved';
        $reason='At least two independent frame metrics cleared the improvement gate with no gated regression.'
    }
    elseif($regressed-ge2-and$improved-eq0){
        $verdict='Regressed';
        $reason='At least two independent frame metrics cleared the regression gate with no gated improvement.'
    }
    return [pscustomobject]@{

        Verdict=$verdict;
        Reason=$reason;
        Signals=$signals;
        ContextStatus='Compatible'
        Policy='Context match + >=120 valid frames/sample + duration >=10 s; AvgFPS +/-2%; 1% low +/-3%; P99 frametime -/+3%; two concordant gated signals required.'
        Classification='ContextGatedHeuristicNoiseModel'

    }

}

function Compare-VSO7PresentMonResults {

    param($Before,$After)
    if($null-eq$Before-or$null-eq$After){
        return
    }
    $rows=@(
        [pscustomobject]@{
        Metrica='FPS medio';Antes=[double]$Before.Metrics.AvgFPS;Despues=[double]$After.Metrics.AvgFPS;CambioPct=(Get-VSO7PercentDelta ([double]$Before.Metrics.AvgFPS) ([double]$After.Metrics.AvgFPS))
    },
        [pscustomobject]@{
        Metrica='1% low (avg peor 1%)';Antes=[double]$Before.Metrics.OnePercentLow;Despues=[double]$After.Metrics.OnePercentLow;CambioPct=(Get-VSO7PercentDelta ([double]$Before.Metrics.OnePercentLow) ([double]$After.Metrics.OnePercentLow))
    },
        [pscustomobject]@{
        Metrica='0.1% low (avg peor 0.1%)';Antes=[double]$Before.Metrics.PointOnePercentLow;Despues=[double]$After.Metrics.PointOnePercentLow;CambioPct=(Get-VSO7PercentDelta ([double]$Before.Metrics.PointOnePercentLow) ([double]$After.Metrics.PointOnePercentLow))
    },
        [pscustomobject]@{
        Metrica='Frametime p95 ms';Antes=[double]$Before.Metrics.P95FrameMs;Despues=[double]$After.Metrics.P95FrameMs;CambioPct=(Get-VSO7PercentDelta ([double]$Before.Metrics.P95FrameMs) ([double]$After.Metrics.P95FrameMs))
    },
        [pscustomobject]@{
        Metrica='Frametime p99 ms';Antes=[double]$Before.Metrics.P99FrameMs;Despues=[double]$After.Metrics.P99FrameMs;CambioPct=(Get-VSO7PercentDelta ([double]$Before.Metrics.P99FrameMs) ([double]$After.Metrics.P99FrameMs))
    }
    )
    Write-CenteredTableVSO -Rows @($rows) -Properties @('Metrica','Antes','Despues','CambioPct')
    $verdict=Get-VSO7PresentMonABVerdictVSO -Before $Before -After $After
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Resultado A/B: {0} - {1}' -En 'A/B result: {0} - {1}')-f$verdict.Verdict,$verdict.Reason) -ForegroundColor $(if($verdict.Verdict-eq'Improved'){
        'Green'
    }elseif($verdict.Verdict-eq'Regressed'){
        'Red'
    }else{
        'Yellow'
    })
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Umbral de ruido: {0}' -En 'Noise gate: {0}')-f$verdict.Policy) -ForegroundColor DarkGray
    $path=Join-Path $script:ReportRoot ("VSO7_FPS_AB_{0}.html"-f(Get-Date -Format 'yyyyMMdd_HHmmss'))
    $frag=$rows|ConvertTo-Html -Fragment;
    $html="<html><head><meta charset='utf-8'><style>body{background:#0b0907;color:#eadbc8;font-family:Segoe UI,Arial;margin:36px}h1{color:#c58b52}table{border-collapse:collapse}td,th{padding:8px 14px;border-bottom:1px solid #4b3424}</style></head><body><h1>VSO7 - FPS A/B</h1><p>$($Before.Game) | BASELINE $($Before.Timestamp) | POST $($After.Timestamp)</p><p><strong>Verdict:</strong> $($verdict.Verdict) - $($verdict.Reason)</p><p>$($verdict.Policy)</p>$frag</body></html>";
    Set-Content $path $html -Encoding UTF8 -Force
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Informe: {0}' -En 'Report: {0}')-f$path) -ForegroundColor Green

}

function Show-VSO7BenchmarkMenu {

    while($true){

        Write-Title
        Write-CenteredLineVSO -Text 'BENCHMARK A/B - ACTIVIDAD DE FONDO' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Mide CPU, DPC, interrupciones, cambios de contexto, disco, RAM y procesos.' -Color $script:ThemeText
        Write-CenteredLineVSO -Text 'No inventa FPS: compara el estado de Windows antes y despues.' -Color 'Green'
        $pmStatus = if (Find-VSO7PresentMon) {
            'PresentMon: LISTO'
        } else {
            'PresentMon: no instalado (VSO7 puede descargarlo y verificarlo)'
        }
        $pmColor = if (Find-VSO7PresentMon) {
            'Green'
        } else {
            'Yellow'
        }
        Write-CenteredLineVSO -Text $pmStatus -Color $pmColor
        Write-VSOHost ''
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[1] Crear medicion BASELINE (10 s)' -En '[1] Create a BASELINE measurement (10 s)');Color='Cyan';Description='Guarda una referencia de actividad de fondo antes de optimizar para poder comparar despues.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[2] Medir POST y comparar con el ultimo BASELINE' -En '[2] Measure POST and compare with the latest BASELINE');Color='Green';Description='Mide de nuevo y compara procesos, CPU y actividad con la referencia anterior.'
        },
            [pscustomobject]@{
            Text='[3] Medicion manual (10 s)';Color='Gray';Description='Hace una captura aislada de actividad sin guardarla como baseline ni aplicar cambios.'
        },
            [pscustomobject]@{
            Text='[4] Ver ultima comparacion';Color='Gray';Description='Solo lectura: vuelve a mostrar el resultado de la ultima comparacion guardada.'
        },
            [pscustomobject]@{
            Text='[5] FPS BASELINE con PresentMon (opcional)';Color='Cyan';Description='Captura FPS y frametimes como referencia antes de cambiar ajustes. Requiere PresentMon.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[6] FPS POST y comparar lows (opcional)' -En '[6] Measure POST FPS and compare lows (optional)');Color='Green';Description='Captura otra muestra y compara FPS, 1% lows y frametimes contra el baseline.'
        },
            [pscustomobject]@{
            Text=$(Get-VSO7ConsoleTextVSO -Es '[7] Gestionar instalacion de PresentMon' -En '[7] Manage the PresentMon installation');Color='Yellow';Description='Abre el gestor de PresentMon; no lo descarga simplemente por entrar.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion'
        if($c-eq'0'){
            return
        }
        if($c-eq'1'){

            $b=Measure-VSO7Performance -Seconds 10 -Label BASELINE;
            $p=Save-VSO7Benchmark $b
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Baseline guardado: {0}' -En 'Baseline saved: {0}') -f $p) -ForegroundColor Green;
            Pause-Vico;
            continue

        }
        if($c-eq'2'){

            $base=Get-LatestVSO7Benchmark -Label BASELINE
            if($null-eq$base){
                Write-VSOHost 'No hay BASELINE. Crea uno primero.' -ForegroundColor Yellow;
                Pause-Vico;
                continue
            }
            $post=Measure-VSO7Performance -Seconds 10 -Label POST;
            $pp=Save-VSO7Benchmark $post
            $rows=Compare-VSO7Benchmarks -Before $base.Data -After $post
            Write-VSOHost '';
            Write-CenteredTableVSO -Rows @($rows) -Properties @('Metrica','Antes','Despues','CambioPct')
            $html=Export-VSO7BenchmarkHtml -Rows $rows -Before $base.Data -After $post
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es "POST: {0}`nInforme HTML: {1}" -En "POST: {0}`nHTML report: {1}") -f $pp,$html) -ForegroundColor Green;
            Pause-Vico;
            continue

        }
        if($c-eq'3'){

            $m=Measure-VSO7Performance -Seconds 10 -Label MANUAL;
            $p=Save-VSO7Benchmark $m;
            Write-VSOHost (($m|Select-Object CpuAvgPct,CpuMaxPct,DpcAvgPct,DpcMaxPct,ContextSwitchesAvg,InterruptsAvg,RamUsedAvgPct,ProcessCountAvg|Format-List|Out-String -Width 220).TrimEnd())
            Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Guardado: {0}' -En 'Saved: {0}') -f $p) -ForegroundColor Green;
            Pause-Vico;
            continue

        }
        if($c-eq'4'){

            if($null-eq$script:LastBenchmarkComparison){
                Write-VSOHost 'No hay comparacion en esta sesion.' -ForegroundColor Yellow
            }else{
                Write-CenteredTableVSO -Rows @($script:LastBenchmarkComparison) -Properties @('Metrica','Antes','Despues','CambioPct')
            }
            Pause-Vico

        }
        if($c-eq'5'){

            try{
                $x=Invoke-VSO7PresentMonCapture -Label FPS_BASELINE -Seconds 60;
                if($null-ne$x){
                    Pause-Vico
                }
            }catch{
                Write-VSOHost $_.Exception.Message -ForegroundColor Red;
                Pause-Vico
            }

        }
        if($c-eq'6'){

            $base=Get-LatestVSO7PresentMonResult -Label FPS_BASELINE;
            if($null-eq$base){
                Write-VSOHost 'No hay FPS_BASELINE.' -ForegroundColor Yellow;
                Pause-Vico;
                continue
            }
            try{
                $post=Invoke-VSO7PresentMonCapture -Label FPS_POST -Seconds 60;
                if($null-ne$post){
                    Write-VSOHost '';
                    Compare-VSO7PresentMonResults -Before $base -After $post;
                    Pause-Vico
                }
            }catch{
                Write-VSOHost $_.Exception.Message -ForegroundColor Red;
                Pause-Vico
            }

        }
        if($c-eq'7'){
            Show-VSO7PresentMonManager
        }

    }

}

function New-VSO7ScoreCheck {

    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][int]$Points,
        [Parameter(Mandatory=$true)][int]$Max,
        [Parameter(Mandatory=$true)][string]$Detail
    )
    return [pscustomobject]@{

        Comprobacion=$Name
        Puntos=$Points
        Max=$Max
        Detalle=$Detail

    }

}

function Get-VSO7TrimmedAverage {

    param([Parameter(Mandatory=$true)][AllowNull()][AllowEmptyCollection()][array]$Samples,[Parameter(Mandatory=$true)][string]$Property)
    $values=@()
    foreach($sample in @($Samples|Where-Object{
        $null-ne$_
    })){
        try{
            $prop=$sample.PSObject.Properties[$Property];
            if($null-ne$prop-and$null-ne$prop.Value){
                $values += [double]$prop.Value
            }
        }catch{}
    }
    $values=@($values|Sort-Object)
    if($values.Count-ge5){
        $trimmed=@();
        for($i=1;$i-lt($values.Count-1);$i++){
            $trimmed += $values[$i]
        };
        $values=$trimmed
    }
    if($values.Count-eq0){
        return $null
    }
    return [math]::Round([double](($values|Measure-Object -Average).Average),2)

}

function Get-VSO7OverlayScoreInfo {

    param([switch]$Strict)
    $all=@(Get-RunningOverlayCandidates -Strict:$Strict);
    $protected=@(Get-VSO7ProtectedProcesses|ForEach-Object{
        $_.ToLowerInvariant()
    });
    $names=@($all|Select-Object -ExpandProperty Process -Unique|Sort-Object)
    $candidates=@();
    $review=@();
    $preferred=@()
    foreach($name in $names){
        $lower=$name.ToLowerInvariant();
        if($protected-contains$lower){
            $preferred+=$name;
            continue
        };
        if($lower-match'discord'){
            $review+=$name;
            continue
        };
        if($lower-match'medal|epicgameslauncher|eosoverlayrenderer|gamebar|nvidia overlay|radeonsoftware'){
            $candidates+=$name;
            continue
        };
        $review+=$name
    }
    return [pscustomobject]@{
        CandidateNames=@($candidates|Sort-Object -Unique);
        ReviewNames=@($review|Sort-Object -Unique);
        PreferredNames=@($preferred|Sort-Object -Unique);
        CandidateCount=@($candidates|Sort-Object -Unique).Count;
        ReviewCount=@($review|Sort-Object -Unique).Count;
        PreferredCount=@($preferred|Sort-Object -Unique).Count;
        RawProcessCount=$all.Count
    }

}

function Write-CenteredTableVSO {

    param(
        [Parameter(Mandatory=$true)][AllowNull()][AllowEmptyCollection()][array]$Rows,
        [Parameter(Mandatory=$true)][array]$Properties
    )

    $Rows=@($Rows|Where-Object{
        $null-ne$_
    })
    if($Rows.Count-eq0){

        Write-CenteredLineVSO -Text '(sin datos)' -Color $script:ThemeMuted
        return

    }

    $rendered=($Rows|Format-Table -Property $Properties -AutoSize|Out-String -Width 220).TrimEnd()
    $lines=@($rendered -split "`r?`n")
    $maxLen=0
    foreach($line in $lines){
        if($line.Length-gt$maxLen){
            $maxLen=$line.Length
        }
    }
    $padding=[math]::Max(0,[math]::Floor(((Get-VSOConsoleWidth)-$maxLen)/2))

    foreach($line in $lines){

        Write-VSOHost ((' '*$padding)+$line)

    }

}

function Get-VSO7Score {

    param([AllowNull()][scriptblock]$ProgressCallback)
    $configChecks=@()
    $stateChecks=@()

    # CONFIGURACION: valores relativamente estables. No penaliza por tener una app abierta en ese instante.
    $gm=Get-RegValueFriendly 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled'
    $configChecks += New-VSO7ScoreCheck 'Modo de juego' $(if($gm-eq'1'){
        15
    }else{
        0
    }) 15 ("Valor={0}"-f$gm)

    $cap=Get-RegValueFriendly 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled'
    $dvr=Get-RegValueFriendly 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled'
    $capturePoints=if($cap-eq'0'-and$dvr-eq'0'){
        15
    }else{
        0
    }
    $configChecks += New-VSO7ScoreCheck 'Captura en segundo plano' $capturePoints 15 ("AppCapture={0}, DVR={1}"-f$cap,$dvr)

    $freePct=$null
    $systemDrive=if($script:SystemDrive){
        [string]$script:SystemDrive
    }else{
        [IO.Path]::GetPathRoot([string]$script:WindowsRoot).TrimEnd('\')
    }
    try{

        $disk=CimCmdlets\Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'"-f$systemDrive) -ErrorAction Stop
        if($null-ne$disk.FreeSpace -and [double]$disk.Size-gt0){
            $freePct=([double]$disk.FreeSpace/[double]$disk.Size)*100
        }

    }catch{}
    if($null-eq$freePct){
        $configChecks += New-VSO7ScoreCheck 'Espacio libre del sistema' 0 0 ("NO DISPONIBLE: telemetria de {0} fallida"-f$systemDrive)
    }else{
        $diskPoints=if($freePct-ge20){
            20
        }elseif($freePct-ge15){
            15
        }elseif($freePct-ge10){
            8
        }else{
            0
        };
        $configChecks += New-VSO7ScoreCheck 'Espacio libre del sistema' $diskPoints 20 ("{0} {1:N1}% libre"-f$systemDrive,$freePct)
    }

    try{
        $startup=@(Get-StartupEntriesDetailed -Strict|Where-Object{
            (Get-StartupClassificationVSO $_)-eq'CANDIDATO'
        }).Count;
        $startupPoints=if($startup-eq0){
            20
        }elseif($startup-eq1){
            18
        }elseif($startup-eq2){
            15
        }elseif($startup-le4){
            10
        }elseif($startup-le7){
            5
        }else{
            0
        };
        $configChecks += New-VSO7ScoreCheck 'Inicio automatico' $startupPoints 20 ("{0} candidato(s)"-f$startup)
    }catch{
        $configChecks += New-VSO7ScoreCheck 'Inicio automatico' 0 0 ('NO DISPONIBLE: '+$_.Exception.Message)
    }

    $pow=Get-ActivePowerSchemeInfo
    if(-not[bool]$pow.Available){
        $configChecks += New-VSO7ScoreCheck 'Plan de energia' 0 0 ('NO DISPONIBLE: '+[string]$pow.Error)
    }else{
        $powerPoints=20;
        if($pow.BuiltInName-eq'PowerSaver'){
            $powerPoints=5
        }elseif($pow.BuiltInName-eq'Balanced'){
            $powerPoints=15
        };
        $configChecks += New-VSO7ScoreCheck 'Plan de energia' $powerPoints 20 $(if($pow.Name){
            $pow.Name
        }else{
            $pow.Guid
        })
    }

    $restorePoints=0
    $restoreDetail='No/antiguo'
    if(Test-RecentRestorePoint -Hours 24){
        $restorePoints=10;
        $restoreDetail='<24 h'
    }
    elseif(Test-RecentRestorePoint -Hours 168){
        $restorePoints=5;
        $restoreDetail='<7 dias'
    }
    $configChecks += New-VSO7ScoreCheck 'Punto de restauracion reciente' $restorePoints 10 $restoreDetail

    # ESTADO ACTUAL: se mide aparte para no confundir una sesion cargada con una mala configuracion.
    try{
        $overlayInfo=Get-VSO7OverlayScoreInfo -Strict;
        $overlayPoints=if($overlayInfo.CandidateCount-eq0){
            25
        }elseif($overlayInfo.CandidateCount-eq1){
            20
        }elseif($overlayInfo.CandidateCount-eq2){
            15
        }elseif($overlayInfo.CandidateCount-eq3){
            8
        }else{
            0
        };
        $overlayDetail=("{0} candidato(s), {1} revisar, {2} protegido(s); {3} proceso(s) detectado(s)"-f $overlayInfo.CandidateCount,$overlayInfo.ReviewCount,$overlayInfo.PreferredCount,$overlayInfo.RawProcessCount);
        $stateChecks += New-VSO7ScoreCheck 'Overlays/launchers activos' $overlayPoints 25 $overlayDetail
    }catch{
        $stateChecks += New-VSO7ScoreCheck 'Overlays/launchers activos' 0 0 ('NO DISPONIBLE: '+$_.Exception.Message)
    }

    if($null-ne$ProgressCallback){
        try{& $ProgressCallback 0 0 0 10}catch{}
    }else{
        Write-CenteredLineVSO -Text 'Midiendo actividad de fondo durante 10 segundos...' -Color $script:ThemeMuted
    }
    Start-Sleep -Milliseconds 750
    $perf=Measure-VSO7Performance -Seconds 10 -Label MANUAL -ProgressCallback $ProgressCallback
    $cpuAvg=Get-VSO7TrimmedAverage -Samples @($perf.Samples) -Property 'CpuPct'
    $dpcAvg=Get-VSO7TrimmedAverage -Samples @($perf.Samples) -Property 'DpcPct'
    $ramAvg=$perf.RamUsedAvgPct

    if($null-eq$cpuAvg){
        $stateChecks += New-VSO7ScoreCheck 'CPU de fondo (10 s)' 0 0 'NO DISPONIBLE: telemetria CPU fallida'
    }else{
        $cpuPoints=if($cpuAvg-le2){
            30
        }elseif($cpuAvg-le4){
            24
        }elseif($cpuAvg-le7){
            15
        }elseif($cpuAvg-le10){
            6
        }else{
            0
        };
        $stateChecks += New-VSO7ScoreCheck 'CPU de fondo (10 s)' $cpuPoints 30 ("{0}% media recortada"-f$cpuAvg)
    }
    if($null-eq$ramAvg){
        $stateChecks += New-VSO7ScoreCheck 'RAM en reposo (10 s)' 0 0 'NO DISPONIBLE: telemetria RAM fallida'
    }else{
        $ramAvg=[math]::Round([double]$ramAvg,2);
        $ramPoints=if($ramAvg-le60){
            20
        }elseif($ramAvg-le70){
            15
        }elseif($ramAvg-le80){
            8
        }else{
            0
        };
        $stateChecks += New-VSO7ScoreCheck 'RAM en reposo (10 s)' $ramPoints 20 ("{0}% usada de media"-f$ramAvg)
    }

    $pending=Test-PendingRebootVSO
    if($null-eq$pending){
        $stateChecks += New-VSO7ScoreCheck 'Reinicio pendiente' 0 0 'NO DISPONIBLE: no se pudo consultar de forma fiable'
    }
    else{
        $stateChecks += New-VSO7ScoreCheck 'Reinicio pendiente' $(if($pending){
            0
        }else{
            15
        }) 15 $(if($pending){
            'SI'
        }else{
            'NO'
        })
    }

    if($null-eq$dpcAvg){
        $stateChecks += New-VSO7ScoreCheck 'Actividad DPC (10 s)' 0 0 'NO DISPONIBLE: telemetria DPC fallida'
    }else{
        $dpcPoints=if($dpcAvg-le0.5){
            10
        }elseif($dpcAvg-le1){
            8
        }elseif($dpcAvg-le2){
            5
        }elseif($dpcAvg-le5){
            2
        }else{
            0
        };
        $stateChecks += New-VSO7ScoreCheck 'Actividad DPC (10 s)' $dpcPoints 10 ("{0}% medio; actividad, no latencia DPC"-f$dpcAvg)
    }

    $configRaw=[double](($configChecks|Measure-Object -Property Puntos -Sum).Sum)
    $configMax=[double](($configChecks|Measure-Object -Property Max -Sum).Sum)
    $stateRaw=[double](($stateChecks|Measure-Object -Property Puntos -Sum).Sum)
    $stateMax=[double](($stateChecks|Measure-Object -Property Max -Sum).Sum)

    $configScore=if($configMax-gt0){
        [math]::Round(($configRaw/$configMax)*100)
    }else{
        0
    }
    $stateScore=if($stateMax-gt0){
        [math]::Round(($stateRaw/$stateMax)*100)
    }else{
        0
    }
    $global=[math]::Round(($configScore+$stateScore)/2)

    return [pscustomobject]@{

        Score=[int]$global
        Max=100
        ConfigurationScore=[int]$configScore
        StateScore=[int]$stateScore
        ConfigurationChecks=@($configChecks)
        StateChecks=@($stateChecks)
        Checks=@($configChecks+$stateChecks)
        Timestamp=(Get-Date).ToString('o')
        MeasurementSeconds=10

    }

}

function Save-VSO7ScoreHistory {

    param($Score)
    $items=@()
    if(Test-Path -LiteralPath $script:ScoreHistoryFile){

        try{
            $items=@(Get-Content $script:ScoreHistoryFile -Raw|ConvertFrom-Json)
        }catch{
            $items=@()
        }

    }

    $items += [pscustomobject]@{

        Timestamp=$Score.Timestamp
        Score=$Score.Score
        ConfigurationScore=$Score.ConfigurationScore
        StateScore=$Score.StateScore

    }

    @($items|Select-Object -Last 100)|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $script:ScoreHistoryFile -Encoding UTF8 -Force

}

function Show-VSO7Score {

    Write-Title
    Write-CenteredLineVSO -Text 'VSO SCORE - CONFIGURACION Y ESTADO ACTUAL' -Color $script:ThemeCopper
    Write-CenteredLineVSO -Text 'No predice FPS: separa ajustes persistentes de la carga puntual de esta sesion.' -Color $script:ThemeText
    Write-VSOHost ''

    $s=Get-VSO7Score
    Save-VSO7ScoreHistory $s

    Write-VSOHost ''
    Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'CONFIGURACION : {0}/100' -En 'CONFIGURATION : {0}/100') -f $s.ConfigurationScore) -Color $(if($s.ConfigurationScore-ge85){
        'Green'
    }elseif($s.ConfigurationScore-ge65){
        'Yellow'
    }else{
        'Red'
    })
    Write-CenteredTableVSO -Rows @($s.ConfigurationChecks) -Properties @('Comprobacion','Puntos','Max','Detalle')

    Write-VSOHost ''
    Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'ESTADO ACTUAL : {0}/100' -En 'CURRENT STATUS: {0}/100') -f $s.StateScore) -Color $(if($s.StateScore-ge85){
        'Green'
    }elseif($s.StateScore-ge65){
        'Yellow'
    }else{
        'Red'
    })
    Write-CenteredTableVSO -Rows @($s.StateChecks) -Properties @('Comprobacion','Puntos','Max','Detalle')

    Write-VSOHost ''
    Write-CenteredLineVSO -Text ("GLOBAL : {0}/100" -f $s.Score) -Color $(if($s.Score-ge85){
        'Green'
    }elseif($s.Score-ge65){
        'Yellow'
    }else{
        'Red'
    })
    Write-CenteredLineVSO -Text 'Global = media entre Configuracion y Estado actual.' -Color $script:ThemeMuted
    Pause-Vico

}

function Get-VSO7LocalDiskFreeSnapshot {

    $snapshot = @{}
    try {

        foreach ($disk in @(CimCmdlets\Get-CimInstance Win32_LogicalDisk -Filter "DriveType=3" -ErrorAction Stop)) {

            if (-not [string]::IsNullOrWhiteSpace([string]$disk.DeviceID) -and $null -ne $disk.FreeSpace) {

                $snapshot[[string]$disk.DeviceID] = [int64]$disk.FreeSpace

            }

        }

    } catch {}
    if ($snapshot.Count -eq 0) {

        foreach ($drive in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)) {

            if ($drive.Root -match '^[A-Za-z]:\\$' -and $null -ne $drive.Free) {

                $snapshot[([string]$drive.Name + ':')] = [int64]$drive.Free

            }

        }

    }
    return $snapshot

}

function Get-VSO7FreedBytesFromSnapshots {

    param([hashtable]$Before,[hashtable]$After)
    [int64]$total = 0
    if ($null -eq $Before -or $null -eq $After) {
        return $total
    }
    foreach ($drive in @($Before.Keys)) {

        if (-not $After.ContainsKey($drive)) {
            continue
        }
        $delta = [int64]$After[$drive] - [int64]$Before[$drive]
        if ($delta -gt 0) {
            $total += $delta
        }

    }
    return $total

}

function Add-VSO7CleanupHistory {

    param([int64]$BytesFreed,[array]$Tweaks)
    $items=@();
    if(Test-Path -LiteralPath $script:CleanupHistoryFile){
        try{
            $items=@(Get-Content $script:CleanupHistoryFile -Raw|ConvertFrom-Json)
        }catch{
            $items=@()
        }
    }
    $items += [pscustomobject]@{
        Timestamp=(Get-Date).ToString('o');
        BytesFreed=$BytesFreed;
        Tweaks=@($Tweaks|Select-Object -ExpandProperty Id)
    }
    @($items|Select-Object -Last 200)|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $script:CleanupHistoryFile -Encoding UTF8 -Force

}

function Show-VSO7CleanupHistory {

    Write-Title;
    Write-CenteredLineVSO -Text 'HISTORIAL DE LIMPIEZA' -Color $script:ThemeCopper
    if(-not(Test-Path -LiteralPath $script:CleanupHistoryFile)){
        Write-VSOHost 'Aun no hay historial.' -ForegroundColor Gray;
        Pause-Vico;
        return
    }
    try{
        $items=@(Get-Content $script:CleanupHistoryFile -Raw|ConvertFrom-Json)
    }catch{
        $items=@()
    }
    [int64]$sum=0;
    foreach($i in $items){
        $sum += [int64]$i.BytesFreed
    }
    Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'Total recuperado medido por VSO7: {0}' -En 'Total recovered space measured by VSO7: {0}') -f (Format-BytesVSO $sum)) -ForegroundColor Green
    Write-CenteredTableVSO -Rows @($items|Select-Object -Last 20 @{
        N='Fecha';E={
            $_.Timestamp
        }
    },@{
        N='Liberado';E={
            Format-BytesVSO ([int64]$_.BytesFreed)
        }
    },@{
        N='Acciones';E={
            @($_.Tweaks).Count
        }
    }) -Properties @('Fecha','Liberado','Acciones')
    Pause-Vico

}

function Get-VSO7MandatoryProtectedProcesses {

    return @('audiodg','dwm','explorer','lsass','services','svchost','wininit','winlogon','csrss','smss','System','Registry','Memory Compression')

}

function Test-VSO7SafeProcessName {

    param([string]$Name)
    if([string]::IsNullOrWhiteSpace($Name)-or$Name.Length-gt128){
        return $false
    }
    if($Name-match'[\\/\*\?\[\]]'){
        return $false
    }
    if($Name.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
        $Name=$Name.Substring(0,$Name.Length-4)
    }
    return ($Name -match '^[^\x00-\x1F]+$')

}

function Get-VSO7ProtectedProcesses {

    $mandatory=@(Get-VSO7MandatoryProtectedProcesses)
    $configured=@()
    if(Test-Path -LiteralPath $script:ProtectedProcessesFile -PathType Leaf){

        try{
            $configured=@((Get-Content -LiteralPath $script:ProtectedProcessesFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)|ForEach-Object{
                [string]$_
            }|Where-Object{
                Test-VSO7SafeProcessName $_
            })
        }catch{}

    }
    return @(($mandatory+$configured)|Where-Object{
        $_
    }|Sort-Object -Unique)

}

function Save-VSO7ProtectedProcesses {

    param([array]$Names)
    $combined = @(Get-VSO7MandatoryProtectedProcesses) + @($Names)
    $all = @($combined | Where-Object {
        $_ -and (Test-VSO7SafeProcessName ([string]$_))
    } | ForEach-Object {
        [string]$_
    } | Sort-Object -Unique)
    $tmp = $script:ProtectedProcessesFile + '.tmp'
    $all | ConvertTo-Json | Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
    [void](Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop)
    [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $script:ProtectedProcessesFile)

}

function Show-VSO7ProtectionManager {

    while($true){

        Write-Title;
        Write-CenteredLineVSO -Text 'EXCLUSIONES DE SESION GAMING' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Los procesos protegidos nunca se cierran ni se reducen de prioridad durante una sesion gaming de VSO7.' -Color $script:ThemeText
        $mandatory=@(Get-VSO7MandatoryProtectedProcesses|ForEach-Object{
            $_.ToLowerInvariant()
        });
        $names=@(Get-VSO7ProtectedProcesses);
        $rows=@()
        for($i=0;$i-lt$names.Count;$i++){
            $isSystem=$mandatory-contains$names[$i].ToLowerInvariant();
            $suffix=if($isSystem){
                if($script:Language-eq'en'){
                    ' [SYSTEM]'
                }else{
                    ' [SISTEMA]'
                }
            }else{
                ''
            };
            $desc=if($isSystem){
                'Proteccion obligatoria de seguridad; no se puede quitar.'
            }else{
                'Proteccion añadida por el usuario; puedes quitarla desde esta pantalla.'
            };
            $rows += [pscustomobject]@{
                Text=("[{0}] {1}{2}"-f($i+1),$names[$i],$suffix);
                Color=$(if($isSystem){
                    'Green'
                }else{
                    'Gray'
                });
                Description=$desc
            }
        }
        if($rows.Count){
            Write-VSO7TwoColumnOptionsVSO -Items $rows
        }
        $addNumber=$names.Count+1;
        $removeNumber=$names.Count+2
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Anadir proceso protegido' -En '[{0}] Add a protected process')-f$addNumber);Color='Cyan';Description='Añade un nombre de proceso para que VSO7 no lo toque durante sesiones gaming.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Quitar una proteccion del usuario' -En '[{0}] Remove a user-added protection')-f$removeNumber);Color='Yellow';Description='Permite quitar una exclusion que hayas añadido; las protecciones de sistema no se pueden borrar.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa sin cambiar mas exclusiones.';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion';
        if($c-eq'0'){
            return
        };
        $choice=0;
        if(-not[int]::TryParse($c,[ref]$choice)){
            continue
        }
        if($choice-eq$addNumber){
            $n=Read-CenteredPromptVSO -Text 'Nombre de proceso SIN .exe';
            if(Test-VSO7SafeProcessName $n){
                if($n.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
                    $n=$n.Substring(0,$n.Length-4)
                };
                Save-VSO7ProtectedProcesses ($names+$n)
            }else{
                Write-VSOHost 'Nombre de proceso invalido.' -ForegroundColor Red;
                Start-Sleep 1
            };
            continue
        }
        if($choice-eq$removeNumber){
            $r=Read-CenteredPromptVSO -AnimatedMenu -Text 'Numero del proceso protegido que quieres quitar';
            $n=0;
            if([int]::TryParse($r,[ref]$n)-and$n-ge1-and$n-le$names.Count){
                $target=[string]$names[$n-1];
                if($mandatory-contains$target.ToLowerInvariant()){
                    Write-VSOHost 'Las protecciones de sistema no se pueden quitar.' -ForegroundColor Yellow;
                    Start-Sleep 1
                }else{
                    $new=@();
                    for($i=0;$i-lt$names.Count;$i++){
                        if($i-ne($n-1)){
                            $new+=$names[$i]
                        }
                    };
                    Save-VSO7ProtectedProcesses $new
                }
            };
            continue
        }

    }

}

function Test-VSO7ExactJsonProperties {

    param(
        [Parameter(Mandatory=$true)]$Object,
        [Parameter(Mandatory=$true)][string[]]$Required,
        [string[]]$Optional=@()
    )
    if($null-eq$Object){
        return $false
    }
    $actual=@($Object.PSObject.Properties|ForEach-Object{
        [string]$_.Name
    })
    $allowed=@($Required+$Optional)
    foreach($name in $Required){
        if($actual -notcontains $name){
            return $false
        }
    }
    foreach($name in $actual){
        if($allowed -notcontains $name){
            return $false
        }
    }
    return $true

}

function Test-VSO7JsonInteger {

    param($Value,[int64]$Min=0,[int64]$Max=[int64]::MaxValue)
    if($null-eq$Value){
        return $false
    }
    if(-not($Value -is [byte] -or $Value -is [int16] -or $Value -is [int32] -or $Value -is [int64] -or $Value -is [uint16] -or $Value -is [uint32])){
        return $false
    }
    try{
        $n=[int64]$Value
    }catch{
        return $false
    }
    return ($n-ge$Min-and$n-le$Max)

}

function Test-VSO7IsoUtcTimestamp {

    param([string]$Value)
    if([string]::IsNullOrWhiteSpace($Value)-or$Value.Length-gt64){
        return $false
    }
    $dto=[DateTimeOffset]::MinValue
    return [DateTimeOffset]::TryParseExact($Value,'o',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$dto)

}

function Test-VSO7PowerSchemeGuid {

    param([string]$Value)
    if([string]::IsNullOrWhiteSpace($Value)){
        return $false
    }
    $g=[guid]::Empty
    return [guid]::TryParseExact($Value,'D',[ref]$g)

}

function Test-VSO7ProcessPriorityName {

    param([string]$Value)
    return @('Idle','BelowNormal','Normal','AboveNormal','High','RealTime') -contains $Value

}

function Close-VSO7ProcessObjectVSO {

    param($Process)
    if($null-ne$Process){
        try{
            $Process.Dispose()
        }catch{}
    }

}

function Close-VSO7ProcessCollectionVSO {

    param($Processes)
    foreach($p in @($Processes)){
        Close-VSO7ProcessObjectVSO -Process $p
    }

}

function Test-VSO7GamingIdentityState {

    param($Identity)
    if(-not(Test-VSO7ExactJsonProperties -Object $Identity -Required @('Id','Name','Path','StartTimeUtc','Priority','AppliedPriority','PriorityStatus'))){
        return $false
    }
    if(-not(Test-VSO7JsonInteger -Value $Identity.Id -Min 1 -Max 2147483647)){
        return $false
    }
    if(-not($Identity.Name -is [string]) -or -not(Test-VSO7SafeProcessName ([string]$Identity.Name))){
        return $false
    }
    if(-not($Identity.Path -is [string])){
        return $false
    }
    if(-not[string]::IsNullOrWhiteSpace([string]$Identity.Path)){

        try{
            if(-not[IO.Path]::IsPathRooted([string]$Identity.Path)){
                return $false
            };
            $full=[IO.Path]::GetFullPath([string]$Identity.Path);
            if([string]::IsNullOrWhiteSpace($full)-or$full.Length-gt32767){
                return $false
            }
        }catch{
            return $false
        }

    }
    if(-not($Identity.StartTimeUtc -is [string]) -or -not(Test-VSO7IsoUtcTimestamp ([string]$Identity.StartTimeUtc))){
        return $false
    }
    if(-not($Identity.Priority -is [string]) -or -not(Test-VSO7ProcessPriorityName ([string]$Identity.Priority))){
        return $false
    }
    if(-not($Identity.AppliedPriority -is [string]) -or -not(Test-VSO7ProcessPriorityName ([string]$Identity.AppliedPriority))){
        return $false
    }
    if(-not($Identity.PriorityStatus -is [string]) -or @('Pending','Applied','NotApplied') -notcontains [string]$Identity.PriorityStatus){
        return $false
    }
    return $true

}

function Test-VSO7GamingSessionStateData {

    param($State)
    if(-not(Test-VSO7ExactJsonProperties -Object $State -Required @('SchemaVersion','Version','Timestamp','Game','Background','OldScheme','AppliedScheme','SchemeChanged'))){
        return $false
    }
    if(-not(Test-VSO7JsonInteger -Value $State.SchemaVersion -Min 3 -Max 3)){
        return $false
    }
    if(-not($State.Version -is [string]) -or [string]$State.Version-cne[string]$script:Version){
        return $false
    }
    if(-not($State.Timestamp -is [string]) -or -not(Test-VSO7IsoUtcTimestamp ([string]$State.Timestamp))){
        return $false
    }
    if($null-eq$State.Game -or -not(Test-VSO7GamingIdentityState -Identity $State.Game)){
        return $false
    }
    if([string]$State.Game.AppliedPriority -ine 'High'){
        return $false
    }
    if($null-eq$State.Background -or $State.Background -is [string]){
        return $false
    }
    $background=@($State.Background);
    if($background.Count-gt256){
        return $false
    };
    $seen=@{}
    foreach($entry in $background){

        if(-not(Test-VSO7GamingIdentityState -Identity $entry)){
            return $false
        }
        if([string]$entry.AppliedPriority -ine 'BelowNormal'){
            return $false
        }
        $key=("{0}|{1}"-f[int]$entry.Id,[string]$entry.StartTimeUtc);
        if($seen.ContainsKey($key)){
            return $false
        };
        $seen[$key]=$true

    }
    if(-not($State.SchemeChanged -is [bool])){
        return $false
    }
    if($null-ne$State.OldScheme -and -not($State.OldScheme -is [string])){
        return $false
    }
    if($null-ne$State.AppliedScheme -and -not($State.AppliedScheme -is [string])){
        return $false
    }
    if([bool]$State.SchemeChanged){

        if(-not(Test-VSO7PowerSchemeGuid ([string]$State.OldScheme))){
            return $false
        }
        if(-not(Test-VSO7PowerSchemeGuid ([string]$State.AppliedScheme))){
            return $false
        }
        if([string]$State.AppliedScheme -ine [string]$script:BuiltInPowerSchemes.HighPerformance){
            return $false
        }
        if([string]$State.OldScheme -ieq [string]$State.AppliedScheme){
            return $false
        }

    }else{

        if(-not[string]::IsNullOrWhiteSpace([string]$State.OldScheme) -and -not(Test-VSO7PowerSchemeGuid ([string]$State.OldScheme))){
            return $false
        }
        if(-not[string]::IsNullOrWhiteSpace([string]$State.AppliedScheme) -and -not(Test-VSO7PowerSchemeGuid ([string]$State.AppliedScheme))){
            return $false
        }

    }
    return $true

}

function Get-VSO7GamingBackgroundCandidates {

    param($GameIdentity)
    $patterns=@('Discord','EpicGamesLauncher','Medal','Overwolf','Spotify','SpotifyLauncher','RiotClientServices','RiotClientUx','steamwebhelper','Steam','msedge','chrome','opera','OneDrive','CurseForge','Code','Code - Insiders','JetBrains Toolbox','CapCut')
    $protected=@(Get-VSO7ProtectedProcesses|ForEach-Object{
        $_.ToLowerInvariant()
    });
    $result=@()
    $processes=@(Get-Process -ErrorAction SilentlyContinue)
    try{

        foreach($p in $processes){

            if($null-ne$GameIdentity -and [int]$p.Id-eq[int]$GameIdentity.Id -and (Test-VSO7ProcessIdentityMatch -Expected $GameIdentity -Process $p)){
                continue
            }
            if($protected-contains$p.ProcessName.ToLowerInvariant()){
                continue
            }
            $match=$false;
            foreach($pat in $patterns){
                if($p.ProcessName-like"*$pat*"){
                    $match=$true;
                    break
                }
            }
            if($match){
                $result += [pscustomobject]@{
                    ProcessName=[string]$p.ProcessName;
                    Id=[int]$p.Id;
                    WorkingSet64=[int64]$p.WorkingSet64
                }
            }

        }

    }finally{
        Close-VSO7ProcessCollectionVSO -Processes $processes
    }
    return @($result|Sort-Object ProcessName,Id -Unique)

}

function Get-VSO7GameCandidates {

    $protected=@(Get-VSO7ProtectedProcesses|ForEach-Object{
        $_.ToLowerInvariant()
    });
    $result=@();
    $processes=@(Get-Process -ErrorAction SilentlyContinue)
    try{

        foreach($p in $processes){

            if($p.MainWindowHandle-eq0-or$protected-contains$p.ProcessName.ToLowerInvariant()){
                continue
            }
            $id=Get-VSO7ProcessIdentity -Process $p
            if([string]::IsNullOrWhiteSpace([string]$id.StartTimeUtc)){
                continue
            }
            $result += [pscustomobject]@{
                ProcessName=[string]$p.ProcessName;
                Id=[int]$p.Id;
                WorkingSet64=[int64]$p.WorkingSet64;
                Path=[string]$id.Path;
                StartTimeUtc=[string]$id.StartTimeUtc
            }

        }

    }finally{
        Close-VSO7ProcessCollectionVSO -Processes $processes
    }
    return @($result|Sort-Object WorkingSet64 -Descending)

}

function Save-VSO7GamingProfile {

    param([string]$Name,[string]$GameProcessName,[string]$GameExe,[array]$BackgroundNames,[bool]$HighPerformance)
    if([string]::IsNullOrWhiteSpace($Name)){
        return
    }
    if(-not(Test-VSO7SafeProcessName $GameProcessName)){
        throw 'Nombre de proceso del juego invalido.'
    };
    if($GameProcessName.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
        $GameProcessName=$GameProcessName.Substring(0,$GameProcessName.Length-4)
    }
    $protected=@(Get-VSO7ProtectedProcesses|ForEach-Object{
        $_.ToLowerInvariant()
    });
    if($protected-contains$GameProcessName.ToLowerInvariant()){
        throw 'El proceso del juego esta en la lista protegida.'
    }
    $cleanBackground=@();
    foreach($bg in @($BackgroundNames)){
        $n=[string]$bg;
        if(-not(Test-VSO7SafeProcessName $n)){
            continue
        };
        if($n.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
            $n=$n.Substring(0,$n.Length-4)
        };
        if($protected-contains$n.ToLowerInvariant()){
            continue
        };
        $cleanBackground+=$n
    }
    if(-not[string]::IsNullOrWhiteSpace($GameExe)){
        try{
            if(-not[IO.Path]::IsPathRooted($GameExe)){
                throw
            };
            $GameExe=[IO.Path]::GetFullPath($GameExe)
        }catch{
            throw 'Ruta del ejecutable del juego invalida.'
        }
    }
    $safe=($Name-replace'[^a-zA-Z0-9._ -]','_').Trim(' ','.');
    if(-not$safe){
        $safe='Perfil'
    }
    $sha=[Security.Cryptography.SHA256]::Create();
    try{
        $nameHash=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Name))).Replace('-','')).Substring(0,12)
    }finally{
        $sha.Dispose()
    }
    $leaf=('{0}__{1}.json'-f$safe,$nameHash);
    $target=Join-Path $script:GamingProfileRoot $leaf
    if(Test-Path -LiteralPath $target -PathType Leaf){
        try{
            $existing=Get-Content -LiteralPath $target -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop;
            if([string]$existing.Name-cne$Name){
                throw 'Colision de nombre de perfil detectada; no se sobrescribe.'
            }
        }catch{
            throw
        }
    }
    $p=[pscustomobject]@{
        Name=$Name;
        GameProcessName=$GameProcessName;
        GameExe=$GameExe;
        BackgroundNames=@($cleanBackground|Sort-Object -Unique);
        HighPerformance=$HighPerformance;
        Created=(Get-Date).ToString('o')
    }
    $tmp=Join-Path $script:GamingProfileRoot ('.'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{
        $p|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop;
        [void](Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop);
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $target)
    }finally{
        if(Test-Path -LiteralPath $tmp -PathType Leaf){
            Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        }
    }

}

function Test-VSO7GamingProfileData {

    param([Alias('Profile')]$GamingProfile,[switch]$NoWait)
    if(-not(Test-VSO7ExactJsonProperties -Object $GamingProfile -Required @('Name','GameProcessName','GameExe','BackgroundNames','HighPerformance','Created'))){
        return $false
    }
    if(-not($GamingProfile.Name -is [string]) -or [string]::IsNullOrWhiteSpace([string]$GamingProfile.Name) -or ([string]$GamingProfile.Name).Length-gt128){
        return $false
    }
    if(-not($GamingProfile.GameProcessName -is [string])){
        return $false
    }
    $game=[string]$GamingProfile.GameProcessName
    if(-not(Test-VSO7SafeProcessName $game)){
        return $false
    }
    if($game.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
        $game=$game.Substring(0,$game.Length-4)
    }
    $protected=@(Get-VSO7ProtectedProcesses|ForEach-Object{
        $_.ToLowerInvariant()
    })
    if($protected-contains$game.ToLowerInvariant()){
        return $false
    }

    if($null-eq$GamingProfile.BackgroundNames -or $GamingProfile.BackgroundNames -is [string]){
        return $false
    }
    $background=@($GamingProfile.BackgroundNames)
    if($background.Count-gt128){
        return $false
    }
    $seen=@{}
    foreach($bg in $background){

        if(-not($bg -is [string])){
            return $false
        }
        $n=[string]$bg
        if(-not(Test-VSO7SafeProcessName $n)){
            return $false
        }
        if($n.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
            $n=$n.Substring(0,$n.Length-4)
        }
        if($protected-contains$n.ToLowerInvariant()){
            return $false
        }
        $key=$n.ToLowerInvariant()
        if($seen.ContainsKey($key)){
            return $false
        }
        $seen[$key]=$true

    }

    if(-not($GamingProfile.GameExe -is [string])){
        return $false
    }
    if(-not[string]::IsNullOrWhiteSpace([string]$GamingProfile.GameExe)){

        try{

            if(-not[IO.Path]::IsPathRooted([string]$GamingProfile.GameExe)){
                return $false
            }
            $full=[IO.Path]::GetFullPath([string]$GamingProfile.GameExe)
            if([string]::IsNullOrWhiteSpace($full)-or$full.Length-gt32767){
                return $false
            }

        }catch{
            return $false
        }

    }
    if(-not($GamingProfile.HighPerformance -is [bool])){
        return $false
    }
    if(-not($GamingProfile.Created -is [string]) -or -not(Test-VSO7IsoUtcTimestamp ([string]$GamingProfile.Created))){
        return $false
    }
    return $true

}

function Get-VSO7GamingProfiles {

    $r=@();
    if(-not(Test-Path -LiteralPath $script:GamingProfileRoot)){
        return $r
    }
    foreach($f in Get-ChildItem -LiteralPath $script:GamingProfileRoot -File -Filter '*.json' -ErrorAction SilentlyContinue){

        try{
            $p=Get-Content -LiteralPath $f.FullName -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop;
            if(Test-VSO7GamingProfileData $p){
                $r += [pscustomobject]@{
                    Path=$f.FullName;
                    Data=$p
                }
            }else{
                Write-VSO7Log ("Perfil Gaming rechazado por validacion: {0}"-f$f.FullName) 'WARN'
            }
        }catch{
            Write-VSO7Log ("Perfil Gaming invalido: {0}"-f$f.FullName) 'WARN'
        }

    }
    return @($r)

}

function Get-VSO7ProcessIdentity {

    param([Parameter(Mandatory=$true)]$Process)
    $path=$null;
    $start=$null
    try{
        $path=[string]$Process.Path
    }catch{}
    if([string]::IsNullOrWhiteSpace($path)){

        try{
            $ci=CimCmdlets\Get-CimInstance Win32_Process -Filter ("ProcessId={0}"-f$Process.Id) -ErrorAction Stop;
            $path=[string]$ci.ExecutablePath
        }catch{}

    }
    try{
        $start=$Process.StartTime.ToUniversalTime().ToString('o')
    }catch{}
    return [pscustomobject]@{
        Id=[int]$Process.Id;
        Name=[string]$Process.ProcessName;
        Path=$path;
        StartTimeUtc=$start
    }

}

function Test-VSO7ProcessIdentityMatch {

    param([Parameter(Mandatory=$true)]$Expected,[Parameter(Mandatory=$true)]$Process)
    if([int]$Expected.Id -ne [int]$Process.Id){
        return $false
    }
    if(-not[string]::IsNullOrWhiteSpace([string]$Expected.Name) -and [string]$Expected.Name -ine [string]$Process.ProcessName){
        return $false
    }
    $actual=Get-VSO7ProcessIdentity -Process $Process
    if(-not[string]::IsNullOrWhiteSpace([string]$Expected.StartTimeUtc)){

        if([string]::IsNullOrWhiteSpace([string]$actual.StartTimeUtc) -or [string]$actual.StartTimeUtc -ne [string]$Expected.StartTimeUtc){
            return $false
        }

    }
    if(-not[string]::IsNullOrWhiteSpace([string]$Expected.Path)){

        if([string]::IsNullOrWhiteSpace([string]$actual.Path)){
            return $false
        }
        try{

            if([IO.Path]::GetFullPath([string]$actual.Path).TrimEnd('\') -ine [IO.Path]::GetFullPath([string]$Expected.Path).TrimEnd('\')){
                return $false
            }

        }catch{
            return $false
        }

    }
    return $true

}

function Select-VSO7ProcessInstance {

    param([string]$ProcessName,[string]$ExecutablePath,$ExpectedIdentity)
    if(-not(Test-VSO7SafeProcessName $ProcessName)){
        return $null
    }
    if($ProcessName.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
        $ProcessName=$ProcessName.Substring(0,$ProcessName.Length-4)
    }
    $protectedNames=@(Get-VSO7ProtectedProcesses|ForEach-Object{
        $_.ToLowerInvariant()
    });
    if($protectedNames-contains$ProcessName.ToLowerInvariant()){
        return $null
    }

    if($null-ne$ExpectedIdentity -and [int]$ExpectedIdentity.Id-gt0){

        $p=Get-Process -Id ([int]$ExpectedIdentity.Id) -ErrorAction SilentlyContinue
        if($null-ne$p){
            if(Test-VSO7ProcessIdentityMatch -Expected $ExpectedIdentity -Process $p){
                return $p
            };
            Close-VSO7ProcessObjectVSO -Process $p
        }

    }

    $candidates=@(Get-Process -Name $ProcessName -ErrorAction SilentlyContinue)
    if(-not[string]::IsNullOrWhiteSpace($ExecutablePath)){

        $exact=@();
        $rejected=@()
        foreach($p in $candidates){

            $match=$false
            try{
                $id=Get-VSO7ProcessIdentity -Process $p;
                if(-not[string]::IsNullOrWhiteSpace([string]$id.Path)-and[IO.Path]::GetFullPath([string]$id.Path).TrimEnd('\')-ieq[IO.Path]::GetFullPath($ExecutablePath).TrimEnd('\')){
                    $match=$true
                }
            }catch{}
            if($match){
                $exact+=$p
            }else{
                $rejected+=$p
            }

        }
        Close-VSO7ProcessCollectionVSO -Processes $rejected
        $candidates=$exact

    }
    if($candidates.Count-eq0){
        return $null
    }
    if($candidates.Count-eq1){
        return $candidates[0]
    }

    Write-Title;
    Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Hay varias instancias de {0}. Elige la correcta.' -En 'Several instances of {0} are running. Choose the correct one.')-f$ProcessName) -Color 'Yellow'
    $rows=@();
    for($i=0;$i-lt$candidates.Count;$i++){
        $rows += [pscustomobject]@{
            Text=("[{0,2}] PID {1,-7} RAM {2,7:N0} MB"-f($i+1),$candidates[$i].Id,($candidates[$i].WorkingSet64/1MB));
            Color='Gray'
        }
    }
    Write-CenteredMenuVSO -Items $rows
    $n=0;
    $raw=Read-CenteredPromptVSO -AnimatedMenu 'Numero';
    $selected=$null
    if([int]::TryParse($raw,[ref]$n)-and$n-ge1-and$n-le$candidates.Count){
        $selected=$candidates[$n-1]
    }
    foreach($p in $candidates){
        if($null-eq$selected-or[int]$p.Id-ne[int]$selected.Id){
            Close-VSO7ProcessObjectVSO -Process $p
        }
    }
    return $selected

}

function Save-VSO7GamingSessionState {

    param([Parameter(Mandatory=$true)]$State)
    if(-not(Test-VSO7GamingSessionStateData -State $State)){
        throw 'VSO7 se nego a persistir un estado Gaming semanticamente invalido.'
    }
    $tmp=$script:GamingSessionStateFile+'.tmp'
    try{

        $State|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        if(-not(Test-VSO7GamingSessionStateData -State $check)){
            throw 'La verificacion semantica del estado temporal Gaming fallo.'
        }
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $script:GamingSessionStateFile)
        $check=Get-Content -LiteralPath $script:GamingSessionStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        if(-not(Test-VSO7GamingSessionStateData -State $check)){
            throw 'La verificacion semantica del estado Gaming persistido fallo.'
        }

    }catch{

        try{
            if(Test-Path -LiteralPath $tmp -PathType Leaf){
                Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
            }
        }catch{}
        Write-VSO7Log ("No se pudo guardar/verificar gaming-session-active.json: {0}"-f$_.Exception.Message) 'ERROR'
        throw

    }

}

function Restore-VSO7GamingSessionState {

    if(-not(Test-Path -LiteralPath $script:GamingSessionStateFile)){
        return $true
    }
    try{
        $st=Get-Content -LiteralPath $script:GamingSessionStateFile -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    }catch{
        Write-VSO7Log ("gaming-session-active.json es ilegible: {0}"-f$_.Exception.Message) 'ERROR';
        return $false
    }
    if(-not(Test-VSO7GamingSessionStateData -State $st)){
        Write-VSO7Log 'gaming-session-active.json fue rechazado por validacion semantica estricta; se conserva sin ejecutar ninguna restauracion.' 'ERROR';
        return $false
    }

    $ok=$true
    foreach($b in @($st.Background)){

        if([string]$b.PriorityStatus-ieq'NotApplied'){
            continue
        }
        $p=Get-Process -Id ([int]$b.Id) -ErrorAction SilentlyContinue
        if($null-eq$p){
            continue
        }
        try{

            if(-not(Test-VSO7ProcessIdentityMatch -Expected $b -Process $p)){
                Write-VSO7Log ("No se restaura PID {0}: identidad distinta o PID reutilizado ({1})."-f$b.Id,$b.Name) 'WARN';
                continue
            }
            $currentPriority=$null;
            try{
                $currentPriority=[string]$p.PriorityClass
            }catch{
                $ok=$false;
                Write-VSO7Log ("No se pudo leer prioridad actual de PID {0}."-f$b.Id) 'ERROR';
                continue
            }
            if($currentPriority-ieq[string]$b.Priority){
                continue
            }
            if([string]$b.PriorityStatus-ieq'Pending'){

                $ok=$false;
                Write-VSO7Log ("Prioridad Gaming Pending ambigua para {0} PID {1}: actual={2}, baseline={3}, objetivo={4}; se conserva evidencia sin tocarla."-f$b.Name,$b.Id,$currentPriority,$b.Priority,$b.AppliedPriority) 'ERROR';
                continue

            }
            if($currentPriority-ine[string]$b.AppliedPriority){
                Write-VSO7Log ("No se restaura prioridad de {0} PID {1}: cambio externo detectado ({2}, VSO7 esperaba {3})."-f$b.Name,$b.Id,$currentPriority,$b.AppliedPriority) 'WARN';
                continue
            }
            try{
                $p.PriorityClass=[string]$b.Priority;
                if([string]$p.PriorityClass-ine[string]$b.Priority){
                    throw 'La prioridad original no quedo aplicada.'
                }
            }catch{
                $ok=$false;
                Write-VSO7Log ("No se pudo restaurar prioridad de {0} PID {1}: {2}"-f$b.Name,$b.Id,$_.Exception.Message) 'ERROR'
            }

        }finally{
            Close-VSO7ProcessObjectVSO -Process $p
        }

    }

    if([string]$st.Game.PriorityStatus-ine'NotApplied'){

        $gp=Get-Process -Id ([int]$st.Game.Id) -ErrorAction SilentlyContinue
        if($null-ne$gp){

            try{

                if(Test-VSO7ProcessIdentityMatch -Expected $st.Game -Process $gp){

                    $currentPriority=$null;
                    try{
                        $currentPriority=[string]$gp.PriorityClass
                    }catch{
                        $ok=$false;
                        Write-VSO7Log ("No se pudo leer prioridad actual del juego PID {0}."-f$st.Game.Id) 'ERROR'
                    }
                    if($null-ne$currentPriority-and$currentPriority-ine[string]$st.Game.Priority){

                        if([string]$st.Game.PriorityStatus-ieq'Pending'){
                            $ok=$false;
                            Write-VSO7Log ("Prioridad del juego Pending ambigua PID {0}: actual={1}, baseline={2}, objetivo={3}; se conserva evidencia."-f$st.Game.Id,$currentPriority,$st.Game.Priority,$st.Game.AppliedPriority) 'ERROR'
                        }
                        elseif($currentPriority-ieq[string]$st.Game.AppliedPriority){
                            try{
                                $gp.PriorityClass=[string]$st.Game.Priority;
                                if([string]$gp.PriorityClass-ine[string]$st.Game.Priority){
                                    throw 'La prioridad original del juego no quedo aplicada.'
                                }
                            }catch{
                                $ok=$false;
                                Write-VSO7Log ("No se pudo restaurar prioridad del juego PID {0}: {1}"-f$st.Game.Id,$_.Exception.Message) 'ERROR'
                            }
                        }
                        else{
                            Write-VSO7Log ("No se restaura prioridad del juego PID {0}: cambio externo detectado ({1}, VSO7 esperaba {2})."-f$st.Game.Id,$currentPriority,$st.Game.AppliedPriority) 'WARN'
                        }

                    }

                }else{
                    Write-VSO7Log ("No se restaura PID de juego {0}: identidad distinta o PID reutilizado."-f$st.Game.Id) 'WARN'
                }

            }finally{
                Close-VSO7ProcessObjectVSO -Process $gp
            }

        }

    }

    if([bool]$st.SchemeChanged){

        try{

            $currentScheme=[string](Get-ActivePowerSchemeGuid);
            if([string]::IsNullOrWhiteSpace($currentScheme)){
                throw 'No se pudo determinar el plan de energia activo.'
            }
            if($currentScheme-ieq[string]$st.AppliedScheme){
                Invoke-NativeCommandVSO -FilePath 'powercfg.exe' -Arguments @('/setactive',[string]$st.OldScheme)|Out-Null;
                if([string](Get-ActivePowerSchemeGuid)-ine[string]$st.OldScheme){
                    throw 'No se verifico el plan original.'
                }
            }
            elseif($currentScheme-ieq[string]$st.OldScheme){
                Write-VSO7Log 'El plan original de Gaming ya estaba restaurado.' 'INFO'
            }
            else{
                Write-VSO7Log ("No se restaura energia Gaming: cambio externo detectado ({0}, VSO7 esperaba {1})."-f$currentScheme,$st.AppliedScheme) 'WARN'
            }

        }catch{
            Write-VSO7Log ("No se pudo reconciliar/verificar energia Gaming: {0}"-f$_.Exception.Message) 'ERROR';
            $ok=$false
        }

    }

    if($ok){
        try{
            Remove-Item -LiteralPath $script:GamingSessionStateFile -Force -ErrorAction Stop
        }catch{
            $ok=$false;
            Write-VSO7Log 'Se reconcilio Gaming pero no se pudo eliminar su estado activo; se bloquean nuevas sesiones para no sobrescribirlo.' 'ERROR'
        }
    }
    return $ok

}

function Repair-StaleVSO7GamingSessionIfNeeded {

    if(-not(Test-Path -LiteralPath $script:GamingSessionStateFile)){
        return $true
    }
    Write-VSOHost '';
    Write-VSOHost 'VSO7 encontro una sesion Gaming anterior sin cerrar correctamente.' -ForegroundColor Yellow;
    Write-VSOHost 'Restaurando prioridades y plan de energia conservados...' -ForegroundColor Yellow
    if(Restore-VSO7GamingSessionState){
        Write-VSOHost '[OK] Estado temporal restaurado.' -ForegroundColor Green;
        return $true
    }
    Write-VSOHost '[BLOQUEADO] La restauracion fue incompleta. No se iniciara otra sesion Gaming ni se sobrescribira el JSON pendiente.' -ForegroundColor Red
    return $false

}

function Invoke-VSO7GamingSession {

    param([Alias('Profile')]$GamingProfile,[switch]$NoWait)
    if(Test-Path -LiteralPath $script:GamingSessionStateFile){
        if(-not(Restore-VSO7GamingSessionState)){
            Write-VSOHost 'Hay una sesion Gaming pendiente que no pudo restaurarse. Nueva sesion bloqueada.' -ForegroundColor Red;
            Pause-Vico;
            return
        }
    }
    $gameName='';
    $gameExe='';
    $backgroundNames=@();
    $useHP=$false;
    $preferredIdentity=$null
    if($null-ne$GamingProfile){

        if(-not(Test-VSO7GamingProfileData $GamingProfile)){
            Write-VSOHost 'Perfil Gaming rechazado: contiene procesos/rutas no validos o protegidos.' -ForegroundColor Red;
            Pause-Vico;
            return
        }
        $gameName=[string]$GamingProfile.GameProcessName;
        if($gameName.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
            $gameName=$gameName.Substring(0,$gameName.Length-4)
        }
        $gameExe=[string]$GamingProfile.GameExe;
        $backgroundNames=@($GamingProfile.BackgroundNames|ForEach-Object{
            $n=[string]$_;if($n.EndsWith('.exe',[StringComparison]::OrdinalIgnoreCase)){
                $n.Substring(0,$n.Length-4)
            }else{
                $n
            }
        });
        $useHP=[bool]$GamingProfile.HighPerformance

    }
    if([string]::IsNullOrWhiteSpace($gameName)){

        $games=@(Get-VSO7GameCandidates);
        if($games.Count-eq0){
            Write-VSOHost 'No hay aplicaciones con ventana detectadas.' -ForegroundColor Yellow;
            Pause-Vico;
            return
        }
        Write-Title;
        Write-CenteredLineVSO -Text 'SELECCIONA EL JUEGO / APLICACION' -Color $script:ThemeCopper
        $rows=@();
        for($i=0;$i-lt[math]::Min($games.Count,30);$i++){
            $rows += [pscustomobject]@{
                Text=("[{0}] {1}"-f($i+1),$games[$i].ProcessName);
                Color='Gray';
                Description=("PID {0} | RAM aproximada: {1:N0} MB. Seleccionarlo solo identifica el juego para preparar la sesion; todavia no cambia nada."-f$games[$i].Id,($games[$i].WorkingSet64/1MB))
            }
        };
        Write-VSO7TwoColumnOptionsVSO -Items $rows
        $n=0;
        $raw=Read-CenteredPromptVSO -AnimatedMenu 'Numero';
        if(-not([int]::TryParse($raw,[ref]$n))-or$n-lt1-or$n-gt[math]::Min($games.Count,30)){
            return
        }
        $g=$games[$n-1];
        $gameName=[string]$g.ProcessName;
        $preferredIdentity=[pscustomobject]@{
            Id=[int]$g.Id;
            Name=[string]$g.ProcessName;
            Path=[string]$g.Path;
            StartTimeUtc=[string]$g.StartTimeUtc
        };
        $gameExe=[string]$g.Path
        if([string]::IsNullOrWhiteSpace($gameExe)){
            try{
                $ci=CimCmdlets\Get-CimInstance Win32_Process -Filter ("ProcessId={0}"-f$g.Id) -ErrorAction Stop;
                $gameExe=[string]$ci.ExecutablePath
            }catch{}
        }
        $cands=@(Get-VSO7GamingBackgroundCandidates -GameIdentity $preferredIdentity);
        $sel=@{}
        while($true){

            Write-Title;
            Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'SESION GAMING: {0}' -En 'GAMING SESSION: {0}')-f$gameName) -Color $script:ThemeCopper;
            Write-CenteredLineVSO -Text 'Selecciona procesos para bajar temporalmente a prioridad BelowNormal.' -Color $script:ThemeText
            $br=@();
            for($i=0;$i-lt$cands.Count;$i++){
                $m=if($sel.ContainsKey($cands[$i].ProcessName)){
                    'X'
                }else{
                    ' '
                };
                $br += [pscustomobject]@{
                    Text=("[{0}] [{1}] {2}"-f($i+1),$m,$cands[$i].ProcessName);
                    Color='Gray';
                    Description=("RAM aproximada: {0:N0} MB. Si lo marcas, VSO7 intentara bajarlo temporalmente a prioridad BelowNormal mientras juegas."-f($cands[$i].WorkingSet64/1MB))
                }
            };
            if($br.Count){
                Write-VSO7TwoColumnOptionsVSO -Items $br
            }else{
                Write-CenteredLineVSO -Text 'No hay candidatos conocidos activos.' -Color 'DarkGray'
            }
            $allBackground=$cands.Count+1;
            $continueBackground=$cands.Count+2
            Write-CenteredMenuVSO -Items @([pscustomobject]@{
                Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Seleccionar todos los candidatos' -En '[{0}] Select all candidates')-f$allBackground);Color='Gray';Description='Marca todos los procesos de fondo mostrados; todavia no cambia prioridades.'
            },[pscustomobject]@{
                Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Continuar con esta seleccion' -En '[{0}] Continue with this selection')-f$continueBackground);Color='Green';Description='Pasa a la confirmacion de energia y perfil con los procesos que hayas marcado.'
            },[pscustomobject]@{
                Text='[0] Cancelar';Color='Gray';Description='Cancela la creacion de esta sesion gaming sin aplicar cambios.';SeparatorBefore=$true
            });
            $c=Read-CenteredPromptVSO 'Opcion / numero'
            if($c-eq'0'){
                return
            };
            $z=0;
            if(-not[int]::TryParse($c,[ref]$z)){
                continue
            };
            if($z-eq$allBackground){
                foreach($x in $cands){
                    $sel[$x.ProcessName]=$true
                };
                continue
            };
            if($z-eq$continueBackground){
                break
            };
            if($z-ge1-and$z-le$cands.Count){
                $pn=$cands[$z-1].ProcessName;
                if($sel.ContainsKey($pn)){
                    $sel.Remove($pn)
                }else{
                    $sel[$pn]=$true
                }
            }

        }
        $backgroundNames=@($sel.Keys);
        $useHP=((Read-VSOHost '¿Usar temporalmente Alto rendimiento si esta disponible? [S/N]')-match'^[sSyY]$')
        if((Read-VSOHost '¿Guardar esta configuracion como perfil? [S/N]')-match'^[sSyY]$'){
            $pn=Read-VSOHost 'Nombre del perfil';
            Save-VSO7GamingProfile -Name $pn -GameProcessName $gameName -GameExe $gameExe -BackgroundNames $backgroundNames -HighPerformance $useHP
        }

    }

    $game=Select-VSO7ProcessInstance -ProcessName $gameName -ExecutablePath $gameExe -ExpectedIdentity $preferredIdentity
    if($null-eq$game){
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es 'No se encontro una instancia inequívoca de {0}. VSO7 no inicia ejecutables desde perfiles elevados: inicia el juego normalmente y vuelve a intentarlo.' -En 'No unambiguous instance of {0} was found. VSO7 does not launch executables from an elevated process; start the game normally and try again.')-f$gameName) -ForegroundColor Red;
        Pause-Vico;
        return
    }

    $restoreOk=$false;$deferRestore=$false
    try{

        $oldGamePriority=$null;
        try{
            $oldGamePriority=[string]$game.PriorityClass
        }catch{}
        $gameIdentity=Get-VSO7ProcessIdentity -Process $game
        if(-not(Test-VSO7ProcessPriorityName $oldGamePriority)-or[string]::IsNullOrWhiteSpace([string]$gameIdentity.StartTimeUtc)){
            Write-VSOHost 'No se pudo obtener una identidad/prioridad suficientemente robusta del juego. Sesion cancelada sin cambios.' -ForegroundColor Red;
            Pause-Vico;
            return
        }
        $priorityBackups=@();
        $protectedNow=@(Get-VSO7ProtectedProcesses|ForEach-Object{
            $_.ToLowerInvariant()
        })
        foreach($name in $backgroundNames){

            $backgroundName=[string]$name;
            $backgroundLower=$backgroundName.ToLowerInvariant();
            if(-not(Test-VSO7SafeProcessName $backgroundName)-or($protectedNow-contains$backgroundLower)){
                Write-VSO7Log ("Proceso de fondo Gaming omitido por validacion/proteccion: {0}"-f$backgroundName) 'WARN';
                continue
            }
            $procs=@(Get-Process -Name $name -ErrorAction SilentlyContinue)
            foreach($p in $procs){

                try{
                    $id=Get-VSO7ProcessIdentity -Process $p;
                    if($id.Id-eq$gameIdentity.Id-and(Test-VSO7ProcessIdentityMatch -Expected $gameIdentity -Process $p)){
                        continue
                    };
                    $originalPriority=[string]$p.PriorityClass;
                    if([string]::IsNullOrWhiteSpace([string]$id.StartTimeUtc)-or-not(Test-VSO7ProcessPriorityName $originalPriority)){
                        Write-VSO7Log ("Proceso Gaming omitido porque su identidad/prioridad no pudo validarse: {0} PID {1}"-f$p.ProcessName,$p.Id) 'WARN';
                        continue
                    };
                    $priorityBackups += [pscustomobject]@{
                        Id=$id.Id;
                        Name=$id.Name;
                        Path=[string]$id.Path;
                        StartTimeUtc=$id.StartTimeUtc;
                        Priority=$originalPriority;
                        AppliedPriority='BelowNormal';
                        PriorityStatus='Pending'
                    }
                }catch{
                    Write-VSO7Log ("No se pudo capturar proceso Gaming de fondo {0}: {1}"-f$backgroundName,$_.Exception.Message) 'WARN'
                }finally{
                    Close-VSO7ProcessObjectVSO -Process $p
                }

            }

        }
        $oldScheme=$null;
        $schemeChanged=$false;
        $hpGuid=$null
        if($useHP){
            $oldScheme=Get-ActivePowerSchemeGuid;
            if([string]::IsNullOrWhiteSpace([string]$oldScheme)){
                Write-VSO7Log 'VSO7 no cambiara el plan de energia temporal porque no pudo guardar el plan original.' 'WARN';
                $useHP=$false
            }else{
                $hp=@(Get-AllPowerSchemes|Where-Object{
                    $_.BuiltInName-eq'HighPerformance'
                }|Select-Object -First 1);
                if($hp.Count){
                    $hpGuid=[string]$hp[0].Guid;
                    $schemeChanged=($hpGuid-ne$oldScheme)
                }
            }
        }
        $sessionState=[pscustomobject]@{
            SchemaVersion=3;
            Version=$script:Version;
            Timestamp=(Get-Date).ToString('o');
            Game=[pscustomobject]@{
                Id=$gameIdentity.Id;
                Name=$gameIdentity.Name;
                Path=[string]$gameIdentity.Path;
                StartTimeUtc=$gameIdentity.StartTimeUtc;
                Priority=$oldGamePriority;
                AppliedPriority='High';
                PriorityStatus='Pending'
            };
            Background=$priorityBackups;
            OldScheme=$oldScheme;
            AppliedScheme=$hpGuid;
            SchemeChanged=$schemeChanged
        }
        Save-VSO7GamingSessionState $sessionState

        # Cada prioridad pasa a Applied SOLO despues de revalidar baseline, escribir y releer.
        try{

            $gameBefore=[string]$game.PriorityClass
            if($gameBefore-ine$oldGamePriority){
                $sessionState.Game.PriorityStatus='NotApplied';
                Write-VSO7Log ("Prioridad del juego cambio externamente entre snapshot y mutacion ({0} -> {1}); VSO7 no la pisa."-f$oldGamePriority,$gameBefore) 'WARN'
            }
            else{
                $game.PriorityClass='High';
                if([string]$game.PriorityClass-ine'High'){
                    throw 'Windows no confirmo prioridad High.'
                };
                $sessionState.Game.PriorityStatus='Applied'
            }

        }catch{
            $reason=$_.Exception.Message;
            try{
                $cur=[string]$game.PriorityClass;
                if($cur-ieq$oldGamePriority){
                    $sessionState.Game.PriorityStatus='NotApplied'
                }
            }catch{};
            Write-VSO7Log ("No se pudo aplicar/verificar prioridad High al juego: {0}"-f$reason) 'WARN'
        }
        Save-VSO7GamingSessionState $sessionState

        foreach($b in @($sessionState.Background)){

            $p=Get-Process -Id ([int]$b.Id) -ErrorAction SilentlyContinue
            if($null-eq$p){
                $b.PriorityStatus='NotApplied';
                Save-VSO7GamingSessionState $sessionState;
                continue
            }
            try{

                if(-not(Test-VSO7ProcessIdentityMatch -Expected $b -Process $p)){
                    $b.PriorityStatus='NotApplied';
                    Save-VSO7GamingSessionState $sessionState;
                    continue
                }
                try{

                    $beforePriority=[string]$p.PriorityClass
                    if($beforePriority-ine[string]$b.Priority){
                        $b.PriorityStatus='NotApplied';
                        Write-VSO7Log ("Prioridad de {0} PID {1} cambio externamente entre snapshot y mutacion ({2} -> {3}); VSO7 no la pisa."-f$b.Name,$b.Id,$b.Priority,$beforePriority) 'WARN'
                    }
                    else{
                        $p.PriorityClass='BelowNormal';
                        if([string]$p.PriorityClass-ine'BelowNormal'){
                            throw 'Windows no confirmo BelowNormal.'
                        };
                        $b.PriorityStatus='Applied'
                    }

                }catch{
                    $reason=$_.Exception.Message;
                    try{
                        $cur=[string]$p.PriorityClass;
                        if($cur-ieq[string]$b.Priority){
                            $b.PriorityStatus='NotApplied'
                        }
                    }catch{};
                    Write-VSO7Log ("No se pudo aplicar/verificar prioridad BelowNormal a {0}: {1}"-f$b.Name,$reason) 'WARN'
                }
                Save-VSO7GamingSessionState $sessionState

            }finally{
                Close-VSO7ProcessObjectVSO -Process $p
            }

        }

        if($schemeChanged-and$hpGuid){

            $schemeBefore=[string](Get-ActivePowerSchemeGuid)
            if([string]::IsNullOrWhiteSpace($schemeBefore)-or$schemeBefore-ine[string]$oldScheme){

                $sessionState.SchemeChanged=$false;
                Save-VSO7GamingSessionState $sessionState
                Write-VSO7Log ("El plan de energia cambio/no pudo revalidarse antes de Gaming (baseline {0}, actual {1}); VSO7 no activa Alto rendimiento."-f$oldScheme,$schemeBefore) 'WARN'

            }else{

                try{
                    Invoke-NativeCommandVSO -FilePath powercfg.exe -Arguments @('/setactive',$hpGuid)|Out-Null;
                    if([string](Get-ActivePowerSchemeGuid)-ine[string]$hpGuid){
                        throw 'Windows no confirmo Alto rendimiento como plan activo.'
                    }
                }
                catch{
                    $reason=$_.Exception.Message;
                    Write-VSO7Log ("No se pudo activar/verificar Alto rendimiento temporal: {0}"-f$reason) 'WARN';
                    try{
                        if(-not[string]::IsNullOrWhiteSpace([string]$oldScheme)){

                    $activeAfterFailure=[string](Get-ActivePowerSchemeGuid)
                    if($activeAfterFailure-ieq[string]$hpGuid){

                        Invoke-NativeCommandVSO -FilePath powercfg.exe -Arguments @('/setactive',$oldScheme)|Out-Null
                        if([string](Get-ActivePowerSchemeGuid)-ine[string]$oldScheme){
                                    throw 'No se pudo verificar la restauracion inmediata del plan original.'
                                }
                        $sessionState.SchemeChanged=$false;
                                Save-VSO7GamingSessionState $sessionState

                            }elseif($activeAfterFailure-ieq[string]$oldScheme){

                        $sessionState.SchemeChanged=$false;
                                Save-VSO7GamingSessionState $sessionState

                            }else{

                        # Drift externo: no robar el plan que otra aplicacion/usuario activo.
                        $sessionState.SchemeChanged=$false;
                                Save-VSO7GamingSessionState $sessionState
                        Write-VSO7Log ("Gaming detecto un plan externo tras fallar Alto rendimiento ({0}); VSO7 no reactiva {1}."-f$activeAfterFailure,$oldScheme) 'WARN'

                            }

                        }
                    }catch{
                        Write-VSO7Log ("No se pudo garantizar la reconciliacion inmediata del plan tras fallo Gaming: {0}"-f$_.Exception.Message) 'ERROR'
                    }
                }

            }

        }
        if($NoWait){
            $deferRestore=$true
            return [pscustomobject]@{Started=$true;GameIdentity=$gameIdentity}
        }
        Write-Title;
        Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'SESION GAMING ACTIVA: {0}' -En 'ACTIVE GAMING SESSION: {0}')-f$gameName) -Color 'Green';
        Write-CenteredLineVSO -Text 'VSO7 restaurara prioridades y energia cuando cierre el proceso.' -Color $script:ThemeText
        while($true){

            $current=Get-Process -Id $gameIdentity.Id -ErrorAction SilentlyContinue
            if($null-eq$current){
                break
            }
            try{
                if(-not(Test-VSO7ProcessIdentityMatch -Expected $gameIdentity -Process $current)){
                    Write-VSO7Log 'El PID del juego fue reutilizado; VSO7 da por finalizada la sesion sin tocar el nuevo proceso.' 'WARN';
                    break
                }
            }finally{
                Close-VSO7ProcessObjectVSO -Process $current
            }
            Start-Sleep -Seconds 2

        }

    }finally{

        Close-VSO7ProcessObjectVSO -Process $game
        if(-not$deferRestore){$restoreOk=[bool](Restore-VSO7GamingSessionState)}

    }
    if($restoreOk){
        Write-VSOHost 'Sesion terminada; estado temporal restaurado.' -ForegroundColor Green
    }else{
        Write-VSOHost 'Sesion terminada, pero la restauracion temporal fue incompleta.' -ForegroundColor Red;
        Write-VSOHost 'VSO7 conserva el estado para reintentar la restauracion en el siguiente inicio.' -ForegroundColor Yellow
    }
    Pause-Vico

}

function Show-VSO7GamingSessionMenu {

    while($true){

        Write-Title;
        Write-CenteredLineVSO -Text 'MODO GAMING TEMPORAL' -Color $script:ThemeCopper
        Write-CenteredLineVSO -Text 'Aplica ajustes temporales mientras juegas y VSO7 intenta restaurarlos al terminar la sesion.' -Color 'Green'
        Write-CenteredLineVSO -Text 'Entrar en esta pantalla no inicia ninguna sesion ni cambia prioridades.' -Color $script:ThemeText
        Write-VSOHost ''
        $profiles=@(Get-VSO7GamingProfiles);
        $rows=@()
        for($i=0;$i-lt$profiles.Count;$i++){
            $rows += [pscustomobject]@{
                Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Perfil: {1}' -En '[{0}] Profile: {1}')-f($i+1),$profiles[$i].Data.Name);
                Color='Gray';
                Description=($(Get-VSO7ConsoleTextVSO -Es 'Usa el perfil guardado para el proceso {0}; podras revisar la sesion antes de iniciarla.' -En 'Uses the saved profile for process {0}; you can review the session before starting it.')-f$profiles[$i].Data.GameProcessName)
            }
        }
        if($rows.Count){
            Write-VSO7TwoColumnOptionsVSO -Items $rows
        }
        $newNumber=$profiles.Count+1;
        $protectNumber=$profiles.Count+2
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Nueva sesion desde un proceso activo' -En '[{0}] New session from a running process')-f$newNumber);Color='Cyan';Description='Eliges un juego que ya este abierto y VSO7 prepara una sesion temporal para ese proceso.'
        },
            [pscustomobject]@{
            Text=($(Get-VSO7ConsoleTextVSO -Es '[{0}] Gestionar exclusiones y procesos protegidos' -En '[{0}] Manage exclusions and protected processes')-f$protectNumber);Color='Gray';Description='Define procesos que VSO7 no debe cerrar ni reducir durante una sesion gaming.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';Description='Regresa sin iniciar ninguna sesion nueva.';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion';
        if($c-eq'0'){
            return
        };
        $n=0;
        if(-not[int]::TryParse($c,[ref]$n)){
            continue
        }
        if($n-ge1-and$n-le$profiles.Count){
            Invoke-VSO7GamingSession -Profile $profiles[$n-1].Data;
            continue
        }
        if($n-eq$newNumber){
            Invoke-VSO7GamingSession -Profile $null;
            continue
        }
        if($n-eq$protectNumber){
            Show-VSO7ProtectionManager;
            continue
        }

    }

}

function New-VSO7TuningFindingVSO {

    param(
        [Parameter(Mandatory=$true)][int]$Risk,
        [Parameter(Mandatory=$true)][string]$Area,
        [Parameter(Mandatory=$true)][string]$Item,
        [Parameter(Mandatory=$true)][string]$Configured,
        [Parameter(Mandatory=$true)][string]$Effective,
        [Parameter(Mandatory=$true)][string]$State,
        [string]$Evidence='Unrated',
        [string]$Maturity='Diagnostic',
        [Parameter(Mandatory=$true)][string]$WhyEs,
        [string]$WhyEn='',
        [string]$RecommendationEs='',
        [string]$RecommendationEn='',
        [string]$LinkedFeature=''
    )
    if([string]::IsNullOrWhiteSpace($WhyEn)){
        $WhyEn=$WhyEs
    }
    if([string]::IsNullOrWhiteSpace($RecommendationEs)){
        $RecommendationEs='Revisar y medir; no asumir que el override mejora rendimiento.'
    }
    if([string]::IsNullOrWhiteSpace($RecommendationEn)){
        $RecommendationEn=$RecommendationEs
    }
    return [pscustomobject]@{
        Risk=$Risk;
        Area=$Area;
        Item=$Item;
        Configured=$Configured;
        Effective=$Effective;
        State=$State;
        Evidence=$Evidence;
        Maturity=$Maturity;
        WhyEs=$WhyEs;
        WhyEn=$WhyEn;
        RecommendationEs=$RecommendationEs;
        RecommendationEn=$RecommendationEn;
        LinkedFeature=$LinkedFeature
    }

}

function Get-VSO7SystemResponsivenessSemanticsVSO {

    param([Parameter(Mandatory=$true)]$Value)
    try{

        $signed=[int64]$Value
        if($signed-lt0){
            $n=[uint64]([uint32][int32]$signed)
        }else{
            $n=[uint64]$signed
        }

    }catch{
        return [pscustomobject]@{
            State='Unknown';
            Configured=[string]$Value;
            Effective='Unknown';
            ExplanationEs='No se pudo interpretar el REG_DWORD.';
            ExplanationEn='The REG_DWORD could not be interpreted.'
        }
    }
    if($n-lt10-or$n-gt100){
        return [pscustomobject]@{
            State='Clamped';
            Configured=[string]$n;
            Effective='20';
            ExplanationEs='Windows documenta que valores inferiores a 10 o superiores a 100 se ajustan a 20.';
            ExplanationEn='Windows documents that values below 10 or above 100 are clamped to 20.'
        }
    }
    if($n-eq100){
        return [pscustomobject]@{
            State='Configured';
            Configured='100';
            Effective='MMCSS disabled';
            ExplanationEs='Windows documenta que 100 deshabilita MMCSS.';
            ExplanationEn='Windows documents that 100 disables MMCSS.'
        }
    }
    $eff=[math]::Floor([double]$n/10.0)*10
    if($eff-ne$n){
        return [pscustomobject]@{
            State='RoundedDown';
            Configured=[string]$n;
            Effective=[string][int]$eff;
            ExplanationEs='Windows redondea hacia abajo los valores que no son multiplos de 10.';
            ExplanationEn='Windows rounds values that are not evenly divisible by 10 down to the nearest multiple of 10.'
        }
    }
    return [pscustomobject]@{
        State='Configured';
        Configured=[string]$n;
        Effective=[string][int]$n;
        ExplanationEs='El valor configurado coincide con la semantica documentada de MMCSS.';
        ExplanationEn='The configured value matches the documented MMCSS semantics.'
    }

}

function Get-VSO7DwordTextVSO {

    param($Value)
    try{
        $signed=[int64]$Value;
        if($signed-lt0){
            return [string]([uint32][int32]$signed)
        };
        return [string]$signed
    }catch{
        return [string]$Value
    }

}

function Get-VSO7TuningSanityFindingsVSO {

    $script:VSO7SanityScanIncomplete=$false
    $findings=@()

    # ---- BCD -----------------------------------------------------------------------------
    try{

        $bcdLines=@(Invoke-NativeCommandVSO -FilePath 'bcdedit.exe' -Arguments @('/enum','{current}') -CaptureOutput)
        $bcd=@{}
        foreach($line in $bcdLines){
            $t=[string]$line;
            if($t-match'^\s*([A-Za-z][A-Za-z0-9]*)\s+(.+)$'){
                $bcd[$Matches[1].ToLowerInvariant()]=$Matches[2].Trim()
            }
        }
        foreach($name in @('useplatformclock','useplatformtick')){
            if($bcd.ContainsKey($name)){
                $findings+=New-VSO7TuningFindingVSO -Risk 3 -Area 'BCD / timers' -Item $name -Configured ([string]$bcd[$name]) -Effective 'Unknown' -State 'DebugOverride' -Evidence 'E1' -Maturity 'Rejected' -WhyEs 'Microsoft documenta este ajuste en el contexto de opciones BCD de depuracion. VSO7 no lo trata como optimizacion gaming universal.' -WhyEn 'Microsoft documents this setting in the context of BCD debugging options. VSO7 does not treat it as a universal gaming optimization.' -RecommendationEs 'Restaurar el comportamiento por defecto solo tras confirmar por que se creo el override.' -RecommendationEn 'Restore default behavior only after confirming why the override was created.'
            }
        }
        if($bcd.ContainsKey('disabledynamictick')){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'BCD / timers' -Item 'disabledynamictick' -Configured ([string]$bcd['disabledynamictick']) -Effective 'Unknown' -State 'DebugOverride' -Evidence 'E1' -Maturity 'Rejected' -WhyEs 'Microsoft documenta disabledynamictick como una opcion que solo debe usarse para depuracion. VSO7 no la ofrece como optimizacion de latencia o FPS.' -WhyEn 'Microsoft documents disabledynamictick as an option that should only be used for debugging. VSO7 does not offer it as a latency or FPS optimization.' -RecommendationEs 'Revisar por que existe el override; no conservarlo por una promesa generica de rendimiento.' -RecommendationEn 'Review why the override exists; do not keep it based on a generic performance claim.'
        }
        foreach($name in @('tscsyncpolicy','nx','debug','bootdebug','onecpu','numproc','truncatememory','removememory','usefirmwarepcisettings','x2apicpolicy')){
            if($bcd.ContainsKey($name)){
                $risk=2;
                if($name-in@('nx','debug','bootdebug','truncatememory','removememory','onecpu','numproc')){
                    $risk=4
                };
                $findings+=New-VSO7TuningFindingVSO -Risk $risk -Area 'BCD / boot' -Item $name -Configured ([string]$bcd[$name]) -Effective 'Boot configuration override' -State 'Configured' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'VSO7 detecto una opcion BCD explicita fuera de la configuracion normal que puede afectar arranque, seguridad o recursos disponibles.' -WhyEn 'VSO7 found an explicit BCD option outside normal defaults that can affect boot, security, or available resources.'
            }
        }

    }catch{
        $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'BCD' -Item 'Lectura BCD' -Configured '<no disponible>' -Effective 'Unknown' -State 'Unknown' -Evidence 'E1' -WhyEs ('No se pudo leer BCD: {0}'-f$_.Exception.Message) -WhyEn ('BCD could not be read: {0}'-f$_.Exception.Message)
    }

    # ---- MMCSS / Multimedia SystemProfile ------------------------------------------------
    try{

        $path='HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
        $sr=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name 'SystemResponsiveness'
        if($sr.Exists){

            $sem=Get-VSO7SystemResponsivenessSemanticsVSO -Value $sr.Value
            $configuredNumber=[uint64]0;
            $configuredIsNumber=[uint64]::TryParse([string]$sem.Configured,[ref]$configuredNumber)
            if($sem.State-in@('Clamped','RoundedDown')-or($configuredIsNumber-and$configuredNumber-eq100)){

                $linked='';
                if($sem.State-eq'Clamped' -and $configuredIsNumber -and $configuredNumber-lt10){
                    $linked='NormalizeClampedSystemResponsivenessOverride'
                }
                $risk=if($configuredIsNumber-and$configuredNumber-eq100){
                    4
                }else{
                    2
                }
                $findings+=New-VSO7TuningFindingVSO -Risk $risk -Area 'MMCSS' -Item 'SystemResponsiveness' -Configured $sem.Configured -Effective $sem.Effective -State $sem.State -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs ($sem.ExplanationEs+' Un valor 0 es comun en tweak packs, pero NO implica una reserva efectiva del 0 %.') -WhyEn ($sem.ExplanationEn+' A value of 0 is common in tweak packs, but it does NOT imply an effective 0% reserve.') -RecommendationEs $(if($linked){
                    'Puede normalizarse explicitamente a 20 con la feature segura de VSO7; el comportamiento efectivo documentado ya es 20.'
                }else{
                    'Revisar el motivo del override antes de cambiarlo.'
                }) -RecommendationEn $(if($linked){
                    'It can be explicitly normalized to 20 with the safe VSO7 feature; the documented effective behavior is already 20.'
                }else{
                    'Review why the override exists before changing it.'
                }) -LinkedFeature $linked

            }

        }
        $nti=Get-VSO7NativeRegistrySnapshotVSO -Path $path -Name 'NetworkThrottlingIndex'
        if($nti.Exists){
            $txt=Get-VSO7DwordTextVSO $nti.Value;
            if($txt-eq'4294967295'){
                $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'MMCSS / red' -Item 'NetworkThrottlingIndex' -Configured '0xFFFFFFFF' -Effective 'Unknown' -State 'Configured' -Evidence 'E4' -Maturity 'Diagnostic' -WhyEs 'Existe el override tipico que intenta desactivar throttling multimedia. VSO7 puede leer el valor configurado, pero no afirma que en Windows actual garantice menor latencia.' -WhyEn 'The common override intended to disable multimedia throttling is present. VSO7 can read the configured value but does not claim it guarantees lower latency on current Windows.'
            }
        }

        $games='HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
        $sched=Get-VSO7NativeRegistrySnapshotVSO -Path $games -Name 'Scheduling Category';
        $pri=Get-VSO7NativeRegistrySnapshotVSO -Path $games -Name 'Priority';
        $gpu=Get-VSO7NativeRegistrySnapshotVSO -Path $games -Name 'GPU Priority';
        $sfio=Get-VSO7NativeRegistrySnapshotVSO -Path $games -Name 'SFIO Priority';
        $clock=Get-VSO7NativeRegistrySnapshotVSO -Path $games -Name 'Clock Rate'
        if($sched.Exists-and$pri.Exists-and[string]$sched.Value-ieq'High'-and[int]$pri.Value-ne2){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'MMCSS / Games' -Item 'Priority' -Configured ([string]$pri.Value) -Effective '2 when Scheduling Category=High' -State 'ClampedByCategory' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'Microsoft documenta que para tareas High el valor Priority siempre se trata como 2; subirlo en Registro no produce la prioridad efectiva que sugiere el numero.' -WhyEn 'Microsoft documents that for High scheduling-category tasks Priority is always treated as 2; raising the registry number does not produce the implied effective priority.'
        }
        if($gpu.Exists){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'MMCSS / Games' -Item 'GPU Priority' -Configured ([string]$gpu.Value) -Effective 'Not used' -State 'Ignored' -Evidence 'E1' -Maturity 'Deprecated' -WhyEs 'La documentacion actual de MMCSS indica que GPU Priority no se usa.' -WhyEn 'Current MMCSS documentation states that GPU Priority is not used.'
        }
        if($sfio.Exists){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'MMCSS / Games' -Item 'SFIO Priority' -Configured ([string]$sfio.Value) -Effective 'Not used' -State 'Ignored' -Evidence 'E1' -Maturity 'Deprecated' -WhyEs 'La documentacion actual de MMCSS indica que SFIO Priority no se usa.' -WhyEn 'Current MMCSS documentation states that SFIO Priority is not used.'
        }
        if($clock.Exists){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'MMCSS / Games' -Item 'Clock Rate' -Configured ([string]$clock.Value) -Effective 'Legacy hint; old guarantee removed since Windows 7' -State 'DeprecatedBehavior' -Evidence 'E1' -Maturity 'Deprecated' -WhyEs 'La garantia asociada a Clock Rate se retiro desde Windows 7/Server 2008 R2 para reducir consumo; no debe venderse como timer tweak moderno.' -WhyEn 'The guarantee associated with Clock Rate was removed starting with Windows 7/Server 2008 R2 to reduce power use; it should not be presented as a modern timer tweak.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    # ---- Memory ---------------------------------------------------------------------------
    foreach($check in @(
        [pscustomobject]@{
        Path='HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management';Name='LargeSystemCache';Match='1';Risk=2;WhyEs='LargeSystemCache=1 no es una optimizacion gaming universal en Windows cliente.';WhyEn='LargeSystemCache=1 is not a universal gaming optimization on Windows client.'
    },
        [pscustomobject]@{
        Path='HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management';Name='DisablePagingExecutive';Match='1';Risk=2;WhyEs='Mantener mas codigo ejecutivo residente puede aumentar presion de memoria y no sustituye medicion.';WhyEn='Keeping more executive code resident can increase memory pressure and does not replace measurement.'
    }
    )){
        try{
            $x=Get-VSO7NativeRegistrySnapshotVSO -Path $check.Path -Name $check.Name;
            if($x.Exists-and[string]$x.Value-eq$check.Match){
                $findings+=New-VSO7TuningFindingVSO -Risk $check.Risk -Area 'Memoria' -Item $check.Name -Configured ([string]$x.Value) -Effective 'Unknown workload-dependent impact' -State 'Configured' -Evidence 'E4' -Maturity 'Diagnostic' -WhyEs $check.WhyEs -WhyEn $check.WhyEn
            }
        }catch{
            $script:VSO7SanityScanIncomplete=$true
        }
    }
    try{

        $cs=CimCmdlets\Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
        $pf=@(CimCmdlets\Get-CimInstance Win32_PageFileSetting -ErrorAction SilentlyContinue)
        if($null-ne$cs-and-not[bool]$cs.AutomaticManagedPagefile){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Memoria / pagefile' -Item 'Pagefile personalizado' -Configured ('AutomaticManagedPagefile=False; entries={0}'-f$pf.Count) -Effective 'Custom pagefile policy' -State 'Configured' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'El pagefile esta gestionado manualmente. VSO7 no asume que desactivarlo o fijar numeros por cantidad de RAM mejore FPS.' -WhyEn 'The pagefile is manually managed. VSO7 does not assume that disabling it or using RAM-size magic numbers improves FPS.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{
        $mm=Get-MMAgent -ErrorAction Stop;
        if($mm.PSObject.Properties.Name-contains'MemoryCompression' -and -not[bool]$mm.MemoryCompression){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Memoria' -Item 'Memory Compression' -Configured 'Disabled' -Effective 'Disabled' -State 'Configured' -Evidence 'E3' -Maturity 'Diagnostic' -WhyEs 'Desactivarla solo por tener mucha RAM no es una optimizacion universal; puede aumentar paginacion bajo presion.' -WhyEn 'Disabling it solely because the system has a lot of RAM is not a universal optimization; it can increase paging under pressure.'
        }
    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    # ---- TCP / network --------------------------------------------------------------------
    try{

        $ifaceRoot='HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces';
        $nagle=0;
        $ack=0;
        $ticks=0
        foreach($key in @(Get-ChildItem -LiteralPath $ifaceRoot -ErrorAction SilentlyContinue)){
            try{
                $names=@($key.GetValueNames());
                if($names-contains'TCPNoDelay'){
                    $nagle++
                };
                if($names-contains'TcpAckFrequency'){
                    $ack++
                };
                if($names-contains'TcpDelAckTicks'){
                    $ticks++
                }
            }catch{
                $script:VSO7SanityScanIncomplete=$true
            }
        }
        if(($nagle+$ack+$ticks)-gt0){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Red / TCP' -Item 'Nagle / delayed ACK overrides' -Configured ('TCPNoDelay={0}; TcpAckFrequency={1}; TcpDelAckTicks={2}'-f$nagle,$ack,$ticks) -Effective 'Unknown per workload/protocol' -State 'Configured' -Evidence 'E4' -Maturity 'Diagnostic' -WhyEs 'Son overrides por interfaz sensibles a protocolo y workload. Una key presente no demuestra menor ping.' -WhyEn 'These are per-interface overrides whose effects depend on protocol and workload. A present key does not prove lower ping.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $tcp=Get-NetTCPSetting -SettingName Internet -ErrorAction Stop
        $local=[string]$tcp.AutoTuningLevelLocal;
        $effective=[string]$tcp.AutoTuningLevelEffective
        if($local-in@('Disabled','HighlyRestricted','Restricted')){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Red / TCP' -Item 'Receive Window Auto-Tuning' -Configured $local -Effective $effective -State 'RestrictiveOverride' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'El perfil local limita el crecimiento de la ventana de recepcion frente a Normal. VSO7 distingue el valor configurado del nivel efectivo reportado por Windows.' -WhyEn 'The local profile restricts receive-window growth compared with Normal. VSO7 distinguishes the configured value from the effective level reported by Windows.' -RecommendationEs 'La remediacion normaliza solo Disabled/HighlyRestricted/Restricted; no toca Experimental.' -RecommendationEn 'The remediation normalizes only Disabled/HighlyRestricted/Restricted; it does not touch Experimental.' -LinkedFeature 'RestoreTcpAutoTuningNormal'
        }
        elseif($local-ieq'Experimental'){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Red / TCP' -Item 'Receive Window Auto-Tuning' -Configured $local -Effective $effective -State 'ExperimentalOverride' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'Experimental permite un crecimiento mas agresivo/no convencional y Microsoft lo describe para escenarios de prueba; no es un perfil restrictivo.' -WhyEn 'Experimental allows more aggressive/non-standard growth and Microsoft describes it for testing scenarios; it is not a restrictive profile.' -RecommendationEs 'No se modifica automaticamente. Medir antes de decidir si volver a Normal.' -RecommendationEn 'It is not changed automatically. Measure before deciding whether to return to Normal.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $off=Get-NetOffloadGlobalSetting -ErrorAction Stop
        if([string]$off.ReceiveSideScaling-eq'Disabled'){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Red / offload' -Item 'ReceiveSideScaling global' -Configured 'Disabled' -Effective 'Configured disabled; runtime capability still depends on NIC/driver' -State 'ConfiguredVsEffective' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'RSS distribuye recepcion entre procesadores. El switch global y el estado por NIC son capas distintas; VSO7 no confunde una con otra.' -WhyEn 'RSS distributes receive processing across processors. The global switch and per-NIC state are separate layers; VSO7 does not conflate them.' -LinkedFeature 'RestoreGlobalReceiveSideScaling'
        }
        if([string]$off.TaskOffload-eq'Disabled'){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Red / offload' -Item 'TaskOffload' -Configured 'Disabled' -Effective 'Unknown until adapter/system restart semantics are satisfied' -State 'ConfiguredVsEffectiveUnknown' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'Microsoft documenta que los cambios de TaskOffload surten efecto tras reiniciar el adaptador o el equipo. El read-back solo demuestra configuracion.' -WhyEn 'Microsoft documents that TaskOffload changes take effect after a network-adapter or computer restart. Read-back proves configuration only.' -RecommendationEs 'VSO7 puede restaurar Configured=Enabled y lo marca PendingRestart; no afirma que sea efectivo inmediatamente.' -RecommendationEn 'VSO7 can restore Configured=Enabled and marks it PendingRestart; it does not claim immediate effectiveness.' -LinkedFeature 'RestoreGlobalTaskOffload'
        }
        if([string]$off.ReceiveSegmentCoalescing-eq'Disabled'){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Red / offload' -Item 'RSC global' -Configured 'Disabled' -Effective 'Configured disabled' -State 'Configured' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'RSC desactivado puede ser intencionado para A/B de latencia/CPU; no es un error universal.' -WhyEn 'Disabled RSC can be intentional for latency/CPU A/B testing; it is not a universal error.' -LinkedFeature 'RestoreGlobalReceiveSegmentCoalescing'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        foreach($nic in @(Get-VSO7PhysicalRssTargetsVSO|Where-Object{
            -not[bool]$_.Enabled
        })){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Red / NIC' -Item ('RSS · '+$nic.InterfaceDescription) -Configured 'Disabled' -Effective 'Disabled on this physical NIC' -State 'Applicable' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'Windows expone esta NIC fisica activa como RSS-capable pero RSS esta desactivado. Activarlo puede mejorar escalabilidad de recepcion; no se promete menor ping.' -WhyEn 'Windows exposes this active physical NIC as RSS-capable but RSS is disabled. Enabling it can improve receive scalability; lower ping is not promised.' -RecommendationEs 'Disponible como feature Advanced con rollback por adaptador.' -RecommendationEn 'Available as an Advanced feature with per-adapter rollback.' -LinkedFeature 'EnablePhysicalNicRss'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    # ---- Power / USB ----------------------------------------------------------------------
    try{

        $usb=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_USB' -SettingAlias 'USBSELECTIVE'
        if($usb.AC-eq0-or$usb.DC-eq0){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Power / USB' -Item 'USB selective suspend' -Configured ('AC={0}; DC={1}'-f$usb.AC,$usb.DC) -Effective 'Power-plan policy; device/driver support still matters' -State 'Configured' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'Microsoft indica que selective suspend esta habilitado por defecto y recomienda encarecidamente no deshabilitarlo globalmente. Un problema real de un dispositivo puede justificar una excepcion diagnostica.' -WhyEn 'Microsoft states selective suspend is enabled by default and strongly recommends not disabling it globally. A real device issue can justify a diagnostic exception.' -RecommendationEs 'Restaurar a Enabled salvo que estes diagnosticando un dispositivo/controlador concreto.' -RecommendationEn 'Restore to Enabled unless you are troubleshooting a specific device/driver.' -LinkedFeature 'EnableUsbSelectiveSuspend'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $min=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_PROCESSOR' -SettingAlias 'PROCTHROTTLEMIN';
        $max=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_PROCESSOR' -SettingAlias 'PROCTHROTTLEMAX'
        if($min.AC-ge100-or$min.DC-ge100){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Power / CPU' -Item 'Minimum processor state' -Configured ('AC={0}%; DC={1}%'-f$min.AC,$min.DC) -Effective 'Plan-specific minimum processor performance state' -State 'Configured' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'Un minimo del 100 % no es una mejora gaming universal: aumenta consumo/temperatura y puede perjudicar boost sostenido en equipos limitados termicamente.' -WhyEn 'A 100% minimum is not a universal gaming improvement: it raises power/thermals and can hurt sustained boost on thermally constrained systems.'
        }
        if($max.AC-lt100-or$max.DC-lt100){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Power / CPU' -Item 'Maximum processor state' -Configured ('AC={0}%; DC={1}%'-f$max.AC,$max.DC) -Effective 'Plan-specific maximum processor performance state' -State 'Configured' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'El maximo esta limitado por el plan. Puede ser intencionado para temperatura/bateria. La remediacion VSO7 solo aplica a AC en desktop y preserva DC.' -WhyEn 'The maximum is limited by the power plan. This can be intentional for thermals/battery. The VSO7 remediation applies only to AC on desktops and preserves DC.' -LinkedFeature 'RestoreMaxProcessorStateOnAcDesktop'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{
        $pt=Get-VSO7NativeRegistrySnapshotVSO -Path 'HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' -Name 'PowerThrottlingOff';
        if($pt.Exists-and[int]$pt.Value-eq1){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Power' -Item 'PowerThrottlingOff' -Configured '1' -Effective 'Power Throttling disabled globally by policy mapping' -State 'Configured' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'Es una policy real de Windows para desactivar Power Throttling, pero eso no demuestra un beneficio gaming y puede aumentar consumo.' -WhyEn 'This is a real Windows policy for turning off Power Throttling, but that does not demonstrate a gaming benefit and can increase power use.' -LinkedFeature 'RestorePowerThrottlingToUserControl'
        }
    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    # ---- Storage / gaming policy -----------------------------------------------------------
    try{

        $trim=Get-VSO7FsutilTrimStateVSO
        if([bool]$trim.NtfsDisabled){

            $refs=Get-VSO7ReFsVolumeCountVSO;
            $linked=''
            try{
                $ctx=Get-VSO7ApplicabilityContextVSO;
                if($refs-eq0-and@($ctx.StorageMediaTypes)-contains'SSD'){
                    $linked='EnableNtfsTrimWhenDisabledNoReFs'
                }
            }catch{
                $script:VSO7SanityScanIncomplete=$true
            }
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'Storage / TRIM' -Item 'NTFS DisableDeleteNotify' -Configured 'Disabled for NTFS' -Effective 'NTFS delete notifications/TRIM disabled' -State 'Configured' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'Windows expone este estado mediante fsutil. En almacenamiento flash compatible, deshabilitar notificaciones de borrado impide el flujo normal de TRIM.' -WhyEn 'Windows exposes this state through fsutil. On compatible flash storage, disabling delete notifications prevents the normal TRIM path.' -RecommendationEs $(if($linked){
                'Remediacion disponible solo con SSD detectado y sin volumen ReFS, para mantener rollback exacto.'
            }else{
                'Diagnosticar media/filesystem antes de cambiarlo.'
            }) -RecommendationEn $(if($linked){
                'Remediation is available only when an SSD is detected and no ReFS volume exists, preserving exact rollback semantics.'
            }else{
                'Diagnose media/filesystem before changing it.'
            }) -LinkedFeature $linked

        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $task=Get-ScheduledTask -TaskPath '\Microsoft\Windows\Defrag\' -TaskName 'ScheduledDefrag' -ErrorAction Stop
        if([string]$task.State-ieq'Disabled'){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Storage / maintenance' -Item 'Scheduled drive optimization' -Configured 'Disabled' -Effective 'Scheduled optimization disabled' -State 'Configured' -Evidence 'E1' -Maturity 'Stable' -WhyEs 'La tarea nativa de optimizacion esta deshabilitada. Windows decide la operacion adecuada segun el volumen/medio en lugar de aplicar una receta HDD/SSD fija.' -WhyEn 'The native optimization task is disabled. Windows chooses the appropriate operation for the volume/media rather than applying a fixed HDD/SSD recipe.' -LinkedFeature 'EnableScheduledDriveOptimization'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $gd=Get-VSO7NativeRegistrySnapshotVSO -Path 'HKEY_LOCAL_MACHINE\SOFTWARE\Policies\Microsoft\Windows\GameDVR' -Name 'AllowGameDVR'
        if($gd.Exists-and[int]$gd.Value-eq0){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Gaming / capture policy' -Item 'AllowGameDVR policy' -Configured '0 (machine policy)' -Effective 'User capture choices constrained by policy' -State 'PolicyOverride' -Evidence 'E1' -Maturity 'Conditional' -WhyEs 'Existe una policy de maquina que fuerza Game DVR off. VSO7 puede devolver el control al usuario sin habilitar automaticamente capturas.' -WhyEn 'A machine policy forces Game DVR off. VSO7 can return control to the user without automatically enabling capture.' -LinkedFeature 'RestoreGameRecordingPolicyToUserControl'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    # ---- Graphics / input -----------------------------------------------------------------
    try{
        $h=Get-VSO7NativeRegistrySnapshotVSO -Path 'HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' -Name 'HwSchMode';
        if($h.Exists){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'GPU / Windows' -Item 'HAGS (HwSchMode)' -Configured ([string]$h.Value) -Effective 'Unknown until OS/driver runtime support is considered' -State 'ConfiguredVsEffectiveUnknown' -Evidence 'E3' -Maturity 'Diagnostic' -WhyEs 'La clave expresa una preferencia/configuracion, pero por si sola no demuestra que HAGS este activo ni que mejore este workload.' -WhyEn 'The key expresses a preference/configuration, but by itself does not prove HAGS is active or beneficial for this workload.'
        }
    }
    catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{
        $mpo=Get-VSO7NativeRegistrySnapshotVSO -Path 'HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\Dwm' -Name 'OverlayTestMode';
        if($mpo.Exists){
            $findings+=New-VSO7TuningFindingVSO -Risk 2 -Area 'GPU / DWM' -Item 'MPO OverlayTestMode' -Configured ([string]$mpo.Value) -Effective 'DWM overlay behavior overridden' -State 'Configured' -Evidence 'E4' -Maturity 'Diagnostic' -WhyEs 'Existe un override de MPO/DWM. VSO7 no asume que desactivar MPO sea mejor en todos los drivers y present models.' -WhyEn 'An MPO/DWM override is present. VSO7 does not assume disabling MPO is better for every driver and presentation model.'
        }
    }
    catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $layers='HKCU:\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers';
        $count=0
        if(Test-Path -LiteralPath $layers){
            $k=Get-Item -LiteralPath $layers -ErrorAction Stop;
            foreach($name in @($k.GetValueNames())){
                $v=[string]$k.GetValue($name);
                if($v-match'(?i)DISABLEDXMAXIMIZEDWINDOWEDMODE'){
                    $count++
                }
            }
        }
        if($count-gt0){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Gaming / fullscreen' -Item 'Fullscreen Optimization compatibility flags' -Configured ('{0} app(s) with DISABLEDXMAXIMIZEDWINDOWEDMODE'-f$count) -Effective 'Per-app compatibility override' -State 'Configured' -Evidence 'E3' -Maturity 'Diagnostic' -WhyEs 'Hay overrides por aplicacion. Windows 11 moderno tiene distintos presentation models; no se recomienda desactivar FSO globalmente basandose en guias antiguas.' -WhyEn 'Per-app overrides are present. Modern Windows 11 uses different presentation models; globally disabling FSO based on old guides is not recommended.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $m=Get-ItemProperty 'HKCU:\Control Panel\Mouse' -ErrorAction Stop;
        $speed=[string]$m.MouseSpeed;
        $t1=[string]$m.MouseThreshold1;
        $t2=[string]$m.MouseThreshold2
        if($speed-ne'0'-or$t1-ne'0'-or$t2-ne'0'){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Input / mouse' -Item 'Windows pointer acceleration' -Configured ('MouseSpeed={0}; Threshold1={1}; Threshold2={2}'-f$speed,$t1,$t2) -Effective 'Pointer acceleration preference for legacy pointer path' -State 'Preference' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'Es una preferencia de entrada, no un fallo. Juegos con raw input pueden no usar esta ruta.' -WhyEn 'This is an input preference, not an error. Games using raw input may bypass this path.' -RecommendationEs 'Cambiar solo por preferencia/consistencia de aim, no como promesa de FPS.' -RecommendationEn 'Change only for preference/aim consistency, not as an FPS promise.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    # ---- Security posture (read-only) -----------------------------------------------------
    try{

        $dg=CimCmdlets\Get-CimInstance -Namespace 'root\Microsoft\Windows\DeviceGuard' -ClassName 'Win32_DeviceGuard' -ErrorAction Stop
        $vbs=[int]$dg.VirtualizationBasedSecurityStatus;
        $run=@($dg.SecurityServicesRunning|ForEach-Object{
            [int]$_
        });
        $cfg=@($dg.SecurityServicesConfigured|ForEach-Object{
            [int]$_
        })
        $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Security / VBS' -Item 'Virtualization-Based Security' -Configured $(if($cfg.Count){
            ($cfg-join',')
        }else{
            'No services reported configured'
        }) -Effective $(switch($vbs){
            0{
                'VBS not enabled'
            }1{
                'VBS enabled, not running'
            }2{
                'VBS enabled and running'
            }default{
                'Unknown'
            }
        }) -State 'ConfiguredVsRuntime' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'Win32_DeviceGuard permite separar configuracion de estado runtime; VSO7 no recomienda desactivar VBS por FPS.' -WhyEn 'Win32_DeviceGuard separates configured state from runtime state; VSO7 does not recommend disabling VBS for FPS.'
        $hvciConfigured=($cfg-contains2);
        $hvciRunning=($run-contains2)
        if($hvciConfigured-or$hvciRunning){
            $findings+=New-VSO7TuningFindingVSO -Risk 1 -Area 'Security / HVCI' -Item 'Memory Integrity' -Configured ([string]$hvciConfigured) -Effective ([string]$hvciRunning) -State 'ConfiguredVsRuntime' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'SecurityServicesRunning=2 indica integridad de memoria realmente ejecutandose; el Registro por si solo no basta.' -WhyEn 'SecurityServicesRunning=2 indicates memory integrity is actually running; registry configuration alone is not enough.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }
    try{

        $mp=Get-MpPreference -ErrorAction Stop;
        $exPath=@($mp.ExclusionPath|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}).Count;
        $exProc=@($mp.ExclusionProcess|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}).Count;
        $exExt=@($mp.ExclusionExtension|Where-Object{-not[string]::IsNullOrWhiteSpace([string]$_)}).Count
        if(($exPath+$exProc+$exExt)-gt0){
            $findings+=New-VSO7TuningFindingVSO -Risk 3 -Area 'Security / Defender' -Item 'Defender exclusions' -Configured ('paths={0}; processes={1}; extensions={2}'-f$exPath,$exProc,$exExt) -Effective 'Excluded from applicable Defender scanning scopes' -State 'Configured' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'VSO7 solo muestra contadores y no revela las rutas/procesos excluidos. Las exclusiones reducen cobertura y no son un tweak gaming generico.' -WhyEn 'VSO7 shows counts only and does not reveal excluded paths/processes. Exclusions reduce coverage and are not a generic gaming tweak.'
        }
        $ms=Get-MpComputerStatus -ErrorAction SilentlyContinue;
        if($null-ne$ms-and($ms.PSObject.Properties.Name-contains'RealTimeProtectionEnabled')-and-not[bool]$ms.RealTimeProtectionEnabled){
            $findings+=New-VSO7TuningFindingVSO -Risk 4 -Area 'Security / Defender' -Item 'Real-time protection' -Configured 'Unknown from runtime query' -Effective 'Disabled' -State 'Runtime' -Evidence 'E1' -Maturity 'Diagnostic' -WhyEs 'La proteccion en tiempo real aparece desactivada. VSO7 no la desactiva como optimizacion.' -WhyEn 'Real-time protection appears disabled. VSO7 does not disable it as an optimization.'
        }

    }catch{
        $script:VSO7SanityScanIncomplete=$true
    }

    return @($findings)

}

function Show-VSO7AdvancedTuningDiagnostics {

    $isEn=($script:Language-eq'en')
    Write-Title
    Write-CenteredLineVSO -Text $(if($isEn){
        'ADVANCED TUNING SANITY SCAN - READ ONLY'
    }else{
        'DIAGNOSTICO AVANZADO DE TWEAKS - SOLO LECTURA'
    }) -Color $script:ThemeCopper
    Write-VSOHost ''
    Write-CenteredLineVSO -Text $(if($isEn){
        'Separates configured values from documented/effective state where Windows exposes enough evidence. It changes NOTHING.'
    }else{
        'Separa valores configurados del estado documentado/efectivo cuando Windows expone evidencia suficiente. No modifica NADA.'
    }) -Color $script:ThemeText
    Write-VSOHost ''
    $findings=@(Get-VSO7TuningSanityFindingsVSO)
    if($findings.Count-eq0){

        if([bool]$script:VSO7SanityScanIncomplete){
            Write-CenteredLineVSO -Text $(if($isEn){
                'Sanity scan INCOMPLETE: one or more providers could not be read. No clean verdict is emitted.'
            }else{
                'Sanity scan INCOMPLETO: uno o mas providers no pudieron leerse. No se emite un veredicto limpio.'
            }) -Color $script:ThemeWarning
        }
        else{
            Write-CenteredLineVSO -Text $(if($isEn){
                'No reviewed aggressive/legacy overrides were detected.'
            }else{
                'No se detectaron overrides agresivos/legacy entre los patrones revisados.'
            }) -Color $script:ThemeSuccess
        }

    }
    else{

        $i=1
        foreach($f in $findings){

            $risk=[int]$f.Risk;
            $label=Get-RiskNameVSO -Risk $risk
            Write-VSOHost ('[{0}] [{1}] {2} / {3}'-f$i,$label,$f.Area,$f.Item) -ForegroundColor (Get-RiskColorVSO -Risk $risk)
            Write-VSOHost ($(if($isEn){
                '    Configured: '
            }else{
                '    Configurado: '
            })+[string]$f.Configured) -ForegroundColor Gray
            Write-VSOHost ($(if($isEn){
                '    Effective:  '
            }else{
                '    Efectivo:    '
            })+[string]$f.Effective) -ForegroundColor Gray
            Write-VSOHost ($(if($isEn){
                '    State:      '
            }else{
                '    Estado:      '
            })+[string]$f.State+' · '+[string]$f.Evidence+' · '+[string]$f.Maturity) -ForegroundColor DarkGray
            Write-VSOHost ('    '+$(if($isEn){
                [string]$f.WhyEn
            }else{
                [string]$f.WhyEs
            })) -ForegroundColor DarkGray
            Write-VSOHost ($(if($isEn){
                '    Recommendation: '
            }else{
                '    Recomendacion: '
            })+$(if($isEn){
                [string]$f.RecommendationEn
            }else{
                [string]$f.RecommendationEs
            })) -ForegroundColor Cyan
            if(-not[string]::IsNullOrWhiteSpace([string]$f.LinkedFeature)){
                Write-VSOHost ($(if($isEn){
                    '    VSO7 feature: '
                }else{
                    '    Feature VSO7: '
                })+[string]$f.LinkedFeature) -ForegroundColor Green
            }
            Write-VSOHost '';
            $i++

        }

    }

    Write-VSOHost '---';
    Write-VSOHost $(if($isEn){
        'Network stack snapshot:'
    }else{
        'Estado de la pila de red:'
    }) -ForegroundColor Cyan
    try{
        $internet=@(Get-NetTCPSetting -SettingName Internet -ErrorAction Stop|Select-Object SettingName,CongestionProvider,AutoTuningLevelLocal,AutoTuningLevelEffective,EcnCapability,Timestamps,ScalingHeuristics);
        Write-CenteredTableVSO -Rows $internet -Properties @('SettingName','CongestionProvider','AutoTuningLevelLocal','AutoTuningLevelEffective','EcnCapability','Timestamps','ScalingHeuristics')
    }catch{
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es '<no disponible: {0}>' -En '<unavailable: {0}>')-f$_.Exception.Message) -ForegroundColor DarkGray
    }
    Write-VSOHost '';
    Write-VSOHost $(if($isEn){
        'Physical adapter RSS/RSC snapshot:'
    }else{
        'Estado RSS/RSC de adaptadores fisicos:'
    }) -ForegroundColor Cyan
    try{
        $rows=@();
        foreach($adapter in @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue)){
            $rss='N/D';
            $rsc='N/D';
            try{
                $r=Get-NetAdapterRss -Name $adapter.Name -ErrorAction Stop;
                $rss=[string]$r.Enabled
            }catch{};
            try{
                $r=Get-NetAdapterRsc -Name $adapter.Name -ErrorAction Stop;
                $rsc=('IPv4={0}, IPv6={1}'-f$r.IPv4Enabled,$r.IPv6Enabled)
            }catch{};
            $rows+=[pscustomobject]@{
                Adapter=[string]$adapter.InterfaceDescription;
                Status=[string]$adapter.Status;
                LinkSpeed=[string]$adapter.LinkSpeed;
                RSS=$rss;
                RSC=$rsc
            }
        };
        if($rows.Count){
            Write-CenteredTableVSO -Rows $rows -Properties @('Adapter','Status','LinkSpeed','RSS','RSC')
        }
    }catch{}
    Write-VSOHost '';
    Write-VSOHost $(if($isEn){
        'Interrupt / latency policy snapshot:'
    }else{
        'Estado de interrupciones / latencia:'
    }) -ForegroundColor Cyan
    try{
        $ints=@(Get-VSO7InterruptDeviceInventoryVSO);
        $explicit=@($ints|Where-Object{
            $_.MsiOverrideState-notlike'Inherited*'-or$_.AffinityOverrideState-eq'ExplicitOverride'
        });
        Write-CenteredTableVSO -Rows $explicit -Properties @('Name','Class','MsiOverrideState','MessageNumberLimit','AffinityOverrideState','AffinityDevicePolicy');
        if($explicit.Count-eq0){
            Write-VSOHost $(if($isEn){
                'No explicit MSI/affinity overrides detected in reviewed device classes.'
            }else{
                'No se detectaron overrides MSI/affinity explicitos en las clases revisadas.'
            }) -ForegroundColor Green
        };
        $dpc=Get-VSO7DpcIsrOverviewVSO -Samples 3 -IntervalMs 150;
        Write-VSOHost (('DPC avg/max={0}/{1}% | ISR avg/max={2}/{3}% | Driver attribution={4}'-f$dpc.DpcAvgPct,$dpc.DpcMaxPct,$dpc.IsrAvgPct,$dpc.IsrMaxPct,$dpc.DriverAttribution)) -ForegroundColor DarkGray
    }catch{
        Write-VSOHost ($(Get-VSO7ConsoleTextVSO -Es '<no disponible: {0}>' -En '<unavailable: {0}>')-f$_.Exception.Message) -ForegroundColor DarkGray
    }
    Write-VSOHost '';
    Write-VSOHost $(if($isEn){
        'USB power / topology snapshot:'
    }else{
        'Estado USB / energia:'
    }) -ForegroundColor Cyan
    try{
        $up=Get-VSO7UsbPowerDiagnosticVSO;
        $ut=@(Get-VSO7UsbTopologyVSO);
        Write-CenteredTableVSO -Rows @([pscustomobject]@{
            Setting='USB selective suspend';AC=$up.SelectiveSuspendAC;DC=$up.SelectiveSuspendDC;ConnectedMappings=$ut.Count
        }) -Properties @('Setting','AC','DC','ConnectedMappings')
    }catch{}
    Write-VSOHost '';
    Write-VSOHost $(if($isEn){
        'Power snapshot:'
    }else{
        'Estado de energia:'
    }) -ForegroundColor Cyan
    try{
        $min=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_PROCESSOR' -SettingAlias 'PROCTHROTTLEMIN';
        $max=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_PROCESSOR' -SettingAlias 'PROCTHROTTLEMAX';
        $usb=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_USB' -SettingAlias 'USBSELECTIVE';
        $aspm=Get-VSO7NativePowerSettingSnapshotVSO -SubGroupAlias 'SUB_PCIEXPRESS' -SettingAlias 'ASPM';
        Write-CenteredTableVSO -Rows @([pscustomobject]@{
            Setting='CPU minimum';AC=$min.AC;DC=$min.DC
        },[pscustomobject]@{
            Setting='CPU maximum';AC=$max.AC;DC=$max.DC
        },[pscustomobject]@{
            Setting='USB selective suspend';AC=$usb.AC;DC=$usb.DC
        },[pscustomobject]@{
            Setting='PCIe ASPM';AC=$aspm.AC;DC=$aspm.DC
        }) -Properties @('Setting','AC','DC')
    }catch{}
    Write-VSOHost '';
    Write-VSOHost $(if($isEn){
        'Memory manager:'
    }else{
        'Gestor de memoria:'
    }) -ForegroundColor Cyan
    try{
        $mm=Get-MMAgent -ErrorAction Stop;
        Write-CenteredTableVSO -Rows @([pscustomobject]@{
            MemoryCompression=$mm.MemoryCompression;PageCombining=$mm.PageCombining;ApplicationLaunchPrefetching=$mm.ApplicationLaunchPrefetching;ApplicationPreLaunch=$mm.ApplicationPreLaunch
        }) -Properties @('MemoryCompression','PageCombining','ApplicationLaunchPrefetching','ApplicationPreLaunch')
    }catch{}
    Write-VSOHost '';
    Write-CenteredLineVSO -Text $(if($isEn){
        'VSO7 does not auto-fix diagnostic findings. Only explicitly reviewed features with applicability, verification and rollback are actionable.'
    }else{
        'VSO7 no corrige automaticamente los hallazgos diagnosticos. Solo son aplicables las features revisadas con aplicabilidad, verificacion y rollback.'
    }) -Color $script:ThemeMuted
    Pause-Vico

}

function Show-VSO7HardwareHealth {

    Write-Title;
    Write-CenteredLineVSO -Text 'HARDWARE / DRIVERS - SOLO LECTURA' -Color $script:ThemeCopper
    try{
        $pd=@(Storage\Get-PhysicalDisk -ErrorAction Stop|Select-Object FriendlyName,MediaType,HealthStatus,@{
            N='SizeGB';E={
                [math]::Round($_.Size/1GB,1)
            }
        });
        Write-CenteredTableVSO -Rows $pd -Properties @('FriendlyName','MediaType','HealthStatus','SizeGB')
    }catch{
        Write-VSOHost 'Get-PhysicalDisk no disponible.' -ForegroundColor DarkGray
    }
    Write-VSOHost '';
    Write-VSOHost 'TRIM (salida de Windows):' -ForegroundColor Cyan;
    try{
        Invoke-NativeCommandVSO -FilePath 'fsutil.exe' -Arguments @('behavior','query','DisableDeleteNotify') -CaptureOutput|ForEach-Object{
            Write-VSOHost $_
        }
    }catch{}
    Write-VSOHost '';
    Write-VSOHost 'Dispositivos con error ConfigManager:' -ForegroundColor Cyan
    try{
        $bad=@(CimCmdlets\Get-CimInstance Win32_PnPEntity -ErrorAction Stop|Where-Object{
            $_.ConfigManagerErrorCode-ne0
        }|Select-Object Name,PNPDeviceID,ConfigManagerErrorCode);
        if($bad.Count){
            Write-CenteredTableVSO -Rows $bad -Properties @('Name','PNPDeviceID','ConfigManagerErrorCode')
        }else{
            Write-VSOHost 'Ninguno detectado.' -ForegroundColor Green
        }
    }catch{
        Write-VSOHost 'No disponible.' -ForegroundColor DarkGray
    }
    Write-VSOHost '';
    Write-VSOHost 'Drivers firmados mas antiguos (20):' -ForegroundColor Cyan
    try{
        $oldDrivers=@(CimCmdlets\Get-CimInstance Win32_PnPSignedDriver -ErrorAction Stop|Where-Object{
            $_.DriverDate
        }|Sort-Object DriverDate|Select-Object -First 20 DeviceName,DriverVersion,DriverDate,Manufacturer);
        Write-CenteredTableVSO -Rows $oldDrivers -Properties @('DeviceName','DriverVersion','DriverDate','Manufacturer')
    }catch{}
    Pause-Vico

}

function Open-VSO7RootFolder {

    try {

        if ([string]::IsNullOrWhiteSpace([string]$script:Root) -or -not(Test-Path -LiteralPath $script:Root -PathType Container)) {
            throw 'La carpeta raiz de VSO7 no existe.'
        }
        $explorer=Join-Path $script:WindowsRoot 'explorer.exe'
        if (-not(Test-Path -LiteralPath $explorer -PathType Leaf)) {
            throw 'No se encontro explorer.exe.'
        }
        $item=Get-Item -LiteralPath $explorer -Force -ErrorAction Stop
        if($item.PSIsContainer -or ($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
            throw 'explorer.exe no es un ejecutable normal.'
        }
        Start-Process -FilePath $explorer -ArgumentList (Quote-VSOArg ([IO.Path]::GetFullPath([string]$script:Root))) -ErrorAction Stop|Out-Null

    } catch {

        Write-VSOHost ''
        Write-VSOHost ((Convert-VSOText -Value $(Get-VSO7ConsoleTextVSO -Es 'No se pudo abrir la carpeta de VSO7:' -En 'Could not open the VSO7 folder:')) + ' ' + $_.Exception.Message) -ForegroundColor Red
        Pause-Vico

    }

}

function Test-VSO7ConfigurationProfileArrayVSO {

    param($Value,[Parameter(Mandatory=$true)][string]$Label,[int]$MaxCount=512)
    if($null-eq$Value){
        return @()
    }
    if($Value-is[string]){
        throw ("{0} debe ser una coleccion JSON, no un string."-f$Label)
    }
    $items=@($Value)
    if($items.Count-gt$MaxCount){
        throw ("{0} excede el limite de {1} elementos."-f$Label,$MaxCount)
    }
    $normalized=@();
    $seen=@{}
    foreach($item in $items){

        if(-not($item-is[string])){
            throw ("{0} contiene un elemento que no es string."-f$Label)
        }
        $v=[string]$item
        if([string]::IsNullOrWhiteSpace($v)-or$v.Length-gt512){
            throw ("{0} contiene un identificador invalido."-f$Label)
        }
        $key=$v.ToLowerInvariant();
        if($seen.ContainsKey($key)){
            throw ("{0} contiene un identificador duplicado: {1}"-f$Label,$v)
        }
        $seen[$key]=$true;
        $normalized+=,$v

    }
    return @($normalized)

}

function ConvertTo-VSO7ValidatedConfigurationProfileVSO {

    param([Parameter(Mandatory=$true)]$Object)
    $required=@('SchemaVersion','Product','CreatedAt','Features','Apps','Preferences')
    if(-not(Test-VSO7ExactJsonProperties -Object $Object -Required $required)){
        throw 'El perfil no coincide exactamente con VSO7ConfigurationProfile Schema 1.'
    }
    if(-not(Test-VSO7JsonInteger -Value $Object.SchemaVersion -Min 1 -Max 1)){
        throw 'Version de esquema de perfil no soportada.'
    }
    if(-not($Object.Product-is[string])-or[string]$Object.Product-cne'VSO7'){
        throw 'Product de perfil invalido.'
    }
    $created=[string]$Object.CreatedAt;
    $dt=[DateTime]::MinValue;
    if([string]::IsNullOrWhiteSpace($created)-or-not[DateTime]::TryParse($created,[ref]$dt)){
        throw 'CreatedAt de perfil invalido.'
    }
    $featureIds=@(Test-VSO7ConfigurationProfileArrayVSO -Value $Object.Features -Label 'Features')
    $appIds=@(Test-VSO7ConfigurationProfileArrayVSO -Value $Object.Apps -Label 'Apps')
    if($null-eq$Object.Preferences-or$Object.Preferences-is[string]){
        throw 'Preferences de perfil invalido.'
    }
    if(-not(Test-VSO7ExactJsonProperties -Object $Object.Preferences -Required @('Language'))){
        throw 'Preferences solo admite Language en Schema 1.'
    }
    $language=[string]$Object.Preferences.Language;
    if(@('es','en')-notcontains$language){
        throw 'Language de perfil debe ser es o en.'
    }

    $catalog=@(Get-VSO7FeatureCatalogVSO);
    $knownFeatures=@{}
    foreach($f in $catalog){
        $knownFeatures[[string]$f.FeatureId]=$f
    }
    foreach($id in $featureIds){

        if($id-notmatch'^[A-Za-z][A-Za-z0-9]+$'){
            throw ("FeatureId de perfil invalido: {0}"-f$id)
        }
        if(-not$knownFeatures.ContainsKey($id)){
            throw ("FeatureId desconocido para esta build: {0}"-f$id)
        }
        if(-not[bool]$knownFeatures[$id].Selectable){
            throw ("FeatureId no seleccionable en esta build: {0}"-f$id)
        }

    }
    if($featureIds.Count-gt0){
        [void](Assert-VSO7FeatureSelectionRelationsVSO -Requested $featureIds -Catalog $catalog)
    }

    $knownApps=@{}
    foreach($app in @(Get-VSO7AppCatalogVSO)){
        foreach($id in @(Get-VSO7AppIdsVSO -App $app)){
            $knownApps[[string]$id]=$true
        }
    }
    foreach($id in $appIds){
        if(-not$knownApps.ContainsKey($id)){
            throw ("AppId desconocido para esta build: {0}"-f$id)
        }
    }

    return [pscustomobject]@{
        SchemaVersion=1;
        Product='VSO7';
        CreatedAt=$created;
        Features=@($featureIds);
        Apps=@($appIds);
        Preferences=[pscustomobject]@{
            Language=$language
        }
    }

}

function Save-VSO7LastAppliedSelectionR76VSO {
    param([string[]]$Features=@(),[string[]]$Apps=@())
    if([string]::IsNullOrWhiteSpace([string]$script:LastAppliedSelectionFile)){return}
    $obj=[pscustomobject]@{SchemaVersion=1;Product='VSO7';CreatedAt=(Get-Date).ToString('o');Features=@($Features|Where-Object{$_}|Sort-Object -Unique);Apps=@($Apps|Where-Object{$_}|Sort-Object -Unique);Preferences=[pscustomobject]@{Language=[string]$script:Language}}
    $validated=ConvertTo-VSO7ValidatedConfigurationProfileVSO -Object $obj
    $parent=Split-Path -Parent ([string]$script:LastAppliedSelectionFile);if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null}
    $tmp=Join-Path $parent ('.last-selection-'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{
        $validated|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop;[void](ConvertTo-VSO7ValidatedConfigurationProfileVSO -Object $check)
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath ([string]$script:LastAppliedSelectionFile))
    }finally{if(Test-Path -LiteralPath $tmp -PathType Leaf){Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}}
    return $validated
}

function Get-VSO7LastAppliedSelectionR76VSO {
    if([string]::IsNullOrWhiteSpace([string]$script:LastAppliedSelectionFile)-or-not(Test-Path -LiteralPath $script:LastAppliedSelectionFile -PathType Leaf)){return $null}
    try{return Read-VSO7ConfigurationProfileVSO -Path ([string]$script:LastAppliedSelectionFile)}catch{try{Write-VSO7Log ('Last applied selection is invalid: '+$_.Exception.Message) 'WARN'}catch{};return $null}
}

function Reset-VSO7GuiLocalizationCachesR76VSO {
    if(-not($script:GuiMode-or$script:GuiRequested)){return}
    $script:GuiPageCache=@{};$script:GuiPageContexts=@{};$script:GuiFeaturePageContexts=@{};$script:GuiApplicationsPageContext=$null;$script:GuiRecoveryPageContext=$null;$script:GuiHomeBuilt=$false;$script:GuiRecommendedPlan=$null
    if($null-ne$script:GuiHomeCards){try{$script:GuiHomeCards.Children.Clear()}catch{}}
    $script:GuiCardButtons=New-Object 'Collections.Generic.List[object]'
    if($null-ne$script:GuiWindow){try{$script:GuiWindow.Title=Get-VSO7GuiStringVSO 'AppTitle'}catch{}}
}

function Set-VSO7LanguageR76VSO {
    param([Parameter(Mandatory=$true)][ValidateSet('en','es')][string]$Language,[switch]$Persist)
    $changed=([string]$script:Language-cne[string]$Language);$script:Language=$Language;$persistError=$null
    try{if($Persist){Save-VSOLanguagePreference}}catch{$persistError=$_}
    if($changed){Reset-VSO7GuiLocalizationCachesR76VSO}
    if($null-ne$persistError){throw $persistError}
    return $changed
}

function Save-VSO7ConfigurationProfileVSO {

    param([Parameter(Mandatory=$true)][string]$Path,[string[]]$Features=@(),[string[]]$Apps=@())
    if([string]::IsNullOrWhiteSpace($Path)){
        throw 'Ruta de perfil vacia.'
    }
    $full=[IO.Path]::GetFullPath($Path);
    if([IO.Path]::GetExtension($full)-ine'.json'){
        $full+='.json'
    }
    $parent=Split-Path -Parent $full;
    if([string]::IsNullOrWhiteSpace($parent)){
        throw 'Directorio de perfil invalido.'
    }
    if(-not(Test-Path -LiteralPath $parent -PathType Container)){
        [IO.Directory]::CreateDirectory($parent)|Out-Null
    }
    $obj=[pscustomobject]@{
        SchemaVersion=1;
        Product='VSO7';
        CreatedAt=(Get-Date).ToString('o');
        Features=@($Features);
        Apps=@($Apps);
        Preferences=[pscustomobject]@{
            Language=[string]$script:Language
        }
    }
    $validated=ConvertTo-VSO7ValidatedConfigurationProfileVSO -Object $obj
    $tmp=Join-Path $parent ('.vso7-profile-'+[guid]::NewGuid().ToString('N')+'.tmp')
    try{
        $validated|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $tmp -Encoding UTF8 -Force -ErrorAction Stop
        $check=Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
        [void](ConvertTo-VSO7ValidatedConfigurationProfileVSO -Object $check)
        [void](Commit-VSO7AtomicFileVSO -SourcePath $tmp -DestinationPath $full)
    }finally{
        if(Test-Path -LiteralPath $tmp -PathType Leaf){Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
    }
    return $full

}

function Read-VSO7ConfigurationProfileVSO {

    param([Parameter(Mandatory=$true)][string]$Path)
    $full=[IO.Path]::GetFullPath($Path)
    if(-not(Test-Path -LiteralPath $full -PathType Leaf)){
        throw 'No existe el perfil indicado.'
    }
    $item=Get-Item -LiteralPath $full -Force -ErrorAction Stop
    if($item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
        throw 'El perfil no puede ser un directorio ni reparse point.'
    }
    if($item.Length-le0-or$item.Length-gt1048576){
        throw 'El perfil excede el tamano permitido (1 MiB).'
    }
    $obj=Get-Content -LiteralPath $full -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
    return (ConvertTo-VSO7ValidatedConfigurationProfileVSO -Object $obj)

}

function Get-VSO7ConfigurationProfilePathVSO {

    param([Parameter(Mandatory=$true)][ValidateSet('Open','Save')][string]$Mode)
    if([bool]$script:GuiMode-or[bool]$script:GuiRequested){

        Add-Type -AssemblyName PresentationFramework -ErrorAction Stop
        if($Mode-eq'Save'){
            $dlg=New-Object Microsoft.Win32.SaveFileDialog;
            $dlg.Title=if($script:Language-eq'es'){'Exportar perfil VSO7'}else{'Export VSO7 profile'};
            $dlg.FileName='VSO7-profile.json'
        }else{
            $dlg=New-Object Microsoft.Win32.OpenFileDialog;
            $dlg.Title=if($script:Language-eq'es'){'Importar perfil VSO7'}else{'Import VSO7 profile'}
        }
        $dlg.Filter='VSO7 JSON (*.json)|*.json';
        $dlg.DefaultExt='.json';
        $dlg.AddExtension=$true
        $accepted=if($null-ne$script:GuiWindow){$dlg.ShowDialog($script:GuiWindow)}else{$dlg.ShowDialog()}
        if($accepted-eq$true){
            return [string]$dlg.FileName
        };
        return $null

    }
    $prompt=if($Mode-eq'Save'){
        'Ruta del perfil JSON a exportar'
    }else{
        'Ruta del perfil JSON a importar'
    }
    $path=Read-CenteredPromptVSO -Text $prompt
    if([string]::IsNullOrWhiteSpace($path)){
        return $null
    };
    return [Environment]::ExpandEnvironmentVariables($path.Trim('"'))

}

function ConvertFrom-VSO7ProfileIdInputVSO {

    param([AllowNull()][string]$Text)
    if([string]::IsNullOrWhiteSpace($Text)){
        return @()
    }
    return @($Text.Split(@(',', ';'),[StringSplitOptions]::RemoveEmptyEntries)|ForEach-Object{
        $_.Trim()
    }|Where-Object{
        -not[string]::IsNullOrWhiteSpace($_)
    })

}

function Show-VSO7ConfigurationProfilePreviewVSO {

    param([Parameter(Mandatory=$true)]$Profile)
    $isEn=($script:Language-eq'en')
    Write-CenteredLineVSO -Text $(if($isEn){
        'VSO7 CONFIGURATION PROFILE'
    }else{
        'PERFIL DE CONFIGURACION VSO7'
    }) -Color $script:ThemeCopper
    Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Esquema: {0} · Ajustes: {1} · Apps: {2} · Idioma: {3}' -En 'Schema: {0} · Features: {1} · Apps: {2} · Language: {3}')-f$Profile.SchemaVersion,@($Profile.Features).Count,@($Profile.Apps).Count,$Profile.Preferences.Language) -Color $script:ThemeText
    foreach($id in @($Profile.Features)){
        $f=Get-VSO7FeatureCatalogVSO|Where-Object{
            [string]$_.FeatureId-ceq$id
        }|Select-Object -First 1;
        if($null-ne$f){
            $name=if($isEn){
                [string]$f.NameEn
            }else{
                [string]$f.NameEs
            };
            $a=Get-VSO7FeatureApplicabilityVSO -Feature $f;
            Write-CenteredLineVSO -Text ("  - {0} [{1}] {2}"-f$id,$(if([bool]$a.Applicable){
                'OK'
            }else{
                'N/A'
            }),$name) -Color $(if([bool]$a.Applicable){
                $script:ThemeText
            }else{
                $script:ThemeWarning
            })
        }
    }
    if(@($Profile.Apps).Count-gt0){
        Write-CenteredLineVSO -Text $(if($isEn){
            'Applications requested for removal:'
        }else{
            'Aplicaciones solicitadas para eliminar:'
        }) -Color $script:ThemeWarning;
        foreach($id in @($Profile.Apps)){
            Write-CenteredLineVSO -Text ('  - '+$id) -Color $script:ThemeText
        }
    }

}

function Show-VSO7ConfigurationProfilesVSO {

    while($true){

        $isEn=($script:Language-eq'en');
        Write-Title;
        Write-CenteredLineVSO -Text $(if($isEn){
            'VSO7 CONFIGURATION PROFILES'
        }else{
            'PERFILES DE CONFIGURACION VSO7'
        }) -Color $script:ThemeCopper;
        Write-VSOHost ''
        Write-CenteredLineVSO -Text $(if($isEn){
            'Profiles are data-only JSON. They cannot contain commands, scriptblocks or executable payloads.'
        }else{
            'Los perfiles son JSON de solo datos. No pueden contener comandos, scriptblocks ni payloads ejecutables.'
        }) -Color $script:ThemeText
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{
            Text='[1] Exportar ultima seleccion nativa aplicada';Color='Green';Description='Exporta FeatureIds de la ultima sesion nativa aplicada y el idioma actual. No exporta estado del equipo.'
        },
            [pscustomobject]@{
            Text='[2] Crear perfil por IDs VSO7';Color='Cyan';Description='Permite introducir FeatureIds/AppIds conocidos. El perfil se valida completamente antes de guardarlo.'
        },
            [pscustomobject]@{
            Text='[3] Importar y previsualizar perfil';Color='Cyan';Description='Valida schema, IDs, duplicados y limites. No aplica nada.'
        },
            [pscustomobject]@{
            Text='[4] Importar y aplicar perfil';Color='Yellow';Description='Valida y previsualiza; revalida aplicabilidad y exige confirmacion/recuperacion antes de mutar.'
        },
            [pscustomobject]@{
            Text='[0] Volver';Color='Gray';SeparatorBefore=$true
        }
        )
        $c=Read-CenteredPromptVSO -Text 'Opcion'
        if($c-eq'0'){
            return
        }
        try{

            if($c-eq'1'){

                $last=Get-VSO7LastAppliedSelectionR76VSO
                if($null-eq$last){
                    throw 'No hay una seleccion aplicada que exportar.'
                }
                $path=Get-VSO7ConfigurationProfilePathVSO -Mode Save;
                if([string]::IsNullOrWhiteSpace($path)){
                    continue
                }
                $saved=Save-VSO7ConfigurationProfileVSO -Path $path -Features @($last.Features) -Apps @($last.Apps);
                Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Perfil guardado: ' -En 'Profile saved: ')+$saved) -Color $script:ThemeSuccess;
                Pause-Vico;
                continue

            }
            if($c-eq'2'){

                Write-CenteredLineVSO -Text 'Introduce IDs VSO7 separados por coma. Deja Apps vacio si no quieres incluir desinstalaciones.' -Color $script:ThemeText
                $features=ConvertFrom-VSO7ProfileIdInputVSO -Text (Read-CenteredPromptVSO -Text 'FeatureIds')
                $apps=ConvertFrom-VSO7ProfileIdInputVSO -Text (Read-CenteredPromptVSO -Text 'AppIds')
                $path=Get-VSO7ConfigurationProfilePathVSO -Mode Save;
                if([string]::IsNullOrWhiteSpace($path)){
                    continue
                }
                $saved=Save-VSO7ConfigurationProfileVSO -Path $path -Features $features -Apps $apps;
                Write-CenteredLineVSO -Text ($(Get-VSO7ConsoleTextVSO -Es 'Perfil guardado: ' -En 'Profile saved: ')+$saved) -Color $script:ThemeSuccess;
                Pause-Vico;
                continue

            }
            if($c-eq'3'-or$c-eq'4'){

                $path=Get-VSO7ConfigurationProfilePathVSO -Mode Open;
                if([string]::IsNullOrWhiteSpace($path)){
                    continue
                }
                $profile=Read-VSO7ConfigurationProfileVSO -Path $path;
                Write-Title;
                Show-VSO7ConfigurationProfilePreviewVSO -Profile $profile
                if($c-eq'3'){
                    Pause-Vico;
                    continue
                }
                $notApplicable=@();
                foreach($id in @($profile.Features)){
                    $f=Get-VSO7FeatureCatalogVSO|Where-Object{
                        [string]$_.FeatureId-ceq$id
                    }|Select-Object -First 1;
                    $a=Get-VSO7FeatureApplicabilityVSO -Feature $f;
                    if(-not[bool]$a.Applicable-and-not[bool]$a.AlreadySatisfied){
                        $notApplicable+=,$id
                    }
                }
                if($notApplicable.Count-gt0){
                    throw ('El perfil contiene features no aplicables: '+[string]::Join(', ',$notApplicable))
                }
                Write-VSOHost '';
                if((Read-CenteredPromptVSO -Text $(Get-VSO7ConsoleTextVSO -Es '¿Aplicar este perfil, incluido su idioma guardado? [S/N]' -En 'Apply this profile, including its saved language? [Y/N]'))-notmatch'^[sSyY]$'){
                    continue
                }
                $profileCatalog=@(Get-VSO7FeatureCatalogVSO)
                if(-not(Confirm-VSO7HighRiskFeatureSelectionVSO -FeatureIds @($profile.Features) -Catalog $profileCatalog)){
                    continue
                }
                if(@($profile.Apps).Count-gt0){
                    if(-not(Confirm-Word -Word 'ELIMINAR APPS' -Message 'El perfil incluye desinstalaciones. Escribe exactamente ELIMINAR APPS para continuar')){
                        continue
                    }
                }
                if(-not(Require-RestorePoint)){
                    Pause-Vico;
                    continue
                }
                $featuresToApply=@();
                foreach($id in @($profile.Features)){
                    $f=Get-VSO7FeatureCatalogVSO|Where-Object{
                        [string]$_.FeatureId-ceq$id
                    }|Select-Object -First 1;
                    $a=Get-VSO7FeatureApplicabilityVSO -Feature $f;
                    if([bool]$a.Applicable){
                        $featuresToApply+=,$id
                    }
                }
                $ok=$true;
                if($featuresToApply.Count-gt0){
                    $ok=[bool](Invoke-VSO7NativeTweaksVSO -Features $featuresToApply)
                }
                if($ok-and@($profile.Apps).Count-gt0){
                    $ok=[bool](Invoke-VSO7NativeTweaksVSO -Apps @($profile.Apps))
                }
                if($ok){
                    $persistWarning=$false
                    try{[void](Save-VSO7LastAppliedSelectionR76VSO -Features @($profile.Features) -Apps @($profile.Apps))}catch{$persistWarning=$true;try{Write-VSO7Log ('Profile applied but last-selection persistence failed: '+$_.Exception.Message) 'WARN'}catch{}}
                    try{[void](Set-VSO7LanguageR76VSO -Language ([string]$profile.Preferences.Language) -Persist)}catch{$persistWarning=$true;try{Write-VSO7Log ('Profile applied but language preference persistence failed: '+$_.Exception.Message) 'WARN'}catch{}}
                    Write-CenteredLineVSO -Text $(if($persistWarning){'Perfil aplicado por el motor VSO7; alguna preferencia no pudo persistirse. Revisa el log.'}else{'Perfil aplicado y verificado por el motor VSO7.'}) -Color $(if($persistWarning){$script:ThemeWarning}else{$script:ThemeSuccess})
                }else{
                    Write-CenteredLineVSO -Text 'El motor reporto un fallo; revisa Recuperacion/logs.' -Color $script:ThemeDanger
                }
                Pause-Vico;
                continue

            }

        }catch{
            Write-VSO7Log ("Perfil de configuracion rechazado/fallo: {0}"-f$_.Exception.Message) 'ERROR';
            Write-CenteredLineVSO -Text $_.Exception.Message -Color $script:ThemeDanger;
            Pause-Vico
        }

    }

}

