# Console workflow: selection, review and execution are separate operations.
# Keep these functions in the core so the existing trusted-memory bootstrap and
# protected Recovery runner continue to authenticate one complete source file.
function Get-VSO7ConsoleTextVSO {
    param([string]$Es,[string]$En)
    # Match Convert-VSOText: Spanish is explicit; English is the default.
    if([string]$script:Language-ieq'es'){return $Es}
    return $En
}

function Get-VSO7ConsoleAutomaticAppRowsVSO {
    # Match the removal engine's all-users + provisioning scope. Read inventory
    # once, not once for each of the 140 catalog entries. Failure aborts preview.
    $installed=@(Appx\Get-AppxPackage -AllUsers -ErrorAction Stop)
    $provisioned=@(Dism\Get-AppxProvisionedPackage -Online -ErrorAction Stop)
    $rows=New-Object 'Collections.Generic.List[object]'
    foreach($app in @(Get-VSO7AppCatalogVSO)){
        if(-not[bool]$app.SelectedByDefault-or[string]$app.Recommendation-ine'safe'){continue}
        # WinGet and special removers stay in the manual flow.
        if([string]$app.RemovalMethod-ine'Appx'){continue}
        $presentIds=@(foreach($id in @(Get-VSO7AppIdsVSO -App $app)){
            $present=@($installed|Where-Object{[string]$_.Name-ilike[string]$id}).Count-gt0
            $staged=@($provisioned|Where-Object{[string]$_.DisplayName-ieq[string]$id}).Count-gt0
            if($present-or$staged){[string]$id}
        })
        if($presentIds.Count){
            [void]$rows.Add([pscustomobject]@{
                Kind='App';Id=(Get-VSO7AppCatalogKeyVSO -App $app)
                Name=[string]$app.FriendlyName;AppIds=$presentIds
                Restart='';IsSelected=$true
            })
        }
    }
    return $rows.ToArray()
}

function Get-VSO7ConsoleAutomaticPlanVSO {
    param([ValidateSet('Tweaks','Apps','Both')][string]$Scope='Tweaks',
          [ValidateSet('Balanced','Performance','Gaming','Responsiveness','PowerEfficiency')][string]$Objective='Balanced')
    $rows=New-Object 'Collections.Generic.List[object]'
    if($Scope-ne'Apps'){
        $recommended=Get-VSO7RecommendedOptimizationPlanVSO -Objective $Objective
        foreach($item in @($recommended.Selected)){
            $feature=$item.Feature
            [void]$rows.Add([pscustomobject]@{
                Kind='Feature';Id=[string]$feature.FeatureId
                Name=(Get-VSO7ConsoleTextVSO -Es ([string]$feature.NameEs) -En ([string]$feature.NameEn))
                AppIds=@();Restart=[string]$feature.RebootRequirement;IsSelected=$true
            })
        }
    }
    if($Scope-ne'Tweaks'){
        foreach($row in @(Get-VSO7ConsoleAutomaticAppRowsVSO)){[void]$rows.Add($row)}
    }
    return [pscustomobject]@{Scope=$Scope;Objective=$Objective;Rows=$rows.ToArray()}
}

function Show-VSO7ConsoleAutomaticPlanVSO {
    param([Parameter(Mandatory=$true)]$Plan)
    Write-Title
    Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'SELECCION AUTOMATICA' 'AUTOMATIC SELECTION') -Color $script:ThemeCopper
    if($Plan.Scope-ne'Apps'){
        Write-CenteredLineVSO -Text ((Get-VSO7ConsoleTextVSO 'Objetivo de tweaks: ' 'Tweak objective: ')+$Plan.Objective) -Color $script:ThemeText
    }
    if($Plan.Scope-ne'Tweaks'){
        Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'Apps: seleccion safe/default de Appx detectadas; no usa el objetivo de optimizacion.' 'Apps: safe/default selection of detected Appx packages; does not use the optimization objective.') -Color $script:ThemeMuted
    }
    Write-VSOHost ''
    $displayRows=New-Object 'Collections.Generic.List[object]'
    $index=0
    foreach($row in @($Plan.Rows)){
        $index++
        $mark=if($row.IsSelected){'X'}else{' '}
        $kind=if($row.Kind-eq'App'){'App'}else{'Tweak'}
        $detail=if($row.Kind-eq'Feature'){
            ('FeatureId: '+$row.Id+$(if($row.Restart-notin@('','None')){(Get-VSO7ConsoleTextVSO ' · Reinicio: ' ' · Restart: ')+$row.Restart}else{Get-VSO7ConsoleTextVSO ' · Sin reinicio' ' · No restart'}))
        }else{
            (Get-VSO7ConsoleTextVSO -Es 'Detectada · se eliminara para todos los usuarios y del aprovisionamiento' -En 'Detected · will be removed for all users and from provisioning')
        }
        [void]$displayRows.Add([pscustomobject]@{
            Text=('[{0}] [{1}] {2}: {3}'-f$index,$mark,$kind,$row.Name)
            Description=$detail
            Color=$(if($row.IsSelected){$script:ThemeSuccess}else{$script:ThemeMuted})
        })
    }
    if($displayRows.Count){Write-VSO7TwoColumnOptionsVSO -Items $displayRows.ToArray()}
    else{Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'No hay elementos aplicables pendientes.' 'No applicable pending items.') -Color $script:ThemeMuted}
    $features=@($Plan.Rows|Where-Object{$_.IsSelected-and$_.Kind-eq'Feature'})
    $apps=@($Plan.Rows|Where-Object{$_.IsSelected-and$_.Kind-eq'App'})
    Write-VSOHost ''
    Write-CenteredLineVSO -Text ('Tweaks: {0} · Apps: {1}'-f$features.Count,$apps.Count) -Color $script:ThemeCopper
    if($Plan.Scope-ne'Tweaks'){
        Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'Seleccion safe detectada en este PC. WinGet y opciones especiales permanecen en el modo manual.' 'Safe selection detected on this PC. WinGet and special removers remain in manual mode.') -Color $script:ThemeMuted
    }
    if($apps.Count){
        Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'Recovery no garantiza reinstalar las aplicaciones eliminadas.' 'Recovery does not guarantee reinstalling removed applications.') -Color $script:ThemeWarning
    }
}

function Invoke-VSO7ConsoleAutomaticPlanVSO {
    param([Parameter(Mandatory=$true)]$Plan)
    # Called only after review; keep the exact selected IDs. Never recalculate a
    # broader automatic selection between confirmation and execution.
    $features=@($Plan.Rows|Where-Object{$_.IsSelected-and$_.Kind-eq'Feature'}|ForEach-Object{[string]$_.Id})
    $apps=@($Plan.Rows|Where-Object{$_.IsSelected-and$_.Kind-eq'App'}|ForEach-Object{$_.AppIds}|Sort-Object -Unique)
    if($features.Count-eq0-and$apps.Count-eq0){return 'Empty'}
    $word=if($apps.Count){'ELIMINAR APPS'}else{'APLICAR'}
    if(-not(Confirm-Word -Word $word -Message ((Get-VSO7ConsoleTextVSO 'Escribe exactamente ' 'Type exactly ')+$word))){return 'Cancelled'}
    if($features.Count){
        $canonical=Get-VSO7FeatureSelectionPlanR75VSO -Operation Recommended -FeatureIds $features -Objective $Plan.Objective
        $result=Invoke-VSO7FeaturePlanExecutionR75VSO -Plan $canonical -Mode Apply -ExecutionKind Recommended
        if([string]$result.Status-ceq'Cancelled'){return 'Cancelled'}
        if([string]$result.Status-cne'Succeeded'){
            Write-VSOHost ([string]$result.Error) -ForegroundColor Red
            # The native batch may already contain applied entries. Do not start
            # app removal after a failed or partial feature batch.
            return 'FailedOrPartial'
        }
    }
    if($apps.Count){
        try{
            if(-not(Require-RestorePoint)){return $(if($features.Count){'Partial'}else{'Cancelled'})}
            if(-not[bool](Invoke-VSO7NativeTweaksVSO -Apps $apps)){return 'FailedOrPartial'}
        }catch{
            Write-VSO7Log ('Fallo en la fase de aplicaciones: '+$_.Exception.Message) 'ERROR'
            Write-VSOHost $_.Exception.Message -ForegroundColor Red
            return 'FailedOrPartial'
        }
    }
    try{
        [void](Save-VSO7LastAppliedSelectionR76VSO -Features $features -Apps $apps)
    }catch{
        Write-VSO7Log ('La operacion termino, pero no se pudo guardar su seleccion: '+$_.Exception.Message) 'WARN'
        return 'AppliedNotSaved'
    }
    return 'Succeeded'
}

function Show-VSO7ConsoleAutomaticVSO {
    param([ValidateSet('Tweaks','Apps','Both')][string]$Scope='Tweaks')
    $objective='Balanced'
    while($true){
        try{
            Write-VSOHost (Get-VSO7ConsoleTextVSO 'Calculando la seleccion para este PC...' 'Preparing the selection for this PC...')
            $plan=Get-VSO7ConsoleAutomaticPlanVSO -Scope $Scope -Objective $objective
            while($true){
                Show-VSO7ConsoleAutomaticPlanVSO -Plan $plan
                Write-CenteredMenuVSO -Items @(
                    [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[A] Aplicar exactamente esta seleccion' '[A] Apply exactly this selection');Color=$script:ThemeSuccess;Description=(Get-VSO7ConsoleTextVSO 'Muestra la confirmacion final y conserva los IDs revisados.' 'Shows the final confirmation and preserves the reviewed IDs.')}
                    [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[E] Marcar o desmarcar por numero' '[E] Toggle items by number');Color='Cyan';Description=(Get-VSO7ConsoleTextVSO 'Acepta varios numeros separados por espacios o comas.' 'Accepts several numbers separated by spaces or commas.')}
                    [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[R] Recalcular el plan' '[R] Recalculate plan');Color='Cyan';Description=(Get-VSO7ConsoleTextVSO 'Vuelve a detectar el equipo y restablece la seleccion recomendada.' 'Detects the PC again and restores the recommended selection.')}
                    $(if($Scope-ne'Apps'){[pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[O] Cambiar objetivo' '[O] Change objective');Color=$script:ThemeCopper;Description=(Get-VSO7ConsoleTextVSO 'Equilibrado, rendimiento, gaming, respuesta o eficiencia.' 'Balanced, performance, gaming, responsiveness or efficiency.')}})
                    [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[0] Volver sin aplicar' '[0] Back without applying');Color='Gray';Description=(Get-VSO7ConsoleTextVSO 'Descarta esta previsualizacion.' 'Discards this preview.');SeparatorBefore=$true}
                )
                $choice=(Read-CenteredPromptVSO -Text (Get-VSO7ConsoleTextVSO 'Opcion' 'Option')).Trim()
                if($choice-eq'0'){return}
                if($choice-ieq'R'){break}
                if($choice-ieq'O'){
                    if($Scope-eq'Apps'){continue}
                    $selectedObjective=Select-VSO7RecommendedObjectiveVSO -Current $objective
                    if($selectedObjective-eq'Privacy'){
                        Write-VSOHost (Get-VSO7ConsoleTextVSO 'Privacidad se configura desde los ajustes manuales de Windows.' 'Privacy is configured in manual Windows settings.') -ForegroundColor Yellow
                        Pause-Vico
                        continue
                    }
                    $objective=$selectedObjective
                    break
                }
                if($choice-ieq'E'){
                    $inputText=Read-CenteredPromptVSO -AnimatedMenu -Text (Get-VSO7ConsoleTextVSO 'Numeros separados por espacios o comas (vacio: cancelar)' 'Numbers separated by spaces or commas (empty: cancel)')
                    if([string]::IsNullOrWhiteSpace($inputText)){continue}
                    $numbers=New-Object 'Collections.Generic.List[int]'
                    $valid=$true
                    foreach($part in @($inputText.Trim()-split'[\s,;]+')){
                        $number=0
                        if(-not[int]::TryParse($part,[ref]$number)-or$number-lt1-or$number-gt@($plan.Rows).Count){$valid=$false;break}
                        if(-not$numbers.Contains($number)){[void]$numbers.Add($number)}
                    }
                    if(-not$valid){
                        Write-VSOHost (Get-VSO7ConsoleTextVSO 'Seleccion invalida; no se ha cambiado ninguna marca.' 'Invalid selection; no checkmarks changed.') -ForegroundColor Yellow
                        Pause-Vico
                        continue
                    }
                    foreach($number in $numbers){$plan.Rows[$number-1].IsSelected=-not$plan.Rows[$number-1].IsSelected}
                    continue
                }
                if($choice-ieq'A'){
                    $status=Invoke-VSO7ConsoleAutomaticPlanVSO -Plan $plan
                    $message=switch($status){
                        'Succeeded'{Get-VSO7ConsoleTextVSO 'Operacion completada. Revisa los reinicios indicados en la lista.' 'Operation completed. Review restart requirements shown in the list.'}
                        'Empty'{Get-VSO7ConsoleTextVSO 'No hay cambios seleccionados.' 'No changes selected.'}
                        'Cancelled'{Get-VSO7ConsoleTextVSO 'Operacion cancelada.' 'Operation cancelled.'}
                        'AppliedNotSaved'{Get-VSO7ConsoleTextVSO 'Cambios aplicados; no se guardo la seleccion para exportar. Revisa el log.' 'Changes applied; export selection could not be saved. Check the log.'}
                        default{Get-VSO7ConsoleTextVSO 'Operacion fallida o parcial. Puede haber cambios aplicados: revisa Recovery y el log antes de repetir.' 'Operation failed or partially completed. Changes may have been applied: check Recovery and the log before retrying.'}
                    }
                    Write-VSOHost $message -ForegroundColor $(if($status-eq'Succeeded'){'Green'}else{'Yellow'})
                    Pause-Vico
                    return
                }
            }
        }catch{
            Write-VSO7Log ('Consola automatica: '+$_.Exception.Message) 'ERROR'
            Write-VSOHost $_.Exception.Message -ForegroundColor Red
            Pause-Vico
            return
        }
    }
}

function Show-VSO7AppSelectorVSO {
    while($true){
        Write-Title
        Write-CenteredLineVSO -Text (Get-VSO7ConsoleTextVSO 'APLICACIONES' 'APPLICATIONS') -Color $script:ThemeCopper
        Write-VSOHost ''
        Write-CenteredMenuVSO -Items @(
            [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[1] Seleccion automatica recomendada' '[1] Automatic recommended selection');Color=$script:ThemeSuccess;Description=(Get-VSO7ConsoleTextVSO 'Detecta solo apps clasificadas como safe y permite revisar cada marca.' 'Detects only apps classified as safe and lets you review every checkmark.')}
            [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[2] Busqueda y seleccion manual' '[2] Search and manual selection');Color='Cyan';Description=(Get-VSO7ConsoleTextVSO 'Abre el catalogo completo con paginas, busqueda y opciones avanzadas.' 'Opens the full catalog with pages, search and advanced choices.')}
            [pscustomobject]@{Text=(Get-VSO7ConsoleTextVSO '[0] Volver' '[0] Back');Color='Gray';Description=(Get-VSO7ConsoleTextVSO 'No elimina ninguna aplicacion.' 'Does not remove any application.');SeparatorBefore=$true}
        )
        switch((Read-CenteredPromptVSO -Text (Get-VSO7ConsoleTextVSO 'Opcion' 'Option'))){
            '1'{Show-VSO7ConsoleAutomaticVSO -Scope Apps}
            '2'{Show-VSO7ManualAppSelectorVSO}
            '0'{return}
        }
    }
}

# Entrada principal
if (-not (Test-IsWindows)) {

    Write-VSOHost 'VSO7 solo funciona en Windows.' -ForegroundColor Red
    exit 1

}

try {
    Initialize-VSOTrustedSystemPaths
} catch {
    Wait-VSO7FatalError -ErrorRecord $_ -Context 'no se pudieron inicializar las rutas de sistema confiables'
    exit 1
}
try {
    Ensure-CompatibleShellAndAdministrator
} catch {
    Wait-VSO7FatalError -ErrorRecord $_ -Context 'el host de PowerShell no cumple los requisitos'
    exit 1
}
try{
    Initialize-VSO7LifecycleDiagnosticsVSO
if($script:GuiRequested-or[string]$StartupProbe-like'GUI*'){try{Write-VSO7GuiPerformanceEventVSO -Name 'PROCESS_ENTRY'}catch{}}
}catch{
    Wait-VSO7FatalError -ErrorRecord $_ -Context 'no se pudo inicializar el diagnostico de lifecycle GUI'
    exit 1
}
if(-not(Enter-VSO7SingleInstance)){
    Write-VSO7LifecycleCheckpointVSO -Name 'SINGLE_INSTANCE_REJECTED'
    exit 2
}
Write-VSO7LifecycleCheckpointVSO -Name 'MUTEX_ACQUIRED'
Write-VSO7EarlyStartupTimelineVSO -Name 'MUTEX_ACQUIRED'
Write-VSO7LifecycleCheckpointVSO -Name 'AFTER_MUTEX' -Detail 'single-instance ownership established'
if($script:GuiRequested-or[string]$StartupProbe-like'GUI*'){try{Write-VSO7GuiPerformanceEventVSO -Name 'MUTEX'}catch{}}

# Desde el instante en que VSO7 posee el mutex, TODO el lifecycle queda bajo este finally.
# Ningun fallo de idioma/organizacion/preflight/GUI puede dejar transcript, mutex o tema
# retenidos por un host oculto. Los exit definitivos se realizan solo despues del cleanup.
$script:ProcessExitCode=0
    $script:LifecycleErrorContext='unhandled error during initialization'
try {

    $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_CONSOLE_THEME'
    Initialize-VSOConsoleTheme
    $script:ConsoleThemeInitialized=$true
    Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_CONSOLE_THEME' -StartedMs $startupStage

    if([string]$StartupProbe-ine'None' -and -not[bool]$script:FullGuiStartupProbe){

        try{
            [void](Initialize-VSO7StartupProbeArtifactsVSO)
            switch([string]$StartupProbe){
                'GUI' {
                    [void](Show-VSO7Gui -SmokeOnly -SmokeAction CloseWindow)
                }
                'GUIButton' {
                    [void](Show-VSO7Gui -SmokeOnly -SmokeAction CloseButton)
                }
                'GUILanguage' {
                    [void](Test-VSO7GuiPromptDialogVSO)
                    [void](Show-VSO7Gui -SmokeOnly -SmokeAction CloseWindow)
                }
                'GUILayout' {
                    $layoutResults=@()
                    foreach($lang in @('en','es')){
                        $layoutResults+=Test-VSO7FirstRunDialogLayoutVSO -Language $lang
                        $layoutResults+=Test-VSO7FirstRunDialogLayoutVSO -Language $lang -LongTextStress
                    }
                    $layoutResults|ForEach-Object{Write-Host ('[LAYOUT] '+($_|ConvertTo-Json -Compress -Depth 4)) -ForegroundColor Cyan}
                    if(-not[string]::IsNullOrWhiteSpace([string]$VSOProbeArtifactRoot)-and$VSOProbeOwnerToken-match'^[A-Fa-f0-9]{32}$'){
                        $layoutReport=Join-Path ([IO.Path]::GetFullPath([string]$VSOProbeArtifactRoot)) ('VSO7_R80_LAYOUT_{0}.json'-f[string]$VSOProbeOwnerToken)
                        $layoutJson=@($layoutResults)|ConvertTo-Json -Depth 6
                        [IO.File]::WriteAllText($layoutReport,$layoutJson,(New-Object Text.UTF8Encoding($false)))
                    }
                    $failed=@($layoutResults|Where-Object{-not[bool]$_.Pass})
                    if($failed.Count-gt0){throw ('R80 first-run layout probe failed: '+($failed|ConvertTo-Json -Compress -Depth 4))}
                    $layoutResults|ForEach-Object{Write-Output $_}
                }
                'GUIPipelineStop' {
                    [void](Show-VSO7Gui -SmokeOnly -SmokeAction CloseWindow)
                    throw (New-Object System.Management.Automation.PipelineStoppedException 'R44 synthetic pipeline-stop/CTRL+C lifecycle probe.')
                }
                'GUILoggingFailure' {
                    [void](Show-VSO7Gui -SmokeOnly -SmokeAction CloseWindow)
                }
                'GUIStopTranscriptFailure' {
                    [void](Show-VSO7Gui -SmokeOnly -SmokeAction CloseWindow)
                }
                default {
                    # Core probe intentionally performs no WPF lifecycle.
                }
            }
            Write-VSOHost ('[OK] STARTUP PROBE {0}: inicializacion del core completada sin mutaciones funcionales.'-f([string]$StartupProbe).ToUpperInvariant()) -ForegroundColor Green
            $script:ProcessExitCode=0
        }catch{
            $script:ProcessExitCode=9
            Wait-VSO7FatalError -ErrorRecord $_ -Context ('startup probe '+[string]$StartupProbe)
        }

    }else{

        # En una ubicacion que aun no es VSO7 se muestra SIEMPRE el selector de idioma antes
        # de preguntar por la organizacion. El relanzamiento organizado recibe -Language y no repite la pantalla.
        $script:LifecycleErrorContext='error while initializing language and first-run settings'
        $forceLanguagePrompt=$false
        if(-not$SkipOrganize-and-not[string]::IsNullOrWhiteSpace([string]$script:Root)-and(Split-Path -Leaf $script:Root)-ine'VSO7'){

            $decisionMatches=$false
            try{

                $orgDecision=Join-Path (Join-Path $script:Root 'Config') 'organization.json'
                if(Test-Path -LiteralPath $orgDecision -PathType Leaf){

                    $savedDecision=Get-Content -LiteralPath $orgDecision -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop
                    if(-not[string]::IsNullOrWhiteSpace([string]$savedDecision.SkippedPath)){

                        $decisionMatches=([IO.Path]::GetFullPath([string]$savedDecision.SkippedPath).TrimEnd('\') -ieq [IO.Path]::GetFullPath([string]$script:Root).TrimEnd('\'))

                    }

                }

            }catch{
                $decisionMatches=$false
            }
            $forceLanguagePrompt=$false # R44: fresh state defaults to English; never force a first-run language prompt

        }
        $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LANGUAGE_INIT' -Detail ('ForcePrompt='+[string][bool]$forceLanguagePrompt)
        Initialize-VSOLanguage -ForcePrompt:$forceLanguagePrompt
        Initialize-VSO7ConsoleBackgroundPreferenceVSO
        Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LANGUAGE_INIT' -StartedMs $startupStage -Detail ('Language='+[string]$script:Language)
        Write-VSO7EarlyStartupTimelineVSO -Name 'LANGUAGE_READY' -Detail ('Language='+[string]$script:Language)

        $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_FIRST_RUN_ORGANIZATION'
        $organizationHandoff=[bool](Invoke-FirstRunOrganization)
        Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_FIRST_RUN_ORGANIZATION' -StartedMs $startupStage -Detail ('Handoff='+[string]$organizationHandoff)

        if(-not$organizationHandoff){

            # A partir de aqui la ubicacion definitiva ya esta decidida. Solo ahora nacen las carpetas base locales.
            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LOCAL_FOLDER_INIT'
            Initialize-VSO7LocalFolders
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LOCAL_FOLDER_INIT' -StartedMs $startupStage

            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LANGUAGE_SAVE_PRE_ENV'
            Save-VSOLanguagePreference
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LANGUAGE_SAVE_PRE_ENV' -StartedMs $startupStage

            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ORGANIZATION_SOURCE_CLEANUP'
            Remove-OrganizationSourceIfSafe
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ORGANIZATION_SOURCE_CLEANUP' -StartedMs $startupStage

            $script:LifecycleErrorContext='protected storage could not be initialized'
            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SECURE_STORAGE_INIT'
            Initialize-VSO7SecureStateStorage
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SECURE_STORAGE_INIT' -StartedMs $startupStage
            Write-VSO7EarlyStartupTimelineVSO -Name 'STORAGE_READY'
            if([bool]$script:FullGuiStartupProbe){ [void](Initialize-VSO7FullStartupProbeArtifactsVSO) }

            # El estado elevado sensible sigue protegido en ProgramData; las carpetas locales existen como
            # estructura estable y destino de recursos/exportaciones visibles de VSO7.
            $script:LifecycleErrorContext='unhandled error in the main workflow'
            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_ENVIRONMENT_INIT'
            Initialize-Environment
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_ENVIRONMENT_INIT' -StartedMs $startupStage
            Write-VSO7EarlyStartupTimelineVSO -Name 'ENV_READY'

            $script:LanguageFile = Join-Path $script:ConfigRoot 'language.json'
            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LANGUAGE_SAVE_POST_ENV'
            Save-VSOLanguagePreference
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LANGUAGE_SAVE_POST_ENV' -StartedMs $startupStage

            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LOAD_STATE'
            Load-State
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LOAD_STATE' -StartedMs $startupStage

            if([bool]$script:FullGuiStartupProbe){
                $probeRpEntries=@($script:State.Registry|Where-Object{ $_.Path-ieq'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'-and$_.Name-ieq'SystemRestorePointCreationFrequency' })
                if($probeRpEntries.Count-gt0){ throw 'FULL STARTUP PROBE se niega a ejecutar una reconciliacion Restore Point potencialmente mutable; limpia/revisa el estado pendiente antes del stress.' }
            }
            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_RESTOREPOINT_REPAIR'
            $script:RestorePointFrequencyRecoveryReady=[bool](Repair-VSO7RestorePointFrequencyTransactionVSO)
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_RESTOREPOINT_REPAIR' -StartedMs $startupStage -Detail ('Ready='+[string][bool]$script:RestorePointFrequencyRecoveryReady)

            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LOAD_EXTREME_STATE'
            Load-ExtremeState
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LOAD_EXTREME_STATE' -StartedMs $startupStage

            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_LOAD_STARTUP_STATE'
            Load-StartupState
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_LOAD_STARTUP_STATE' -StartedMs $startupStage

            if([bool]$script:FullGuiStartupProbe-and(Test-Path -LiteralPath $script:GamingSessionStateFile -PathType Leaf)){
                throw 'FULL STARTUP PROBE se niega a ejecutar una restauracion Gaming potencialmente mutable; existe gaming-session-active.json.'
            }
            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_GAMING_SESSION_REPAIR'
            $script:GamingRecoveryReady=Repair-StaleVSO7GamingSessionIfNeeded
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_GAMING_SESSION_REPAIR' -StartedMs $startupStage -Detail ('Ready='+[string][bool]$script:GamingRecoveryReady)

            $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_PREFLIGHT'
            $preflightReady=[bool](Invoke-VSO7Preflight)
            Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_PREFLIGHT' -StartedMs $startupStage -Detail ('Ready='+[string]$preflightReady)
            Write-VSO7EarlyStartupTimelineVSO -Name 'PREFLIGHT_READY' -Detail ('Ready='+[string]$preflightReady)

            if(-not[bool]$script:RestorePointFrequencyRecoveryReady){

                Write-VSOHost ''
                Write-VSOHost 'VSO7 se detiene porque no pudo reconciliar una transaccion temporal de Restauracion del sistema.' -ForegroundColor Red
                Write-VSOHost 'El estado protegido se conserva para volver a intentarlo; no se ejecutaran nuevas operaciones mutables.' -ForegroundColor Yellow
                if([bool]$script:FullGuiStartupProbe){ throw 'FULL STARTUP PROBE: Restore Point recovery no esta lista.' }
                Pause-Vico
                $script:ProcessExitCode=5

            } elseif(-not[bool]$script:GamingRecoveryReady){

                Write-VSOHost ''
                Write-VSOHost 'VSO7 se detiene para conservar intacto el estado Gaming pendiente.' -ForegroundColor Red
                Write-VSOHost 'No se ejecutaran preflight mutable, menus ni nuevas optimizaciones hasta recuperar o revisar ese estado.' -ForegroundColor Yellow
                if([bool]$script:FullGuiStartupProbe){ throw 'FULL STARTUP PROBE: Gaming recovery no esta lista.' }
                Pause-Vico
                $script:ProcessExitCode=4

            } elseif(-not$preflightReady){

                Write-VSOHost ''
                Write-VSOHost 'VSO7 se detiene antes de modificar nada.' -ForegroundColor Red
                if([bool]$script:FullGuiStartupProbe){ throw 'FULL STARTUP PROBE: preflight no paso; no se abre GUI ni se ejecuta ninguna mutacion.' }
                Pause-Vico
                $script:ProcessExitCode=1

            } elseif (-not [string]::IsNullOrWhiteSpace($RestoreFromBundle)) {

                if(-not [bool](Invoke-RestoreFromBundleVSO -Bundle $RestoreFromBundle)){
                    $script:ProcessExitCode=3
                }

            } else {

                switch([string]$DirectAction){

                    'GUI'{
                        Write-VSO7EarlyStartupTimelineVSO -Name 'GUI_CONSTRUCTION_BEGIN'
                        $startupStage=Start-VSO7LifecycleStageVSO -BeforeName 'BEFORE_SHOW_GUI_CALL' -Detail ('FullProbe='+[string][bool]$script:FullGuiStartupProbe+';NoTranscript='+[string][bool]$script:ProbeSuppressTranscript)
                        if([bool]$script:FullGuiStartupProbe){
                            $fullSmokeAction=if([string]$StartupProbe-ieq'GUI_WELCOME_FULL_STARTUP'){'StartHome'}elseif([string]$StartupProbe-ieq'GUI_NAVIGATION_MATRIX'){'NavigationMatrix'}elseif([string]$StartupProbe-ieq'GUI_TASKBAR'){'Taskbar'}elseif([string]$StartupProbe-ieq'GUI_PERFORMANCE'){'PerformanceMatrix'}elseif([string]$StartupProbe-ieq'GUI_CALLBACKS'){'CallbackMatrix'}else{'CloseWindow'}
                            [void](Show-VSO7Gui -SmokeOnly -SmokeAction $fullSmokeAction)
                            Write-VSOHost ('[OK] FULL STARTUP PROBE {0}: pre-GUI completo, ContentRendered y cierre limpio solicitados.'-f[string]$StartupProbe) -ForegroundColor Green
                        }else{
                            Show-VSO7Gui
                        }
                        Complete-VSO7LifecycleStageVSO -AfterName 'AFTER_SHOW_GUI_CALL' -StartedMs $startupStage
                    }
                    'Recommended'{
                        Show-VSO7RecommendedOptimizationVSO
                    }
                    'Safe'{
                        Show-VSO7SafeSelector
                    }
                    'Gaming'{
                        Show-VSO7GamingSelector
                    }
                    'Balanced'{
                        Invoke-VSO7BalancedOptimization
                    }
                    'Aggressive'{
                        Invoke-AggressiveOptimization
                    }
                    'Extreme'{
                        Show-ExtremeOptimizer
                    }
                    'Windows'{
                        Show-VSO7WindowsFeatures
                    }
                    'V7SP002'{
                        Show-VSO7AppSelectorVSO
                    }
                    'Tools'{
                        Show-VSO7SystemTools
                    }
                    'TuningAudit'{
                        Show-VSO7AdvancedTuningDiagnostics
                    }
                    'RestorePoint'{
                        Show-VSO7RestorePointPrompt
                    }
                    'Recovery'{
                        Invoke-Revert
                    }
                    default{
                        Show-Menu
                    }

                }

            }

        }

    }

} catch {

    $script:ProcessExitCode=1
    try{
        Write-VSO7Log ("Unhandled lifecycle error: {0}"-f$_.Exception.Message) 'ERROR'
    }catch{
        # El logger puede no estar inicializado todavia; Wait-VSO7FatalError conserva el diagnostico visible.
    }
    Wait-VSO7FatalError -ErrorRecord $_ -Context ([string]$script:LifecycleErrorContext)

} finally {

    Invoke-VSO7OwnedLifecycleCleanupVSO

}
try{Export-VSO7GuiPerformanceTraceVSO}catch{}
if([string]$StartupProbe-like'GUI*'-and-not[string]::IsNullOrWhiteSpace([string]$VSOProbeArtifactRoot)-and[string]$VSOProbeOwnerToken-match'^[A-Fa-f0-9]{32}$'){
    try{
        $processResultPath=Join-Path ([IO.Path]::GetFullPath([string]$VSOProbeArtifactRoot)) ('VSO7_R80_PROCESS_RESULT_'+[string]$VSOProbeOwnerToken+'.json')
        $processResultTmp=$processResultPath+'.tmp.'+[guid]::NewGuid().ToString('N')
        try{[IO.File]::WriteAllText($processResultTmp,([pscustomobject]@{Schema='VSO7.ProbeProcessResult.v1';Release='RC R80';Token=[string]$VSOProbeOwnerToken;Pid=[int]$PID;ExitCode=[int]$script:ProcessExitCode;CompletedUtc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Depth 4 -Compress),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $processResultTmp -Destination $processResultPath -Force -ErrorAction Stop}finally{Remove-Item -LiteralPath $processResultTmp -Force -ErrorAction SilentlyContinue}
    }catch{try{Write-VSO7Log ('Probe process result publication failed: '+$_.Exception.Message) 'ERROR'}catch{};if([int]$script:ProcessExitCode-eq0){$script:ProcessExitCode=92}}
}
Write-VSO7LifecycleCheckpointVSO -Name 'BEFORE_PROCESS_EXIT' -Detail ('exitCode='+[string]$script:ProcessExitCode)
exit ([int]$script:ProcessExitCode)
